# ==================== DROPBOX URL CACHE ====================
_dropbox_url_cache: dict = {}

def _cache_key(file_path: str) -> str:
    return hashlib.md5(file_path.encode()).hexdigest()

def _get_cached_url(company_id: str, file_path: str):
    now = datetime.now(timezone.utc)
    entry = _dropbox_url_cache.get(company_id, {}).get(_cache_key(file_path))
    if entry and entry["expires_at"] > now:
        return entry["url"]
    return None

def _set_cached_url(company_id: str, file_path: str, url: str):
    if company_id not in _dropbox_url_cache:
        _dropbox_url_cache[company_id] = {}
    _dropbox_url_cache[company_id][_cache_key(file_path)] = {
        "url": url,
        "expires_at": datetime.now(timezone.utc) + timedelta(hours=3),
    }

# ==================== CLOUDFLARE R2 STORAGE ====================

def _get_r2_client():
    """Get boto3 S3 client configured for Cloudflare R2. Returns None if not configured."""
    if not _BOTO3_AVAILABLE:
        return None
    if not R2_ACCESS_KEY_ID or not R2_SECRET_ACCESS_KEY or not R2_ENDPOINT_URL:
        return None
    return boto3.client(
        "s3",
        endpoint_url=R2_ENDPOINT_URL,
        aws_access_key_id=R2_ACCESS_KEY_ID,
        aws_secret_access_key=R2_SECRET_ACCESS_KEY,
        config=BotoConfig(signature_version="s3v4"),
        region_name="auto",
    )

_r2_client = None  # initialized in startup_event


def _upload_to_r2(file_bytes: bytes, r2_key: str, content_type: str = "application/octet-stream") -> str:
    """Upload bytes to R2, returns the public URL. Returns empty string if R2 not configured."""
    if not _r2_client or not R2_BUCKET_NAME:
        return ""
    _r2_client.put_object(
        Bucket=R2_BUCKET_NAME,
        Key=r2_key,
        Body=file_bytes,
        ContentType=content_type,
    )
    if R2_PUBLIC_URL:
        return f"{R2_PUBLIC_URL.rstrip('/')}/{r2_key}"
    return f"{R2_ENDPOINT_URL}/{R2_BUCKET_NAME}/{r2_key}"


# Daily-log photo enhancement runs on a SMALL dedicated threadpool, never on
# the event loop. OpenCV/Pillow work is CPU-bound: a bare asyncio.create_task
# would stall every concurrent request for the duration of the encode. Two
# workers is deliberate — enough to keep up with a CP saving a log of 5 photos,
# small enough that it cannot monopolise a 1-2 vCPU Railway instance.
_PHOTO_ENHANCE_POOL = ThreadPoolExecutor(max_workers=2, thread_name_prefix="photo-enh")

# Key shape, mirroring the existing plans/{project_id}/ convention so the
# project delete cascade can sweep it with one unconditional prefix (see
# hard_delete_project). Project-scoped rather than company-scoped on purpose:
# the {company_id}/{project_id}/ sweep is conditional on company_id being
# truthy, and an orphaned photo must still be reachable by the cascade.
def _logbook_photo_r2_key(project_id: str, logbook_id: str, ai: int, pi: int, kind: str) -> str:
    return f"logbook-photos/{project_id}/{logbook_id}/{ai}-{pi}-{kind}.jpg"


# ── THE CAPTURE-TIME KEY ─────────────────────────────────────────────────────
# A photo is uploaded when it is TAKEN, not when the log is saved, so its key
# cannot be built out of anything that only exists after a save:
#
#   logbook_id  DOES NOT EXIST YET. The editor's `existingLogId` is null until
#               the first successful push, and a photo taken offline may have no
#               server document for hours.
#   (ai, pi)    are POSITIONS. Rows are added, removed and reordered all day; a
#               positional key stops naming the same photo the moment they are.
#
# So the key is (project_id, activity_id, photo_id): all three client-minted,
# all three stable for the life of the row. `activity_id` is the per-row id
# minted on the device when the row is created; `photo_id` is the capture id
# that already existed so a background compress could find its own photo again.
#
# BOTH SCHEMES COEXIST, AND NOTHING IS MIGRATED. _logbook_photo_r2_key above
# still names every object the enhance pass wrote for a photo taken before this
# change. Those keys are READ OFF THE PHOTO DOCUMENT and never recomputed (see
# _logbook_photo_sources and _purge_finalized_photo_base64), so an old photo
# keeps resolving forever without either scheme knowing about the other.
def _logbook_photo_key_segment(value: str) -> str:
    """One path segment of an R2 key, built from a client-supplied id.

    The ids are minted on the device, so they are untrusted input on their way
    into an object key. Everything outside [A-Za-z0-9._-] is replaced, which
    makes a traversal ('../') or an injected key prefix impossible to express.
    """
    cleaned = re.sub(r"[^A-Za-z0-9._-]", "_", str(value or "").strip())
    return cleaned[:80] or "unknown"


# ────────────────────────────────────────────────────────────────────────────
# THE CHECK-IN SELFIE
#
# It used to be written INLINE, as a base64 data URL, straight onto the workers
# document. A ~1200px JPEG at q0.7 is on the order of 100-200KB of base64 per
# worker, sitting in a document that is read on every roster render, every
# staffing screen and every check-in lookup — none of which want it. This moves
# the bytes to object storage and leaves a key behind.
#
# SAME BUCKET, DISTINCT PREFIX. Deliberately NOT the card-audit bucket: that one
# is object-locked with 7-year retention because a credential photo is evidence
# of what was presented at the gate. A selfie is not that. It exists for a later
# human spot-check — no face match, no liveness, no gate — and putting it under a
# retention lock would assert a purpose it does not have and cannot be undone.
def _worker_selfie_r2_key(worker_id: str) -> str:
    return f"worker-selfies/{_logbook_photo_key_segment(worker_id)}/selfie.jpg"


def _decode_image_data_url(value: str) -> bytes:
    """Bytes out of a `data:image/...;base64,...` URL, or b"" if it is not one."""
    if not isinstance(value, str) or not value:
        return b""
    payload = value.split(",", 1)[1] if value.startswith("data:") and "," in value else value
    try:
        return base64.b64decode(payload, validate=False)
    except Exception:
        return b""


async def _store_worker_selfie(worker_id: str, selfie_image: str) -> dict:
    """Put a check-in selfie in R2 and return the fields to write on the worker.

    A FAILED UPLOAD MUST NOT FAIL THE CHECK-IN. The selfie is optional at the
    gate — checkin.html never blocks on it — so it cannot become the thing that
    turns a man away because object storage is down, misconfigured, or slow. Every
    failure path here returns instead of raising.

    NO POINTER IS EVER INVENTED. On failure there is no key, no URL, and no empty
    string. A URL that 404s is a claim this app cannot support, and `""` is a
    VALUE — it reads as a fact about the selfie rather than as the absence of one.

    WHAT IS RECORDED INSTEAD: `selfie_upload_failed: True`. This is not a
    sentinel standing in for a photo; it is a boolean recording what happened.
    The difference matters and is the reason it is here rather than not:

      * a POINTER to a missing object asserts the object exists — forbidden;
      * a BOOLEAN asserts only that an upload was attempted and did not land,
        which is true, checkable, and about the event rather than the image.

    WHY IT IS NEEDED EVEN THOUGH THE BASE64 IS STILL WRITTEN. Today the inline
    copy does carry the distinction: `selfie_image` present + no `selfie_r2_key`
    is "took one, upload failed", and neither is "declined". So while Q2 holds,
    this flag is redundant. It stops being redundant the moment the strip PR
    removes the inline copy — at which point those two rows become byte-identical
    and the distinction is gone. Recording it NOW means the strip PR does not
    have to reconstruct information it can no longer see. See
    docs/design/d3-phone-wins-and-the-server-copy.md.

    Returns {} when no selfie was offered. On any failure with a selfie offered,
    returns {"selfie_upload_failed": True} and nothing else.
    """
    if not selfie_image:
        return {}
    raw = _decode_image_data_url(selfie_image)
    if not raw:
        logger.warning(
            "[selfie] worker=%s: selfie payload was not decodable base64; not stored",
            worker_id,
        )
        return {"selfie_upload_failed": True}
    key = _worker_selfie_r2_key(worker_id)
    try:
        # to_thread: _upload_to_r2 is a blocking boto3 PUT, and this runs inside
        # the request that the worker is standing at the turnstile waiting on.
        url = await asyncio.to_thread(_upload_to_r2, raw, key, "image/jpeg")
    except Exception as e:
        logger.error("[selfie] worker=%s: R2 upload failed key=%s: %r", worker_id, key, e)
        return {"selfie_upload_failed": True}
    if not url:
        # _upload_to_r2 returns "" when R2 is not configured at all. Not an
        # error and not a crash — but nothing was stored, so the record says
        # nothing. NOT `selfie_r2_url: ""`: an empty string is a value.
        logger.warning("[selfie] worker=%s: R2 not configured; selfie not stored", worker_id)
        return {"selfie_upload_failed": True}
    # THE URL PROVES THE WRITE RETURNED, NOT THAT THE OBJECT IS READABLE. That is
    # why the caller still stores the inline copy; see the note there.
    return {"selfie_r2_key": key, "selfie_r2_url": url}


def _logbook_capture_photo_r2_key(project_id: str, activity_id: str, photo_id: str) -> str:
    """logbook-photos/{project_id}/{activity_id}/{photo_id}.jpg

    Same `logbook-photos/{project_id}/` prefix as the positional scheme, so the
    project delete cascade (hard_delete_project) still sweeps both with the one
    unconditional prefix it already uses.
    """
    return (
        f"logbook-photos/{_logbook_photo_key_segment(project_id)}/"
        f"{_logbook_photo_key_segment(activity_id)}/"
        f"{_logbook_photo_key_segment(photo_id)}.jpg"
    )


def _logbook_photo_derivative_key(original_key: str, kind: str) -> str:
    """The enhanced/thumb object belonging to a capture-scheme original.

    Derived from the ORIGINAL KEY, never from (ai, pi), so the derivatives
    inherit the original's position-independence instead of reintroducing the
    very problem the capture key exists to solve.
    """
    base = original_key[:-4] if original_key.endswith(".jpg") else original_key
    return f"{base}-{kind}.jpg"


# A stored photo can carry up to four copies of itself, and WHICH ones exist
# changes over the record's life:
#
#   base64          the full-size original, inlined in the logbook document.
#                   DROPPED at finalize by _purge_finalized_photo_base64, but
#                   only once R2 has been proven to hold both derivatives.
#   thumb_base64    the ~400px copy written in its place. NEVER removed. This
#                   is the last-resort copy: small beats absent on a signed
#                   legal record.
#   enhanced_r2_key / thumb_r2_key   the two objects the enhance pass uploads.
#
# Every reader must ask "which copies does this photo still have", never "does
# it have base64" — the latter was the same question only while base64 was the
# only copy, and it silently becomes "was this photo never taken" afterwards.
def _logbook_photo_sources(photo: dict, v: str = "") -> list:
    """Ordered (kind, value) copies to try for one serve request.

    kind is "r2" (an object key) or "b64" (inline data). The requested
    derivative leads and every other surviving copy follows, so no single
    missing copy can 404 a photo another copy could have served.

    With no variant asked for, ORIGINAL STILL MEANS ORIGINAL: the inline
    full-size copy leads while it exists, and the derivatives stand in only
    once the purge has taken it. That keeps the lightbox's "Original" label
    honest instead of quietly serving an enhanced render under it.

    `original_r2_key` is read because the ladder is specified in terms of an
    original object; nothing writes that field today (the enhance pass uploads
    enhanced + thumb and nothing else), so the rung is inert until something
    does. It is listed, not assumed.
    """
    if not isinstance(photo, dict):
        return []
    enhanced = photo.get("enhanced_r2_key")
    thumb = photo.get("thumb_r2_key")
    original = photo.get("original_r2_key")
    full_b64 = photo.get("base64")
    thumb_b64 = photo.get("thumb_base64")
    if v == "thumb":
        order = [("r2", thumb), ("r2", enhanced), ("r2", original),
                 ("b64", full_b64), ("b64", thumb_b64)]
    elif v == "enhanced":
        order = [("r2", enhanced), ("r2", thumb), ("r2", original),
                 ("b64", full_b64), ("b64", thumb_b64)]
    else:
        order = [("b64", full_b64), ("r2", original), ("r2", enhanced),
                 ("r2", thumb), ("b64", thumb_b64)]
    out = []
    for kind, val in order:
        if val and (kind, val) not in out:
            out.append((kind, val))
    return out


def _logbook_photo_is_renderable(photo: dict) -> bool:
    """Has this photo ANY copy left to serve? Emit it if so."""
    return bool(_logbook_photo_sources(photo))


# ── A PHOTOGRAPH THAT WAS NOT THERE WHEN HE SIGNED SAYS SO ───────────────────
#
# append_activity_photo lets a photograph be added to a log that is already
# filed, because a photograph is not DOB-required daily log content and
# treating one as an amendment to a compliance record is wrong on the merits.
# The corollary is this: a report that prints an appended photograph beside the
# ones the CP had in front of him, with nothing to tell them apart, makes the
# record assert that all of them were present at attestation. That assertion is
# the only thing this feature could manufacture, and this is what stops it.
#
# THE FLAG IS THE CLAIM; THE ATTRIBUTION IS A COURTESY. `added_after_filing`
# alone is enough to mark the photograph, so a row that somehow carries no
# stamp of who or when is still labelled rather than silently passed through.
#
# NEVER THE RAW `added_by`. That is a user id. Printing one on a report tells a
# reader nothing and looks like a redaction; the display name is printed when
# there is one, and nothing when there is not.
_PHOTO_ADDED_AFTER_FILING_LABEL = "Added after filing"


def _photo_added_after_filing_caption(photo: dict) -> str:
    """The caption HTML for an appended photograph, or '' for an original.

    Two lines: the label, then the attribution. Inline styles and no flex, like
    the rest of this report — the same string is emailed as HTML and rendered
    to PDF by WeasyPrint, so it has to survive both.
    """
    if not isinstance(photo, dict) or not photo.get("added_after_filing"):
        return ""
    import html as _h

    parts = []
    when = photo.get("added_at")
    if isinstance(when, str) and when:
        try:
            when = datetime.fromisoformat(when.replace("Z", "+00:00"))
        except Exception:
            when = None
    if isinstance(when, datetime):
        # THE NEW YORK DAY. `added_at` is a UTC instant, and 21:00 EDT is
        # already tomorrow in UTC -- so a photograph appended on Tuesday
        # evening was captioned Wednesday on the record. Same class of error
        # `eastern_date` was written to stop, on the same kind of document.
        # An unanchored legacy value keeps its own digits rather than vanishing.
        try:
            when = _as_eastern_instant(when)
        except ValueError:
            pass
        # NOT strftime('%b %-d'): '%-d' is a glibc extension and this module is
        # imported on developer machines that do not have it.
        parts.append(f"{when.strftime('%b')} {when.day}, {when.year}")
    who = str(photo.get("added_by_name") or "").strip()
    if who:
        parts.append(who)
    # 9px IS ILLEGIBLE IN PRINT WHATEVER THE CONTRAST. Both sub-captions go to
    # 11px, which still fits the 160px of text width inside the 166px tile.
    # #92400e keeps the amber warning semantics (the same family as the AMENDED
    # RECORD band) and takes this from 5.02:1 to 7.09:1.
    out = (
        '<span style="display:block;font-size:11px;line-height:1.35;'
        'overflow-wrap:anywhere;font-weight:700;color:#92400e;">&#9888; '
        f'{_h.escape(_PHOTO_ADDED_AFTER_FILING_LABEL)}</span>'
    )
    if parts:
        # Each part escaped on its own, THEN joined with the raw entity —
        # escaping the joined string would emit a literal "&middot;".
        _joined = " &middot; ".join(_h.escape(p) for p in parts)
        # THE ONE OUTRIGHT FAILURE. #94a3b8 on white is 2.56:1 -- it fails AA
        # (4.5:1) AND AA-large (3:1), and at 9px nothing qualifies as large
        # text, so the 3:1 threshold never applied. #475569 is 7.58:1.
        # `overflow-wrap` closes the one real wrap risk: an unbreakable
        # attribution token longer than 160px would otherwise run into the
        # neighbouring tile.
        out += (
            '<span style="display:block;font-size:11px;line-height:1.35;'
            f'overflow-wrap:anywhere;color:#475569;">{_joined}</span>'
        )
    return out


def _enhance_bytes_to_r2_sync(raw_bytes: bytes, enh_key: str, thumb_key: str,
                              retain_thumb_b64: bool) -> dict:
    """Blocking: enhance -> upload both derivatives -> return the photo patch.

    `retain_thumb_b64` decides whether the ~400px copy is ALSO inlined back into
    the document, and the two answers are not a preference:

      False, for a photo that arrived as inline base64. The finalize purge
      materialises that copy itself, from the bytes R2 really returns, in the
      same update that removes the full-size original — because the writer must
      not be the thing that verifies the writer (_purge_finalized_photo_base64).

      True, for a photo UPLOADED AT CAPTURE. Such a photo never had an inline
      copy for the purge to trade, so the purge skips it and thumb_base64 would
      stay permanently absent. That copy is not an optimisation: it is what the
      KIOSK draws for an inspector standing on site with no signal, whose
      reader is inline-first on purpose (app/site/logbooks.jsx logbookPhotoUri).
      At ~25-40KB it is ~4MB for a hundred photos — comfortably inside the 16MB
      document ceiling this whole track exists to stay under, and nothing like
      the ~20.5MB the full-size inline copies came to.
    """
    from lib.photo_enhance import enhance_photo
    result = enhance_photo(raw_bytes)
    _upload_to_r2(result.enhanced_jpeg, enh_key, "image/jpeg")
    _upload_to_r2(result.thumbnail_jpeg, thumb_key, "image/jpeg")
    patch = {
        "enhanced_r2_key": enh_key,
        "thumb_r2_key": thumb_key,
        "enhance_status": "done",
        "enhance_ms": result.elapsed_ms,
        "enhanced_w": result.enhanced_size[0],
        "enhanced_h": result.enhanced_size[1],
    }
    if retain_thumb_b64:
        patch["thumb_base64"] = base64.b64encode(result.thumbnail_jpeg).decode("ascii")
    return patch


def _enhance_one_photo_sync(b64_data: str, project_id: str, logbook_id: str, ai: int, pi: int) -> dict:
    """Blocking: decode -> enhance -> upload both derivatives to R2.

    Runs in _PHOTO_ENHANCE_POOL. Returns the fields to merge into the photo
    entry. Raises on failure; the caller records the failure and MOVES ON —
    the original base64 in Mongo is untouched either way, so a failed
    enhancement can never lose a photo.

    This is the INLINE path and its behaviour is unchanged: positional keys,
    and no retained thumbnail (the finalize purge writes that one).
    """
    return _enhance_bytes_to_r2_sync(
        base64.b64decode(b64_data),
        _logbook_photo_r2_key(project_id, logbook_id, ai, pi, "enhanced"),
        _logbook_photo_r2_key(project_id, logbook_id, ai, pi, "thumb"),
        retain_thumb_b64=False,
    )


def _enhance_r2_original_sync(original_key: str) -> dict:
    """Blocking: pull a CAPTURE-UPLOADED original back out of R2 and enhance it.

    The photo never passed through Mongo, so there is no inline copy to read —
    the bytes come from the object the device wrote at capture time. Raises on
    any failure (missing object, R2 unreachable, undecodable image); the caller
    records enhance_status="failed" and moves on, and the ORIGINAL OBJECT IS
    NEVER TOUCHED, so a failed enhancement still cannot lose a photo — exactly
    the invariant the inline path has always held.
    """
    if not (_r2_client and R2_BUCKET_NAME):
        raise RuntimeError("R2 is not configured")
    obj = _r2_client.get_object(Bucket=R2_BUCKET_NAME, Key=original_key)
    return _enhance_bytes_to_r2_sync(
        obj["Body"].read(),
        _logbook_photo_derivative_key(original_key, "enhanced"),
        _logbook_photo_derivative_key(original_key, "thumb"),
        retain_thumb_b64=True,
    )


async def _enhance_logbook_photos(logbook_id: str, project_id: str) -> None:
    """Walk data.activities[].photos[] and enhance each one off the hot path.

    Fire-and-forget: the CP's save has already returned by the time this runs.
    Every photo is independent — one failure never blocks the others, and the
    photo keeps rendering from its original base64 regardless.
    """
    try:
        doc = await db.logbooks.find_one({"_id": to_query_id(logbook_id)})
        if not doc:
            return
        activities = (doc.get("data") or {}).get("activities") or []
        loop = asyncio.get_running_loop()
        done = failed = 0

        for ai, activity in enumerate(activities):
            for pi, photo in enumerate(activity.get("photos") or []):
                if not isinstance(photo, dict):
                    continue
                if photo.get("enhance_status") == "done":
                    continue          # idempotent: re-saving a log re-runs nothing
                b64 = photo.get("base64")
                orig_key = photo.get("original_r2_key")
                if not b64 and not orig_key:
                    continue          # URI-only entry, nothing to enhance yet
                field = f"data.activities.{ai}.photos.{pi}"
                try:
                    if b64:
                        # Inline path, unchanged. Deliberately FIRST: a photo
                        # carrying both (what the backfill script produces
                        # mid-migration) must keep taking the route whose
                        # derivatives the finalize purge knows how to prove.
                        patch = await loop.run_in_executor(
                            _PHOTO_ENHANCE_POOL,
                            _enhance_one_photo_sync, b64, project_id, logbook_id, ai, pi,
                        )
                    else:
                        # Uploaded at capture: the bytes are in R2, never in
                        # Mongo, so they are read back from the object itself.
                        patch = await loop.run_in_executor(
                            _PHOTO_ENHANCE_POOL,
                            _enhance_r2_original_sync, orig_key,
                        )
                    done += 1
                except Exception as e:
                    logger.warning(
                        "[photo-enhance] failed logbook=%s a=%d p=%d: %r",
                        logbook_id, ai, pi, e,
                    )
                    patch = {"enhance_status": "failed", "enhance_error": str(e)[:200]}
                    failed += 1
                await db.logbooks.update_one(
                    {"_id": to_query_id(logbook_id)},
                    {"$set": {f"{field}.{k}": v for k, v in patch.items()}},
                )
        if done or failed:
            logger.info(
                "[photo-enhance] logbook=%s enhanced=%d failed=%d", logbook_id, done, failed,
            )
    except Exception as e:
        # Never let the background task surface as an unhandled task exception.
        logger.error("[photo-enhance] walk failed logbook=%s: %r", logbook_id, e)


def _presign_r2_get(r2_key: str, expires_in: int = 3600) -> str:
    """Return a short-lived signed GET URL for a private R2 object.

    Works even when the bucket has no public R2.dev subdomain enabled.
    Returns '' if R2 is not configured or signing fails.
    """
    if not _r2_client or not R2_BUCKET_NAME or not r2_key:
        return ""
    try:
        return _r2_client.generate_presigned_url(
            "get_object",
            Params={"Bucket": R2_BUCKET_NAME, "Key": r2_key},
            ExpiresIn=expires_in,
        )
    except Exception as e:
        logger.error(f"R2 presign failed for {r2_key}: {e}")
        return ""

