# Returns the project's complaints from the last 90 days, classified
# into the 10 violation_taxonomy buckets and sorted by count DESC.
# The Tactical Recommendations FE component uses this to decide which
# complaint buckets to fan out into /api/causal-lift queries.
@api_router.get(
    "/projects/{project_id}/recent-complaint-buckets",
    response_model=RecentComplaintBucketsResponse,
)
async def get_project_recent_complaint_buckets(
    project_id: str,
    current_user = Depends(get_current_user),
):
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    bin_id = project.get("nyc_bin")
    if not bin_id:
        return RecentComplaintBucketsResponse(buckets=[])
    from lib.statistical_engine.causal_lift import (
        _resolve_recent_complaint_buckets,
    )
    rows = await _resolve_recent_complaint_buckets(db, str(bin_id))
    return RecentComplaintBucketsResponse(buckets=[
        RecentComplaintBucket(**r) for r in rows
    ])


# ── PR #15D — Compliance Risk forecast endpoint ──────────────────
#
# Q1 lock: Pydantic models live INLINE here (matches codebase
# precedent: 100+ inline BaseModel classes elsewhere in server.py).
# NOT extracted to a separate models.py module.

class HorizonProbabilities(BaseModel):
    """PR #15D — 3-horizon probability shape for the response.
    Mirrors prediction_cache.prob_violation_{7,14,30}d fields."""
    model_config = ConfigDict(extra="forbid")
    prob_7d:  Optional[float] = None
    prob_14d: Optional[float] = None
    prob_30d: Optional[float] = None


class AnchoredBaseline(BaseModel):
    """PR #15D — cohort baseline shape.
    Mirrors prediction_cache.anchored_baseline_prob_{7,14,30}d +
    anchored_baseline_label + cohort_sample_size."""
    model_config = ConfigDict(extra="forbid")
    prob_7d:     Optional[float] = None  # G2 — may be None for legacy fits
    prob_14d:    Optional[float] = None
    prob_30d:    Optional[float] = None  # G2 — may be None for legacy fits
    label:       Optional[str]   = None
    cohort_size: Optional[int]   = None


class ConfidenceInfo(BaseModel):
    """PR #15D L8 + B-SERIALIZE — confidence + badge.
    badge is computed from prediction_cache flags at serialization
    time; not persisted in prediction_cache."""
    model_config = ConfigDict(extra="forbid")
    tier:          Optional[str]  = None
    sample_size:   Optional[int]  = None
    is_cold_start: Optional[bool] = None
    # null | "limited_peer_sample" | "cold_start" — see
    # lib.statistical_engine.live_mutation.compute_confidence_badge
    badge:         Optional[str]  = None


class PredictionMetadata(BaseModel):
    """PR #15D — timing + schema info. fit_at may be None for
    cold-start projects per Stage 1 Probe E receipts; L7 staleness
    is computed on last_validated_timestamp (always populated)."""
    model_config = ConfigDict(extra="forbid")
    fit_at:                   Optional[datetime] = None
    last_validated_timestamp: Optional[datetime] = None
    schema_version:           Optional[str]      = None


class PredictionResponse(BaseModel):
    """PR #15D — top-level response model for
    GET /api/projects/{project_id}/prediction."""
    model_config = ConfigDict(extra="forbid")
    prediction_available: bool
    horizons:             HorizonProbabilities
    anchored_baseline:    AnchoredBaseline
    confidence:           ConfidenceInfo
    metadata:             PredictionMetadata
    # PR #49 — adaptive primary forecast horizon (days). 14 by default;
    # 30 when an active SWO was issued within the last 7 days (cool-off
    # suppression). Computed live in the endpoint from SWO state;
    # defaults to 14 in the pure serializer (no DB access there). Literal
    # default mirrors live_mutation.DEFAULT_PRIMARY_HORIZON (kept inline
    # to avoid a heavy top-level import at class-definition time).
    recommended_primary_horizon: int = 14


def serialize_prediction_cache_to_response(
    project: Dict[str, Any],
) -> PredictionResponse:
    """PR #15D — transform ``project.prediction_cache`` into the
    API response shape. Handles:

      • Missing cache → ``prediction_available=False`` + all
        nested sub-models with default null fields.
      • ``fit_at=None`` (cold-start per Stage 1 Probe E) → preserved
        as null; ``last_validated_timestamp`` always populated.
      • Legacy fits without G2 baselines (anchored_baseline_prob_7d
        / _30d) → null in response (graceful degradation).
      • ``confidence.badge`` computed via
        ``compute_confidence_badge`` per B-SERIALIZE lock —
        NOT persisted in prediction_cache.
    """
    from lib.statistical_engine.live_mutation import (
        compute_confidence_badge as _badge,
    )

    cache = project.get("prediction_cache") or {}

    if not cache:
        return PredictionResponse(
            prediction_available=False,
            horizons=HorizonProbabilities(),
            anchored_baseline=AnchoredBaseline(),
            confidence=ConfidenceInfo(),
            metadata=PredictionMetadata(),
        )

    return PredictionResponse(
        prediction_available=True,
        horizons=HorizonProbabilities(
            prob_7d=cache.get("prob_violation_7d"),
            prob_14d=cache.get("prob_violation_14d"),
            prob_30d=cache.get("prob_violation_30d"),
        ),
        anchored_baseline=AnchoredBaseline(
            prob_7d=cache.get("anchored_baseline_prob_7d"),
            prob_14d=cache.get("anchored_baseline_prob_14d"),
            prob_30d=cache.get("anchored_baseline_prob_30d"),
            label=cache.get("anchored_baseline_label"),
            cohort_size=cache.get("cohort_sample_size"),
        ),
        confidence=ConfidenceInfo(
            tier=cache.get("cohort_tier_utilized"),
            sample_size=cache.get("cohort_sample_size"),
            is_cold_start=cache.get("is_cold_start"),
            badge=_badge(cache),
        ),
        metadata=PredictionMetadata(
            fit_at=cache.get("fit_at"),
            last_validated_timestamp=cache.get("last_validated_timestamp"),
            schema_version=cache.get("schema_version"),
        ),
    )


@api_router.get(
    "/projects/{project_id}/prediction",
    response_model=PredictionResponse,
)
async def get_project_prediction(
    project_id: str,
    current_user = Depends(get_current_user),
):
    """PR #15D — Compliance Risk forecast endpoint.

    Returns 3-horizon probability + anchored cohort baseline +
    confidence metadata for the user-facing Compliance Risk panel.
    Mirrors get_project at server.py:6950 for auth pattern:
      1. 404 on missing or soft-deleted project
      2. 403 on cross-company access
      3. 200 + PredictionResponse JSON on authorized read

    The frontend CompliancePanel consumes this; see
    frontend/src/components/CompliancePanel.jsx.
    """
    project = await db.projects.find_one(
        {"_id": to_query_id(project_id), "is_deleted": {"$ne": True}}
    )
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(
            status_code=403, detail="Access denied to this project",
        )

    response = serialize_prediction_cache_to_response(project)

    # PR #49 — compute the adaptive primary horizon live from SWO state.
    # 30-day window when an active SWO was issued within 7 days (cool-off
    # suppression), else 14. Computed per-request (no schema change) so
    # the panel reflects intra-day SWO changes. Defensive: any failure
    # leaves the serializer's 14-day default in place.
    try:
        from lib.statistical_engine.defcon import _resolve_swo_state
        from lib.statistical_engine.live_mutation import (
            _recommended_primary_horizon,
        )
        project_id_str = str(project.get("_id") or "")
        swo_state = await _resolve_swo_state(
            db, project_id_str, datetime.now(timezone.utc),
        )
        response.recommended_primary_horizon = _recommended_primary_horizon(
            swo_state,
        )
    except Exception as e:  # pragma: no cover — defensive
        logger.warning(
            "[pr49] recommended_primary_horizon compute failed for "
            "%s: %r", project.get("_id"), e,
        )

    return response


# ──────────────── V2.2 admin endpoints ────────────────────────────
#
# V2.3 Commit 1: the admin backfill endpoint was removed (it served
# the V2.2 local-mirror architecture, which is being replaced by
# lazy Socrata queries). Two admin-only endpoints survive:
#   GET  /api/admin/risk-score/calibration  — calibration breakdown
#   POST /api/admin/risk-score/weights      — manual prior tuning

@api_router.get("/admin/risk-score/calibration")
async def get_admin_risk_score_calibration(
    model_version: Optional[str] = None,
    current_user = Depends(get_admin_user),
):
    """Per-trigger calibration stats. Counts of hit / miss /
    expired_no_data, accuracy, false_positive_rate. Computed on
    demand from prediction_outcomes."""
    stats = await _stat_engine.compute_calibration_stats(
        db, model_version=model_version,
    )
    return {"calibration": stats}


class V22WeightTuneRequest(BaseModel):
    trigger_kind: str
    prior: float
    note: Optional[str] = None


@api_router.post("/admin/risk-score/weights")
async def post_admin_risk_score_weights(
    body: V22WeightTuneRequest,
    current_user = Depends(get_admin_user),
):
    """Manual per-trigger prior tuning. Operator reads
    calibration stats, decides, edits. NO auto-update — the
    statistical model never adjusts its own priors."""
    try:
        doc = await _stat_engine.set_trigger_prior(
            db,
            trigger_kind=body.trigger_kind,
            prior=body.prior,
            set_by_user_id=str(current_user.get("id") or ""),
            note=body.note,
        )
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e))
    return {"prior": doc}


