@api_router.post("/admin/company/insurance/refresh")
async def refresh_admin_company_insurance(current_user=Depends(get_admin_user)):
    """Refresh the company's GC license status/name from NYC Open Data.

    Insurance records are NOT touched by this endpoint — they are now managed
    manually via PUT /admin/company/insurance/manual. DOB BIS was the only
    source for insurance and is blocked by Akamai bot protection.
    """
    company_id = get_user_company_id(current_user)
    if not company_id:
        raise HTTPException(status_code=404, detail="No company associated with your account")

    company = await db.companies.find_one({"_id": to_query_id(company_id), "is_deleted": {"$ne": True}})
    if not company:
        raise HTTPException(status_code=404, detail="Company not found")

    lic_num = company.get("gc_license_number")
    if not lic_num:
        raise HTTPException(status_code=400, detail="No GC license linked to this company. Contact your administrator.")

    now = datetime.now(timezone.utc)
    warning = "Insurance records are manually managed. Use 'Update Insurance' to change expiry dates."

    # Pull current status via NYC Open Data using the existing scrape_gc_license_info
    # implementation (which was rewritten in Commit 1 to hit Open Data).
    try:
        from permit_renewal import scrape_gc_license_info
        lookup_name = company.get("gc_business_name") or company.get("name", "")
        logger.info(
            f"Insurance refresh — company_id={company_id} license={lic_num} "
            f"lookup_name={lookup_name!r}"
        )
        gc_info = await scrape_gc_license_info(lookup_name)
        update_fields = {
            "gc_last_verified": now,
            "updated_at": now,
        }
        if gc_info:
            if gc_info.license_status:
                update_fields["gc_license_status"] = gc_info.license_status
            if gc_info.license_expiration:
                update_fields["gc_license_expiration"] = gc_info.license_expiration
            if gc_info.business_name:
                update_fields["gc_business_name"] = gc_info.business_name
            if gc_info.licensee_name:
                update_fields["gc_licensee_name"] = gc_info.licensee_name

        await db.companies.update_one({"_id": to_query_id(company_id)}, {"$set": update_fields})
        # Re-read so we return fresh values
        company = await db.companies.find_one({"_id": to_query_id(company_id)})

    except Exception as e:
        logger.error(f"License refresh failed for company {company_id} license {lic_num}: {e}")
        warning = "Could not reach NYC Open Data. Showing cached license data."

    return {
        "gc_license_number": lic_num,
        "gc_license_status": company.get("gc_license_status"),
        "gc_license_expiration": company.get("gc_license_expiration"),
        # Preserve manually-entered records — never overwrite.
        "gc_insurance_records": company.get("gc_insurance_records", []),
        "gc_last_verified": str(now),
        "warning": warning,
    }


class ManualInsuranceRequest(BaseModel):
    general_liability_expiry: str
    workers_comp_expiry: str
    disability_expiry: str


@api_router.put("/admin/company/insurance/manual")
async def set_admin_company_insurance_manual(
    body: ManualInsuranceRequest,
    current_user=Depends(get_admin_user),
):
    """
    Admin manually sets the 3 required insurance expiry dates for their company.
    Replaces the BIS-scraped records, since BIS is blocked by Akamai.

    Dates must be parseable (MM/DD/YYYY preferred), must be in the future,
    and must be within 5 years from today.
    """
    company_id = get_user_company_id(current_user)
    if not company_id:
        raise HTTPException(status_code=404, detail="No company associated with your account")

    company = await db.companies.find_one({"_id": to_query_id(company_id), "is_deleted": {"$ne": True}})
    if not company:
        raise HTTPException(status_code=404, detail="Company not found")

    from dateutil import parser as dateparser

    field_specs = [
        ("general_liability", "General Liability", body.general_liability_expiry),
        ("workers_comp",      "Workers' Comp",     body.workers_comp_expiry),
        ("disability",        "Disability",        body.disability_expiry),
    ]

    now = datetime.now(timezone.utc)
    max_future = now + timedelta(days=365 * 5)
    today_midnight = now.replace(hour=0, minute=0, second=0, microsecond=0)

    parsed = []
    for ins_type, label, raw in field_specs:
        raw = (raw or "").strip()
        if not raw:
            raise HTTPException(
                status_code=422,
                detail=f"{label} expiration date is required.",
            )
        try:
            dt = dateparser.parse(raw)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
        except Exception:
            raise HTTPException(
                status_code=422,
                detail=f"{label} date '{raw}' could not be parsed. Use MM/DD/YYYY.",
            )

        if dt < today_midnight:
            raise HTTPException(
                status_code=422,
                detail=f"{label} expiration is in the past ({raw}). Enter a current or future date.",
            )
        if dt > max_future:
            raise HTTPException(
                status_code=422,
                detail=f"{label} expiration is more than 5 years out ({raw}). Double-check the year.",
            )

        parsed.append((ins_type, label, dt))

    today_str = now.strftime("%m/%d/%Y")
    records = []
    for ins_type, label, dt in parsed:
        records.append({
            "insurance_type": ins_type,
            "carrier_name":   None,
            "policy_number":  None,
            "effective_date": today_str,
            "expiration_date": dt.strftime("%m/%d/%Y"),
            "is_current":     True,
            "source":         "manual_entry",
        })

    await db.companies.update_one(
        {"_id": to_query_id(company_id)},
        {"$set": {
            "gc_insurance_records": records,
            "gc_last_verified": now,
            "updated_at": now,
        }},
    )

    # Audit
    try:
        await audit_log(
            "insurance_manual_update",
            str(current_user.get("id", "")),
            "company",
            str(company_id),
            {"records": records},
        )
    except Exception as e:
        logger.warning(f"audit_log(insurance_manual_update) failed: {e}")

    company = await db.companies.find_one({"_id": to_query_id(company_id)})
    return {
        "company_id":            str(company["_id"]),
        "company_name":          company.get("name"),
        "gc_license_number":     company.get("gc_license_number"),
        "gc_business_name":      company.get("gc_business_name"),
        "gc_licensee_name":      company.get("gc_licensee_name"),
        "gc_license_status":     company.get("gc_license_status"),
        "gc_license_expiration": company.get("gc_license_expiration"),
        "gc_insurance_records":  company.get("gc_insurance_records", []),
        "gc_resolved":           company.get("gc_resolved", False),
        "gc_last_verified":      company.get("gc_last_verified"),
    }


# ==================== COI UPLOAD + OCR (Step 7) ====================
# Admin uploads a Certificate of Insurance PDF; backend OCRs via Qwen,
# stores the original in R2 with 7-year retention, returns the parsed
# fields for admin to review before commit.
#
# Two-phase: upload returns a draft, confirm commits to gc_insurance_records.
# Drafts auto-expire after 24h (TTL index in startup).
#
# GC-licensed companies only; HIC and unlicensed companies don't see
# the upload UI (per plan §5.1) and are rejected here as defense in depth.

class CoiConfirmRequest(BaseModel):
    draft_id: str
    insurance_type: str           # general_liability | workers_comp | disability
    carrier_name: Optional[str] = None
    policy_number: Optional[str] = None
    effective_date: Optional[str] = None    # MM/DD/YYYY
    expiration_date: Optional[str] = None   # MM/DD/YYYY


@api_router.post("/admin/company/insurance/upload-coi", dependencies=[Depends(require_approved)])
async def admin_upload_coi(
    insurance_type: str = Form(...),
    file: UploadFile = File(...),
    current_user=Depends(get_admin_user),
):
    """Phase 1 of COI upload — validate, store, OCR, return draft.

    Idempotent on file bytes via SHA-256: re-uploading the same PDF
    yields the same R2 key (R2 dedupes naturally) and re-uses the
    cached OCR result if one exists for this (company, sha) pair —
    no duplicate Qwen API charge.
    """
    from lib.coi_storage import (
        validate_pdf_bytes,
        coi_pdf_key,
        coi_preview_key,
        render_first_page_jpeg,
        upload_coi_objects,
        ALLOWED_INSURANCE_TYPES,
        CoiValidationError,
    )
    from lib.coi_ocr import extract_coi_fields, OcrConfigError

    if insurance_type not in ALLOWED_INSURANCE_TYPES:
        raise HTTPException(
            status_code=400,
            detail=f"insurance_type must be one of {sorted(ALLOWED_INSURANCE_TYPES)}",
        )

    company_id = get_user_company_id(current_user)
    if not company_id:
        raise HTTPException(status_code=404, detail="No company associated with your account")

    company = await db.companies.find_one(
        {"_id": to_query_id(company_id), "is_deleted": {"$ne": True}}
    )
    if not company:
        raise HTTPException(status_code=404, detail="Company not found")

    # Defense in depth: HIC / unlicensed companies don't get COI UI in
    # the frontend, but reject here too in case the endpoint is hit
    # directly. GC license is the only one DOB tracks insurance for.
    if (company.get("license_class") or "GC_LICENSED") != "GC_LICENSED":
        raise HTTPException(
            status_code=409,
            detail=(
                "COI upload is for GC-licensed companies only. "
                "HIC license insurance is managed through DCWP, not LeveLog."
            ),
        )

    # Read + validate. Synchronous bytes work runs in executor so the
    # event loop doesn't block on a 300KB upload.
    pdf_bytes = await file.read()
    try:
        validated = await asyncio.to_thread(
            validate_pdf_bytes,
            pdf_bytes,
            expected_content_type=file.content_type or "",
        )
    except CoiValidationError as e:
        raise HTTPException(status_code=400, detail=str(e))

    # Idempotency: if we already have a draft / confirmed record for
    # this exact file, return the existing OCR result. Same sha →
    # same parsed fields, no Qwen charge.
    sha = validated.sha256_hex
    pdf_key = coi_pdf_key(str(company_id), insurance_type, sha)
    preview_key = coi_preview_key(str(company_id), insurance_type, sha)

    existing_draft = await db.coi_ocr_drafts.find_one({
        "company_id": str(company_id),
        "sha256": sha,
        "insurance_type": insurance_type,
    })
    if existing_draft:
        return {
            "draft_id": str(existing_draft["_id"]),
            "pdf_url": existing_draft.get("pdf_url"),
            "preview_url": existing_draft.get("preview_url"),
            "parsed": existing_draft.get("ocr_result", {}),
            "cached": True,
        }

    # Render first page → JPEG. Run in executor (poppler is blocking).
    try:
        preview_bytes = await asyncio.to_thread(render_first_page_jpeg, pdf_bytes)
    except CoiValidationError as e:
        raise HTTPException(status_code=400, detail=str(e))

    # Upload PDF + preview to R2. Same path runs in executor.
    try:
        urls = await asyncio.to_thread(
            upload_coi_objects,
            pdf_bytes, preview_bytes,
            pdf_key, preview_key,
            sha256_hex=sha,
            insurance_type=insurance_type,
            company_id=str(company_id),
        )
    except RuntimeError as e:
        # R2 not configured — surface as 503, not a 500.
        raise HTTPException(status_code=503, detail=str(e))

    # OCR — async-native, no executor needed.
    try:
        ocr_result = await extract_coi_fields(
            preview_bytes,
            insurance_type=insurance_type,
        )
    except OcrConfigError as e:
        raise HTTPException(status_code=503, detail=str(e))
    except Exception as e:
        # OCR failed but we have the PDF stored. Return a draft with
        # empty parsed values so admin can manually fill in.
        logger.error(f"COI OCR failed for company={company_id} sha={sha[:16]}: {type(e).__name__}")
        from lib.coi_ocr import CoiOcrResult
        ocr_result = CoiOcrResult(min_confidence=0.0)

    parsed_payload = ocr_result.as_admin_payload()

    # Persist as draft. Confirmed-in-place via the confirm endpoint.
    now = datetime.now(timezone.utc)
    draft_doc = {
        "company_id": str(company_id),
        "user_id": str(current_user.get("id", "")),
        "sha256": sha,
        "insurance_type": insurance_type,
        "size_bytes": validated.size_bytes,
        "page_count": validated.page_count,
        "pdf_key": pdf_key,
        "preview_key": preview_key,
        "pdf_url": urls["pdf_url"],
        "preview_url": urls["preview_url"],
        "ocr_result": parsed_payload,
        "created_at": now,
    }
    insert_result = await db.coi_ocr_drafts.insert_one(draft_doc)

    # Audit log: never echoes parsed values, only metadata. PII stays
    # in coi_ocr_drafts and only flows to the confirm response.
    try:
        await audit_log(
            "coi_uploaded",
            str(current_user.get("id", "")),
            "company",
            str(company_id),
            {
                "insurance_type": insurance_type,
                "sha256": sha,
                "size_bytes": validated.size_bytes,
                "page_count": validated.page_count,
                "min_confidence": parsed_payload.get("min_confidence"),
                "auto_accept": parsed_payload.get("auto_accept"),
                "draft_id": str(insert_result.inserted_id),
            },
        )
    except Exception as e:
        logger.warning(f"audit_log(coi_uploaded) failed: {e}")

    return {
        "draft_id": str(insert_result.inserted_id),
        "pdf_url": urls["pdf_url"],
        "preview_url": urls["preview_url"],
        "parsed": parsed_payload,
        "cached": False,
    }


@api_router.put("/admin/company/insurance/upload-coi/confirm", dependencies=[Depends(require_approved)])
async def admin_confirm_coi(
    body: CoiConfirmRequest,
    current_user=Depends(get_admin_user),
):
    """Phase 2 — admin commits the (possibly edited) parsed fields to
    gc_insurance_records. Replaces any existing record of the same
    insurance_type on this company; the prior record's PDF stays in
    R2 (7-year retention metadata) and is referenced from the audit
    log entry so we don't lose the audit trail."""
    from lib.coi_storage import ALLOWED_INSURANCE_TYPES

    if body.insurance_type not in ALLOWED_INSURANCE_TYPES:
        raise HTTPException(
            status_code=400,
            detail=f"insurance_type must be one of {sorted(ALLOWED_INSURANCE_TYPES)}",
        )

    company_id = get_user_company_id(current_user)
    if not company_id:
        raise HTTPException(status_code=404, detail="No company associated with your account")

    draft = await db.coi_ocr_drafts.find_one({"_id": to_query_id(body.draft_id)})
    if not draft:
        raise HTTPException(status_code=404, detail="COI draft not found or expired")
    if draft.get("company_id") != str(company_id):
        # Don't reveal cross-tenant existence — generic 404.
        raise HTTPException(status_code=404, detail="COI draft not found or expired")
    if draft.get("insurance_type") != body.insurance_type:
        raise HTTPException(
            status_code=400,
            detail="Draft insurance_type does not match confirm body. Re-upload.",
        )

    # Build the new InsuranceRecord. Pulled values from the confirm
    # request (admin may have edited the OCR output); R2 URL + OCR
    # confidence carry over from the draft so audit trail is preserved.
    now = datetime.now(timezone.utc)
    parsed = draft.get("ocr_result") or {}
    new_record = {
        "insurance_type":      body.insurance_type,
        "carrier_name":        body.carrier_name,
        "policy_number":       body.policy_number,
        "effective_date":      body.effective_date,
        "expiration_date":     body.expiration_date,
        "is_current":          True,
        "source":              "coi_ocr",
        "coi_pdf_url":         draft.get("pdf_url"),
        "ocr_confidence":      parsed.get("min_confidence"),
        "dob_now_verified_at": None,
        "dob_now_discrepancy": False,
    }

    company = await db.companies.find_one(
        {"_id": to_query_id(company_id), "is_deleted": {"$ne": True}}
    )
    if not company:
        raise HTTPException(status_code=404, detail="Company not found")

    # Replace any existing record of this type. Keep all other types untouched.
    existing_records = company.get("gc_insurance_records") or []
    prior_of_type = next(
        (r for r in existing_records
         if isinstance(r, dict) and r.get("insurance_type") == body.insurance_type),
        None,
    )
    new_records = [
        r for r in existing_records
        if not (isinstance(r, dict) and r.get("insurance_type") == body.insurance_type)
    ]
    new_records.append(new_record)

    await db.companies.update_one(
        {"_id": to_query_id(company_id)},
        {"$set": {"gc_insurance_records": new_records, "updated_at": now}},
    )

    # Cleanup: drop the draft now that it's been committed.
    await db.coi_ocr_drafts.delete_one({"_id": to_query_id(body.draft_id)})

    try:
        await audit_log(
            "coi_confirmed",
            str(current_user.get("id", "")),
            "company",
            str(company_id),
            {
                "insurance_type":   body.insurance_type,
                "draft_id":         body.draft_id,
                "ocr_confidence":   parsed.get("min_confidence"),
                "auto_accept":      parsed.get("auto_accept"),
                "edited_by_admin":  _coi_diff(parsed, body),
                "prior_record_url": (prior_of_type or {}).get("coi_pdf_url"),
                "new_record_url":   draft.get("pdf_url"),
            },
        )
    except Exception as e:
        logger.warning(f"audit_log(coi_confirmed) failed: {e}")

    return {
        "ok": True,
        "insurance_type": body.insurance_type,
        "carrier_name":   new_record["carrier_name"],
        "expiration_date": new_record["expiration_date"],
        "source":         new_record["source"],
        "ocr_confidence": new_record["ocr_confidence"],
        "coi_pdf_url":    new_record["coi_pdf_url"],
    }


def _coi_diff(parsed: dict, body: CoiConfirmRequest) -> list:
    """Identify which fields the admin edited away from the OCR result.
    Returned in the audit log so we can post-hoc audit OCR accuracy:
    if admins are routinely overriding `policy_number`, the prompt
    needs work. Field VALUES are intentionally NOT logged — only the
    list of which fields were changed."""
    edited = []
    for f in ("carrier_name", "policy_number", "effective_date", "expiration_date"):
        if (parsed.get(f) or "") != (getattr(body, f) or ""):
            edited.append(f)
    return edited


# ==================== END COI UPLOAD + OCR ====================


class CreateAdminRequest(BaseModel):
    name: str
    email: str
    password: str
    company_name: str
    phone: Optional[str] = None

@api_router.post("/owner/admins", dependencies=[Depends(require_platform_operator)])
async def create_admin_with_company(admin_data: CreateAdminRequest, current_user = Depends(get_current_user)):
    """Create admin account with company (owner only)"""
    if current_user.get("role") != "owner":
        raise HTTPException(status_code=403, detail="Owner access required")
    
    # Check if email exists
    existing_user = await db.users.find_one({"email": admin_data.email, "is_deleted": {"$ne": True}})
    if existing_user:
        raise HTTPException(status_code=400, detail="Email already registered")
    
    # Create company first
    company_name = admin_data.company_name
    existing_company = await db.companies.find_one({"name": company_name, "is_deleted": {"$ne": True}})
    
    now = datetime.now(timezone.utc)
    
    if existing_company:
        company_id = str(existing_company["_id"])
    else:
        company_doc = {
            "name": company_name,
            "created_at": now,
            "updated_at": now,
            "created_by": current_user.get("id"),
            "is_deleted": False
        }
        company_result = await db.companies.insert_one(company_doc)
        company_id = str(company_result.inserted_id)
    
    # Normalize and collision-check phone (if provided)
    new_phone = ""
    if admin_data.phone and admin_data.phone.strip():
        new_phone = normalize_phone(admin_data.phone.strip())
        collision = await db.users.find_one({
            "company_id": company_id,
            "phone": new_phone,
            "is_deleted": {"$ne": True},
        })
        if collision:
            raise HTTPException(
                status_code=409,
                detail="This phone number is already in use by another user in this company.",
            )

    # Create admin user
    user_doc = {
        "email": admin_data.email,
        "password": hash_password(admin_data.password),
        "name": admin_data.name,
        "role": "admin",
        "registration_source": REG_ADMIN,
        "company_id": company_id,
        "company_name": company_name,
        "created_at": now,
        "updated_at": now,
        "assigned_projects": [],
        "is_deleted": False
    }
    if new_phone:
        user_doc["phone"] = new_phone

    user_result = await db.users.insert_one(user_doc)
    new_user_id = str(user_result.inserted_id)

    # If company WhatsApp is active, upsert the new admin into whatsapp_contacts.
    # If not active, whatsapp_activate's auto-population sweep will pick them up later.
    if new_phone:
        try:
            wa_config = await db.whatsapp_config.find_one({"company_id": company_id})
            if wa_config and wa_config.get("is_active"):
                await db.whatsapp_contacts.update_one(
                    {"company_id": company_id, "phone": new_phone},
                    {"$set": {
                        "company_id": company_id,
                        "phone": new_phone,
                        "user_id": new_user_id,
                        "display_name": admin_data.name,
                    }},
                    upsert=True,
                )
        except Exception as e:
            logger.warning(f"whatsapp_contacts upsert failed for new admin {new_user_id}: {e}")

    return {
        "id": new_user_id,
        "email": admin_data.email,
        "name": admin_data.name,
        "phone": new_phone or None,
        "company_id": company_id,
        "company_name": company_name,
        "role": "admin",
        "message": "Admin account created successfully"
    }

@api_router.get("/owner/admins", dependencies=[Depends(require_platform_operator)])
async def get_admin_accounts(current_user = Depends(get_current_user)):
    """Get all admin accounts (owner only)"""
    if current_user.get("role") != "owner":
        raise HTTPException(status_code=403, detail="Owner access required")
    
    admins = await db.users.find({"role": "admin", "is_deleted": {"$ne": True}}, {"password": 0}).to_list(200)
    return serialize_list(admins)

@api_router.delete("/owner/admins/{admin_id}", dependencies=[Depends(require_platform_operator)])
async def delete_admin_account(admin_id: str, current_user = Depends(get_current_user)):
    """Delete admin account (owner only)"""
    if current_user.get("role") != "owner":
        raise HTTPException(status_code=403, detail="Owner access required")
    
    # Same single writer as DELETE /admin/users/{id} — see the note there.
    result = await db.users.update_one(
        {"_id": to_query_id(admin_id), "role": "admin"},
        {"$set": _mark_user_deleted(admin_id)},
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Admin not found")
    
    return {"message": "Admin account deleted successfully"}

@api_router.put("/owner/admins/{admin_id}", dependencies=[Depends(require_platform_operator)])
async def update_admin_account(admin_id: str, admin_data: dict, current_user = Depends(get_current_user)):
    """Update admin account (owner only)"""
    if current_user.get("role") != "owner":
        raise HTTPException(status_code=403, detail="Owner access required")
    
    update_fields = {}
    if "name" in admin_data:
        update_fields["name"] = admin_data["name"]
    if "email" in admin_data:
        update_fields["email"] = admin_data["email"]
    if "company_id" in admin_data:
        update_fields["company_id"] = admin_data["company_id"]
    if "password" in admin_data and admin_data["password"]:
        update_fields["password"] = hash_password(admin_data["password"])
    
    if not update_fields:
        raise HTTPException(status_code=400, detail="No fields to update")
    
    update_fields["updated_at"] = datetime.now(timezone.utc)
    
    result = await db.users.update_one(
        {"_id": to_query_id(admin_id), "role": "admin", "is_deleted": {"$ne": True}},
        {"$set": update_fields}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Admin not found")
    
    admin = await db.users.find_one({"_id": to_query_id(admin_id)})
    return serialize_id(admin)

@api_router.post("/admin/migrate-company-data")
async def migrate_company_data(data: dict, current_user = Depends(get_current_user)):
    """Migrate admin data to companies (owner only)"""
    if current_user.get("role") != "owner":
        raise HTTPException(status_code=403, detail="Owner access required")
    
    assignments = data.get("assignments", [])
    results = []
    
    for assignment in assignments:
        admin_email = assignment.get("admin_email")
        company_id = assignment.get("company_id")
        
        if not admin_email or not company_id:
            continue
        
        # Update admin's company_id
        await db.users.update_one(
            {"email": admin_email, "is_deleted": {"$ne": True}},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        
        # Find admin
        admin = await db.users.find_one({"email": admin_email})
        if not admin:
            continue
        
        admin_id = str(admin["_id"])
        
        # Migrate projects created by this admin
        await db.projects.update_many(
            {"created_by": admin_id, "company_id": {"$exists": False}},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        await db.projects.update_many(
            {"created_by": admin_id, "company_id": None},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        
        # Migrate workers
        await db.workers.update_many(
            {"created_by": admin_id, "company_id": {"$exists": False}},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        await db.workers.update_many(
            {"created_by": admin_id, "company_id": None},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        
        # Migrate checkins
        await db.checkins.update_many(
            {"created_by": admin_id, "company_id": {"$exists": False}},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        
        # Migrate daily logs
        await db.daily_logs.update_many(
            {"created_by": admin_id, "company_id": {"$exists": False}},
            {"$set": {"company_id": company_id, "updated_at": datetime.now(timezone.utc)}}
        )
        
        results.append({"admin_email": admin_email, "company_id": company_id, "status": "migrated"})
    
    return {"message": "Migration completed", "results": results}

# ==================== PROJECTS ====================

@api_router.get("/projects")
async def get_projects(
    current_user = Depends(get_current_user),
    limit: int = Query(50, ge=1, le=200),
    skip: int = Query(0, ge=0),
):
    company_id = get_user_company_id(current_user)

    # Marked-for-deletion projects vanish from the admin list; only the
    # owner sees them, via GET /projects/pending-deletion.
    query = dict(ACTIVE_PROJECT_FILTER)

    # THE TENANT FILTER WAS CONDITIONAL, and this is where foreign project ids
    # came from. `if company_id:` — so a caller with NO company_id skipped it
    # and received EVERY company's projects, ids included.
    #
    # That is not an exotic account state, it is the DEFAULT one: self-serve
    # registration sets `user_dict["company_id"] = None` outright, and a
    # company is only attached later by POST /onboarding/company. So every
    # freshly registered account, before onboarding, could list the whole
    # platform's projects.
    #
    # A caller with no company has no projects, so the honest answer is an
    # empty list. `_id: None` cannot match any document — an unsatisfiable
    # filter rather than a second return path, so pagination, the defcon
    # augmentation below and the response shape stay identical to a company
    # that simply owns nothing. A pre-onboarding user still has GET
    # /demo/project, which is what they are meant to see.
    #
    # The platform operator keeps the unfiltered list: the one deliberate
    # cross-company path, the same carve-out validate_assignable_projects
    # makes, and never inferred from `role` — role "owner" is what every
    # self-serve signup receives.
    if company_id:
        query["company_id"] = company_id
    elif not is_platform_operator(current_user):
        query["_id"] = None

    result = await paginated_query(
        db.projects, query, sort_field="name", sort_dir=1,
        limit=limit, skip=skip,
    )

    # Phase 1 Week 11-12 PR-A — augment each project with defcon_tier
    # for the project-list colored-dot rendering. Avoids N+1 calls
    # from the frontend. Failures per-project are swallowed (tier
    # field defaults to None) — list rendering must not break on a
    # single project's defcon compute failure.
    from lib.statistical_engine.defcon import compute_defcon_status
    items = result.get("items") if isinstance(result, dict) else None
    if items is None and isinstance(result, list):
        items = result
    if items:
        for p in items:
            try:
                ds = await compute_defcon_status(db, p)
                p["defcon_tier"] = ds.get("tier")
            except Exception as _e:
                logger.warning(
                    "[phase1w11] defcon tier compute failed for "
                    "project=%r: %r", p.get("_id"), _e,
                )
                p["defcon_tier"] = None
    return result


# NOTE: this route MUST stay defined before GET /projects/{project_id}
# (the 2-segment catch-all below) or Starlette would match
# "/projects/dob-summary" as project_id="dob-summary".
@api_router.get("/projects/dob-summary")
async def get_projects_dob_summary(
    project_id: Optional[str] = Query(
        None,
        description=(
            "Restrict to a single project. Omit for the whole "
            "company portfolio."
        ),
    ),
    current_user=Depends(get_current_user),
):
    """DIAGNOSTIC cross-project DOB exposure rollup.

    Reports STANDING OPEN exposure computed server-side in Mongo from
    facts already in db.dob_logs. Serves the desktop dashboard rollup
    (portfolio totals) and the projects table (per-row) from one call,
    replacing the N+1 per-row risk fetch.

    This endpoint makes NO prediction and computes NO risk score. It
    counts currently-open records and reuses existing risk_scores rows
    only to report PRESENCE (has_risk_score / "Scoring").

    Correctness invariants:
      • Dedup by raw_dob_id — a status change INSERTS a new row, so
        counting rows overcounts. The pipeline keeps the latest row per
        raw_dob_id (status_changed_at desc, then detected_at desc).
      • NO detected_at FILTER anywhere. detected_at is a backfill/sync
        stamp; filtering on it is the tile-decay bug this endpoint
        exists to avoid. It is used only as the final dedup tiebreaker.
      • "open" is derived from per-record STATUS fields, never an
        event-date window — so a violation issued years ago that is
        still open is counted.

    Response:
      { "by_project": { "<pid>": { "open_violations", "open_complaints",
                                   "permits_expiring", "total_violations",
                                   "total_complaints", "total_permits",
                                   "permits_no_expiry", "has_risk_score" } },
        "totals":     { "open_violations", "open_complaints",
                        "permits_expiring", "total_violations",
                        "total_complaints", "total_permits",
                        "permits_no_expiry", "projects_without_score",
                        "projects_total" } }

    total_* are per-type denominators for the "X of Y" tiles (deduped by
    raw_dob_id, all statuses; total_permits = ACTIVE only — not-expired by date,
    REVOKED excluded). permits_no_expiry = permits with no parseable
    expiration_date, excluded from total_permits and disclosed in the UI.

    Violations are count-only: dob_logs has no field mapping to DOB
    hazard class 1/2/3 (see docs/audits/ui-inventory-2026-07-23.md
    Follow-ups). Permit expiry uses $dateFromString because
    expiration_date is mixed-format (ISO-with-time, MDY, null);
    unparseable rows drop out (undercount, never miscount) — normalizing
    expiration_date at ingestion is a logged follow-up.
    """
    company_id = get_user_company_id(current_user)

    # Resolve the in-scope project set (company-scoped, active).
    proj_query = dict(ACTIVE_PROJECT_FILTER)
    if company_id:
        proj_query["company_id"] = company_id
    if project_id:
        proj_query["_id"] = to_query_id(project_id)
    proj_docs = await db.projects.find(proj_query, {"_id": 1}).to_list(length=1000)
    project_ids = [str(p["_id"]) for p in proj_docs]

    if not project_ids:
        return {
            "by_project": {},
            "totals": {
                "open_violations": 0, "open_complaints": 0,
                "permits_expiring": 0,
                "total_violations": 0, "total_complaints": 0,
                "total_permits": 0, "permits_no_expiry": 0,
                "projects_without_score": 0, "projects_total": 0,
            },
        }

    now = datetime.now(timezone.utc)
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    t30 = today_start + timedelta(days=30)

    # Match prefix leads with company_id (the dob_logs_summary_dedup
    # index prefix). Fall back to the resolved project set for the
    # no-company superadmin path; narrow to one project when asked.
    match: Dict[str, Any] = {
        "is_deleted": {"$ne": True},
        "is_seed_transition": {"$ne": True},
        "record_type": {"$in": ["violation", "swo", "complaint", "permit"]},
    }
    if company_id:
        match["company_id"] = company_id
    else:
        match["project_id"] = {"$in": project_ids}
    if project_id:
        match["project_id"] = project_id

    # Dedup: newest state per raw_dob_id wins. detected_at is ONLY a
    # tiebreaker here — never a filter.
    dedup_sort = {"raw_dob_id": 1, "status_changed_at": -1, "detected_at": -1}

    pipeline = [
        {"$match": match},
        {"$facet": {
            "open_violations": [
                {"$match": {"record_type": {"$in": ["violation", "swo"]}}},
                {"$sort": dedup_sort},
                {"$group": {
                    "_id": "$raw_dob_id",
                    "project_id": {"$first": "$project_id"},
                    "resolution_state": {"$first": "$resolution_state"},
                }},
                # open = resolution_state NOT in the closed set. null /
                # absent counts as open (conservative for compliance).
                {"$match": {"resolution_state": {
                    "$nin": ["certified", "dismissed", "paid", "resolved"]}}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
            "open_complaints": [
                {"$match": {"record_type": "complaint"}},
                {"$sort": dedup_sort},
                {"$group": {
                    "_id": "$raw_dob_id",
                    "project_id": {"$first": "$project_id"},
                    "closed_date": {"$first": "$closed_date"},
                    "complaint_status": {"$first": "$complaint_status"},
                }},
                # open = no closed_date AND status not matching /closed/i.
                {"$match": {"$and": [
                    {"$or": [
                        {"closed_date": None},
                        {"closed_date": {"$exists": False}},
                        {"closed_date": ""},
                    ]},
                    {"$or": [
                        {"complaint_status": None},
                        {"complaint_status": {
                            "$not": {"$regex": "closed", "$options": "i"}}},
                    ]},
                ]}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
            "permits_expiring": [
                {"$match": {"record_type": "permit"}},
                {"$sort": dedup_sort},
                {"$group": {
                    "_id": "$raw_dob_id",
                    "project_id": {"$first": "$project_id"},
                    "expiration_date": {"$first": "$expiration_date"},
                }},
                # Mixed-format expiration_date (ISO-with-time / MDY /
                # null): ISO parses; MDY + null fail -> onError/onNull
                # null -> excluded by the range below (null is not
                # >= a date). Undercount, never miscount.
                {"$addFields": {"_exp": {"$dateFromString": {
                    "dateString": "$expiration_date",
                    "onError": None, "onNull": None,
                }}}},
                # Expiring within 30 days AND not already expired.
                {"$match": {"_exp": {"$gte": today_start, "$lte": t30}}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
            # ── Per-type TOTALS (denominators for the "X of Y" tiles) ──
            # Same dedup + scope as the open facets; additive — the open-count
            # logic above is untouched.
            "total_violations": [
                {"$match": {"record_type": {"$in": ["violation", "swo"]}}},
                {"$sort": dedup_sort},
                {"$group": {"_id": "$raw_dob_id", "project_id": {"$first": "$project_id"}}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
            "total_complaints": [
                {"$match": {"record_type": "complaint"}},
                {"$sort": dedup_sort},
                {"$group": {"_id": "$raw_dob_id", "project_id": {"$first": "$project_id"}}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
            # ACTIVE permits (Option A): not-expired by date, REVOKED excluded,
            # Signed-off kept. Dedup FIRST so REVOKED/expiration are judged on
            # the LATEST row. Reuses the SAME UTC today_start as permits_expiring
            # so expiring (today..t30) is always a subset of active (>= today) —
            # UTC-vs-NYC-local boundary logged as a minor known item. Permits
            # whose expiration_date is null/unparseable (all DOB NOW Electrical —
            # dm9a-ab7w has no expiration_date) get _exp=null and drop out here;
            # they are surfaced as permits_no_expiry so the tile can disclose
            # them (never a silent undercount).
            "total_permits": [
                {"$match": {"record_type": "permit"}},
                {"$sort": dedup_sort},
                {"$group": {
                    "_id": "$raw_dob_id",
                    "project_id": {"$first": "$project_id"},
                    "permit_status": {"$first": "$permit_status"},
                    "expiration_date": {"$first": "$expiration_date"},
                }},
                {"$match": {"permit_status": {"$ne": "REVOKED"}}},
                {"$addFields": {"_exp": {"$dateFromString": {
                    "dateString": "$expiration_date", "onError": None, "onNull": None,
                }}}},
                {"$match": {"_exp": {"$gte": today_start}}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
            # Deduped permits with NO parseable expiration_date — excluded from
            # the active denominator; returned so the UI can disclose the gap.
            "permits_no_expiry": [
                {"$match": {"record_type": "permit"}},
                {"$sort": dedup_sort},
                {"$group": {
                    "_id": "$raw_dob_id",
                    "project_id": {"$first": "$project_id"},
                    "expiration_date": {"$first": "$expiration_date"},
                }},
                {"$addFields": {"_exp": {"$dateFromString": {
                    "dateString": "$expiration_date", "onError": None, "onNull": None,
                }}}},
                {"$match": {"_exp": None}},
                {"$group": {"_id": "$project_id", "n": {"$sum": 1}}},
            ],
        }},
    ]

    agg = await db.dob_logs.aggregate(pipeline).to_list(length=1)
    facets = agg[0] if agg else {}

    def _by_pid(bucket):
        return {r["_id"]: r["n"] for r in facets.get(bucket, []) if r.get("_id")}

    ov = _by_pid("open_violations")
    oc = _by_pid("open_complaints")
    pe = _by_pid("permits_expiring")
    tv = _by_pid("total_violations")
    tc = _by_pid("total_complaints")
    tp = _by_pid("total_permits")        # active permits (Option A)
    pne = _by_pid("permits_no_expiry")   # excluded from active — disclose in UI

    # Risk-score PRESENCE only — separate collection, string project_id
    # (projects._id is ObjectId; recompute_and_persist stores
    # str(project["_id"])), current model_version. No score is computed
    # or written here.
    scored = set(await db.risk_scores.distinct(
        "project_id",
        {"model_version": _stat_engine.MODEL_VERSION,
         "project_id": {"$in": project_ids}},
    ))

    by_project = {
        pid: {
            "open_violations": int(ov.get(pid, 0)),
            "open_complaints": int(oc.get(pid, 0)),
            "permits_expiring": int(pe.get(pid, 0)),
            "total_violations": int(tv.get(pid, 0)),
            "total_complaints": int(tc.get(pid, 0)),
            "total_permits": int(tp.get(pid, 0)),
            "permits_no_expiry": int(pne.get(pid, 0)),
            "has_risk_score": pid in scored,
        }
        for pid in project_ids
    }
    totals = {
        "open_violations": sum(v["open_violations"] for v in by_project.values()),
        "open_complaints": sum(v["open_complaints"] for v in by_project.values()),
        "permits_expiring": sum(v["permits_expiring"] for v in by_project.values()),
        "total_violations": sum(v["total_violations"] for v in by_project.values()),
        "total_complaints": sum(v["total_complaints"] for v in by_project.values()),
        "total_permits": sum(v["total_permits"] for v in by_project.values()),
        "permits_no_expiry": sum(v["permits_no_expiry"] for v in by_project.values()),
        "projects_without_score": sum(1 for pid in project_ids if pid not in scored),
        "projects_total": len(project_ids),
    }
    return {"by_project": by_project, "totals": totals}


@api_router.post(
    "/projects",
    response_model=ProjectResponse,
    # require_approved gates SPEND. require_company_access gates TENANCY:
    # the stamp below takes admin.get("company_id") verbatim, so without
    # this a company-less admin mints a project owned by nobody, and every
    # worker who later taps in at its gate inherits that None.
    dependencies=[Depends(require_approved), Depends(require_company_access)],
)
async def create_project(project_data: ProjectCreate, admin = Depends(get_admin_user)):
    project_dict = project_data.model_dump()

    # MR.5+ — third instance of Pydantic-default-not-protecting-writes.
    # ProjectCreate.gates: Optional[List[ProjectGate]] = None carries
    # through model_dump() as {"gates": None}. ProjectResponse below
    # rejects None for its non-Optional List type. Forward-init now
    # so the Mongo insert is shape-stable AND the response succeeds.
    # (Same fix shape as the historical filing_reps credentials lift,
    # which was removed in MR.14 commit 4b along with the field.)
    _lift_project_list_defaults(project_dict)

    if project_dict.get("address") and (not project_dict.get("name") or project_dict["name"] == project_dict["address"]):
        project_dict["name"] = project_dict["address"]
    if project_dict.get("name") and not project_dict.get("address"):
        project_dict["address"] = project_dict.get("location") or project_dict["name"]
    
    now = datetime.now(timezone.utc)
    project_dict["created_at"] = now
    project_dict["updated_at"] = now
    project_dict["nfc_tags"] = []
    project_dict["dropbox_enabled"] = False
    project_dict["dropbox_folder"] = None
    project_dict["is_deleted"] = False

    # ── ROSTER IDS ARE MINTED HERE TOO ──────────────────────────────────────
    #
    # `_merge_trade_assignments` had ONE call site — the project UPDATE path —
    # so a roster supplied at CREATION was stored exactly as the client sent
    # it, with no server-minted `id` on any row. Everything downstream depends
    # on that id and degrades silently without it:
    #
    #   get_daily_headcount skips any row with no id (`if not _rid: continue`),
    #   so `subcontractor_id` came back None on EVERY activity row — which is
    #   why the chip ranker fell back to the unfiltered catalogue, and why the
    #   crew-level identity the operator ruled never took effect. It was
    #   implemented; it was one call site short of the door.
    #
    # The "every" was the tell: a key mismatch nulls SOME rows, only an empty
    # roster_ids nulls all of them.
    #
    # The SAME function as the update path, so a roster cannot mean two
    # different things depending on how it arrived. Existing projects still
    # carry id-less rows — nothing here rewrites stored data; see the backfill
    # question in the PR.
    project_dict["trade_assignments"] = _merge_trade_assignments(
        [], project_dict.get("trade_assignments") or [],
    )
    
    # Auto-inject company_id from admin. require_company_access on the route
    # has already refused a falsy one, so this can no longer stamp None - but
    # the assert states the invariant at the stamp rather than only at the
    # decorator, because that is where a future edit would break it.
    # NOT an assert: python -O strips those, and an AssertionError here would
    # surface as a 500 rather than the 403 this is. Defence in depth that
    # behaves correctly on its own.
    _company_id = admin.get("company_id")
    if not _company_id:
        raise HTTPException(
            status_code=403,
            detail=(
                "Your account is not linked to a company yet. "
                "Complete onboarding before creating projects."
            ),
        )
    project_dict["company_id"] = _company_id
    project_dict["company_name"] = admin.get("company_name")
    project_dict["admin_id"] = admin.get("id")
    
    # ── DOB: Auto-resolve NYC BIN + canonical address from address ──
    # Field rename note (2026-04-27 step 9.1): nyc_bbl → bbl. The
    # legacy nyc_bbl key is no longer written by new project creation.
    # Existing prod docs still carry nyc_bbl; the step 9.1 migration
    # copies their values into the new `bbl` field. Cleanup commit
    # drops the legacy nyc_bbl reads after deploy verification.
    project_dict["nyc_bin"] = None
    project_dict["bbl"] = None
    project_dict["bbl_source"] = None
    project_dict["bbl_last_synced"] = None
    # MR.14 (commit 2a) — default True. v1 monitoring product treats
    # DOB-signal polling as the core feature; new projects opt IN by
    # default. Operator F7: existing False docs are NOT migrated
    # (customer choice). Override below from BIN-resolution logic
    # only flips it when bin_result explicitly says so.
    project_dict["track_dob_status"] = True

    address_for_bin = project_dict.get("address") or project_dict.get("location") or ""
    if address_for_bin:
        bin_result = await fetch_nyc_bin_from_address(address_for_bin)
        project_dict["nyc_bin"] = bin_result["nyc_bin"]
        if bin_result.get("bbl"):
            project_dict["bbl"] = bin_result["bbl"]
            project_dict["bbl_source"] = "address_lookup_at_creation"
            project_dict["bbl_last_synced"] = now
        # MR.14 (commit 2a) — do NOT downgrade track_dob_status from
        # the True default just because no BIN resolved at creation
        # time. Address-fallback in _query_dob_apis still produces
        # signals for non-BIN projects, and the nightly scan already
        # filters projects with neither bin nor address. The
        # bin_result hint is informational only for new schema.
        if bin_result.get("track_dob_status") is True:
            project_dict["track_dob_status"] = True

        # Upgrade the project's address to GeoSearch's canonical form
        # (e.g. "852 E 176" → "852 EAST 176 STREET, Bronx, NY, USA").
        # This is critical: downstream address-based DOB Socrata
        # queries LIKE-match DOB's canonical street names, which use
        # "EAST" not "E" and include "STREET". Without this upgrade,
        # "852 E 176" finds nothing even though the building has
        # permits filed under "852 EAST 176 STREET".
        normalized = bin_result.get("normalized_address")
        if normalized and normalized != project_dict.get("address"):
            logger.info(
                f"Normalized address '{project_dict.get('address')}' → "
                f"'{normalized}'"
            )
            project_dict["address"] = normalized

        if bin_result["nyc_bin"]:
            logger.info(
                f"Auto-resolved BIN {bin_result['nyc_bin']} for project "
                f"'{project_dict.get('name')}'"
            )
        else:
            logger.info(
                f"No real BIN resolved for project "
                f"'{project_dict.get('name')}' — address-based DOB "
                f"lookups will be used."
            )
    # ── END DOB ──

    # ── Project classification ──
    suggested = classify_project(
        project_dict.get("building_stories"),
        project_dict.get("footprint_sqft"),
        project_dict.get("has_full_demolition", False),
        project_dict.get("demolition_stories"),
        project_dict.get("building_height"),
    )
    project_dict["suggested_class"] = suggested
    override = project_dict.get("project_class")
    if override and override in VALID_PROJECT_CLASSES:
        project_dict["project_class"] = override
        # A HUMAN DECIDED IT. That is an assessment even when it agrees with
        # nothing, which is why it is recorded separately from the class: a
        # stored "regular" that a person chose and a stored "regular" that fell
        # out of an empty form are the same string, and only this field can
        # ever tell them apart afterwards.
        project_dict["classification_source"] = "admin"
        if override != suggested:
            await db.compliance_alerts.insert_one({
                "type": "classification_override",
                "project_name": project_dict.get("name"),
                "suggested_class": suggested,
                "override_class": override,
                "admin_id": str(admin.get("_id", admin.get("id", ""))),
                "timestamp": now,
                "resolved": False,
            })
    else:
        # May be None — classify_project returns None when there was nothing to
        # classify, and storing that is the whole point. get_required_logbooks
        # fails CLOSED on it rather than quietly dropping two required logs.
        project_dict["project_class"] = suggested
        project_dict["classification_source"] = "measured" if suggested else "unassessed"

    project_dict["required_logbooks"] = get_required_logbooks(project_dict["project_class"], project_dict)
    # ── END classification ──

    result = await db.projects.insert_one(project_dict)
    project_dict["id"] = str(result.inserted_id)

    await audit_log("project_create", str(admin.get("_id", admin.get("id", ""))), "project", str(result.inserted_id), {
        "name": project_dict.get("name"), "address": project_dict.get("address"),
        "project_class": project_dict.get("project_class"), "suggested_class": suggested,
    })

    # V2.3 Commit 4 — async pre-warm of peer_stats_cache. Fire-and-
    # forget; the HTTP response returns immediately while the
    # compute runs in the background. First risk-score recompute
    # on this project becomes a cache-hit instead of paying the
    # 500ms-2s synchronous compute cost. Spawn is wrapped in
    # try/except so a bug here can never fail project creation.
    try:
        asyncio.create_task(
            _stat_engine.prewarm_peer_stats(db, result.inserted_id),
            name=f"prewarm_peer_stats:{result.inserted_id}",
        )
    except Exception as _e:
        logger.warning(
            f"[create_project] prewarm task spawn failed for "
            f"{result.inserted_id}: {_e!r}",
        )

    # Defense in depth — the lift above already covered model_dump's
    # None values, but if any code path between then and now wrote
    # None back into project_dict (e.g. a future migration helper),
    # we'd still want the response to construct cleanly.
    _lift_project_list_defaults(project_dict)
    # Safe here specifically because the insert above has already happened —
    # this only ever decorates the outgoing response, never the stored document.
    _lift_project_retention_view(project_dict)

    return ProjectResponse(**project_dict)

@api_router.get("/projects/pending-deletion")
async def list_pending_deletion_projects(owner = Depends(get_owner_user)):
    """Review list of projects an admin has marked for deletion.

    MUST stay registered ABOVE GET /projects/{project_id} — FastAPI matches
    in registration order, so declaring it after would make the literal
    "pending-deletion" bind to {project_id} and 404.

    THIS LISTED EVERY COMPANY'S. `get_owner_user` is role == "owner", which is
    what EVERY self-serve signup receives — a company owner, i.e. a customer —
    so any customer could read the ids of every other company's projects
    awaiting purge. Together with the hard-delete gate below, that was the
    discovery half of a working cross-tenant purge.

    SCOPED THE SAME WAY GET /projects IS: the platform operator sees across
    companies, everyone else sees their own. `is_platform_operator` is the
    PURE FUNCTION, deliberately — `require_platform_operator` is in shadow
    mode until PLATFORM_GATES_ENFORCED is set, so a gate written on the
    dependency would log, allow, and pass its tests while protecting nothing.
    """
    _q = {
        "marked_for_deletion": True,
        "is_deleted": {"$ne": True},
    }
    if not is_platform_operator(owner):
        _company = get_user_company_id(owner)
        if _company:
            _q["company_id"] = _company
        else:
            # ABSENCE IS NOT AUTHORIZATION. `company_id: None` would MATCH
            # every project that has no company — an orphan row is not "mine".
            # `_id: None` matches nothing, which is the honest answer for a
            # caller who owns nothing.
            _q["_id"] = None
    projects = await db.projects.find(_q).sort("marked_at", -1).to_list(500)

    _today = eastern_today()
    items = []
    for p in projects:
        pid = str(p["_id"])
        # The SAME function the purge endpoint calls, deliberately — this
        # screen must never offer a button that the server will refuse, nor
        # grey one out that the server would have allowed. One definition,
        # asked twice.
        _refusal = retention_refusal(p, today=_today)
        items.append({
            "id": pid,
            "name": p.get("name"),
            "address": p.get("address"),
            "company_id": p.get("company_id"),
            "nyc_bin": p.get("nyc_bin"),
            "marked_by": p.get("marked_by"),
            "marked_at": p.get("marked_at"),
            # Rough scale indicator so the owner sees what a purge destroys.
            "dob_logs_count": await db.dob_logs.count_documents({"project_id": pid}),
            "checkins_count": await db.checkins.count_documents({"project_id": pid}),
            # ── What the law still wants, beside the scale of the loss.
            # The counts above tell the owner HOW MUCH a purge destroys; these
            # tell them whether they are ALLOWED to, and until when.
            "job_completion_date": p.get("job_completion_date"),
            "job_completion_co_number": p.get("job_completion_co_number"),
            "completion_source": p.get("completion_source"),
            **legal_hold_view(p),
            # The other named statement about whether these records may go.
            # Carried here so the owner about to purge sees WHO said this
            # project was never completed, rather than just an unblocked
            # button — this attestation is the only reason the button is live.
            **no_completion_attestation_view(p),
            # Computed here as everywhere else, stored nowhere.
            "purge_eligible_at": purge_eligible_at(p),
            "purge_blocked": _refusal is not None,
            "purge_block_reason": _refusal,
        })
    return {"items": items, "count": len(items)}


@api_router.get("/projects/{project_id}", response_model=ProjectResponse)
async def get_project(project_id: str, current_user = Depends(get_current_user)):
    # Marked-for-deletion projects read as 404 to everyone here; the owner
    # reviews them through GET /projects/pending-deletion instead.
    project = await db.projects.find_one({
        "_id": to_query_id(project_id), **ACTIVE_PROJECT_FILTER,
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")

    # MR.5+ — defensive lift for legacy docs that have list fields
    # set to None. Three production docs in this state today (the
    # operator's failed create attempts before this commit landed);
    # without this lift, GET on any of them 500s.
    _lift_project_list_defaults(project)
    # Computed for this response only. `project` here is a find_one result and
    # is not written back, so nothing persists.
    _lift_project_retention_view(project)

    return ProjectResponse(**serialize_id(project))

@api_router.put("/projects/{project_id}", response_model=ProjectResponse, dependencies=[Depends(require_approved), Depends(require_project_access)])
async def update_project(project_id: str, project_data: ProjectUpdate, admin = Depends(get_admin_user)):
    update_data = {k: v for k, v in project_data.model_dump().items() if v is not None}
    update_data["updated_at"] = datetime.now(timezone.utc)

    # ── COMPLETION AND LEGAL HOLD ───────────────────────────────────────────
    #
    # Both go through THIS path rather than getting endpoints of their own, so
    # they inherit the gates already on it: require_approved, require_project_access,
    # and get_admin_user (role in {"admin", "owner"}).
    #
    # Everything here either validates or STAMPS. `completed_by`, `legal_hold_by`
    # and the timestamps are taken from the authenticated caller and are not
    # accepted from the request body — ProjectUpdate does not declare them, so a
    # client that sends them has them dropped rather than honoured.
    _admin_id = str(admin.get("_id", admin.get("id", "")))
    _now = update_data["updated_at"]
    _touches_retention = (
        "job_completion_date" in update_data
        or "job_completion_co_number" in update_data
        or "legal_hold" in update_data
        or "legal_hold_reason" in update_data
        or "no_completion_attested" in update_data
        or "no_completion_reason" in update_data
    )
    _prev = None
    if _touches_retention:
        _prev = await db.projects.find_one({"_id": to_query_id(project_id)})
        if not _prev:
            raise HTTPException(status_code=404, detail="Project not found")

    # ── THE COMPLETION IS A PAIR: NUMBER AND DATE, OR NOTHING ───────────────
    #
    # Refused BEFORE either half is looked at, so a partial entry is never
    # stored and never half-validated. A claim about a legal event carries the
    # event's identifier: a date on its own says some job finished some day and
    # attributes it to no document, and that lone date is what starts — and
    # seven years later ends — the retention period.
    #
    # This also holds for a CORRECTION. Moving the date without restating the
    # number would leave a certificate number describing a day it no longer
    # describes, which is precisely the "a wrong number lives here forever"
    # failure the pair is meant to prevent. Re-attesting both is one extra
    # field on a form an admin fills out approximately once per project.
    _has_date = "job_completion_date" in update_data
    _has_co = "job_completion_co_number" in update_data
    if _has_date != _has_co:
        raise HTTPException(
            status_code=400,
            detail="Recording a job completion requires BOTH the certificate "
                   "of occupancy number and the completion date. Neither is "
                   "accepted without the other.",
        )

    if _has_date:
        _raw = update_data["job_completion_date"]
        _parsed = parse_calendar_date(_raw)
        if _parsed is None:
            # Strict, and NOT coerced. A coerced date is an invented one, and
            # this value decides when records may be destroyed.
            raise HTTPException(
                status_code=400,
                detail="job_completion_date must be a real calendar date "
                       "formatted YYYY-MM-DD",
            )
        # A completion is an event that ALREADY HAPPENED. A future date is a
        # typo or a schedule, and either way it would move the seven-year
        # period out with it — the one direction that loses records.
        # eastern_date() because NYC DOB compliance runs on the New York
        # calendar day; the UTC day is already tomorrow here from 20:00 EDT.
        if _raw > eastern_date(_now):
            raise HTTPException(
                status_code=400,
                detail="job_completion_date cannot be in the future",
            )
        # ATTESTED, NOT FORMAT-CHECKED. co_number_problem() rejects only what
        # is not storable text — blank, oversized, or multi-line. It invents no
        # pattern, because a guessed pattern's failure mode is an admin holding
        # a real certificate that the app will not accept. The full argument,
        # including why this repo is in no position to rule on the format, is
        # in lib/project_retention.py.
        _co_problem = co_number_problem(update_data["job_completion_co_number"])
        if _co_problem:
            raise HTTPException(status_code=400, detail=_co_problem)
        update_data["job_completion_co_number"] = normalize_co_number(
            update_data["job_completion_co_number"])
        # Provenance beside the value — the bbl_source pattern. STAMPED, never
        # taken from the body: nothing here verified the number against DOB, so
        # the only honest source is the attestation that it is.
        update_data["completion_source"] = DEFAULT_COMPLETION_SOURCE
        update_data["completed_by"] = _admin_id

    if "no_completion_attested" in update_data:
        # `False` reaches here because it is not None — same mechanism that
        # makes the legal hold liftable. An attestation must be withdrawable:
        # it is a statement of fact, and facts get corrected.
        if update_data["no_completion_attested"]:
            # NEVER ALONGSIDE A COMPLETION, in the same request or already on
            # record. This is the direction that would look like it releases
            # the brake, so it is refused rather than reconciled. (It would not
            # in fact release anything — retention_refusal reads the recorded
            # completion first — but a document asserting both "completed
            # 2024-03-01" and "never completed" is a record nobody can rely on,
            # and the reader who most needs to rely on it is deciding whether
            # to destroy the project's history.)
            if _has_date:
                raise HTTPException(
                    status_code=400,
                    detail="A job completion and a never-completed attestation "
                           "cannot be recorded in the same request.",
                )
            if has_recorded_completion(_prev or {}):
                raise HTTPException(
                    status_code=400,
                    detail="This project has a recorded job completion, so it "
                           "cannot be attested as never completed. Correct the "
                           "completion record instead.",
                )
            _nc_reason = (update_data.get("no_completion_reason")
                          or (_prev or {}).get("no_completion_reason") or "").strip()
            if not _nc_reason:
                # This attestation is the ONLY thing that unblocks the purge of
                # a project with no completion on record, so it is the sentence
                # a regulator would be shown to explain why the records are
                # gone. An unexplained one cannot serve that purpose, and a
                # bare boolean is indistinguishable from a mis-click.
                raise HTTPException(
                    status_code=400,
                    detail="Attesting that a project was never completed "
                           "requires a reason — it is what permits the "
                           "permanent deletion of its records.",
                )
            update_data["no_completion_reason"] = _nc_reason
            update_data["no_completion_attested_by"] = _admin_id
            update_data["no_completion_attested_at"] = _now
        else:
            # WITHDRAWN. Who attested and why is deliberately left in place,
            # exactly as the hold's placement fields survive its lifting — the
            # trail of a statement that was made and retracted is the part
            # worth keeping. Only the withdrawal is added.
            update_data.pop("no_completion_reason", None)
            update_data["no_completion_withdrawn_by"] = _admin_id
            update_data["no_completion_withdrawn_at"] = _now
    elif ("no_completion_reason" in update_data
          and not (_prev or {}).get("no_completion_attested")):
        raise HTTPException(
            status_code=400,
            detail="no_completion_reason needs an active attestation to describe",
        )

    # A RECORDED COMPLETION SUPERSEDES A STANDING "NEVER COMPLETED".
    #
    # Applied HERE, after the attestation branch above, so the two can never
    # write the same keys in one request — an earlier draft cleared the flag
    # inside the completion branch and then fell into the withdrawal branch,
    # stamping the document as both superseded and withdrawn by the same call.
    #
    # This is the safe direction to resolve the contradiction in: the
    # attestation refused nothing, the completion starts a seven-year refusal,
    # so retiring the former can only ever TIGHTEN the brake. The reverse
    # direction is refused outright above rather than reconciled here.
    # `_has_date` implies the pair, and the pair implies the request did not
    # also carry an attestation — that combination raised.
    if _has_date and (_prev or {}).get("no_completion_attested"):
        update_data["no_completion_attested"] = False
        update_data["no_completion_superseded_by"] = _admin_id
        update_data["no_completion_superseded_at"] = _now

    if "legal_hold" in update_data:
        # `False` reaches here because it is not None — that is what makes a
        # hold LIFTABLE through this path. If this ever becomes an
        # Optional[bool] filtered like the rest, a hold could be placed and
        # never removed.
        if update_data["legal_hold"]:
            _reason = (update_data.get("legal_hold_reason")
                       or (_prev or {}).get("legal_hold_reason") or "").strip()
            if not _reason:
                # A hold never expires on its own, so an unexplained one is
                # indistinguishable from a mistake that nothing will ever
                # correct. The reason is the only thing that lets a later
                # reader decide whether it still applies.
                raise HTTPException(
                    status_code=400,
                    detail="A legal hold requires a reason",
                )
            update_data["legal_hold_reason"] = _reason
            update_data["legal_hold_by"] = _admin_id
            update_data["legal_hold_at"] = _now
        else:
            # The placement fields are deliberately LEFT IN PLACE — who placed
            # a hold and why survives its lifting, or the trail ends exactly
            # where it matters. Only the release is added.
            update_data.pop("legal_hold_reason", None)
            update_data["legal_hold_released_by"] = _admin_id
            update_data["legal_hold_released_at"] = _now
    elif "legal_hold_reason" in update_data and not (_prev or {}).get("legal_hold"):
        raise HTTPException(
            status_code=400,
            detail="legal_hold_reason needs an active legal hold to describe",
        )

    # Roster rows carry a STABLE, SERVER-MINTED id. The $set below replaces
    # the whole array, so the ids cannot come from the client — they are
    # re-derived here by matching each submitted row against the stored
    # roster. Note the dict-comprehension above only filters None at the TOP
    # level, so an `id: None` inside a row would still reach Mongo and then
    # 500 the ProjectResponse read-back; _merge_trade_assignments emits
    # strings only.
    if update_data.get("trade_assignments") is not None:
        _existing_project = await db.projects.find_one({"_id": to_query_id(project_id)})
        update_data["trade_assignments"] = _merge_trade_assignments(
            (_existing_project or {}).get("trade_assignments") or [],
            update_data["trade_assignments"],
        )

    # Normalize email list to lowercase if present
    if "report_email_list" in update_data and update_data["report_email_list"] is not None:
        update_data["report_email_list"] = [e.lower() for e in update_data["report_email_list"]]

    # Re-classify when classification-relevant fields change
    classification_fields = {"building_stories", "building_height", "footprint_sqft", "has_full_demolition", "demolition_stories", "project_class"}
    if classification_fields & update_data.keys():
        existing = await db.projects.find_one({"_id": to_query_id(project_id)})
        if existing:
            merged = {**existing, **update_data}
            suggested = classify_project(
                merged.get("building_stories"),
                merged.get("footprint_sqft"),
                merged.get("has_full_demolition", False),
                merged.get("demolition_stories"),
                merged.get("building_height"),
            )
            update_data["suggested_class"] = suggested
            override = update_data.get("project_class")
            if override and override in VALID_PROJECT_CLASSES:
                update_data["project_class"] = override
                update_data["classification_source"] = "admin"
            else:
                update_data["project_class"] = suggested
                update_data["classification_source"] = (
                    "measured" if suggested else "unassessed")
            # `merged` carries the STORED class, not the one just decided, so
            # the resolved set is computed from the new class explicitly.
            update_data["required_logbooks"] = get_required_logbooks(
                update_data["project_class"], {**merged, **update_data})

    result = await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {"$set": update_data}
    )

    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Project not found")

    # ── AUDIT, WITH THE PREVIOUS VALUE ──────────────────────────────────────
    # These two fields decide whether a purge is refused, so a change to either
    # is a compliance-relevant mutation. The PREVIOUS value is recorded beside
    # the new one because the interesting question afterwards is never "what is
    # it now" — the document says that — but "what was it before, and who moved
    # it". Shortening a retention period is the abuse this makes visible.
    #
    # Written AFTER the $set commits, so an audit entry never claims a change
    # that did not land. audit_log swallows its own failures, so this cannot
    # fail the update.
    if _touches_retention:
        _before = _prev or {}
        if "job_completion_date" in update_data:
            await audit_log(
                "project_completion_set", _admin_id, "project", project_id,
                {
                    "job_completion_date": update_data["job_completion_date"],
                    # THE NUMBER IS AUDITED LIKE THE DATE, and for a sharper
                    # reason. Nothing in this app verifies a CO number, so the
                    # audit trail is the ONLY record of what was claimed and by
                    # whom. If a real certificate later contradicts this entry,
                    # this is the only place that says what the entry was
                    # before someone corrected it.
                    "job_completion_co_number":
                        update_data.get("job_completion_co_number"),
                    "completion_source": update_data.get("completion_source"),
                    "previous": {
                        "job_completion_date": _before.get("job_completion_date"),
                        "job_completion_co_number":
                            _before.get("job_completion_co_number"),
                        "completion_source": _before.get("completion_source"),
                        "completed_by": _before.get("completed_by"),
                    },
                },
            )
        if "no_completion_attested" in update_data:
            # THE MOST CONSEQUENTIAL ENTRY IN THIS BLOCK. A standing attestation
            # is the single thing that lets a project with no completion on
            # record be permanently destroyed, so who stated it, why, and what
            # the document said beforehand is the whole account of why the
            # records are gone.
            await audit_log(
                "project_no_completion_attestation", _admin_id, "project",
                project_id,
                {
                    "no_completion_attested":
                        bool(update_data["no_completion_attested"]),
                    "no_completion_reason": update_data.get("no_completion_reason")
                                            or _before.get("no_completion_reason"),
                    # Set when a recorded completion retired the attestation,
                    # so the trail distinguishes a withdrawal from a supersede.
                    "superseded_by_completion":
                        update_data.get("job_completion_date"),
                    "previous": {
                        "no_completion_attested":
                            bool(_before.get("no_completion_attested")),
                        "no_completion_reason":
                            _before.get("no_completion_reason"),
                        "no_completion_attested_by":
                            _before.get("no_completion_attested_by"),
                    },
                },
            )
        if "legal_hold" in update_data:
            await audit_log(
                "project_legal_hold", _admin_id, "project", project_id,
                {
                    "legal_hold": bool(update_data["legal_hold"]),
                    "legal_hold_reason": update_data.get("legal_hold_reason")
                                         or _before.get("legal_hold_reason"),
                    "previous": {
                        "legal_hold": bool(_before.get("legal_hold")),
                        "legal_hold_reason": _before.get("legal_hold_reason"),
                        "legal_hold_by": _before.get("legal_hold_by"),
                    },
                },
            )

    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    # MR.5+ — same defensive lift as get_project. Update endpoints
    # don't currently set list fields to None (the existing code
    # filters None values out via dict-comprehension before $set),
    # but the read-back can still pull a legacy doc whose pre-update
    # state had None lists.
    _lift_project_list_defaults(project)
    # Read-back only. The $set above is already committed and does not include
    # this key — the eligibility date is never a stored field.
    _lift_project_retention_view(project)
    return ProjectResponse(**serialize_id(project))

@api_router.get("/projects/{project_id}/required-logbooks")
async def get_project_required_logbooks(project_id: str, current_user = Depends(get_current_user)):
    """Return the required logbook types for this project based on its classification."""
    project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")
    # NO "regular" DEFAULT HERE EITHER. A missing class is reported as missing;
    # substituting the non-major class at the read is the same silent default
    # classify_project stopped making, one layer out.
    project_class = project.get("project_class")
    required = get_required_logbooks(project_class, project)
    return {
        "project_id": project_id,
        "project_class": project_class,
        # The client says so on screen. Two logs appear that would not appear
        # on an assessed non-major project, and a CP who is not told why reads
        # them as the app being wrong about his site.
        "classification_assessed": classification_assessed(project),
        "required_logbooks": required,
        # The toggles, so the screen makes one request rather than two and can
        # never show a control whose state disagrees with the set beside it.
        "activations": logbook_activations(project),
    }

@api_router.delete("/projects/{project_id}", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def delete_project(project_id: str, admin = Depends(get_admin_user)):
    """TIER 1 — mark for deletion (admin or owner).

    Replaces the previous hybrid handler, which soft-deleted the project but
    HARD-deleted its dob_logs — destroying the compliance history while only
    hiding the project. Nothing is removed now: the project is flagged, hidden
    from every admin surface, and its NFC tags are deactivated so no new
    check-ins land against a closed site. The owner reviews marked projects
    via GET /projects/pending-deletion and is the only role that can purge.
    """
    project = await db.projects.find_one({
        "_id": to_query_id(project_id), **ACTIVE_PROJECT_FILTER,
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    company_id = get_user_company_id(admin)
    if company_id and project.get("company_id") != company_id:
        raise HTTPException(status_code=403, detail="Access denied to this project")

    now = datetime.now(timezone.utc)
    admin_id = str(admin.get("_id", admin.get("id", "")))

    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {"$set": {
            "marked_for_deletion": True,
            "marked_by": admin_id,
            "marked_at": now,
            "updated_at": now,
        }},
    )

    # Deactivate the site's NFC tags. register_and_checkin matches
    # status:"active", so a tap now fails fast with "Invalid check-in point"
    # instead of passing the tag check and dying on the project lookup.
    tag_result = await db.nfc_tags.update_many(
        {"project_id": project_id},
        {"$set": {"status": "project_closed", "updated_at": now}},
    )

    await audit_log("project_mark_delete", admin_id, "project", project_id, {
        "name": project.get("name"),
        "nfc_tags_deactivated": getattr(tag_result, "modified_count", 0) or 0,
    })

    return {
        "message": "Project marked for deletion",
        "marked_for_deletion": True,
        "nfc_tags_deactivated": getattr(tag_result, "modified_count", 0) or 0,
    }


# ── TIER 2: owner-only hard delete ───────────────────────────────────────
#
# Collections whose documents are OWNED by a project and keyed by a plain
# `project_id` field. Sourced from the cascade audit. Anything not on this
# list is either company/user-scoped (companies, users, whatsapp_config,
# notification_preferences, feature_flags) or needs special handling below
# (workers, document_page_index).
_PROJECT_OWNED_COLLECTIONS = [
    "dob_logs", "checkins", "logbooks", "logbook_entries", "nfc_tags",
    "project_files", "daily_logs", "daily_log_photos", "checklists",
    "checklist_assignments", "checklist_completions", "compliance_alerts",
    "notifications", "signature_events", "material_requests", "report_emails",
    "reports", "cs_registrations", "safety_staff_registrations",
    "document_annotations", "upload_attempts_log", "project_models",
    "project_schedules", "sequence_graph", "risk_scores", "daily_panels",
    "prediction_models", "prediction_validation_ledger", "eligibility_shadow",
    "permit_renewals", "renewal_alert_sent", "site_devices", "subcontractors",
    # Gate-side failure diagnostics (POST /checkin/gate-failure). Project-scoped
    # rows, so they go when the project goes.
    "gate_failures",
    # card_audit family — the runtime flow is route-shadowed, but rows may
    # exist from any earlier exercise of it, so sweep them.
    "worker_enrollments", "sign_ins", "daily_signatures", "pending_enrollments",
    "card_fraud_flags", "card_audit_log", "unexpected_ndef_hosts",
    # whatsapp — PROJECT-scoped only. whatsapp_config is COMPANY-scoped and
    # is deliberately absent.
    "whatsapp_groups", "whatsapp_checklists", "whatsapp_link_codes",
    "whatsapp_messages", "whatsapp_send_log", "whatsapp_conversation_state",
    "whatsapp_voice_events", "whatsapp_audio_probe", "whatsapp_webhook_log",
]


async def _r2_delete_keys(client, bucket: str, keys) -> int:
    """Delete an EXPLICIT list of keys. Prefer this over `_r2_delete_prefix`
    wherever the keys are known, and read that function's warning for why.

    Uses DeleteObjects in batches of 1000 (the API cap) rather than one call
    per key, and reports per-key errors R2 returns in the batch response. Same
    best-effort contract as the prefix sweep: returns a count, never raises.
    """
    keys = [k for k in (keys or []) if k]
    if not (client and bucket and keys):
        return 0
    deleted = 0
    for i in range(0, len(keys), 1000):
        chunk = [{"Key": k} for k in keys[i:i + 1000]]
        try:
            resp = await asyncio.to_thread(
                client.delete_objects, Bucket=bucket,
                Delete={"Objects": chunk, "Quiet": False},
            )
            deleted += len(resp.get("Deleted") or [])
            for err in (resp.get("Errors") or []):
                logger.error(
                    f"[r2] delete_objects refused key={err.get('Key')!r} "
                    f"code={err.get('Code')!r} msg={err.get('Message')!r}"
                )
        except Exception as e:
            logger.error(
                f"[r2] delete_objects failed bucket={bucket} "
                f"n={len(chunk)} first={chunk[0]['Key']!r}: {e!r}"
            )
    return deleted


async def _r2_delete_prefix(client, bucket: str, prefix: str) -> int:
    """Delete every object under `prefix`. Paginates past the 1000-key
    ListObjectsV2 cap. Best-effort: returns the count deleted and never raises,
    so one storage hiccup can't abort the purge.

    ┌───────────────────────────────────────────────────────────────────────┐
    │ THIS RETURNS 0 AGAINST THIS DEPLOYMENT NO MATTER WHAT IS IN THE       │
    │ BUCKET. USE `_r2_delete_keys` WHENEVER THE KEYS ARE KNOWN.            │
    └───────────────────────────────────────────────────────────────────────┘

    `R2_ENDPOINT_URL` ENDS IN THE BUCKET NAME —
    `https://<account>.r2.cloudflarestorage.com/blueview` — and boto3 appends
    `Bucket=` on top of it. Object operations survive that (the doubled segment
    just becomes part of the key namespace, consistently, for every write and
    every read), but a LISTING becomes `GET /blueview/blueview?list-type=2`,
    which is a GET on an object named `blueview`. R2 answers it **HTTP 200 with
    the bucket's CORS configuration**, and botocore parses `<CORSConfiguration>`
    as a `ListBucketResult`: no `Contents`, no `KeyCount`, no error, ever.

    Measured against production 2026-09-04, one token, one client:

        head_object("plans/<proj>/<file>/page_1.jpg")   -> 3,353,739 bytes
        list_objects_v2(Prefix="plans/")                -> 200, CORS document
        list_buckets()                                  -> []

    and with the bucket stripped from the endpoint, same credential:

        list_buckets()                                  -> ['blueview']
        head_object("plans/<proj>/<file>/page_1.jpg")   -> 404

    IT IS NOT A PERMISSION. The token is Admin Read & Write and can list; the
    first diagnosis of this said otherwise and was wrong. The last line above is
    the one that matters: the real keys carry the doubled segment, so
    `R2_ENDPOINT_URL` is LOAD-BEARING EXACTLY AS IT IS. Stripping the bucket
    from it would 404 every object ever written. Do not "fix" it.

    So this function paged an empty result, deleted nothing, returned a truthful
    `0` and never raised. `hard_delete_project` had never removed a single plan
    page image; the count it reports as `r2_objects_deleted` counted only the
    keys taken from DB rows above it.

    KEPT, NOT DELETED, because it is the only thing that could ever reach a
    derivative no row names — and because the prefix it is given would need the
    doubled segment too. Treat a 0 from this function as UNKNOWN.
    """
    if not (client and bucket and prefix):
        return 0
    deleted = 0
    token = None
    try:
        while True:
            kwargs = {"Bucket": bucket, "Prefix": prefix, "MaxKeys": 1000}
            if token:
                kwargs["ContinuationToken"] = token
            page = await asyncio.to_thread(client.list_objects_v2, **kwargs)
            for obj in (page.get("Contents") or []):
                key = obj.get("Key")
                if not key:
                    continue
                try:
                    await asyncio.to_thread(
                        client.delete_object, Bucket=bucket, Key=key,
                    )
                    deleted += 1
                except Exception as e:
                    logger.error(f"[hard_delete] R2 delete failed key={key}: {e!r}")
            if page.get("IsTruncated"):
                token = page.get("NextContinuationToken")
                if not token:
                    break
            else:
                break
    except Exception as e:
        logger.error(
            f"[hard_delete] R2 prefix sweep failed bucket={bucket} "
            f"prefix={prefix}: {e!r}"
        )
    return deleted


@api_router.delete("/projects/{project_id}/hard-delete", dependencies=[Depends(require_approved), Depends(require_platform_operator)])
async def hard_delete_project(project_id: str, owner = Depends(get_owner_user)):
    """TIER 2 — irreversible purge. OWNER ONLY.

    Physically removes the project and every document, storage object and
    config key it owns. Uses delete_many/delete_one exclusively — never
    drop(). Storage and scheduler cleanup are best-effort so a single
    failure cannot leave the database half-purged.
    """
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # ── TENANT GATE ON AN IRREVERSIBLE PURGE ────────────────────────────────
    # This compared NOTHING. The decorator's require_platform_operator is in
    # SHADOW MODE while PLATFORM_GATES_ENFORCED is unset — it logs the
    # non-operator and lets them through — so the only live gate was
    # `get_owner_user`, i.e. role == "owner", which is what every self-serve
    # signup receives. Any customer owner could physically purge any company's
    # project, and GET /projects/pending-deletion handed them the ids.
    #
    # is_platform_operator is the PURE FUNCTION on purpose. Writing this on
    # the dependency would inherit the shadow and gate nothing, while passing
    # its own tests. That is asserted with the flag unset.
    #
    # Not narrowed to operator-only: that would lock the real operator out
    # until is_platform_operator is bootstrapped on their account, which is
    # the very hazard shadow mode exists to avoid. Operator purges anything;
    # anyone else is confined to their own company.
    if not is_platform_operator(owner):
        _caller_company = str(get_user_company_id(owner) or "")
        if not _caller_company or _caller_company != str(project.get("company_id") or ""):
            raise HTTPException(
                status_code=403, detail="Not authorized to delete this project",
            )

    # ── RETENTION BRAKE ─────────────────────────────────────────────────────
    #
    # BEFORE ANY DESTRUCTION, AND THAT PLACEMENT IS THE POINT. Everything below
    # this line is irreversible and some of it is unrecoverable even in
    # principle: the R2 sweeps delete by PREFIX, and those objects have no
    # database rows to rebuild from. A refusal that arrived after the sweep
    # would be a refusal that had already destroyed the photographs.
    #
    # This is the one code path in the product that can destroy statutory
    # records today, and until now nothing asked whether the law still required
    # them. ESRA BB2024-007 §V.4 wants seven years past job completion; the
    # compliance doc records the gap as "Not computable. No job-completion date
    # exists." It exists now, and this is what it is for.
    #
    # NO OPERATOR EXEMPTION, unlike the tenant gate above. Cross-tenant scoping
    # protects a customer from another customer, so the platform operator is
    # reasonably outside it. Retention is owed to a regulator, and the operator
    # is not the party it is owed to.
    #
    # 409, not 403: the caller is authorised and the request is well-formed.
    # The PROJECT's state is what refuses, and it is a state that changes —
    # a hold gets lifted, a retention period elapses. A 403 would read as "you
    # personally may not", which would send an owner looking for a bigger role.
    _refusal = retention_refusal(project, today=eastern_today())
    if _refusal:
        logger.warning(
            "[hard_delete] REFUSED project %s (%s) for owner %s: %s",
            project_id, project.get("name"), owner.get("email"), _refusal,
        )
        raise HTTPException(status_code=409, detail=_refusal)

    owner_id = str(owner.get("_id", owner.get("id", "")))
    company_id = str(project.get("company_id") or "")
    report: Dict[str, Any] = {}

    # ── LANDMINE 2: document_page_index is keyed by file_id, NOT project_id.
    # Collect the project's file ids BEFORE deleting project_files, or the
    # index rows orphan silently with nothing left to find them by.
    file_docs = await db.project_files.find(
        {"project_id": project_id}, {"_id": 1, "r2_key": 1},
    ).to_list(5000)
    file_ids = [str(f["_id"]) for f in file_docs]
    # ── LANDMINE 2b: THE SAME LESSON, ONE LEVEL DOWN, AND IT WAS MISSED.
    # The comment above says to collect the file ids before deleting
    # project_files. The index rows are the only record of the PAGE IMAGE KEYS
    # in exactly the same way, and this deleted them and then relied on a
    # prefix sweep that returns 0 here whatever the bucket holds (see
    # `_r2_delete_prefix`) — so every
    # hard-deleted project left its rendered pages in the bucket with nothing
    # left in the database naming them. Collect, then delete.
    page_keys = []
    if file_ids:
        try:
            async for _row in db.document_page_index.find(
                {"file_id": {"$in": file_ids}},
                {"page_jpeg_r2_key": 1, "page_thumb_r2_key": 1, "page_base_r2_key": 1},
            ):
                for _f in ("page_jpeg_r2_key", "page_thumb_r2_key", "page_base_r2_key"):
                    if _row.get(_f):
                        page_keys.append(_row[_f])
        except Exception as e:
            logger.error(f"[hard_delete] could not read page keys: {e!r}")
        idx_res = await db.document_page_index.delete_many(
            {"file_id": {"$in": file_ids}},
        )
        report["document_page_index"] = getattr(idx_res, "deleted_count", 0) or 0

    # ── R2: per-file keys recorded on project_files rows.
    r2_deleted = 0
    if _r2_client and R2_BUCKET_NAME:
        for f in file_docs:
            key = f.get("r2_key")
            if not key:
                continue
            try:
                await asyncio.to_thread(
                    _r2_client.delete_object, Bucket=R2_BUCKET_NAME, Key=key,
                )
                r2_deleted += 1
            except Exception as e:
                logger.error(f"[hard_delete] R2 delete failed key={key}: {e!r}")

    # ── R2: the page images, BY KEY, from the rows collected above. Against
    # this deployment this is the only half that removes anything.
    r2_deleted += await _r2_delete_keys(_r2_client, R2_BUCKET_NAME, page_keys)

    # ── R2: prefix sweeps for artefacts NO DB ROW NAMES. A supplement, not the
    # mechanism — every one of these returns 0 here regardless of what is in
    # the bucket, because the endpoint carries the bucket name and a listing
    # against it comes back as a CORS document. See `_r2_delete_prefix`.
    r2_deleted += await _r2_delete_prefix(
        _r2_client, R2_BUCKET_NAME, f"plans/{project_id}/",
    )
    # Enhanced + thumbnail derivatives of daily-log photos. Unconditional (not
    # nested under the company sweep below) so an orphaned or company-less
    # project still has its derivatives purged.
    r2_deleted += await _r2_delete_prefix(
        _r2_client, R2_BUCKET_NAME, f"logbook-photos/{project_id}/",
    )
    if company_id:
        r2_deleted += await _r2_delete_prefix(
            _r2_client, R2_BUCKET_NAME, f"{company_id}/{project_id}/",
        )
    try:
        from card_audit import _r2_client as _ca_client, CARD_AUDIT_BUCKET_NAME, CARD_AUDIT_KEY_PREFIX
        if _ca_client and CARD_AUDIT_BUCKET_NAME:
            r2_deleted += await _r2_delete_prefix(
                _ca_client, CARD_AUDIT_BUCKET_NAME,
                f"{CARD_AUDIT_KEY_PREFIX}{project_id}/",
            )
    except Exception as e:
        logger.warning(f"[hard_delete] card-audit bucket sweep skipped: {e!r}")
    report["r2_objects_deleted"] = r2_deleted

    # ── Project-owned collections.
    for coll in _PROJECT_OWNED_COLLECTIONS:
        try:
            res = await db[coll].delete_many({"project_id": project_id})
            n = getattr(res, "deleted_count", 0) or 0
            if n:
                report[coll] = n
        except Exception as e:
            logger.error(f"[hard_delete] {coll} delete failed: {e!r}")

    # ── LANDMINE 1: workers are NOT project-scoped — one worker spans many
    # projects. Their check-ins are already gone above; here we only detach
    # this project's orientation entry and KEEP the worker document.
    worker_res = await db.workers.update_many(
        {"safety_orientations.project_id": project_id},
        {"$pull": {"safety_orientations": {"project_id": project_id}}},
    )
    report["workers_orientations_pulled"] = (
        getattr(worker_res, "modified_count", 0) or 0
    )

    # ── User references.
    user_res = await db.users.update_many(
        {"assigned_projects": project_id},
        {"$pull": {"assigned_projects": project_id}},
    )
    report["users_unassigned"] = getattr(user_res, "modified_count", 0) or 0

    # ── system_config: four per-project key families, two with unbounded
    # suffixes. Anchored on the escaped id so a project whose id is a
    # substring of another's is never caught.
    pid_re = re.escape(project_id)
    try:
        cfg_res = await db.system_config.delete_many({"$or": [
            {"key": f"dob_sync_last:{project_id}"},
            {"key": {"$regex": f"^initial_scan_done:.*:{pid_re}$"}},
            {"key": {"$regex": f"^dob_alert_sent:{pid_re}:"}},
            {"key": {"$regex": f"^daily_report:{pid_re}:"}},
        ]})
        report["system_config"] = getattr(cfg_res, "deleted_count", 0) or 0
    except Exception as e:
        logger.error(f"[hard_delete] system_config sweep failed: {e!r}")

    # ── Background work. NOTE: prediction_resolution_check:{pid} and
    # predict_inspection:{pid}:* are asyncio TASK names (asyncio.create_task
    # name=...), not APScheduler jobs — they are transient and die on their
    # own. Cancel any still in flight; there is nothing persistent to remove.
    cancelled = 0
    try:
        for task in asyncio.all_tasks():
            nm = task.get_name() or ""
            if nm.startswith(f"prediction_resolution_check:{project_id}") or \
               nm.startswith(f"predict_inspection:{project_id}:"):
                task.cancel()
                cancelled += 1
    except Exception as e:
        logger.warning(f"[hard_delete] task cancel sweep failed: {e!r}")
    report["tasks_cancelled"] = cancelled

    # ── The project's own audit trail (owner's explicit choice: nothing
    # remains). Done before the final audit_log write so this purge itself
    # is still recorded.
    try:
        al_res = await db.audit_logs.delete_many({
            "resource_type": "project", "resource_id": project_id,
        })
        report["audit_logs"] = getattr(al_res, "deleted_count", 0) or 0
    except Exception as e:
        logger.error(f"[hard_delete] audit_logs sweep failed: {e!r}")

    # ── The project document itself.
    await db.projects.delete_one({"_id": to_query_id(project_id)})

    logger.warning(
        f"🔥 HARD DELETE project {project_id} ({project.get('name')}) "
        f"by owner {owner_id}: {report}"
    )
    await audit_log("project_hard_delete", owner_id, "project_purged", project_id, {
        "name": project.get("name"), "deleted": report,
    })

    return {
        "message": "Project permanently deleted",
        "project_id": project_id,
        "deleted": report,
    }

# ==================== PROJECT NFC TAGS ====================

@api_router.get("/projects/{project_id}/nfc-tags")
async def get_project_nfc_tags(project_id: str, current_user = Depends(get_current_user), _proj = Depends(require_project_access)):
    project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    rows = project.get("nfc_tags", []) or []

    # PROVISIONAL IS READ FROM THE COLLECTION, NOT COPIED INTO THE ARRAY.
    #
    # The project's nfc_tags array is a denormalized {tag_id, location} list.
    # Writing the flag into it too would make two copies of one fact, and this
    # repo already carries two live bugs of exactly that shape (see followups
    # "the re-assign path leaves the displayed names stale" and
    # "checklist_title is frozen at creation") - in both, one copy got updated
    # and the one the screen renders did not.
    #
    # So the array keeps saying WHICH tags, the collection keeps saying WHAT
    # THEY ARE, and this join is the only place the two meet. A flag that
    # changes - and this one is meant to, once an admin programs a chip with
    # the id - must not be stored where a later write can miss it.
    flags = {}
    try:
        async for t in db.nfc_tags.find(
            {"project_id": project_id, "is_deleted": {"$ne": True}},
            {"tag_id": 1, "provisional": 1, "created_by_role": 1},
        ):
            flags[t.get("tag_id")] = {
                # Absent means False. Every tag that predates the CP bootstrap
                # path was programmed onto a chip by an admin, so the default
                # has to be "real", not "unknown".
                "provisional": bool(t.get("provisional")),
                "created_by_role": t.get("created_by_role") or "admin",
            }
    except Exception as e:
        # The list is what the admin screen renders; a flag lookup failing must
        # not blank it. Degrade to the array alone.
        logger.warning("nfc-tags flag join failed for project %s: %r", project_id, e)
        return rows

    return [
        {**row, **flags.get(row.get("tag_id"), {})}
        if isinstance(row, dict) else row
        for row in rows
    ]

@api_router.post("/projects/{project_id}/nfc-tags", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def add_nfc_tag_to_project(project_id: str, tag_data: NfcTagCreate, admin = Depends(get_admin_user)):
    # Get project and verify company access
    project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    
    company_id = get_user_company_id(admin)
    if company_id and project.get("company_id") != company_id:
        raise HTTPException(status_code=403, detail="Access denied to this project")
    
    # Location is optional; fall back to a sensible default so the UI never shows a blank label
    if not (tag_data.location_description or "").strip():
        tag_data.location_description = "Check-In Point"

    now = datetime.now(timezone.utc)

    # Check if this tag_id exists ANYWHERE (including soft-deleted) due to unique index on tag_id
    existing_tag = await db.nfc_tags.find_one({"tag_id": tag_data.tag_id})

    if existing_tag:
        # ── A LIVE TAG ON ANOTHER PROJECT IS REFUSED ────────────────────────
        #
        # This used to SILENTLY MOVE it: $pull the tag off the other project's
        # nfc_tags array, then repoint the row here. The company check above is
        # on the TARGET project only, so an admin of company A could take a
        # check-in point off company B's project document by typing its id —
        # a cross-tenant edit reachable from a typo, with nothing but an
        # info-level log line to show for it.
        #
        # NOTHING LEGITIMATE DEPENDED ON IT. A tag physically moved between
        # sites is a real case and it is still served, explicitly and in the
        # right order: DELETE it from the old project (which requires access to
        # THAT project — the check the implicit move skipped), then add it
        # here, where it arrives on the is_deleted path below. Moving a tag
        # must be an action someone takes, not a side effect of entering an id.
        #
        # THE PROJECT IS NOT NAMED. "already registered to 250 Water Street"
        # would leak another tenant's project name to whoever guessed an id,
        # which is a smaller version of the hole being closed. The id is the
        # caller's own input, so echoing that discloses nothing.
        _blocked = (
            not existing_tag.get("is_deleted")
            and existing_tag.get("status") == "active"
            and str(existing_tag.get("project_id") or "") != str(project_id)
        )
        if _blocked:
            logger.warning(
                "NFC tag %s is active on another project; refusing to reassign "
                "to %s", tag_data.tag_id, project_id,
            )
            raise HTTPException(
                status_code=409,
                detail=(
                    f"Check-in point ID '{tag_data.tag_id}' is already in use. "
                    "Remove it from the project it is registered to before "
                    "adding it here."
                ),
            )

        # ── THE THREE STATES THAT MUST STILL PASS ───────────────────────────
        #
        # The predicate above is narrow on purpose. Refusing on the mere
        # EXISTENCE of a row would be a worse trap than the bug it closes,
        # because the unique index on tag_id means an insert can never be the
        # fallback — this branch is the ONLY way any of these three re-register:
        #
        #   1. SAME PROJECT, ACTIVE. Re-registering a tag already here is how
        #      location_description gets renamed. Idempotent, and the only
        #      rename path there is.
        #
        #   2. is_deleted. An admin removed it from a project; DELETE soft-
        #      deletes rather than dropping the row, precisely so the id can
        #      come back. This is the second half of the delete-then-add move
        #      described above, so refusing it would break the very flow
        #      offered as the remedy.
        #
        #   3. status == "project_closed". DO NOT "TIDY" THIS INTO THE
        #      is_deleted CHECK. It is a DIFFERENT field set by a DIFFERENT
        #      path: marking a project for deletion sweeps every one of its
        #      tags to status "project_closed" and leaves is_deleted alone
        #      (see mark_project_for_deletion). Such a tag is not deleted and
        #      not active. Refuse it and a physical sticker from a closed site
        #      can NEVER be reused — the only release is DELETE, DELETE needs
        #      the old project_id, and that project is gone from every listing.
        #      That is a permanent dead end created by the fix, which is why
        #      the status check is written as `== "active"` and not as a
        #      truthiness test on is_deleted.
        #
        # THE $pull IS GONE ON PURPOSE, and it did run for case 3 before.
        # Reviving a "project_closed" tag used to also strip it from the old
        # project's nfc_tags ARRAY. That write is the cross-tenant edit this
        # whole change exists to stop, and keeping it "just for the tidy case"
        # would leave the hole open through a narrower door. Not pulling costs
        # one stale entry on a project that is marked for deletion — invisible
        # to every listing (ACTIVE_PROJECT_FILTER), reachable only from the
        # owner's pending-deletion review, and purged outright when the project
        # is hard-deleted. Nothing functional reads that array: the gate,
        # /info and register_and_checkin all query the nfc_tags COLLECTION,
        # which this update repoints correctly.
        #
        # Update the existing document in-place (avoids unique index conflict)
        await db.nfc_tags.update_one(
            {"_id": existing_tag["_id"]},
            {"$set": {
                "project_id": project_id,
                "location_description": tag_data.location_description,
                "updated_at": now,
                "admin_id": admin["id"],
                "company_id": project.get("company_id"),
                "status": "active",
                "is_deleted": False
            }}
        )
    else:
        # Brand new tag - safe to insert
        nfc_tag = {
            "tag_id": tag_data.tag_id,
            "project_id": project_id,
            "location_description": tag_data.location_description,
            "created_at": now,
            "updated_at": now,
            "admin_id": admin["id"],
            "company_id": project.get("company_id"),
            "status": "active",
            "is_deleted": False
        }
        await db.nfc_tags.insert_one(nfc_tag)
    
    # Also update project's nfc_tags array
    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {
            "$push": {"nfc_tags": {"tag_id": tag_data.tag_id, "location": tag_data.location_description}},
            "$set": {"updated_at": now}
        }
    )
    
    # Return success - frontend will refetch project data via fetchData()
    logger.info(f"NFC tag {tag_data.tag_id} registered to project {project_id}")
    return {
        "message": "NFC tag registered successfully",
        "tag_id": tag_data.tag_id,
    }

@api_router.delete("/projects/{project_id}/nfc-tags/{tag_id}", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def remove_nfc_tag_from_project(project_id: str, tag_id: str, admin = Depends(get_admin_user)):
    now = datetime.now(timezone.utc)
    
    # Soft delete from nfc_tags collection
    await db.nfc_tags.update_one(
        {"tag_id": tag_id, "project_id": project_id},
        {"$set": {"is_deleted": True, "deleted_at": now, "updated_at": now}}
    )
    
    # Remove from project's nfc_tags array
    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {
            "$pull": {"nfc_tags": {"tag_id": tag_id}},
            "$set": {"updated_at": now}
        }
    )
    return {"message": "NFC tag removed successfully"}


# ==================== CP EMERGENCY CHECK-IN POINT ====================
#
# A SEPARATE SUB-RESOURCE, not a relaxed get_admin_user on /nfc-tags above.
# The two paths differ in WHO may call them, WHERE the id comes from, and WHAT
# the row means. Folding a second authorization model and a second id policy
# into one handler is the shape that produced the silent-reassignment bug this
# file just finished removing.
#
# THE FAILURE IT EXISTS FOR. A tag is destroyed mid-shift and no admin is
# reachable. Today that is a site with no compliant check-in: /info 404s
# without an ACTIVE row, so tap and scan both fail. The men still work -
# nothing turns anyone away - but the 3301.11 orientation record for that
# shift is simply missing, and it cannot be reconstructed afterwards. That is
# a compliance loss, not an inconvenience, and the CP is the one person
# standing there.

# NFC hardware UIDs are HEX. "qr-" contains a letter and a separator that hex
# cannot produce, so a minted id can never collide with a chip's UID no matter
# how many bytes that chip reports. This is what lets the CP path skip
# accepting an id from the caller entirely.
CP_CHECKIN_POINT_PREFIX = "qr-"


@api_router.post(
    "/projects/{project_id}/checkin-points/bootstrap",
    dependencies=[Depends(require_approved), Depends(require_project_access)],
)
async def bootstrap_checkin_point(
    project_id: str,
    data: dict = None,
    current_user = Depends(get_current_user),
):
    """Mint a check-in point when a project has none. Admin OR CP.

    THE CALLER NEVER SUPPLIES AN ID. The server mints it, which is stronger
    than validating input: a CP who cannot type an id cannot typo one, cannot
    squat one, and cannot reach the cross-project collision branch that
    add_nfc_tag_to_project now refuses.
    """
    project = await db.projects.find_one({
        "_id": to_query_id(project_id), **ACTIVE_PROJECT_FILTER,
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    role = current_user.get("role")
    if role not in ("admin", "owner", "cp"):
        raise HTTPException(status_code=403, detail="Not authorized")

    # -- THE RULE IS "ZERO ACTIVE TAGS", NOT "NO EXISTING ROWS" -------------
    #
    # Those are different questions and the difference is load-bearing.
    # nfc_tags rows outlive their usefulness in two states that are NOT
    # active: is_deleted (an admin removed the tag) and status
    # "project_closed" (the project was marked for deletion, which sweeps
    # every one of its tags).
    #
    # A REOPENED SITE IS THE CASE. A project that was closed and restored
    # still carries its old rows at status "project_closed" - a gate nobody
    # can check in through, because /info and register_and_checkin both match
    # status "active". Asking "no existing rows" would see those and refuse,
    # leaving the CP exactly as stuck as if the rule did not exist, on a site
    # that genuinely has no working gate. Asking "zero ACTIVE tags" correctly
    # mints a new one and leaves the dead rows alone.
    #
    # The query is the gate's own, deliberately: if a tag would let a worker
    # check in, it counts here.
    active_existing = await db.nfc_tags.count_documents({
        "project_id": project_id,
        "status": "active",
        "is_deleted": {"$ne": True},
    })
    if active_existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "This project already has a check-in point. Use the existing "
                "one, or ask an admin to add another."
            ),
        )

    location = str((data or {}).get("location_description") or "").strip()
    if not location:
        location = "Check-In Point"

    now = datetime.now(timezone.utc)

    # Retried rather than trusted: tag_id carries a unique index, and a silent
    # duplicate-key error here would surface at a gate rather than at this call.
    import secrets as _secrets

    tag_id = None
    for _ in range(5):
        candidate = f"{CP_CHECKIN_POINT_PREFIX}{_secrets.token_hex(6)}"
        if not await db.nfc_tags.find_one({"tag_id": candidate}):
            tag_id = candidate
            break
    if not tag_id:
        raise HTTPException(
            status_code=503,
            detail="Could not allocate a check-in point ID. Try again.",
        )

    # PROVISIONAL, and the flag is the point. A minted gate is QR-ONLY: no chip
    # in the field carries this id, so it can only be scanned off a screen or a
    # printout. A printed code is permanently shareable (see followups.md), so
    # without a marker the emergency fix silently becomes the permanent state
    # and nobody is told. The flag is what an admin sees, and what tells them a
    # physical tag still needs programming with THIS id.
    await db.nfc_tags.insert_one({
        "tag_id": tag_id,
        "project_id": project_id,
        "location_description": location,
        "created_at": now,
        "updated_at": now,
        "admin_id": current_user.get("id"),
        "created_by": current_user.get("id"),
        "created_by_role": role,
        "provisional": True,
        "company_id": project.get("company_id"),
        "status": "active",
        "is_deleted": False,
    })

    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {
            "$push": {"nfc_tags": {"tag_id": tag_id, "location": location}},
            "$set": {"updated_at": now},
        },
    )

    logger.info(
        "Provisional check-in point %s minted on project %s by %s (role=%s)",
        tag_id, project_id, current_user.get("id"), role,
    )
    return {
        "message": "Check-in point created",
        "tag_id": tag_id,
        "location_description": location,
        "provisional": True,
    }


@api_router.delete(
    "/projects/{project_id}/checkin-points/{tag_id}",
    dependencies=[Depends(require_approved), Depends(require_project_access)],
)
async def remove_cp_checkin_point(
    project_id: str,
    tag_id: str,
    current_user = Depends(get_current_user),
):
    """Let a CP remove a gate THEY created, while it is still only a mistake.

    A rule that lets someone act in an emergency and then traps them with the
    result is not a safety property. bootstrap refuses once a gate exists, so
    without this a CP who mints one by accident cannot undo it and cannot try
    again - the emergency power becomes a one-shot they have already spent.

    TWO CONDITIONS, and the second is where it stops being theirs to undo.
    """
    tag = await db.nfc_tags.find_one({
        "tag_id": tag_id, "project_id": project_id, "is_deleted": {"$ne": True},
    })
    if not tag:
        raise HTTPException(status_code=404, detail="Check-in point not found")

    role = current_user.get("role")
    if role not in ("admin", "owner", "cp"):
        raise HTTPException(status_code=403, detail="Not authorized")

    if role == "cp":
        # 1. IT MUST BE THEIRS. A CP undoing their own mistake is not the same
        #    power as a CP removing the gate an admin programmed, and this
        #    endpoint grants only the first.
        if tag.get("created_by_role") != "cp":
            raise HTTPException(
                status_code=403,
                detail="Only an admin can remove this check-in point.",
            )
        # 2. ONCE A MAN HAS TAPPED IN IT IS EVIDENCE. A check-in is a 3301.11
        #    record and it names this tag_id; the gate has to keep existing for
        #    that record to resolve. The same rule holds everywhere else a
        #    signed artifact exists, and it is not relaxed because this row was
        #    created under an emergency.
        used = await db.checkins.count_documents({
            "tag_id": tag_id, "project_id": project_id,
        })
        if used:
            raise HTTPException(
                status_code=409,
                detail=(
                    "This check-in point has check-ins against it and can no "
                    "longer be removed. Ask an admin."
                ),
            )

    now = datetime.now(timezone.utc)
    await db.nfc_tags.update_one(
        {"tag_id": tag_id, "project_id": project_id},
        {"$set": {"is_deleted": True, "deleted_at": now, "updated_at": now}},
    )
    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {
            "$pull": {"nfc_tags": {"tag_id": tag_id}},
            "$set": {"updated_at": now},
        },
    )
    return {"message": "Check-in point removed"}


@api_router.post(
    "/projects/{project_id}/checkin-points/{tag_id}/programmed",
    dependencies=[Depends(require_approved), Depends(require_project_access)],
)
async def mark_checkin_point_programmed(
    project_id: str,
    tag_id: str,
    admin = Depends(get_admin_user),
):
    """A physical tag now carries this gate's id. Clear the provisional flag.

    THIS IS THE ONLY THING THAT CLEARS IT, and that is the design.

    A provisional gate was minted in the field by a CP because the project had
    none. It is QR-only - no chip anywhere carries the id - and a printed QR is
    permanently shareable (followups.md). The flag says "no chip exists", so
    the only honest way to clear it is for a chip to start existing.

    NOTHING IS RE-REGISTERED. writeNfcTag takes an EXPLICIT id, so the admin
    programs a blank sticker with THIS gate's qr- id and the chip's own UID is
    never read and never stored. Same row, same tag_id, same project - every
    check-in already recorded against this gate stays attached to it, and no
    second gate appears. That is why this is a flag flip and not a migration.

    ORDERING, and only one direction is safe. The client writes the chip FIRST
    and calls this only after the write returns success:

      * write ok, this call fails  -> a programmed chip still marked
        provisional. The banner stays, the admin retries, and re-writing the
        same URL to the same chip is idempotent. Over-cautious, which is the
        correct way for this flag to fail.
      * this call first, write fails -> a gate marked "has a physical tag"
        with no chip anywhere. That is precisely the silent state the flag
        exists to prevent.

    So do not "improve" the client by flipping the flag optimistically for a
    snappier UI. The slow order is the safe one.

    ADMIN ONLY, deliberately. The marker exists FOR admins; letting the CP who
    minted the gate clear their own flag makes it self-certifying and it stops
    being evidence of anything.

    NO DISMISS ENDPOINT, and this is where one would naturally be added.
    Declined on the grounds, not the preference: if dismissal is the easy path
    it becomes the only path, and the flag stops meaning "no chip exists" and
    starts meaning "nobody clicked X" - which is the same as having no flag at
    all, with the added cost that everyone believes there is one. There is a
    legitimate case (a site that has genuinely decided the printed code IS the
    gate), so if this is ever revisited it must record WHO dismissed and WHEN,
    and read as ACKNOWLEDGED rather than resolved. It must not reuse this
    endpoint or this field.
    """
    tag = await db.nfc_tags.find_one({
        "tag_id": tag_id, "project_id": project_id, "is_deleted": {"$ne": True},
    })
    if not tag:
        raise HTTPException(status_code=404, detail="Check-in point not found")

    # NOTHING TO CLEAR IS NOT SUCCESS. A silent 200 here would let a client bug
    # - the wrong tag_id, a stale list - look exactly like a completed
    # programming run, and the banner would vanish for a gate nobody touched.
    if not tag.get("provisional"):
        raise HTTPException(
            status_code=409,
            detail="This check-in point is not provisional.",
        )

    now = datetime.now(timezone.utc)
    await db.nfc_tags.update_one(
        {"tag_id": tag_id, "project_id": project_id},
        {"$set": {
            "provisional": False,
            # KEPT, not deleted. "This gate was minted in the field and later
            # given a chip" is worth being able to read a year from now, and
            # dropping the fact to tidy the document destroys it.
            "provisional_cleared_by": admin.get("id"),
            "provisional_cleared_at": now,
            "updated_at": now,
        }},
    )

    logger.info(
        "Check-in point %s on project %s marked programmed by %s",
        tag_id, project_id, admin.get("id"),
    )
    return {
        "message": "Check-in point marked as programmed",
        "tag_id": tag_id,
        "provisional": False,
    }


# ==================== NFC TAG INFO (PUBLIC) ====================

@api_router.get("/nfc-tags/{tag_id}/info", response_model=NfcTagInfo)
async def get_nfc_tag_info(tag_id: str):
    """Public endpoint - no auth required. Used by workers scanning NFC tags."""
    tag = await db.nfc_tags.find_one({"tag_id": tag_id, "status": "active", "is_deleted": {"$ne": True}})
    if not tag:
        raise HTTPException(status_code=404, detail="NFC tag not found or inactive")
    
    # Get project info
    project = await db.projects.find_one({"_id": to_query_id(tag["project_id"]), "is_deleted": {"$ne": True}})
    
    return NfcTagInfo(
        tag_id=tag["tag_id"],
        project_id=tag["project_id"],
        project_name=project.get("name", "Unknown Project") if project else "Unknown Project",
        location_description=tag.get("location_description", "Check-In Point"),
        company_name=project.get("company_name") if project else None
    )

@api_router.get("/checkin/{project_id}/{tag_id}/info")
async def get_checkin_info(project_id: str, tag_id: str):
    """Public endpoint - no auth required"""
    try:
        tag = await db.nfc_tags.find_one({
            "tag_id": tag_id,
            "project_id": project_id,
            "status": "active",
            "is_deleted": {"$ne": True}
        })

        if not tag:
            raise HTTPException(status_code=404, detail="Invalid check-in link")

        project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})

        if not project:
            raise HTTPException(status_code=404, detail="Project not found")

        # Per-project trade/company assignments. Admins set these via
        # PUT /api/projects/{id} with trade_assignments: [{trade, company}].
        # Sanitize + drop any rows missing either field. Soft-deleted rows
        # are dropped HERE, server-side: checkin.html builds its <select>
        # with the ARRAY INDEX as the option value and resolves the pick
        # back by index, so filtering on the client would desynchronize
        # that index. Filtering here keeps the two in step.
        raw_assignments = _active_assignments(project)
        assignments: List[Dict[str, str]] = []
        for row in raw_assignments:
            if not isinstance(row, dict):
                continue
            t = str(row.get("trade") or "").strip()
            c = str(row.get("company") or "").strip()
            if t and c:
                assignments.append({"trade": t, "company": c})

        return {
            "project_id": project_id,
            "project_name": project.get("name", "Unknown Project"),
            "location": tag.get("location_description", "Check-In Point"),
            "tag_id": tag_id,
            "company_name": project.get("company_name"),
            "trade_assignments": assignments,
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Server error: {str(e)}")

class OshaCardOcrResult(BaseModel):
    """The shape POST /checkin/upload-osha is allowed to return.

    IT HAD NO response_model AT ALL. The handler did

        extracted = json_mod.loads(text)
        return extracted

    so whatever the vision model emitted became the API's response verbatim —
    every key, every type, unvalidated. A model that answered `"name": "null"`
    put the four-character string on the wire, into `oshaData` on the gate
    page, into `osha_data` on the worker document, and onto filed compliance
    PDFs as a worker called "null". Worker 6a96c5ff6ee1b3362d156e6c carries it
    in two places today.

    TWO SEPARATE PROTECTIONS, AND THEY FIX DIFFERENT HALVES:

      * norm_ocr_str, applied below, turns the model's "null"/"N/A"/"" into a
        real None BEFORE it is ever seen. That is the defect.
      * this model pins the SHAPE — the fields, their types, and the fact that
        a key nobody declared does not reach a caller. That is the reason the
        defect could exist unnoticed: nothing anywhere stated what this
        endpoint returns, so nothing could be wrong.

    EVERY FIELD IS OPTIONAL AND NONE IS A REFUSAL. An unreadable field is the
    normal case at a jobsite gate — glare, a sleeve, a bent card — and a
    validation error here would turn a partly-read card into a 502 for a
    worker standing at a turnstile. The gate's rule is that a config or tooling
    problem never stops a man working; this model is written to that rule.

    `box_2d` IS IN THE MODEL BECAUSE THE PAGE USES IT. checkin.html crops the
    on-screen preview from it. A response_model silently drops undeclared keys,
    so omitting it here would have removed the crop with nothing to read in a
    diff — the shape of defect this model exists to prevent, introduced by the
    model itself.
    """
    name: Optional[str] = None
    sst_number: Optional[str] = None
    card_type: Optional[str] = None
    card_class: Optional[str] = None
    issued: Optional[str] = None
    expiration: Optional[str] = None
    card_dominant_color: Optional[str] = None
    card_color_confidence: Optional[str] = None
    card_color_conditions: List[str] = Field(default_factory=list)
    box_2d: Optional[List[float]] = None
    # Present only on the JSONDecodeError path, where the model returned
    # something that is not JSON and the raw text is the only evidence of what
    # went wrong. Never populated on a successful parse.
    raw_text: Optional[str] = None


def _osha_ocr_payload(data: dict) -> "OshaCardOcrResult":
    """The model's JSON, normalised once, at the boundary.

    Three consumers each ask "did the model read this field" in their own way —
    `name_ok` in build_worker_certifications, `ocrMissingCriticalFields` on the
    gate page, and the identity normalisers that dedupe workers. All three are
    correct against a real value and all three are wrong against the string
    "null". Fixing them one at a time leaves a fourth place to get it wrong.

    So it is fixed HERE, where the answer is parsed, and every reader downstream
    receives a real None. See lib/ocr_text.py.
    """
    conditions = data.get("card_color_conditions")
    if not isinstance(conditions, list):
        conditions = []
    # NORMALISED TOO, and this is not over-thoroughness: a list carrying the
    # string "null" would put it in front of the same tests as the scalars.
    conditions = [c for c in (norm_ocr_str(x) for x in conditions) if c]

    box = data.get("box_2d")
    coerced_box = None
    if isinstance(box, (list, tuple)) and len(box) == 4:
        try:
            coerced_box = [float(v) for v in box]
        except (TypeError, ValueError):
            # A box that will not parse is a display convenience that failed,
            # never a reason to fail the read. checkin.html already treats a
            # missing box as "show the uncropped frame".
            coerced_box = None

    return OshaCardOcrResult(
        name=norm_ocr_str(data.get("name")),
        sst_number=norm_ocr_str(data.get("sst_number")),
        card_type=norm_ocr_str(data.get("card_type")),
        card_class=norm_ocr_str(data.get("card_class")),
        issued=norm_ocr_str(data.get("issued")),
        expiration=norm_ocr_str(data.get("expiration")),
        card_dominant_color=norm_ocr_str(data.get("card_dominant_color")),
        card_color_confidence=norm_ocr_str(data.get("card_color_confidence")),
        card_color_conditions=conditions,
        box_2d=coerced_box,
        raw_text=norm_ocr_str(data.get("raw_text")),
    )


@api_router.post("/checkin/upload-osha", response_model=OshaCardOcrResult)
async def upload_osha_card(file_data: dict, request: Request):
    """OCR an OSHA/SST card photo using the Qwen2.5-VL vision model.

    PUBLIC endpoint — the NFC check-in flow is unauthenticated (workers
    tap a sticker, land on a public HTML page, no login). Previously
    this was gated behind `Depends(get_current_user)`, which made every
    photo upload 401 and surface as "Could not read card" in the UI.

    RATE LIMIT REMOVED (operator ruling), for the reason already recorded on
    register_and_checkin: "A config artifact must never stop a man from
    working." This carried a 30/min PER-IP cap while every worker at one gate
    — their own phones on the site WiFi, or one shared gate tablet — presents
    a SINGLE client IP. Thirteen workers at shift start, three retake attempts
    each, is thirty-nine requests from one address: the tail of the queue got a
    429, and a 429 here reads to the worker as "could not read your card".
    Dropped outright rather than tuned, same as the register path: no per-worker
    limit and no raised threshold were substituted.

    THE ABUSE CONCERN IS REAL AND IS NOT ADDRESSED HERE. This calls a paid
    vision API and is public. A per-IP cap was simply the wrong instrument — it
    priced a shared gate as a single abuser. If metering is wanted it belongs on
    the device fingerprint the gate already collects, or as a global circuit
    breaker on spend, neither of which can single out a busy turnstile.

    Mirrors the httpx+Together shape used by _qwen_visual_qa(). Input is
    a base64 image + content_type; output is the same {name, sst_number,
    issued, expiration, box_2d} JSON the frontend already consumes.
    """
    import httpx
    import json as json_mod

    if not QWEN_API_KEY:
        raise HTTPException(
            status_code=503,
            detail="Vision API not configured. Set QWEN_API_KEY.",
        )

    image_b64 = file_data.get("image")
    content_type = file_data.get("content_type", "image/jpeg")

    if not image_b64:
        raise HTTPException(status_code=400, detail="No image provided")

    # Strip data URL prefix if present
    if "," in image_b64:
        image_b64 = image_b64.split(",", 1)[1]

    image_url = f"data:{content_type};base64,{image_b64}"

    # ── COUNTED BEFORE THE CALL, NOT AFTER ──────────────────────────────────
    #
    # NOTHING RECORDED THAT THIS HAPPENED. This endpoint has called a paid
    # vision model on every card photo at every gate since launch, and "how
    # much did we spend on OCR last month" could not be answered from our own
    # data — only from a lower bound (checkins.card_ocr_attempts, which exists
    # only for workers who got PAST the card step), the Railway access log
    # (bounded by retention), or the provider's dashboard.
    #
    # NO LIMIT IS ATTACHED. Nothing below refuses, alerts or thresholds. A
    # ceiling reads a number and there is no number yet; this is the write that
    # makes one, and it is the same write a ceiling would need.
    #
    # BEFORE, because a call that errors after the provider has billed it is
    # still spend — and a provider outage arrives as a burst of exactly those.
    #
    # project_id is optional and may be absent on an older cached gate page;
    # those count under "unknown" rather than not at all.
    await record_vision_call(
        db,
        endpoint=VISION_UPLOAD_OSHA,
        project_id=(str(file_data.get("project_id") or "").strip() or None),
    )

    extraction_prompt = (
        "Extract the following from this SST/OSHA safety training card image. "
        "Return ONLY valid JSON, no markdown:\n"
        "{\"name\": \"full name on card\", "
        "\"sst_number\": \"the ID number or card number shown on the card\", "
        "\"card_type\": \"OSHA or SST — which kind of card this is\", "
        "\"card_class\": \"the exact class or level printed on the card: "
        "for SST one of FULL, LIMITED, SUPERVISOR, TEMPORARY; "
        "for OSHA one of 10, 30. "
        "CRITICAL: SST cards also print the COURSE HOURS (e.g. '40 hours', "
        "'62 hours', '10-hr', '30-hr') — those are the training DURATION, NOT the "
        "class. NEVER return an hours value as card_class. The SST class is always "
        "a WORD: SUPERVISOR, LIMITED, FULL, or TEMPORARY. If only hours are visible "
        "and no class word, set card_class to null\", "
        "\"issued\": \"issued date if visible\", "
        "\"expiration\": \"expiration date if visible\", "
        # COLOUR IS ASKED FOR, AND THE MAP IS NOT IN THE PROMPT. No SST class
        # names, no card-type names, no colour->class table: a mapping here
        # would let the model work backwards (read a class, then report the
        # colour that justifies it), it would be a rule no test can assert
        # against, and it would make the model the thing that decides the
        # class. The table lives in Python, which is what makes "colour
        # proposes, never asserts" enforceable rather than aspirational.
        "\"card_dominant_color\": \"the dominant background colour of the CARD "
        "STOCK itself - not the lanyard, sleeve, hand, or background behind it. "
        "One of: WHITE, BLUE, GREEN, PURPLE, RED, YELLOW, ORANGE, GREY, OTHER. "
        "If the card is inside a tinted or reflective sleeve, if the lighting "
        "has an obvious colour cast, if glare covers much of the card, or if "
        "you are not confident, return null. Do NOT infer the colour from any "
        "words printed on the card\", "
        "\"card_color_confidence\": \"high, medium or low - how sure you are of "
        "card_dominant_color given glare, shade, colour cast and sleeve. null "
        "when card_dominant_color is null\", "
        "\"card_color_conditions\": \"array of any of GLARE, SHADE, COLOR_CAST, "
        "SLEEVE, PARTIAL_CARD that could be distorting the colour; [] if none\", "
        "\"box_2d\": [ymin, xmin, ymax, xmax]}\n"
        "If a field is not visible or you are not certain, set it to null — "
        "do NOT guess the class. 'box_2d' should be the normalized coordinates "
        "(0-1000) tightly framing the card. Return the JSON object only."
    )

    text = ""
    try:
        async with ServerHttpClient(timeout=60.0) as client_http:
            resp = await client_http.post(
                f"{QWEN_API_BASE}/chat/completions",
                headers={
                    "Authorization": f"Bearer {QWEN_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": QWEN_MODEL,
                    "max_tokens": 500,
                    "temperature": 0,
                    "messages": [{
                        "role": "user",
                        "content": [
                            {"type": "image_url",
                             "image_url": {"url": image_url}},
                            {"type": "text", "text": extraction_prompt},
                        ],
                    }],
                },
            )
            if resp.status_code != 200:
                # UA + IP on the line: the client reports this same failure as
                # `card_ocr_http_failed`, but a vision-provider outage should be
                # answerable from the server's own logs without correlating.
                logger.error(
                    f"Qwen vision error {resp.status_code}: {resp.text[:300]} "
                    f"[ip={request.client.host if request.client else 'unknown'} "
                    f"ua={request.headers.get('user-agent', '')[:200]}]"
                )
                raise HTTPException(
                    status_code=502,
                    detail=f"Vision API error: {resp.status_code}",
                )

            result = resp.json()
            raw_text = result["choices"][0]["message"]["content"]

        # Parse JSON from response
        text = (raw_text or "").strip()
        if text.startswith("```"):
            text = text.split("\n", 1)[1].rsplit("```", 1)[0]

        extracted = json_mod.loads(text)
        # NOT `return extracted`. See _osha_ocr_payload and lib/ocr_text.py:
        # the model's own answer for "I could not read this" is sometimes the
        # STRING "null", and every presence test between here and a filed PDF
        # reads that as a value.
        if not isinstance(extracted, dict):
            # A JSON array or scalar parses fine and is not a card reading.
            # Same disposition as unparseable text: nothing was read.
            return _osha_ocr_payload({"raw_text": text})
        return _osha_ocr_payload(extracted)

    except json_mod.JSONDecodeError:
        return _osha_ocr_payload({"raw_text": text})
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"OSHA OCR error: {str(e)}")
        raise HTTPException(
            status_code=500,
            detail=f"OCR processing failed: {str(e)}",
        )

# ══ GATE FAILURE TELEMETRY ══════════════════════════════════════════════════
#
# WHY: two workers failed at the card step on 588 Thomas and there was no record
# anywhere of why. `card_ocr_attempts` / `card_ocr_failure_reason` already exist
# but are frozen onto the CHECK-IN ROW by register_and_checkin — so they only
# ever describe workers who got PAST the card step. The population that most
# needs explaining is precisely the population that wrote nothing down.
#
# This is the sink for that. It records that a gate step failed, on which
# project, on what device, and of what kind. It is diagnostics, not evidence:
# nothing reads it to make a decision about a worker.
#
# NO PII AND NO IMAGE, enforced by construction — the handler reads a fixed set
# of keys off the body and ignores everything else, so a future client that
# starts sending a name cannot leak one into this collection by accident. IP and
# User-Agent are taken from the REQUEST HEADERS, never from the body: the client
# is not trusted to describe itself, and this is the same presence evidence
# register_and_checkin already captures.
GATE_FAILURE_KINDS = {
    "card_file_read_failed",
    "card_image_decode_failed",
    "card_handler_crashed",
    "card_ocr_http_failed",
    "selfie_file_read_failed",
    "selfie_image_decode_failed",
    "selfie_handler_crashed",
}

# A LIMITER HERE IS SAFE, AND ON upload-osha IT WAS NOT. The distinction is not
# a preference, it is what the endpoint sits in front of: upload-osha is IN the
# worker's path — a 429 there is a man not working — while this endpoint is
# fire-and-forget from a handler that has already decided what to show him.
# Dropping a log line costs a diagnostic, never a shift. Sized well above a
# shift-start burst (13 workers x several failures each) so it only engages
# against something that is not a gate.
gate_failure_rate_limiter = RateLimiter(max_requests=120, window_seconds=60)


@api_router.post("/checkin/gate-failure", status_code=204)
async def record_gate_failure(data: dict, request: Request):
    """PUBLIC, fire-and-forget sink for a gate-side failure. Always 204.

    ALWAYS 204, INCLUDING WHEN IT DROPS THE EVENT. The caller is a
    navigator.sendBeacon (or keepalive fetch) that cannot read a response and
    will never retry; a 4xx would only surface as console noise on a worker's
    phone at a turnstile. Nothing here is allowed to fail loudly, and nothing
    here is allowed to be slow — it is one bounded insert.

    Same-origin by construction (checkin.html builds the URL from
    window.location.origin), which is what lets sendBeacon post JSON at all: a
    cross-origin beacon with Content-Type application/json would need a
    preflight, and sendBeacon cannot preflight.
    """
    client_ip = request.client.host if request.client else "unknown"
    if not gate_failure_rate_limiter.is_allowed(client_ip):
        return Response(status_code=204)

    try:
        raw_kind = str(data.get("kind") or "").strip()[:80]
        # An unrecognised kind is KEPT, not dropped — a client sending something
        # this server has not heard of is itself worth seeing — but it is
        # normalised so the `kind` field keeps a bounded vocabulary and a typo
        # cannot fragment a week of events across near-identical spellings.
        kind = raw_kind if raw_kind in GATE_FAILURE_KINDS else "unknown"

        project_id = data.get("project_id") or None
        project_name = None
        company_id = None
        if project_id:
            # Resolved server-side so the row is queryable per project and gets
            # swept by project teardown. A failure to resolve is not a failure
            # to record: the event is still worth having without the name.
            try:
                project = await db.projects.find_one(
                    {"_id": to_query_id(project_id), "is_deleted": {"$ne": True}},
                    {"name": 1, "company_id": 1},
                )
                if project:
                    project_name = project.get("name")
                    company_id = project.get("company_id")
            except Exception:
                pass

        try:
            ocr_attempts = int(data.get("ocr_attempts"))
        except (TypeError, ValueError):
            ocr_attempts = None

        lang = str(data.get("lang") or "").strip().lower()
        if lang not in ("en", "es"):
            lang = None

        await db.gate_failures.insert_one({
            "kind": kind,
            # Only set when the client sent something off-vocabulary, so the
            # normalisation above is never silent.
            "kind_raw": raw_kind if kind == "unknown" and raw_kind else None,
            "detail": str(data.get("detail") or "")[:300] or None,
            "project_id": project_id,
            "project_name": project_name,
            "company_id": company_id,
            "tag_id": str(data.get("tag_id") or "")[:120] or None,
            "ocr_attempts": ocr_attempts,
            "lang": lang,
            "fingerprint_id": str(data.get("fingerprint_id") or "")[:120] or None,
            "source": str(data.get("source") or "")[:60] or None,
            # From the headers, not the body — see the block comment above.
            "source_ip": client_ip,
            "user_agent": request.headers.get("user-agent", "")[:400],
            "created_at": datetime.now(timezone.utc),
        })
    except Exception as e:
        # A telemetry write must never be able to become a gate incident. This
        # endpoint exists because failures went unrecorded; it would be its own
        # counter-example if it could raise into a worker's flow.
        logger.warning(f"gate_failure record dropped: {e!r}")

    return Response(status_code=204)


@api_router.get(
    "/projects/{project_id}/gate-failures",
    dependencies=[Depends(require_approved), Depends(require_project_access)],
)
async def list_gate_failures(
    project_id: str,
    limit: int = 100,
    current_user = Depends(get_current_user),
):
    """The read path, so "why did these two men fail yesterday" is answerable
    from the app rather than from a Mongo shell.

    Project-scoped by dependency (require_project_access), newest first.
    """
    limit = max(1, min(int(limit or 100), 500))
    rows = await db.gate_failures.find(
        {"project_id": project_id},
    ).sort("created_at", -1).limit(limit).to_list(limit)
    for r in rows:
        r["_id"] = str(r["_id"])
    return {"failures": rows, "count": len(rows)}


@api_router.get("/trades/vocabulary")
async def get_trade_vocabulary(current_user=Depends(get_current_user)):
    """The controlled trade list. ONE SOURCE OF TRUTH, and this is it.

    The list lived twice -- DEFAULT_TRADES here and TRADE_SUGGESTIONS in
    app/project/[id]/trades.jsx -- as twenty identical strings that validated
    nothing. The client now fetches instead of carrying a copy, and a test
    asserts no second copy exists.

    `deprecated` is returned SEPARATELY rather than merged: those labels stay
    valid on rows that already carry them and must never be re-spelled, but an
    admin picking a new trade should not be offered them. The client hides them
    from the picker and still renders a row that holds one as a normal
    vocabulary value.

    Not tenant-scoped -- it is a static list with no project or company in it --
    but authenticated, because nothing anonymous needs it. THE GATE DOES NOT
    CALL THIS. A worker's pick is validated against the project roster by
    _roster_key, and adding a vocabulary check there would be a new way to
    refuse a man at a turnstile.
    """
    return {
        "trades": list(TRADE_VOCABULARY),
        "deprecated": dict(DEPRECATED_TRADES),
    }


# ── GET /checkin/{project_id}/companies IS GONE ─────────────────────────
#
# It had NO CALLER. checkin.html reads the roster from
# /checkin/{project_id}/{tag_id}/info, which returns `trade_assignments:
# [{trade, company}]`; the deleted endpoint returned `[{name, trade}]` -- a
# different key for the company -- and injected a synthetic
# {"name": <main company>, "trade": "General Contractor"} row the gate never
# saw. Two shapes for one roster, one of them unreachable, already drifted.
#
# `let companies = []` in checkin.html was its only trace and is gone with it.
#
# The GATE_ROUTES set in test_company_less_tenancy.py listed this path; it has
# been removed there WITH A NOTE, because that set exists to stop someone
# quietly deleting a route workers depend on, and the note is what distinguishes
# this deletion from the thing the set guards against.


# ── worker_project_trades: a worker's trade + company, PER PROJECT ──────
#
# THE RULE (operator, final): a worker's trade and company belong to the
# {worker, project} PAIR, never to the worker alone. A framer on one job may
# be a painter for a different sub on the next. So:
#   • first check-in on a project — the worker picks trade + company and the
#     pairing is stored here;
#   • later check-ins on the SAME project — read the pairing; do not
#     re-prompt and do not raise needs_trade_assignment;
#   • a DIFFERENT project — no pairing exists, so he picks again, entirely
#     independently of what he picked elsewhere.
# Nothing writes trade or company to the global `workers` document. A single
# worker-level trade cannot represent two simultaneous jobs, and writing one
# is exactly how a value bled across projects before.
#
# ── ACCEPTED DEBT (deliberate — do NOT "fix" this by merging the two) ──
# `worker_enrollments` (backend/card_audit.py — model at card_audit.py:272-291,
# unique index at card_audit.py:2281) ALREADY implements this same
# per-worker-per-project rule, correctly, for the gate/NFC card system: it
# carries `trade` + `sub_name` on a row keyed (project_id, card_id), so a
# card-holder's trade is likewise scoped to one project.
#
# We are NOT reusing it and NOT merging into it, because the two systems
# identify a person by DIFFERENT primary keys that the codebase never joins:
#   • worker_enrollments  → card_id (a physical NFC card, per project)
#   • worker_project_trades / checkins / workers → worker_id (a phone- or
#     OSHA-number-resolved `workers` document)
# There is no card_id on a `workers` doc and no worker_id on an enrollment.
# Unifying the two identity systems is a real project with a migration and a
# reconciliation policy for people who exist in one system but not the other;
# it is explicitly out of scope here. Until that project happens, the two
# collections are parallel implementations of one rule over two disjoint
# populations, and that duplication is ACCEPTED, not accidental.
WORKER_PROJECT_TRADES_COLLECTION = "worker_project_trades"


async def _get_worker_project_trade(worker_id, project_id):
    """The stored {trade, company} for this worker on this project, or None.

    Returns None when either key is missing or no pairing exists. NEVER falls
    back to the `workers` document — a value from another project is worse
    than no value, because it is silently wrong instead of visibly absent.
    """
    if not worker_id or not project_id:
        return None
    row = await db[WORKER_PROJECT_TRADES_COLLECTION].find_one({
        "worker_id": str(worker_id),
        "project_id": str(project_id),
    })
    if not row:
        return None
    trade = str(row.get("trade") or "").strip()
    company = str(row.get("company") or "").strip()
    if not trade:
        # A pairing with no trade tells us nothing; treat it as absent so the
        # caller re-prompts rather than freezing an empty trade onto the row.
        return None
    return {"trade": trade, "company": company}


async def _project_trades_for(project_id, worker_ids) -> Dict[str, str]:
    """{worker_id: trade} for these workers on THIS project. One query.

    The batch form of _get_worker_project_trade, for the check-in list
    endpoints. They serialise a page of rows at a time, so the per-row helper
    would be an N+1 on screens a CP opens every morning.

    SAME TWO RULES AS THE SINGLE-ROW HELPER, so the two cannot disagree:
    a pairing whose trade is blank is treated as ABSENT rather than returned as
    an empty answer, and the `workers` document is never consulted.

    Returns {} on any failure. A pairing read is bookkeeping; it must never be
    the reason a roster does not load.
    """
    out: Dict[str, str] = {}
    ids = [str(w) for w in (worker_ids or []) if w]
    if not project_id or not ids:
        return out
    try:
        # to_list, not `async for`. One round trip for a bounded page of rows,
        # and it is the cursor method this codebase's callers and fakes
        # actually implement -- an `async for` against a cursor without
        # __aiter__ raises TypeError, which the fail-open below would swallow
        # into "no pairings found". A lookup that cannot run must not be
        # indistinguishable from one that ran and found nothing.
        rows = await db[WORKER_PROJECT_TRADES_COLLECTION].find({
            "project_id": str(project_id),
            "worker_id": {"$in": ids},
        }).to_list(len(ids))
        for row in rows:
            trade = str(row.get("trade") or "").strip()
            if trade:
                out[str(row.get("worker_id"))] = trade
    except Exception as e:
        logger.warning(f"[pairings] lookup failed for project {project_id}: {e!r}")
        return {}
    return out


async def _store_worker_project_trade(worker_id, project_id, trade, company):
    """Upsert the pairing for this worker on this project.

    Callers must only reach here on a RESOLVED trade — never with the
    "UNASSIGNED" sentinel a flagged check-in carries, because storing that
    would make the next visit read UNASSIGNED back and silently skip the
    needs_trade_assignment flag the CP still has to clear.
    Failure-isolated: a gate check-in must never fail because a bookkeeping
    write did.
    """
    trade = str(trade or "").strip()
    company = str(company or "").strip()
    if not worker_id or not project_id or not trade or trade == "UNASSIGNED":
        return
    try:
        await db[WORKER_PROJECT_TRADES_COLLECTION].update_one(
            {"worker_id": str(worker_id), "project_id": str(project_id)},
            {"$set": {
                "worker_id": str(worker_id),
                "project_id": str(project_id),
                "trade": trade,
                "company": company,
                "updated_at": datetime.now(timezone.utc),
            }},
            upsert=True,
        )
    except Exception as e:  # pragma: no cover — defensive
        logger.warning(
            f"[worker_project_trades] upsert failed for "
            f"worker={worker_id} project={project_id}: {e!r}"
        )


def _roster_key(value) -> str:
    """The ONE roster-match normalization rule: strip surrounding whitespace
    then casefold. Used for MATCHING a submitted (trade, company) against the
    project roster — never for STORAGE (the raw values are preserved). This is
    mirrored verbatim by rosterKey() in checkin.html, so the frontend
    re-prompt guard and the backend strict match agree on case-only edits,
    leading/trailing whitespace, internal whitespace, and renames.
    """
    return str(value or "").strip().casefold()


# POPULATED HERE, not beside the lists, because THIS is where the one
# normalization rule lives. Building the index next to TRADE_VOCABULARY would
# mean either importing the rule upward or re-implementing it -- and a second
# implementation of _roster_key is exactly the drift this file keeps closing.
_TRADE_BY_KEY.update({_roster_key(_t): _t for _t in TRADE_VOCABULARY})
_TRADE_BY_KEY.update({_roster_key(_t): _t for _t in DEPRECATED_TRADES})


def _assignment_is_inactive(row) -> bool:
    """True for a soft-deleted roster row.

    Soft-delete state is the STRING "inactive" on the row's `status` key,
    NOT a boolean: ProjectResponse.trade_assignments is
    List[Dict[str, str]], so a bool stored in the array makes every later
    GET /projects/{id} fail validation with a 500.
    """
    if not isinstance(row, dict):
        return False
    return _roster_key(row.get("status")) == "inactive"


# ── THE TWO READERS ─────────────────────────────────────────────────────────
#
# One fact, three field names. `project.trade_assignments` and
# worker_project_trades say `company`; `checkins` rows say `worker_company`;
# `worker_enrollments` says `sub_name` (card_audit.py:278); and two report
# paths also try `company_name`. Four spellings for "which sub does this man
# work for".
#
# They MEET. checkins_today merges three passes that each read the company from
# a different one of these, and the comment above _norm_key records what that
# cost: a trailing or doubled space made the lowercased (name, company) pair
# miss and emitted THE SAME MAN TWICE on a production pre-shift sheet — once
# from the gate with his card id, once from legacy without one. The same comment
# notes the pair "has now produced four separate defects on this project".
#
# WHAT THIS DOES AND DOES NOT FIX. It collapses the READ: one place that knows
# how to get a company string out of a row, so the `or`-chain-then-strip is not
# retyped at every site. It does NOT fix the identity problem — a single name
# for a string-keyed identity is still a string-keyed identity. Keying that
# merge on `worker_id` is the real fix and it is a separate pass; this is what
# makes it expressible without a translation layer in the middle.
#
# SEMANTICS ARE PRESERVED EXACTLY, and the shape is chosen for that reason.
# Every original site was `(a.get(x) or b.get(y) or "").strip()` — an `or` chain
# FIRST, one strip at the END. So this tests each candidate for truthiness in
# the caller's order and strips only the winner. A whitespace-only value is
# truthy, wins, and strips to "" — exactly as before. Stripping each candidate
# before testing it would let "  " fall through to the next one, which is
# probably the better behaviour and is NOT this pass's decision to make.
#
# The candidates stay AT THE CALL SITE, in the caller's own priority order.
# That is deliberate: the divergence is real and each reader's order is part of
# its meaning, so the fix is to make the order visible on one line rather than
# to average four orders into a hidden default.
def _recorded_trade(value) -> str:
    """The trade a frozen check-in ACTUALLY recorded — '' when it recorded none.

    "UNASSIGNED" is not a trade. register_and_checkin stamps it onto the
    check-in row when the project has no roster, or when the worker picked "my
    company isn't listed" — it is the frozen way of saying NOTHING WAS
    RECORDED, which is why _store_worker_project_trade refuses to persist it as
    a pairing and _display_sub_company renders it as "Pending assignment".

    Anything that reads a frozen trade to decide whether one exists has to ask
    through here, or the sentinel reads as a real answer and suppresses the
    lookup that would have produced one.
    """
    s = str(value or "").strip()
    return "" if s.upper() == "UNASSIGNED" else s


def _worker_company(*candidates) -> str:
    """The company string from the first candidate that carries one.

    Mirrors `(a or b or "").strip()` exactly: first TRUTHY candidate wins, and
    only that one is stripped.
    """
    for v in candidates:
        if v:
            return str(v).strip()
    return ""


# ── ROSTER PRESENCE ─────────────────────────────────────────────────────────
#
# "Does this project have a roster?" decided the same way in one place. The
# canonical rule is register_and_checkin's, because it is the one a man at the
# turnstile is judged by: ACTIVE rows only (a soft-deleted sub must never be a
# valid new selection) and normalised through _roster_key, so the strict match
# and the frontend's rosterKey() cannot disagree about case or whitespace.
#
# ONE CONSUMER IS DELIBERATELY NOT ROUTED THROUGH THIS — assign_checkin_trade
# (:12191). It reads the RAW array on purpose, inactive rows included, because a
# CP correcting an old check-in must still be able to pick a sub that has since
# been removed from the project. Its comment says so. It is left exactly as it
# is: changing it is a UX decision about what a CP may select, which belongs
# with the mandatory-trade gate and not in a reader cleanup.
#
# (Its comment also claims it "still filters through _active_assignments" while
# the code below it does not, and it compares un-normalised strings so a pair
# differing only in case is rejected. Both are logged, not touched here.)
def _roster_pairs(project) -> set:
    """Normalised (trade, company) pairs this project's ACTIVE roster allows."""
    pairs = set()
    for row in _active_assignments(project):
        if not isinstance(row, dict):
            continue
        t = str(row.get("trade") or "").strip()
        c = str(row.get("company") or "").strip()
        if t and c:
            pairs.add((_roster_key(t), _roster_key(c)))
    return pairs


def _has_roster(project) -> bool:
    """True when the project has at least one selectable (trade, company) pair.

    False is NOT an error state. It means an admin has not filled the roster in
    yet, and the ruling that governs every consumer is that an unfilled admin
    form must never stop a man from working: the check-in proceeds, the trade is
    marked pending, and the row is flagged for the CP.
    """
    return bool(_roster_pairs(project))


def _active_assignments(project) -> List[Dict[str, Any]]:
    """The project's roster rows that are still selectable.

    Rows are passed through UNMODIFIED (no rebuild) so callers that
    compare the raw stored rows keep seeing exactly what Mongo holds.
    """
    rows = (project or {}).get("trade_assignments") or []
    return [r for r in rows if not _assignment_is_inactive(r)]


def _merge_trade_assignments(existing_rows, incoming_rows) -> List[Dict[str, str]]:
    """Merge a client-submitted roster onto the stored one, server-side.

    Ids are SERVER-OWNED. The client's `id` is discarded outright; an
    existing row's id is carried forward when the incoming row matches it
    on the SAME normalization the check-in strict-roster match uses
    (_roster_key over trade + company), and only a genuinely new pair
    mints one. Without this, PUT /projects/{id} — which $sets the whole
    array — would let any id-less client wipe every id on the roster.

    Rows the client omits are NOT dropped either: they are retained with
    status "inactive". Nothing here ever hard-deletes a roster row, so an
    older client (or a stale tab) cannot destroy roster history.

    Every emitted value is a string — `id: None` must never reach Mongo,
    because ProjectResponse.trade_assignments is List[Dict[str, str]] and
    a None value 500s the read-back on this very request.
    """
    existing_by_key: Dict[tuple, Dict[str, Any]] = {}
    for row in existing_rows or []:
        if not isinstance(row, dict):
            continue
        t = str(row.get("trade") or "").strip()
        c = str(row.get("company") or "").strip()
        if not t or not c:
            continue
        existing_by_key.setdefault((_roster_key(t), _roster_key(c)), row)

    merged: List[Dict[str, str]] = []
    seen_keys = set()
    for row in incoming_rows or []:
        if not isinstance(row, dict):
            continue
        t = str(row.get("trade") or "").strip()
        c = str(row.get("company") or "").strip()
        if not t or not c:
            continue
        key = (_roster_key(t), _roster_key(c))
        if key in seen_keys:
            continue
        seen_keys.add(key)
        prior = existing_by_key.get(key) or {}
        row_id = str(prior.get("id") or "").strip() or f"srv_{uuid.uuid4().hex}"
        # trade_source is DERIVED, never accepted from the client: it is a
        # statement about the vocabulary, not a field an admin owns. Stamped on
        # every save so a row that becomes vocabulary (because the label was
        # added) flips without anyone editing the trade.
        out: Dict[str, str] = {
            "trade": t, "company": c, "id": row_id,
            "trade_source": _trade_source(t),
        }
        # Only an explicit "inactive" is persisted; an active row keeps the
        # historical {trade, company, id} shape with no status key.
        if _assignment_is_inactive(row):
            out["status"] = "inactive"
        merged.append(out)

    # Anything the client left out is soft-deleted, never dropped.
    for key, row in existing_by_key.items():
        if key in seen_keys:
            continue
        t = str(row.get("trade") or "").strip()
        c = str(row.get("company") or "").strip()
        row_id = str(row.get("id") or "").strip() or f"srv_{uuid.uuid4().hex}"
        merged.append({
            "trade": t, "company": c, "id": row_id, "status": "inactive",
            "trade_source": _trade_source(t),
        })
    return merged


async def _worker_by_phone(phone, projection=None):
    """Resolve a worker by phone, or None. NEVER MATCHES ON AN EMPTY PHONE.

    THE DEFECT THIS CLOSES. The same three-variant lookup was spelled by hand
    at three call sites. `format_phone("")` returns `""`, so a submission with
    no phone built `{"phone": {"$in": ["", "", ""]}}` -- a query that matches
    any worker whose stored phone is the empty string. One of the 61 live
    worker records has exactly that, so on the unguarded site every phone-less
    submission would have resolved to one specific named man.

    AND RESOLVING HIM IS NOT A READ. `submit_checkin` follows the lookup with
    `if worker.get("name") != checkin_data.name: update_fields["name"] = ...`,
    so the wrong man's stored name is overwritten with the submitter's, and the
    check-in is filed under his worker_id. A misattributed check-in and a
    renamed worker, from an empty text field.

    `register_and_checkin` already guarded this with `if phone:` and
    `lookup_worker` 400s on a falsy phone upstream. `submit_checkin` did
    neither. Rather than add a third hand-written guard, the query itself now
    refuses to run without something to match on -- the guard cannot be
    forgotten at a fourth call site because there is no longer a query to
    copy.

    An empty phone therefore falls through to worker CREATION, which is the
    right direction on a document that records who was on site: a duplicate row
    is visible and correctable, and attaching a man's check-in to someone else
    -- while renaming that someone else -- is neither.
    """
    digits = ''.join(c for c in (phone or '') if c.isdigit())
    if not digits:
        return None
    candidates = [v for v in (phone, digits, format_phone(digits)) if v]
    query = {"phone": {"$in": candidates}, "is_deleted": {"$ne": True}}
    if projection is not None:
        return await db.workers.find_one(query, projection)
    return await db.workers.find_one(query)


@api_router.post("/checkin/register-and-checkin")
async def register_and_checkin(data: dict, request: Request):
    """Public endpoint - full registration with OSHA + orientation + check-in in one call"""
    project_id = data.get("project_id")
    tag_id = data.get("tag_id")
    # NORMALISED AT THIS BOUNDARY TOO, and this is the half that makes a data
    # correction stick. `if name: update_fields["name"] = name` below rewrites
    # the stored worker name on EVERY returning check-in, so correcting a
    # worker called "null" in the database is undone at his next tap unless the
    # value that arrives here is cleaned first.
    #
    # THE GATE IS A SECOND MOUTH. upload-osha now returns a real None (see
    # OshaCardOcrResult), but this endpoint takes a body, not that response:
    # a cached gate page, a retried submit, a manual entry, or any future
    # client can still post the string. Cleaning only the OCR response would
    # fix the producer and leave the consumer open.
    #
    # `if name:` then does the rest of the work — None is falsy, so a nullish
    # arrival leaves the stored name ALONE rather than overwriting it, which is
    # also the right answer for a returning worker whose card would not read
    # today.
    name = norm_ocr_str(data.get("name"))
    phone = data.get("phone")
    trade = data.get("trade")
    company = data.get("company")
    osha_card_image = data.get("osha_card_image")  # base64
    # base64 worker selfie, for later human spot-check ONLY (no face match, no
    # liveness, no gate). Stored in R2 now, not inline — see _store_worker_selfie.
    selfie_image = data.get("selfie_image")
    osha_data = data.get("osha_data")  # OCR results dict
    # Same rule, same reason: osha_number reaches the OSHA register and the
    # LL196 attestation, and a card number of "N/A" prints as one.
    osha_number = norm_ocr_str(data.get("osha_number"))
    safety_orientation = data.get("safety_orientation")  # dict of checked items
    signature = data.get("signature")  # base64 PNG
    language_provided = data.get("language_provided", "en")  # "en" or "es" auto-captured from NFC
    device_info = data.get("device_info")  # FingerprintJS data from checkin.html
    # FEATURE 1.4: worker picked "My company isn't listed" — their sub is not on
    # this project's roster. Admit them anyway (never block), flag for the CP.
    trade_not_listed = bool(data.get("trade_not_listed"))
    # FEATURE 2.10: how many card photos OCR was tried on and why the last one
    # failed. Frozen onto the check-in row so an admin can tell "card unreadable"
    # apart from "no card". None on the returning/no-photo path.
    card_ocr_attempts = data.get("card_ocr_attempts")
    card_ocr_failure_reason = data.get("card_ocr_failure_reason")
    # HOW HE REACHED THE GATE — "nfc" (tapped the tag) or "qr" (scanned the
    # code the CP holds up when his phone has no NFC radio).
    #
    # NOT DERIVED FROM THE TAG ROW, and it must not be. A QR carries the SAME
    # nfc_tags row as the tag on the same post — one gate, one registration,
    # one location_description — so the row cannot distinguish them and there
    # is nothing on it to read. Only the client knows, via ?m=qr.
    #
    # FROZEN ONTO THE CHECK-IN, like sst_status and the OCR telemetry beside
    # it, because nfc_tags rows are mutable and soft-deletable while a check-in
    # is the durable artifact. Reading the method back later must not be able
    # to give a different answer than the day it happened.
    #
    # UNKNOWN VALUES BECOME "nfc", not an error and not the raw string. This is
    # a public, unauthenticated endpoint, so the field is closed to the two
    # values that exist; and absent must mean "nfc" permanently, because every
    # tag already programmed into the field sends no marker and an NDEF write
    # cannot be taken back.
    #
    # It is EVIDENCE, never a gate. A QR can be photographed and used off-site
    # where a tap cannot — this is what makes that queryable after the fact. It
    # is not a reason to turn a man away at the gate.
    checkin_method = "qr" if str(data.get("checkin_method") or "").strip().lower() == "qr" else "nfc"
    # TOOLBOX ROSTER (optional): the worker tapped "Confirm attending toolbox
    # talk" at the gate. This is a ROSTER ENHANCEMENT for GCs/insurers — it is
    # NOT a legal attestation and NOT a gate. Under NYC DOB §3301.12.3 / OSHA
    # 29 CFR 1926.21 the CP's signature over the roster is the sole legal
    # anchor; a worker who does not tap is still on the roster purely by having
    # checked in. Recorded as attributed name + server timestamp (ESRA: intent,
    # attribution, association) — deliberately NOT by replaying the worker's
    # stored signature image, which was captured once on day 1 attesting to the
    # §3301.11 site orientation and would misrepresent provenance if rendered
    # under a "Worker Signatures" heading on a toolbox-talk record.
    toolbox_confirm = bool(data.get("toolbox_talk_confirm"))
    # ── DAILY SIGNATURE AFFIRMATION ─────────────────────────────────────────
    #
    # He signed ONCE, at orientation. Printing that image against today's date
    # asserts he signed today's sheet — the same class of overstatement as the
    # "UNAFFIRMED — inherited signature" warning already carried on the CP's
    # signatures. Affirming turns the stamp into a real daily attestation.
    #
    # THE LANGUAGE IS FROZEN HERE, at the moment of affirmation, from what the
    # client says it SHOWED him. Reading it back from live state later would
    # let the record change after the fact, and a worker affirming Spanish copy
    # is evidence about what he read. Only the two locales that exist are
    # accepted; anything else records "en" rather than a language nobody has
    # copy for.
    _sig_affirmed = bool(data.get("signature_affirmed"))
    _sig_lang = str(data.get("signature_affirmed_lang") or "").strip().lower()
    if _sig_lang not in ("en", "es"):
        _sig_lang = "en"

    # Task 12 Phase 0: presence evidence + abuse control on this public endpoint.
    # Capture the caller IP / User-Agent / device fingerprint — all already on the
    # wire or in headers but previously DROPPED — and rate-limit per IP so a
    # stale/shared check-in URL can't be scripted at volume. Keyed under "reg:" so
    # it has its OWN 30/min budget (sized for shift-start bursts), separate from
    # the upload-osha scan limiter's counter.
    client_ip = request.client.host if request.client else "unknown"
    user_agent = request.headers.get("user-agent", "")[:400]
    device_fp = (device_info or {}).get("fingerprint_id") if isinstance(device_info, dict) else None
    # RATE LIMIT REMOVED (operator ruling). This endpoint is the live gate.
    # Workers on their own phones behind one site WiFi — or a shared gate
    # tablet — all present a SINGLE client IP, so a per-IP cap made worker
    # 31 at shift start get a 429 at the gate. A config artifact must never
    # stop a man from working. Dropped outright, not tuned: no per-worker
    # limit and no raised threshold were substituted. client_ip / user_agent
    # / device_fp below are still captured as presence evidence.

    # FIX 1: `company` is deliberately NOT required here. When a project has
    # no trade_assignments configured there is nothing for the worker to pick,
    # so they legitimately submit no company. It is re-required below, but
    # only for projects that DO have trades configured.
    if not all([project_id, tag_id, name]):
        raise HTTPException(status_code=400, detail="Missing required fields")

    # Format phone number
    if phone:
        phone = format_phone(phone)

    # Verify tag + project
    tag = await db.nfc_tags.find_one({
        "tag_id": tag_id,
        "project_id": project_id,
        "status": "active",
        "is_deleted": {"$ne": True}
    })
    if not tag:
        raise HTTPException(status_code=404, detail="Invalid check-in point")

    project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # Resolve the EXISTING worker before the roster check, because the
    # per-project pairing below is keyed on their worker_id and decides
    # whether the roster check runs at all. Read-only find_one, unchanged
    # query — creation of a brand-new worker still happens further down,
    # after the validation, exactly as before.
    worker = await _worker_by_phone(phone)
    if not worker and osha_number:
        worker = await db.workers.find_one({"osha_number": osha_number, "is_deleted": {"$ne": True}})

    # PER-PROJECT PAIRING: this worker already picked a trade + company on
    # THIS project, so that answer stands. Read it, skip the roster prompt
    # entirely, and never raise needs_trade_assignment — the trade is not
    # pending, it is on file. On any OTHER project this lookup finds nothing
    # and he picks again from scratch, which is the point.
    existing_pair = await _get_worker_project_trade(
        worker.get("_id") if worker else None, project_id,
    )

    # Strict-roster enforcement: the submitted {trade, company} MUST match
    # one of the admin-configured trade_assignments for this project. The
    # frontend already forces a dropdown pick, but a modified client could
    # still POST arbitrary values — reject them here so the workforce list
    # matches who's actually been assigned to the project.
    # Soft-deleted rows are excluded: a removed sub must never be a valid
    # NEW selection, even from a stale client that still has it cached.
    # Match on the normalized KEY (strip + casefold) only — the raw
    # trade/company are still what gets stored. This ONE rule is mirrored by
    # rosterKey() in checkin.html so the frontend re-prompt guard and this
    # strict match can never disagree on case or whitespace. It now lives in
    # _roster_pairs, which is the only place that rule is written.
    allowed_pairs = _roster_pairs(project)
    submitted_pair = (_roster_key(trade), _roster_key(company))
    # FIX 1: a project with NO configured trades used to 409 here, which meant
    # a worker standing at the gate could never check in — a pure config gap
    # became a hard block on a real person. Now they proceed, the trade is
    # marked pending, and the check-in is flagged for the CP. The strict
    # roster match below is UNCHANGED for projects that DO have trades.
    needs_trade_assignment = False
    # Why the trade is pending — selects the CP-notification copy below.
    # "" means the trade resolved normally and no notification fires.
    trade_flag_reason = ""
    if existing_pair:
        # Already answered for THIS project — the stored pairing wins over
        # whatever the client sent (a stale or blank client value must not be
        # able to re-open a question the worker has already closed here), and
        # nothing is flagged for the CP.
        trade = existing_pair["trade"]
        company = existing_pair["company"]
    elif not allowed_pairs:
        needs_trade_assignment = True
        trade_flag_reason = "no_roster"
        trade = trade or "UNASSIGNED"
        company = company or "UNASSIGNED"
    elif trade_not_listed:
        # FEATURE 1.4: the worker's subcontractor is not on this project's
        # roster. The roster company is the *accountable* sub, so an absent one
        # is a real gap a human must close — but it must NEVER block a worker at
        # the gate. Admit, mark the trade pending, and notify the CP to add the
        # sub and assign the worker. Mirrors the no-roster path exactly —
        # including keeping any typed value so a future UI that captures the
        # worker's real sub isn't silently dropped.
        needs_trade_assignment = True
        trade_flag_reason = "not_listed"
        trade = trade or "UNASSIGNED"
        company = company or "UNASSIGNED"
    else:
        if not company:
            raise HTTPException(status_code=400, detail="Missing required fields")
        # A returning worker whose roster entry was renamed/removed lands here
        # (their stored pair is no longer allowed and they did NOT pick "not
        # listed"). The 400 is the signal the check-in page uses to re-prompt
        # them for a current roster entry — it is not a dead-end.
        if submitted_pair not in allowed_pairs:
            raise HTTPException(
                status_code=400,
                detail="Selected trade and company are not assigned to this project.",
            )
    
    now = datetime.now(timezone.utc)
    admin_id = project.get("admin_id")
    company_id = project.get("company_id")
    
    # `worker` was already resolved above (the pairing lookup needed it).
    if not worker:
        # Create new worker with full data.
        # NOTE: no `trade` / `company` here. Those are per-project and live in
        # worker_project_trades; a worker-level copy is what bled across jobs.
        # THE ID IS MINTED HERE, not by the insert, because the selfie's R2 key
        # is built from it and the object has to be written before the document
        # that names it. insert_one honours an explicit _id and returns it, so
        # `result.inserted_id` below is this same value.
        worker_oid = ObjectId()
        # BOTH COPIES, DELIBERATELY, AND THE INLINE ONE IS NOT REDUNDANT.
        # `_upload_to_r2` returning a URL proves the PUT returned, not that the
        # object is readable — this project has produced an unreachable file that
        # way before, and until something verifies the object the base64 is the
        # only copy that is known to exist. Dropping it is its own PR, gated on a
        # head_object check (the shape Track P used for the logbook photos).
        #
        # Returns {} when no selfie was offered; the key + url when it landed;
        # {"selfie_upload_failed": True} when a selfie was offered and no object
        # was stored. Never a pointer to something that is not there.
        selfie_fields = await _store_worker_selfie(str(worker_oid), selfie_image)
        worker = {
            "_id": worker_oid,
            "name": name,
            "phone": phone or "",
            "osha_number": osha_number or "",
            "osha_data": osha_data,
            "osha_card_image": osha_card_image,
            "selfie_image": selfie_image,
            **selfie_fields,
            "signature": signature,
            "safety_orientations": [{
                "project_id": project_id,
                "project_name": project.get("name"),
                "checklist": safety_orientation,
                "completed_at": now.isoformat(),
            }] if safety_orientation else [],
            "certifications": [],
            "admin_id": admin_id,
            "company_id": company_id,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "is_deleted": False,
        }
        result = await db.workers.insert_one(worker)
        worker["_id"] = result.inserted_id
    else:
        # Update existing worker with new OSHA data if provided
        update_fields = {"updated_at": now}
        if card_image_may_be_replaced(worker, osha_card_image):
            update_fields["osha_card_image"] = osha_card_image
        # A WORKER WHO ALREADY HAS ONE IS LEFT ALONE, whichever form it is in.
        # `selfie_image` is the pre-R2 inline copy: existing rows keep it and
        # nothing here backfills them, so the two shapes coexist and the reader
        # has to handle both. Only a worker with NEITHER gets a new upload.
        if selfie_image and not worker.get("selfie_image") and not worker.get("selfie_r2_key"):
            # Same pairing as the create path: the inline copy is written
            # unconditionally, the R2 fields only when there is a real key.
            update_fields["selfie_image"] = selfie_image
            update_fields.update(
                await _store_worker_selfie(str(worker.get("_id")), selfie_image)
            )
        if osha_data:
            update_fields["osha_data"] = osha_data
        if osha_number:
            update_fields["osha_number"] = osha_number
        if name:
            update_fields["name"] = name
        # THE BLEED, REMOVED: this used to stamp `company` and `trade` from
        # the CURRENT check-in onto the global worker document on every
        # visit, so a framer's next job — a different project, a different
        # sub — read back the previous job's answer. Both now live only in
        # worker_project_trades, keyed per project. Everything else here
        # (name, phone, osha_number, images, certifications, orientations)
        # is genuinely worker-level and still written.

        # Append safety orientation for this project if not already done
        if safety_orientation:
            existing_orientations = worker.get("safety_orientations", [])
            already_oriented = any(o.get("project_id") == project_id for o in existing_orientations)
            if not already_oriented:
                existing_orientations.append({
                    "project_id": project_id,
                    "project_name": project.get("name"),
                    "checklist": safety_orientation,
                    "completed_at": now.isoformat(),
                })
                update_fields["safety_orientations"] = existing_orientations
        
        await db.workers.update_one({"_id": worker["_id"]}, {"$set": update_fields})
        # The check-in row built below reads company/trade/name off this
        # in-memory dict, which still holds the values loaded from the DB
        # BEFORE the update above. Without this refresh a returning worker who
        # changed employer freezes the STALE company onto today's check-in.
        # Same idiom as the certifications refresh further down.
        worker.update(update_fields)

    # Save orientation as a proper logbook document so CP can view/sign it
    if safety_orientation:
        worker_id_str = str(worker["_id"])
        existing_orient_log = await db.logbooks.find_one({
            "log_type": "subcontractor_orientation",
            "project_id": project_id,
            "data.worker_id": worker_id_str,
            "is_deleted": {"$ne": True},
        })
        if not existing_orient_log:
            await db.logbooks.insert_one({
                "log_type": "subcontractor_orientation",
                "project_id": project_id,
                "project_name": project.get("name", ""),
                "company_id": company_id,
                # TIER 1 — this date is FILED onto a compliance record, not used
                # for a lookup. `now` is UTC, so a worker registering at the gate
                # after 20:00 EDT (19:00 EST) had his orientation stamped with
                # TOMORROW's date. That persists and an inspector reads it.
                "date": eastern_date(now),
                "status": "draft",  # CP must add signature to submit
                "cp_signature": None,
                "cp_name": None,
                "data": {
                    "worker_id": worker_id_str,
                    "worker_name": name,
                    "worker_company": company,
                    "worker_trade": trade or "",
                    "osha_number": osha_number or "",
                    "worker_signature": signature,
                    "checklist": safety_orientation,
                    "completed_at": now.isoformat(),
                    "orientation_number": None,
					"language_provided": language_provided,
                },
                "created_at": now,
                "updated_at": now,
                "is_deleted": False,
            })
    
    # Create check-in — use EST-aligned day boundaries for NYC compliance
    today_start, today_end = get_today_range_est()
    existing_checkin = await db.checkins.find_one({
        "worker_id": str(worker["_id"]),
        "project_id": project_id,
        "check_in_time": {"$gte": today_start, "$lt": today_end},
        "status": "checked_in",
        "is_deleted": {"$ne": True}
    })
    
    if existing_checkin:
        return {
            "success": True,
            "message": "Already checked in",
            "worker_id": str(worker["_id"]),
            "worker_name": worker.get("name"),
            "project_name": project.get("name"),
            "check_in_time": existing_checkin["check_in_time"].isoformat(),
            "is_new_worker": False,
        }
    
    # ── CERTIFICATION GATE ──
    # Create an OSHA cert from the uploaded card. Previously this code
    # would OVERWRITE type to "SST_LIMITED" when an expiration date was
    # detected — which is wrong: an OSHA card with expiration is still
    # an OSHA card, and flipping the type made validate_worker_certifications
    # fail "MISSING_OSHA" immediately for any worker who uploaded one.
    #
    # Strategy now: if the photo carries an expiration, create BOTH an
    # OSHA_10 entry (lifetime, no expiration carried over) AND an
    # SST_LIMITED entry (the expiration lives there). If no expiration
    # found, just create the OSHA_10. Also: accept any uploaded card
    # image as a best-effort OSHA signal even if OCR couldn't pull the
    # number — better than silently blocking the worker for an OCR fail.
    # Snapshot the ORIGINAL cert list BEFORE appending. The previous code did
    # `worker_certs = worker.get("certifications", [])`, which ALIASES the very
    # list it then appends to — so the change-guard below compared that list to
    # itself, was always equal, and the update_one NEVER fired. Result:
    # db.workers.certifications stayed [] forever (new AND returning workers)
    # and the certs were rebuilt from OCR on every single check-in. Copying the
    # list makes the comparison real so the certs actually persist.
    existing_certs = list(worker.get("certifications") or [])
    # Task E (valid returning worker falsely blocked): the returning-worker quick
    # check-in path sends NO card evidence (no osha_data / osha_card_image, often
    # no osha_number), so a worker who proved OSHA on a prior visit would resolve
    # to no cert → has_osha False → MISSING_OSHA block. Fall back to the worker's
    # ON-FILE evidence so their prior proof counts. This does NOT admit a worker
    # with no evidence anywhere (stored or submitted) — that still blocks. It is
    # independent of the company/roster logic (Task D), so it can't weaken D.
    effective_osha_number = osha_number or worker.get("osha_number")
    effective_osha_card_image = osha_card_image or worker.get("osha_card_image")
    worker_certs, not_sst = build_worker_certifications(
        existing_certs, osha_data, effective_osha_number, effective_osha_card_image, now
    )
    if worker_certs != existing_certs:
        await db.workers.update_one(
            {"_id": worker["_id"]},
            {"$set": {"certifications": worker_certs, "updated_at": now}}
        )
        worker["certifications"] = worker_certs

    cert_result = validate_worker_certifications(worker, project)

    # ── THE WRONG CARD SAYS SO ──────────────────────────────────────────────
    # A purple Worker Wallet produces no SST cert (correctly — it is not an SST
    # card), which lands as MISSING_OSHA: "No OSHA card on file". That is a
    # refusal the worker cannot act on, and it is not even true — nothing was
    # learned about his OSHA card, because he never photographed one.
    #
    # SCOPED TO THE BLOCK, not to the scan. `not_sst` is only allowed to
    # re-label a refusal that has ALREADY been decided by
    # validate_worker_certifications. It never creates one: a returning worker
    # with certs on file who happens to photograph his wallet still clears,
    # exactly as before. This changes what a blocked man is TOLD, not who is
    # blocked — the standing rule is that the gate does not stop a man working,
    # and this does not stop one more.
    if not cert_result["cleared"] and not_sst:
        cert_result["blocks"] = [
            {**b, "type": "CARD_NOT_SST"} if b.get("type") == "MISSING_OSHA" else b
            for b in (cert_result.get("blocks") or [])
        ]

    if not cert_result["cleared"]:
        await create_cert_block_alert(worker, project, cert_result["blocks"])
        return {
            "success": False,
            "blocked": True,
            "worker_name": worker.get("name"),
            "worker_id": str(worker["_id"]),
            "blocks": cert_result["blocks"],
            "message": "Registration saved but check-in denied — missing certifications.",
        }
    cert_warnings = cert_result.get("warnings", [])

    # ── Cert-validity snapshot (FROZEN onto the immutable check-in row) ──
    # The worker doc's osha_data.expiration is a mutable raw OCR string that is
    # overwritten on every visit, so it can never prove what was true on a
    # given date. These four fields freeze the cert verdict AS OF this
    # check-in, making "did worker X hold a valid SST on date Y" a single query
    # against `checkins`. Written once at insert; never updated afterwards.
    _warning_types = {w.get("type") for w in cert_warnings}
    _block_types = {b.get("type") for b in (cert_result.get("blocks") or [])}
    _sst_cert = next(
        (c for c in worker_certs if str(c.get("type", "")).startswith("SST")),
        None,
    )
    # Parsed date (datetime), NOT the raw OCR string.
    sst_expiration = _sst_cert.get("expiration_date") if _sst_cert else None
    sst_card_number = (
        (_sst_cert.get("card_number") if _sst_cert else None) or osha_number or None
    )
    # Frozen snapshot mirrors validate's three-state verdict. `unknown` folds
    # in the old "unparseable"/"no-expiry" cases — a class or expiry we could
    # not confirm is unknown, never silently "valid".
    if "EXPIRED_SST" in _warning_types or "EXPIRED_SST" in _block_types:
        sst_status = "expired"
    elif "SST_UNKNOWN" in _warning_types:
        sst_status = "unknown"
    elif "CERT_EXPIRING_SOON" in _warning_types:
        sst_status = "expiring_soon"
    elif _sst_cert is None:
        sst_status = "missing"
    else:
        sst_status = "valid"

    # PR B: freeze WHAT is unknown — class / expiry / both — as an immutable COPY
    # derived from the SST cert AT CHECK-IN. The cert can change later (re-scan,
    # admin edit); this row is the record of what was known now, so the value is
    # copied here, never re-derived at read time. Same rule as worker_trade /
    # worker_company. None unless sst_status == "unknown".
    sst_unknown_reason = None
    if sst_status == "unknown" and _sst_cert is not None:
        _class_unknown = str(_sst_cert.get("type", "")) not in SST_CLASS_TYPES
        _expiry_unknown = (
            _sst_cert.get("expiration_date") is None
            or bool(_sst_cert.get("expiration_raw_rejected"))
        )
        if _class_unknown and _expiry_unknown:
            sst_unknown_reason = "BOTH"
        elif _class_unknown:
            sst_unknown_reason = "CLASS"
        elif _expiry_unknown:
            sst_unknown_reason = "EXPIRY"

    # FEATURE 2.10: coerce the client-reported OCR attempt count + last failure
    # reason into safe shapes before freezing them on the row.
    try:
        _ocr_attempts = int(card_ocr_attempts) if card_ocr_attempts is not None else None
    except (TypeError, ValueError):
        _ocr_attempts = None
    if isinstance(card_ocr_failure_reason, str):
        _ocr_failure_reason = card_ocr_failure_reason.strip()[:300] or None
    else:
        _ocr_failure_reason = None

    checkin_record = {
        "worker_id": str(worker["_id"]),
        "worker_name": worker.get("name"),
        "worker_phone": worker.get("phone"),
        # Trade/company come from the PROJECT-SCOPED resolution above — the
        # stored pairing when one exists, otherwise this visit's validated
        # pick. They are deliberately NOT read off the worker document any
        # more: that field no longer exists for new workers, and for old ones
        # it holds whatever the last unrelated project happened to write.
        "worker_company": company,
        "worker_trade": trade,
        "company": company,
        "trade": trade,
        "project_id": project_id,
        "project_name": project.get("name"),
        "admin_id": admin_id,
        "company_id": company_id,
        "tag_id": tag_id,
        "check_in_time": now,
        "check_out_time": None,
        "status": "checked_in",
        "timestamp": now,
        "created_at": now,
        "updated_at": now,
        "is_deleted": False,
        "cert_warnings": cert_warnings,
        # FIX 1: true when the project had no trades configured, so the worker
        # checked in without one. The CP assigns the real trade later.
        "needs_trade_assignment": needs_trade_assignment,
        # Frozen cert-validity snapshot (see comment above) — the durable
        # per-check-in compliance artifact. Never overwritten.
        "sst_card_number": sst_card_number,
        "sst_expiration": sst_expiration,
        "sst_status": sst_status,
        # PR B: immutable copy of what was unknown at check-in (class/expiry/both).
        "sst_unknown_reason": sst_unknown_reason,
        "cert_cleared": bool(cert_result.get("cleared")),
        # FEATURE 2.10: card-photo OCR telemetry, so an admin reviewing an
        # `unknown`/flagged card sees the photo was tried and unreadable rather
        # than never supplied. None when the card read cleanly or no photo path.
        "card_ocr_attempts": _ocr_attempts,
        "card_ocr_failure_reason": _ocr_failure_reason,
        # Optional gate confirmation for the toolbox-talk roster (see above).
        # Name + server timestamp, so the roster can show WHO confirmed and WHEN
        # without implying the worker signed a legal attestation.
        # The affirmation is a fact about TODAY, so it is recorded with
        # today's check-in rather than on the worker doc beside the signature
        # it affirms. Absent/false simply means he did not affirm, which is a
        # gap on a sheet and never a locked turnstile.
        "signature_affirmed": _sig_affirmed,
        "signature_affirmed_at": now if _sig_affirmed else None,
        "signature_affirmed_lang": _sig_lang if _sig_affirmed else None,
        "toolbox_talk_confirmed": toolbox_confirm,
        "toolbox_talk_confirmed_at": now if toolbox_confirm else None,
        # Task 12 Phase 0: presence evidence (previously received then dropped).
        # Detective, not preventive — makes a stale-URL / off-site check-in
        # queryable (one IP/UA/device behind many check-ins, or an IP never on
        # site) instead of invisible.
        "source_ip": client_ip,
        "user_agent": user_agent,
        "device_fingerprint": device_fp,
        # Tapped or scanned. See the resolution above for why absent is "nfc".
        "checkin_method": checkin_method,
    }

    result = await db.checkins.insert_one(checkin_record)

    # ── THE AFFIRMATION IS ITS OWN SIGNED RECORD, WRITTEN HERE ──────────────
    #
    # THIS IS THE ONLY CONTEMPORANEOUS MOMENT. The worker taps Affirm and this
    # request is the act; anything written later is a record ABOUT the act
    # rather than the act itself. Everything the ledger needs is already in
    # hand -- who, when, from where, on what device, and in which language he
    # read it -- so nothing has to be reconstructed.
    #
    # THE SNAPSHOT HOLDS THE EXACT WORDING HE READ, in the language he read it.
    # checkin.html freezes the language at the moment of affirmation and the
    # gate already stores it, so the record can say WHAT HE AGREED TO and not
    # merely that he agreed. That is the strongest part of this change: a
    # signature event that carries its own text needs no external document to
    # be understood years later.
    #
    # FAIL-SOFT, DELIBERATELY. A ledger write must never cost a man his
    # check-in: the turnstile is not a compliance gate and an affirmation that
    # failed to record is a gap on a sheet, not a locked door. The check-in row
    # still carries `signature_affirmed`, so nothing is lost if this fails.
    if _sig_affirmed:
        try:
            await create_signature_event(
                document_type=PRESHIFT_AFFIRMATION_DOC_TYPE,
                document_id=preshift_affirmation_document_id(
                    project_id, eastern_date(now)),
                event_type="worker_sign",
                signer_name=str(worker.get("name") or ""),
                signer_role="worker",
                signer_user_id=str(worker["_id"]),
                signature_data={
                    # A REFERENCE, NOT A SECOND COPY. The stroke lives on the
                    # worker document; duplicating it here would create two
                    # artefacts that can disagree about one signature.
                    "affirmed_signature_of": str(worker["_id"]),
                    "affirmed_at": now,
                },
                content_snapshot={
                    # THE EXACT WORDING, from the server's own copy, in the
                    # language the gate recorded. Not taken from the request:
                    # a consent whose text the client chooses is evidence of
                    # nothing.
                    "affirmation_text": preshift_affirmation_text(_sig_lang),
                    "affirmation_version": PRESHIFT_AFFIRMATION_VERSION,
                    "language": _sig_lang or None,
                    "project_id": str(project_id),
                    "date": eastern_date(now),
                    "worker_name": worker.get("name"),
                },
                device_info={"device_fingerprint": device_fp,
                             "user_agent": user_agent},
                ip_address=client_ip,
                acting_capacity="Worker - signature affirmation",
                authenticated_role="worker",
                # CONTEMPORANEOUS BY CONSTRUCTION. This request IS the act:
                # the worker tapped Affirm at the turnstile and the device
                # fingerprint, the user agent and the IP above are the gate's
                # own, read from the request that carried the tap. Nothing
                # derives affirmation rows, so this can never be the fallback.
                provenance=contemporaneous_provenance(written_by="gate"),
                # NO signature_key, AND THAT IS DELIBERATE — see the note on
                # signature_ledger_key. This event's `signature_data` is a
                # REFERENCE to the stroke on the worker document, not the
                # stroke itself: no ink, no client timestamp. And the document
                # id here is (project, date), shared by EVERY worker who
                # affirms that day, so a key computed over what is left would
                # be identical for all of them and the first row would swallow
                # the rest. An event with nothing of its own to key on gets no
                # key, and the idempotency it does not need is not applied.
            )
        except Exception as _e:  # pragma: no cover
            # ERROR, NOT WARNING, AND NAMED. The fail-soft above is deliberate
            # and stays -- the turnstile is not a compliance gate -- but it
            # means this line IS the record of the affirmation. A warning that
            # gives only a worker's name cannot be reconciled to anything: the
            # ledger is queried by document, and the document id for an
            # affirmation is (project, eastern date), so both go in the line.
            logger.error(
                f"[signature-ledger] AFFIRMATION NOT RECORDED — the worker "
                f"affirmed at the gate and no ledger row was written. "
                f"document_type={PRESHIFT_AFFIRMATION_DOC_TYPE!r} "
                f"document_id="
                f"{preshift_affirmation_document_id(project_id, eastern_date(now))!r} "
                f"project_id={str(project_id)!r} date={eastern_date(now)!r} "
                f"worker={worker.get('name')!r} worker_id={str(worker['_id'])!r} "
                f"lang={_sig_lang!r}: {_e!r}")

    # FIRST check-in on this project with a resolved trade — store the pairing
    # so every later visit HERE reads it instead of re-prompting. Skipped when
    # one already exists (nothing changed) and when the trade is still pending
    # (UNASSIGNED must never become a stored PAIRING — the CP has to assign it,
    # and _store_worker_project_trade refuses the sentinel besides).
    #
    # SCOPE, because "never stored" stated flatly is wrong and dangerous: the
    # sentinel IS persisted, deliberately, on the checkins row inserted just
    # above — checkin_record carries it in worker_trade/worker_company/trade/
    # company, and _display_sub_company and the headcount renderer translate it
    # to "Pending assignment" / "Not yet assigned" at read time. Stripping it
    # from checkin_record would break every one of those surfaces. What must
    # never persist is THE PAIRING, and only because reading it back would skip
    # the needs_trade_assignment flag the CP still has to clear.
    if not existing_pair and not needs_trade_assignment:
        await _store_worker_project_trade(
            str(worker["_id"]), project_id, trade, company,
        )

    # FIX 1: tell the CP + admins this check-in needs a trade assigned. The
    # check-in is ALREADY written above; this dispatch is failure-isolated so
    # a notification problem can never block a worker at the gate.
    if needs_trade_assignment:
        try:
            from zoneinfo import ZoneInfo
            _nt_today = today_start.astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        except Exception:
            _nt_today = now.strftime("%Y-%m-%d")
        if trade_flag_reason == "not_listed":
            _nt_message = (
                f"{worker.get('name') or 'A worker'} checked in at "
                f"{project.get('name') or 'the site'} but their subcontractor is "
                f"not on this project's roster, so no trade could be selected. "
                f"Add the sub to the roster and assign this worker."
            )
        else:
            _nt_message = (
                f"{worker.get('name') or 'A worker'} checked in at "
                f"{project.get('name') or 'the site'} but this project has no "
                f"trades configured, so no trade could be selected. Add the "
                f"project's trades and assign this worker."
            )
        try:
            await _notifications_inbox.dispatch_notification(
                db,
                project=project,
                kind="checkin_needs_trade",
                severity="warning",
                title="Check-in needs a trade assigned",
                message=_nt_message,
                source_kind="checkin",
                source_id=f"needs-trade:{str(worker['_id'])}:{_nt_today}",
                metadata={
                    "checkin_id": str(result.inserted_id),
                    "worker_id": str(worker["_id"]),
                    "reason": trade_flag_reason,
                },
                deeplink_anchor="workforce",
            )
        except Exception as e:
            logger.warning(f"[needs_trade] dispatch_notification failed: {e!r}")

    # ── Relaxed EXPIRED_SST handling (flag-but-allow) ──
    # The LL196 hard-block was intentionally relaxed in
    # validate_worker_certifications: an expired SST is now a WARNING, so the
    # worker has already checked in normally above (no red block). When that
    # warning is present we still (a) write the compliance_alerts row so the
    # /compliance-alerts admin screen stays populated, and (b) notify the
    # project's admins + assigned CP via the in-app inbox. The check-in is
    # ALREADY written; both side-effects are failure-isolated so a
    # notification/DB blip can NEVER undo or block the successful check-in.
    expired_sst_warnings = [w for w in cert_warnings if w.get("type") == "EXPIRED_SST"]
    if expired_sst_warnings:
        try:
            # Reuse the existing compliance_alerts writer so the admin
            # /compliance-alerts screen keeps surfacing these events.
            await create_cert_block_alert(worker, project, expired_sst_warnings)
        except Exception as e:
            logger.warning(f"[expired_sst] compliance_alerts write failed: {e!r}")
        try:
            from zoneinfo import ZoneInfo
            est_today = today_start.astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        except Exception:
            est_today = now.strftime("%Y-%m-%d")
        exp_on = expired_sst_warnings[0].get("expired_on") or "an unknown date"
        try:
            # Mirror the inspection-prediction dispatch (predictions.py:559).
            # source_id keyed on (worker, EST day) so a same-day re-tap does
            # not double-alert. Wrapped so a dispatch failure NEVER blocks the
            # already-written check-in (contract: test_v2_2_schema_scaffolding).
            await _notifications_inbox.dispatch_notification(
                db,
                project=project,
                kind="expired_sst_checkin",
                severity="warning",
                title="Expired SST card — worker checked in",
                message=(
                    f"{worker.get('name') or 'A worker'} checked in at "
                    f"{project.get('name') or 'the site'} with an SST card that "
                    f"expired {exp_on}. Entry allowed under flag-but-allow policy; "
                    f"SST renewal required."
                ),
                source_kind="checkin",
                source_id=f"{str(worker['_id'])}:{est_today}",
                # Point the notification at THIS check-in so an admin/CP taps
                # through to the check-in detail screen and can record an
                # Approve / Send-home decision there. The inbox itself stays
                # display-only — the buttons live on the detail screen.
                deeplink_anchor=f"checkin-{str(result.inserted_id)}",
                metadata={
                    "checkin_id": str(result.inserted_id),
                    "worker_id": str(worker["_id"]),
                    "sst_status": sst_status,
                    "sst_expiration": (
                        sst_expiration.isoformat() if sst_expiration else None
                    ),
                },
            )
        except Exception as e:
            logger.warning(f"[expired_sst] dispatch_notification failed: {e!r}")

    # ── SST_UNKNOWN handling (flag-but-allow) — mirrors EXPIRED_SST exactly. ──
    # An SST card whose class or expiry could not be confirmed must be as loud
    # as an expired one: it is the silent-failure direction the three-state gate
    # exists to close. The worker has ALREADY checked in above; both side
    # effects are failure-isolated so a blip can never undo the check-in.
    unknown_sst_warnings = [w for w in cert_warnings if w.get("type") == "SST_UNKNOWN"]
    if unknown_sst_warnings:
        try:
            await create_cert_block_alert(worker, project, unknown_sst_warnings)
        except Exception as e:
            logger.warning(f"[sst_unknown] compliance_alerts write failed: {e!r}")
        try:
            from zoneinfo import ZoneInfo
            est_today = today_start.astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        except Exception:
            est_today = now.strftime("%Y-%m-%d")
        try:
            await _notifications_inbox.dispatch_notification(
                db,
                project=project,
                kind="unknown_sst_checkin",
                severity="warning",
                title="Unverified SST credential — worker checked in",
                message=(
                    f"{worker.get('name') or 'A worker'} checked in at "
                    f"{project.get('name') or 'the site'} with an SST card whose "
                    f"class or expiration could not be confirmed. Entry allowed "
                    f"under flag-but-allow policy; CP/admin must verify the card."
                ),
                source_kind="checkin",
                source_id=f"unknown_sst:{str(worker['_id'])}:{est_today}",
                deeplink_anchor=f"checkin-{str(result.inserted_id)}",
                metadata={
                    "checkin_id": str(result.inserted_id),
                    "worker_id": str(worker["_id"]),
                    "sst_status": sst_status,
                },
            )
        except Exception as e:
            logger.warning(f"[sst_unknown] dispatch_notification failed: {e!r}")

    return {
        "success": True,
        "message": "Registration and check-in successful",
        "worker_id": str(worker["_id"]),
        "checkin_id": str(result.inserted_id),
        "worker_name": worker.get("name"),
        "project_name": project.get("name"),
        "check_in_time": now.isoformat(),
        "is_new_worker": True,
    }
def _worker_signature_signed_at(worker) -> Optional[str]:
    """When the stored signature was captured, as an ISO date, or None.

    The signature lives inline on the worker doc and carries no timestamp of its
    own — it is written in the same breath as the first safety_orientations entry
    (register_and_checkin), so that entry's completed_at is when he signed.
    EARLIEST, not latest: a second orientation on another project did not
    re-capture the signature, and reporting the later date would overstate how
    fresh the stroke is, which is the whole thing the kiosk is showing him.
    """
    if not worker or not worker.get("signature"):
        return None
    stamps = []
    for _o in (worker.get("safety_orientations") or []):
        if not isinstance(_o, dict):
            continue
        _c = _o.get("completed_at")
        if isinstance(_c, datetime):
            stamps.append(_c.isoformat())
        elif isinstance(_c, str) and _c.strip():
            stamps.append(_c.strip())
    return min(stamps) if stamps else None


@api_router.post("/checkin/lookup-worker")
async def lookup_worker(data: dict):
    """Public endpoint - check if worker exists by phone.
    Used by returning workers to skip registration."""
    phone = data.get("phone")
    if not phone:
        raise HTTPException(status_code=400, detail="Phone required")
    
    worker = await _worker_by_phone(phone, {"osha_card_image": 0})
    
    if not worker:
        return {"found": False}

    # Trade/company are PER PROJECT and are answered ONLY from the pairing
    # for the project in this request. This used to return
    # worker.get("trade") / worker.get("company") — a global value the
    # worker may have picked on a completely different job — which the
    # check-in page then pre-filled and submitted here.
    #
    # No pairing for THIS project (including a request that names no
    # project) means NO trade and NO company come back, and the worker is
    # asked to pick. There is deliberately no fallback to the worker
    # document: a trade from another job is not a better guess than none,
    # it is a wrong answer that looks confirmed.
    #
    # NOTE (scoped): only the trade source changes here. name / phone and
    # this endpoint's (absent) auth are untouched — the PII question on
    # them is a separate, still-pending operator decision.
    project_id = data.get("project_id")
    pair = await _get_worker_project_trade(worker["_id"], project_id)

    # Site safety orientation is PER PROJECT under §3301.11, so the answer
    # this endpoint gives must be per project too. The full
    # safety_orientations list used to be shipped to the gate page, which
    # then did the project match itself. Compute it here instead and return
    # ONE project-scoped boolean:
    #
    #   - project-scoped, never "has any orientation". A worker oriented at
    #     8 Walworth is NOT oriented at 588 Thomas S Boyland; a global
    #     boolean would skip his site orientation there and write a false
    #     compliance record.
    #   - no project_id in the request means no project to be oriented on,
    #     so the answer is False and the gate runs orientation. Failing
    #     closed here is the safe direction: the cost is a repeated
    #     orientation, not a missing one.
    #
    # osha_number stays the REAL value, deliberately — it is not a display
    # field. checkin.html forwards it back into the register-and-checkin
    # payload for returning workers (checkin.html:1142).
    _orientations = worker.get("safety_orientations") or []
    oriented_on_this_project = bool(project_id) and any(
        isinstance(o, dict) and str(o.get("project_id")) == str(project_id)
        for o in _orientations
    )

    return {
        "found": True,
        "worker_id": str(worker["_id"]),
        "name": worker.get("name"),
        "trade": pair["trade"] if pair else None,
        "company": pair["company"] if pair else None,
        "osha_number": worker.get("osha_number"),
        "has_osha_card": bool(worker.get("osha_card_image")),
        "oriented_on_this_project": oriented_on_this_project,
        # ── DAILY SIGNATURE AFFIRMATION — what the kiosk needs, and no more.
        #
        # A BOOLEAN AND A DATE, NEVER THE IMAGE. This endpoint is PUBLIC and
        # keyed on a phone number, so returning the signature PNG would make
        # signature images enumerable by phone — the one artefact where that
        # matters, and the same enumeration E3 is already open about. The
        # affirmation's weight comes from the worker tapping a named, dated
        # attestation, not from him looking at a thumbnail.
        #
        # THE DATE IS SHOWN, NOT ENFORCED. He signed once at orientation and
        # a stamp re-timestamped is still a stamp, so the kiosk tells him when
        # he signed it. Old is a fact to show, never a gate: the standing rule
        # is that the gate does not stop a man working.
        "has_signature": bool(worker.get("signature")),
        "signature_signed_at": _worker_signature_signed_at(worker),
    }
   
@api_router.post("/checkin/submit")
async def submit_checkin(checkin_data: PublicCheckInSubmit):
    """Public endpoint - workers check in via this"""
    try:
        # Format phone number
        checkin_data.phone = format_phone(checkin_data.phone)
        
        # Verify tag
        tag = await db.nfc_tags.find_one({
            "tag_id": checkin_data.tag_id,
            "project_id": checkin_data.project_id,
            "status": "active",
            "is_deleted": {"$ne": True}
        })
        
        if not tag:
            raise HTTPException(status_code=404, detail="Invalid check-in")
        
        project = await db.projects.find_one({"_id": to_query_id(checkin_data.project_id), "is_deleted": {"$ne": True}})
        
        if not project:
            raise HTTPException(status_code=404, detail="Project not found")

        # Strict (trade, company) validation — the check-in page presents
        # a dropdown of combined Trade — Company entries from the admin's
        # per-project subcontractor roster. Workers can only submit a
        # pair that the admin pre-configured. Matching is case/whitespace
        # tolerant so the DB values get canonicalized to the admin's
        # exact casing for consistent reporting. Soft-deleted rows are
        # excluded — a removed sub is never a valid new selection.
        raw_assignments = _active_assignments(project)
        assignments = []
        for row in raw_assignments:
            if not isinstance(row, dict):
                continue
            t = str(row.get("trade") or "").strip()
            c = str(row.get("company") or "").strip()
            if t and c:
                assignments.append({"trade": t, "company": c})

        # Resolve the EXISTING worker before the roster check — same
        # read-only query the create-or-update block below runs, hoisted
        # because the per-project pairing is keyed on their worker_id and
        # decides whether the roster check runs at all.
        worker = await _worker_by_phone(checkin_data.phone)

        # PER-PROJECT PAIRING: this worker already answered trade + company
        # on THIS project, so the answer stands — no re-prompt, no flag. On
        # any OTHER project this finds nothing and he picks again.
        existing_pair = await _get_worker_project_trade(
            worker.get("_id") if worker else None, checkin_data.project_id,
        )

        # A project with no configured trades used to hard-400 here, which
        # blocked a real worker standing at the gate over a pure config gap.
        # Admit them instead, mark the trade pending, and flag the check-in
        # for the CP — the same fail-open register_and_checkin already does.
        # The strict roster match below is UNCHANGED for projects that DO
        # have trades.
        needs_trade_assignment = False
        # Why the trade is pending — selects the CP-notification copy below.
        # "" means the trade resolved normally and no notification fires.
        trade_flag_reason = ""
        if existing_pair:
            # Already answered for THIS project — the stored pairing wins over
            # whatever the client sent, and nothing is flagged for the CP.
            checkin_data.trade = existing_pair["trade"]
            checkin_data.company = existing_pair["company"]
        elif not assignments:
            needs_trade_assignment = True
            trade_flag_reason = "no_roster"
            checkin_data.trade = str(checkin_data.trade or "").strip() or "UNASSIGNED"
            checkin_data.company = str(checkin_data.company or "").strip() or "UNASSIGNED"
        else:
            submitted_trade = str(checkin_data.trade or "").strip()
            submitted_company = str(checkin_data.company or "").strip()
            match = next(
                (
                    a for a in assignments
                    if a["trade"].lower() == submitted_trade.lower()
                    and a["company"].lower() == submitted_company.lower()
                ),
                None,
            )
            if not match:
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "Please pick your trade and company from the dropdown. "
                        "Custom entries are not allowed."
                    ),
                )
            # Canonicalize to the admin's exact casing.
            checkin_data.trade = match["trade"]
            checkin_data.company = match["company"]

        admin_id = project.get("admin_id")
        company_id = project.get("company_id")
        now = datetime.now(timezone.utc)

        # `worker` was already resolved above (the pairing lookup needed it).
        if not worker:
            # NOTE: no `trade` / `company` here. Those are per-project and
            # live in worker_project_trades; a worker-level copy is what bled
            # across jobs.
            new_worker = {
                "name": checkin_data.name,
                "phone": checkin_data.phone,
                "admin_id": admin_id,
                "company_id": company_id,
                "created_at": now,
                "updated_at": now,
                "status": "active",
                "is_deleted": False
            }
            result = await db.workers.insert_one(new_worker)
            worker = new_worker
            worker["_id"] = result.inserted_id
        else:
            # Update worker info
            update_fields = {}
            if worker.get("name") != checkin_data.name:
                update_fields["name"] = checkin_data.name
            # THE BLEED, REMOVED: `company` and `trade` used to be written
            # here from the CURRENT check-in, so the next project read back
            # this job's answer. Both are per-project now; only genuinely
            # worker-level fields are still written.
            if not worker.get("admin_id"):
                update_fields["admin_id"] = admin_id
            if not worker.get("company_id"):
                update_fields["company_id"] = company_id
            
            if update_fields:
                update_fields["updated_at"] = now
                await db.workers.update_one(
                    {"_id": worker["_id"]},
                    {"$set": update_fields}
                )
                # The check-in row built below reads company/trade/name off this
                # in-memory dict, which still holds the pre-update values.
                # Without this refresh a returning worker who changed employer
                # freezes the STALE company onto today's check-in.
                worker.update(update_fields)

        # Check if already checked in today (EST-aligned)
        today_start, today_end = get_today_range_est()
        existing_checkin = await db.checkins.find_one({
            "worker_id": str(worker["_id"]),
            "project_id": checkin_data.project_id,
            "check_in_time": {"$gte": today_start, "$lt": today_end},
            "status": "checked_in",
            "is_deleted": {"$ne": True}
        })
        
        if existing_checkin:
            return {
                "success": True,
                "message": "Already checked in",
                "checkin_id": str(existing_checkin["_id"]),
                "worker_name": worker.get("name"),
                "project_name": project.get("name"),
                "check_in_time": existing_checkin["check_in_time"].isoformat()
            }
        
        # ── CERTIFICATION GATE ──
        cert_result = validate_worker_certifications(worker, project)
        if not cert_result["cleared"]:
            await create_cert_block_alert(worker, project, cert_result["blocks"])
            raise HTTPException(
                status_code=403,
                detail={
                    "blocked": True,
                    "worker_name": worker.get("name"),
                    "blocks": cert_result["blocks"],
                    "message": "Check-in denied — certification requirements not met."
                }
            )
        cert_warnings = cert_result.get("warnings", [])

        # Create check-in
        checkin_record = {
            "worker_id": str(worker["_id"]),
            "worker_name": worker.get("name"),
            "worker_phone": worker.get("phone"),
            # Trade/company come from the PROJECT-SCOPED resolution above —
            # the stored pairing when one exists, otherwise this visit's
            # validated pick. Not read off the worker document any more.
            "worker_company": checkin_data.company,
            "worker_trade": checkin_data.trade,
            "company": checkin_data.company,
            "trade": checkin_data.trade,
            "project_id": checkin_data.project_id,
            "project_name": project.get("name"),
            "admin_id": admin_id,
            "company_id": company_id,
            "tag_id": checkin_data.tag_id,
            "check_in_time": now,
            "check_out_time": None,
            "status": "checked_in",
            "timestamp": now,
            "created_at": now,
            "updated_at": now,
            "is_deleted": False,
            "cert_warnings": cert_warnings,
            # True when the project had no trades configured, so the worker
            # checked in without one. The CP assigns the real trade later via
            # POST /checkins/{id}/assign-trade.
            "needs_trade_assignment": needs_trade_assignment,
        }

        result = await db.checkins.insert_one(checkin_record)

        # FIRST check-in on this project with a resolved trade — store the
        # pairing so every later visit HERE reads it instead of re-prompting.
        # Skipped when one already exists and when the trade is still pending
        # (UNASSIGNED must never become a stored PAIRING — NOT "never stored":
        # the checkins row inserted just above carries the sentinel on purpose,
        # and the report renderers translate it. See the fuller note on the
        # register-and-checkin twin of this block.)
        if not existing_pair and not needs_trade_assignment:
            await _store_worker_project_trade(
                str(worker["_id"]), checkin_data.project_id,
                checkin_data.trade, checkin_data.company,
            )

        # Tell the CP + admins this check-in needs a trade assigned. The
        # check-in is ALREADY written above; this dispatch is failure-isolated
        # so a notification problem can never block a worker at the gate.
        # Mirrors the register_and_checkin dispatch.
        if needs_trade_assignment:
            try:
                from zoneinfo import ZoneInfo
                _nt_today = today_start.astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
            except Exception:
                _nt_today = now.strftime("%Y-%m-%d")
            _nt_message = (
                f"{worker.get('name') or 'A worker'} checked in at "
                f"{project.get('name') or 'the site'} but this project has no "
                f"trades configured, so no trade could be selected. Add the "
                f"project's trades and assign this worker."
            )
            try:
                await _notifications_inbox.dispatch_notification(
                    db,
                    project=project,
                    kind="checkin_needs_trade",
                    severity="warning",
                    title="Check-in needs a trade assigned",
                    message=_nt_message,
                    source_kind="checkin",
                    source_id=f"needs-trade:{str(worker['_id'])}:{_nt_today}",
                    metadata={
                        "checkin_id": str(result.inserted_id),
                        "worker_id": str(worker["_id"]),
                        "reason": trade_flag_reason,
                    },
                    deeplink_anchor="workforce",
                )
            except Exception as e:
                logger.warning(f"[needs_trade] dispatch_notification failed: {e!r}")

        return {
            "success": True,
            "message": "Check-in successful",
            "checkin_id": str(result.inserted_id),
            "worker_name": worker.get("name"),
            "project_name": project.get("name"),
            "check_in_time": now.isoformat(),
            "needs_trade_assignment": needs_trade_assignment,
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Check-in failed: {str(e)}")
        
# ==================== WORKERS ====================

@api_router.get("/workers")
async def get_workers(
    current_user = Depends(get_current_user),
    limit: int = Query(50, ge=1, le=500),
    skip: int = Query(0, ge=0),
):
    company_id = get_user_company_id(current_user)

    query = {"is_deleted": {"$ne": True}}
    # THE TENANT FILTER WAS CONDITIONAL - the same leak already closed on GET
    # /projects, in the same shape. `if company_id:` meant a caller with NO
    # company_id skipped the filter and received EVERY tenant's workers: names,
    # phones, OSHA numbers and ids.
    #
    # That is the DEFAULT account state, not an exotic one. Self-serve
    # registration sets company_id = None and a company is only attached later
    # by POST /onboarding/company, so opening self-registration to trial users
    # hands each of them the whole platform's worker roster until they onboard.
    #
    # A caller with no company owns no workers, so the honest answer is an empty
    # list. `_id: None` cannot match any document - an unsatisfiable filter
    # rather than a second return path, so pagination and the response shape
    # stay identical to a company that simply owns nobody. NOT
    # `company_id: None`, which would match precisely the orphan rows.
    #
    # The platform operator keeps the unfiltered list: the same deliberate
    # cross-company carve-out GET /projects makes, and never inferred from
    # `role` - "owner" is what every self-serve signup receives.
    if company_id:
        query["company_id"] = company_id
    elif not is_platform_operator(current_user):
        query["_id"] = None

    # ── THE LIST DOES NOT CARRY THE CARD IMAGES ───────────────────────────
    #
    # This endpoint returned 500 for every admin on a company whose roster had
    # grown past ~32MB:
    #
    #   pymongo.errors.OperationFailure: Executor error during find command:
    #   blueview.workers :: caused by :: Sort exceeded memory limit of 33554432
    #   bytes, but did not opt in to external sorting.
    #
    # Three things compounded. The sort is on `name`, which had no index, so it
    # is a BLOCKING in-memory sort. There was no projection, so whole documents
    # were loaded. And a worker document carries `osha_card_image` as base64 --
    # a photograph per worker, added by every gate registration. `.limit(50)`
    # does not help: Mongo must sort the whole matched set before it can take
    # the first fifty.
    #
    # That made it DATA-DEPENDENT, not request-dependent: it began the moment
    # that company crossed the limit and then failed on every load, for every
    # admin on that company, on every device. The sibling call in the same
    # batch (/api/checkins) succeeded throughout, because check-in rows carry
    # no images -- which is what ruled out auth, connectivity and the limiter.
    #
    # DERIVED FROM THE CONSUMERS, not guessed. Everything the three callers of
    # workersAPI.getAll() read off a row:
    #   app/index.jsx          workers.length
    #   app/checkin/index.jsx  name, _id/id
    #   useWorkers.searchWorkers  name, company, trade
    # `trade` and `company` are structurally empty on this document -- nothing
    # writes them here, they belong to the {worker, project} pair -- but
    # searchWorkers still filters on them, so they stay rather than changing
    # search behaviour inside a hotfix.
    #
    # THE DETAIL SCREEN IS UNAFFECTED. workers/[id].jsx fetches through
    # workersAPI.getById and getOshaCard, both their own endpoints, so nothing
    # excluded here can blank a field on a page.
    #
    # What is excluded and why: osha_card_image, signature, osha_data,
    # certifications[] and safety_orientations[] are each served to the one
    # screen that needs them by an endpoint of their own. None is read from a
    # list row.
    WORKER_LIST_FIELDS = {
        "name": 1, "phone": 1, "company": 1, "trade": 1,
        "company_id": 1, "status": 1, "is_deleted": 1,
        "created_at": 1, "updated_at": 1,
    }
    result = await paginated_query(
        db.workers, query, sort_field="name", sort_dir=1,
        limit=limit, skip=skip, projection=WORKER_LIST_FIELDS,
    )
    return result

# POST /workers/register IS DELETED. It was public, unauthenticated, and had no
# caller anywhere - not the app, not checkin.html, not card_audit, not the seed
# scripts. Its only frontend wrapper (`registerWorker` in api.js) was added by
# 9bf110b on 2026-01-31 and removed by 87c08c4 on 2026-03-01, and `git grep` at
# both commits shows NO SCREEN EVER CALLED IT - it was a dead wrapper for its
# entire five-week life, so even the oldest installed bundle cannot miss it.
#
# Three separate defects, any one of which is disqualifying:
#
#   1. It never set company_id AT ALL - not `if company_id:`, the field was
#      simply absent from the insert. Every worker it ever created is an orphan
#      by construction, and those orphans are what the osha-card leak needed:
#      `worker_company != company_id` compared two Nones as EQUAL.
#   2. It was an unauthenticated ENUMERATION ORACLE. Before inserting it did a
#      global, unscoped phone lookup and returned the existing row's id, so
#      anyone on the internet could POST a phone number and learn whether it
#      belonged to a registered construction worker, and get that worker's id.
#   3. `worker_data.model_dump()` wrote `trade` and `company` onto the workers
#      document wholesale - precisely what the worker_project_trades design
#      forbids ("Nothing writes trade or company to the global workers
#      document"), because a worker-level trade answers for every project.
#
# Worker self-registration at the gate is POST /checkin/register-and-checkin,
# which is public BY DESIGN and derives company_id from the project.

# ==================== ELECTRONIC SIGNATURE CONSENT (ESRA) ====================
#
# Buildings Bulletin 2024-007 sec V.5 requires that "all involved parties must
# clearly intend to sign electronically and agree to conduct transactions
# electronically". Nothing recorded such an agreement, so this does.
#
# ONE-TIME, AT ACCOUNT SETUP. Not a per-entry confirmation: a signer learns to
# click through anything they see every day, and a consent clicked through is
# not evidence of intent.
#
# THE TEXT IS COPIED ONTO THE ROW. A version pointer alone would resolve, years
# later, to whatever this file says THEN -- text the person never saw. The row
# carries the wording verbatim and lib/esra_consent.py keeps every version, so
# the two can be checked against each other.
#
# APPEND-ONLY. A new row per agreement; nothing is updated in place. Re-agreeing
# to a new wording adds a row and leaves the old one standing, because what a
# person agreed to in the past does not stop being true when the wording
# changes.


async def latest_esra_consent(db_, user_id: str) -> Optional[dict]:
    """The most recent consent this user gave, or None.

    A FAILED READ RETURNS None, NOT AN EXCEPTION, and the caller must treat
    None as "no consent on record" rather than "assume consented". Failing open
    on a consent check is the one direction that cannot be undone: an entry
    signed without consent cannot be retroactively consented to.
    """
    if db_ is None or not user_id:
        return None
    try:
        rows = await db_.esra_consents.find(
            {"user_id": str(user_id), "is_deleted": {"$ne": True}},
        ).sort("agreed_at", -1).to_list(1)
        return rows[0] if rows else None
    except Exception as e:  # pragma: no cover
        logger.warning(f"[esra] consent read failed for {user_id}: {e!r}")
        return None


async def latest_esra_decline(db_, user_id: str) -> Optional[dict]:
    """The most recent REFUSAL to sign electronically, or None.

    ── WHY A SEPARATE COLLECTION ───────────────────────────────────────────
    `latest_esra_consent` returns the newest row in `esra_consents` and every
    caller treats A ROW AS A CONSENT -- `has_consented` is `bool(row)`. Writing
    a decline into that collection would therefore make a refusal read as an
    agreement, which is precisely the direction its own docstring says cannot
    be undone: "an entry signed without consent cannot be retroactively
    consented to".

    So declines live in `esra_consent_declines` and the consent read path is
    byte-identical to before this endpoint existed. Nothing about recording a
    refusal can break the question "has he agreed".

    A FAILED READ RETURNS None, the same posture as the consent read, and for
    a different reason: a decline that cannot be read is reported as "no
    decline on record", which shows him the agreement again rather than
    stranding him behind a refusal the system cannot see. Asking twice is
    recoverable; a silent permanent block is not.
    """
    if db_ is None or not user_id:
        return None
    try:
        rows = await db_.esra_consent_declines.find(
            {"user_id": str(user_id), "is_deleted": {"$ne": True}},
        ).sort("declined_at", -1).to_list(1)
        return rows[0] if rows else None
    except Exception as e:  # pragma: no cover
        logger.warning(f"[esra] decline read failed for {user_id}: {e!r}")
        return None


async def has_current_esra_consent(db_, user_id: str) -> bool:
    """Has this user agreed to the wording IN FORCE NOW?

    A separate function from `latest_esra_consent` on purpose, so a caller
    cannot get a truthy row back and forget to ask which version it was. The
    superintendent log's signing path is the intended caller.
    """
    row = await latest_esra_consent(db_, user_id)
    return bool(row) and consent_is_current(row.get("consent_version"))


class EsraConsentAgree(BaseModel):
    """What the client sends. DELIBERATELY ALMOST EMPTY.

    The version is echoed back so a client showing stale cached wording is
    caught, rather than silently recording agreement to text the user never
    saw. Everything else -- who, when, from where, and the wording itself -- is
    taken from the server, never from the caller. A consent whose subject the
    client could choose would not be evidence of anything.
    """
    consent_version: str


@api_router.get("/projects/{project_id}/roster")
async def get_project_roster(project_id: str, current_user = Depends(get_current_user)):
    """Every worker who has ever been on this project, for the pre-shift picker.

    WHY THIS EXISTS. `+ Add Row` on the pre-shift sign-in sheet accepted a
    hand-typed name into a document where the gate already knows who is on
    site. That is how one man came to appear twice on one filed report -- once
    as "Jose Castaneda" typed by a CP and once as "Jose Julio Castaneda" from
    his orientation -- and no downstream matching rule can undo it, because
    every rule that would unify those two is asserted AGAINST by a regression
    guard written after a production failure in that direction
    (test_report_six_defects.py: `_norm_key("Wilmer J Carrillo") !=
    _norm_key("Wilmer Carrillo")`). The fix is upstream: pick the man.

    ONE ANSWER TO "WHO WAS ON THIS SITE". This calls `roster_for_window`, the
    same join the LL196 statutory attestation uses, with the month window
    dropped. A second join would let the register and the sheet a CP fills
    disagree about the same men, which is the defect this endpoint exists to
    stop, one level up.

    DUPLICATES ARE RETURNED, DELIBERATELY. A man who exists as two worker
    documents appears twice. The CP is the only person who knows they are the
    same man; a picker that silently collapsed them would perform in the UI
    exactly the merge those regression guards forbid in a normaliser -- and
    deleting a man from the record of who was on site is worse than showing
    two rows, because a duplicate is visible and a deletion is not.

    ── THE TENANT GUARD, WHICH IS THE WHOLE RISK HERE ──────────────────────

    TWO GATES, because the company filter alone does not scope a PROJECT.
    `_assert_project_access` runs first, against the path parameter: without
    it a CP at a legitimate company could name any project id and read its
    roster. Then the worker hydrate is company-scoped.

    `company_id = None` IS THE DEFAULT ACCOUNT STATE, NOT AN EDGE CASE. Self-
    serve registration sets it, and a company is only attached later by POST
    /onboarding/company. `GET /workers` had `if company_id:` alone and that
    was a leak, not a corner: every trial user received the whole platform's
    worker roster -- names, phones, OSHA numbers and ids -- until they
    onboarded. The same shape is refused here.

    `_id: None` RATHER THAN `company_id: None`. An unsatisfiable filter, so a
    caller who owns nobody gets the same empty list a company with no workers
    gets. `company_id: None` would match precisely the orphan rows. It is
    merged with `$and` inside `roster_for_window` so it cannot replace the
    `_id: {$in: ...}` term.

    The platform-operator carve-out is explicit and is never inferred from
    `role`: "owner" is what every self-serve signup receives.
    """
    from lib.logbook.ll196 import roster_for_window

    await _assert_project_access(project_id, current_user)

    company_id = get_user_company_id(current_user)
    if company_id:
        worker_filter = {"company_id": company_id}
    elif is_platform_operator(current_user):
        worker_filter = None
    else:
        worker_filter = {"_id": None}

    # NO CARD IMAGES. `osha_card_image` is base64 on the worker document and
    # is what took GET /workers over Mongo's 32MB sort limit on a large
    # roster. A picker needs four fields.
    workers, trade_by_id = await roster_for_window(
        db, project_id=project_id, worker_filter=worker_filter,
        projection={"name": 1, "company": 1, "osha_number": 1, "_id": 1},
    )

    rows = []
    for w in workers:
        wid = str(w.get("_id"))
        rows.append({
            "worker_id": wid,
            "name": w.get("name") or "",
            "company": w.get("company") or "",
            "osha_number": w.get("osha_number") or "",
            "trade": trade_by_id.get(wid, ""),
        })
    rows.sort(key=lambda r: (r["name"] or "").casefold())
    return {"workers": rows, "total": len(rows)}


@api_router.get("/esra-consent")
async def get_esra_consent(current_user = Depends(get_current_user)):
    """What this user has agreed to, and what is currently being asked.

    Returns the CURRENT WORDING whether or not they have agreed, so the client
    has something to show without a second round trip.
    """
    uid = str(current_user.get("id") or current_user.get("_id") or "")
    row = await latest_esra_consent(db, uid)
    check = verify_stored_consent(row)
    _agreed_at = (row or {}).get("agreed_at")
    _declined = await latest_esra_decline(db, uid)
    _declined_at = (_declined or {}).get("declined_at")
    return {
        "current_version": ESRA_CONSENT_VERSION,
        "current_text": ESRA_CONSENT_TEXT,
        "has_consented": bool(row),
        "is_current": bool(row) and consent_is_current(row.get("consent_version")),
        "agreed_version": (row or {}).get("consent_version"),
        "agreed_at": (
            _agreed_at.isoformat() if isinstance(_agreed_at, datetime) else None
        ),
        # Whether the STORED wording still matches this build's registry. A
        # machine code, never prose; the client decides what a human reads.
        # UNKNOWN_VERSION means this build cannot check the row, which is not
        # the same fact as the row being wrong -- the distinction the OSHA
        # register draws between "No findings" and "Not checked".
        "verification": check["reason"],
        # ── HAS HE REFUSED, AND WHEN ────────────────────────────────────────
        #
        # Reported so the screen can say "you declined on the 2nd" instead of
        # presenting the same question as though it had never been asked. A
        # product that re-asks identically after a refusal is a loop, and the
        # operator's rule is: never a silent block, never a loop.
        #
        # IT DOES NOT GATE ANYTHING. `has_consented` and `is_current` are
        # computed exactly as before; a decline is a fact shown to the person,
        # not a lock. He may agree at any time -- see decline_esra_consent.
        "has_declined": bool(_declined),
        "declined_at": (
            _declined_at.isoformat() if isinstance(_declined_at, datetime) else None
        ),
        "declined_version": (_declined or {}).get("consent_version"),
    }


@api_router.post("/esra-consent")
async def agree_esra_consent(
    body: EsraConsentAgree,
    request: Request,
    current_user = Depends(get_current_user),
):
    """Record that this user agrees to sign electronically.

    THE VERSION IS CHECKED, NOT TRUSTED. A client holding an older wording is
    refused rather than having its agreement recorded against text the user was
    never shown.
    """
    if str(body.consent_version or "") != ESRA_CONSENT_VERSION:
        # The server names the condition; the client owns the wording and is
        # expected to re-fetch and re-present the current text.
        raise HTTPException(
            status_code=409, detail={"code": "ESRA_CONSENT_VERSION_STALE"},
        )

    uid = str(current_user.get("id") or current_user.get("_id") or "")
    if not uid:
        raise HTTPException(
            status_code=400, detail={"code": "ESRA_CONSENT_NO_SUBJECT"},
        )

    existing = await latest_esra_consent(db, uid)
    if existing and consent_is_current(existing.get("consent_version")):
        # ALREADY AGREED TO THIS WORDING. Not an error and not a second row:
        # re-tapping must not multiply the record, and the ORIGINAL agreement's
        # timestamp is the one that matters.
        _prev = existing.get("agreed_at")
        return {
            "recorded": False,
            "already": True,
            "consent_version": existing.get("consent_version"),
            "agreed_at": (
                _prev.isoformat() if isinstance(_prev, datetime) else None
            ),
        }

    now = datetime.now(timezone.utc)
    doc = {
        "user_id": uid,
        # DENORMALISED ON PURPOSE. The consent must stay readable when the user
        # row has been renamed, soft-deleted, or moved to another company. Who
        # agreed is part of what is being recorded, not a lookup.
        "user_email": current_user.get("email"),
        "user_name": current_user.get("name") or current_user.get("full_name"),
        "role_at_time": current_user.get("role"),
        "company_id": current_user.get("company_id"),
        "consent_version": ESRA_CONSENT_VERSION,
        # THE WORDING ITSELF. See lib/esra_consent.py: a consent whose text
        # cannot be reconstructed is not evidence.
        "consent_text": ESRA_CONSENT_TEXT,
        "agreed_at": now,
        "ip_address": (request.client.host if request and request.client else None),
        "user_agent": (request.headers.get("user-agent") if request else None),
        "is_deleted": False,
    }
    await db.esra_consents.insert_one(doc)
    await audit_log("esra_consent_agree", uid, "user", uid, {
        "consent_version": ESRA_CONSENT_VERSION,
    })
    return {
        "recorded": True,
        "already": False,
        "consent_version": ESRA_CONSENT_VERSION,
        "agreed_at": now.isoformat(),
    }


@api_router.post("/esra-consent/decline")
async def decline_esra_consent(
    body: EsraConsentAgree,
    request: Request,
    current_user = Depends(get_current_user),
):
    """Record that this user REFUSED to sign electronically.

    ── A REFUSAL IS A FACT ABOUT THE RECORD ────────────────────────────────

    Not merely the absence of one. "He was asked on 2 September and said no" is
    a different and more useful statement than "no consent on file", which is
    also what an admin who never sent the invitation produces. The second
    cannot be told from the first unless the refusal is written down, and the
    person it describes is the one whose signature is missing from a statutory
    log.

    THE WORDING IS STORED VERBATIM, exactly as the agreement stores it. What he
    declined is as much a part of the record as what someone else accepted --
    and if the text later changes, a refusal that named only a version pointer
    would resolve to words he was never shown. Same failure the consent
    registry exists to prevent, same fix.

    ── IT IS NOT A LOCK ────────────────────────────────────────────────────

    Declining does not bar him from agreeing later, and this writes nothing
    that could. The screen says paper remains available and offers the
    agreement again; a refusal that could not be revisited would be a state
    the product has no way out of, set by one tap.

    ── AND IT DOES NOT TOUCH THE CONSENT PATH ──────────────────────────────

    Separate collection. See latest_esra_decline: any row in `esra_consents` is
    read as a consent by every caller, so a decline written there would read as
    an agreement.

    THE VERSION IS CHECKED, NOT TRUSTED, for the same reason the agreement
    checks it: a client holding stale wording would otherwise record a refusal
    of text nobody showed him.
    """
    uid = str(current_user.get("id") or current_user.get("_id") or "")
    if str(body.consent_version or "") != ESRA_CONSENT_VERSION:
        raise HTTPException(
            status_code=409, detail={"code": "ESRA_CONSENT_VERSION_STALE"},
        )
    if not uid:
        raise HTTPException(
            status_code=400, detail={"code": "ESRA_CONSENT_NO_SUBJECT"},
        )

    now = datetime.now(timezone.utc)
    doc = {
        "user_id": uid,
        # Denormalised for the same reason the agreement denormalises it: the
        # refusal must stay readable when the user row has moved on.
        "user_email": current_user.get("email"),
        "user_name": current_user.get("name") or current_user.get("full_name"),
        "role_at_time": current_user.get("role"),
        "company_id": current_user.get("company_id"),
        "consent_version": ESRA_CONSENT_VERSION,
        "consent_text": ESRA_CONSENT_TEXT,
        "declined_at": now,
        "ip_address": (request.client.host if request and request.client else None),
        "user_agent": (request.headers.get("user-agent") if request else None),
        "is_deleted": False,
    }
    # NOT IDEMPOTENT, and deliberately so. Declining twice is two facts: he was
    # asked again and refused again. The agreement collapses repeats because
    # the FIRST agreement is the one that matters; for a refusal it is the
    # most recent, and the history of being re-asked is worth keeping.
    await db.esra_consent_declines.insert_one(doc)
    await audit_log("esra_consent_decline", uid, "user", uid, {
        "consent_version": ESRA_CONSENT_VERSION,
    })
    return {
        "recorded": True,
        "consent_version": ESRA_CONSENT_VERSION,
        "declined_at": now.isoformat(),
    }


# ==================== WORKER CERTIFICATION MANAGEMENT ====================

@api_router.get("/workers/{worker_id}/certifications")
async def get_worker_certifications(worker_id: str, worker = Depends(require_worker_access)):
    """Get structured certifications with validation status.

    Certifications are the SST/OSHA evidence, so the read gate is the same one
    osha-card already used: same company, the provisioned site device, or a
    company this worker has actually checked in for.
    """
    # THE OTHER READ, and the gap that made read-time evaluation incomplete.
    #
    # The register renders card_number_finding in its Review column, so
    # Cristian's row shows "Unexpected card format" to an investor. This
    # endpoint feeds the CP'S OWN certification screen, and it returned the
    # stored document verbatim -- so the finding appeared on the document he
    # cannot edit and not on the screen where he could fix it. A flag the CP
    # cannot see is a flag he cannot act on.
    #
    # OVERLAID, NEVER WRITTEN. Each row is COPIED before the finding is set, so
    # nothing here can mutate the document this request just read, and nothing
    # is persisted. Same posture as the pre-shift affirmation overlay: the
    # stored record is the stored record, and a read may describe it without
    # amending it.
    #
    # THE SHAPE IS THE STORED SHAPE ON PURPOSE. needs_review and review_reason
    # are the keys every existing reader already understands -- the screen's
    # own row renderer keys on `needs_review || c.review_reason` -- so an
    # evaluated finding reaches the CP through the path a stored one takes,
    # rather than through a second field every reader would have to learn.
    certs = []
    for _c in (worker.get("certifications", []) or []):
        _finding = card_number_finding(_c)
        if _finding and isinstance(_c, dict):
            _c = dict(_c)
            _c["needs_review"] = True
            _c["review_reason"] = _finding
        certs.append(_c)
    validation = validate_worker_certifications(worker)
    return {"worker_id": worker_id, "worker_name": worker.get("name"), "certifications": certs, "validation": validation}

@api_router.post("/workers/{worker_id}/certifications")
async def add_worker_certification(
    worker_id: str,
    cert: WorkerCertification,
    admin=Depends(get_admin_user),
    worker=Depends(require_worker_write_access),
):
    """Add a certification to a worker's record.

    WRITE gate, not the read one: forging a cleared SST on another tenant's
    worker is how a man walks onto a job he is not cleared for.
    """
    try:
        now = datetime.now(timezone.utc)
        cert_dict = cert.model_dump()

        # BEFORE THE $push, WHICH IS THE WHOLE POINT. Validation already ran on
        # this endpoint -- after the write, on the row it had just created --
        # and its result was returned to the caller and never acted on. A row
        # that fails a check is still in the database; the caller is merely
        # told about it. Checking first is the difference between a validator
        # and a report.
        #
        # IT REFUSES HERE AND ONLY OBSERVES AT READ TIME, and the asymmetry is
        # deliberate. The rule rests on two production samples and an
        # all-letter SST number has not been proven impossible, only
        # unobserved. At WRITE time the person who typed it is present and can
        # look at the card in their hand, so a refusal costs one correction. At
        # READ time the row is historical, nobody is there to ask, and a rule
        # this young must not overwrite the record -- so it states what it sees
        # and leaves the row alone.
        #
        # A MISSING NUMBER IS NOT REFUSED. A certification with no card number
        # is a gap in the record, not a false value, and the register already
        # says so twice: an em dash in the Card # column and "Not checked" in
        # Review, because with no number the credential join cannot happen.
        # SST ROWS ONLY, for the same reason the read-time check is scoped:
        # an OSHA 10 or 30 card number has a different shape entirely, and
        # refusing one would block a legitimate entry the rule says nothing
        # about.
        if (str(cert_dict.get("type") or "") in RECOGNIZED_SST_TYPES
                and _card_number_shape(cert_dict.get("card_number")) == "unexpected"):
            # The server names the condition; the client owns the wording.
            raise HTTPException(
                status_code=400, detail={"code": "CARD_NUMBER_FORMAT"},
            )

        cert_dict["added_by"] = str(admin.get("id") or admin.get("_id") or "")
        cert_dict["added_at"] = now
        await db.workers.update_one(
            {"_id": to_query_id(worker_id)},
            {"$push": {"certifications": cert_dict}, "$set": {"updated_at": now}}
        )
        updated = await db.workers.find_one({"_id": to_query_id(worker_id)})
        try:
            validation = validate_worker_certifications(updated)
        except Exception as e:
            logger.warning(f"validate_worker_certifications failed: {e}")
            validation = {"cleared": False, "blocks": [], "warnings": []}

        # Make the response JSON-safe — datetime objects from Pydantic v2 .model_dump()
        # are real datetime.datetime instances and FastAPI will only serialize them
        # if returned via JSONResponse or the Pydantic response_model path.
        from fastapi.encoders import jsonable_encoder
        return jsonable_encoder({
            "message": "Certification added",
            "certification": cert_dict,
            "validation": validation,
        })
    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"add_worker_certification crashed for worker {worker_id}: {e}")
        raise HTTPException(status_code=500, detail=f"Internal error: {str(e)[:200]}")

@api_router.delete("/workers/{worker_id}/certifications/{cert_index}")
async def remove_worker_certification(
    worker_id: str,
    cert_index: int,
    admin=Depends(get_admin_user),
    worker=Depends(require_worker_write_access),
):
    """Remove a certification by index."""
    certs = worker.get("certifications", [])
    if cert_index < 0 or cert_index >= len(certs):
        raise HTTPException(status_code=400, detail="Invalid certification index")
    removed = certs.pop(cert_index)
    now = datetime.now(timezone.utc)
    await db.workers.update_one(
        {"_id": to_query_id(worker_id)},
        {"$set": {"certifications": certs, "updated_at": now}}
    )
    return {"message": "Certification removed", "removed": removed}

@api_router.delete("/workers/{worker_id}/osha-card-image")
async def remove_worker_osha_card_image(
    worker_id: str,
    admin = Depends(get_admin_user),
    worker = Depends(require_worker_write_access),
):
    """Remove the stored card IMAGE and nothing else.

    THE MISSING PRIMITIVE. Three paths look like they would remove one and none
    of them does:

      DELETE /workers/{id}/certifications/{i}  pops a `certifications[]` row.
          The image is a SIBLING field on the worker document, not inside the
          array, so the row goes and the photograph stays.
      DELETE /workers/{id}                     is a SOFT delete, and `workers`
          is on SOFT_DELETE_NEVER_PURGE beside `checkins` and `audit_logs` --
          exempted from the 90-day purge deliberately, because it is compliance
          evidence. The row is never hard-deleted by anything.
      a re-scan of the correct card            overwrites (now), which is a
          correction, not a removal.

    So a photograph of a worker's FACE, stored under a certification key
    because he uploaded the wrong image, is retained permanently and served
    inline to every CP flagged-review screen on the project as the credential
    being judged. That is a privacy exposure rather than a compliance one, and
    it needs an eraser, not a better guard.

    WHAT THIS DOES NOT DO, and the omissions are the design:

      * IT NEVER DELETES THE WORKER ROW. That row carries check-in history
        which is statutory evidence; removing a photograph is not a reason to
        touch it. `$unset` on one field, nothing else.
      * IT NEVER TOUCHES `certifications[]`. Whether the card behind the image
        was valid is a separate question with a separate endpoint, and
        answering it here would delete a compliance fact to fix a privacy one.
      * IT IS NOT OFFERED TO THE GATE OR THE SITE DEVICE. `get_admin_user` plus
        `require_worker_write_access`: an admin, and this worker's admin. The
        second dependency is not decoration -- DELETE /workers/{id} shipped
        with only the first, so any admin could soft-delete any tenant's
        worker.

    Audited, because the whole point of removing the bytes is being able to say
    later that they were removed, by whom, and when.
    """
    had_image = bool(worker.get("osha_card_image"))
    result = await db.workers.update_one(
        {"_id": to_query_id(worker_id)},
        {
            "$unset": {"osha_card_image": ""},
            "$set": {"updated_at": datetime.now(timezone.utc)},
        },
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Worker not found")
    # RECORDED EVEN WHEN THERE WAS NOTHING TO REMOVE. "I asked and it was
    # already gone" and "I never asked" are different facts, and only one of
    # them is evidence that somebody handled the report.
    await audit_log(
        "worker_osha_card_image_removed",
        str(admin.get("id", "")),
        "worker",
        worker_id,
        {"had_image": had_image, "worker_name": worker.get("name")},
    )
    return {"message": "Card image removed", "had_image": had_image}


@api_router.post("/admin/certifications/scan-expiring")
async def scan_expiring_certifications(admin=Depends(get_admin_user)):
    """Scan all workers for expiring or missing certifications."""
    company_id = get_user_company_id(admin)
    query = {"is_deleted": {"$ne": True}}
    # Same conditional-filter leak as GET /workers, and worse in kind: this one
    # returns a per-worker COMPLIANCE VERDICT, so a falsy company_id yielded
    # every tenant's blocked and expiring workers by name.
    if company_id:
        query["company_id"] = company_id
    elif not is_platform_operator(admin):
        query["_id"] = None
    workers = await db.workers.find(query).to_list(5000)
    blocked_workers = []
    warning_workers = []
    for w in workers:
        result = validate_worker_certifications(w)
        ws = {"worker_id": str(w.get("_id", "")), "name": w.get("name", ""), "company": w.get("company", ""), "trade": w.get("trade", "")}
        if result["blocks"]:
            ws["blocks"] = result["blocks"]
            blocked_workers.append(ws)
        elif result["warnings"]:
            ws["warnings"] = result["warnings"]
            warning_workers.append(ws)
    return {"total_scanned": len(workers), "blocked_count": len(blocked_workers), "warning_count": len(warning_workers), "blocked_workers": blocked_workers, "warning_workers": warning_workers}
	
@api_router.get("/workers/{worker_id}/osha-card")
async def get_worker_osha_card(worker_id: str, current_user = Depends(get_current_user)):
    """Get worker's OSHA card image and data - for admin and site device"""
    worker = await db.workers.find_one(
        {"_id": to_query_id(worker_id), "is_deleted": {"$ne": True}},
		{"osha_card_image": 1, "osha_data": 1, "osha_number": 1, "safety_orientations": 1, "name": 1, "company_id": 1, "signature": 1}
	)
    if not worker:
        raise HTTPException(status_code=404, detail="Worker not found")

    # ROLE restriction stays: this endpoint is for an admin console and the
    # kiosk, not for every authenticated principal.
    user_role = current_user.get("role")
    if user_role not in ["admin", "site_device"]:
        raise HTTPException(status_code=403, detail="Access denied")

    # TENANCY is now the shared gate. The check that stood here compared
    # `worker_company != company_id` directly, so two Nones compared EQUAL and
    # a pre-onboarding admin passed straight through to another tenant's card.
    # It also queried checkins with a possibly-None company_id, which matches
    # orphan rows rather than nothing. _assert_worker_access preserves both
    # legitimate paths this endpoint had - the site device on its provisioned
    # project, and a company that holds a check-in for this worker - and fails
    # closed on absence instead of passing.
    await _assert_worker_access(worker_id, current_user)

    return {
        "name": worker.get("name"),
        "osha_card_image": worker.get("osha_card_image"),
        "osha_data": worker.get("osha_data"),
        "osha_number": worker.get("osha_number"),
        "safety_orientations": worker.get("safety_orientations", []),
		"signature": worker.get("signature"),
    }
@api_router.get("/workers/{worker_id}", response_model=WorkerResponse)
async def get_worker(worker_id: str, worker = Depends(require_worker_access)):
    # The hand-rolled check here was `if company_id and ...` - the `and`
    # short-circuited on a falsy company_id and let a pre-onboarding account
    # read any worker in the database. require_worker_access fails closed.
    # It also does the lookup and the 404, so nothing is re-fetched.
    return WorkerResponse(**serialize_id(worker))

@api_router.put("/workers/{worker_id}", response_model=WorkerResponse)
async def update_worker(
    worker_id: str,
    worker_data: dict,
    worker = Depends(require_worker_write_access),
):
    # HAD NO TENANT CHECK AT ALL. Any authenticated caller who knew a worker id
    # could rename or re-phone a worker in another tenant. `company_id` is not
    # in ALLOWED_WORKER_FIELDS and stays out - moving a worker between tenants
    # is a separate, audited operation, not a field edit.
    # TRADE AND COMPANY ARE NOT EDITABLE FIELDS ON A WORKER.
    #
    # They belong to the {worker, project} PAIR and live in
    # worker_project_trades. register_and_checkin says so where it builds the
    # document: "no `trade` / `company` here. Those are per-project and live
    # in worker_project_trades; a worker-level copy is what bled across jobs."
    #
    # This allowlist admitted both, and the worker detail screen offered an
    # admin two inputs for them -- directly under a card reading "No trade
    # specified / No company". So the screen invited exactly the write the
    # design forbids, at the moment an admin was most motivated to make it,
    # and the result would have been a global value overriding nothing and
    # contradicting every per-project pairing.
    #
    # Absent is the correct state. _get_worker_project_trade refuses to fall
    # back to the worker document for the same reason: "a value from another
    # project is worse than no value, because it is silently wrong instead of
    # visibly absent."
    ALLOWED_WORKER_FIELDS = {"name", "phone", "osha_number", "certifications", "emergency_contact", "emergency_phone", "notes"}
    update_data = {k: v for k, v in worker_data.items() if v is not None and k in ALLOWED_WORKER_FIELDS}
    update_data["updated_at"] = datetime.now(timezone.utc)
    
    result = await db.workers.update_one(
        {"_id": to_query_id(worker_id)},
        {"$set": update_data}
    )
    
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Worker not found")
    
    worker = await db.workers.find_one({"_id": to_query_id(worker_id)})
    return WorkerResponse(**serialize_id(worker))

@api_router.delete("/workers/{worker_id}")
async def delete_worker(
    worker_id: str,
    admin = Depends(get_admin_user),
    worker = Depends(require_worker_write_access),
):
    # HAD NO TENANT CHECK AT ALL - get_admin_user proved the caller was AN
    # admin, never that they were THIS worker's admin. Both dependencies stay:
    # one answers "is this an admin", the other "is this their worker".
    # Soft delete
    result = await db.workers.update_one(
        {"_id": to_query_id(worker_id)},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Worker not found")
    return {"message": "Worker deleted successfully"}

# ==================== CHECK-INS ====================

@api_router.post("/workers", dependencies=[Depends(require_company_access)])
async def create_worker(worker_data: WorkerCreate, current_user = Depends(get_current_user)):
    """Create a new worker (admin).

    The stamp below was `if company_id:` - a company-less caller silently
    created a worker owned by nobody. Since the /workers tenant fix that row is
    unreachable to every legitimate admin rather than leaked, but minting an
    unreachable record is still wrong, so the mint is refused at the door.

    Costs nothing: no screen calls this. workersAPI.create reaches only
    useWorkers.createWorker, which no component destructures, and the offline
    queue can only replay an item nothing enqueues. Every worker a real user
    creates comes from the two GATE endpoints, which derive company_id from
    the project and are deliberately untouched.
    """
    # Check if worker with phone exists
    existing = await db.workers.find_one({"phone": worker_data.phone, "is_deleted": {"$ne": True}})
    if existing:
        raise HTTPException(status_code=400, detail="Worker with this phone already exists")
    
    company_id = get_user_company_id(current_user)
    worker_dict = worker_data.model_dump()
    worker_dict["status"] = "active"
    now = datetime.now(timezone.utc)
    worker_dict["created_at"] = now
    worker_dict["updated_at"] = now
    worker_dict["certifications"] = []
    worker_dict["signature"] = None
    worker_dict["is_deleted"] = False
    # require_company_access has refused a falsy company_id at the door; the
    # unconditional stamp is what makes an orphan impossible rather than
    # merely unlikely.
    worker_dict["company_id"] = company_id

    result = await db.workers.insert_one(worker_dict)
    worker_dict["id"] = str(result.inserted_id)
    worker_dict.pop("_id", None)
    
    return WorkerResponse(**worker_dict)

@api_router.get("/checkins")
async def get_all_checkins(
    date: str = None,
    current_user = Depends(get_current_user),
    limit: int = Query(50, ge=1, le=500),
    skip: int = Query(0, ge=0),
):
    """Get all check-ins for the user's company"""
    company_id = get_user_company_id(current_user)
    query = {"is_deleted": {"$ne": True}}
    if company_id:
        query["company_id"] = company_id
    if date:
        # Parse date as an Eastern Time day, convert to UTC range
        day_start_utc, day_end_utc = get_day_range_est(date)
        query["check_in_time"] = {"$gte": day_start_utc, "$lt": day_end_utc}
    total = await db.checkins.count_documents(query)
    checkins = await db.checkins.find(query).sort("check_in_time", -1).skip(skip).limit(limit).to_list(limit)
    
    results = []
    for c in checkins:
        s = serialize_id(c)
        if not s.get("worker_name") and s.get("worker_id"):
            worker = await db.workers.find_one({"_id": to_query_id(s["worker_id"]), "is_deleted": {"$ne": True}})
            if worker:
                s["worker_name"] = worker.get("name", "Unknown Worker")
                s["worker_company"] = s.get("worker_company") or worker.get("company")
                # THE ONE THAT CANNOT RESOLVE, AND WHY. This list is
                # COMPANY-scoped -- one response spans every project the company
                # runs -- so there is no single project_id to key a pairing on.
                # Resolving here would need a per-row (worker_id, project_id)
                # lookup, which is a different query and a different PR.
                #
                # The fallback still goes, because the fallback was the wrong
                # answer everywhere: `workers.trade` is one slot for a man who
                # holds different trades on different jobs, filled by whichever
                # project got to him first. An admin list showing a blank trade
                # is visibly incomplete; one showing another site's trade is
                # invisibly wrong.
                s["name"] = s["worker_name"]
                s["company"] = s["worker_company"]
                s["trade"] = s["worker_trade"]
        results.append(s)
    return {"items": results, "total": total, "limit": limit, "skip": skip, "has_more": (skip + limit) < total}

@api_router.post("/checkins")
async def create_checkin(checkin_data: CheckInCreate, current_user = Depends(get_current_user)):
    """Create a check-in from admin panel — with duplicate prevention"""
    worker = None
    if checkin_data.worker_id:
        worker = await db.workers.find_one({"_id": to_query_id(checkin_data.worker_id), "is_deleted": {"$ne": True}})
    if not worker:
        raise HTTPException(status_code=404, detail="Worker not found")
    
    project = None
    if checkin_data.project_id:
        project = await db.projects.find_one({"_id": to_query_id(checkin_data.project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    
    now = datetime.now(timezone.utc)
    
    # ── Prevent duplicate check-in for same worker+project today (EST-aligned) ──
    today_start, today_end = get_today_range_est()
    existing_checkin = await db.checkins.find_one({
        "worker_id": str(worker["_id"]),
        "project_id": str(project["_id"]),
        "check_in_time": {"$gte": today_start, "$lt": today_end},
        "status": "checked_in",
        "is_deleted": {"$ne": True}
    })
    
    if existing_checkin:
        existing_data = serialize_id(existing_checkin)
        return existing_data

    # ── CERTIFICATION GATE ──
    cert_result = validate_worker_certifications(worker, project)
    if not cert_result["cleared"]:
        await create_cert_block_alert(worker, project, cert_result["blocks"])
        raise HTTPException(
            status_code=403,
            detail={
                "blocked": True,
                "worker_name": worker.get("name"),
                "blocks": cert_result["blocks"],
                "message": "Check-in denied — certification requirements not met."
            }
        )
    cert_warnings = cert_result.get("warnings", [])

    # Trade/company are PER PROJECT. This used to read worker.get("trade") /
    # worker.get("company") off the global worker document — whatever some
    # unrelated project last wrote there. Read the pairing for THIS project
    # instead; when there is none, the row carries no trade rather than
    # another job's trade.
    _pair = await _get_worker_project_trade(worker["_id"], str(project["_id"]))

    checkin_record = {
        "worker_id": str(worker["_id"]),
        "worker_name": worker.get("name"),
        "worker_company": _pair["company"] if _pair else None,
        "worker_trade": _pair["trade"] if _pair else None,
        "project_id": str(project["_id"]),
        "project_name": project.get("name"),
        "company_id": project.get("company_id"),
        "check_in_time": now,
        "check_out_time": None,
        "status": "checked_in",
        "timestamp": now,
        "created_at": now,
        "updated_at": now,
        "is_deleted": False,
        "cert_warnings": cert_warnings,
    }

    result = await db.checkins.insert_one(checkin_record)
    checkin_record["id"] = str(result.inserted_id)
    checkin_record.pop("_id", None)
    # JSON-safe — checkin_record carries raw datetime fields that FastAPI's
    # default serializer will choke on without a response_model.
    from fastapi.encoders import jsonable_encoder
    return jsonable_encoder(checkin_record)


@api_router.post("/checkin")
async def check_in_worker(checkin_data: CheckInCreate, request: Request = None):
    """Public endpoint - allows workers to check in via NFC or manual.
    Rate-limited and duplicate-protected since it doesn't require JWT."""
    client_ip = request.client.host if request and request.client else "unknown"
    if not checkin_rate_limiter.is_allowed(client_ip):
        raise HTTPException(status_code=429, detail="Too many check-in requests. Try again shortly.")
    # Find worker
    worker = None
    if checkin_data.worker_id:
        worker = await db.workers.find_one({"_id": to_query_id(checkin_data.worker_id), "is_deleted": {"$ne": True}})
    elif checkin_data.phone:
        worker = await db.workers.find_one({"phone": checkin_data.phone, "is_deleted": {"$ne": True}})
    
    if not worker:
        raise HTTPException(status_code=404, detail="Worker not found")
    
    # Find project from tag or direct project_id
    project = None
    if checkin_data.tag_id:
        tag = await db.nfc_tags.find_one({"tag_id": checkin_data.tag_id, "status": "active", "is_deleted": {"$ne": True}})
        if tag:
            project = await db.projects.find_one({"_id": to_query_id(tag["project_id"]), "is_deleted": {"$ne": True}})
    elif checkin_data.project_id:
        project = await db.projects.find_one({"_id": to_query_id(checkin_data.project_id), "is_deleted": {"$ne": True}})
    
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    
    # ── DUPLICATE CHECK (EST-aligned) ──
    today_start, today_end = get_today_range_est()
    existing_checkin = await db.checkins.find_one({
        "worker_id": str(worker["_id"]),
        "project_id": str(project["_id"]),
        "check_in_time": {"$gte": today_start, "$lt": today_end},
        "status": "checked_in",
        "is_deleted": {"$ne": True}
    })
    if existing_checkin:
        return {
            "id": str(existing_checkin["_id"]),
            "worker_id": str(worker["_id"]),
            "worker_name": worker.get("name"),
            "project_id": str(project["_id"]),
            "project_name": project.get("name"),
            "timestamp": existing_checkin["check_in_time"].isoformat(),
            "message": "Already checked in today"
        }

    # ── CERTIFICATION GATE ──
    cert_result = validate_worker_certifications(worker, project)
    if not cert_result["cleared"]:
        await create_cert_block_alert(worker, project, cert_result["blocks"])
        raise HTTPException(
            status_code=403,
            detail={
                "blocked": True,
                "worker_name": worker.get("name"),
                "blocks": cert_result["blocks"],
                "message": "Check-in denied — certification requirements not met."
            }
        )
    cert_warnings = cert_result.get("warnings", [])

    # Create check-in record
    now = datetime.now(timezone.utc)
    # Trade/company are PER PROJECT. This used to read worker.get("trade") /
    # worker.get("company") off the global worker document — whatever some
    # unrelated project last wrote there. Read the pairing for THIS project
    # instead; when there is none, the row carries no trade rather than
    # another job's trade.
    _pair = await _get_worker_project_trade(worker["_id"], str(project["_id"]))
    checkin_record = {
        "worker_id": str(worker["_id"]),
        "worker_name": worker.get("name"),
        "worker_company": _pair["company"] if _pair else None,
        "worker_trade": _pair["trade"] if _pair else None,
        "project_id": str(project["_id"]),
        "project_name": project.get("name"),
        "company_id": project.get("company_id"),
        "check_in_time": now,
        "check_out_time": None,
        "status": "checked_in",
        "timestamp": now,
        "created_at": now,
        "updated_at": now,
        "is_deleted": False,
	    "cert_warnings": cert_warnings,
    }
    
    result = await db.checkins.insert_one(checkin_record)
    checkin_record["id"] = str(result.inserted_id)

    await audit_log("checkin_create", str(worker["_id"]), "checkin", str(result.inserted_id), {
        "worker_name": worker.get("name"), "project_name": project.get("name"), "project_id": str(project["_id"]),
    })

    return {
        "id": str(result.inserted_id),
        "worker_id": str(worker["_id"]),
        "worker_name": worker.get("name"),
        "project_id": str(project["_id"]),
        "project_name": project.get("name"),
        "timestamp": now.isoformat(),
        "message": "Check-in successful"
    }

@api_router.post("/checkins/{checkin_id}/checkout")
async def check_out_worker(checkin_id: str, current_user = Depends(get_current_user)):
    now = datetime.now(timezone.utc)
    result = await db.checkins.update_one(
        {"_id": to_query_id(checkin_id)},
        {"$set": {"check_out_time": now, "status": "checked_out", "updated_at": now}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Check-in record not found")

    await audit_log("checkout", str(current_user.get("_id", "")), "checkin", checkin_id)

    return {"message": "Check-out successful"}

def user_can_act_on_project(project: dict, project_id: str, current_user: dict) -> bool:
    """Per-project authorization shared by the check-in review + flagged
    endpoints. Composed from the two existing idioms, since the codebase has
    no ready-made per-project guard:

      • admin/owner scoped to the project's company (the company-scope check
        used by the reports endpoints), OR
      • a user assigned to this project (the CP write-gate in update_logbook).

    This mirrors how the check-in notifications pick their recipients, so the
    people who get alerted are exactly the people allowed to act.
    """
    role = current_user.get("role")
    assigned = current_user.get("assigned_projects", []) or []
    is_company_admin = (
        role in ("admin", "owner")
        and project.get("company_id") == current_user.get("company_id")
    )
    return bool(is_company_admin or str(project_id) in assigned)


@api_router.get("/checkins/project/{project_id}/flagged")
async def get_flagged_project_checkins(
    project_id: str,
    current_user = Depends(get_current_user),
    limit: int = Query(50, ge=1, le=200),
    skip: int = Query(0, ge=0),
):
    """Check-ins on this project that need a human decision:

      • an expired SST that nobody has approved / sent home yet, or
      • a check-in that arrived with no trade because the project had no
        trade_assignments configured.

    Tenant scoping: the sibling project-checkins endpoints filter on
    `project_id` ALONE with no company check, so any authenticated user can
    read any project's check-ins. That gap is deliberately NOT inherited —
    this endpoint authorizes per project before returning anything.

    Payload note: the worker's card image is attached inline (base64) so the
    reviewer can see the card they're judging. Flagged lists are short by
    nature; the default limit is kept low (50) to bound the response size.
    """
    project = await db.projects.find_one({
        "_id": to_query_id(project_id),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if not user_can_act_on_project(project, project_id, current_user):
        raise HTTPException(
            status_code=403, detail="Not authorized to view this project",
        )

    # "Unreviewed" covers rows written before the review feature existed
    # (field absent) as well as rows explicitly reset to null.
    _unreviewed = [
        {"review_decision": {"$exists": False}},
        {"review_decision": None},
    ]
    unreviewed_expired = {"sst_status": "expired", "$or": _unreviewed}
    # PR B: an unknown SST (class/expiry we could not confirm) is as much a
    # review case as an expired one — surface it here so the review screen can
    # act on it, instead of it living only in the notification inbox.
    unreviewed_unknown = {"sst_status": "unknown", "$or": _unreviewed}
    query = {
        "project_id": project_id,
        "is_deleted": {"$ne": True},
        "$or": [
            unreviewed_expired,
            unreviewed_unknown,
            {"needs_trade_assignment": True},
        ],
    }

    checkins = await db.checkins.find(query).sort(
        "check_in_time", -1,
    ).skip(skip).limit(limit).to_list(limit)

    # Batch-fetch the workers so each row can carry the card image + a name
    # fallback, without an N+1 per row.
    worker_ids = {c.get("worker_id") for c in checkins if c.get("worker_id")}
    # And the pairings, the same way and for the same reason. See the trade
    # resolution below.
    _proj_trades = await _project_trades_for(project_id, worker_ids)
    workers_map = {}
    if worker_ids:
        query_ids = [to_query_id(w) for w in worker_ids]
        workers_list = await db.workers.find({
            "_id": {"$in": query_ids}, "is_deleted": {"$ne": True},
        }).to_list(len(query_ids))
        for w in workers_list:
            workers_map[str(w["_id"])] = w

    results = []
    for c in checkins:
        s = serialize_id(c)
        worker = workers_map.get(s.get("worker_id")) or {}
        if not s.get("worker_name"):
            s["worker_name"] = worker.get("name", "Unknown Worker")
        s["worker_company"] = s.get("worker_company") or worker.get("company")
        # THE ONE THAT MATTERS MOST. This is the trade the CP reads on the
        # picker before tapping Change (preshift_signin.jsx `current_trade`) and
        # on the review row. Two different wrong answers were possible here:
        # a trade from ANOTHER PROJECT via the workers document, or -- once that
        # is removed -- a blank on a worker whose pairing has since been set.
        #
        # Frozen first, pairing second, `workers` never. Same precedence as the
        # roster read in get_project_checkins_today, and it has to be the same:
        # the CP decides whether to change a trade by reading this, and the log
        # he is deciding about reads that.
        s["worker_trade"] = (
            _recorded_trade(s.get("worker_trade"))
            or _proj_trades.get(str(s.get("worker_id")), "")
        )
        s["osha_card_image"] = worker.get("osha_card_image")
        s["osha_number"] = s.get("sst_card_number") or worker.get("osha_number")
        # Explicit reason list so the UI doesn't have to re-derive it.
        reasons = []
        if s.get("sst_status") == "expired" and not s.get("review_decision"):
            reasons.append("expired_sst")
        if s.get("sst_status") == "unknown" and not s.get("review_decision"):
            reasons.append("unknown_sst")
            # Surface the SST cert's CURRENT granular review_reason so the review
            # screen can name exactly what to fix (CLASS_UNVERIFIED / EXPIRY_*).
            # This is advisory display of live cert state — the immutable
            # what-was-known copy stays on the row as sst_unknown_reason.
            _sst = next(
                (c for c in (worker.get("certifications") or [])
                 if str(c.get("type", "")).startswith("SST")),
                None,
            )
            s["sst_review_reason"] = (_sst or {}).get("review_reason")
        if s.get("needs_trade_assignment"):
            reasons.append("needs_trade")
        s["flag_reasons"] = reasons
        results.append(s)

    # ── WHAT A TRADE CORRECTION WILL NOT CHANGE ─────────────────────────────
    #
    # Assigning or correcting a trade rewrites the check-in it is applied to
    # and the worker_project_trades pairing, so FUTURE check-ins use it. It
    # does NOT rewrite earlier check-in rows, and it cannot touch a filed
    # logbook at all -- those are signed records.
    #
    # The confirm step has to say so with a NUMBER, because "earlier check-ins
    # keep what they recorded" is abstract until a CP sees that it means four
    # of them. Computed here, in ONE aggregate keyed by worker_id, rather than
    # per row: a lookup inside the loop above would be an N+1 on a screen a CP
    # opens every morning.
    #
    # FILED LOGS ARE DELIBERATELY NOT COUNTED. A preshift sheet stores its
    # roster as data.workers[] keyed by name, an orientation by data.worker_id,
    # and an OSHA register by neither -- so any single count would be wrong for
    # two of the three. The copy says "any filed logs" without a number for
    # exactly that reason, which is honest rather than vague.
    prior_checkins: Dict[str, int] = {}
    try:
        _worker_ids = [str(r.get("worker_id")) for r in results if r.get("worker_id")]
        if _worker_ids:
            async for _row in db.checkins.aggregate([
                {"$match": {"project_id": project_id,
                            "worker_id": {"$in": _worker_ids},
                            "is_deleted": {"$ne": True}}},
                {"$group": {"_id": "$worker_id", "n": {"$sum": 1}}},
            ]):
                # MINUS THE ONE BEING CORRECTED. The row on screen is itself a
                # check-in, and counting it would tell the CP his own edit is
                # among the records he is not changing.
                prior_checkins[str(_row["_id"])] = max(0, int(_row.get("n") or 0) - 1)
    except Exception as e:
        # NON-FATAL, and the client renders the sentence without a number
        # rather than blocking a correction on a count. Never a reason a CP
        # cannot fix a trade.
        logger.warning(f"[flagged] prior check-in count failed: {e!r}")
        prior_checkins = {}

    return {
        "project_id": project_id,
        "project_name": project.get("name"),
        # Per worker: how many OTHER check-in rows this project holds for him.
        # The trade correction leaves every one of them as filed.
        "prior_checkin_counts": prior_checkins,
        # The review screen offers these as the choices for assign-trade, so
        # soft-deleted rows are excluded. Surviving rows are passed through
        # untouched — this filters the list, it does not reshape the rows.
        "trade_assignments": _active_assignments(project),
        "items": results,
        "count": len(results),
    }


@api_router.post("/checkins/{checkin_id}/assign-trade")
async def assign_checkin_trade(checkin_id: str, data: dict, current_user = Depends(get_current_user)):
    """Assign a trade/company to a check-in that arrived without one, and
    clear its needs_trade_assignment flag.

    Closes the loop opened when a worker checks in on a project that has no
    trade_assignments configured: previously the flag was raised and the CP
    was notified, but NOTHING could clear it — there was no endpoint to set a
    trade on a check-in, and the project trade-roster screen is admin-only.

    Mirrors review_checkin: same per-project authorization helper, attribution
    derived SERVER-SIDE from current_user, and an audit_log entry.

    The submitted {trade, company} must be one of the project's configured
    trade_assignments — the same strict-roster rule the check-in itself
    enforces, so this cannot introduce a pair the roster doesn't know.
    Soft-deleted (inactive) rows count here, unlike everywhere else: a CP
    may correct a check-in from any day, so a sub removed since that
    check-in must still be selectable for it.

    The answer is also stored as the worker's pairing for THIS project in
    worker_project_trades, so their next check-in here reads it instead of
    being flagged again. Nothing is written to the global worker document:
    an assignment on one project must not answer for any other.
    """
    trade = str((data or {}).get("trade") or "").strip()
    company = str((data or {}).get("company") or "").strip()
    if not trade or not company:
        raise HTTPException(
            status_code=400, detail="trade and company are required",
        )

    checkin = await db.checkins.find_one({
        "_id": to_query_id(checkin_id),
        "is_deleted": {"$ne": True},
    })
    if not checkin:
        raise HTTPException(status_code=404, detail="Check-in record not found")

    project_id_str = str(checkin.get("project_id") or "")
    project = await db.projects.find_one({
        "_id": to_query_id(project_id_str),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    if not user_can_act_on_project(project, project_id_str, current_user):
        raise HTTPException(
            status_code=403,
            detail="Not authorized to assign a trade on this check-in",
        )

    # Strict roster: the pair must exist on the project now that the admin has
    # configured trades. Prevents the assign action from becoming a back door
    # around the same validation register_and_checkin applies.
    #
    # INACTIVE (soft-deleted) rows are ACCEPTED here — and ONLY here. A CP may
    # correct a check-in from ANY day; same-day is not enforced. So a sub that
    # has been removed from the project since that check-in must still be
    # selectable, otherwise correcting an old row 400s and the flag can never
    # be cleared. Every other consumer (site-info, register_and_checkin,
    # /checkin/submit, the flagged passthrough) still filters through
    # _active_assignments, so a removed sub is never a valid NEW selection.
    #
    # The pair is scoped to this ONE project when it is stored below, so an
    # inactive pair can describe this project's history without reaching any
    # other project the worker has been on.
    allowed_pairs = set()
    for row in (project or {}).get("trade_assignments") or []:
        if not isinstance(row, dict):
            continue
        rt = str(row.get("trade") or "").strip()
        rc = str(row.get("company") or "").strip()
        if rt and rc:
            allowed_pairs.add((rt, rc))
    if not allowed_pairs:
        raise HTTPException(
            status_code=409,
            detail="This project has no trades configured yet. Add trades to the project first.",
        )
    if (trade, company) not in allowed_pairs:
        raise HTTPException(
            status_code=400,
            detail="Selected trade and company are not assigned to this project.",
        )

    user_id = str(current_user.get("_id") or current_user.get("id") or "")
    assigner_name = (
        current_user.get("full_name")
        or current_user.get("name")
        or current_user.get("email")
        or ""
    )
    now = datetime.now(timezone.utc)

    await db.checkins.update_one(
        {"_id": to_query_id(checkin_id)},
        {"$set": {
            "trade": trade,
            "company": company,
            "worker_trade": trade,
            "worker_company": company,
            "needs_trade_assignment": False,
            "trade_assigned_by": user_id,
            "trade_assigned_by_name": assigner_name,
            "trade_assigned_at": now,
            "updated_at": now,
        }},
    )

    # Record the CP's answer where trade actually lives: the PAIRING for
    # this worker on THIS project. The next check-in here reads it and stops
    # asking; a check-in on any other project is unaffected, which is the
    # whole point of the pair key.
    #
    # This REPLACES the previous fill-if-empty write of `trade` onto the
    # global worker document. That write was correct under the earlier
    # ruling and is wrong under this one: even guarded by "only when empty",
    # a worker-level trade is a single slot for a man who can hold different
    # trades on different jobs, and whichever project filled it first
    # answered for all the others.
    worker_id = checkin.get("worker_id")
    if worker_id:
        await _store_worker_project_trade(
            worker_id, project_id_str, trade, company,
        )

    await audit_log(
        "checkin_assign_trade", user_id, "checkin", checkin_id,
        {"trade": trade, "company": company},
    )

    return {
        "success": True,
        "checkin_id": checkin_id,
        "trade": trade,
        "company": company,
        "needs_trade_assignment": False,
        "trade_assigned_by": user_id,
        "trade_assigned_by_name": assigner_name,
        "trade_assigned_at": now.isoformat(),
    }


@api_router.post("/checkins/{checkin_id}/review")
async def review_checkin(checkin_id: str, data: dict, current_user = Depends(get_current_user)):
    """Record an admin/CP decision on a flagged (e.g. expired-SST) check-in.

    Mirrors the checkout endpoint above: mutate the check-in row, then write an
    audit_log entry. Attribution is SERVER-DERIVED from current_user — the
    client cannot supply reviewed_by.

    "sent_home" RECORDS the decision only: no worker notification and no
    must-leave enforcement (product decision — logging only).

    Re-review is allowed: the latest decision overwrites the fields on the row,
    while audit_logs preserves the full history of every decision.
    """
    decision = str((data or {}).get("decision") or "").strip()
    if decision not in ("approved", "sent_home"):
        raise HTTPException(
            status_code=400,
            detail="decision must be 'approved' or 'sent_home'",
        )

    checkin = await db.checkins.find_one({
        "_id": to_query_id(checkin_id),
        "is_deleted": {"$ne": True},
    })
    if not checkin:
        raise HTTPException(status_code=404, detail="Check-in record not found")

    project_id_str = str(checkin.get("project_id") or "")
    project = await db.projects.find_one({
        "_id": to_query_id(project_id_str),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # Authorization — shared with the flagged-list endpoint so the people who
    # get alerted are exactly the people allowed to act. See the helper above.
    if not user_can_act_on_project(project, project_id_str, current_user):
        raise HTTPException(
            status_code=403,
            detail="Not authorized to review this check-in",
        )

    user_id = str(current_user.get("_id") or current_user.get("id") or "")
    reviewer_name = (
        current_user.get("full_name")
        or current_user.get("name")
        or current_user.get("email")
        or ""
    )
    now = datetime.now(timezone.utc)
    await db.checkins.update_one(
        {"_id": to_query_id(checkin_id)},
        {"$set": {
            "review_decision": decision,
            "reviewed_by": user_id,
            "reviewed_by_name": reviewer_name,
            "reviewed_at": now,
            "updated_at": now,
        }},
    )

    await audit_log(
        "checkin_review", user_id, "checkin", checkin_id, {"decision": decision},
    )

    return {
        "success": True,
        "checkin_id": checkin_id,
        "review_decision": decision,
        "reviewed_by": user_id,
        "reviewed_by_name": reviewer_name,
        "reviewed_at": now.isoformat(),
    }

@api_router.get("/checkins/project/{project_id}")
async def get_project_checkins(
    project_id: str,
    current_user = Depends(get_current_user),
    limit: int = Query(200, ge=1, le=1000),
    skip: int = Query(0, ge=0),
    _proj = Depends(require_project_access),
):
    checkins = await db.checkins.find({"project_id": project_id, "is_deleted": {"$ne": True}}).sort("check_in_time", -1).skip(skip).limit(limit).to_list(limit)

    # Batch-fetch workers for check-ins missing worker_name (avoid N+1)
    missing_worker_ids = set()
    for c in checkins:
        if not c.get("worker_name") and c.get("worker_id"):
            missing_worker_ids.add(c["worker_id"])

    workers_map = {}
    if missing_worker_ids:
        query_ids = [to_query_id(wid) for wid in missing_worker_ids]
        workers_list = await db.workers.find({"_id": {"$in": query_ids}, "is_deleted": {"$ne": True}}).to_list(len(query_ids))
        for w in workers_list:
            workers_map[str(w["_id"])] = w

    # This list is scoped to ONE project, so the pairing is well defined and
    # is the right answer for a row that froze no trade. Applied to all three
    # of these endpoints rather than only the one with a consumer today
    # (/today renders it on the site check-ins screen; /active and the bare
    # list do not) -- a rule that holds only where someone currently looks is
    # a rule that breaks the first time someone else looks.
    _proj_trades = await _project_trades_for(
        project_id, [c.get("worker_id") for c in checkins],
    )

    results = []
    for c in checkins:
        s = serialize_id(c)
        if not s.get("worker_name") and s.get("worker_id"):
            worker = workers_map.get(s["worker_id"])
            if worker:
                s["worker_name"] = worker.get("name", "Unknown Worker")
                s["worker_company"] = s.get("worker_company") or worker.get("company")
        # OUTSIDE the missing-name branch, deliberately. The trade has nothing
        # to do with whether the name needed filling in; nesting it there meant
        # a row that already had a name never got its trade resolved at all.
        s["worker_trade"] = (
            _recorded_trade(s.get("worker_trade"))
            or _proj_trades.get(str(s.get("worker_id")), "")
        )
        results.append(s)
    return results

