@api_router.get("/daily-logs")
async def get_daily_logs(
    current_user = Depends(get_current_user),
    limit: int = Query(50, ge=1, le=500),
    skip: int = Query(0, ge=0),
):
    company_id = get_user_company_id(current_user)
    
    query = {"is_deleted": {"$ne": True}}
    if company_id:
        query["company_id"] = company_id
    
    result = await paginated_query(db.daily_logs, query, sort_field="date", limit=limit, skip=skip)
    return result

@api_router.post("/daily-logs", response_model=DailyLogResponse)
async def create_daily_log(log_data: DailyLogCreate, current_user = Depends(get_current_user)):
    log_dict = log_data.model_dump()
    now = datetime.now(timezone.utc)
    log_dict["created_at"] = now
    log_dict["updated_at"] = now
    log_dict["created_by"] = current_user.get("id")
    log_dict["created_by_name"] = current_user.get("full_name") or current_user.get("name") or current_user.get("device_name")
    log_dict["is_deleted"] = False

    # The project id arrives in the BODY, so it is caller-controlled and has to
    # be authorized before anything is read or written under it. Runs FIRST so
    # the duplicate-check 409 below cannot be used to probe another tenant's
    # logs. 404 when the project does not exist, which also closes the old
    # silent path that inserted a log with no company_id at all.
    project = await _assert_project_access(log_data.project_id, current_user)

    # Prevent duplicate log for same project + date
    existing = await db.daily_logs.find_one({
        "project_id": log_data.project_id,
        "date": log_data.date,
        "is_deleted": {"$ne": True}
    })
    if existing:
        raise HTTPException(status_code=409, detail="A daily log already exists for this project and date.")

    log_dict["company_id"] = project.get("company_id")

    result = await db.daily_logs.insert_one(log_dict)
    log_dict["id"] = str(result.inserted_id)

    # Phase V2.0: post-save deficiency hook. Gated by the
    # `v2_logbook` feature flag — flag-off customers see no
    # behavior change. Wrapped in try/except so a hook bug never
    # breaks the daily_log save itself.
    try:
        if project and await feature_flags.is_feature_enabled(
            db, "v2_logbook",
            user_id=str(current_user.get("id") or ""),
            company_id=str(project.get("company_id") or "") or None,
        ):
            from lib.logbook.deficiency import run_deficiency_check_post_save
            await run_deficiency_check_post_save(
                db,
                daily_log=log_dict,
                project=project,
            )
    except Exception as _e:
        logger.warning(
            f"[v2_logbook] post-save deficiency hook failed for "
            f"daily_log={log_dict.get('id')}: {_e!r}",
        )

    return DailyLogResponse(**log_dict)

@api_router.put("/daily-logs/{log_id}")
async def update_daily_log(log_id: str, update_data: dict, current_user = Depends(get_current_user)):
    """Update an existing daily log"""
    existing = await db.daily_logs.find_one({"_id": to_query_id(log_id)})
    
    if not existing:
        raise HTTPException(status_code=404, detail="Daily log not found")
    
    if existing.get("is_locked"):
        raise HTTPException(status_code=423, detail="This log is locked and cannot be edited.")

    # Authorize against the STORED project id, never the body: the body is the
    # thing being authorized, so trusting it would let a caller name a project
    # they do have access to while writing to a log belonging to another.
    await _assert_project_access(str(existing.get("project_id") or ""), current_user)

    update_data.pop("id", None)
    update_data.pop("_id", None)
    update_data.pop("created_at", None)
    update_data.pop("created_by", None)
    # $set takes this dict wholesale, so an unpopped project_id/company_id would
    # RE-PARENT the log into another tenant. Ownership is set at creation only.
    update_data.pop("project_id", None)
    update_data.pop("company_id", None)
    # ── LIFECYCLE IS NOT A FIELD EDIT ──────────────────────────────────────
    #
    # Both of these were reachable, by anyone with access to the project, until
    # they were popped:
    #
    #   is_deleted  — a soft-deleted log has `is_deleted: True` and every reader
    #                 filters on `{"$ne": True}`. Sending `is_deleted: false`
    #                 through this body RESURRECTED it everywhere at once. The
    #                 delete endpoint is the only thing that may set it.
    #   is_locked   — sending `is_locked: true` FROZE somebody else's open log.
    #                 The reverse was already impossible by accident rather than
    #                 by design: the 423 above refuses a locked log before
    #                 reaching this line, so an unlock could never land. Popping
    #                 makes both directions deliberate instead of one of them
    #                 being blocked by an unrelated guard.
    #
    # POPS, NOT AN ALLOWLIST. An allowlist is the better shape and is a contract
    # change — the callers of PUT /daily-logs are not enumerated and the offline
    # queue replays this endpoint, so a field silently dropped from a queued
    # edit is a worse failure than the two this closes. Recorded as owed.
    update_data.pop("is_deleted", None)
    update_data.pop("is_locked", None)

    now = datetime.now(timezone.utc)
    update_data["updated_at"] = now
    update_data["updated_by"] = current_user.get("id")
    update_data["updated_by_name"] = current_user.get("full_name") or current_user.get("name") or current_user.get("device_name")
    
    await db.daily_logs.update_one(
        {"_id": to_query_id(log_id)},
        {"$set": update_data}
    )
    
    log = await db.daily_logs.find_one({"_id": to_query_id(log_id)})
    return serialize_id(log)

@api_router.get("/daily-logs/{log_id}", response_model=DailyLogResponse)
async def get_daily_log(log_id: str, current_user = Depends(get_current_user)):
    log = await db.daily_logs.find_one({"_id": to_query_id(log_id), "is_deleted": {"$ne": True}})
    if not log:
        raise HTTPException(status_code=404, detail="Daily log not found")
    return DailyLogResponse(**serialize_id(log))

