@api_router.get("/reports/logbook/{logbook_id}/pdf")
async def get_single_logbook_pdf(logbook_id: str, token: Optional[str] = None, current_user=Depends(get_current_user)):
    """Generate PDF for a single logbook entry (per-type PDF).
    Reuses the combined report HTML generator but filters to one log type."""
    from fastapi.responses import Response
    
    logbook = await db.logbooks.find_one({"_id": to_query_id(logbook_id), "is_deleted": {"$ne": True}})
    if not logbook:
        raise HTTPException(status_code=404, detail="Logbook not found")
    
    project_id = logbook.get("project_id")
    date = logbook.get("date")
    log_type = logbook.get("log_type")
    
    # Generate full report HTML but we'll use it as-is since it filters by date
    # For a single-type PDF, generate targeted HTML
    html = await generate_single_logbook_html(logbook)
    
    try:
        from weasyprint import HTML
        # OFF THE EVENT LOOP -- see the note at the first of these three.
        def _render_pdf(h: str) -> bytes:
            return HTML(string=h).write_pdf()

        pdf_bytes = await asyncio.to_thread(_render_pdf, html)
    except Exception as e:
        logger.error(f"PDF generation failed: {e}")
        raise HTTPException(status_code=500, detail=f"PDF generation failed: {str(e)}")
    
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = (project.get("name", "report") if project else "report").replace(" ", "_")
    type_label = log_type.replace("_", "-") if log_type else "log"
    filename = f"Levelog_{type_label}_{project_name}_{date}.pdf"
    
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )
 
 
async def generate_single_logbook_html(logbook: dict) -> str:
    """The per-logbook PDF an inspector downloads. ONE MEDIUM: PAPER.

    THE STALE CLAIM THIS REPLACES: "Reuses the same styling as the combined
    report." It does not, and the difference is the whole of this change.
    `generate_combined_report` genuinely serves TWO media -- it is emailed AND
    handed to WeasyPrint -- so its wrapper is 680px because that is the right
    column for an email client, and a `@media print` block releases the width
    for the sheet of paper. This renderer has exactly ONE caller,
    `get_single_logbook_pdf` (server.py:18720), which hands the string straight
    to WeasyPrint and returns application/pdf. Nothing emails it. Its 700px
    wrapper was a constraint borrowed from a medium this document does not
    have: 700px on a ~794px A4 page, leaving a dead strip down the right.

    THE FIX WAS NEVER PORTED, AND THAT IS THE FINDING. The combined report
    corrected exactly this defect -- same page size, same cause, same dead
    strip -- and the correction stopped at the renderer someone was reading.
    Two renderers print the same stored records; fixing one of them fixes one
    document. The print block below is that block, ported.

    The width release stays inside `@media print` rather than simply deleting
    the 700px, so that a future email consumer of this string is not handed a
    full-bleed table. WeasyPrint renders at media type `print`, so the release
    applies on the only path that exists today.
    """

    BASE_URL = "https://api.levelog.com"
    
    project_id = logbook.get("project_id")
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = project.get("name", "Unknown") if project else "Unknown"
    project_address = project.get("address", "") if project else ""
    date = logbook.get("date", "N/A")
    log_type = logbook.get("log_type", "unknown")
    data = logbook.get("data", {})
    
    # THE ZONE IS PART OF THE FACT. This printed a UTC clock with the word
    # UTC beside it -- not wrong, but the only Eastern-looking number on a
    # New York document, sitting four hours from every other time on it.
    # `eastern_datetime` carries its own zone, so the literal goes with it.
    gen_time = eastern_datetime(datetime.now(timezone.utc))
    
    # Reuse existing style constants
    TH = (
        'style="background-color:#1e293b;color:#ffffff;padding:10px 12px;'
        'text-align:left;font-weight:600;font-size:11px;text-transform:uppercase;'
        'letter-spacing:0.5px;" bgcolor="#1e293b"'
    )
    TD = 'style="padding:10px 12px;border-bottom:1px solid #e2e8f0;color:#334155;"'
    
    def section_title(text):
        return (
            '<table cellpadding="0" cellspacing="0" border="0" style="margin:28px 0 12px 0;">'
            '<tr><td style="font-size:16px;font-weight:600;color:#0A1929;'
            f'padding-bottom:8px;border-bottom:2px solid #e2e8f0;">{text}</td></tr></table>'
        )
    
    def bold_para(label, value):
        return f'<p style="color:#475569;margin:6px 0;"><strong style="color:#0A1929;">{label}:</strong> {value}</p>'
    
    def info_box(content):
        return (
            '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
            'style="margin:12px 0;"><tr><td style="background-color:#f1f5f9;'
            f'padding:16px;border-radius:8px;color:#334155;" bgcolor="#f1f5f9">{content}</td></tr></table>'
        )

    def sub_title(text):
        return f'<h3 style="color:#0A1929;margin:16px 0 8px;font-size:14px;">{text}</h3>'

    # ── ABSENT IS STATED, NEVER IMPLIED ──────────────────────────────────────
    # This renderer is read by a DOB inspector. A key the CP never filled must
    # never render as a VALUE — no invented "None", no silent "No". It renders
    # "— Not recorded", the same words generate_combined_report already prints
    # for the same fact (server.py:17486, :17553, :17612, :17696, :17862,
    # :17916, :17932). Two compliance surfaces must not disagree about one
    # record, and a blank is ambiguous: an inspector cannot tell whether the
    # field was never asked or asked and left unanswered.
    #
    # TWO KINDS OF ABSENCE, and they are NOT the same:
    #   (a) a FIELD missing from a section that IS being rendered
    #       -> "— Not recorded"
    #   (b) a ROW missing from a repeating list (load_entries,
    #       adjacent_buildings, slump_tests, osha entries)
    #       -> DROPPED, exactly as the combined report drops it. A row that
    #          does not exist is not an unrecorded field, and printing one
    #          would invent a record of work nobody logged.
    # A whole SECTION whose payload is entirely absent stays absent too — a
    # page of "— Not recorded" rows for a log that was never filled is the
    # same fabrication in a different direction.
    #
    # False and 0 ARE captured values and render as captured.
    #
    # THE LOCAL `NOT_RECORDED = "&mdash; Not recorded"` IS GONE. There were two
    # constants with the same name and DIFFERENT literals -- this one and the
    # module-level `"— Not recorded"` -- so the same absence read one way
    # on the per-logbook PDF and another on the combined report, and each had a
    # test pinning its own spelling. The module-level one wins because it is
    # tied to the device: test_weather_display_and_chip_trade pins it against
    # `fNotRecorded` in en.js, on the rule that one record must read the same in
    # the app and in the PDF. The entity and the character render identically.

    def has(d, key):
        if not isinstance(d, dict) or key not in d:
            return False
        v = d[key]
        if isinstance(v, bool):
            return True
        if v is None:
            return False
        if isinstance(v, str):
            return v.strip() != ""
        if isinstance(v, (list, dict, tuple, set)):
            return len(v) > 0
        return True

    _raw = lambda v: v
    _yn = lambda v: "Yes" if v else "No"

    def field_lines(d, specs):
        """[(key, label, fmt)] -> one info_box line per spec, ALWAYS.

        Case (a): a key the CP never filled still gets its line, reading
        "— Not recorded". The label is on the form either way, so a silent
        omission would hide which questions went unanswered.

        The one exception is the whole-section case: if NOT ONE of the specs
        is on the document there is no section to annotate, and the box is not
        rendered at all rather than fabricating a full page of absences.
        """
        if not any(has(d, key) for key, *_rest in specs):
            return []
        out = []
        for key, label, fmt in specs:
            val = fmt(d.get(key)) if has(d, key) else NOT_RECORDED
            out.append(f'<strong style="color:#0A1929;">{label}:</strong> {val}')
        return out

    def maybe_info_box(lines):
        return info_box("<br />".join(lines)) if lines else ""

    def rows_table(headers, rows_html):
        head = "".join(f'<th {TH}>{h}</th>' for h in headers)
        return (
            '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
            'style="border-collapse:collapse;margin:12px 0;font-size:13px;">'
            f'<tr>{head}</tr>{rows_html}</table>'
        )

    def cell(v):
        """A cell inside a row that EXISTS — case (b) territory.

        An empty cell stays empty. The ROW is the record here, and the
        combined report prints a bare em-dash in the same place
        (server.py:17562-17565); neither form asserts a value.
        """
        return f'<td {TD}>{"" if v is None else v}</td>'

    def key_label(k):
        """Fallback label for a map key the label list does not know.

        A snake_case key becomes Title Case. Anything else is rendered VERBATIM
        — the kiosk keys its orientation checklist by the item's full English
        sentence (backend/checkin.html:674-687, 1574-1579), and title-casing a
        sentence turns a compliance line into nonsense.
        """
        s = str(k)
        return s.replace("_", " ").title() if ("_" in s or " " not in s) else s

    def toggle_map_rows(m, items):
        """Rows for a sparse toggle map — case (a) over a FIXED checklist.

        The editors seed these maps as {} and write a key only once the CP taps
        it, so `key present and False` is an explicit No while `key absent` is
        untouched. An untouched item reads "— Not recorded", never a silent
        "No" — the same convention generate_combined_report uses for these
        exact checklists (server.py:17482-17487, :17549-17554, :17912-17917).

        The full checklist is only asserted once the map is keyed the way the
        in-app editor keys it. The kiosk keys its orientation checklist by the
        item's full English SENTENCE (backend/checkin.html:674-687), so a map
        carrying none of the known keys renders only what it carries — listing
        18 snake_case items as unrecorded against a kiosk document would be a
        finding about a form that was never used.
        """
        if not isinstance(m, dict) or not m:
            return ""
        labels = dict(items)
        known_present = [k for k, _ in items if k in m]
        ordered = [k for k, _ in items] if known_present else []
        ordered += [k for k in m.keys() if k not in labels]
        rows = ""
        for k in ordered:
            val = _yn(m.get(k)) if k in m else NOT_RECORDED
            rows += (f'<tr><td {TD}>{labels.get(k) or key_label(k)}</td>'
                     f'<td {TD}>{val}</td></tr>')
        return rows

    def toggle_block(d, key, items, title, col_label):
        """A titled table for a sparse toggle map. An absent/empty map is a
        whole absent SECTION and renders nothing at all."""
        rows = toggle_map_rows(d.get(key), items)
        if not rows:
            return ""
        return sub_title(title) + rows_table([col_label, "Confirmed"], rows)

    # Build type-specific content
    body_html = ""
    type_title = ""

    # Top-level attestation, shared by every branch below. Rendered only when
    # it is actually on the document.
    cp_name_line = (
        bold_para("CP", _capitalize_first(logbook.get("cp_name") or ""))
        if logbook.get("cp_name") else ""
    )
    cp_sig_block = render_signature_html(logbook.get("cp_signature"), "CP Signature")

    if log_type == "daily_jobsite":
        type_title = "Daily Jobsite Log (NYC DOB 3301-02)"
        weather_str = _display_weather(data)
        
        # Activities table
        act_rows = ""
        for i, act in enumerate(data.get("activities", [])):
            act_rows += (
                # PR G: crew/company/location are short-entry (capitalize first);
                # work description is prose (sentence case). num_workers excluded.
                # crew_id, NOT crew_name. The CP types a crew IDENTIFIER
                # (daily_jobsite.jsx EMPTY_ACTIVITY `crew_id`, and the auto-seed
                # writes `C1`, `C2`, ...). Nothing in the repo has ever written
                # crew_name, so this column rendered empty on every record while
                # generate_combined_report read the same row correctly.
                f'<tr><td {TD}>{_capitalize_first(act.get("crew_id", ""))}</td>'
                f'<td {TD}>{_capitalize_first(_display_sub_company(act.get("company")))}</td>'
                f'<td {TD}>{_headcount_cell(act, blank="0")}</td>'
                f'<td {TD}>{_sentence_case(act.get("work_description", "N/A"))}</td>'
                f'<td {TD}>{_capitalize_first(act.get("work_locations", ""))}</td></tr>'
            )
        
        equip = data.get("equipment_on_site", {})
        equip_list = ", ".join(k.replace("_", " ").title() for k, v in equip.items() if v)
        chk = data.get("checklist_items", {})
        check_list = _display_inspections(chk)
        
        # Observations
        obs_html = ""
        obs_rows = ""
        for obs in data.get("observations", []):
            if obs.get("description", "").strip():
                obs_rows += (
                    # description/remedy prose; responsible party short-entry.
                    f'<tr><td {TD}>{_sentence_case(obs.get("description", ""))}</td>'
                    f'<td {TD}>{_capitalize_first(obs.get("responsible_party", ""))}</td>'
                    f'<td {TD}>{_sentence_case(obs.get("remedy", ""))}</td></tr>'
                )
        if obs_rows:
            obs_html = (
                '<h3 style="color:#0A1929;margin:16px 0 8px;">Safety Observations</h3>'
                '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
                'style="border-collapse:collapse;font-size:13px;">'
                f'<tr><th {TH}>Description</th><th {TH}>Responsible</th><th {TH}>Remedy</th></tr>'
                + obs_rows + '</table>'
            )
        
        cp_sig = render_signature_html(logbook.get("cp_signature"), "CP Signature")
        sup_sig = render_signature_html(data.get("superintendent_signature"), "Superintendent")
        visitors = data.get("visitors_deliveries", "")

        # ── THE PERMANENT "N/A" IS GONE ──────────────────────────────────────
        #
        # This printed `Time In: N/A   Time Out: N/A` on EVERY daily jobsite
        # log ever rendered, because nothing in the app has ever written those
        # two keys -- daily_jobsite.jsx held the state and hydrated it and no
        # control set it. As of the picker work the state, the payload keys and
        # the hydrate are all deleted from the screen, so nothing will write
        # them again and the row could only ever say N/A.
        #
        # CONDITIONAL RATHER THAN DELETED, and the difference matters on a
        # signed record. A log filed BEFORE the U1 rebuild may carry real
        # times; deleting the row outright would remove them from a document
        # that has already been signed and read. Printed only when a value is
        # actually there, an old log still shows what it said and a new one
        # shows nothing at all.
        #
        # AND IT IS THE SAME RULE generate_combined_report ALREADY APPLIES,
        # deliberately: TheTwoRenderersAgreeOnAnEmptyRow in
        # backend/tests/test_report_six_defects.py exists because this pair has
        # drifted twice before. Deleting here while the report stayed
        # conditional would have been a third drift, on the same field.
        _t_in = str(data.get("time_in") or "").strip()
        _t_out = str(data.get("time_out") or "").strip()
        _times_line = (
            f'<strong style="color:#0A1929;">Time In:</strong> {_t_in or NOT_RECORDED}'
            f' &nbsp;&nbsp; <strong style="color:#0A1929;">Time Out:</strong> '
            f'{_t_out or NOT_RECORDED}<br />'
        ) if (_t_in or _t_out) else ""

        body_html = (
            info_box(
                f'<strong style="color:#0A1929;">Weather:</strong> {weather_str}<br />'
                f'<strong style="color:#0A1929;">Description:</strong> {_sentence_case(data.get("general_description") or NOT_RECORDED)}<br />'
                f'{_times_line}'
                f'<strong style="color:#0A1929;">Areas Visited:</strong> {_capitalize_first(data.get("areas_visited") or "N/A")}'
            )
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:12px 0;font-size:13px;">'
            # "CP's count", not "Workers". This number is HAND-TYPED by the CP
            # on the crew row (activities[].num_workers); page 1's headcount is
            # counted at the GATE from check-ins. They disagree — 4 here, 3 there
            # — and both are true statements about different things. Labelled at
            # the point of use rather than reconciled: a CP who counts four men
            # on his crew and a turnstile that recorded three are each reporting
            # something real, and silently picking one would delete a fact.
            + f'<tr><th {TH}>Crew</th><th {TH}>Company</th><th {TH}>CP&#39;s count</th>'
              f'<th {TH}>Description</th><th {TH}>Location</th></tr>'
            + (act_rows or f'<tr><td colspan="5" {TD}>—</td></tr>')
            + '</table>'
            + bold_para("Equipment", equip_list or "None")
            + bold_para("Inspected", check_list or "None")
            + obs_html
            + (bold_para("Visitors / Deliveries", _sentence_case(visitors)) if visitors else "")
            + bold_para("CP", _capitalize_first(logbook.get("cp_name", "N/A")))
            + cp_sig + sup_sig
        )
    
    elif log_type == "toolbox_talk":
        type_title = "Tool Box Talk"
        topics = data.get("checked_topics", {})
        topic_list = ", ".join(k.replace("_", " ").title() for k, v in topics.items() if v)
        
        att_rows = ""
        for a in data.get("attendees", []):
            # AN ATTENDEE WITH NO NAME IS NOT AN ATTENDEE. A seed row the CP
            # never filled printed here as a blank line carrying Present ✓ and
            # Confirmed at gate ✓ — a man who was at the talk, was marked
            # present by the CP, tapped confirm himself, and cannot be
            # identified by anybody reading the signed attendance record. Same
            # rule the pre-shift sheet, the OSHA register and the combined
            # report apply; this table was the last one without it.
            if not str(a.get("name") or "").strip():
                continue
            # TWO COLUMNS ARE GONE FROM THIS TABLE, AND NEITHER FIELD IS.
            #
            # "Present" printed `signed` and "Confirmed" printed
            # `gate_confirmed`. Neither is a legal attestation -- the CP's
            # signature over the whole roster is (NYC DOB §3301.12.3 / OSHA
            # 1926.21) -- and two tick columns beside it invited exactly the
            # reading that signature already forecloses: that each man
            # individually attested to something. "Added by" stays, because
            # WHOSE CLAIM PUT HIM ON THE SHEET is the provenance question a
            # reader of an attendance record actually has.
            #
            # THE FIELDS STAY IN STORAGE, unchanged, and toolboxTalkModel.js is
            # untouched. Dropping a COLUMN is a rendering change; dropping a
            # FIELD is a data change, and the operator is not making that one.
            # Both are still written at the gate and both are still read --
            # `signed` by app/site/logbooks.jsx, `gate_confirmed` by anything
            # that queries the stored document.
            att_rows += (
                f'<tr><td {TD}>{_capitalize_first(a.get("name", ""))}</td>'
                f'<td {TD}>{_capitalize_first(a.get("title", ""))}</td>'
                f'<td {TD}>{_capitalize_first(a.get("company", ""))}</td>'
                f'<td {TD}>{_roster_clock(a.get("time"))}</td>'
                f'<td {TD}>{_attendee_source_label(a)}</td></tr>'
            )

        tb_sig = render_signature_html(logbook.get("cp_signature"), "CP Signature")

        # PR G: location/company/performed-by/cp are short-entry; time excluded;
        # topics are enum labels already title-cased.
        body_html = (
            info_box(
                f'<strong style="color:#0A1929;">Location:</strong> {_capitalize_first(data.get("location", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Company:</strong> {_capitalize_first(data.get("company_name", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Performed By:</strong> {_capitalize_first(data.get("performed_by", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Time:</strong> {data.get("meeting_time", "N/A")}'
            )
            + bold_para("Topics", topic_list or "None")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:12px 0;font-size:13px;">'
            + f'<tr><th {TH}>Name</th><th {TH}>Title</th><th {TH}>Company</th><th {TH}>In</th><th {TH}>Added by</th></tr>'
            + (att_rows or f'<tr><td colspan="5" {TD}>—</td></tr>')
            + '</table>'
            + bold_para("CP", _capitalize_first(logbook.get("cp_name", "N/A")))
            + tb_sig
        )
    
    elif log_type == "preshift_signin":
        type_title = "Pre-Shift Sign-In"
        workers = data.get("workers", [])
        # ONE RESOLUTION FOR THE WHOLE ROSTER, and the SAME one the combined
        # report does — two renderers print this sheet and a man who reads as
        # signed on one and unsigned on the other is worse than either alone.
        _ps_sigs = await _resolve_signin_signatures(workers)
        # THE SAME OVERLAY AS THE COMBINED REPORT. Two renderers print this
        # sheet, and a document that says AFFIRMED in one and NOT AFFIRMED in
        # the other is worse than one that is wrong in both.
        # A COUNT FOR THE FOOTER, not an overlay onto a man's row.
        _affirm_n = await preshift_affirmation_count(
            db, logbook.get("project_id"), logbook.get("date"))

        w_rows = ""
        for w in workers:
            # `.get("name", "")` RETURNS THE DEFAULT ONLY ON AN ABSENT KEY.
            # A row storing `name: None` — which is exactly what correcting a
            # worker called "null" produces — returns None, and None.strip()
            # raises AttributeError. In a renderer, that does not skip a row:
            # it takes down the WHOLE PDF, so a data fix meant to clean one
            # name would have stopped every filed roster from printing.
            #
            # The safe form is already used twice in these same two functions
            # (`if not str(a.get("name") or "").strip()` on the attendee rows).
            # Shipped, not invented.
            if str(w.get("name") or "").strip():
                # PR G: name/company short-entry; osha_number excluded (identifier).
                # `or ""` ON EVERY CELL, for the same reason as the guard
                # above: a stored None interpolates into an f-string as the
                # four characters None, and a filed compliance record printing
                # "None" for a man's employer is the same defect as printing
                # "null" for his name, one field over.
                w_rows += (
                    f'<tr><td {TD}>{_capitalize_first(w.get("name") or "")}</td>'
                    f'<td {TD}>{_capitalize_first(w.get("company") or "")}</td>'
                    f'<td {TD}>{w.get("osha_number") or ""}</td>'
                    f'<td {TD}>{answer_label(w.get("had_injury"))}</td>'
                    f'<td {TD}>{answer_label(w.get("inspected_ppe"))}</td>'
                    f'<td {TD}>{_preshift_signature_cell(w, _ps_sigs)}</td></tr>'
                )

        ps_sig = render_signature_html(logbook.get("cp_signature"), "CP Signature")

        # PR G: company/location short-entry; total count excluded (numeric).
        body_html = (
            info_box(
                f'<strong style="color:#0A1929;">Company:</strong> {_capitalize_first(data.get("company", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Location:</strong> {_capitalize_first(data.get("project_location", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Total Workers:</strong> {data.get("total_count", len(workers))}'
            )
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:12px 0;font-size:13px;">'
            + f'<tr><th {TH}>Name</th><th {TH}>Company</th><th {TH}>OSHA #</th>'
              f'<th {TH}>Injury</th><th {TH}>PPE</th><th {TH}>Signature</th></tr>'
            + (w_rows or f'<tr><td colspan="6" {TD}>—</td></tr>')
            + '</table>'
            + preshift_affirmation_footer(_affirm_n)
            # ABOVE the signature: the claim, then the name that makes it.
            + PRESHIFT_ATTESTATION_HTML
            + bold_para("CP", _capitalize_first(logbook.get("cp_name", "N/A")))
            + ps_sig
        )
    
    # ══════════════════════════════════════════════════════════════════════
    #  THE OTHER EIGHT TYPES
    #
    #  Until this block existed, every one of these fell to the `else` below
    #  and rendered a single "Status: submitted" line — a BLANK compliance
    #  record for hot work, crane, excavation, concrete, scaffold, the SSC
    #  daily log, the OSHA/SST log and subcontractor orientation.
    #
    #  Key names and section ordering follow generate_combined_report, which
    #  already renders all eight correctly; the payload keys themselves come
    #  from the editors that write them (cited per branch). Absence follows it
    #  too: a field missing from a rendered section reads "— Not recorded",
    #  and a missing ROW in a repeating list is dropped. One record must not
    #  read differently on two compliance surfaces.
    # ══════════════════════════════════════════════════════════════════════

    elif log_type == "hot_work":
        # frontend/src/utils/hotWorkModel.js — draftBody decides the payload
        # shape and PRECAUTION_ITEMS the seven keys and labels. The screen
        # (app/logbooks/hot_work.jsx) holds none of it. The list below is
        # duplicated here because this renderer has no access to that bundle;
        # frontend/src/utils/portedFormPayloads.test.cjs asserts the two agree,
        # key for key and word for word — the editor used to say "(35ft)" and
        # "Covered/Protected" where every reader printed "(35 ft)" and
        # "Covered / Protected", so the CP ticked one sentence and the
        # inspector read another.
        type_title = "Hot Work Permit"
        HW_PRECAUTIONS = [
            ("area_cleared", "Area Cleared of Combustibles (35 ft)"),
            ("fire_extinguisher_present", "Fire Extinguisher Present"),
            ("sprinklers_operational", "Sprinklers Operational"),
            ("combustibles_covered", "Combustibles Covered / Protected"),
            ("fire_watch_assigned", "Fire Watch Assigned"),
            ("ventilation_adequate", "Ventilation Adequate"),
            ("permit_posted", "Permit Posted at Location"),
        ]
        # The editor captures NO real fire-watch end time — it DERIVES
        # fire_watch_end_time as work end + 30 min
        # (hotWorkModel.calcFireWatchEnd).
        # FDNY can require 60, so it is labelled as the computed default it
        # is and never asserted as a recorded watch-until. It rides in the
        # spec list so an absent one reads "— Not recorded" like any other
        # field rather than vanishing.
        _fw_default = (
            lambda v: f'{v} <span style="color:#94a3b8;">(default: work end + 30 min)</span>'
        )
        hw_lines = field_lines(data, [
            ("work_type", "Work Type", _raw),
            ("location", "Location", _capitalize_first),
            ("worker_name", "Worker", _capitalize_first),
            ("worker_cert_number", "Worker Cert #", _raw),
            ("start_time", "Start Time", _raw),
            ("end_time", "End Time", _raw),
            ("fire_watch_name", "Fire Watch", _capitalize_first),
            ("fire_watch_end_time", "Fire Watch Until", _fw_default),
        ])
        body_html = (
            maybe_info_box(hw_lines)
            + toggle_block(data, "precautions", HW_PRECAUTIONS,
                           "Pre-Work Precautions", "Precaution")
            + cp_name_line + cp_sig_block
        )

    elif log_type == "crane_operations":
        # frontend/src/utils/craneOperationsModel.js — draftBody decides the
        # payload shape, PRE_OP_CHECKLIST_ITEMS the fifteen keys and labels,
        # EMPTY_LOAD_ENTRY the lift row. The screen (app/logbooks/
        # crane_operations.jsx) holds none of it. The list below is duplicated
        # here because this renderer has no access to that bundle;
        # frontend/src/utils/portedFormPayloads.test.cjs asserts the two agree,
        # key for key and word for word.
        type_title = "Crane Operations"
        CRANE_PREOP = [
            ("wire_ropes", "Wire Ropes Inspected"),
            ("hooks_latches", "Hooks & Latches Secure"),
            ("brakes", "Brakes Functional"),
            ("outriggers", "Outriggers Deployed"),
            ("load_chart", "Load Chart Available"),
            ("boom_condition", "Boom Condition OK"),
            ("anti_two_block", "Anti Two-Block Device"),
            ("fire_extinguisher", "Fire Extinguisher Present"),
            ("signals_reviewed", "Signals Reviewed"),
            ("area_barricaded", "Area Barricaded"),
            ("wind_speed_checked", "Wind Speed Checked"),
            ("power_lines_clear", "Power Lines Clear"),
            ("load_weight_known", "Load Weight Known"),
            ("rigging_inspected", "Rigging Inspected"),
            ("swing_radius_clear", "Swing Radius Clear"),
        ]
        # load_weight / radius are unit-less strings exactly as the operator
        # typed them — the editor captures no unit, so none is printed.
        load_rows = ""
        for le in (data.get("load_entries") or []):
            if not isinstance(le, dict):
                continue
            if not any(has(le, k) for k in ("time", "description", "load_weight", "radius")):
                continue      # an untouched EMPTY_LOAD_ENTRY seed, not a lift
            load_rows += (
                "<tr>"
                + cell(le.get("time"))
                + cell(_capitalize_first(le.get("description", "")))
                + cell(le.get("load_weight"))
                + cell(le.get("radius"))
                + "</tr>"
            )
        lift_html = (
            sub_title("Lift Log")
            + rows_table(["Time", "Description", "Load Weight", "Radius"], load_rows)
        ) if load_rows else ""
        body_html = (
            maybe_info_box(field_lines(data, [
                ("crane_type", "Crane Type", _capitalize_first),
                ("crane_id", "Crane ID", _raw),
                ("operator_name", "Operator", _capitalize_first),
                ("operator_license", "Operator License", _raw),
            ]))
            + toggle_block(data, "pre_operation_checklist", CRANE_PREOP,
                           "Pre-Operation Checklist", "Item")
            + lift_html
            + cp_name_line + cp_sig_block
        )

    elif log_type == "excavation_monitoring":
        # frontend/src/utils/excavationMonitoringModel.js — draftBody decides
        # the payload shape and is the ONE place `delta` and
        # vibration_over_threshold are derived, so the autosave, the flush and
        # the submit all write the same document. The screen
        # (app/logbooks/excavation_monitoring.jsx) holds none of it.
        type_title = "Excavation Monitoring"
        exc_lines = field_lines(data, [
            # excavation_depth is a raw number — the editor captures no unit.
            ("excavation_depth", "Excavation Depth", _raw),
            ("soil_type", "Soil Type", _raw),
            ("protection_system", "Protection System", _raw),
            ("groundwater_observed", "Groundwater Observed", _yn),
            ("atmospheric_testing", "Atmospheric Testing", _yn),
        ])
        # The over-threshold flag is only meaningful ALONGSIDE a reading. With
        # no reading the STATUS reads "— Not recorded" — a bare "Within
        # threshold" over no measurement is a finding the CP never made
        # (generate_combined_report does the same, server.py:17606-17612).
        # With neither reading there is no vibration section to annotate and
        # the whole block is dropped.
        v_thr = str(data.get("vibration_threshold") or "").strip()
        v_cur = str(data.get("vibration_current") or "").strip()
        vib_html = ""
        if v_thr or v_cur:
            if v_thr and v_cur and has(data, "vibration_over_threshold"):
                status = (
                    '<span style="color:#b45309;font-weight:600;">&#9888; Over threshold</span>'
                    if data.get("vibration_over_threshold") else "Within threshold"
                )
            else:
                status = NOT_RECORDED
            vib_lines = [
                f'<strong style="color:#0A1929;">Threshold:</strong> {v_thr or NOT_RECORDED}',
                f'<strong style="color:#0A1929;">Current:</strong> {v_cur or NOT_RECORDED}',
                f'<strong style="color:#0A1929;">Status:</strong> {status}',
            ]
            vib_html = sub_title("Vibration") + info_box("<br />".join(vib_lines))

        # Units and per-reading timestamps are NOT captured, so there is no
        # unit in the headers and no time column — readings render as entered.
        bld_rows = ""
        for b in (data.get("adjacent_buildings") or []):
            if not isinstance(b, dict):
                continue
            # A MONITORING POINT IS A BUILDING. The rule was any-of four, so a
            # row carrying a baseline and a current reading with NO ADDRESS
            # printed — vibration data attributed to no structure. Nobody can
            # act on it: the whole purpose of the log is telling the DOB which
            # adjacent building moved and by how much.
            #
            # THE SAME OWNER RULE the OSHA register, the toolbox roster, the
            # pre-shift sheet and the fall-protection log apply to a WORKER.
            # Here the thing that owns the row is an address.
            if not has(b, "address"):
                continue
            bld_rows += (
                "<tr>"
                + cell(_capitalize_first(b.get("address", "")))
                + cell(b.get("baseline_reading"))
                + cell(b.get("current_reading"))
                + cell(b.get("delta"))
                + "</tr>"
            )
        bld_html = (
            sub_title("Adjacent-Structure Monitoring Points")
            + rows_table(["Location", "Baseline", "Current", "Movement (&Delta;)"], bld_rows)
        ) if bld_rows else ""

        body_html = (
            maybe_info_box(exc_lines) + vib_html + bld_html
            + cp_name_line + cp_sig_block
        )

    elif log_type == "concrete_operations":
        # frontend/src/utils/concreteOperationsModel.js — draftBody decides the
        # payload shape, FORMWORK_ITEMS the four keys and labels,
        # EMPTY_SLUMP_TEST the slump row. The screen (app/logbooks/
        # concrete_operations.jsx) holds none of it. The list below is
        # duplicated here because this renderer has no access to that bundle;
        # frontend/src/utils/portedFormPayloads.test.cjs asserts the two agree,
        # key for key and word for word.
        type_title = "Concrete Operations"
        FORMWORK_ITEMS = [
            ("shores_plumb", "Shores Plumb"),
            ("bracing_adequate", "Bracing Adequate"),
            ("formwork_clean", "Formwork Clean"),
            ("no_gaps", "No Gaps"),
        ]
        slump_rows = ""
        for st in (data.get("slump_tests") or []):
            if not isinstance(st, dict):
                continue
            t = str(st.get("time", "")).strip()
            v = str(st.get("value", "")).strip()
            p = st.get("pass")
            if not t and not v and p is None:
                continue      # an untouched EMPTY_SLUMP_TEST seed
            # `pass` is TRI-STATE (EMPTY_SLUMP_TEST seeds it null). Null is
            # rendered as nothing — never as a Fail the CP did not record.
            if p is True:
                result = '<span style="color:#15803d;font-weight:600;">Pass</span>'
            elif p is False:
                result = '<span style="color:#b91c1c;font-weight:600;">Fail</span>'
            else:
                result = ""
            slump_rows += "<tr>" + cell(t) + cell(v) + cell(result) + "</tr>"
        slump_html = (
            sub_title("Slump Tests")
            + rows_table(["Time", "Slump", "Result"], slump_rows)
        ) if slump_rows else ""

        body_html = (
            maybe_info_box(field_lines(data, [
                ("pour_location", "Pour Location", _capitalize_first),
                ("concrete_supplier", "Supplier", _capitalize_first),
                ("mix_design", "Mix Design", _raw),
                # volume_ordered / temperature are unit-less as entered.
                ("volume_ordered", "Volume Ordered", _raw),
                ("weather_conditions", "Weather", _raw),
                ("temperature", "Temperature", _raw),
            ]))
            + slump_html
            + toggle_block(data, "formwork_checklist", FORMWORK_ITEMS,
                           "Formwork Inspection", "Item")
            + cp_name_line + cp_sig_block
        )

    elif log_type == "scaffold_maintenance":
        # frontend/app/logbooks/scaffold_maintenance.jsx:194
        #   const data = { general_info: generalInfo, answers };
        # GENERAL_INFO_FIELDS :27-36 + shed_type (:38, :89) and drawings_on_site
        # (:90); MAINTENANCE_QUESTIONS :41-61; ANSWER_OPTIONS :63 = YES/NO/N/A.
        type_title = "Scaffold Maintenance Inspection"
        gi = data.get("general_info") or {}
        answers = data.get("answers") or {}
        SCAFFOLD_QUESTIONS = [
            ("signs_on_parapets", "Are the signs on the parapets?"),
            ("base_plates_mudsills", "Are the base plates and mudsills secured?"),
            ("scaffold_pins_bolts", "Are the scaffold pins and bolts installed?"),
            ("legs_poles_plumb", "Are the legs and poles plumb, braced and not displaced?"),
            ("tie_ins_spaced", "Are tie-ins correctly spaced, properly secured and the correct amount?"),
            ("cross_braces", "Are cross braces fully attached, not bent, and not missing?"),
            ("pipe_clamps_tight", "Are pipe clamps tight?"),
            ("window_jacks_tight", "Are window jacks tight?"),
            ("planks_secured", "Are all the planks secured?"),
            ("decking_planks_condition", "Are decking and planks in good condition?"),
            ("deck_fully_planked", "Is deck fully planked?"),
            ("gaps_open_spaces", "Are there gaps or open spaces on decking?"),
            ("guardrails_toe_boards", "Are the guardrails and toe boards secured at all places where required?"),
            ("netting_extension", "Is the netting extension of full length and height?"),
            ("netting_secured", "Is the netting secured?"),
            ("parapet_height", "Is the parapet the proper height and secured?"),
            ("lights_working", "Are the lights working?"),
            ("deck_clean", "Is the deck clean and free of debris?"),
            ("drawings_on_site", "Drawings on site for inspection?"),
        ]
        # Answers are YES / NO / N/A strings, not booleans — an N/A the CP
        # CHOSE is a real answer and is rendered as chosen. An UNANSWERED
        # question reads "— Not recorded", never a silent "NO", matching
        # generate_combined_report (server.py:17694-17697). If the form was
        # never answered at all there is no checklist to annotate and the
        # table is dropped.
        q_labels = dict(SCAFFOLD_QUESTIONS)
        q_answered = [k for k, _ in SCAFFOLD_QUESTIONS if has(answers, k)]
        q_order = [k for k, _ in SCAFFOLD_QUESTIONS] if q_answered else []
        q_order += [k for k in answers.keys() if k not in q_labels and has(answers, k)]
        q_rows = ""
        for k in q_order:
            q_rows += (f'<tr><td {TD}>{q_labels.get(k) or key_label(k)}</td>'
                       f'<td {TD}>{answers.get(k) if has(answers, k) else NOT_RECORDED}</td></tr>')
        q_html = (
            sub_title("Inspection Checklist")
            + rows_table(["Question", "Answer"], q_rows)
        ) if q_rows else ""

        # general_info.drawings_on_site is a dead duplicate of the answers
        # question of the same key — only the answer is rendered.
        body_html = (
            maybe_info_box(field_lines(gi, [
                ("scaffold_erector", "Scaffold Erector", _capitalize_first),
                ("renters_name", "Renter", _capitalize_first),
                ("permit_number", "Permit #", _raw),
                ("phone", "Phone #", _raw),
                ("installation_date", "Installation Date", _raw),
                ("expiration_date", "Expiration", _raw),
                ("scaffold_height", "Scaffold Height", _raw),
                ("num_platforms", "Platforms Decked", _raw),
                ("shed_type", "Shed Type", _raw),
            ]))
            + q_html
            + cp_name_line + cp_sig_block
        )

    elif log_type == "ssc_daily_safety_log":
        # frontend/src/utils/sscDailySafetyLogModel.js — draftBody decides the
        # payload shape, COMPLIANCE_FLAGS the five keys and labels and
        # NARRATIVE_FIELDS the three prompts. The screen
        # (app/logbooks/ssc_daily_safety_log.jsx) holds none of it. Both lists
        # below are duplicated here because this renderer has no access to that
        # bundle; frontend/src/utils/portedFormPayloads.test.cjs asserts they
        # agree, key for key and word for word.
        type_title = "SSC Daily Safety Log"
        SSC_FLAGS = [
            ("incidents_reported", "Incidents Reported"),
            ("safety_meetings_held", "Safety Meetings Held"),
            ("fire_protection_in_place", "Fire Protection in Place"),
            ("housekeeping_satisfactory", "Housekeeping Satisfactory"),
            ("ppe_compliance", "PPE Compliance"),
        ]
        # The five are a fixed list: once ANY of them is on the document the
        # rest read "— Not recorded" rather than dropping out of the table.
        # (generate_combined_report prints "No" for an absent flag here,
        # server.py:17856-17857 — this renderer will not assert a negative
        # finding from a key that is not on the record.)
        flag_rows = ""
        if any(has(data, key) for key, _ in SSC_FLAGS):
            for key, label in SSC_FLAGS:
                val = _yn(data.get(key)) if has(data, key) else NOT_RECORDED
                flag_rows += f'<tr><td {TD}>{label}</td><td {TD}>{val}</td></tr>'
        # These five are ToggleRows seeded false, so a rendered "No" may be an
        # untouched default rather than a deliberate negative finding. Say so —
        # a bare "No" must not read as an affirmative safety-violation
        # attestation on a DOB record.
        flags_html = (
            sub_title("Compliance")
            + rows_table(["Item", "Status"], flag_rows)
            + '<p style="color:#94a3b8;font-size:11px;font-style:italic;margin:2px 0 0;">'
              'Compliance items default to "No" if not explicitly set by the reviewer.</p>'
        ) if flag_rows else ""

        # An unwritten narrative reads "— Not recorded", never an asserted
        # "none" that could pass for a negative finding the CP never made
        # (generate_combined_report, server.py:17859-17862). All three go
        # together: once the narrative section exists, every prompt on it is
        # accounted for.
        NARRATIVE_FIELDS = (
            ("site_conditions", "Site Conditions"),
            ("safety_violations_observed", "Safety Violations Observed"),
            ("corrective_actions_taken", "Corrective Actions Taken"),
        )
        # Incident detail is only meaningful when an incident was reported —
        # but if one WAS, a missing detail is an unanswered question, not
        # silence.
        show_incident = bool(data.get("incidents_reported"))
        narrative = ""
        if show_incident or any(has(data, k) for k, _ in NARRATIVE_FIELDS):
            for key, label in NARRATIVE_FIELDS:
                val = _sentence_case(data.get(key)) if has(data, key) else NOT_RECORDED
                narrative += bold_para(label, val)
            if show_incident:
                detail = (
                    _sentence_case(data.get("incident_details"))
                    if has(data, "incident_details") else NOT_RECORDED
                )
                narrative += bold_para("Incident Details", detail)
        narrative_html = (sub_title("Narrative") + narrative) if narrative else ""

        body_html = (
            maybe_info_box(field_lines(data, [
                ("project_address", "Project Address", _capitalize_first),
                ("ssp_number", "Site Safety Plan #", _raw),
                ("weather", "Weather", _raw),
                ("workers_on_site_count", "Workers on Site", _raw),
            ]))
            + flags_html
            + narrative_html
            + cp_name_line
            + render_signature_html(logbook.get("cp_signature"), "SSC / SSM Signature")
        )

    elif log_type == "fall_protection":
        # frontend/src/utils/fallProtectionModel.js — draftBody writes
        # { activities: rows }, and each row carries the keys below.
        #
        # THE ROWS LIVE UNDER `activities` because get_logbook_activity_photo —
        # the ONE production read of a logbook photo — indexes
        # data.activities[ai].photos[pi]. Anywhere else means either no photos
        # on the report or a second photo reader, and a second reader is how a
        # record and its photos drift apart (device round 6, item 5).
        type_title = "Fall Protection Equipment Log"
        fp_rows = ""
        for r in (data.get("activities") or []):
            if not isinstance(r, dict):
                continue
            # A ROW THAT NAMES NOBODY IS NOT A ROW — the Group 1 rule. Here the
            # claim is that a man's fall-arrest equipment was inspected, so a
            # nameless row asserts it about somebody the record cannot name.
            if not has(r, "worker_name"):
                continue
            result = str(r.get("result") or "").strip()
            if result == "Pass":
                result_cell = '<span style="color:#15803d;font-weight:600;">Pass</span>'
            elif result == "Fail":
                result_cell = '<span style="color:#b91c1c;font-weight:600;">Fail</span>'
            elif result:
                # "Removed from service" — a stronger statement than Fail, and
                # a different one. Printed as recorded, never collapsed into it.
                result_cell = (
                    '<span style="color:#b91c1c;font-weight:700;">'
                    + _capitalize_first(result) + '</span>'
                )
            else:
                # TRI-STATE, seeded null. An inspection nobody performed must
                # never print as a Pass.
                result_cell = NOT_RECORDED
            impact = r.get("impact_loaded")
            # Same three states. A silent "No" here is the answer that keeps
            # impact-loaded equipment in service (1926.502(d)(19)).
            impact_cell = (NOT_RECORDED if impact is None
                           else ("Yes" if impact else "No"))
            fp_rows += (
                "<tr>"
                + cell(_capitalize_first(r.get("worker_name", "")))
                + cell(_capitalize_first(r.get("company", "")))
                + cell(_capitalize_first(r.get("equipment_type", "")))
                # equipment_id is the manufacturer's marking — an identifier,
                # rendered raw. So is the date, as entered.
                + cell(r.get("equipment_id"))
                + cell(r.get("manufacture_date"))
                + cell(result_cell)
                + cell(impact_cell)
                + cell(_sentence_case(r.get("defect_found") or ""))
                + cell(_sentence_case(r.get("action_taken") or ""))
                + cell(_capitalize_first(r.get("anchor_point", "")))
                + "</tr>"
            )
        body_html = (
            (rows_table(
                ["Worker", "Company", "Equipment", "ID / Serial", "Mfg Date",
                 "Result", "Impact Loaded", "Defect", "Action Taken", "Anchor"],
                fp_rows) if fp_rows else "")
            + cp_name_line + cp_sig_block
            # WHAT THIS DOCUMENT IS, printed on the document itself. A reader
            # who finds it in a compliance packet must not take it for a
            # required filing, and the packet is exactly where it will be found.
            + '<p style="color:#64748b;font-size:11px;line-height:1.6;'
              'margin:18px 0 0;border-top:1px solid #e2e8f0;padding-top:10px;">'
            + FALL_PROTECTION_NOTICE + '</p>'
        )

    elif log_type == "site_superintendent_log":
        # THE SAME BUILDER THE COMBINED REPORT USES. The OSHA register and the
        # pre-shift sheet each drifted between these two renderers and each had
        # to be pulled back into one definition; this one never forks.
        type_title = "Construction Superintendent Log (BC 3301.13.13)"
        _cs_attr = await cs_attribution_for(
            db, logbook.get("project_id"), logbook.get("date"),
            (data or {}).get("presence") or {})
        body_html = _superintendent_log_html(logbook, attribution=_cs_attr)

    elif log_type == "osha_log":
        # frontend/app/logbooks/osha_log.jsx:200  data: { entries };
        # EMPTY_ENTRY :28-37.
        #
        # NOTE vs generate_combined_report: that renderer adds a Review column
        # by joining each row back to the worker's LIVE certifications. That is
        # a database read, not a payload key, and this function renders one
        # stored document — the snapshot is rendered as stored, with no
        # invented review state.
        type_title = "OSHA / SST Certification Log"
        osha_rows = ""
        for e in (data.get("entries") or []):
            if not isinstance(e, dict):
                continue
            # AN ENTRY WITH NO WORKER IS NOT AN ENTRY. This read five fields
            # any-of and printed a row that carried only a card number — a
            # certification on a signed register belonging to nobody named.
            # Same rule as _SUBMIT_ROW_CONTENT_RULES["osha_log"], the combined
            # report and entriesForFiling on the device; the untouched
            # EMPTY_ENTRY seed it used to catch has no name either and is still
            # dropped here.
            if not any(has(e, k) for k in
                       ("worker_name",)):
                continue      # a row that names nobody
            # card_number / expiration are identifiers — rendered raw.
            osha_rows += (
                "<tr>"
                + cell(_capitalize_first(e.get("worker_name", "")))
                + cell(_capitalize_first(e.get("company", "")))
                + cell(_osha_type_cell(e))
                + cell(e.get("card_number"))
                + cell(e.get("expiration"))
                # LEFT AS IT IS, DELIBERATELY, AND THE CENSUS ENTRY STAYS OPEN.
                # This column and its twin in the combined report spell "not
                # signed" differently -- empty here, "&mdash;" there. Both
                # attempts to unify them broke a documented rule of the
                # document they were moved into: a bare "&mdash;" is banned in
                # THIS renderer as indistinguishable from a placeholder, and
                # "&mdash; Not recorded" is wrong on a REGISTER, whose own rule
                # is that "the row is the record, and there is no unanswered
                # form field" -- an absent tick is not an unanswered question.
                # The divergence is cosmetic; breaking either convention to end
                # it is not an improvement. Recorded rather than forced.
                + cell("&#10003;" if e.get("signed") else "")
                + "</tr>"
            )
        body_html = (
            (rows_table(["Worker", "Company", "Cert Type", "Card #", "Expiration", "Signed"],
                        osha_rows) if osha_rows else "")
            # ABOVE the signature, on BOTH renderers. This is the document an
            # inspector asks for by name; it carries the same CP signature over
            # the same register, so it must make the same claim. The Review
            # column is deliberately absent here (see the note above) and the
            # sentence says nothing about it.
            + OSHA_LOG_ATTESTATION_HTML
            + cp_name_line + cp_sig_block
        )

    elif log_type == "subcontractor_orientation":
        # ONE DOCUMENT PER WORKER (server.py:14945 comment). Payload keys:
        #   frontend/app/logbooks/subcontractor_orientation.jsx:472-483 (manual
        #   entry) and backend/server.py:9900-9912 (the kiosk registration
        #   path), which write the same field names.
        # Checklist labels: ORIENTATION_SECTIONS, subcontractor_orientation.jsx:49-87.
        type_title = "Subcontractor Safety Orientation"
        ORIENTATION_ITEMS = [
            ("hard_hats", "Hard hats required at all times on site"),
            ("safety_boots", "Safety boots required (steel toe, ANSI rated)"),
            ("safety_glasses", "Safety glasses / eye protection required"),
            ("high_vis", "High-visibility vest required near traffic"),
            ("no_horseplay", "No horseplay, running, or unsafe behavior"),
            ("report_hazards", "Report all hazards to CP immediately"),
            ("fall_protection_required", "Fall protection required at 6 ft and above"),
            ("harness_inspection", "Inspect harness before each use"),
            ("ladder_safety", "Three-point contact on ladders at all times"),
            ("scaffold_rules", "Only use scaffold as erected — no modifications"),
            ("emergency_exits", "Emergency exit locations reviewed"),
            ("first_aid", "First aid kit location reviewed"),
            ("emergency_contact", "Emergency contact numbers provided"),
            ("incident_reporting", "All incidents must be reported immediately"),
            ("no_drugs_alcohol", "Zero tolerance for drugs and alcohol on site"),
            ("sign_in_out", "Must sign in and out every day"),
            ("authorized_areas", "Only enter authorized work areas"),
            ("housekeeping", "Keep work area clean at all times"),
        ]
        orient_lines = field_lines(data, [
            ("worker_name", "Worker", _capitalize_first),
            ("worker_trade", "Trade", _capitalize_first),
            ("worker_company", "Company", _capitalize_first),
            ("osha_number", "OSHA / SST #", _raw),
            ("orientation_number", "Orientation #", _raw),
            ("language_provided", "Language Provided", _raw),
            ("completed_at", "Completed",
             lambda v: str(v)[:19].replace("T", " ")),
        ])

        # The kiosk writes {checked: bool, checked_at: iso} per item and keys it
        # by the item's full English sentence (backend/checkin.html:674-687,
        # 1574-1579); the in-app editor writes key -> bool. Both shapes render.
        # An item the editor's map does not carry reads "— Not recorded"; a map
        # keyed the kiosk way carries none of the known keys, so it renders only
        # its own sentences (see toggle_map_rows).
        checklist = data.get("checklist")
        chk_rows = ""
        if isinstance(checklist, dict) and checklist:
            labels = dict(ORIENTATION_ITEMS)
            known_present = [k for k, _ in ORIENTATION_ITEMS if k in checklist]
            order = [k for k, _ in ORIENTATION_ITEMS] if known_present else []
            order += [k for k in checklist.keys() if k not in labels]
            for k in order:
                if k not in checklist:
                    val = NOT_RECORDED
                else:
                    v = checklist.get(k)
                    checked = bool(v.get("checked")) if isinstance(v, dict) else bool(v)
                    # A tick against the word "No" mixed a glyph with a word
                    # in one column. Both words now, through the one helper.
                    val = answer_label(checked)
                chk_rows += (
                    f'<tr><td {TD}>{labels.get(k) or key_label(k)}</td>'
                    f'<td {TD}>{val}</td></tr>'
                )
        chk_html = (
            sub_title("Safety Topics Reviewed")
            + rows_table(["Topic", "Reviewed"], chk_rows)
        ) if chk_rows else ""

        # LOAD-BEARING: worker_signature is written as null on manual entries
        # (subcontractor_orientation.jsx:481). When the key is THERE and empty,
        # say UNSIGNED — an unattested acknowledgment must never be presented
        # as complete. When the key is absent entirely, say nothing.
        worker_sig_html = ""
        if "worker_signature" in data:
            if data.get("worker_signature"):
                worker_sig_html = render_signature_html(
                    data.get("worker_signature"), "Worker Acknowledgment",
                )
            else:
                worker_sig_html = (
                    '<p style="color:#b91c1c;font-weight:700;margin:6px 0;">'
                    'Worker acknowledgment: UNSIGNED</p>'
                )

        body_html = (
            maybe_info_box(orient_lines)
            + chk_html
            + worker_sig_html
            + cp_name_line
            + render_signature_html(logbook.get("cp_signature"), "Conducted By (CP)")
        )

    else:
        type_title = log_type.replace("_", " ").title()
        body_html = bold_para("Status", logbook.get("status", "N/A"))

    # Wrap in full HTML document
    html = f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>{type_title} — {project_name} — {date}</title>
<style>body{{font-family:Arial,sans-serif;margin:0;padding:0;color:#334155;background:#fff;}}
table{{border-collapse:collapse;}}

/* PRINT / PDF. Ported from generate_combined_report -- see this function's
   docstring for why it was missing: the combined report fixed the 680px dead
   strip on an A4 page and nobody carried the fix to the other renderer of the
   same records. Only h3 and tr appear below because those are the only
   selectors this renderer actually emits; the combined report's h2 and
   .doc-section rules have nothing here to match. */
@page {{ size: A4; margin: 12mm; }}
@media print {{
  .wrapper {{ width: 100% !important; max-width: 100% !important; }}

  /* A HEADING MUST NOT BE THE LAST THING ON A PAGE. A sub-head alone at the
     foot of a sheet with its content overleaf is the shape a reader takes
     for a truncated document. */
  h3 {{ page-break-after: avoid; break-after: avoid-page; }}

  /* NEVER SPLIT A ROW. A man's name on one sheet and his check-in time on
     the next is not a roster entry.

     BUT NOT THE THREE SHELL ROWS, AND THIS IS THE HALF THE COMBINED REPORT
     GOT WRONG. This document's outer table is an email-style layout shell:
     header row, ONE content row holding the entire body, footer row. An
     unqualified `tr` rule matches that content row, so WeasyPrint refuses to
     split the whole document and relocates it to a fresh sheet -- leaving
     page 1 carrying nothing but the header. That is measured, not predicted:
     on the combined report, whose shell is the same shape, deleting this one
     rule moved a 461px section off page 2 and back onto page 1.

     The rule is wanted for the roster tables NESTED inside the content cell
     and for nothing else, so the shell rows opt out by class rather than by
     a `> tbody >` combinator that depends on where the parser puts an
     anonymous tbody. */
  tr {{ page-break-inside: avoid; break-inside: avoid; }}
  tr.shell {{ page-break-inside: auto; break-inside: auto; }}

  /* One line of a paragraph stranded by itself reads as a fragment. */
  p, li {{ orphans: 3; widows: 3; }}
}}
</style></head>
<body style="margin:0;padding:0;background-color:#ffffff;">
<table cellpadding="0" cellspacing="0" border="0" width="100%" class="wrapper" style="max-width:700px;margin:0 auto;">
<tr class="shell"><td style="background-color:#0A1929;padding:24px 40px;color:#fff;" bgcolor="#0A1929">
<span style="font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#60a5fa;">LEVELOG</span><br/>
<span style="font-size:20px;font-weight:600;">{type_title}</span><br/>
<span style="font-size:13px;color:#94a3b8;">{project_name} — {project_address}</span>
<table cellpadding="0" cellspacing="0" border="0" style="margin-top:12px;"><tr>
<td style="padding-right:24px;vertical-align:top;"><span style="font-size:10px;text-transform:uppercase;color:#64748b;">DATE</span><br/><span style="font-size:15px;color:#fff;">{date}</span></td>
<td style="vertical-align:top;"><span style="font-size:10px;text-transform:uppercase;color:#64748b;">STATUS</span><br/><span style="font-size:15px;color:#fff;">{logbook.get("status", "N/A").upper()}</span></td>
</tr></table>
</td></tr>
<tr class="shell"><td style="padding:24px 40px;background-color:#ffffff;" bgcolor="#ffffff">
{section_title(type_title)}
{body_html}
</td></tr>
<tr class="shell"><td style="background-color:#f8fafc;padding:24px 40px;text-align:center;border-top:1px solid #e2e8f0;" bgcolor="#f8fafc">
<span style="font-size:11px;color:#94a3b8;">Generated on {gen_time}</span><br/>
<span style="font-size:10px;color:#cbd5e1;letter-spacing:3px;">LEVELOG CONSTRUCTION MANAGEMENT</span>
</td></tr></table></body></html>"""
    
    return html
	
# ==================== STATS / DASHBOARD ====================
@api_router.get("/stats/dashboard")
async def get_dashboard_stats(current_user = Depends(get_current_user)):
    company_id = get_user_company_id(current_user)
    today_start, today_end = get_today_range_est()
    
    query = {"is_deleted": {"$ne": True}}
    if company_id:
        query["company_id"] = company_id
    
    total_workers = await db.workers.count_documents(query)

    # ON SITE = checked in AND within the Eastern-local "today" window, matching
    # the per-project active tile (GET /checkins/project/{id}/active). Without the
    # date bound this counted stale checked-in rows from prior days.
    on_site_query = {
        **query,
        "status": "checked_in",
        "check_in_time": {"$gte": today_start, "$lt": today_end},
    }
    unique_on_site = await db.checkins.distinct("worker_id", on_site_query)
    on_site_now = len(unique_on_site)
    
    project_query = {**query, "status": "active"}
    total_projects = await db.projects.count_documents(project_query)
    
    today_query = {**query, "check_in_time": {"$gte": today_start, "$lt": today_end}}
    today_checkins = await db.checkins.count_documents(today_query)
    
    return {
        "total_workers": total_workers,
        "total_projects": total_projects,
        "on_site_now": on_site_now,
        "today_checkins": today_checkins
    }
    


# ==================== CHECKLIST READ SHAPE ====================
#
# EVERY CHECKLIST READ SERVES `checklist` NESTED. The four read endpoints below
# hand back an assignment with a `checklist` object (title, description, items)
# and a computed `completions` list. Nothing serves `checklist_title` or
# `checklist_items` flat any more: no client ever read them, and
# `app/checklists.jsx:101` was calling `details.checklist.items.forEach` on a
# payload with no `checklist` key. That threw into the surrounding catch and
# told the CP "Could not load checklist" — so a newly assigned checklist could
# not be opened by the person it was assigned to, and only that person, and
# only until a completion record existed to send the other branch.
#
# THE TITLE IS DERIVED ON EVERY READ, AND THAT IS THE POINT — DO NOT "RESTORE"
# THE FLAT KEY. `assign_checklist` copies the title onto the assignment
# document at creation and `update_checklist` never propagates a rename, so
# `checklist_assignments.checklist_title` goes stale the first time a checklist
# is renamed. Joining db.checklists on every read makes that stale copy
# INVISIBLE WITHOUT A MIGRATION — the second copy still sits on the document,
# nothing serves it, so nothing can print the old name. Serving the stored key
# again (for a cheaper read, or because the field looks unused) brings the bug
# back with it. Do not store a third copy either; derive it.
#
# `completions` IS COMPUTED, NOT STORED, and is not a rename of anything.
# `complete_checklist` persists `item_completions` (a dict of
# {checked, note, timestamp}) and `user_name`; there has never been a
# `progress` object anywhere in checklist_completions.


def _checklist_scale(checklist):
    """(live item ids, item count) — computed once per checklist and reused for
    every completion measured against it."""
    items = (checklist or {}).get("items", []) or []
    ids = {str(i["id"]) for i in items if isinstance(i, dict) and i.get("id")}
    return ids, len(items)


def _checklist_progress(completion, item_ids, total):
    """{completed, total} for one completion, measured against LIVE items.

    `total` is the number of items on the checklist now. `completed` counts
    only checked keys that still name one of those items, so an item deleted
    after someone ticked it cannot leave a stored completion reporting 5/4:
    completed <= total always.
    """
    checked = 0
    for item_id, state in ((completion or {}).get("item_completions", {}) or {}).items():
        if str(item_id) not in item_ids:
            continue
        if isinstance(state, dict):
            if state.get("checked"):
                checked += 1
        elif state:
            checked += 1
    return {"completed": checked, "total": total}


def _completion_row(completion, item_ids, total):
    """One row of the `completions` list both admin surfaces render:
    [{user_id, user_name, progress: {completed, total}}]."""
    return {
        "user_id": completion.get("user_id"),
        "user_name": completion.get("user_name", ""),
        "progress": _checklist_progress(completion, item_ids, total),
    }


def _nested_checklist(checklist):
    """The `checklist` object every client reads off an assignment."""
    if not checklist:
        return None
    return {
        "id": str(checklist.get("_id", checklist.get("id", ""))),
        "title": checklist.get("title", ""),
        "description": checklist.get("description"),
        "items": checklist.get("items", []) or [],
    }


def _serialize_assignment(assignment):
    """Serialize an assignment WITHOUT its frozen `checklist_title` copy — the
    title is derived from db.checklists per request instead. See above."""
    out = serialize_id(dict(assignment))
    out.pop("checklist_title", None)
    return out


async def _checklists_by_id(checklist_ids):
    """The checklists for a whole page of assignments in one $in, instead of a
    find_one per assignment. Keyed by the id as a STRING, which is how
    assignments store it."""
    wanted = {str(cid) for cid in checklist_ids if cid}
    if not wanted:
        return {}
    out = {}
    async for doc in db.checklists.find({"_id": {"$in": [to_query_id(c) for c in wanted]}}):
        out[str(doc["_id"])] = doc
    return out


async def _completions_by_assignment(assignment_ids, user_id=None):
    """Completions for a whole page of assignments in one $in, grouped by
    assignment id. `assignment_id` is a STRING on checklist_completions
    (`complete_checklist` writes `str(_id)`), so these are not ObjectIds."""
    wanted = [str(a) for a in assignment_ids if a]
    if not wanted:
        return {}
    query = {"assignment_id": {"$in": wanted}}
    if user_id:
        query["user_id"] = user_id
    out = {}
    async for doc in db.checklist_completions.find(query):
        out.setdefault(str(doc.get("assignment_id")), []).append(doc)
    return out


def _serialize_completion(completion, item_ids, total):
    """The owner's own completion record, plus the `progress` object
    `app/checklists.jsx:198` draws its bar from. The stored document has never
    carried one, so that bar read 0/0 · 0% for every CP — including one who had
    just ticked every item — until it was computed here."""
    if not completion:
        return None
    out = serialize_id(dict(completion))
    out.setdefault("user_name", "")
    out["progress"] = _checklist_progress(completion, item_ids, total)
    return out


# ==================== PROJECT CHECKLISTS ====================

@api_router.get("/projects/{project_id}/checklists")
async def get_project_checklists(project_id: str, current_user = Depends(get_current_user), _proj = Depends(require_project_access)):
    """Get all checklist assignments for a project"""
    assignments = await db.checklist_assignments.find({
        "project_id": project_id,
        "is_deleted": {"$ne": True}
    }).to_list(200)
    if not assignments:
        return []

    checklists = await _checklists_by_id(a.get("checklist_id") for a in assignments)
    completions = await _completions_by_assignment(str(a["_id"]) for a in assignments)

    result = []
    for assignment in assignments:
        checklist = checklists.get(str(assignment.get("checklist_id")))
        if not checklist:
            continue
        item_ids, total = _checklist_scale(checklist)
        item = _serialize_assignment(assignment)
        item["checklist"] = _nested_checklist(checklist)
        item["completions"] = [
            _completion_row(c, item_ids, total)
            for c in completions.get(str(assignment["_id"]), [])
        ]
        result.append(item)

    return result

# ==================== ADMIN CHECKLISTS ====================

@api_router.get("/admin/checklists")
async def get_checklists(admin = Depends(get_admin_user)):
    """Get all checklists for the admin's company"""
    company_id = get_user_company_id(admin)
    query = {"is_deleted": {"$ne": True}}
    if company_id:
        query["company_id"] = company_id
    
    checklists = await db.checklists.find(query).sort("created_at", -1).to_list(200)
    result = []
    for cl in checklists:
        serialized = serialize_id(cl)
        # Get creator name
        if cl.get("created_by"):
            creator = await db.users.find_one({"_id": to_query_id(cl["created_by"])})
            serialized["created_by_name"] = creator.get("name") if creator else "Unknown"
        result.append(serialized)
    return result

@api_router.post("/admin/checklists")
async def create_checklist(checklist_data: ChecklistCreate, admin = Depends(get_admin_user)):
    """Create a new checklist"""
    company_id = get_user_company_id(admin)
    now = datetime.now(timezone.utc)
    
    # Add IDs to items if not present
    items = []
    for i, item in enumerate(checklist_data.items):
        if "id" not in item:
            item["id"] = str(uuid.uuid4())
        if "order" not in item:
            item["order"] = i
        items.append(item)
    
    checklist_dict = {
        "title": checklist_data.title,
        "description": checklist_data.description,
        "items": items,
        "company_id": company_id,
        "created_by": admin.get("id"),
        "created_at": now,
        "updated_at": now,
        "is_deleted": False
    }
    
    result = await db.checklists.insert_one(checklist_dict)
    checklist_dict["id"] = str(result.inserted_id)
    checklist_dict.pop("_id", None)
    
    # Add creator name
    checklist_dict["created_by_name"] = admin.get("name")
    
    return checklist_dict

@api_router.get("/admin/checklists/{checklist_id}")
async def get_checklist(checklist_id: str, admin = Depends(get_admin_user)):
    """Get a single checklist by ID"""
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id), "is_deleted": {"$ne": True}})
    if not checklist:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    serialized = serialize_id(checklist)
    if checklist.get("created_by"):
        creator = await db.users.find_one({"_id": to_query_id(checklist["created_by"])})
        serialized["created_by_name"] = creator.get("name") if creator else "Unknown"
    
    return serialized

@api_router.put("/admin/checklists/{checklist_id}")
async def update_checklist(checklist_id: str, checklist_data: dict, admin = Depends(get_admin_user)):
    """Update a checklist"""
    update_fields = {}
    if "title" in checklist_data:
        update_fields["title"] = checklist_data["title"]
    if "description" in checklist_data:
        update_fields["description"] = checklist_data["description"]
    if "items" in checklist_data:
        items = []
        for i, item in enumerate(checklist_data["items"]):
            if "id" not in item:
                item["id"] = str(uuid.uuid4())
            if "order" not in item:
                item["order"] = i
            items.append(item)
        update_fields["items"] = items
    
    update_fields["updated_at"] = datetime.now(timezone.utc)
    
    result = await db.checklists.update_one(
        {"_id": to_query_id(checklist_id), "is_deleted": {"$ne": True}},
        {"$set": update_fields}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id)})
    return serialize_id(checklist)

@api_router.delete("/admin/checklists/{checklist_id}")
async def delete_checklist(checklist_id: str, admin = Depends(get_admin_user)):
    """Soft delete a checklist"""
    result = await db.checklists.update_one(
        {"_id": to_query_id(checklist_id)},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    # Also soft-delete related assignments
    await db.checklist_assignments.update_many(
        {"checklist_id": checklist_id},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    
    return {"message": "Checklist deleted successfully"}

@api_router.post("/admin/checklists/{checklist_id}/assign")
async def assign_checklist(checklist_id: str, assignment_data: ChecklistAssignmentCreate, admin = Depends(get_admin_user)):
    """Assign a checklist to projects and users"""
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id), "is_deleted": {"$ne": True}})
    if not checklist:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    now = datetime.now(timezone.utc)
    company_id = get_user_company_id(admin)
    created_assignments = []
    
    # The [{id, name}] list the admin surfaces actually PRINT. It does not vary
    # by project, so it is built once for the call and written on BOTH paths
    # below. The re-assign path used to $set `assigned_user_ids` alone: that
    # changed the list the server queries by and left the list the screen
    # renders naming whoever was assigned before.
    assigned_users = []
    for user_id in assignment_data.user_ids:
        user = await db.users.find_one({"_id": to_query_id(user_id)})
        if user:
            assigned_users.append({"id": user_id, "name": user.get("name", "")})

    for project_id in assignment_data.project_ids:
        # Check if assignment already exists
        existing = await db.checklist_assignments.find_one({
            "checklist_id": checklist_id,
            "project_id": project_id,
            "is_deleted": {"$ne": True}
        })
        if existing:
            # Update existing assignment's users — both copies of them.
            await db.checklist_assignments.update_one(
                {"_id": existing["_id"]},
                {"$set": {
                    "assigned_user_ids": assignment_data.user_ids,
                    "assigned_users": assigned_users,
                    "updated_at": now,
                }}
            )
            continue
        
        # Get project name
        project = await db.projects.find_one({"_id": to_query_id(project_id)})
        project_name = project.get("name", "") if project else ""
        
        assignment_dict = {
            "checklist_id": checklist_id,
            "checklist_title": checklist.get("title", ""),
            "project_id": project_id,
            "project_name": project_name,
            "assigned_user_ids": assignment_data.user_ids,
            "assigned_users": assigned_users,
            "company_id": company_id,
            "created_by": admin.get("id"),
            "created_at": now,
            "updated_at": now,
            "is_deleted": False
        }
        
        result = await db.checklist_assignments.insert_one(assignment_dict)
        assignment_dict["id"] = str(result.inserted_id)
        assignment_dict.pop("_id", None)
        created_assignments.append(assignment_dict)
    
    return created_assignments

@api_router.get("/admin/checklists/{checklist_id}/assignments")
async def get_checklist_assignments(checklist_id: str, admin = Depends(get_admin_user)):
    """Get all assignments for a checklist"""
    assignments = await db.checklist_assignments.find({
        "checklist_id": checklist_id,
        "is_deleted": {"$ne": True}
    }).to_list(200)
    if not assignments:
        return []

    # Every assignment on this page is an assignment OF this checklist, so the
    # title/items join is one read for the whole page.
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id)})
    nested = _nested_checklist(checklist)
    item_ids, total = _checklist_scale(checklist)

    completions = await _completions_by_assignment(str(a["_id"]) for a in assignments)

    result = []
    for assignment in assignments:
        serialized = _serialize_assignment(assignment)
        serialized["checklist"] = nested
        rows = [
            _completion_row(c, item_ids, total)
            for c in completions.get(str(assignment["_id"]), [])
        ]
        serialized["completions"] = rows

        # Unchanged meaning: `completed` is how many completion RECORDS exist,
        # exactly what the per-assignment count_documents this replaced
        # returned. Nothing reads it (see followups) — it is kept because
        # removing a served key is its own decision, not a side effect.
        serialized["completion_stats"] = {
            "total_assigned": len(assignment.get("assigned_user_ids", [])),
            "completed": len(rows),
        }
        result.append(serialized)

    return result

# ==================== USER CHECKLISTS ====================

@api_router.get("/checklists/assigned")
async def get_assigned_checklists(current_user = Depends(get_current_user)):
    """Get checklists assigned to the current user"""
    user_id = current_user.get("id")

    assignments = await db.checklist_assignments.find({
        "assigned_user_ids": user_id,
        "is_deleted": {"$ne": True}
    }).to_list(200)
    if not assignments:
        return []

    checklists = await _checklists_by_id(a.get("checklist_id") for a in assignments)
    # This is the CP's list of their OWN work, not a roster — scope the one
    # $in to them rather than reading everyone's completions and discarding.
    completions = await _completions_by_assignment(
        (str(a["_id"]) for a in assignments), user_id=user_id,
    )

    result = []
    for assignment in assignments:
        checklist = checklists.get(str(assignment.get("checklist_id")))
        if not checklist:
            continue

        item_ids, total = _checklist_scale(checklist)
        serialized = _serialize_assignment(assignment)
        serialized["checklist"] = _nested_checklist(checklist)

        mine = completions.get(str(assignment["_id"]), [])
        completion = mine[0] if mine else None
        serialized["is_completed"] = completion is not None
        serialized["completion"] = _serialize_completion(completion, item_ids, total)

        result.append(serialized)

    return result

@api_router.get("/checklists/assignments/{assignment_id}")
async def get_assignment_details(assignment_id: str, current_user = Depends(get_current_user)):
    """Get details of a specific checklist assignment"""
    # Named on it, or project access. See _assert_assignment_access.
    assignment = await _assert_assignment_access(assignment_id, current_user)

    checklist = await db.checklists.find_one({"_id": to_query_id(assignment["checklist_id"])})
    if not checklist:
        # There is no checklist to open. The list endpoints already skip an
        # assignment whose checklist is gone, so this only answers a stale deep
        # link, and 404 is the honest answer. Serving the assignment with
        # `checklist: null` would put the client back where it started —
        # dereferencing a key that is not there.
        raise HTTPException(status_code=404, detail="Checklist not found")

    item_ids, total = _checklist_scale(checklist)
    serialized = _serialize_assignment(assignment)
    serialized["checklist"] = _nested_checklist(checklist)

    # Get user's completion
    user_id = current_user.get("id")
    completion = await db.checklist_completions.find_one({
        "assignment_id": assignment_id,
        "user_id": user_id
    })
    serialized["completion"] = _serialize_completion(completion, item_ids, total)

    return serialized

@api_router.put("/checklists/assignments/{assignment_id}/complete")
async def complete_checklist(assignment_id: str, completion_data: ChecklistCompletionUpdate, current_user = Depends(get_current_user)):
    """Submit or update checklist completion"""
    # NAMED ON IT, AND NOTHING ELSE — a completion is one person's attestation
    # that they did the work, so project access does not authorize filing one.
    assignment = await _assert_assignment_access(
        assignment_id, current_user, write=True,
    )
    
    user_id = current_user.get("id")
    now = datetime.now(timezone.utc)
    
    # Check if completion already exists
    existing = await db.checklist_completions.find_one({
        "assignment_id": assignment_id,
        "user_id": user_id
    })
    
    completion_dict = {
        "assignment_id": assignment_id,
        "checklist_id": assignment.get("checklist_id"),
        "project_id": assignment.get("project_id"),
        "user_id": user_id,
        "user_name": current_user.get("name", ""),
        "item_completions": completion_data.item_completions,
        "updated_at": now,
    }
    
    if existing:
        await db.checklist_completions.update_one(
            {"_id": existing["_id"]},
            {"$set": completion_dict}
        )
        completion_dict["id"] = str(existing["_id"])
    else:
        completion_dict["created_at"] = now
        result = await db.checklist_completions.insert_one(completion_dict)
        completion_dict["id"] = str(result.inserted_id)
    
    completion_dict.pop("_id", None)
    return completion_dict

