# ==================== DROPBOX INTEGRATION ====================

@api_router.get("/dropbox/status")
async def get_dropbox_status(current_user = Depends(get_current_user)):
    """Check if Dropbox is connected for current user's company"""
    company_id = get_user_company_id(current_user)
    if not company_id:
        return {"connected": False}
    
    connection = await db.dropbox_connections.find_one({
        "company_id": company_id,
        "is_deleted": {"$ne": True}
    })
    
    if connection and connection.get("access_token"):
        return {
            "connected": True,
            "account_name": connection.get("account_name", ""),
            "connected_at": connection.get("connected_at"),
        }
    return {"connected": False}

@api_router.get("/dropbox/auth-url")
async def get_dropbox_auth_url(current_user = Depends(get_current_user)):
    """Get Dropbox OAuth authorization URL"""
    state = jwt.encode(
        {"user_id": current_user.get("id"), "exp": datetime.now(timezone.utc) + timedelta(minutes=10)},
        JWT_SECRET, algorithm=JWT_ALGORITHM
    )
    auth_url = (
        f"https://www.dropbox.com/oauth2/authorize"
        f"?client_id={DROPBOX_APP_KEY}"
        f"&redirect_uri={DROPBOX_REDIRECT_URI}"
        f"&response_type=code"
        f"&token_access_type=offline"
        f"&state={state}"
    )
    return {"auth_url": auth_url}

@api_router.get("/dropbox/callback")
async def dropbox_callback(code: str = None, state: str = None, error: str = None):
    """Handle Dropbox OAuth callback"""
    from fastapi.responses import HTMLResponse
    
    if error:
        return HTMLResponse(f"<html><body><h2>Dropbox connection failed</h2><p>{error}</p><script>window.close();</script></body></html>")
    
    if not code or not state:
        raise HTTPException(status_code=400, detail="Missing code or state")
    
    # Verify state
    try:
        payload = jwt.decode(state, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        user_id = payload["user_id"]
    except (jwt.InvalidTokenError, KeyError, Exception) as e:
        logger.warning(f"Dropbox callback state validation failed: {e}")
        raise HTTPException(status_code=400, detail="Invalid state")
    
    # Exchange code for token
    async with ServerHttpClient() as client_http:
        token_response = await client_http.post(
            "https://api.dropboxapi.com/oauth2/token",
            data={
                "code": code,
                "grant_type": "authorization_code",
                "client_id": DROPBOX_APP_KEY,
                "client_secret": DROPBOX_APP_SECRET,
                "redirect_uri": DROPBOX_REDIRECT_URI,
            }
        )
    
    if token_response.status_code != 200:
        try:
            err = token_response.json()
            msg = (
                err.get("error_description")
                or err.get("error_summary")
                or err.get("error")
                or "Connection failed"
            )
        except Exception:
            msg = token_response.text[:300] if token_response.text else "Unknown error"
        return HTMLResponse(
            f"""<html><body style="font-family:sans-serif;padding:40px;background:#0a0e1a;color:#f1f5f9;text-align:center">
            <h2 style="color:#ef4444;margin-bottom:16px">Dropbox Connection Failed</h2>
            <p style="color:#94a3b8;margin-bottom:12px">{msg}</p>
            <p style="color:#64748b;font-size:13px">If this says 'too_many_users': go to dropbox.com/developers/apps
            and either submit the app for Production or add this user email as a Tester.</p>
            <script>setTimeout(()=>window.close(),8000);</script>
            </body></html>""",
            status_code=200,
        )
    
    token_data = token_response.json()
    
    # Get account info
    async with ServerHttpClient() as client_http:
        account_response = await client_http.post(
            "https://api.dropboxapi.com/2/users/get_current_account",
            headers={"Authorization": f"Bearer {token_data['access_token']}"}
        )
    
    account_name = ""
    if account_response.status_code == 200:
        account_info = account_response.json()
        account_name = account_info.get("name", {}).get("display_name", "")
    
    # Get user's company
    user = await db.users.find_one({"_id": to_query_id(user_id)})
    company_id = user.get("company_id") if user else None
    
    now = datetime.now(timezone.utc)
    
    # Store connection
    expires_at = now + timedelta(seconds=token_data.get("expires_in", 14400))
    await db.dropbox_connections.update_one(
        {"company_id": company_id},
        {"$set": {
            "company_id": company_id,
            "user_id": user_id,
            "access_token": token_data["access_token"],
            "refresh_token": token_data.get("refresh_token"),
            "account_id": token_data.get("account_id"),
            "account_name": account_name,
            "access_token_expires_at": expires_at,
            "connected_at": now,
            "updated_at": now,
            "is_deleted": False,
        }},
        upsert=True
    )
    
    # Use specific origin instead of '*' to prevent cross-origin message interception
    allowed_origin = ALLOWED_ORIGINS[0] if ALLOWED_ORIGINS else "https://levelog.com"
    return HTMLResponse(f"<html><body><h2>Dropbox connected successfully!</h2><p>You can close this window.</p><script>window.opener && window.opener.postMessage('dropbox-connected','{allowed_origin}'); setTimeout(()=>window.close(), 2000);</script></body></html>")

@api_router.post("/dropbox/complete-auth")
async def complete_dropbox_auth(data: dict, current_user = Depends(get_current_user)):
    """Complete Dropbox OAuth with authorization code (alternative to callback)"""
    code = data.get("code")
    if not code:
        raise HTTPException(status_code=400, detail="Authorization code required")
    
    async with ServerHttpClient() as client_http:
        token_response = await client_http.post(
            "https://api.dropboxapi.com/oauth2/token",
            data={
                "code": code,
                "grant_type": "authorization_code",
                "client_id": DROPBOX_APP_KEY,
                "client_secret": DROPBOX_APP_SECRET,
                "redirect_uri": DROPBOX_REDIRECT_URI,
            }
        )
    
    if token_response.status_code != 200:
        try:
            err = token_response.json()
            msg = (err.get("error_description") or err.get("error") or "Token exchange failed")
        except Exception:
            msg = token_response.text[:200] or "Token exchange failed"
        raise HTTPException(status_code=422, detail=f"Dropbox error: {msg}")

    token_data = token_response.json()
    company_id = get_user_company_id(current_user)
    now = datetime.now(timezone.utc)
    
    # Get account info
    async with ServerHttpClient() as client_http:
        account_response = await client_http.post(
            "https://api.dropboxapi.com/2/users/get_current_account",
            headers={"Authorization": f"Bearer {token_data['access_token']}"}
        )
    
    account_name = ""
    if account_response.status_code == 200:
        account_info = account_response.json()
        account_name = account_info.get("name", {}).get("display_name", "")
    
    expires_at = now + timedelta(seconds=token_data.get("expires_in", 14400))
    await db.dropbox_connections.update_one(
        {"company_id": company_id},
        {"$set": {
            "company_id": company_id,
            "user_id": current_user.get("id"),
            "access_token": token_data["access_token"],
            "refresh_token": token_data.get("refresh_token"),
            "account_id": token_data.get("account_id"),
            "account_name": account_name,
            "access_token_expires_at": expires_at,
            "connected_at": now,
            "updated_at": now,
            "is_deleted": False,
        }},
        upsert=True
    )

    return {"message": "Dropbox connected successfully", "account_name": account_name}

@api_router.delete("/dropbox/disconnect")
async def disconnect_dropbox(current_user = Depends(get_current_user)):
    """Disconnect Dropbox"""
    company_id = get_user_company_id(current_user)
    
    # Revoke token
    connection = await db.dropbox_connections.find_one({"company_id": company_id})
    if connection and connection.get("access_token"):
        try:
            async with ServerHttpClient() as client_http:
                await client_http.post(
                    "https://api.dropboxapi.com/2/auth/token/revoke",
                    headers={"Authorization": f"Bearer {connection['access_token']}"}
                )
        except Exception as e:
            logger.warning(f"Dropbox token revocation failed (non-blocking): {e}")
    
    await db.dropbox_connections.update_one(
        {"company_id": company_id},
        {"$set": {"is_deleted": True, "access_token": None, "refresh_token": None, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    
    return {"message": "Dropbox disconnected"}

async def get_valid_dropbox_token(company_id: str) -> str:
    """Get a valid Dropbox access token, proactively refreshing if expired or expiring within 30 min."""
    connection = await db.dropbox_connections.find_one({
        "company_id": company_id, "is_deleted": {"$ne": True}
    })
    if not connection:
        raise HTTPException(status_code=400, detail="Dropbox not connected")

    # Check if token is still valid (with 30-min buffer).
    # PyMongo returns datetimes as offset-naive by default, even though we
    # store them as aware UTC — coerce before comparing, otherwise Python
    # raises "can't compare offset-naive and offset-aware datetimes".
    expires_at = connection.get("access_token_expires_at")
    if expires_at and isinstance(expires_at, datetime):
        if expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=timezone.utc)
        if expires_at > datetime.now(timezone.utc) + timedelta(minutes=30):
            return connection["access_token"]

    # Token expired or no expiry stored — refresh
    refresh_token = connection.get("refresh_token")
    if not refresh_token:
        raise HTTPException(status_code=401, detail="No refresh token. Please reconnect Dropbox.")

    try:
        async with ServerHttpClient(timeout=15.0) as c:
            resp = await c.post("https://api.dropboxapi.com/oauth2/token", data={
                "grant_type": "refresh_token",
                "refresh_token": refresh_token,
                "client_id": DROPBOX_APP_KEY,
                "client_secret": DROPBOX_APP_SECRET,
            })
        if resp.status_code != 200:
            logger.error(f"Dropbox token refresh failed: {resp.status_code} {resp.text}")
            raise HTTPException(status_code=401, detail="Dropbox token refresh failed. Please reconnect.")

        token_data = resp.json()
        new_token = token_data["access_token"]
        expires_in = token_data.get("expires_in", 14400)  # default 4 hours
        new_expires_at = datetime.now(timezone.utc) + timedelta(seconds=expires_in)

        await db.dropbox_connections.update_one(
            {"company_id": company_id},
            {"$set": {
                "access_token": new_token,
                "access_token_expires_at": new_expires_at,
                "updated_at": datetime.now(timezone.utc),
            }}
        )
        logger.info(f"Dropbox token refreshed for company {company_id}, expires at {new_expires_at}")
        return new_token
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Dropbox token refresh error: {e}")
        raise HTTPException(status_code=500, detail="Failed to refresh Dropbox token")

async def dropbox_api_call(company_id: str, method: str, url: str, **kwargs):
    """Make Dropbox API call with automatic token refresh"""
    token = await get_valid_dropbox_token(company_id)

    headers = kwargs.pop("headers", {})
    headers["Authorization"] = f"Bearer {token}"

    async with ServerHttpClient() as client_http:
        response = await getattr(client_http, method)(url, headers=headers, **kwargs)

    # Safety net: if 401 despite proactive refresh, force-refresh once more
    if response.status_code == 401:
        token = await get_valid_dropbox_token(company_id)
        headers["Authorization"] = f"Bearer {token}"
        async with ServerHttpClient() as client_http:
            response = await getattr(client_http, method)(url, headers=headers, **kwargs)

    return response

@api_router.get("/dropbox/folders")
async def get_dropbox_folders(path: str = "", current_user = Depends(get_current_user)):
    """Get Dropbox folders for selection.

    Dropbox quirk: the root path MUST be the empty string, NOT '/'. If the
    client passes '/', Dropbox returns 400 malformed_path. We also include
    shared and mounted folders so users of Dropbox Business accounts see
    team-shared folders in the picker.
    """
    company_id = get_user_company_id(current_user)

    # Normalize the path — Dropbox is strict here.
    norm_path = (path or "").strip()
    if norm_path in ("/", ""):
        norm_path = ""  # root
    elif not norm_path.startswith("/"):
        norm_path = "/" + norm_path
    # Strip trailing slash for non-root paths
    if norm_path != "" and norm_path.endswith("/"):
        norm_path = norm_path.rstrip("/")

    try:
        response = await dropbox_api_call(
            company_id, "post",
            "https://api.dropboxapi.com/2/files/list_folder",
            json={
                "path": norm_path,
                "recursive": False,
                "include_mounted_folders": True,
                "include_non_downloadable_files": False,
            }
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(
            f"Dropbox folders request blew up — company={company_id} path={norm_path!r} err={e}"
        )
        raise HTTPException(status_code=500, detail=f"Dropbox request failed: {e}")

    if response.status_code != 200:
        # Surface the actual Dropbox error so the UI / logs tell us what broke
        # (bad_path, expired_token, insufficient_scope, etc.) instead of a
        # generic 400 that forces us to guess.
        body_text = ""
        try:
            body_text = response.text[:500]
        except Exception:
            pass
        logger.error(
            f"Dropbox list_folder failed — company={company_id} path={norm_path!r} "
            f"status={response.status_code} body={body_text!r}"
        )
        # Parse Dropbox's JSON error to produce a user-facing message.
        detail = "Failed to list folders"
        try:
            err = response.json()
            summary = err.get("error_summary") or ""
            tag = (err.get("error", {}) or {}).get(".tag") or ""
            if "insufficient_scope" in summary or "missing_scope" in summary:
                detail = (
                    "Dropbox app is missing the files.metadata.read permission. "
                    "Disconnect and reconnect, or check the Dropbox app permissions."
                )
            elif "expired_access_token" in summary or "invalid_access_token" in summary:
                detail = "Dropbox token expired — please reconnect Dropbox."
            elif tag == "path" or "path/" in summary:
                detail = f"Dropbox rejected path {norm_path!r}: {summary or 'not_found'}"
            elif summary:
                detail = f"Dropbox error: {summary}"
        except Exception:
            if body_text:
                detail = f"Dropbox error: {body_text[:200]}"
        raise HTTPException(status_code=400, detail=detail)

    data = response.json()
    folders = [
        {
            "name": entry["name"],
            "path": entry.get("path_lower") or entry.get("path_display") or "",
            "id": entry.get("id", ""),
        }
        for entry in data.get("entries", [])
        if entry.get(".tag") == "folder"
    ]

    return folders

def _normalize_subfolder_names(names: List[str]) -> List[str]:
    """Strip leading slashes + trailing slashes, drop empties, dedupe
    (case-insensitive by comparison but preserve caller casing).
    Used so both 'Approved Plans' and '/Approved Plans/' end up as
    the single canonical 'Approved Plans' entry."""
    seen_lower = set()
    out = []
    for raw in names or []:
        if not isinstance(raw, str):
            continue
        n = raw.strip().strip("/").strip()
        if not n:
            continue
        low = n.lower()
        if low in seen_lower:
            continue
        seen_lower.add(low)
        out.append(n)
    return out


# The name an app-uploaded file answers to. A file uploaded through the app
# never went near Dropbox: upload_project_file writes `dropbox_path: ""` and an
# r2_key, so it has no folder to be under and the subfolder rule -- keyed on a
# path -- refused it for EVERY possible value of site_device_subfolders. That
# is not a strict rule, it is an unsatisfiable one, and it hid every direct
# upload on every project from every tablet.
#
# It is repaired by making such files ADDRESSABLE rather than by publishing
# them. They are treated as living in one reserved folder, which an admin ticks
# exactly as they tick a real Dropbox subfolder -- and until they do, the file
# stays invisible. The operator's ruling is "no auto-publish"; reachable is not
# published. See _visibility_path_for_record.
APP_UPLOADS_VIRTUAL_FOLDER = "Uploaded in App"


def _visibility_path_for_record(rec: dict) -> str:
    """The path the site-device visibility rule is applied to for one
    project_files row.

    For a Dropbox-synced row that is its real `dropbox_path`. For a row with no
    Dropbox path at all -- a direct upload -- it is a synthetic path under
    APP_UPLOADS_VIRTUAL_FOLDER, deliberately NOT under the project's Dropbox
    folder: an admin who ticks the Dropbox folder chose what is inside that
    folder, and an app upload was never inside it. Ticking the uploads folder
    by name is the only thing that reveals these files.

    A row with neither a path nor an r2_key names no retrievable file and gets
    "" -- it stays refused, rather than being conjured into the uploads folder
    as an entry the tablet would fail to download.
    """
    path = str(rec.get("dropbox_path") or "").strip()
    if path:
        return path
    if not str(rec.get("r2_key") or "").strip():
        return ""
    name = str(rec.get("name") or "").replace("\\", "/").rsplit("/", 1)[-1].strip()
    if not name:
        name = str(rec.get("r2_key") or "").rsplit("/", 1)[-1].strip()
    if not name:
        return ""
    return f"/{APP_UPLOADS_VIRTUAL_FOLDER}/{name}"


def _path_is_under_allowed_subfolder(
    file_path: str, folder_path: str, allowed_subfolders: List[str]
) -> bool:
    """True iff file_path lives under any allowed subfolder of
    folder_path. Path comparison is case-insensitive because Dropbox
    preserves case in `name` but stores a lowercased `path_lower`; we
    call this with either, so normalize both sides.

    THE BASE FOLDER SELECTED AS ITS OWN SUBFOLDER. The picker lists the base
    folder's children, but an admin can and does tick the project folder itself
    -- `dropbox_folder_path: '/588 plans'` with `site_device_subfolders:
    ['588 plans']` is live production config. The base prefix is stripped
    first, so `/588 plans/A-101.pdf` became the relative `A-101.pdf` and was
    compared against `588 plans`, which matched nothing: the selection was read
    as "a folder named 588 plans INSIDE /588 plans", which does not exist. Every
    file on that project was hidden from the gate. A name that IS the base --
    its leaf name or its full stored path -- now means everything under the
    base, which is what ticking it plainly intends.

    The base prefix is matched on a path SEGMENT boundary. A bare startswith
    also matched `/588 plans archive/`, so a sibling folder that merely shared
    the prefix had its contents measured against the selection as though they
    were inside the project.
    """
    if not file_path or not allowed_subfolders:
        return False
    fp = file_path.lower()
    base = (folder_path or "").lower().rstrip("/")
    under_base = bool(base) and (fp == base or fp.startswith(base + "/"))
    # Strip the base project folder prefix so comparisons are relative.
    rel = fp[len(base):] if under_base else fp
    rel = rel.lstrip("/")
    # The spellings that name the base folder itself rather than a child of it.
    base_aliases = set()
    if base:
        base_aliases.add(base.strip("/"))
        base_aliases.add(base.rsplit("/", 1)[-1])
        base_aliases.discard("")
    for sub in allowed_subfolders:
        sub_low = sub.lower().strip("/").strip()
        if not sub_low:
            continue
        if under_base and sub_low in base_aliases:
            return True
        if rel == sub_low or rel.startswith(sub_low + "/"):
            return True
    return False


@api_router.get("/projects/{project_id}/dropbox-subfolders")
async def list_dropbox_subfolders(
    project_id: str, current_user = Depends(get_admin_user)
):
    """Admin-only: list the top-level subfolders under the project's
    linked Dropbox folder. Used by the 'Site Device Visibility' UI to
    render checkboxes for which subfolders the kiosk can see."""
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    company_id = get_user_company_id(current_user)
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")
    company_id = company_id or project.get("company_id")
    folder_path = project.get("dropbox_folder_path") or ""

    # Files uploaded through the app have no Dropbox path, so they appear in no
    # Dropbox listing and this picker never offered a name that could reveal
    # them. Offer the reserved one — but only where such files exist, so a
    # project without them is not shown a folder holding nothing.
    has_app_uploads = await db.project_files.count_documents({
        "project_id": project_id,
        "is_deleted": {"$ne": True},
        "dropbox_path": {"$in": [None, ""]},
        "r2_key": {"$nin": [None, ""]},
    }) > 0

    selected = _normalize_subfolder_names(
        project.get("site_device_subfolders") or []
    )

    if not folder_path:
        # A project that has only ever had direct uploads has no linked folder.
        # That early return used to answer with nothing selectable at all —
        # precisely the project on which every file is invisible.
        return {
            "subfolders": [APP_UPLOADS_VIRTUAL_FOLDER] if has_app_uploads else [],
            "selected": selected,
            "folder_path": "",
        }

    try:
        # Dropbox wants "" for root, not "/" — translate our stored sentinel.
        api_path = _dropbox_api_path(folder_path)
        resp = await dropbox_api_call(
            company_id, "post",
            "https://api.dropboxapi.com/2/files/list_folder",
            json={"path": api_path, "recursive": False},
        )
        subfolders: List[str] = []
        if resp.status_code == 200:
            for entry in resp.json().get("entries", []):
                if entry.get(".tag") == "folder":
                    subfolders.append(entry.get("name", ""))
            subfolders = [s for s in subfolders if s]
            subfolders.sort(key=lambda x: x.lower())
    except Exception as e:
        logger.warning(
            f"list subfolders failed for project {project_id}: {e}"
        )
        subfolders = []

    # Appended after the sort so the reserved name sits at the end of the list
    # rather than interleaved among the project's real Dropbox folders.
    if has_app_uploads and not any(
        s.lower() == APP_UPLOADS_VIRTUAL_FOLDER.lower() for s in subfolders
    ):
        subfolders.append(APP_UPLOADS_VIRTUAL_FOLDER)

    return {
        "folder_path": folder_path,
        "subfolders": subfolders,
        "selected": selected,
    }


@api_router.put("/projects/{project_id}/site-device-subfolders", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def set_site_device_subfolders(
    project_id: str,
    data: dict,
    current_user = Depends(get_admin_user),
):
    """Admin-only: set the list of subfolder names (relative to the
    project's Dropbox folder) that site-device users are allowed to
    see. Passing [] locks site devices out completely (safe default).
    Names are stripped + deduped server-side; do not include slashes.
    """
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    company_id = get_user_company_id(current_user)
    if company_id and project.get("company_id") != company_id:
        raise HTTPException(status_code=403, detail="Access denied to this project")
    subfolders_raw = data.get("subfolders")
    if not isinstance(subfolders_raw, list):
        raise HTTPException(
            status_code=400,
            detail="subfolders must be an array of folder names",
        )
    cleaned = _normalize_subfolder_names(subfolders_raw)
    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {"$set": {
            "site_device_subfolders": cleaned,
            "updated_at": datetime.now(timezone.utc),
        }},
    )
    return {
        "message": "Site device visibility updated",
        "site_device_subfolders": cleaned,
    }


def _dropbox_api_path(stored: str) -> str:
    """Translate an internally-stored folder path to the exact shape
    Dropbox's API expects. We store '/' as a sentinel for 'the root of
    this app's scope' (so `if not folder_path` can still distinguish
    linked-to-root from not-linked). Dropbox requires root as '' not '/'.
    """
    s = (stored or "").strip()
    if s in ("", "/"):
        return ""
    if not s.startswith("/"):
        s = "/" + s
    return s.rstrip("/")


@api_router.post("/projects/{project_id}/link-dropbox", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def link_dropbox_to_project(project_id: str, data: dict, current_user = Depends(get_current_user)):
    """Link or unlink a Dropbox folder for a project.

    - folder_path: None  → unlink (clear dropbox_folder_path)
    - folder_path: "" or "/" → REFUSED 400, unless allow_root is true
    - folder_path: "/Foo/Bar" → link to that folder (normalized)

    ROOT IS NO LONGER WHAT AN EMPTY STRING FALLS THROUGH TO. "" is the value a
    BUG produces -- a cleared input, a falsy variable, a missing key -- and it
    used to mean "link this project to everything the company owns". A control
    labelled Disconnect sent exactly that and stored "/" instead of clearing the
    field; _sync_project_to_r2 lists with recursive=True, so the next sync would
    have copied the whole company Dropbox into one project's project_files rows
    and onto R2. It never fired only because the button rendered behind two
    fields nothing writes.

    The asymmetry is the argument: refusing a legitimate root link costs an
    error message, accepting an accidental one costs a full-company copy. None
    already gives "clear it" an unambiguous signal, so root gets its own —
    allow_root, a second deliberate key that no falsy fallback can produce.

    THE NEVER-BLOCK-AT-THE-GATE RULE DOES NOT APPLY HERE, and this is written
    down so it is not invoked against this refusal later. "An unfilled admin
    form must never stop a man from working" governs the check-in path: the
    turnstile, the card step, register-and-checkin. This endpoint is admin
    CONFIGURATION, reached from project settings by an approved admin with
    project access. Nothing on this path is in a worker's way, and no 400
    returned here can stop a man from working — it stops an admin from
    misconfiguring a project, which is the opposite thing.
    """
    now = datetime.now(timezone.utc)
    folder_path = data.get("folder_path")

    # Explicit null means unlink. Clear the field and return.
    if folder_path is None:
        await db.projects.update_one(
            {"_id": to_query_id(project_id)},
            {
                "$unset": {
                    "dropbox_folder_path": "",
                    "dropbox_linked_at": "",
                    "dropbox_linked_by": "",
                },
                "$set": {"updated_at": now},
            },
        )
        return {"message": "Dropbox folder unlinked", "folder_path": None}

    if not isinstance(folder_path, str):
        raise HTTPException(status_code=400, detail="folder_path must be a string or null")

    raw = folder_path.strip()
    if raw in ("", "/"):
        # Compared with `is True`, not for truthiness: "false", 0 and "" are all
        # things a client can put in this key by accident, and none of them is
        # an admin deciding to link an entire Dropbox.
        if data.get("allow_root") is not True:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Pick a folder inside Dropbox — an empty path would link "
                    "this project to your entire Dropbox and copy every file "
                    "your company stores into it. To unlink, send "
                    "folder_path: null. To deliberately link the whole "
                    "Dropbox, send allow_root: true as well."
                ),
            )
        # Stored as "/" so downstream truthiness checks ('if not folder_path')
        # treat a root-linked project as linked.
        norm = "/"
    else:
        norm = raw if raw.startswith("/") else "/" + raw
        if norm != "/" and norm.endswith("/"):
            norm = norm.rstrip("/")

    await db.projects.update_one(
        {"_id": to_query_id(project_id)},
        {"$set": {
            "dropbox_folder_path": norm,
            "dropbox_linked_at": now,
            "dropbox_linked_by": current_user.get("id"),
            "updated_at": now,
        }}
    )

    return {"message": "Dropbox folder linked", "folder_path": norm}

@api_router.get("/projects/{project_id}/dropbox-files")
async def get_project_dropbox_files(project_id: str, current_user = Depends(get_current_user)):
    """Get files from project's linked Dropbox folder (R2-backed with Dropbox fallback).

    Role-based visibility: users with role=site_device only see files
    whose path sits under one of the project's site_device_subfolders.
    Empty list → site devices see nothing (safe default). Admins/CPs
    see the full folder regardless.
    """
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    company_id = get_user_company_id(current_user)
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")

    company_id = company_id or project.get("company_id")
    folder_path = project.get("dropbox_folder_path")

    is_site_device = (
        current_user.get("site_mode")
        or current_user.get("role") == "site_device"
    )
    allowed_subfolders = _normalize_subfolder_names(
        project.get("site_device_subfolders") or []
    )

    def _visible_to_site(path: str) -> bool:
        return _path_is_under_allowed_subfolder(
            path, folder_path or "", allowed_subfolders
        )

    # Short-circuit: site device with no subfolders configured sees nothing.
    if is_site_device and not allowed_subfolders:
        return []

    # Check project_files collection first (R2 cache + direct uploads)
    cached_files = await db.project_files.find({
        "project_id": project_id,
        "company_id": company_id,
        "is_deleted": {"$ne": True},
    }).to_list(5000)

    if cached_files:
        files = []
        for rec in cached_files:
            dropbox_path = rec.get("dropbox_path", "")
            # The rule is applied to the record's VISIBILITY path, not to
            # dropbox_path: a direct upload has none, and testing the raw ""
            # refused it under every possible selection. The row still reports
            # its real (empty) dropbox_path below — the synthetic one is a
            # selection handle, not an address anything else may resolve.
            if is_site_device and not _visible_to_site(
                _visibility_path_for_record(rec)
            ):
                continue
            r2_key = rec.get("r2_key", "")
            stored_url = rec.get("r2_url", "")
            rec_id = str(rec.get("_id", ""))
            # Prefer backend proxy URL (no CORS headaches, enforces auth).
            proxy_url = f"/api/projects/{project_id}/files/{rec_id}/content" if r2_key and rec_id else ""
            files.append({
                "name": rec.get("name", ""),
                "path": dropbox_path,
                "id": rec_id,
                "type": "file",
                "size": rec.get("size", 0),
                "modified": rec.get("modified", ""),
                "r2_url": proxy_url or stored_url,
                "cache_version": rec.get("cache_version", 0),
                "source": rec.get("source", "dropbox_sync"),
            })
        return files

    # No cached records — fall back to live Dropbox listing (only if folder linked)
    if not folder_path:
        return []

    # Dropbox wants "" for root, not "/" — translate our stored sentinel.
    norm_folder = _dropbox_api_path(folder_path)

    # Site devices need a RECURSIVE listing so we can see files inside
    # the allowed subfolders, not just top-level entries.
    response = await dropbox_api_call(
        company_id, "post",
        "https://api.dropboxapi.com/2/files/list_folder",
        json={"path": norm_folder, "recursive": bool(is_site_device)}
    )

    if response.status_code != 200:
        body_text = ""
        try:
            body_text = response.text[:500]
        except Exception:
            pass
        logger.error(
            f"Dropbox dropbox-files list_folder failed — company={company_id} "
            f"project={project_id} path={norm_folder!r} status={response.status_code} "
            f"body={body_text!r}"
        )
        detail = "Failed to list files"
        try:
            err = response.json()
            summary = err.get("error_summary") or ""
            if "not_found" in summary:
                detail = f"Dropbox folder {norm_folder!r} not found. Re-link the project to a valid folder."
            elif summary:
                detail = f"Dropbox error: {summary}"
        except Exception:
            pass
        raise HTTPException(status_code=400, detail=detail)

    data = response.json()
    files = []
    for entry in data.get("entries", []):
        path_lower = entry.get("path_lower", "")
        if is_site_device:
            # Only files; drop any folder entries from the recursive scan.
            if entry.get(".tag") != "file":
                continue
            if not _visible_to_site(path_lower):
                continue
        file_info = {
            "name": entry["name"],
            "path": path_lower,
            "id": entry.get("id", ""),
            "type": entry[".tag"],
            "r2_url": "",
            "cache_version": 0,
        }
        if entry[".tag"] == "file":
            file_info["size"] = entry.get("size", 0)
            file_info["modified"] = entry.get("server_modified", "")
        files.append(file_info)

    # Trigger background sync so next request will use cached records
    asyncio.create_task(_sync_project_to_r2(project_id, company_id, folder_path))

    # Background-warm URL cache for PDFs
    async def _warm_pdf_cache(files_list, cid):
        for f in files_list:
            if f.get("name", "").lower().endswith(".pdf"):
                path = f.get("path", "")
                if path and not _get_cached_url(cid, path):
                    try:
                        resp = await dropbox_api_call(
                            cid, "post",
                            "https://api.dropboxapi.com/2/files/get_temporary_link",
                            json={"path": path}
                        )
                        if resp.status_code == 200:
                            _set_cached_url(cid, path, resp.json().get("link", ""))
                    except Exception:
                        pass
    asyncio.create_task(_warm_pdf_cache(files, company_id))

    return files


# ══ SITE MANIFEST ═══════════════════════════════════════════════════════════
#
# WHAT IT IS FOR. A fixed Android tablet is bolted to the gate. It has to hold
# everything the project has approved it to see -- plans, documents AND
# submitted logbooks -- fill itself on first connection with nobody preparing
# it, and still open all of it after a cold boot with no network. To do that the
# client needs ONE cheap read that names the COMPLETE approved set, so it can
# work out what is missing, what has changed version, and what is no longer
# approved.
#
# WHY THE ROWS ARE THREE LETTERS WIDE. This is polled, not browsed. The client
# needs an identity and a version per record and nothing else; `name`, `path`,
# `modified`, `source` and the proxy url are all things the LISTING endpoints
# already serve to the screens that render them. A manifest row that carried
# them would be four times the bytes for no decision the client can make with
# them. `s` (size) earns its place because the store budgets disk before it
# starts pulling; `e` (extension) earns its place because the tablet can render
# PDFs and nothing else, and a compact row carries no filename to infer it from.
#
# ── THE 500 CAP, WHICH IS THE WHOLE REASON THIS IS PAGINATED ────────────────
#
# The read this replaces for logbooks is
#
#     GET /logbooks/project/{id}/submitted   ->  .to_list(500)
#
# 500 is a SILENT ceiling. A project past it returns its first 500 rows with
# nothing in the response saying so; no caller can tell a 500-row project from a
# truncated 1300-row one. Against the screens that exist today that is a display
# bug. Against a diff-and-delete client it is a cache shredder: the client's
# rule is "an id the manifest does not name is deleted locally", so every
# logbook past the cap reads as withdrawn and the tablet deletes the compliance
# record a DOB inspector asks for -- offline, where it cannot be fetched back.
#
# So this endpoint does two separate things, and it needs both:
#
#   1. IT PAGES, so the whole set is actually obtainable. Each section carries
#      its own skip and its own has_more, and the client walks to the end.
#      Paging alone is not enough: a client that stops early still holds a
#      partial set and cannot tell.
#
#   2. IT DECLARES `complete`, which is true ONLY when this single response IS
#      the entire approved set -- both sections exhausted AND both skips zero.
#      Deliberately not derivable from the rows: a client cannot tell a short
#      page from a complete one by counting, which is precisely how the 500 cap
#      stayed invisible. The client refuses to delete anything unless it holds a
#      complete assembly, so a paging bug, a dropped page or a mid-walk network
#      failure all degrade to "download but never remove" -- stale, never lost.
#
# The last page of a walk is NOT `complete`, because it is not the whole set. A
# client that fetched only page 2 of 2 would otherwise be told it holds
# everything and delete page 1.
#
# ── SKIP/LIMIT, NOT A CURSOR ────────────────────────────────────────────────
#
# `_id` is ObjectId on some rows and a plain string on others (to_query_id falls
# back), and BSON orders those as different TYPES -- so a `_id > cursor` range
# scan silently skips whole classes of row. Skip/limit over a fixed `_id` sort
# has no such trap. Its known weakness is that a row deleted mid-walk shifts the
# rows behind it back by one and one can be missed; that row is then absent from
# the assembly, is dropped locally and re-downloads on the next poll. Churn,
# self-healing, and never a loss of anything the server still holds.
#
# ── THE FILE FILTER STAYS IN PYTHON ─────────────────────────────────────────
#
# Which files a site device may see is `projects.site_device_subfolders`,
# applied per record by _path_is_under_allowed_subfolder. It cannot be pushed
# into the Mongo query: the comparison is case-insensitive, it is relative to a
# base prefix stored on a DIFFERENT document, and the list is normalised at read
# time. So the page is taken from Mongo and filtered afterwards, exactly as the
# listing endpoint does, calling the SAME helper -- a second copy of that rule
# would be a second thing to get wrong and the two would drift in silence.
#
# One consequence is deliberate and is not a bug: `total` and `has_more` for the
# files section describe the RAW page walk, so a page may return fewer rows than
# its limit, or none at all, while has_more is still true. The walk still covers
# every row exactly once, which is the property that matters. Counting the
# filtered set instead would mean filtering the entire collection on every page.

# One page of manifest rows. Large because the point is to need few round trips
# on a tablet that has just been switched on, bounded because an unbounded limit
# is the same silent-ceiling defect with the number chosen by the caller.
MANIFEST_PAGE_DEFAULT = 1000
MANIFEST_PAGE_MAX = 2000


def _manifest_version(rec: dict):
    """The version half of the client's on-disk name `{id}.{version}.{ext}`.

    NOT A FREE CHOICE. docCache keys a logbook PDF on
    `updated_at || submitted_at || created_at`, and the site logbooks screen
    writes files under exactly that name. A manifest that picked a different
    field -- or a different precedence -- would name the same file differently,
    so every logbook would download a second time and both copies would sit on
    the tablet for ever.

    Naive datetimes are marked UTC for the same reason serialize_id marks them:
    the value is rendered into a filename by `new Date()` on the client, and an
    unmarked one is read as local time and produces a second on-disk copy.
    """
    for field in ("updated_at", "submitted_at", "created_at"):
        v = rec.get(field)
        if v is None or v == "":
            continue
        if isinstance(v, datetime) and v.tzinfo is None:
            return v.replace(tzinfo=timezone.utc)
        return v
    return "0"


def _manifest_ext(name: str) -> str:
    """Lowercased extension, or "" — the store pulls bytes only for what the
    tablet can actually open offline."""
    base = str(name or "").rsplit("/", 1)[-1]
    return base.rsplit(".", 1)[-1].lower() if "." in base else ""


@api_router.get(
    "/projects/{project_id}/manifest",
    dependencies=[Depends(require_approved), Depends(require_project_access)],
)
async def get_project_manifest(
    project_id: str,
    current_user = Depends(get_current_user),
    limit: int = Query(MANIFEST_PAGE_DEFAULT, ge=1, le=MANIFEST_PAGE_MAX),
    files_skip: int = Query(0, ge=0),
    logbooks_skip: int = Query(0, ge=0),
):
    """The complete set this caller is approved to hold offline, as compact rows.

    Response:

        {
          "project_id": str,
          "generated_at": datetime,
          "limit": int,
          "files":    {"rows": [{"id","v","s","e"}], "skip", "total", "has_more"},
          "logbooks": {"rows": [{"id","v"}],         "skip", "total", "has_more"},
          "complete": bool
        }

    `complete` means THIS RESPONSE IS THE WHOLE APPROVED SET. It is false on a
    page with more behind it and false on any page reached with a non-zero skip.
    A client may only delete local records against a complete assembly; see the
    block above this handler for why that rule is what makes the endpoint safe.
    """
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    company_id = get_user_company_id(current_user) or project.get("company_id")
    folder_path = project.get("dropbox_folder_path") or ""

    is_site_device = (
        current_user.get("site_mode")
        or current_user.get("role") == "site_device"
    )
    allowed_subfolders = _normalize_subfolder_names(
        project.get("site_device_subfolders") or []
    )

    def _visible_to_site(path: str) -> bool:
        return _path_is_under_allowed_subfolder(
            path, folder_path, allowed_subfolders
        )

    # ── files ──────────────────────────────────────────────────────────────
    #
    # A site device with nothing configured sees nothing, and the short-circuit
    # is here rather than left to the filter so the query is never issued. Same
    # safe default the listing endpoint applies: a device approved for no
    # subfolder must not enumerate -- let alone download -- a project's Dropbox.
    file_rows = []
    files_total = 0
    if not (is_site_device and not allowed_subfolders):
        file_query = {
            "project_id": project_id,
            "company_id": company_id,
            "is_deleted": {"$ne": True},
        }
        files_total = await db.project_files.count_documents(file_query)
        page = await (
            db.project_files.find(file_query)
            .sort("_id", 1)
            .skip(files_skip)
            .limit(limit)
        ).to_list(limit)
        for rec in page:
            dropbox_path = rec.get("dropbox_path", "")
            # Same visibility path the listing endpoint applies, via the same
            # pair of helpers. A direct upload the listing shows but the
            # manifest omits would render on screen and never reach the offline
            # store — the tablet would go dark on it the moment it lost signal.
            if is_site_device and not _visible_to_site(
                _visibility_path_for_record(rec)
            ):
                continue
            rec_id = str(rec.get("_id", ""))
            if not rec_id:
                continue
            file_rows.append({
                "id": rec_id,
                # `?? 0` is the client's default for a record with no
                # cache_version, and the on-disk name is built from it.
                "v": rec.get("cache_version", 0) or 0,
                "s": rec.get("size", 0) or 0,
                "e": _manifest_ext(rec.get("name") or dropbox_path),
            })

        # ── THUMBNAILS RIDE THE FILE ROWS, NOT A SECTION OF THEIR OWN ──────
        #
        # A parallel `thumbnails` section would need its own copy of the site
        # device's visibility filter, and this file already carries the note
        # about what that costs: "a direct upload the listing shows but the
        # manifest omits would render on screen and never reach the offline
        # store". Two filters is one divergence away from a device that syncs
        # thumbnails for plans it may not open. Hanging a flag on the row that
        # has ALREADY passed the filter cannot drift.
        #
        # `t: 1` means page one has a thumbnail to fetch from
        # GET /projects/{pid}/files/{fid}/thumbnail. It is a FLAG, not a url:
        # the device builds that url from the id it already has, and a row that
        # carried one would put an authenticated endpoint into a cached
        # document.
        #
        # ONE QUERY FOR THE PAGE, bounded by `limit`, projected to two fields.
        # Absent for a plan that was never indexed, which is honest — the
        # endpoint's bottom rung may still produce one by rendering the source
        # PDF, and a device that skips it loses a thumbnail, never a document.
        if file_rows:
            try:
                _thumb_ids = set()
                async for _p in db.document_page_index.find(
                    {"file_id": {"$in": [r["id"] for r in file_rows]},
                     "page_number": 1},
                    {"file_id": 1, "page_thumb_r2_key": 1},
                ):
                    if _p.get("page_thumb_r2_key"):
                        _thumb_ids.add(str(_p.get("file_id")))
                for _r in file_rows:
                    if _r["id"] in _thumb_ids:
                        _r["t"] = 1
            except Exception as _e:
                # A manifest that fails is a device that syncs nothing. A
                # thumbnail flag is not worth that, so this degrades to "no
                # thumbnails known" and the rest of the manifest stands.
                logger.warning(f"manifest thumbnail flags failed: {_e!r}")

    # ── submitted logbooks ─────────────────────────────────────────────────
    #
    # SUBMITTED ONLY. A draft is not a filed record and must never be pulled
    # onto the device an inspector reads from.
    log_query = {
        "project_id": project_id,
        "status": "submitted",
        "is_deleted": {"$ne": True},
    }
    logs_total = await db.logbooks.count_documents(log_query)
    log_page = await (
        db.logbooks.find(log_query)
        .sort("_id", 1)
        .skip(logbooks_skip)
        .limit(limit)
    ).to_list(limit)
    log_rows = [
        {"id": str(rec.get("_id", "")), "v": _manifest_version(rec)}
        for rec in log_page
        if rec.get("_id")
    ]

    files_has_more = (files_skip + limit) < files_total
    logs_has_more = (logbooks_skip + limit) < logs_total

    return {
        "project_id": project_id,
        "generated_at": datetime.now(timezone.utc),
        "limit": limit,
        "files": {
            "rows": file_rows,
            "skip": files_skip,
            "total": files_total,
            "has_more": files_has_more,
        },
        "logbooks": {
            "rows": log_rows,
            "skip": logbooks_skip,
            "total": logs_total,
            "has_more": logs_has_more,
        },
        # Both sections exhausted AND both walks started at zero. Anything less
        # is a fragment, and a fragment must never authorise a deletion.
        "complete": (
            not files_has_more and not logs_has_more
            and files_skip == 0 and logbooks_skip == 0
        ),
    }


# ══ DROPBOX SYNC RUN RECORD ═════════════════════════════════════════════════
#
# WHY THIS EXISTS. The plans screen caches its file list for offline use, and it
# was writing that cache from whatever it happened to read -- including a read
# taken while this background task was still inserting rows. The saved-for-
# offline list could therefore be a strict SUBSET of the project, and a CP in a
# cellar would be missing drawings with nothing on screen to say so.
#
# dropbox_last_synced IS NOT ENOUGH AND IS DELIBERATELY LEFT ALONE. It honestly
# records that a sync finished, and it is stamped UNCONDITIONALLY at the end --
# so it reads the same whether 15 of 15 arrived or 3 of 15 did. That is how 588
# Thomas looked correct while being wrong. It keeps its meaning; the counts live
# here beside it rather than being loaded onto it.
#
# NOT AN IN-PROCESS FLAG. "Is the task still running" could be answered from
# memory today -- the Procfile runs one uvicorn process with no --workers -- and
# that is exactly the objection: it would be correct by accident, resting on
# deployment config, and would silently start lying the day anything scales to
# two processes with no test able to notice.
#
# NOT POLLING FOR A STABLE COUNT EITHER. Files download one at a time and a
# large drawing outlasts any poll interval, so a count that stopped moving is as
# likely to mean mid-download as finished.
DROPBOX_SYNC_RUNS = "dropbox_sync_runs"

# A run older than this is not believed to be running any more. The process can
# die mid-sync -- Railway restarts, an unhandled error above the try -- and a
# record left at "running" for ever would make the client refuse to refresh its
# offline list permanently.
#
# UNKNOWN MUST FAIL TOWARD LETTING THE MAN WORK. The only thing a fresh running
# record buys is a short, bounded window in which the client declines to
# OVERWRITE a good cached list. Past that window the client goes back to normal
# behaviour; it never blocks, never refuses to render, never withholds what is
# already on the device.
DROPBOX_SYNC_STALE_AFTER_SECONDS = 15 * 60


async def _sync_run_open(project_id: str, company_id: str, expected: int):
    """Record that a sync has started, and how many files it expects to see.

    `expected` comes from the recursive listing this task has ALREADY done, so
    it costs nothing extra and is the number the client needs to know whether
    the list it is holding is the whole list.
    """
    now = datetime.now(timezone.utc)
    doc = {
        "project_id": project_id,
        "company_id": company_id,
        "status": "running",
        "expected": expected,
        "synced": 0,
        "failed": 0,
        "failures": [],
        "started_at": now,
        "finished_at": None,
        "created_at": now,
    }
    try:
        res = await db[DROPBOX_SYNC_RUNS].insert_one(doc)
        run_id = str(res.inserted_id)
    except Exception as e:
        # A diagnostic must never take the sync down with it.
        logger.error(f"sync run open failed for project {project_id}: {e}")
        return None

    await _stamp_project_sync(project_id, {
        "run_id": run_id, "status": "running", "expected": expected,
        "synced": 0, "failed": 0,
        "started_at": now, "finished_at": None,
    })
    return run_id


async def _sync_run_close(run_id, project_id: str, status: str,
                          expected: int, synced: int, failures: list):
    """Close the run with counts, and mirror a compact summary onto the project.

    MIRRORED ONTO THE PROJECT ON PURPOSE. GET /projects/{id} is already fetched
    by every screen that needs this, so the client learns the state with no new
    endpoint and no response-shape change. GET /projects/{id}/dropbox-files
    returns a BARE ARRAY and has three callers; wrapping it would break all
    three for nothing.
    """
    now = datetime.now(timezone.utc)
    failed = len(failures)
    try:
        if run_id:
            await db[DROPBOX_SYNC_RUNS].update_one(
                {"_id": to_query_id(run_id)},
                {"$set": {
                    "status": status, "expected": expected, "synced": synced,
                    "failed": failed,
                    # Bounded: a pathological folder must not write a document
                    # larger than the sync it describes.
                    "failures": failures[:50],
                    "finished_at": now,
                }},
            )
    except Exception as e:
        logger.error(f"sync run close failed for project {project_id}: {e}")

    await _stamp_project_sync(project_id, {
        "run_id": str(run_id) if run_id else None, "status": status,
        "expected": expected, "synced": synced, "failed": failed,
        "finished_at": now,
    })


async def _stamp_project_sync(project_id: str, summary: dict):
    """Write the compact summary under `dropbox_sync` on the project.

    SEPARATE FROM dropbox_last_synced, which keeps its own meaning and its own
    field. Nothing here overloads it.
    """
    try:
        sets = {f"dropbox_sync.{k}": v for k, v in summary.items()}
        await db.projects.update_one({"_id": to_query_id(project_id)}, {"$set": sets})
    except Exception as e:
        logger.error(f"sync summary stamp failed for project {project_id}: {e}")


async def _sync_project_to_r2(project_id: str, company_id: str, folder_path: str):
    """Background task: sync Dropbox files to R2 and update project_files collection."""
    try:
        # Dropbox wants "" for root, not "/" — translate our stored sentinel.
        api_path = _dropbox_api_path(folder_path)
        response = await dropbox_api_call(
            company_id, "post",
            "https://api.dropboxapi.com/2/files/list_folder",
            json={"path": api_path, "recursive": True}
        )
        if response.status_code != 200:
            logger.error(f"Sync failed for project {project_id}: Dropbox list_folder returned {response.status_code}")
            # NO RUN IS OPEN YET -- the listing is what tells us how many files
            # to expect, so there is nothing to count. Recorded anyway: a client
            # that sees `failed` with expected 0 knows the sync never got far
            # enough to say anything about the list, which is different from a
            # sync that ran and found nothing.
            await _sync_run_close(
                None, project_id, "failed", 0, 0,
                [{"reason": f"list_folder {response.status_code}"}],
            )
            return

        data = response.json()
        entries = [e for e in data.get("entries", []) if e[".tag"] == "file"]

        # Handle pagination
        while data.get("has_more"):
            cursor_resp = await dropbox_api_call(
                company_id, "post",
                "https://api.dropboxapi.com/2/files/list_folder/continue",
                json={"cursor": data["cursor"]}
            )
            if cursor_resp.status_code != 200:
                break
            data = cursor_resp.json()
            entries.extend([e for e in data.get("entries", []) if e[".tag"] == "file"])

        now = datetime.now(timezone.utc)
        synced = 0
        # Countable, not retried. Making the silent per-file skips visible is
        # this change; doing something about them is separate work.
        failures = []

        run_id = await _sync_run_open(project_id, company_id, len(entries))

        for entry in entries:
            dropbox_path = entry["path_lower"]
            content_hash = entry.get("content_hash", "")
            filename = entry["name"]

            try:
                existing = await db.project_files.find_one({
                    "project_id": project_id, "dropbox_path": dropbox_path
                })

                if existing and existing.get("dropbox_content_hash") == content_hash and content_hash:
                    # Unchanged — just update last_synced_at
                    await db.project_files.update_one(
                        {"_id": existing["_id"]},
                        {"$set": {"last_synced_at": now}}
                    )
                    synced += 1
                    continue

                # New or changed — download from Dropbox
                dl_resp = await dropbox_api_call(
                    company_id, "post",
                    "https://content.dropboxapi.com/2/files/download",
                    headers={"Dropbox-API-Arg": f'{{"path": "{dropbox_path}"}}'}
                )
                if dl_resp.status_code != 200:
                    logger.warning(f"Sync skip {dropbox_path}: download failed {dl_resp.status_code}")
                    failures.append({
                        "path": dropbox_path,
                        "reason": f"download {dl_resp.status_code}",
                    })
                    continue

                file_bytes = dl_resp.content
                r2_key = f"{company_id}/{project_id}/{filename}"
                ct = mimetypes.guess_type(filename)[0] or "application/octet-stream"
                r2_url = ""

                # Upload to R2 (non-blocking)
                if _r2_client:
                    try:
                        r2_url = await asyncio.to_thread(_upload_to_r2, file_bytes, r2_key, ct)
                    except Exception as r2_err:
                        logger.error(f"R2 upload failed for {r2_key}: {r2_err}")

                file_record = {
                    "project_id": project_id,
                    "company_id": company_id,
                    "name": filename,
                    "dropbox_path": dropbox_path,
                    "dropbox_content_hash": content_hash,
                    "r2_key": r2_key if r2_url else "",
                    "r2_url": r2_url,
                    "size": entry.get("size", 0),
                    "modified": entry.get("server_modified", ""),
                    "source": "dropbox_sync",
                    "last_synced_at": now,
                    "updated_at": now,
                }

                if existing:
                    file_record["cache_version"] = existing.get("cache_version", 0) + 1
                    await db.project_files.update_one(
                        {"_id": existing["_id"]},
                        {"$set": file_record}
                    )
                    file_record["_id"] = existing["_id"]
                else:
                    file_record["cache_version"] = 1
                    file_record["created_at"] = now
                    insert_res = await db.project_files.insert_one(file_record)
                    file_record["_id"] = insert_res.inserted_id

                # Sprint 3: spawn plan indexing for PDFs when a file is new/changed.
                # Hash cache inside _index_pdf_file also catches unchanged bytes.
                if (
                    QWEN_API_KEY
                    and filename.lower().endswith(".pdf")
                    and r2_url
                ):
                    asyncio.create_task(
                        _index_pdf_file(project_id, company_id, dict(file_record))
                    )

                synced += 1
            except Exception as entry_err:
                logger.error(f"Sync error for {dropbox_path}: {entry_err}")
                failures.append({"path": dropbox_path, "reason": str(entry_err)[:200]})

        # Update sync timestamp. UNCHANGED, and deliberately: this field
        # honestly records that a sync finished, and the counts that say WHAT it
        # finished with live in the run record beside it.
        await db.projects.update_one(
            {"_id": to_query_id(project_id)},
            {"$set": {"dropbox_last_synced": now}}
        )
        await _sync_run_close(
            run_id, project_id, "complete", len(entries), synced, failures,
        )
        logger.info(f"Sync complete for project {project_id}: {synced}/{len(entries)} files")

    except Exception as e:
        logger.error(f"Background sync failed for project {project_id}: {e}")
        # A run left at "running" would make the client decline to refresh its
        # offline list until the staleness window expired. Close it.
        try:
            await _sync_run_close(
                locals().get("run_id"), project_id, "failed",
                len(locals().get("entries") or []), locals().get("synced") or 0,
                (locals().get("failures") or []) + [{"reason": str(e)[:200]}],
            )
        except Exception:
            pass


@api_router.post("/projects/{project_id}/sync-dropbox", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def sync_project_dropbox(project_id: str, current_user = Depends(get_current_user)):
    """Sync/refresh project files from Dropbox — returns immediately, runs sync in background"""
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    company_id = get_user_company_id(current_user)
    if company_id and project.get("company_id") != company_id:
        raise HTTPException(status_code=403, detail="Access denied to this project")

    folder_path = project.get("dropbox_folder_path")
    if not folder_path:
        raise HTTPException(status_code=400, detail="No Dropbox folder linked")

    company_id = company_id or project.get("company_id")

    # Dropbox wants "" for root, not "/" — translate our stored sentinel.
    api_path = _dropbox_api_path(folder_path)

    # Quick count from Dropbox for immediate response
    response = await dropbox_api_call(
        company_id, "post",
        "https://api.dropboxapi.com/2/files/list_folder",
        json={"path": api_path, "recursive": True}
    )

    file_count = 0
    if response.status_code == 200:
        data = response.json()
        file_count = len([e for e in data.get("entries", []) if e[".tag"] == "file"])

    # Launch background sync
    asyncio.create_task(_sync_project_to_r2(project_id, company_id, folder_path))

    return {"message": "Sync started", "file_count": file_count}

@api_router.get("/projects/{project_id}/dropbox-file-url")
async def get_dropbox_file_url(project_id: str, file_path: str, current_user = Depends(get_current_user)):
    """Get a download/preview URL for a project file (R2 preferred, Dropbox fallback)"""
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    company_id = get_user_company_id(current_user)
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")

    company_id = company_id or project.get("company_id")

    # Check project_files for R2 URL first (company-scoped)
    file_rec = await db.project_files.find_one({
        "project_id": project_id, "company_id": company_id, "dropbox_path": file_path
    })
    if file_rec and file_rec.get("r2_key"):
        proxy = f"/api/projects/{project_id}/files/{str(file_rec['_id'])}/content"
        return {"url": proxy, "cached": False, "source": "r2_proxy"}
    if file_rec and file_rec.get("r2_url"):
        return {"url": file_rec["r2_url"], "cached": True, "source": "r2"}

    # Check in-memory Dropbox URL cache
    cached_url = _get_cached_url(company_id, file_path)
    if cached_url:
        return {"url": cached_url, "cached": True, "source": "dropbox_cache"}

    # Fall back to Dropbox temporary link
    response = await dropbox_api_call(
        company_id, "post",
        "https://api.dropboxapi.com/2/files/get_temporary_link",
        json={"path": file_path}
    )

    if response.status_code != 200:
        raise HTTPException(status_code=400, detail="Failed to get file URL")

    data = response.json()
    url = data.get("link", "")
    _set_cached_url(company_id, file_path, url)
    return {"url": url, "cached": False, "source": "dropbox"}


# ==================== DIRECT FILE UPLOAD (R2) ====================

def _sanitize_upload_filename(raw: str) -> str:
    """Normalize an uploaded filename for safe R2 storage.

    - URL-decodes any %XX escapes (React Native / some browsers send them encoded).
    - Strips directory path components (basename only).
    - Collapses multiple spaces.
    - Replaces characters that make R2 public URLs awkward (#, ?) with '_'.
    - Keeps spaces, parentheses, dashes — those are fine in keys, R2/browsers
      handle them with single URL-encoding in flight.
    """
    import urllib.parse as _urlparse
    from pathlib import PurePosixPath
    name = raw or "upload.pdf"
    # Strip any path, take basename
    name = PurePosixPath(name.replace("\\", "/")).name or "upload.pdf"
    # Decode %XX until stable (handle double-encoding seen in some clients)
    for _ in range(3):
        decoded = _urlparse.unquote(name)
        if decoded == name:
            break
        name = decoded
    # Replace characters that break R2 URLs
    for ch in ["#", "?", "\n", "\r", "\t"]:
        name = name.replace(ch, "_")
    name = " ".join(name.split())  # collapse whitespace
    if not name.lower().endswith(".pdf"):
        name = name + ".pdf"
    return name[:180]  # cap length


async def _log_upload_attempt(record: dict):
    """Fire-and-forget log of upload attempts to help diagnose failures."""
    try:
        record["received_at"] = datetime.now(timezone.utc)
        await db.upload_attempts_log.insert_one(record)
    except Exception:
        pass  # never let logging break the request


@api_router.post("/projects/{project_id}/upload-file", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def upload_project_file(project_id: str, request: Request, file: UploadFile = File(...), current_user = Depends(get_current_user)):
    """Upload a file directly to R2 storage for a project (PDF only, max 100 MB)."""
    _log_base = {
        "project_id":      project_id,
        "raw_filename":    file.filename or "",
        "content_type":    file.content_type or "",
        "actor_email":     current_user.get("email", ""),
        "remote_addr":     request.client.host if request and request.client else "",
        "user_agent":      request.headers.get("user-agent", "") if request else "",
    }

    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        await _log_upload_attempt({**_log_base, "outcome": "404_project_not_found"})
        raise HTTPException(status_code=404, detail="Project not found")

    company_id = get_user_company_id(current_user)
    if company_id and project.get("company_id") != company_id:
        await _log_upload_attempt({**_log_base, "outcome": "403_wrong_company"})
        raise HTTPException(status_code=403, detail="Access denied to this project")
    company_id = company_id or project.get("company_id")

    # Validate file type (accept .pdf regardless of case; decode if URL-encoded)
    filename = _sanitize_upload_filename(file.filename or "upload.pdf")
    if not filename.lower().endswith(".pdf"):
        await _log_upload_attempt({**_log_base, "outcome": "400_not_pdf", "sanitized_filename": filename})
        raise HTTPException(status_code=400, detail="Only PDF files are allowed")

    # Read and validate size (100 MB max)
    try:
        file_bytes = await file.read()
    except Exception as e:
        logger.error(f"upload read failed for {filename}: {e}", exc_info=True)
        await _log_upload_attempt({**_log_base, "outcome": "400_read_failed", "error": str(e)[:500]})
        raise HTTPException(status_code=400, detail=f"Could not read uploaded file: {e}")
    if not file_bytes:
        await _log_upload_attempt({**_log_base, "outcome": "400_empty_file", "sanitized_filename": filename})
        raise HTTPException(status_code=400, detail="Uploaded file is empty.")
    max_size = 100 * 1024 * 1024
    if len(file_bytes) > max_size:
        await _log_upload_attempt({**_log_base, "outcome": "400_too_large", "size": len(file_bytes)})
        raise HTTPException(status_code=400, detail="File too large. Maximum 100 MB.")

    if not _r2_client:
        await _log_upload_attempt({**_log_base, "outcome": "503_r2_not_configured", "size": len(file_bytes)})
        raise HTTPException(status_code=503, detail="File storage (R2) is not configured")

    # De-dup: if a record with the same name already exists on this project,
    # suffix with a timestamp so we don't overwrite the original in R2.
    existing_same = await db.project_files.find_one({
        "project_id": project_id,
        "name": filename,
        "is_deleted": {"$ne": True},
    })
    if existing_same:
        stem, _, ext = filename.rpartition(".")
        ts = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
        filename = f"{stem or filename}-{ts}.{ext or 'pdf'}"

    r2_key = f"{company_id}/{project_id}/{filename}"
    try:
        r2_url = await asyncio.to_thread(_upload_to_r2, file_bytes, r2_key, "application/pdf")
    except Exception as e:
        logger.error(f"Direct upload R2 error (key={r2_key}): {e}", exc_info=True)
        await _log_upload_attempt({**_log_base, "outcome": "500_r2_error", "r2_key": r2_key, "error": str(e)[:500]})
        raise HTTPException(status_code=500, detail=f"Storage error: {str(e)[:200]}")

    now = datetime.now(timezone.utc)
    file_record = {
        "project_id": project_id,
        "company_id": company_id,
        "name": filename,
        "dropbox_path": "",
        "dropbox_content_hash": "",
        "r2_key": r2_key,
        "r2_url": r2_url,
        "size": len(file_bytes),
        "modified": now.isoformat(),
        "source": "direct_upload",
        "cache_version": 1,
        "created_at": now,
        "updated_at": now,
        "uploaded_by": current_user.get("id"),
    }
    try:
        result = await db.project_files.insert_one(file_record)
    except Exception as e:
        logger.error(f"project_files insert failed: {e}", exc_info=True)
        await _log_upload_attempt({**_log_base, "outcome": "500_mongo_error", "error": str(e)[:500]})
        raise HTTPException(status_code=500, detail=f"Metadata write error: {str(e)[:200]}")
    file_record["_id"] = str(result.inserted_id)
    file_record.pop("created_at", None)
    file_record.pop("updated_at", None)

    # Sprint 3: spawn plan indexing for PDFs (no-op if QWEN_API_KEY unset)
    if filename.lower().endswith(".pdf") and QWEN_API_KEY:
        asyncio.create_task(_index_pdf_file(project_id, company_id, file_record))

    proxy_url = f"/api/projects/{project_id}/files/{file_record['_id']}/content"
    await _log_upload_attempt({
        **_log_base,
        "outcome": "200_ok",
        "sanitized_filename": filename,
        "r2_key": r2_key,
        "size": len(file_bytes),
        "file_id": file_record["_id"],
    })
    return {
        "id": file_record["_id"],
        "name": filename,
        "r2_url": proxy_url,
        "size": len(file_bytes),
        "source": "direct_upload",
    }


@api_router.get("/debug/bis-scraper-state")
async def debug_bis_scraper_state(current_user=Depends(get_current_user)):
    """Dump the state the BIS scraper has written to Mongo, so we can
    verify it's actually getting through DOB's Akamai gate without
    tailing Railway logs.

    Reports (owner/admin only):
      - Per-project initial-scan markers (source='bis')
      - Per-license insurance fetch cache entries + record counts
      - Companies whose gc_license_number/gc_insurance_records came
        from the scraper
      - Recent dob_logs written with source='bis_scraper'
      - Tracked projects the scraper should be hitting (for reference)
    """
    role = (current_user.get("role") or "").lower()
    if role not in ("owner", "admin"):
        raise HTTPException(status_code=403, detail="Admin access required")

    company_id = get_user_company_id(current_user)
    now = datetime.now(timezone.utc)

    # 1. Tracked projects the scraper should be scanning.
    proj_filter: Dict[str, Any] = {
        "track_dob_status": True,
        "nyc_bin":          {"$exists": True, "$ne": ""},
        "is_deleted":       {"$ne": True},
    }
    if company_id:
        proj_filter["company_id"] = company_id
    tracked = await db.projects.find(
        proj_filter,
        {"name": 1, "nyc_bin": 1, "company_id": 1},
    ).to_list(200)

    # 2. initial_scan_done:bis markers per project.
    bis_markers = await db.system_config.find(
        {"key": {"$regex": "^initial_scan_done:bis:"}}
    ).to_list(500)
    markers_by_pid: Dict[str, Any] = {}
    for m in bis_markers:
        pid = str(m.get("project_id") or m.get("key", "").split(":")[-1] or "")
        if pid:
            markers_by_pid[pid] = m.get("completed_at")

    # 3. Insurance fetch cache — per unique license.
    fetches = await db.system_config.find(
        {"key": {"$regex": "^insurance_fetch:"}}
    ).sort("last_fetched_at", -1).to_list(200)
    fetch_rows = []
    for f in fetches:
        last = f.get("last_fetched_at")
        if isinstance(last, datetime):
            if last.tzinfo is None:
                last = last.replace(tzinfo=timezone.utc)
            hours_ago = round((now - last).total_seconds() / 3600.0, 1)
        else:
            hours_ago = None
        fetch_rows.append({
            "license_number":      f.get("license_number"),
            "last_fetched_at":     str(last) if last else None,
            "hours_since_fetch":   hours_ago,
            "last_record_count":   f.get("last_record_count"),
        })

    # 4. Companies with scraper-sourced license or insurance.
    comp_filter: Dict[str, Any] = {
        "$or": [
            {"gc_license_source": "bis_scraper"},
            {"gc_insurance_records.source": "bis_scraper"},
        ],
    }
    if company_id:
        comp_filter["_id"] = to_query_id(company_id)
    companies = await db.companies.find(comp_filter).to_list(200)
    company_rows = []
    for c in companies:
        ins = c.get("gc_insurance_records") or []
        scraper_ins = [
            {
                "type":       i.get("insurance_type"),
                "expiration": i.get("expiration_date"),
                "is_current": i.get("is_current"),
                "carrier":    i.get("carrier_name"),
                "source":     i.get("source"),
            }
            for i in ins
        ]
        company_rows.append({
            "company_id":          str(c.get("_id")),
            "name":                c.get("name") or c.get("gc_business_name"),
            "gc_license_number":   c.get("gc_license_number"),
            "gc_license_source":   c.get("gc_license_source"),
            "gc_last_verified":    str(c.get("gc_last_verified") or ""),
            "insurance_records":   scraper_ins,
        })

    # 5. Recent dob_logs with source='bis_scraper' (cap 20).
    log_filter: Dict[str, Any] = {"source": "bis_scraper"}
    if company_id:
        log_filter["company_id"] = company_id
    recent_logs = await db.dob_logs.find(log_filter).sort("detected_at", -1).limit(20).to_list(20)
    log_rows = [{
        "detected_at":  str(r.get("detected_at")),
        "project_id":   r.get("project_id"),
        "record_type":  r.get("record_type"),
        "severity":     r.get("severity"),
        "raw_dob_id":   r.get("raw_dob_id"),
        "summary":      (r.get("ai_summary") or "")[:200],
    } for r in recent_logs]

    bis_log_total = await db.dob_logs.count_documents(log_filter)

    # 6. Per-project summary — join tracked list with markers + company license.
    project_rows = []
    for p in tracked:
        pid = str(p.get("_id"))
        cid = p.get("company_id") or ""
        comp = None
        try:
            comp = await db.companies.find_one(
                {"_id": to_query_id(cid)} if cid else {"_id": None},
                {"gc_license_number": 1, "gc_license_source": 1},
            )
        except Exception:
            comp = None
        project_rows.append({
            "project_id":           pid,
            "name":                 p.get("name"),
            "nyc_bin":              p.get("nyc_bin"),
            "initial_scan_done_at": str(markers_by_pid.get(pid) or ""),
            "company_id":           cid,
            "company_license":      (comp or {}).get("gc_license_number"),
            "license_source":       (comp or {}).get("gc_license_source"),
        })

    return {
        "now":                      now.isoformat(),
        "tracked_project_count":    len(tracked),
        "projects":                 project_rows,
        "insurance_fetch_cache":    fetch_rows,
        "companies_with_scraper_data": company_rows,
        "recent_bis_dob_logs":      log_rows,
        "total_bis_dob_logs":       bis_log_total,
        "interpretation": {
            "scraper_is_hitting_bis": (
                bool(recent_logs) or bool(markers_by_pid) or bool(fetches)
            ),
            "scraper_is_capturing_licenses": bool(company_rows),
            "scraper_is_fetching_insurance": any(
                (r.get("last_record_count") or 0) > 0 for r in fetch_rows
            ),
        },
    }


