@api_router.post("/projects/{project_id}/safety-staff", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def create_safety_staff(project_id: str, data: SafetyStaffCreate, admin = Depends(get_admin_user)):
    """Register a Site Safety Coordinator (SSC) or Site Safety Manager (SSM) for a project."""
    project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    if data.role not in ("ssc", "ssm"):
        raise HTTPException(status_code=422, detail="Role must be 'ssc' or 'ssm'")

    now = datetime.now(timezone.utc)
    staff_dict = data.model_dump()
    staff_dict["company_id"] = project.get("company_id")
    staff_dict["created_at"] = now
    staff_dict["updated_at"] = now
    staff_dict["is_deleted"] = False

    result = await db.safety_staff_registrations.insert_one(staff_dict)

    await audit_log("safety_staff_create", str(admin.get("_id", admin.get("id", ""))), "safety_staff", str(result.inserted_id), {
        "role": data.role, "name": data.name, "license_number": data.license_number, "project_id": project_id,
    })

    staff_dict["id"] = str(result.inserted_id)
    return staff_dict

@api_router.put("/safety-staff/{staff_id}")
async def update_safety_staff(staff_id: str, data: dict, admin = Depends(get_admin_user)):
    """Update a safety staff registration."""
    ALLOWED_FIELDS = {"name", "license_number", "license_expiration", "phone", "email", "role"}
    update_data = {k: v for k, v in data.items() if v is not None and k in ALLOWED_FIELDS}
    update_data["updated_at"] = datetime.now(timezone.utc)

    result = await db.safety_staff_registrations.update_one(
        {"_id": to_query_id(staff_id)},
        {"$set": update_data}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Safety staff not found")

    updated = await db.safety_staff_registrations.find_one({"_id": to_query_id(staff_id)})
    return serialize_id(updated)

@api_router.delete("/safety-staff/{staff_id}")
async def delete_safety_staff(staff_id: str, admin = Depends(get_admin_user)):
    """Soft delete a safety staff registration."""
    result = await db.safety_staff_registrations.update_one(
        {"_id": to_query_id(staff_id)},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Safety staff not found")

    await audit_log("safety_staff_delete", str(admin.get("_id", admin.get("id", ""))), "safety_staff", staff_id)
    return {"message": "Safety staff removed"}

# ==================== GOOGLE PLACES AUTOCOMPLETE ====================

@api_router.get("/places/autocomplete")
async def places_autocomplete(input: str, types: str = "address", current_user = Depends(get_current_user)):
    """Proxy Google Places Autocomplete to avoid exposing API key on client."""
    if not GOOGLE_PLACES_API_KEY:
        raise HTTPException(status_code=501, detail="Google Places API key not configured")
    
    if not input or len(input) < 2:
        return {"predictions": []}
    
    try:
        async with ServerHttpClient() as client:
            response = await client.get(
                "https://maps.googleapis.com/maps/api/place/autocomplete/json",
                params={
                    "input": input,
                    "types": types,
                    "components": "country:us",
                    "key": GOOGLE_PLACES_API_KEY,
                },
                timeout=5.0,
            )
            data = response.json()
            if data.get("status") != "OK" and data.get("status") != "ZERO_RESULTS":
                logger.warning(f"Places API error: {data.get('status')} - {data.get('error_message', '')}")
            
            return {"predictions": data.get("predictions", [])}
    except httpx.RequestError as e:
        logger.error(f"Places API request failed: {e}")
        raise HTTPException(status_code=502, detail="Could not reach Google Places API")
		
@api_router.get("/weather")
async def get_weather(lat: Optional[float] = None, lng: Optional[float] = None, address: Optional[str] = None, current_user = Depends(get_current_user)):
    """
    Get current weather using OpenWeather API.
    Pass lat/lng directly, or address for geocoding.
    Falls back to NYC (40.7128, -74.0060) if no location provided.
    """
    api_key = os.environ.get('OPENWEATHER_API_KEY')
    if not api_key:
        raise HTTPException(status_code=500, detail="Weather API key not configured")

    latitude = lat or 40.7128
    longitude = lng or -74.0060

    try:
        async with ServerHttpClient(timeout=10.0) as client:
            # If address provided but no lat/lng, geocode via OpenWeather
            if address and not lat:
                geo_url = (
                    f"https://api.openweathermap.org/geo/1.0/direct"
                    f"?q={address}&limit=1&appid={api_key}"
                )
                geo_res = await client.get(geo_url)
                if geo_res.status_code == 200:
                    geo_data = geo_res.json()
                    if geo_data and len(geo_data) > 0:
                        latitude = geo_data[0].get("lat", latitude)
                        longitude = geo_data[0].get("lon", longitude)

            # Fetch current weather from OpenWeather
            weather_url = (
                f"https://api.openweathermap.org/data/2.5/weather"
                f"?lat={latitude}&lon={longitude}"
                f"&units=imperial&appid={api_key}"
            )
            res = await client.get(weather_url)
            if res.status_code != 200:
                logger.error(f"OpenWeather API error: {res.status_code} {res.text}")
                raise HTTPException(status_code=502, detail="Weather API unavailable")

            data = res.json()
            main = data.get("main", {})
            wind = data.get("wind", {})
            weather_list = data.get("weather", [{}])
            weather_main = weather_list[0].get("main", "") if weather_list else ""
            weather_desc = weather_list[0].get("description", "") if weather_list else ""

            # Map OpenWeather main condition to our app's weather options
            condition_map = {
                "Clear": "Sunny",
                "Clouds": "Cloudy",
                "Rain": "Rainy",
                "Drizzle": "Rainy",
                "Thunderstorm": "Stormy",
                "Snow": "Snow",
                "Mist": "Fog",
                "Fog": "Fog",
                "Haze": "Fog",
                "Smoke": "Fog",
                "Dust": "Windy",
                "Sand": "Windy",
                "Squall": "Windy",
                "Tornado": "Stormy",
            }
            condition = condition_map.get(weather_main, "Cloudy")

            # Check if it's very windy (> 20 mph) regardless of condition
            wind_speed = wind.get("speed", 0)
            if wind_speed > 20 and condition not in ("Stormy", "Snow", "Rainy"):
                condition = "Windy"

            return {
                "temperature": main.get("temp"),
                "feels_like": main.get("feels_like"),
                "humidity": main.get("humidity"),
                "wind_speed": wind_speed,
                "condition": condition,
                "description": weather_desc,
            }
    except httpx.RequestError as e:
        logger.error(f"Weather fetch failed: {e}")
        raise HTTPException(status_code=502, detail="Could not fetch weather data")

@api_router.get("/logbooks/project/{project_id}/checkins-today")
async def get_project_checkins_today(project_id: str, date: Optional[str] = None, envelope: bool = False, current_user = Depends(get_current_user), _proj = Depends(require_project_access)):
    """Get all workers checked in to a project on a given date (for
    auto-populating log books).

    ENVELOPE (`?envelope=1`) — OPT-IN, AND THE DEFAULT IS BYTE-IDENTICAL.
    Without the flag this returns the bare list it always has, because three
    screens already consume that shape (osha_log.jsx:98, preshift_signin.jsx:116,
    toolbox_talk.jsx:170) and none of them should have to change to add a
    capability they do not use.

    With it, the same rows come back under `workers`, plus what the bare list
    could never say:

        {"workers": [...], "partial": bool, "degraded_passes": [...],
         "collapsed": N, "truncated_passes": [...]}

    WHY THIS EXISTS. Each of the three passes below swallows its own failure
    and contributes nothing, and the bare list cannot distinguish "nobody else
    was on site" from "a query failed and those men are missing". A CP building
    a SIGNED log off a short roster would be attesting to a jobsite that did
    not exist. `partial` is true when any pass degraded, truncated, or dropped
    a row to the dedupe key; the caller is expected to say so rather than
    render a short list as if it were complete.

    `collapsed` counts rows dropped by the (name, company) dedupe guard in
    passes 2 and 3. That guard is what stops a worker present in BOTH the gate
    and legacy systems from being listed twice, but it cannot tell that case
    apart from two different men who share a name at one subcontractor — the
    two id spaces have no join key (WorkerEnrollment carries no worker_id;
    card_audit.py:272-290). So the drop is COUNTED rather than silently taken,
    and a non-zero count means the headcount may be short by that many.

    Merges two sources so the rollout from the legacy `checkins`
    collection to the new gate-based `sign_ins` + `worker_enrollments`
    can happen without breaking existing logbooks:

      1. NEW: sign_ins + worker_enrollments + daily_signatures for the
         given calendar date. Workers who signed at the gate today
         appear here with their daily signature auto-filled — no
         physical sign-on-admin's-tablet needed.
      2. LEGACY: the pre-existing `checkins` collection for workers
         who haven't migrated. Their signature comes from the per-
         worker `workers.signature` field as before.

    Dedup key: lower(name)+lower(company). New-system rows win on
    collision because their signature is the day's attestation, not
    a static profile image.

    FIX 1 — every row additionally carries five flag fields so the pre-shift
    roster can name WHY a worker is flagged and act on it without a second
    lookup: checkin_id, sst_status, needs_trade_assignment, review_decision,
    cert_warnings. Only PASS 2 (legacy `checkins`) can populate them — they
    are fields OF a checkins row. Pass 1 (gate sign_ins) and pass 3
    (compliance_alerts) have no such row, so they emit checkin_id=None and
    the rest null/false/[]; a null checkin_id is the UI's signal that no
    action can be offered. Nothing new is persisted by this change.
    """
    from zoneinfo import ZoneInfo
    eastern = ZoneInfo("America/New_York")
    now_eastern = datetime.now(eastern)
    target_date = date or now_eastern.strftime("%Y-%m-%d")

    # Parse date using Eastern Time boundaries for NYC compliance
    try:
        day_eastern = datetime.strptime(target_date, "%Y-%m-%d").replace(tzinfo=eastern)
        day_start = day_eastern.astimezone(timezone.utc)
        day_end = (day_eastern + timedelta(hours=24)).astimezone(timezone.utc)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid date format")

    result: List[Dict[str, Any]] = []
    # NORMALISED IDENTITY KEYS for the three-pass merge below.
    #
    # The passes read the company from different places — the gate pass from
    # the enrollment's `sub_name`, the legacy pass from the check-in's
    # `worker_company` (or the worker doc) — so a trailing or doubled space on
    # either side made the raw lowercased pair miss and emitted the SAME MAN
    # twice: once from the gate WITH his card id, once from legacy WITHOUT one.
    # That is the duplicate row found on a production pre-shift sheet.
    def _norm_key(v):
        return " ".join(str(v or "").split()).casefold()

    # THE ONLY RELIABLE IDENTITY IN THIS MERGE. A worker_id is an id; the
    # (name, company) pair below is a STRING STANDING IN for one, and it has
    # now produced four separate defects on this project.
    #
    # THE DEFECT THIS CLOSES, from production (project 6a5f63bc147407d3261df2c7,
    # preshift_signin, 2026-08-12): worker_id 6a79b9f19d8cee518e4712c4 appeared
    # TWICE in one stored roster — once complete from pass 2 (company "AAZ",
    # OSHA number, signature) and once stripped from pass 3 (company "", no
    # number, no signature). Pass 3 reads compliance_alerts, whose rows often
    # carry NO worker_company, so its key was ('wilmer carrillo', '') against
    # pass 2's ('wilmer carrillo', 'aaz') — a miss, and the same man was
    # emitted again. There were ZERO worker_enrollments for him, so pass 1
    # never ran; this was never a two-card case.
    #
    # SAME worker_id IS THE SAME MAN, whatever company string came back with
    # him. This does NOT collapse two men who share a name — they have
    # different worker_ids — so it is strictly safer than the string key and
    # runs BEFORE it. The string key stays as the fallback for a row that
    # carries no id at all.
    seen_worker_ids: set = set()
    seen_name_keys: set = set()
    # Names seen so far, company ignored. Used ONLY as a fallback for a row
    # that carries no company at all: a blank company distinguishes nobody, so
    # it must not be what mints a second row for a name already reported.
    seen_names_only: set = set()
    # Roster-integrity accounting for the envelope. Every one of these is a way
    # the list below can come back SHORT while still looking complete.
    _degraded: List[str] = []        # a pass raised and contributed nothing
    _truncated: List[str] = []       # a pass hit its to_list ceiling
    _collapsed = 0                   # rows dropped by the (name, company) guard
    _GATE_LIMIT, _LEGACY_LIMIT, _BLOCKED_LIMIT = 1000, 500, 500

    # ── PASS 1: New-system gate sign_ins ────────────────────────────────
    try:
        import card_audit as _ca
        sign_ins = await db.sign_ins.find({
            "project_id": project_id,
            "timestamp": {"$gte": day_start, "$lt": day_end},
        }).to_list(_GATE_LIMIT)
        if len(sign_ins) >= _GATE_LIMIT:
            _truncated.append("gate")

        # Unique worker_enrollment_ids from today's sign_ins
        enrollment_ids = []
        seen_eids: set = set()
        first_checkin_at: Dict[str, datetime] = {}
        for si in sign_ins:
            eid = si.get("worker_enrollment_id")
            if not eid:
                continue
            ts = si.get("timestamp")
            if eid not in seen_eids:
                seen_eids.add(eid)
                enrollment_ids.append(eid)
            if isinstance(ts, datetime):
                cur = first_checkin_at.get(eid)
                if cur is None or ts < cur:
                    first_checkin_at[eid] = ts

        # Pull enrollments and today's daily signatures in bulk
        enrollment_map: Dict[str, Dict[str, Any]] = {}
        if enrollment_ids:
            enrollment_object_ids = []
            for eid in enrollment_ids:
                try:
                    enrollment_object_ids.append(ObjectId(eid))
                except Exception:
                    pass
            async for e in db.worker_enrollments.find({"_id": {"$in": enrollment_object_ids}}):
                enrollment_map[str(e["_id"])] = e

        sig_map: Dict[str, str] = {}
        async for sig in db.daily_signatures.find({
            "project_id": project_id,
            "calendar_date": target_date,
            "worker_enrollment_id": {"$in": enrollment_ids},
        }):
            key = sig.get("signature_r2_key")
            if key:
                sig_map[sig["worker_enrollment_id"]] = key

        for eid in enrollment_ids:
            e = enrollment_map.get(eid)
            if not e:
                continue
            # NULLISH TAKES THE PATH A BLANK NAME ALREADY TAKES.
            #
            # `"null"` is not blank. It is four characters, it survives
            # `.strip()`, and `_norm_key` casefolds it to the string "null" —
            # a LIVE DEDUPE KEY. Two different men whose cards could not be
            # read both key as ("null", <company>) and the second is dropped
            # as a duplicate of the first. That is the opposite failure from
            # the case-variance one recorded beside it: "null" COLLAPSES
            # distinct workers, case variance SPLITS one.
            #
            # NOT A NEW POLICY FOR AN UNNAMED ROW. Each pass keeps whatever it
            # already does with a blank name — pass 3 skips one outright
            # (`or not name: continue`), the others let it form a key. This
            # only stops a token that means "nothing was read" from behaving
            # like a name. See lib/ocr_text.py.
            name = norm_ocr_str(e.get("worker_name")) or ""
            company = _worker_company(e.get("sub_name"))
            name_key = (_norm_key(name), _norm_key(company))
            seen_name_keys.add(name_key)
            seen_names_only.add(name_key[0])
            # Registered so a LATER pass carrying the same id skips him. Pass 1
            # itself still dedupes per ENROLLMENT, which is unique per card, so
            # two cards remain two rows.
            seen_worker_ids.add(str(eid))
            first_ts = first_checkin_at.get(eid)
            # Use the first sign_in of the day as the stable reference —
            # the frontend builds /api/signatures/{signin_id} from this.
            # No presigned URL is returned; access goes through the
            # authenticated proxy so the image is fetchable for the full
            # session, not just an hour.
            first_signin_id = None
            for si in sign_ins:
                if si.get("worker_enrollment_id") == eid:
                    first_signin_id = str(si["_id"])
                    break
            result.append({
                "worker_id": eid,   # enrollment id serves the same role
                "worker_name": name or "Unknown",
                "company": company,
                "trade": e.get("trade") or "",
                "check_in_time": first_ts.isoformat() if isinstance(first_ts, datetime) else "",
                "osha_number": e.get("card_id") or "",   # SST card id doubles as the worker's ID number
                "certifications": [],
                "worker_signature": None,               # new system: frontend uses signin_id
                "signin_id": first_signin_id,           # → /api/signatures/{signin_id}
                "source": "gate_checkin",
                # TOOLBOX ROSTER — EMITTED, AND ALWAYS FALSE ON THIS PASS.
                #
                # The key was absent entirely, so the client read `undefined`
                # and the toolbox roster's Confirmed column was unreachable for
                # this population rather than merely false. Emitting it makes
                # the shape match the legacy pass below.
                #
                # IT CANNOT YET BE TRUE, and that is the real defect: the
                # optional confirmation is offered on ONE check-in path only —
                # checkin.html posts `toolbox_talk_confirm` to
                # /checkin/register-and-checkin (server.py:9955), which writes
                # it onto a `checkins` row. The card/enrollment path in
                # card_audit.py writes `sign_ins` + `worker_enrollments` and
                # contains no reference to a toolbox confirmation at all — no
                # control on the page, no field on the row. So a worker who
                # arrives by card can never confirm, and this hardcoded False
                # is the honest report of that, NOT a value read from a row.
                #
                # Closing it means capturing the tap on the enrollment flow —
                # a change to the gate page itself, which is the turnstile.
                # Scoped separately rather than smuggled in here.
                # The card/enrollment path has no affirmation control, so
                # this is false by construction, not by a read. Same honesty
                # as the toolbox pair below it.
                "signature_affirmed": False,
                "signature_affirmed_at": None,
                "signature_affirmed_lang": None,
                "toolbox_talk_confirmed": False,
                "toolbox_talk_confirmed_at": None,
                # ── Flag fields (FIX 1) ──────────────────────────────────────
                # The gate system writes `sign_ins` + `worker_enrollments` ONLY:
                # card_audit.py contains no reference to the `checkins`
                # collection at all (see _write_cookie_signin, card_audit.py:1283
                # and the enrollment path at card_audit.py:1926 — both insert a
                # sign_ins row and stop). So a gate-signed worker has NO
                # checkins row, and therefore NO id to POST against
                # /checkins/{checkin_id}/review or /assign-trade.
                #
                # checkin_id is emitted as null rather than fabricated. The
                # per-check-in cert snapshot (sst_status / cert_warnings /
                # review_decision) and needs_trade_assignment are all fields of
                # a checkins row, so they do not exist for this population
                # either — they are reported as null/false/[] , never guessed.
                # The UI must offer NO action when checkin_id is null.
                #
                # (Enrollment also hard-requires a trade — card_audit.py:1832
                # rejects a submission with no `trade` — so a gate worker can
                # never be in the needs_trade_assignment state to begin with.)
                "checkin_id": None,
                "sst_status": None,
                "needs_trade_assignment": False,
                "review_decision": None,
                "cert_warnings": [],
            })
    except Exception as _e:
        logger.warning(f"checkins-today new-system merge failed: {_e!r}")
        _degraded.append("gate")

    # ── PASS 2: Legacy checkins for workers not on the new system ──────
    try:
        legacy = await db.checkins.find({
            "project_id": project_id,
            "check_in_time": {"$gte": day_start, "$lt": day_end},
            "is_deleted": {"$ne": True},
        }).to_list(_LEGACY_LIMIT)
        if len(legacy) >= _LEGACY_LIMIT:
            _truncated.append("legacy")
    except Exception:
        legacy = []
        _degraded.append("legacy")

    # ── THE PAIRING, FOR ROWS THAT FROZE NO TRADE ───────────────────────────
    #
    # `checkins.worker_trade` is an OBSERVATION: what was recorded at the gate
    # the moment this man walked through, frozen onto an immutable row. When it
    # holds a trade, that trade stands — see the row below.
    #
    # When it holds NOTHING, the row is not evidence that this worker has no
    # trade; it is evidence that nobody had recorded one yet. The answer to
    # "what does he do on this project" lives in worker_project_trades, and
    # until now this endpoint never looked: an admin correcting a pairing could
    # not change a check-in written that morning, so the daily jobsite log named
    # crews with no trade on a signed §3301.2 record, and every crew fell back
    # to the unfiltered activity-chip catalogue because chips key on the trade.
    #
    # ONE QUERY, NOT ONE PER WORKER. The loop below already does a per-row
    # `workers.find_one`; adding a second per-row round trip to the roster read
    # that thirteen men at shift start are waiting on is not a trade worth
    # making. The pairings for this project are fetched once and indexed.
    # Hoisted into _project_trades_for when four more endpoints needed the same
    # thing. Behaviour is unchanged and the tests for it are unchanged.
    _pair_by_wid = await _project_trades_for(
        project_id, [c.get("worker_id") for c in legacy],
    )

    seen_legacy_wids: set = set()
    for c in legacy:
        wid = c.get("worker_id")
        if wid in seen_legacy_wids:
            continue
        seen_legacy_wids.add(wid)
        if wid and str(wid) in seen_worker_ids:
            _collapsed += 1
            continue          # same id, already emitted by an earlier pass
        worker = await db.workers.find_one({"_id": to_query_id(wid)}) if wid else None
        # Same rule as the first pass: a token meaning "nothing was
        # read" must not be a dedupe key. See lib/ocr_text.py.
        name = norm_ocr_str(c.get("worker_name")
                            or (worker.get("name") if worker else "")) or ""
        company = _worker_company(c.get("worker_company"),
                                 worker.get("company") if worker else None)
        name_key = (_norm_key(name), _norm_key(company))
        if name_key in seen_name_keys or (
            not name_key[1] and name_key[0] in seen_names_only
        ):
            # Usually correct: the same man, already listed from the gate pass.
            # But it is ALSO what happens to a second, different worker who
            # shares a name with him at the same sub, and nothing on either row
            # can tell the two cases apart. Counted, so the caller can warn.
            _collapsed += 1
            continue   # already represented by a gate sign-in
        seen_name_keys.add(name_key)
        seen_names_only.add(name_key[0])
        if wid:
            seen_worker_ids.add(str(wid))
        result.append({
            "worker_id": wid,
            "worker_name": name or "Unknown",
            "company": company,
            # FROZEN FIRST, PAIRING ONLY TO FILL A GAP, and never the worker doc.
            #
            # A frozen trade is never overwritten. It is either what the worker
            # picked at the gate or what a CP put there through
            # POST /checkins/{id}/assign-trade, which writes the row AND the
            # pairing together — both are authoritative for that day. Letting
            # today's pairing win over it would mean a pairing edited next week
            # silently rewrites the roster on a log that has already been signed,
            # which is the retroactive mutation the frozen cert snapshot on this
            # same row exists to prevent.
            #
            # THE `workers` DOCUMENT FALLBACK IS GONE. `workers.trade` is the
            # cross-project bleed that register_and_checkin deliberately stopped
            # writing (server.py: "a worker-level copy is what bled across
            # jobs") — one slot for a man who holds different trades on
            # different jobs, answered by whichever project filled it first.
            # Reading it here kept that wrong answer alive on the one surface
            # that prints it onto a compliance record. The pairing replaces it
            # and is scoped to THIS project by construction.
            "trade": (
                _recorded_trade(c.get("worker_trade"))
                or (_pair_by_wid.get(str(wid), "") if wid else "")
            ),
            "check_in_time": c.get("check_in_time").isoformat() if isinstance(c.get("check_in_time"), datetime) else str(c.get("check_in_time", "")),
            "osha_number": worker.get("osha_number") if worker else "",
            "certifications": worker.get("certifications", []) if worker else [],
            # Legacy rows carry the inline base64 signature from the old
            # per-worker profile field. These aren't in R2 so the proxy
            # endpoint doesn't apply — frontend renders directly from
            # this string (data URL or base64).
            "worker_signature": worker.get("signature") if worker else None,
            "signin_id": None,
            "source": "legacy_checkin",
            # TOOLBOX ROSTER: optional gate confirmation (name + when), so the
            # toolbox-talk roster can show "confirmed at gate" per worker. Absent
            # /false simply means they did not tap — they are still on the roster
            # by virtue of checking in. The CP's signature remains the only legal
            # attestation.
            # ── DAILY SIGNATURE AFFIRMATION, carried to the sheet ───────
            # The signature itself already flows on this pass (worker_signature
            # above, from the worker doc). What was missing is whether he
            # AFFIRMED it today — without that the sheet can only print a
            # stamp, which is what the affirmation exists to stop.
            "signature_affirmed": bool(c.get("signature_affirmed")),
            "signature_affirmed_at": (
                c.get("signature_affirmed_at").isoformat()
                if isinstance(c.get("signature_affirmed_at"), datetime) else None
            ),
            "signature_affirmed_lang": c.get("signature_affirmed_lang"),
            "toolbox_talk_confirmed": bool(c.get("toolbox_talk_confirmed")),
            "toolbox_talk_confirmed_at": (
                c.get("toolbox_talk_confirmed_at").isoformat()
                if isinstance(c.get("toolbox_talk_confirmed_at"), datetime) else None
            ),
            # ── Flag fields (FIX 1) ──────────────────────────────────────────
            # ADMITTED-WITH-WARNINGS state, read straight off the checkins row
            # that already holds it. Nothing new is persisted anywhere: the
            # pre-shift roster needs a reason to display AND an id to POST
            # against, and both already exist here.
            #
            #   checkin_id             → POST /checkins/{checkin_id}/review
            #                            (decision "approved" | "sent_home")
            #                            and POST /checkins/{checkin_id}/assign-trade
            #   sst_status             → frozen at check-in (server.py ~:9826)
            #   cert_warnings          → EXPIRED_SST / SST_UNKNOWN entries
            #   needs_trade_assignment → cleared by assign-trade
            #   review_decision        → null until a CP decides; re-review
            #                            overwrites it, so it is never final
            "checkin_id": str(c.get("_id")) if c.get("_id") is not None else None,
            "sst_status": c.get("sst_status"),
            "needs_trade_assignment": bool(c.get("needs_trade_assignment")),
            "review_decision": c.get("review_decision"),
            "cert_warnings": c.get("cert_warnings") or [],
        })

    # ── PASS 3 (Task 9): workers TURNED AWAY for missing OSHA today ──────
    # A gate block writes a CERT_BLOCK compliance_alert but NO checkins row
    # (register_and_checkin returns before the insert), so without this they are
    # invisible on the OSHA log — the very log meant to prove who lacked OSHA.
    # Surface them BADGED (blocked=true / cert_cleared=false) and read-only.
    # Sourced from compliance_alerts, NOT checkins, so these rows can never count
    # toward any "checked_in" headcount — they don't exist in the checkins
    # collection at all. Deduped against Pass 1/2 by (name, company): a worker who
    # was blocked then cleared shows only their cleared row.
    try:
        blocked_alerts = await db.compliance_alerts.find({
            "alert_type": "CERT_BLOCK",
            "project_id": project_id,
            "created_at": {"$gte": day_start, "$lt": day_end},
        }).to_list(_BLOCKED_LIMIT)
        if len(blocked_alerts) >= _BLOCKED_LIMIT:
            _truncated.append("blocked")
    except Exception:
        blocked_alerts = []
        _degraded.append("blocked")
    seen_blocked_wids: set = set()
    for a in blocked_alerts:
        wid = a.get("worker_id")
        if wid and wid in seen_blocked_wids:
            continue
        if wid:
            seen_blocked_wids.add(wid)
        if wid and str(wid) in seen_worker_ids:
            # THE PRODUCTION DUPLICATE. A CERT_BLOCK alert usually carries no
            # worker_company, so the string key below could never match the row
            # pass 2 had already emitted for the same man.
            _collapsed += 1
            continue
        # Same rule as the first pass: a token meaning "nothing was
        # read" must not be a dedupe key. See lib/ocr_text.py.
        name = norm_ocr_str(a.get("worker_name")) or ""
        company = _worker_company(a.get("worker_company"))
        name_key = (_norm_key(name), _norm_key(company))
        if name_key in seen_name_keys:
            # Same ambiguity as pass 2: normally a worker who was blocked then
            # cleared, but indistinguishable from a same-named second man.
            _collapsed += 1
            continue  # already cleared/represented today — never double-list
        seen_name_keys.add(name_key)
        seen_names_only.add(name_key[0])
        if wid:
            seen_worker_ids.add(str(wid))
        result.append({
            "worker_id": wid,
            "worker_name": name or "Unknown",
            "company": company,
            "trade": "",
            "check_in_time": a.get("created_at").isoformat() if isinstance(a.get("created_at"), datetime) else str(a.get("created_at", "")),
            "osha_number": "",
            "certifications": [],
            "worker_signature": None,
            "signin_id": None,
            "source": "cert_block",
            "blocked": True,
            "cert_cleared": False,
            "blocks": [b.get("type") for b in (a.get("blocks") or []) if isinstance(b, dict)],
            # ── Flag fields (FIX 1) ──────────────────────────────────────────
            # These rows come from compliance_alerts, NOT checkins — a blocked
            # worker never reaches the checkins insert (register_and_checkin
            # returns at server.py:9796, before it). There is no row to review
            # or assign a trade on, so checkin_id is null and the snapshot
            # fields are null/false/[]. This is the BLOCKED population, which is
            # out of scope for the admitted-with-warnings actions: the null
            # checkin_id is what makes the UI offer none.
            "checkin_id": None,
            "sst_status": None,
            "needs_trade_assignment": False,
            "review_decision": None,
            "cert_warnings": [],
        })

    if not envelope:
        # The shape three screens already parse. Unchanged, deliberately.
        return result
    return {
        "workers": result,
        # ONE boolean the caller can gate a warning on, so a new degradation
        # mode added here starts warning without the client changing.
        "partial": bool(_degraded or _truncated or _collapsed),
        "degraded_passes": _degraded,
        "truncated_passes": _truncated,
        "collapsed": _collapsed,
    }


@api_router.get("/projects/{project_id}/daily-headcount")
async def get_project_daily_headcount(
    project_id: str,
    date: Optional[str] = None,
    current_user=Depends(get_current_user),
):
    """Per-sub headcount for a project on a given calendar date.

    Used by Daily Jobsite Log — a per-company headcount report, NOT a
    per-worker signature roster. The response is flat:

        [{"sub_name": "...", "trade": "...", "worker_count_today": N,
          "subcontractor_id": "srv_..." | None}, ...]

    `subcontractor_id` is the project roster row's server-minted id
    (project.trade_assignments[].id, see _merge_trade_assignments). It is
    what lets the Daily Jobsite Log key an activity row on the
    SUBCONTRACTOR instead of on its position in the array. It is None
    whenever the (sub, trade) pair has no roster row — an "UNASSIGNED"
    check-in, or a sub the admin has not entered yet. None is the honest
    answer there and callers must treat it as "no roster identity"; a
    fabricated id would silently merge two unrelated subs.

    Workers are counted, not listed. No signatures. The three logbooks
    that DO need per-worker signature autofill (preshift_signin,
    osha_log, toolbox_talk) continue to hit /checkins-today, which
    returns the roster + signin_id for signature proxy.
    """
    from zoneinfo import ZoneInfo
    eastern = ZoneInfo("America/New_York")
    now_eastern = datetime.now(eastern)
    target_date = date or now_eastern.strftime("%Y-%m-%d")
    try:
        day_eastern = datetime.strptime(target_date, "%Y-%m-%d").replace(tzinfo=eastern)
        day_start = day_eastern.astimezone(timezone.utc)
        day_end = (day_eastern + timedelta(hours=24)).astimezone(timezone.utc)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid date format")

    # Project access check — same pattern as other project-scoped reads.
    project = await db.projects.find_one({"_id": to_query_id(project_id), "is_deleted": {"$ne": True}})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")

    # Aggregate in two passes — new gate sign_ins + legacy checkins —
    # keyed by (sub, trade). Dedup workers across passes by normalized
    # (name, company) so a worker who appears in both systems during
    # transition isn't counted twice.
    buckets: Dict[tuple, Dict[str, Any]] = {}   # (sub_lower, trade_lower) -> row
    seen_workers: set = set()                   # (name_lower, company_lower)

    # ── Pass 1: new gate sign_ins ──────────────────────────────────────
    sign_ins = await db.sign_ins.find({
        "project_id": project_id,
        "timestamp": {"$gte": day_start, "$lt": day_end},
    }).to_list(2000)
    eids: List[str] = []
    seen_eids: set = set()
    for si in sign_ins:
        eid = si.get("worker_enrollment_id")
        if eid and eid not in seen_eids:
            seen_eids.add(eid)
            eids.append(eid)

    if eids:
        oids = []
        for eid in eids:
            try:
                oids.append(ObjectId(eid))
            except Exception:
                pass
        async for e in db.worker_enrollments.find({"_id": {"$in": oids}}):
            sub = _worker_company(e.get("sub_name"))
            trade = (e.get("trade") or "").strip()
            # Same rule as the first pass: a token meaning "nothing was
            # read" must not be a dedupe key. See lib/ocr_text.py.
            name = norm_ocr_str(e.get("worker_name")) or ""
            worker_key = (name.lower(), sub.lower())
            if worker_key in seen_workers:
                continue
            seen_workers.add(worker_key)
            key = (sub.lower(), trade.lower())
            row = buckets.get(key)
            if row is None:
                row = {"sub_name": sub, "trade": trade, "worker_count_today": 0}
                buckets[key] = row
            row["worker_count_today"] += 1

    # ── Pass 2: legacy checkins (pre-gate-migration workers) ───────────
    try:
        legacy = await db.checkins.find({
            "project_id": project_id,
            "check_in_time": {"$gte": day_start, "$lt": day_end},
            "is_deleted": {"$ne": True},
        }).to_list(2000)
    except Exception:
        legacy = []

    for c in legacy:
        wid = c.get("worker_id")
        worker = await db.workers.find_one({"_id": to_query_id(wid)}) if wid else None
        # Same rule as the first pass: a token meaning "nothing was
        # read" must not be a dedupe key. See lib/ocr_text.py.
        name = norm_ocr_str(c.get("worker_name")
                            or (worker.get("name") if worker else "")) or ""
        company = _worker_company(c.get("worker_company"),
                                 worker.get("company") if worker else None)
        trade = (c.get("worker_trade") or (worker.get("trade") if worker else "") or "").strip()
        worker_key = (name.lower(), company.lower())
        if worker_key in seen_workers or not name:
            continue
        seen_workers.add(worker_key)
        key = (company.lower(), trade.lower())
        row = buckets.get(key)
        if row is None:
            row = {"sub_name": company, "trade": trade, "worker_count_today": 0}
            buckets[key] = row
        row["worker_count_today"] += 1

    # ── Roster identity for each (sub, trade) pair ─────────────────────
    # Resolved from the project doc already fetched above (no extra query),
    # on the SAME normalization the check-in strict-roster match uses
    # (_roster_key over company + trade), so a case-only or whitespace edit
    # still resolves to the same row. An active row always wins; a
    # soft-deleted row still supplies the id it was minted with rather than
    # losing it, because the day's work really was done by that sub.
    roster_ids: Dict[tuple, str] = {}
    for _assignment in (project.get("trade_assignments") or []):
        if not isinstance(_assignment, dict):
            continue
        _rid = str(_assignment.get("id") or "").strip()
        if not _rid:
            continue
        _rkey = (_roster_key(_assignment.get("company")), _roster_key(_assignment.get("trade")))
        if _assignment_is_inactive(_assignment):
            roster_ids.setdefault(_rkey, _rid)
        else:
            roster_ids[_rkey] = _rid

    # Stable order: by sub_name, then trade
    rows = sorted(buckets.values(), key=lambda r: ((r["sub_name"] or "").lower(), (r["trade"] or "").lower()))
    for row in rows:
        # Absent from the roster -> None, never a minted id. A headcount read
        # must not create roster identity; only the admin's roster does.
        row["subcontractor_id"] = roster_ids.get(
            (_roster_key(row.get("sub_name")), _roster_key(row.get("trade")))
        )
    return rows


@api_router.get("/signatures/{signin_id}")
async def get_signature_image(signin_id: str, current_user=Depends(get_current_user)):
    """Authenticated proxy for a worker's daily signature image.

    Permanent mechanism (replaces presigned R2 URLs, which were
    unreliable for logbook forms left open through a full shift).

    Auth: session-authenticated user must have project-level read
          access to the project containing the sign-in.
    Source: the R2 key stored on the sign_in's matching daily_signature
            row. No app-layer cache — R2 reads are cheap and browser
            caching via Cache-Control: private, max-age=3600 covers
            repeat loads within a session.

    Error shapes — frontend distinguishes these to render four
    distinct states (missing signature, forbidden, storage down,
    unknown id):
      404 {"error":"signature_not_found"}   — sign-in has no stored signature
      403 {"error":"forbidden"}             — cross-project access attempt
      500 {"error":"storage_unavailable"}   — R2 read failure
      404 {"error":"signature_not_found"}   — sign-in id does not exist
    """
    try:
        oid = ObjectId(signin_id)
    except Exception:
        return JSONResponse(status_code=404, content={"error": "signature_not_found"})

    sign_in = await db.sign_ins.find_one({"_id": oid})
    if not sign_in:
        return JSONResponse(status_code=404, content={"error": "signature_not_found"})

    # Access check — resolve the project, compare company to the user's.
    project = await db.projects.find_one({
        "_id": to_query_id(sign_in.get("project_id")),
        "is_deleted": {"$ne": True},
    })
    if not project:
        return JSONResponse(status_code=404, content={"error": "signature_not_found"})
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    #
    # project_access_ok, NOT _assert_project_access, and that is deliberate on
    # two counts:
    #   * the RESPONSE SHAPE is preserved. This route returns
    #     JSONResponse({"error": ...}) rather than raising, and its documented
    #     contract lists those bodies. _assert_project_access raises
    #     {"detail": ...}. SignatureImage.jsx branches only on
    #     err.response.status, so either would have worked -- but changing a
    #     documented shape for no gain is not a fix.
    #   * the LOOKUP stays `is_deleted` only. ACTIVE_PROJECT_FILTER also
    #     excludes marked_for_deletion, which would turn a signature on a
    #     just-marked project into a 404 for the CP who needs it.
    if not project_access_ok(project, str(sign_in.get("project_id") or ""), current_user):
        return JSONResponse(status_code=403, content={"error": "forbidden"})

    # Resolve the R2 key via daily_signatures (spec: "No schema changes"
    # — the key lives on daily_signatures, keyed by
    # project_id + worker_enrollment_id + calendar_date, derivable from
    # the sign_in's own fields).
    from zoneinfo import ZoneInfo
    ts = sign_in.get("timestamp") or datetime.now(timezone.utc)
    if isinstance(ts, datetime) and ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)
    date_ymd = (
        ts.astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        if isinstance(ts, datetime) else ""
    )
    sig_row = await db.daily_signatures.find_one({
        "project_id": sign_in.get("project_id"),
        "worker_enrollment_id": sign_in.get("worker_enrollment_id"),
        "calendar_date": date_ymd,
    })
    r2_key = (sig_row or {}).get("signature_r2_key")
    if not r2_key:
        return JSONResponse(status_code=404, content={"error": "signature_not_found"})

    # Separate card-audit bucket (object-locked, 7-year retention).
    # Not the general R2_BUCKET_NAME — don't fall through to that.
    import card_audit as _ca
    if not _r2_client or not _ca.CARD_AUDIT_BUCKET_NAME:
        return JSONResponse(status_code=500, content={"error": "storage_unavailable"})
    try:
        obj = await asyncio.to_thread(
            _r2_client.get_object,
            Bucket=_ca.CARD_AUDIT_BUCKET_NAME,
            Key=r2_key,
        )
        content_type = obj.get("ContentType") or "image/png"
        body = obj["Body"].read()
    except Exception as e:
        logger.error(f"signature proxy R2 read failed key={r2_key}: {e!r}")
        return JSONResponse(status_code=500, content={"error": "storage_unavailable"})

    return Response(
        content=body,
        media_type=content_type,
        headers={"Cache-Control": "private, max-age=3600"},
    )


# ==================== ROOT ENDPOINT ====================

@api_router.get("/")
async def root():
    return {"message": "Levelog API v2.0.0 - Sync Enabled", "status": "running"}

@api_router.get("/health")
async def health_check():
    """Up, and — separately — INDEX-COMPLETE.

    `status` deliberately stays "healthy" while an index is missing. This is
    the probe the platform restarts on, and a unique index the data refuses is
    not fixed by cycling the process; flipping it would turn a data finding
    into a restart loop that takes the API down for exactly the reason
    _ensure_index_resilient refuses to raise.

    `indexes.failed_unique_builds` NAMES them instead. A deploy is provably
    index-complete when that list is empty — which is the question nobody could
    ask before, because a rejected build logged one warning and startup went
    green over it. Each name here is a declared uniqueness rule that is NOT in
    force, and any `except DuplicateKeyError` written against it is dead code.
    """
    _failed = sorted(FAILED_UNIQUE_INDEX_BUILDS)
    _refused = sorted(CORS_PREFLIGHT_REJECTIONS)
    _ours = [h for h in _refused
             if CORS_PREFLIGHT_REJECTIONS[h].get("from_our_origins")]
    return {
        "status": "healthy",
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "indexes": {
            "complete": not _failed,
            "failed_unique_builds": _failed,
            "detail": {n: FAILED_UNIQUE_INDEX_BUILDS[n] for n in _failed},
        },
        # WHAT THE BROWSER WAS REFUSED PERMISSION TO SEND. `clean` false with a
        # name under `refused_from_our_origins` means the web build is being
        # blocked before it sends anything, on every endpoint — the state that
        # ran for seven days behind a 200 from /api/version. Refusals from
        # origins we do not own are counted but never listed there: those are
        # scanners, not an outage.
        "cors": {
            "clean": not _ours,
            "allow_headers": list(CORS_ALLOW_HEADERS),
            "refused_from_our_origins": _ours,
            "refused_any_origin": _refused,
            "detail": {h: CORS_PREFLIGHT_REJECTIONS[h] for h in _refused},
        },
    }

# WHEN THIS PROCESS CAME INTO EXISTENCE. Read once, at import, so every request
# reports the same instant.
#
# NOT THE COMMIT'S DATE, and the difference is stated rather than papered over.
# Railway injects RAILWAY_GIT_COMMIT_SHA / _BRANCH but NO commit timestamp, and
# asking git at runtime assumes a .git the image may not carry. What this does
# answer is the question the build card actually asks — WHICH SIDE IS MORE
# RECENT — because a deploy is the moment the backend's code started running,
# the same kind of fact as `Updates.createdAt` on the bundle side.
#
# A RESTART RESETS IT WITHOUT A NEW COMMIT. That is why the card's wording (see
# app/settings.jsx) states the comparison as a fact and offers the benign cause
# without asserting it: "backend is ahead of your bundle" is true after a
# restart too, and a card that over-claimed would be the same defect it exists
# to fix.
BACKEND_STARTED_AT = datetime.now(timezone.utc).isoformat()


@api_router.get("/version")
async def version():
    """Report the exact commit this running backend was built from, so a
    deploy can be verified as "the active deploy IS my commit" — not merely
    "a deploy is green". Railway injects RAILWAY_GIT_COMMIT_SHA at build; the
    others are fallbacks for other hosts / local runs.

    IT ALSO REPORTS WHEN, and that is not decoration. The build card compared
    `jsCommit[:7] == backendCommit[:7]` and printed "MISMATCH — the app and the
    backend are on different commits" for every inequality. That single output
    covers three different states:

        the app is behind          a bundle that failed to publish
        the backend is behind      a deploy that has not landed
        neither is behind          a BACKEND-ONLY change, where no OTA is
                                   published because nothing under frontend/
                                   changed, and the phone is exactly right

    On 2026-09-04 the third case sent an acceptance test out that told the CP
    to wait for a version line that was never going to change. String equality
    has no notion of ancestry, so it cannot separate them — but two timestamps
    can say WHICH SIDE MOVED, which is the actionable half.
    """
    sha = (
        os.environ.get("RAILWAY_GIT_COMMIT_SHA")
        or os.environ.get("GIT_COMMIT_SHA")
        or os.environ.get("SOURCE_COMMIT")
        or os.environ.get("COMMIT_SHA")
        or "unknown"
    )
    return {
        "commit": sha,
        "short": sha[:7] if sha != "unknown" else "unknown",
        "branch": os.environ.get("RAILWAY_GIT_BRANCH") or None,
        # MISNAMED SINCE IT WAS WRITTEN: this is a deployment UUID, not a
        # time, and anything reading `built_at` as a timestamp got a string
        # that parses as nothing. Kept under the old key because removing it
        # is a response-shape change nothing asked for, and named correctly
        # beside it.
        "built_at": os.environ.get("RAILWAY_DEPLOYMENT_ID") or None,
        "deployment_id": os.environ.get("RAILWAY_DEPLOYMENT_ID") or None,
        # The one the build card compares against Updates.createdAt. ISO-8601,
        # UTC, process start — see BACKEND_STARTED_AT above for what it is and
        # what it is not.
        "deployed_at": BACKEND_STARTED_AT,
        # The floor a client compares its own NATIVE version against. Null when
        # this deploy could not read it, and the client treats null as "do not
        # judge" rather than as "behind" — an install we cannot assess must not
        # be accused. Unauthenticated like the rest of this endpoint: it is a
        # number about the product, not about anyone using it.
        "client_minimum_supported": CLIENT_MINIMUM_SUPPORTED,
    }

@app.get("/checkin/{tag_id}")
async def serve_checkin_page(tag_id: str):
    from fastapi.responses import HTMLResponse
    html_path = Path(__file__).parent / "checkin.html"
    if not html_path.exists():
        raise HTTPException(status_code=404, detail="Check-in page not found")
    return HTMLResponse(content=html_path.read_text(), status_code=200)

# ⚠️  THIS ROUTE SHADOWS card_audit.gate_router AND THAT IS LOAD-BEARING.
#
# `card_audit.py:1173` declares `GET /checkin/{project_id}/{gate_id}` — the
# same method and the same two-segment shape. Both are mounted on `app`;
# THIS ONE IS REGISTERED FIRST (module-level decorators run at import, the
# include_router call is near the bottom of this file), so FastAPI matches
# it and card_audit's gate page never serves. `GET /checkin/success/{id}`
# is shadowed by the same rule — two segments after /checkin.
#
# WHAT DEPENDS ON THAT, PHYSICALLY. `nfcHelper.buildCheckinUrl` writes
# `{baseUrl}/checkin/{projectId}/{tagId}` onto every NFC tag on every fence.
# Those tags are already deployed and cannot be rewritten remotely. Which
# side of this collision wins decides what a worker sees when he taps one.
#
# THE TWO SIDES ARE DIFFERENT GENERATIONS, not duplicates. This handler
# serves checkin.html, which writes the LEGACY `checkins` collection.
# card_audit's gate writes `sign_ins` + `worker_enrollments`, which
# get_project_checkins_today calls the NEW system and still reads —
# see its docstring on the rollout.
#
# SO DO NOT "TIDY" EITHER ROUTE. Removing this one hands every deployed tag
# to a half-migrated gate. Removing card_audit's deletes the only writer of
# `worker_enrollments` while a merge in this file goes on reading it.
# Changing either path re-resolves a collision that is currently holding
# hardware on a fence in a known state.
#
# Mirrored at card_audit.py:1173. If you change one, change both.
@app.get("/checkin/{project_id}/{tag_id}")
async def serve_checkin_page_full(project_id: str, tag_id: str):
    from fastapi.responses import HTMLResponse
    html_path = Path(__file__).parent / "checkin.html"
    return HTMLResponse(content=html_path.read_text(), status_code=200)

# ==================== COMBINED REPORT GENERATOR ====================
def _is_affirmed_signature(sig) -> bool:
    """AFFIRMED FOR *THIS* DOCUMENT — the one predicate, so nothing can ask a
    weaker question of the same object and get a different answer.

    A signature is affirmed only when the CP took an explicit affirmative action
    on THIS record and `affirmed is True` records it. A base64 string, a legacy
    credential, an inherited profile signature and — the shape production
    actually held — an EMPTY DICT are all not affirmed. `not {}` is False, which
    is how `cp_signature: {}` satisfied every presence gate in the app while
    every document it signed printed UNAFFIRMED.

    Mirrors frontend/src/utils/signatureAffirmed.js. If one changes the other
    changes with it, or the app gates on one rule and prints another.
    """
    return isinstance(sig, dict) and sig.get("affirmed") is True


def _has_signature_ink(sig) -> bool:
    """IS THERE ACTUALLY A MARK ON THIS SIGNATURE?

    The second predicate, and the companion to the one above. Three places asked
    "is there a signature OBJECT" when they meant "is there ink", and an object
    is not ink -- `{}` is truthy in JS, is not null in Mongo, and `not {}` is
    True in Python only by accident of a different rule.

    THE TWO SHAPES THAT ARE REAL INK, and there are only two:

        paths: [...]   SignaturePad's vector output. canConfirm requires
                       paths.length > 0, so a confirmed signature always carries
                       at least one stroke -- an EMPTY list is therefore not "a
                       signature with no strokes", it is no signature.
        data: "..."    a base64 raster. The legacy / pre-rendered path.

    A bare string IS a signature: render_signature_html treats `isinstance(sig,
    str)` as a base64 image. An empty one is not.

    NOT A REPLACEMENT FOR _is_affirmed_signature. Ink says a mark exists;
    affirmed says the signer adopted it for THIS document. Both are required and
    they fail for different reasons -- an inkless `{"affirmed": True}` passes the
    second and fails this one, and that is precisely the shape a pad offering
    AFFIRM over an empty canvas used to mint.

    MIRRORS frontend/src/utils/signatureAffirmed.js:hasSignatureInk, field for
    field and in the same order. If one changes the other changes with it, or
    the app gates on one rule and prints another.
    """
    if not sig:
        return False
    if isinstance(sig, str):
        return len(sig) > 0
    if not isinstance(sig, dict):
        return False
    paths = sig.get("paths")
    if isinstance(paths, list) and len(paths) > 0:
        return True
    data = sig.get("data")
    return isinstance(data, str) and len(data) > 0


# THE SAME PREDICATE IN QUERY LANGUAGE, so a selector never hauls signature
# blobs across the wire to ask a question Mongo can answer. `paths.0` exists
# iff the array is non-empty, which is the list-length half; the two string
# clauses are the `data` half and the bare-string shape.
#
# Kept adjacent to _has_signature_ink because it is the same rule written twice
# and the only defence against them drifting is that they are read together.
# test_signature_ink_predicate.py asserts they agree on every shape.
_SIGNATURE_HAS_INK_CLAUSES = [
    {"cp_signature.paths.0": {"$exists": True}},
    {"cp_signature.data": {"$type": "string", "$ne": ""}},
    {"cp_signature": {"$type": "string", "$ne": ""}},
]


def merge_attestation_gaps(
    stale_unsigned_docs, stale_unsigned_refs, inkless_filed_docs, unaffirmed_docs,
):
    """One row per (log_type, date), each naming its own state.

    LIFTED OUT OF THE ENDPOINT SO IT CAN BE TESTED AT ALL. It was 49 lines
    inline in a 400-line handler that needs a live Mongo to reach, so the only
    test of the merge rule was a REIMPLEMENTATION of it in the test file -- a
    copy that agreed with itself while the original was wrong for weeks. Same
    shape as a test double thinner than the real module, already recorded here.
    Nothing about the merge changes in the move except the amendment guard.

    Returns the list the endpoint serves as `attestation_gaps`.
    """
    # AND A SIGNED AMENDMENT IS NOT AN UNSIGNED ONE. `stale_unsigned_docs` is
    # the RAW query result and its selector carries no signature clause at all --
    # the affirmation test lives twenty lines below, in `stale_unsigned_refs`,
    # and this loop did not use it. So an amendment the CP had signed AND
    # affirmed kept raising `amendment_unsigned`, and because the override at
    # the bottom is applied LAST it beat the two states that ARE signature-aware.
    #
    # The comment above states the assumption that made it wrong: "an amendment
    # child is created unsigned ... and can never be `unaffirmed`". True at
    # creation. False the moment he signs, which is the only interesting moment.
    #
    # THE COST WAS NOT COSMETIC. The banner cleared itself overnight, when the
    # freeze sweep locked the row out of the selector -- so for up to 27 hours
    # after every correction the app told the CP his signed work still needed a
    # signature, and he signed it again. That is where the draft pile came from.
    #
    # META IS STILL COLLECTED FOR EVERY AMENDMENT, only the GAP is withheld.
    # A parent and its child share (log_type, date), so an unsigned parent whose
    # child is signed must still be able to say "this day was amended" on the
    # row its own deficiency raises.
    _amend_meta = {}
    _amend_unsigned = set()
    for _doc in stale_unsigned_docs:
        if _doc.get("is_amendment") is not True:
            continue
        _lt, _dt = _doc.get("log_type"), _doc.get("date")
        if not (_lt and _dt):
            continue
        _amend_meta[(_lt, _dt)] = amendment_state(_doc)
        if not _is_affirmed_signature(_doc.get("cp_signature")):
            _amend_unsigned.add((_lt, _dt))

    _gaps = {}
    for _ref in stale_unsigned_refs:
        _gaps[(_ref["log_type"], _ref["date"])] = "unsigned"
    # The third selector, merged as UNSIGNED — the banner's existing sentence
    # ("never signed — still open and still yours to finish") is already the
    # right one for it, so this needs no new copy and no fourth state.
    for _doc in inkless_filed_docs:
        _lt, _dt = _doc.get("log_type"), _doc.get("date")
        if _lt and _dt:
            _gaps[(_lt, _dt)] = "unsigned"
    for _doc in unaffirmed_docs:
        _lt, _dt = _doc.get("log_type"), _doc.get("date")
        if not _lt or not _dt:
            continue
        # A present-but-unaffirmed signature is the more specific state, so it
        # wins over the generic "unsigned" the stale pass assigned.
        _gaps[(_lt, _dt)] = "unaffirmed"
    # MORE SPECIFIC STILL, and applied last for that reason. An amendment child
    # is created unsigned (cp_signature None), so it carries no ink and can
    # never be `unaffirmed` -- the two never collide in practice, and the
    # ordering says which would win if they ever did.
    for _key in _amend_unsigned:
        _gaps[_key] = "amendment_unsigned"
    def _gap_row(k, v):
        row = {"log_type": k[0], "date": k[1], "state": v}
        meta = _amend_meta.get(k)
        if meta:
            # Off the RECORD. A bundle rendering this in December must read the
            # same sentence it would have read in September.
            row["amendment"] = {
                "reason": meta.get("reason"),
                "by": meta.get("by"),
                "at": _amendment_day(meta.get("at")) or None,
                "has_reason": meta.get("state") == AMENDMENT_PRESENT,
            }
        return row

    return sorted(
        (_gap_row(k, v) for k, v in _gaps.items()),
        key=lambda g: g["date"], reverse=True,
    )

def submit_freezes_record(log_type, is_amendment, effective_signature) -> bool:
    """Does `status: submitted` seal this record, or does something else close it?

    TWO REASONS, AND THEY ARE NOT THE SAME REASON.

    IMMEDIATE / PRE-SHIFT -- the timing class says the signature is the freeze.
    A no-op until counsel classifies a log as immediate_preshift; kept here so
    the two freeze-on-submit rules live in one predicate rather than two
    branches that drift.

    AN AMENDMENT -- and NOT by its timing class, which is the point. An
    END_OF_DAY log stays open because the day is still accumulating, and
    sweep_stale_end_of_day_logs closes it that night. An amendment to
    2026-08-14 filed on 2026-09-04 HAS NO DAY LEFT TO ACCUMULATE: it is
    complete the instant it is signed. Leaving it to a sweep whose selector is
    `date < today` makes a record three weeks old wait on a rule about
    yesterday, and until it fires the row keeps matching stale_unsigned_docs
    every night. The child inherits nothing from the parent and should not --
    the parent was an end-of-day narrative, the child is a correction to a
    closed one. This is the rule a `visit` log already uses.

    AFFIRMED, NEVER MERELY PRESENT. The same bar sweep_stale_end_of_day_logs
    sets, for its reason: an unfrozen record can still be frozen later and a
    wrongly sealed one cannot be opened. An inherited credential, a legacy
    signature and the `{}` production actually held are all not affirmed.

    NOTE THE ASYMMETRY. is_immediate_preshift does not consult the signature
    because SUBMIT_MISSING_CP_SIGNATURE has already refused an unsigned submit
    upstream; the amendment arm asks anyway, because "signed" and "affirmed"
    are different questions and only the second one may seal a record.
    """
    if is_immediate_preshift(log_type):
        return True
    if is_amendment is True and _is_affirmed_signature(effective_signature):
        return True
    return False



def _signature_affirmation_html(sig):
    """The per-document affirmation banner. A signature is AFFIRMED only when the
    CP took an explicit affirmative action on THIS document (sig.affirmed is
    True). An inherited/reused credential or a legacy signature renders
    UNAFFIRMED — an honest deficiency, never a VERIFIED stamp the signer never
    made for this record. Mirrors SignaturePad's attention/verified treatment."""
    affirmed = _is_affirmed_signature(sig)
    if not affirmed:
        return (
            '<div style="font-size:12px;font-weight:700;color:#d97706;margin-top:4px;">'
            '⚠ UNAFFIRMED — inherited signature, not affirmed for this document</div>'
        )

    def _fmt(raw):
        # NEW YORK, like every other time on this document. It printed the
        # stored digits with " UTC" appended -- honest, and still the only
        # clock on a §3301 record a New York inspector had to convert in his
        # head. eastern_datetime carries the zone, so nothing is lost by it.
        # AN UNANCHORED VALUE STILL PRINTS: a legacy signature carrying a naive
        # timestamp says what it says rather than disappearing from the banner.
        if not raw:
            return ""
        try:
            return eastern_datetime(raw)
        except Exception:
            return str(raw)[:19].replace("T", " ")

    claimed = _fmt(sig.get("affirmedAt") or sig.get("timestamp"))
    received = _fmt(sig.get("affirmed_received_at"))
    flag = sig.get("affirmation_flag")
    # Server-received (a time the server can vouch for) is always shown.
    recv_line = (
        f'<div style="font-size:11px;color:#475569;">server-received {received}</div>'
        if received else ""
    )
    if flag:
        # The client-claimed time failed validation — say so, do NOT print it
        # as fact.
        return (
            '<div style="font-size:12px;font-weight:700;color:#d97706;margin-top:4px;">'
            '✓ AFFIRMED — claimed time NOT VERIFIED (' + flag + '): '
            + (claimed or 'no time') + '</div>' + recv_line
        )
    claim_line = (
        f'<div style="font-size:11px;color:#475569;">claimed {claimed}</div>'
        if claimed else ""
    )
    return (
        '<div style="font-size:12px;font-weight:700;color:#16a34a;margin-top:4px;">'
        '✓ AFFIRMED for this document</div>' + claim_line + recv_line
    )


def _attendee_source_label(a) -> str:
    """WHOSE CLAIM PUT THIS MAN ON THE SHEET.

    Three provenances, recorded by the app as `added_from`:

      'gate'         he checked in TODAY - the gate says he was on site
      'weekly_gap'   he worked this WEEK; the CP is asserting he attended
      'manual'       the CP typed him in; the app knows nothing about him

    A toolbox talk is a WEEKLY obligation built from a DAILY roster, so the CP
    can now add men who worked earlier in the week. That is a genuinely weaker
    claim than a gate check-in, and a signed attendance record that renders the
    two identically is the stronger one lending its authority to the weaker -
    which is the whole reason the field is stored.

    AN OLD RECORD HAS NO `added_from`. Every attendee filed before the field
    existed came from the gate or from the CP's own typing with no way to tell
    which, and inventing a label for those would be the same false confidence
    this column exists to remove. They read as an em-dash: we do not know, and
    the record says so.
    """
    raw = str((a or {}).get("added_from") or "").strip().lower()
    return {
        "gate": "Gate",
        "weekly_gap": "CP &mdash; this week",
        "manual": "CP &mdash; added",
    }.get(raw, "&mdash;")


def _roster_clock(v) -> str:
    """A roster row's check-in time, IN NEW YORK. The toolbox roster carries
    the §3301.12.3 required fields (name, title, company, date/time); this
    renders the time for the PDF.

    IT USED TO PRINT THE UTC DIGITS. The stored value is an instant -- the gate
    writes `check_in_time` straight onto the attendee (toolboxTalkModel.js
    buildAttendees) -- and this parsed it correctly and then formatted it
    without converting, so `10:47:05Z` printed as "10:47" on a signed
    attendance record for a man who was at the gate at 6:47 AM EDT.
    `eastern_clock` owns that conversion now and no other renderer does it.

    AN UNANCHORED VALUE IS PRINTED AS ITSELF. `weeklyGapAttendee` writes
    `time: ''` and older rosters hold typed wall-clock strings like "07:15".
    Those carry no zone, so there is nothing to convert -- eastern_clock
    refuses them rather than guessing, and they print exactly as they always
    did. Never a parse error onto a legal record.
    """
    if not v:
        return "&mdash;"
    try:
        return eastern_clock(v)
    except Exception:
        return str(v)[:16]

def _capitalize_first(text):
    """RULE 1 (short entry): capitalize the first letter, preserve everything
    after it EXACTLY. Display-time only — never mutates stored data. Mirrors the
    frontend capitalizeFirst() in src/utils/textFormat.js."""
    s = "" if text is None else str(text)
    for i, ch in enumerate(s):
        if not ch.isspace():
            return s[:i] + ch.upper() + s[i + 1:]
    return s


def _sentence_case(text):
    """RULE 2 (prose): capitalize the first letter of the string and the first
    letter after every terminal punctuation (. ! ?); preserve everything else
    exactly. Display-time only. Mirrors the frontend sentenceCase()."""
    s = "" if text is None else str(text)
    out = []
    cap_next = True
    for ch in s:
        if cap_next and ch.isalpha():
            out.append(ch.upper())
            cap_next = False
        else:
            out.append(ch)
            if ch in ".!?":
                cap_next = True
    return "".join(out)
def _headcount_cell(act, blank=""):
    """The crew row's headcount, SAYING WHERE THE NUMBER CAME FROM.

    A daily 3301.2 log already carries two headcounts from two provenances: the
    gate table, computed here from the check-ins (_headcount_by_sub), and the
    crew rows, which print activities[].num_workers. Until now the crew row
    never said which kind it was, so a number a person typed and a number a
    turnstile counted printed identically on a signed record.

    The CP can now correct a crew's headcount, so the distinction stopped being
    cosmetic. `4 (CP) - gate recorded 6` is the whole point of retaining
    gate_num_workers: if his correction simply replaced the turnstile's number,
    nothing downstream -- an inspector, an audit, this renderer -- could tell
    that a person had changed a gate count, or what it had been.

    ABSENCE MEANS GATE. Drafts written before num_workers_source existed carry
    no marker and hold numbers that came from the roster; labelling those "(CP)"
    would put a false attribution on records that are already filed.
    """
    raw = act.get("num_workers", "")
    text = str(raw).strip() if raw is not None else ""
    if text == "":
        return blank
    if act.get("num_workers_source") != "cp":
        return text
    gate = act.get("gate_num_workers")
    gate_text = str(gate).strip() if gate is not None else ""
    if gate_text == "":
        # A hand-added crew: the CP's own assertion, with no gate count to
        # stand over. It is still his number and still says so.
        return f"{text} (CP)"
    return f"{text} (CP) - gate recorded {gate_text}"


AMENDMENT_PRESENT = "present"
AMENDMENT_NO_REASON = "no_reason_recorded"
AMENDMENT_NONE = "not_amended"


# ══ WITHDRAWN — THE EXIT AN UNSIGNED CORRECTION NEVER HAD ═══════════════════
#
# THE PRODUCTION STATE THIS ANSWERS. Seven unsigned `daily_jobsite` amendment
# drafts on one project, and on two of those days TWO drafts on ONE parent,
# sixty and twenty-six seconds apart: a superintendent tapped Amend, nothing on
# the screen changed, he tapped again. Every one of them warns on his
# compliance card, forever, because the only two exits were both wrong:
#
#   SIGN IT     files a correction he may not intend — and on a fork, files one
#               of two competing versions with nothing recording which he meant.
#   DELETE IT   destroys a document. (It also refused him outright until #371:
#               `delete_logbook` read `current_user["_id"]` on an object where
#               `serialize_id` had deleted that key, so no CP could delete his
#               own logbook. Even repaired, delete is the wrong answer here —
#               the amendment is evidence of what was attempted.)
#
# A STATE, NOT A DELETE. The document survives untouched — its data, its
# reason, its author, its parent link. What changes is what it CLAIMS to be: a
# withdrawn amendment is no longer an open correction, so nothing counts it,
# nothing offers it for editing, and no report can ever select it.
#
# ONE FIELD CARRIES THE STATE. `status` is the field every reader in this file
# and in the client already consults to decide what a logbook is, and a second
# boolean beside it would be a second writer of one fact — the failure mode
# this codebase has spent its last month closing. `withdrawn_at` /
# `withdrawn_by` / `withdrawn_by_name` are NOT that second writer: they are the
# ATTESTATION, and they answer a different question (who, and when).
WITHDRAWN_STATUS = "withdrawn"

# The Mongo clause, written once. Every selector that hunts for unfinished work
# keys on `is_locked: {$ne: True}` or `status: {$ne: "submitted"}`, and a
# withdrawn child satisfies BOTH — so without this it stays on the CP's card
# under a new name. `$ne` matches a missing field as well as a different value,
# so it is correct against every document written before this existed.
#
# SPREAD IT ONLY INTO A SELECTOR THAT HAS NO `status` KEY. It is a dict, and
# `{**q, **WITHDRAWN_EXCLUDED}` REPLACES an existing `status` clause instead of
# narrowing it — silently, and in the widening direction. The one selector
# where the two collide (`unsigned_orientations`) spells out a `$nin` instead
# and says so on the line.
WITHDRAWN_EXCLUDED = {"status": {"$ne": WITHDRAWN_STATUS}}

WITHDRAW_NOT_AN_AMENDMENT = "WITHDRAW_NOT_AN_AMENDMENT"
WITHDRAW_FILED_AMENDMENT = "WITHDRAW_FILED_AMENDMENT"
WITHDRAW_SIGNATURE_REQUIRED = "WITHDRAW_SIGNATURE_REQUIRED"

# THE SENTENCE ABOVE THE PAD, STORED WITH THE INK.
#
# `attach_attestation` exists in this file because a signature with no recorded
# sentence above it attests to nothing nameable — you can prove a man drew a
# mark and not what he was told it meant. A withdrawal is signed for under the
# same rule, so the sentence is stored on the document beside the ink rather
# than living only in the client that rendered it. The client renders THIS
# string; if the two ever diverge the record still says what the server
# believed the signer was shown.
WITHDRAWAL_ATTESTATION_STATEMENT = (
    "I am withdrawing this proposed correction. It was never filed, it is not "
    "part of the record, and the log it proposed to correct is unchanged."
)


def withdrawal_attestation(signature, *, by: str, by_name, at: datetime) -> dict:
    """The attested half of a withdrawal, in a shape that is NOT a signing act.

    ── WHY THIS IS NOT A signature_events ROW ─────────────────────────────────

    That collection's unique index is literally named
    `signature_events_one_row_per_signing_act`, and its `version` is a count of
    the signings OF ONE DOCUMENT'S CONTENT. A withdrawal row there would bump
    the amendment's signature version and assert a signing act performed on
    content nobody signed — the content is precisely what is being abandoned.
    That is the fabricated attestation `ensure_signature_ledger_row` refuses to
    mint, in its own words: "a row for a signature nobody made is a fabricated
    attestation." The signature here is real; what it attests to is the
    ABANDONMENT, and there is no collection whose readers mean that.

    ── SO IT LANDS ON THE DOCUMENT, SHAPED SO NO LEDGER READER CAN CLAIM IT ───

    Exactly two readers ask a LOGBOOK what its signature is, and both read one
    field, `cp_signature`: `ensure_signature_ledger_row` and
    `sweep_signature_ledger_gaps`. Neither is reachable from here:

      * the withdrawal never writes `cp_signature` and never clears the null
        that amend_logbook already put there, so the derivation returns None
        at its first line (no ink, no affirmation);
      * the nightly sweep selects `status: "submitted"`, and a withdrawn
        document's status is "withdrawn", so it is not in the cursor at all.

    The ink is therefore nested under ONE field with no top-level `*_signature`
    sibling, and carries `kind: "withdrawal"` so a future reader that goes
    looking has to actively decide to treat it as a content signing rather than
    stumble into it. `document_type`, `document_id`, `event_type`, `version`,
    `signer` and `content_hash` — every key a signature-ledger reader keys on —
    are deliberately absent.

    ── WHAT THE CLIENT IS TRUSTED FOR, WHICH IS THE INK AND NOTHING ELSE ──────

    `by`, `by_name` and `at` are server-stamped by the caller. A device with a
    wrong clock must not be able to date an attestation and a client must not
    be able to name someone else as its signer — the same rule the
    withdrawn_by / withdrawn_at trio already follows, and they are written in
    the same update as this.
    """
    return {
        # NEVER a content signing. Named, so it cannot be mistaken silently.
        "kind": "withdrawal",
        "statement": WITHDRAWAL_ATTESTATION_STATEMENT,
        "ink": signature,
        "by": by,
        "by_name": by_name,
        "at": at,
    }


# ══ ONE OPEN AMENDMENT PER PARENT, ENFORCED BY THE DATABASE ═════════════════
#
# `open_amendment_head` / AMENDMENT_ALREADY_OPEN keys correctly on the parent,
# but amend_logbook READS the children and then INSERTS with nothing between.
# Two genuinely simultaneous requests both read "no open child" and both
# insert. That is the fork production is carrying twice over — Aug 10 and Aug
# 14, two open children on one parent, sixty and twenty-six seconds apart.
#
# THE SAME SHAPE signature_events_one_row_per_signing_act ALREADY USES: a
# PARTIAL UNIQUE INDEX. The application check stays — it is what produces the
# helpful 409 that hands the CP the correction already open — but it is now the
# fast path in front of a rule the database enforces, not the only rule.
OPEN_AMENDMENT_INDEX_NAME = "logbooks_one_open_amendment_per_parent"
OPEN_AMENDMENT_INDEX_KEYS = [("parent_logbook_id", 1)]

# PARTIAL, AND EVERY CLAUSE IS ONE A partialFilterExpression MAY CONTAIN.
# Mongo permits equality, `$exists: true`, the range operators and `$type`, and
# nothing else — no `$ne`, no `$or`, no `$not`, no `$nin`. An index whose
# filter uses a forbidden operator is REJECTED, and `_ensure_index_resilient`
# logs and returns rather than raising, so the rejection would be silent and
# the race would stay open behind a green suite. Hence the shape below, and
# hence the by-hand script that fails loudly.
#
# IT SELF-MAINTAINS, WHICH IS WHY THERE IS NO SENTINEL FIELD. Every clause
# reads a field the document already carries, so a child leaves the index the
# moment it is withdrawn, filed, signed or soft-deleted — no closing path has
# to remember to unset anything, and a path that forgot would otherwise hold a
# parent's Amend button shut forever.
#
# `cp_signature: None` matches null OR MISSING, which is Mongo's rule for an
# equality-to-null and is exactly the question "unsigned" means here.
OPEN_AMENDMENT_PARTIAL_FILTER = {
    "parent_logbook_id": {"$type": "string"},
    "is_amendment": True,
    "is_deleted": False,
    "status": "draft",
    "is_locked": False,
    "cp_signature": None,
}


def logbook_is_withdrawn(log) -> bool:
    """Has this amendment been withdrawn? The one predicate, for one field."""
    return (isinstance(log, dict)
            and str(log.get("status") or "") == WITHDRAWN_STATUS)


def logbook_is_filed(log) -> bool:
    """IS THIS DOCUMENT A RECORD? The rule, in one place at last.

    FILED means `is_locked` (the finalize flag) or `status == "submitted"` (the
    freeze for the immediate types). A `cp_signature` on an open draft is not a
    filed record.

    IT WAS WRITTEN TWICE, VERBATIM — `_filed_log._is_filed` on the server and
    `isFiled` in frontend/src/utils/amendmentChain.js — and the withdraw
    endpoint would have made a third. The client's copy stays, because it runs
    on a device this server cannot reach and has to answer offline; the Python
    one is now this, and `_filed_log` calls it.

    `open_amendment_head` IS NOT A THIRD COPY AND IS DELIBERATELY LEFT ALONE.
    It also treats a bare `cp_signature` as closing a child, which is BROADER
    than filed and correct for the question it asks — "is there an INTENTION
    still outstanding" — see its own note. Withdrawal asks the narrower legal
    question, because a signature on an unfrozen draft is not yet a filed
    correction, and folding the two together would start refusing to withdraw a
    draft somebody signed but never submitted.
    """
    if not isinstance(log, dict):
        return False
    return bool(log.get("is_locked")) or log.get("status") == "submitted"


def withdrawal_state(log) -> dict:
    """Who withdrew this amendment, and when. Off the RECORD, never the clock.

    Returns `{"withdrawn": bool, "by": str|None, "by_name": str|None,
    "at": datetime|str|None}`. Absent parts stay absent rather than being
    filled in — the same rule `amendment_state` follows, and for the same
    reason: a withdrawal written by a script or a migration that recorded no
    actor must READ as having recorded no actor.
    """
    if not logbook_is_withdrawn(log):
        return {"withdrawn": False, "by": None, "by_name": None, "at": None}
    return {
        "withdrawn": True,
        "by": str(log.get("withdrawn_by") or "").strip() or None,
        "by_name": str(log.get("withdrawn_by_name") or "").strip() or None,
        "at": log.get("withdrawn_at"),
    }


def withdrawal_sentence(state) -> str:
    """One line saying the correction was taken back. Empty when it was not.

    THE RECORD HAS TO BE ABLE TO SAY SO. A withdrawal of a proposed correction
    to a compliance record is itself an act; a state flag that only makes a
    warning disappear would let a correction vanish with nobody's name on it.
    Same shape as `amendment_sentence`, which is the sentence this one answers.
    """
    if not (state or {}).get("withdrawn"):
        return ""
    who = (state or {}).get("by_name")
    day = _amendment_day((state or {}).get("at"))
    lead = "This proposed correction was withdrawn"
    if who:
        lead += f" by {who}"
    if day:
        lead += f" on {day}"
    return (f"{lead}. It was never signed and never filed, so it is not part "
            f"of the record; the log it proposed to correct is unchanged.")


AMENDMENT_REASON_REQUIRED = "AMENDMENT_REASON_REQUIRED"
AMENDMENT_REASON_NOT_A_SENTENCE = "AMENDMENT_REASON_NOT_A_SENTENCE"
AMENDMENT_REASON_MIN_CHARS = 6


def amendment_reason_problem(reason):
    """None if the reason is readable, else the code naming what is wrong.

    WHY A RULE AT ALL. On 2026-08-31 a CP filed five amendments to one
    orientation with the reasons "1", "1", "1", "1" and "0". Nothing wrote
    those digits -- both gates asked only whether the field was non-empty
    (`if (!reason.trim())` on the client, `if not str(reason).strip()` here),
    so "1" was the shortest thing that passed and the button enabled on the
    first keystroke. A check on PRESENCE standing in for a check on CONTENT,
    on the field whose entire purpose is explaining a change to a signed
    compliance record to a human reader.

    WHY SIX CHARACTERS AND A WORD, defended rather than picked.

    A length alone is defeated by "11111111". A rule banning numerals would
    refuse "corrected count to 4", which is a better reason than most. So the
    test is BOTH: at least six characters after trimming, and at least one run
    of three letters -- a word.

    Six clears every short reason a CP would really give: "wrong trade" (11),
    "bad trade" (9), "no OSHA" (7). Lower would admit "ok"; higher would begin
    refusing legitimate ones. The WORD requirement does the actual work -- it
    is what "1", "0", "11", "12345678" and "1 2 3 4 5 6" fail, and the rule
    never mentions digits to do it.

    IT IS NOT PROOF AGAINST A DETERMINED BYPASS. "aaaaaa" passes. It is not
    meant to be: it stops the accidental digit, which is what happened, and a
    CP who wants to defeat it can already write "asdfgh". The remedy for that
    is a person reading the record, not a longer regex.
    """
    text = str(reason or "").strip()
    if not text:
        return AMENDMENT_REASON_REQUIRED
    if len(text) < AMENDMENT_REASON_MIN_CHARS:
        return AMENDMENT_REASON_NOT_A_SENTENCE
    if not re.search(r"[A-Za-z]{3}", text):
        return AMENDMENT_REASON_NOT_A_SENTENCE
    return None


def open_amendment_head(children):
    """The ONE unsigned child of a parent, chosen deterministically.

    An unsigned amendment is an intention, not a correction. Two of them on one
    parent are two competing intentions and neither is the record -- the record
    is the deepest SIGNED link. 588 Thomas has exactly that fork today: two
    unsigned orientation children of one parent, 49 seconds apart.

    DETERMINISTIC, BY THE SAME (created_at, _id) ORDER _filed_log USES. With
    two open children a raw find_one returns whichever Mongo hands back first,
    so the refusal would name a different draft on each attempt and the CP
    would be offered a different correction every time he tapped.

    A SIGNED child does not block: a correction that landed is part of the
    chain, and the next amendment amends it.

    NEITHER DOES A WITHDRAWN ONE, and that is what makes withdrawal an EXIT
    rather than a second trap. A withdrawn child that still counted as open
    would hold this parent's amend button shut forever, and the refusal would
    keep offering the CP a correction he has already taken back — which is
    exactly the dead end that produced the forks this rule exists to stop.
    """
    def _open(c):
        if not isinstance(c, dict):
            return False
        if logbook_is_withdrawn(c):
            return False
        return not (c.get("is_locked") or c.get("status") == "submitted"
                    or c.get("cp_signature"))

    def _order(c):
        created = c.get("created_at")
        return (created if isinstance(created, datetime)
                else datetime.min.replace(tzinfo=timezone.utc),
                str(c.get("_id", "")))

    openc = [c for c in (children or []) if _open(c)]
    return max(openc, key=_order) if openc else None


def amendment_state(log) -> dict:
    """Was this record amended, and is the reason on it? THREE states.

    `amendment_reason` was WRITE-ONLY: amend_logbook stored it on the child and
    nothing read it back, so the sentence justifying a change to a signed
    3301.2 record existed only in Mongo.

    THE MIDDLE STATE IS NOT DECORATIVE. amend_logbook refuses a reasonless
    amendment (400), so nothing through that endpoint lands there -- but a
    script, a migration or a direct write can, and this codebase spent
    2026-08-31 on exactly that class of row. Collapsing "amended, reason
    unknown" into "not amended" hides a correction; collapsing it into "amended
    and explained" prints an empty quotation as though somebody wrote it.

    IT READS THE RECORD, NEVER THE CLOCK. Every value comes off the document,
    so an amendment filed in September for an August log says the same thing in
    December.
    """
    if not isinstance(log, dict) or log.get("is_amendment") is not True:
        return {"state": AMENDMENT_NONE, "reason": None, "by": None, "at": None}
    reason = str(log.get("amendment_reason") or "").strip()
    by = str(log.get("created_by_name") or "").strip()
    return {
        "state": AMENDMENT_PRESENT if reason else AMENDMENT_NO_REASON,
        "reason": reason or None,
        "by": by or None,
        "at": log.get("created_at"),
    }


def _amendment_day(value) -> str:
    """The calendar day off the record. A datetime or an ISO string, both of
    which reach here depending on whether the doc has been serialized. Never a
    guess, and never relative to now."""
    # ── LEFT AS THE UTC DAY, DELIBERATELY, AND IT IS WRONG ──────────────────
    # `amended_at` / `withdrawn_at` are UTC instants, so an amendment filed at
    # 8pm on a Tuesday in New York reports as Wednesday's -- the same defect
    # `eastern_date` exists to stop, on the one line of the document that says
    # when somebody changed it. Routing it through eastern_date is a two-line
    # change and it was made and reverted here: `_amendment_day` is shared with
    # `withdrawal_sentence`, which is not part of the report renderer, and the
    # correction moves a date on two of ITS tests. That is an owner's call, not
    # this one's. See the report's "found but not changed" section.
    if isinstance(value, datetime):
        return value.date().isoformat()
    text = str(value or "").strip()
    return text[:10] if len(text) >= 10 and text[4] == "-" else ""


def amendment_sentence(state) -> str:
    """One line for a document header. Empty when the record is not amended.

    Says WHO and WHEN as well as why: the CP did not create this and did not
    ask for it, and "filed by <name> on <date>" is the fact that turns a record
    that changed shape into one somebody changed. Absent parts are omitted, not
    filled in.
    """
    st = (state or {}).get("state")
    if st not in (AMENDMENT_PRESENT, AMENDMENT_NO_REASON):
        return ""
    who = (state or {}).get("by")
    day = _amendment_day((state or {}).get("at"))
    lead = "This record was amended"
    if who:
        lead += f" by {who}"
    if day:
        lead += f" on {day}"
    if st == AMENDMENT_PRESENT:
        return f"{lead}. Reason given: {state.get('reason')}"
    return (f"{lead}. NO REASON WAS RECORDED for this amendment - the "
            f"correction is on the record but its explanation is not.")


def _display_sub_company(name):
    """Render a subcontractor/company for a report or headcount. The
    'UNASSIGNED' sentinel — a worker whose sub was not on the project roster at
    check-in — is a PLACEHOLDER, not a company. Show it as an explicit pending
    state so an inspector reads 'awaiting assignment', never a real sub named
    UNASSIGNED. The row and its headcount stay visible; ONLY the label changes —
    a pending row is better than a dropped worker (PR B, constraint 2)."""
    s = str(name or "").strip()
    if not s or s.upper() == "UNASSIGNED":
        return "Pending assignment"
    return s


# The one phrase for a field that was never filled. Matches the inspector
# screen's logbookView.fNotRecorded, so one record reads the same on the device
# and in the PDF.
NOT_RECORDED = "— Not recorded"


def answer_label(value, *, yes="Yes", no="No"):
    """A stored answer as a LABEL, with absence stated rather than implied.

    THREE ANSWERS, AND THE THIRD IS THE ONE THAT KEPT GETTING LOST: yes, no, and
    "nobody answered". Twelve tables printed the raw stored value instead, which
    produced, on filed compliance documents:

        `no` under a column headed `Injury`, where it is unreadable as "no
            injury" versus "the question was not asked"
        the literal `True` in a Status column
        `flag: True` inside a joined key/value cell
        a tick against the WORD "No" in the same column

    and worst, in `_cs_item_body`, an answered NO vanishing entirely -- its
    guard was `value not in (None, "", False, [])`, and `False == 0` in Python,
    so a false answer took the same branch as an absent one and the row read
    "— Not recorded" on a BC 3301.13.13 statutory record.

    THE MACHINERY EXISTED AND WAS SCOPE-TRAPPED. `_yn`, `has()` and
    `toggle_map_rows` sit INSIDE `generate_single_logbook_html`, unreachable
    from the combined report, `get_daily_log_pdf` and `_cs_item_body` -- eight
    of the twelve sites. Their semantics were already right and already argued
    in their own comments ("False and 0 ARE captured values and render as
    captured"). Only their scope was wrong. This is that rule, at module level.

    ABSENCE IS `None` OR AN EMPTY/WHITESPACE STRING, and nothing else. `False`
    and `0` are answers and are rendered as answers -- that is the whole point.

    CASE- AND TYPE-TOLERANT ON THE WAY IN, because the stored domain is wider
    than any single writer: `preshift_signin.jsx` writes only lowercase
    `'yes'`/`'no'`/`None` (verified against production: 329 rows, zero
    capitalised, zero boolean), while test fixtures carry `"Yes"` and real
    booleans. Reading tolerantly costs nothing; NORMALISING THE STORED VALUES
    was ruled out, because the editor compares with strict lowercase equality
    and a rewritten `"Yes"` would render as unselected and be silently
    overwritten by the CP's first tap.

    Anything it does not recognise is returned as written rather than guessed
    at, so an unexpected value is visible instead of being flattened to "No".
    """
    if value is None:
        return NOT_RECORDED
    if isinstance(value, str):
        v = value.strip()
        if not v:
            return NOT_RECORDED
        low = v.casefold()
        if low in ("yes", "y", "true", "checked"):
            return yes
        if low in ("no", "n", "false", "unchecked"):
            return no
        if low in ("na", "n/a"):
            return "N/A"
        return _capitalize_first(v)
    if isinstance(value, bool):
        return yes if value else no
    return str(value)

# The nine daily inspections, in the order the CP walks them. Order lives here
# so the PDF does not print them in whatever order a dict happened to be built.
# "Other" names no specific thing, so pass/fail says nothing about anything.
# It carries what the CP wrote instead. See _display_inspections.
OTHER_INSPECTION_KEY = "other_checklist"

INSPECTION_ORDER = [
    "street_frontage", "fire_safety", "perimeter_fence", "fall_protections",
    "neighbors_property", "license_spot_check", "plans", "permits",
    "other_checklist",
]


def _inspection_label(key: str) -> str:
    """`fall_protections` -> `Fall Protections`, matching the device."""
    return str(key or "").replace("_", " ").title()


OSHA_REVIEW_LABELS = {
    "CLASS_UNVERIFIED": "Class unverified",
    "EXPIRY_IMPLAUSIBLE": "Expiry implausible",
    "EXPIRY_UNPARSEABLE": "Expiry unreadable",
    "EXPIRY_CONFLICT": "Expiry conflict",
    "DUPLICATE_SST": "Duplicate SST",
    # AN OBSERVATION, NEVER A JUDGEMENT. "Incorrect card number" and "Invalid
    # card number" both say the CP got it wrong; this register cannot make a
    # claim about what he meant. It states the system's expectation and that
    # this value differs from it, and says nothing about which is right --
    # which matters, because the rule rests on two samples. "Not recognised"
    # was rejected too: it implies a registry was checked, and none was.
    "CARD_NUMBER_FORMAT": "Unexpected card format",
    "NEEDS_REVIEW": "Needs review",
}


def osha_review_index(worker_docs) -> Tuple[Dict, set, set]:
    """Three indexes over the LIVE certifications, built in one pass.

    EVERY CERT IS INDEXED, NOT ONLY THE FLAGGED ONES, and that is the whole
    change. Indexing flagged certs alone left a miss with two causes the code
    could not tell apart -- the cert is present and clean, or THE CERT IS NOT
    THERE AT ALL -- and both rendered an em dash.

    Returns (review_by_key, known_cards, known_workers):
      review_by_key   (wid, card) -> review_reason, FLAGGED certs only
      known_cards     (wid, card) for EVERY live cert that has a card number
      known_workers   the wids the lookup actually returned, so a deleted
                      worker is distinguishable from a clean one
    A FOURTH ELEMENT, class_by_key, WAS REMOVED. It fed a Cert Type column
    that composed the class label and its hours from live certifications at
    print time; that composition is gone, and an index nobody reads is the same
    defect as a field nobody writes.
    """
    review_by_key: Dict = {}
    known_cards, known_workers = set(), set()
    for wdoc in worker_docs or []:
        wid = str(wdoc.get("_id"))
        known_workers.add(wid)
        for cert in (wdoc.get("certifications") or []):
            cn = str(cert.get("card_number") or "")
            if cn:
                known_cards.add((wid, cn))
            if cert.get("needs_review"):
                review_by_key[(wid, cn)] = cert.get("review_reason") or "NEEDS_REVIEW"
            elif card_number_finding(cert):
                # OBSERVED AT READ TIME, AND NOTHING IS WRITTEN. A backfill
                # would write onto a worker record to describe a defect in it,
                # and would re-create the hazard the Review column just closed:
                # a stored flag keyed to a card number, orphaned by any later
                # correction. Evaluating here applies to every row the instant
                # it ships, including rows filed long before the rule, and if
                # the rule proves too tight there is no backfill AND no
                # un-backfill to run.
                #
                # THE SAME EVALUATION THE CP'S SCREEN MAKES. Both reads go
                # through card_number_finding, which owns the SST scoping and
                # the precedence rule, so the document and the queue cannot
                # disagree about whether a row has a finding.
                review_by_key[(wid, cn)] = "CARD_NUMBER_FORMAT"
    return review_by_key, known_cards, known_workers


def osha_review_cell(entry, review_by_key, known_cards, known_workers) -> str:
    """What the Review column says about one row. THREE STATES, because there
    are three.

    This column printed an em dash for a clean row. Everywhere else in this
    file an em dash means "we do not know" -- _attendee_source_label says so in
    those words -- and the same table uses it in four other columns for
    genuinely absent data. One row could print an em dash five times meaning
    four different things, and the fifth was the only one that meant "verified".

    THE JOIN KEY IS UNSTABLE BY CONSTRUCTION. review_by_key is keyed on
    (worker_id, card_number) where the card number comes from the LIVE worker
    document and this row's comes from the FILED snapshot. Correct a stored
    card number and the flag orphans from its row, and the row printed CLEAN --
    the dangerous direction. The card_number validation pass rewrites malformed
    numbers on live worker documents, so it manufactures this case deliberately.
    A row whose card number matches NO live cert was not checked, whatever it
    says, and this now says so.

    A PER-WORKER FALLBACK WAS REJECTED. A man holding a clean OSHA 30 and a
    flagged SST must not have his correct OSHA 30 row marked uncertain because
    a flag exists somewhere on his record. The row's own card number against
    the full live set has no such failure mode.
    """
    wid = str((entry or {}).get("worker_id") or "")
    cn = str((entry or {}).get("card_number") or "")
    # ── THE ROWS THIS COLUMN EXISTS FOR WERE THE ONES IT COULD NOT REACH ─────
    #
    # `osha_review_index` writes `review_by_key[(wid, cn)]` for every flagged
    # cert INCLUDING those with no card number, where `cn` is "". This read was
    # `... if cn else None`, so it declined to look up exactly those keys. The
    # register's worst rows -- an unreadable class, no number, no expiry -- are
    # precisely the ones with no card number, and they fell through to the grey
    # "Not checked" instead of the amber "Class unverified". The column hid its
    # own findings.
    #
    # THIS IS NOT THE PER-WORKER FALLBACK REJECTED ABOVE, and the difference is
    # the whole reason it is safe: `(wid, "")` is an EXACT key for a cert that
    # genuinely has no number. It cannot attribute a flag from the man's other
    # certs to this row -- a clean OSHA 30 keyed `(wid, "12345")` is still
    # unreachable from a row with no number, which is what the rejection was
    # protecting.
    #
    # KNOWN LIMIT: two flagged no-number certs on one worker collide on
    # `(wid, "")` and the last indexed wins. Both are flagged, so the column is
    # right either way; only WHICH reason is shown is arbitrary.
    reason = review_by_key.get((wid, cn)) if wid else None
    if reason is not None:
        label = OSHA_REVIEW_LABELS.get(reason, "Needs review")
        return f'<span style="color:#b45309;font-weight:600;">&#9888; {label}</span>'
    if wid and cn and wid in known_workers and (wid, cn) in known_cards:
        # "No findings" rather than "None": a check ran and returned nothing.
        # "None" reads equally as "no review was done", which is the state below.
        return '<span style="color:#15803d;">No findings</span>'
    # NOT AN EM DASH. Every other dash in that table means a field was left
    # empty; this means a check did not run -- a different fact, and the one a
    # reader must not mistake for a clean result. Four ways to land here: no
    # card number to key on, no worker id, a worker document the lookup did not
    # return, or a card number that matches nothing in the live record.
    return '<span style="color:#64748b;">Not checked</span>'


def _osha_type_cell(entry) -> str:
    """The Cert Type column for one row, resolved against the live cert.

    THE LABEL comes from the STORED row, reworded to the class name the card
    actually prints. THE HOURS come from the live cert, and only when COLOUR
    determined its class. A row that joins to nothing keeps its filed label and
    gains nothing -- the same failure the Review column reports as "Not
    checked", and for the same reason: nothing was looked up.
    """
    stored = entry.get("certification_type", "") if isinstance(entry, dict) else ""
    wid = str((entry or {}).get("worker_id") or "")
    cn = str((entry or {}).get("card_number") or "")
    # THE STORED LABEL, AND NOTHING ELSE. This used to reword the filed value
    # through sst_class_label and append the hours the CLASS carries when
    # COLOUR had determined it -- a classification the filed row does not state,
    # resolved from live worker certifications at render time.
    #
    # SAME SHAPE AS THE PRE-SHIFT AFFIRMATION OVERLAY AND OUT FOR THE SAME
    # REASON. If composition is wrong for an attestation about a named man, it
    # is wrong for a classification the card did not state: Bulletin 2024-007
    # sec V.6 asks that a signature's integrity be maintained with "any changes
    # detectable after signing", and a register whose Cert Type column reads
    # differently on two renderings of one stored document cannot be validated
    # against a single moment.
    #
    # THE REGISTER WILL SHOW TWO SPELLINGS FOR A WHILE, AND THAT IS CORRECT.
    # certLabel wrote "SST" for SST_FULL until ca71e5f and "SST Worker" after
    # it, so rows filed before that date print "SST" and rows filed after print
    # "SST Worker". A FILED DOCUMENT SHOWS WHAT WAS FILED. Do not "fix" the old
    # rows: rewriting them would be the very thing this change removes, and the
    # ruling that the label is the word the card prints is kept by every row
    # filed since.
    #
    # The class and its hours are not lost. They live on the worker's
    # certification, where they are provable, and the Review column already
    # reports whether that record was checked.
    # NO PLACEHOLDER HERE. The combined report prints "&mdash;" for an empty
    # cell and the per-logbook PDF prints nothing; each applies its own at the
    # call site, and a helper that picked one would have quietly given the
    # per-logbook document a dash it has never used -- which is what
    # AbsentKeyIsStatedTest caught.
    # STRINGIFIED: a stored None would otherwise print the word "None" on a
    # compliance register. Empty stays empty -- the call sites own what an empty
    # cell shows, and the two renderers do not agree about it.
    _label = str(stored or "")
    # ── UNVERIFIED, FROM THE FILED ROW AND NOT FROM A LOOKUP ─────────────────
    #
    # `unverified` is frozen onto the entry from the check-in's `sst_status` at
    # the moment the card was read. Printing it here does NOT break the rule
    # this function is built around -- it is the stored snapshot speaking, the
    # same source as the label beside it, not a classification composed at
    # render time.
    #
    # WHY THE COLUMN NEEDED IT. A row reading "SST Unspecified / — / —" states a
    # class it never established, and reads as a credential on file. The gate is
    # unchanged and stays unchanged: a man is never refused for a card the app
    # could not read. What changes is that the DOCUMENT stops saying the
    # baseline was met. The LL196 attestation has always excluded these rows;
    # this register was the surface that disagreed with it.
    #
    # ROWS FILED BEFORE THIS FIELD EXISTED CARRY NO FLAG AND GAIN NO MARKER --
    # a filed document shows what was filed.
    if isinstance(entry, dict) and entry.get("unverified") is True:
        return (_label or "&mdash;") + (
            '<br /><span style="color:#b45309;font-size:11px;font-weight:600;">'
            "UNVERIFIED &#183; card could not be read</span>"
        )
    return _label


async def preshift_affirmation_count(db_, project_id: str, day: str) -> int:
    """How many workers affirmed for this project on this date.

    A COUNT, FOR THE FOOTER, AND NOT A PER-ROW CLAIM. The sheet states a fact
    about a different record -- how many affirmations are on file -- and never
    puts an affirmation beside a named man's row, because the stored sheet does
    not carry one.

    DATE-AGNOSTIC ACROSS THE CUTOVER, and this is what makes a legacy path
    unnecessary. Before signature events existed, an affirmation was a boolean
    on a check-in row; after, it is also a signature event. Counting DISTINCT
    WORKERS across both sources is correct in all three eras and double-counts
    in none of them:

        before   check-in rows only
        after    both, naming the same workers
        later    events only, if the check-in field is ever retired

    NOTHING IS MIGRATED. Writing a signature event for an affirmation that
    happened before the ledger existed would mean inventing a content hash over
    a snapshot nobody hashed and a timestamp the ledger did not witness -- a
    forged audit entry indistinguishable from a real one, which is worse than
    the gap it would close. The six affirmations recorded on 2026-08-28 stay
    exactly where they are and are counted from there.

    A FAILED READ RETURNS 0, and the footer then says nothing rather than
    guessing. It must never turn a read failure into a claim.
    """
    if db_ is None or not project_id or not day:
        return 0
    workers = set()
    try:
        start, end = get_day_range_est(day)
        async for row in db_.checkins.find(
            {
                "project_id": str(project_id),
                "check_in_time": {"$gte": start, "$lt": end},
                "is_deleted": {"$ne": True},
                "signature_affirmed": True,
            },
            {"worker_id": 1},
        ):
            wid = str(row.get("worker_id") or "")
            if wid:
                workers.add(wid)
    except Exception as e:  # pragma: no cover
        logger.warning(f"[preshift] affirmation count (checkins) failed: {e!r}")
    try:
        async for evt in db_.signature_events.find(
            {
                "document_type": PRESHIFT_AFFIRMATION_DOC_TYPE,
                "document_id": preshift_affirmation_document_id(project_id, day),
                "is_deleted": {"$ne": True},
            },
            {"signer": 1},
        ):
            wid = str(((evt.get("signer") or {}).get("user_id")) or "")
            if wid:
                workers.add(wid)
    except Exception as e:  # pragma: no cover
        logger.warning(f"[preshift] affirmation count (events) failed: {e!r}")
    return len(workers)


def preshift_affirmation_footer(count: int) -> str:
    """The line beneath the table. States what is held ELSEWHERE.

    A COUNT IS SAFE WHERE A PER-ROW MARK IS NOT: it is a fact about a separate
    record rather than an assertion about any named worker on this sheet.
    """
    if not count:
        return ""
    plural = "affirmation is" if count == 1 else "affirmations are"
    return (
        '<p style="color:#64748b;font-size:11px;line-height:1.6;margin:8px 0 0;">'
        "Affirmation records for this date are held separately and are not part "
        f"of this sheet. {count} {plural} on record.</p>"
    )


async def _resolve_signin_signatures(workers) -> dict:
    """`signin_id` -> base64 PNG, for roster rows whose signature lives in R2.

    THE FILED SHEET WAS CALLING SIGNED MEN UNSIGNED. `preshift_signin.jsx`
    persists `signin_id` on every row the new gate produces, and the merge that
    builds those rows HARDCODES `worker_signature: None` in two of its three
    passes — pass 1 with the comment "new system: frontend uses signin_id", and
    pass 3 for compliance-alert rows. The app resolves the image through
    `GET /api/signatures/{signin_id}`; this renderer only ever read
    `worker_signature`. So every man who signed through the gate printed
    "NO SIGNATURE ON FILE" on a filed compliance document while his signature
    sat in the card-audit bucket. An inspector reading that page concludes he
    did not sign.

    RESOLVED SERVER-SIDE AND INLINED, not linked. The report is rendered to PDF
    by WeasyPrint; an `<img src="/api/signatures/...">` would need it to make an
    authenticated HTTP call back into this app, so the bytes are fetched here
    and embedded as a data URI the same way every other signature on the sheet
    already is.

    THE SAME CHAIN THE ENDPOINT USES, so the two cannot diverge:
        signin_id -> sign_ins -> (project_id, worker_enrollment_id, ET date)
                  -> daily_signatures.signature_r2_key -> card-audit bucket
    It is the CARD-AUDIT bucket, not R2_BUCKET_NAME — the endpoint says so and
    falling through to the general bucket would silently find nothing.

    BEST-EFFORT AND NEVER RAISES. A storage failure must not take down a filed
    roster; an unresolved row is reported as UNRESOLVED and rendered as a third
    state, never as an accusation. Bounded concurrency because a 60-man roster
    is 60 object reads.
    """
    ids = []
    for w in (workers or []):
        if str(w.get("worker_signature") or w.get("signature") or "").strip():
            continue                      # already inline; nothing to resolve
        sid = str(w.get("signin_id") or "").strip()
        if sid:
            ids.append(sid)
    if not ids:
        return {}
    out: dict = {}
    try:
        oids, by_oid = [], {}
        for sid in set(ids):
            try:
                oid = ObjectId(sid)
            except Exception:
                continue
            oids.append(oid)
            by_oid[str(oid)] = sid
        if not oids:
            return {}
        sign_ins = await db.sign_ins.find({"_id": {"$in": oids}}).to_list(2000)

        from zoneinfo import ZoneInfo
        _et = ZoneInfo("America/New_York")
        wanted, key_to_sid = [], {}
        for si in sign_ins:
            ts = si.get("timestamp")
            if isinstance(ts, datetime):
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                date_ymd = ts.astimezone(_et).strftime("%Y-%m-%d")
            else:
                continue
            k = (si.get("project_id"), si.get("worker_enrollment_id"), date_ymd)
            wanted.append({
                "project_id": k[0], "worker_enrollment_id": k[1], "calendar_date": k[2],
            })
            key_to_sid[k] = by_oid.get(str(si.get("_id")), "")
        if not wanted:
            return {}
        sig_rows = await db.daily_signatures.find({"$or": wanted}).to_list(2000)

        import card_audit as _ca
        bucket = getattr(_ca, "CARD_AUDIT_BUCKET_NAME", "")
        if not (_r2_client and bucket):
            logger.warning("[preshift-sig] card-audit storage not configured; "
                           f"{len(sig_rows)} signature(s) left unresolved")
            return {}

        sem = asyncio.Semaphore(8)

        async def _fetch(row):
            k = (row.get("project_id"), row.get("worker_enrollment_id"),
                 row.get("calendar_date"))
            sid = key_to_sid.get(k)
            r2_key = row.get("signature_r2_key")
            if not (sid and r2_key):
                return
            async with sem:
                try:
                    obj = await asyncio.to_thread(
                        _r2_client.get_object, Bucket=bucket, Key=r2_key,
                    )
                    out[sid] = base64.b64encode(obj["Body"].read()).decode("ascii")
                except Exception as e:
                    logger.error(
                        f"[preshift-sig] UNRESOLVED signin_id={sid} key={r2_key}: {e!r}"
                    )

        await asyncio.gather(*[_fetch(r) for r in sig_rows])
    except Exception as e:
        logger.error(f"[preshift-sig] signature resolution failed: {e!r}")
        return out
    _missing = len(set(ids)) - len(out)
    if _missing > 0:
        logger.warning(
            f"[preshift-sig] {_missing} of {len(set(ids))} roster signature(s) "
            "could not be resolved; those rows print as unavailable, NOT as unsigned"
        )
    return out


def _preshift_signature_cell(w, resolved=None) -> str:
    """The Signature column. TWO STATES, AND NEITHER MENTIONS AFFIRMATION.

    THIS COLUMN USED TO ASSERT A CLAIM IT DID NOT OWN. It printed NOT AFFIRMED
    from `signature_affirmed`, a key `preshift_signin.jsx` has never written, so
    every filed sheet accused every worker. The fix was a render-time overlay
    that resolved the affirmation from the day's check-ins -- which corrected
    the falsehood but left the printed document saying something the stored
    document did not, and Bulletin 2024-007 sec V.6 asks that a signature's
    integrity be maintained with "any changes detectable after signing".

    SO THE COLUMN GIVES UP THE CLAIM. The affirmation is now its own signature
    event, written at the gate at the moment it happens, and the sheet points at
    those records in its footer rather than absorbing them into a man's row.
    What remains here is the only thing the stored row actually knows:

        signature on file    the image, and that it is on file
        none on file         NO SIGNATURE ON FILE -- unchanged, and still the
                             strongest statement this column makes

    IT MUST NOT PRINT "NOT AFFIRMED" AGAIN, in any form: that was a finding
    against a named man from a field nobody wrote. It must not print "Affirmed"
    either. Both are claims about a record kept somewhere else.
    """
    _sig = str(w.get("worker_signature") or w.get("signature") or "").strip()
    if not _sig:
        # ── THE THIRD STATE, AND WHY IT HAS TO EXIST ────────────────────────
        # A row can carry `signin_id` instead of an inline image — that is what
        # the new gate produces, and `_resolve_signin_signatures` fetches it.
        # When the row HAS a signin_id and resolution failed, we do not know
        # that the man is unsigned; we know we could not read his signature.
        # Printing NO SIGNATURE ON FILE there is a finding against a named man
        # from a lookup that failed, which is the same defect this function's
        # docstring already forbids one dimension over. So it says what is true.
        # isinstance, not truthiness: a non-string in the map would reach
        # `.startswith` and raise, and a renderer that raises does not skip a
        # row -- it takes down the whole filed PDF.
        _b64 = (resolved or {}).get(str(w.get("signin_id") or "").strip())
        if isinstance(_b64, str) and _b64.strip():
            _sig = _b64.strip()
        elif str(w.get("signin_id") or "").strip():
            return (
                '<span style="color:#b45309;">Signature on file '
                '&mdash; image unavailable</span>'
            )
        else:
            return '<span style="color:#b91c1c;">NO SIGNATURE ON FILE</span>'
    _src = _sig if _sig.startswith("data:") else f"data:image/png;base64,{_sig}"
    return (
        f'<img src="{_src}" alt="Signature" '
        'style="max-height:34px;max-width:150px;display:block;" />'
        '<span style="font-size:10px;color:#475569;">Signature on file</span>'
    )


def _display_inspections(chk) -> str:
    """Render the daily inspections for a filed document.

    A FAILED INSPECTION MUST NOT PRINT AS A PASSED ONE. Both renderers used to
    do `", ".join(k for k, v in chk.items() if v)`, which was right while the
    value was a tick. The value is now {result, note}, and a dict is truthy —
    so that same line would have listed a FAILED item in the inspected list,
    identically to a passed one, and dropped the note entirely. On an NYC DOB
    3301-02 that is a document stating an inspection was fine when the CP
    recorded that it was not.

    THREE STATES, AND THEY ARE DIFFERENT:
      pass        walked, and fine
      fail        walked, and not fine — the note prints, always
      not walked  no result. NOT a pass. Named, so its absence is visible
                  rather than looking like an item that was never on the list.

    LEGACY LOGS RENDER EXACTLY AS THEY DID. A log filed while this was a
    tick-chip has {key: True} and no result anywhere in it. It keeps printing
    as the same plain comma list — an already-filed document does not change
    because the app later learned to record more.
    """
    import html as _html

    if not isinstance(chk, dict) or not chk:
        return ""

    rows = [(k, chk[k]) for k in INSPECTION_ORDER if k in chk]
    rows += [(k, v) for k, v in chk.items() if k not in INSPECTION_ORDER]

    if all(not isinstance(v, dict) for _k, v in rows):
        # Legacy tick shape, byte-identical to what it printed before.
        return ", ".join(_inspection_label(k) for k, v in rows if v)

    passed, failed, unwalked, other = [], [], [], []
    for key, value in rows:
        label = _inspection_label(key)
        if isinstance(value, dict):
            result = value.get("result")
            note = str(value.get("note") or "").strip()
            # "OTHER" IS NOT A PASS/FAIL ITEM — device round 4, finding 13.
            #
            # The other eight name a specific thing to look at, so pass and
            # fail mean something about that thing. "Other" names nothing, so
            # a green "Passed: Other" on a DOB document asserts that an
            # unnamed inspection was fine — a claim with no subject. It is now
            # the CP writing WHAT he inspected, and the note is the record.
            #
            # A stored pass/fail from before this change still renders, in the
            # branch below: an already-filed document does not change because
            # the app later learned to record something better.
            if key == OTHER_INSPECTION_KEY and not result:
                if note:
                    other.append(note)
                continue
            if result == "fail":
                failed.append((label, note))
            elif result == "pass":
                passed.append(label)
            else:
                unwalked.append(label)
        elif value:
            # A tick sitting in an otherwise-upgraded log. It says the CP
            # looked and nothing about what he found, so it is not a pass.
            unwalked.append(label)

    out = []
    if passed:
        out.append(f'Passed: {", ".join(passed)}')
    for label, note in failed:
        # The note is escaped. Everything around it in these renderers is not,
        # which is a pre-existing hole this change does not widen.
        detail = _html.escape(note) if note else NOT_RECORDED
        out.append(
            f'<span style="color:#b91c1c;"><strong>FAILED &mdash; {label}:</strong> '
            f'{detail}</span>'
        )
    if unwalked:
        out.append(f'Not inspected: {", ".join(unwalked)}')
    for note in other:
        out.append(f'Also inspected: {_html.escape(note)}')
    return "<br />".join(out)


def _report_date_long(date_str: str) -> str:
    """`2026-08-11` -> `August 11, 2026`.

    A machine date on a page an investor reads looks like a database dump. The
    calendar day is already a calendar day — no timezone is involved at either
    end, so none is introduced: the string is split, not parsed into a datetime
    that would shift a day west of Greenwich.
    """
    parts = str(date_str or "").split("-")
    if len(parts) != 3:
        return str(date_str or "")
    try:
        y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
        return f"{_MONTHS[m - 1]} {d}, {y}"
    except (ValueError, IndexError):
        return str(date_str or "")


_MONTHS = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
]


def _headcount_by_sub(checkins) -> "Tuple[List[Tuple[str, int]], int]":
    """Workers per subcontractor, and the total — FROM CHECK-INS.

    Check-ins are the source of truth for headcount everywhere on this page.
    The hand-entered numbers on the Site Superintendent and SSC logs stay in
    their own sections on page 2, where they are that form's record.

    A worker with no company is counted in the total and shown under an
    explicit heading rather than dropped: he was on site.
    """
    counts: Dict[str, int] = {}
    for c in checkins or []:
        if c.get("blocked") is True:
            continue          # turned away at the gate; he did no work
        name = str(c.get("company") or "").strip()
        if not name or name.upper() == "UNASSIGNED":
            name = "Not yet assigned"
        counts[name] = counts.get(name, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0].lower()))
    return ordered, sum(counts.values())


def _display_weather(data):
    """Render weather for a report or PDF. NEVER a blank.

    A blank cell cannot be told apart from a question nobody asked, and on the
    Daily Jobsite Log weather is now fetched rather than typed — so when the
    fetch fails the CP has no way to fill it in and the document must say what
    happened instead of leaving a gap.

    The three renderers that print this disagreed. All used
    `data.get("weather", "N/A")`, but a dict default only fires when the key is
    ABSENT: the editor always writes the key, so an empty value rendered as an
    empty string on two of them and "N/A" on the third. Measured:

        key ABSENT -> 'N/A '        key EMPTY -> ' '

    `weather_fetch_state` is written by the editor on every outcome
    ('ok' | 'offline' | 'error'), so a failure is distinguishable from a log
    filed before the field existed. Older documents have no state and simply
    fall through to the not-recorded case, which is the honest reading of them.
    """
    d = data or {}
    state = str(d.get("weather_fetch_state") or "").strip().lower()
    if state in ("offline", "error"):
        return "— Weather could not be retrieved"
    parts = [
        str(d.get("weather") or "").strip(),
        str(d.get("weather_temp") or "").strip(),
    ]
    body = " ".join(p for p in parts if p)
    if not body:
        return NOT_RECORDED
    wind = str(d.get("weather_wind") or "").strip()
    return f"{body} — Wind: {wind}" if wind else body


def _signature_paths_to_svg(paths, stroke_color="#0A1929", max_width=140, max_height=60):
    """Reconstruct an inline SVG from SignaturePad stroke paths.

    SignaturePad (frontend) stores a signature as {paths, signerName, timestamp}
    where `paths` is a list of strokes, each stroke a list of {x, y} points in
    pad-pixel coords — NOT a base64 raster. The report renderers only knew how to
    embed base64, so real signatures fell through to a typed-name fallback and the
    document showed no signature. Rebuild the strokes as SVG polylines (viewBox =
    the drawn bounding box, so it scales regardless of the original pad size);
    weasyprint and the HTML report both render inline SVG. Works retroactively for
    every already-signed logbook. Returns the SVG string, or None if unusable."""
    if not isinstance(paths, list):
        return None
    # Collect valid points per stroke (kept for drawing) and flat (for bounds).
    strokes_pts = []
    for stroke in paths:
        if not isinstance(stroke, list):
            continue
        sp = [
            (p["x"], p["y"]) for p in stroke
            if isinstance(p, dict) and isinstance(p.get("x"), (int, float)) and isinstance(p.get("y"), (int, float))
        ]
        if sp:
            strokes_pts.append(sp)
    pts = [p for sp in strokes_pts for p in sp]
    if len(pts) < 2:
        return None

    xs = sorted(x for x, _ in pts)
    ys = sorted(y for _, y in pts)

    # Robust bounding box. A single mis-captured touch (a stray point far from the
    # ink) used to land in min()/max() and inflate the box — stretching the whole
    # signature vertically and dragging one stroke down the full height. Take a
    # 1st/99th percentile window instead, so a lone outlier can't set the bounds;
    # fall back to raw extents for tiny point sets or a degenerate span.
    def _pctl(vals, q):
        i = min(len(vals) - 1, max(0, int(round(q * (len(vals) - 1)))))
        return vals[i]

    if len(pts) >= 12:
        minx, maxx = _pctl(xs, 0.01), _pctl(xs, 0.99)
        miny, maxy = _pctl(ys, 0.01), _pctl(ys, 0.99)
    else:
        minx, maxx, miny, maxy = xs[0], xs[-1], ys[0], ys[-1]
    if maxx - minx < 1:
        minx, maxx = xs[0], xs[-1]
    if maxy - miny < 1:
        miny, maxy = ys[0], ys[-1]

    pad = 6.0
    vb_w = (maxx - minx or 1.0) + pad * 2
    vb_h = (maxy - miny or 1.0) + pad * 2

    polylines = []
    for sp in strokes_pts:
        coords = []
        for (x, y) in sp:
            # Drop points outside the robust box — removes the outlier spike
            # rather than clamping it to an edge, so no stroke drags to full height.
            if x < minx or x > maxx or y < miny or y > maxy:
                continue
            coords.append(f"{x - minx + pad:.1f},{y - miny + pad:.1f}")
        if len(coords) >= 2:
            polylines.append(
                f'<polyline points="{" ".join(coords)}" fill="none" stroke="{stroke_color}" '
                'stroke-width="0.6" stroke-linecap="round" stroke-linejoin="round"/>'
            )
    if not polylines:
        return None

    # Fit within BOTH max_width and max_height, preserving the true aspect ratio
    # (never stretch to fill a fixed-tall box); preserveAspectRatio keeps it
    # centered. Gentle upscale cap so a small signature isn't ballooned.
    scale = min(float(max_width) / vb_w, float(max_height) / vb_h, 3.0)
    disp_w = vb_w * scale
    disp_h = vb_h * scale
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {vb_w:.0f} {vb_h:.0f}" '
        f'width="{disp_w:.0f}" height="{disp_h:.0f}" '
        'preserveAspectRatio="xMidYMid meet" '
        'style="border:1px solid #e2e8f0;border-radius:4px;background:#ffffff;">'
        + "".join(polylines) + '</svg>'
    )


# ── This section styles ITSELF ──────────────────────────────────────────────
#
# info_box, bold_para, TH and TD are defined INSIDE generate_combined_report, so
# a builder shared with the per-logbook renderer cannot borrow them. Carrying
# its own styling is what lets ONE function produce the body for both -- and one
# body is the point: the OSHA register and the pre-shift sheet each drifted
# between the two renderers and each had to be pulled back.
_CS_TH = ('style="background-color:#1e293b;color:#ffffff;padding:10px 12px;'
          'text-align:left;font-weight:600;font-size:11px;text-transform:uppercase;'
          'letter-spacing:0.5px;" bgcolor="#1e293b"')
_CS_TD = ('style="padding:10px 12px;border-bottom:1px solid #e2e8f0;'
          'color:#334155;"')


def _cs_info_box(inner):
    return ('<table cellpadding="0" cellspacing="0" border="0" width="100%" '
            'style="margin:12px 0;" bgcolor="#f1f5f9"><tr><td '
            'style="background-color:#f1f5f9;padding:14px 18px;'
            'border-left:4px solid #f59e0b;font-size:15px;line-height:1.7;'
            f'color:#475569;">{inner}</td></tr></table>')


def _cs_bold_para(label, value):
    return ('<p style="color:#475569;line-height:1.6;margin:8px 0;">'
            f'<strong style="color:#0A1929;">{label}:</strong> {value}</p>')


CS_LOG_ATTESTATION = _ATTESTATIONS["site_superintendent_log"]["text"]

CS_LOG_ATTESTATION_HTML = (
    '<p style="color:#334155;font-size:12px;line-height:1.6;margin:14px 0 4px;'
    'padding:9px 11px;background:#f8fafc;border-left:3px solid #f59e0b;">'
    + CS_LOG_ATTESTATION + '</p>'
)


def _cs_item_body(item, block, cs_name):
    """One item's content, or the honest statement of why there is none.

    FOUR STATES, RENDERED FOUR WAYS, because they are four different facts and
    the OSHA register already demonstrated what happens when they are not.

        PRESENT         what he wrote
        ATTESTED_NONE   "None to report" WITH HIS NAME on it -- the assertion
                        is the value, and an unattributed "none" asserts
                        nothing
        NOT_REACHED     the sanctioned "&mdash; Not recorded" placeholder, the
                        one string this codebase allows for "the app has no
                        value for this"
        NOT_COLLECTED   a SCOPE statement: this system does not capture the
                        item. Not an attestation, and it must not read as one.
    """
    key = item["key"]
    fields = item.get("fields") or []

    if not item.get("collected"):
        # A SCOPE LINE, in the shape FALL_PROTECTION_NOTICE established: it says
        # what the document does NOT cover, so a reader does not take an empty
        # item for "nothing happened". Superintendent changes are rare and real;
        # silence about them would be read as their absence.
        return ('<span style="color:#64748b;">This log does not record this '
                'item. It is kept elsewhere.</span>')

    state = cs_item_state(key, {key: block}, None) if block is not None else NOT_REACHED

    if state == ATTESTED_NONE:
        who = _capitalize_first(str(cs_name or "").strip()) or "the superintendent"
        return (f'<span style="color:#15803d;">None to report</span>'
                f'<span style="color:#64748b;font-size:12px;"> &#183; attested by '
                f'{who}</span>')

    if state != PRESENT:
        return NOT_RECORDED

    # ── content ─────────────────────────────────────────────────────────────
    #
    # A SIGNATURE IS NOT A LINE OF TEXT, AND ITEM 1 WAS PRINTING IT AS ONE.
    # superintendentLogModel.js lists `signature` among the presence FIELDS, so
    # this loop reached it like any other and fell through to `str(value)`.
    # SignaturePad stores strokes, so a filed BC 3301.13.13 log rendered
    #
    #     Michael Cespedes
    #     {'paths': [[{'x': 1, 'y': 2}, ...]], 'signerName': 'Michael Cespedes'}
    #     06:45
    #     16:30
    #
    # as item 1's record, on BOTH renderers -- and a legacy base64 signature is
    # a STRING, so that branch pasted the whole blob in as body text instead.
    #
    # The signature is already rendered, correctly and with its affirmation
    # banner, by render_signature_html at the foot of this same section. This
    # was a second, garbled copy of it inside the table.
    #
    # SKIPPED BY NAME, not by type: the value being a dict is incidental, and a
    # type test would go on printing the base64 case. Nothing is lost.
    _NOT_TEXT = {"signature"}
    rows = []
    for field in fields:
        if field in _NOT_TEXT:
            continue
        value = block.get(field)
        if isinstance(value, (list, tuple)):
            for entry in value:
                if isinstance(entry, dict):
                    # `if str(v or "").strip()` drops False and 0 for the same
                    # reason the branch below did. A bool is an ANSWER.
                    parts = [f'<strong>{_capitalize_first(str(k).replace("_", " "))}:</strong> '
                             f'{answer_label(v) if isinstance(v, bool) else _sentence_case(str(v))}'
                             for k, v in entry.items()
                             if isinstance(v, bool) or str(v or "").strip()]
                    if parts:
                        rows.append(" &#183; ".join(parts))
                elif str(entry or "").strip():
                    rows.append(_sentence_case(str(entry)))
        elif isinstance(value, str) and value.strip():
            rows.append(_sentence_case(value))
        elif isinstance(value, bool):
            # AN ANSWERED "NO" USED TO VANISH FROM A STATUTORY RECORD.
            # The branch below reads `value not in (None, "", False, [])`, and
            # `False == 0` in Python, so a false answer took the SAME path as an
            # absent one: no row was appended, and if it was the item's only
            # field the function returned NOT_RECORDED. The superintendent
            # answered, and BC 3301.13.13 said he had not. `True` fared no
            # better -- it printed the four characters `True`.
            #
            # Checked BEFORE that guard, because a bool must never reach it.
            rows.append(answer_label(value))
        elif value not in (None, "", False, []):
            rows.append(str(value))
    if not rows:
        return NOT_RECORDED
    return "<br />".join(rows)


async def cs_attribution_for(db_, project_id, log_date, signer):
    """Was the signer the registered CS for this project on the log's date?

    READ TIME, AND IT WRITES NOTHING. Nothing about a superintendent's log may
    mutate the registration that describes him -- the same posture as the
    card-number finding and the pre-shift affirmation overlay.

    A FAILED READ REPORTS "no registration", NEVER a mismatch. The one thing
    this must not do is turn an outage into a finding against a named person on
    a statutory record.
    """
    if db_ is None or not project_id:
        return attribute_signer(signer, None, log_date)
    try:
        # THE ACTIVE ONE, AND DETERMINISTICALLY.
        #
        # This was a bare find_one on (project_id, is_deleted) with no
        # `is_active` and no sort. A project ACCUMULATES registrations --
        # register_construction_superintendent deactivates the predecessor and
        # inserts a new row rather than editing in place, and an admin can
        # switch one off -- so this returned whichever row Mongo handed back
        # first. When that was the deactivated predecessor, attribute_signer
        # read its `deactivated_at` and a project with a live registered CS
        # reported as having none: the exact failure the account link exists to
        # prevent, degrading toward telling a statutory record that a named
        # person was not registered.
        #
        # Two active rows should not exist, but "should not" is not "cannot" --
        # one migration and it would. Newest created_at wins, ties on _id, the
        # same ordering _filed_log and open_amendment_head use.
        _regs = await db_.cs_registrations.find({
            "project_id": str(project_id),
            "is_active": True,
            "is_deleted": {"$ne": True},
        }).sort([("created_at", -1), ("_id", -1)]).to_list(20)
        reg = _regs[0] if _regs else None
    except Exception as e:  # pragma: no cover
        logger.warning(f"[cs-log] registration read failed for {project_id}: {e!r}")
        reg = None
    return attribute_signer(signer, reg, log_date)


async def superintendent_projects_for(db_, user) -> list:
    """The projects where THIS user is the registered construction superintendent.

    WHY THIS EXISTS. The CP nav has three slots and a superintendent needs the
    3301.13.13 log in one of them. Keying that on ROLE would be wrong in the
    only case that matters: the superintendent on 588 Thomas holds a `cp`
    account, so a role test hides the log from the one man who has to file it,
    and shows it to every CP who does not.

    So the menu asks the same question the filed document answers about its own
    signer -- attribute_signer, via is_registered_cs. One predicate; a nav that
    decided this its own way would drift from the sentence the record prints.

    A FAILED READ RETURNS AN EMPTY LIST, never a raised error. This runs on the
    session-start path, and an outage in a registration lookup must not stop a
    CP logging in. The cost of the empty answer is one missing menu shortcut on
    a log that is still reachable from the dashboard.

    RESOLVED AGAINST TODAY, deliberately, unlike the read-time path which
    resolves against the LOG's date. The question here is present-tense -- "is
    he the superintendent now" -- not "was he when this was signed".
    """
    if db_ is None or not isinstance(user, dict):
        return []
    uid = str(user.get("id") or user.get("_id") or "")
    lic = normalise_licence(
        user.get("cs_license_number") or user.get("license_number"))
    if not uid and not lic:
        return []

    # ONLY the rows that could possibly match, rather than every active
    # registration in the database. The account link is the primary key here;
    # the licence is the corroborating one, and is only queried when the user
    # actually carries a licence number.
    ors = []
    if uid:
        ors.append({"user_id": uid})
    if lic:
        ors.append({"license_number_normalized": lic})
    try:
        regs = await db_.cs_registrations.find({
            "is_active": True,
            "is_deleted": {"$ne": True},
            "$or": ors,
        }).sort([("created_at", -1), ("_id", -1)]).to_list(50)
    except Exception as e:  # pragma: no cover
        logger.warning(f"[cs-capability] registration read failed for {uid}: {e!r}")
        return []

    today = eastern_date()
    out = []
    for reg in regs:
        # The SAME function the document uses, not a reimplementation of its
        # rule. It also re-checks created_at/deactivated_at against the date,
        # which the query above does not.
        if is_registered_cs(attribute_signer(user, reg, today)):
            pid = str(reg.get("project_id") or "")
            if pid and pid not in out:
                out.append(pid)
    return out


def _superintendent_log_html(logbook, weekly_status=None, attribution=None,
                             *, legal_record=True):
    """The whole section, built ONCE for both renderers.

    ONE BUILDER, TWO CALLERS. The OSHA register and the pre-shift sheet each
    drifted between the per-logbook PDF and the combined report -- the same
    stored document printing different things depending on which one you asked
    for -- and each had to be pulled back. This one starts that way.

    ── legal_record ────────────────────────────────────────────────────────
    ONE FLAG, THREE THINGS, AND THEY ARE ALL THE SAME THING: apparatus that a
    DOB inspector needs and a lender does not.

        the AFFIRMED / UNAFFIRMED banner under the signature
        the BC 3301.13.13 / 1 RCNY citations under every item label
        the attestation paragraph explaining what "none to report" means and
            that the times are the superintendent's account, not observed

    All three are the audit trail of a §3301 filing. On a progress report sent
    to an investor they read as a system talking to itself, and the operator
    ruled they come off it.

    THE SAME SHAPE `render_signature_html`'s `show_affirmation` ALREADY HAS, and
    deliberately not a second renderer: two builders for one stored document is
    how the register and the pre-shift sheet drifted in the first place.

    DEFAULT True, SO THE LEGAL PDF INHERITS IT. A new caller gets the filing's
    behaviour unless it asks otherwise, which is the safe direction: a citation
    printed to a lender is noise, a citation missing from a filing is a gap.

    AND THIS IS THE CALL SITE THAT BROKE B4. The signature below never passed
    `show_affirmation=False`, so the CS section was the one part of the investor
    report still printing the affirmation banner -- and a check that counted
    occurrences of the keyword could never have found it, because the defect was
    a call site that OMITS the keyword. `test_report_legal_vs_investor.py` walks
    the call graph instead.
    """
    data = (logbook or {}).get("data") or {}
    log_date = (logbook or {}).get("date")
    presence = data.get("presence") or {}
    cs_name = presence.get("printed_name") or (logbook or {}).get("cp_name") or ""

    rows = ""
    for item in cs_applicable_items(log_date):
        block = data.get(item["key"])
        if item["key"] == "weekly_meeting":
            # ITEM 10 IS A STATUS, NOT A FIELD, and it belongs in its own row
            # rather than as a paragraph below the table -- an item of the
            # eleven that is missing from the list of eleven reads as an
            # omission. The obligation is WEEKLY: a daily field blank six days
            # in seven teaches the reader that blank is normal here, and
            # teaches the superintendent the same, which then bleeds into items
            # 4 to 7 where a blank IS a finding.
            # NOT COLLECTED IN THIS RELEASE, so it says so rather than
            # rendering a blank a reader would take for "no meeting was due".
            # `weekly_status` is the parameter the meeting record will supply:
            # whether a BC 3301.13.19 meeting was recorded in the last seven
            # days OF ACTIVE WORK, with days carrying no gate check-ins not
            # counted, so a shutdown week cannot manufacture a violation.
            body = (weekly_status
                    or '<span style="color:#64748b;">This log does not record '
                       'the weekly meeting. It is kept elsewhere.</span>')
        else:
            body = _cs_item_body(
                item, block if isinstance(block, dict) else {}, cs_name)
        # ITEM 2 SAYS WHERE IT CAME FROM. Adopted from the CP's log unedited,
        # or his own once he changed it. Unmarked on a log filed before the
        # flag existed -- NOT "adopted", because a record that predates the
        # question has not answered it.
        if item.get("provenance") and body and body != NOT_RECORDED:
            _prov = cs_item_provenance(data)
            _prov_text = {
                PROVENANCE_ADOPTED: "adopted from the daily jobsite log",
                PROVENANCE_OWN: "the superintendent&#39;s own account",
            }.get(_prov)
            if _prov_text:
                body += ('<br /><span style="font-size:11px;color:#64748b;">'
                         + _prov_text + '</span>')
        cite = (item.get("citation") or "") if legal_record else ""
        rows += (
            f'<tr><td {_CS_TD} valign="top" width="34%">'
            f'<strong>{item["number"]}. {item["label"]}</strong>'
            + (f'<br /><span style="font-size:11px;color:#64748b;">{cite}</span>'
               if cite else "")
            + f'</td><td {_CS_TD} valign="top">{body}</td></tr>'
        )

    _arrived = presence.get("arrived_at") or NOT_RECORDED
    _departed = presence.get("departed_at") or NOT_RECORDED
    return (
        _cs_info_box(
            f'<strong style="color:#0A1929;">Superintendent:</strong> '
            f'{_capitalize_first(cs_name) or NOT_RECORDED}<br />'
            f'<strong style="color:#0A1929;">On site:</strong> {_arrived} '
            f'to {_departed}'
        )
        + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
          'style="border-collapse:collapse;margin:12px 0;font-size:13px;">'
        + f'<tr><th {_CS_TH}>Item</th><th {_CS_TH}>Record</th></tr>'
        + rows
        + '</table>'
        # ABOVE the signature: the claim, then the name that makes it.
        + (CS_LOG_ATTESTATION_HTML if legal_record else "")
        # WHAT THE SYSTEM KNOWS ABOUT WHO SIGNED, stated as a fact and never as
        # an accusation. There are legitimate reasons a signer is not the
        # registered CS, and from 2027-01-01 the alternate licensed
        # superintendent is one of them.
        + (('<p style="color:#475569;font-size:12px;line-height:1.6;'
            'margin:6px 0 4px;">' + attribution_sentence(attribution) + '</p>')
           if attribution else "")
        + _cs_bold_para("Construction Superintendent", _capitalize_first(cs_name) or "N/A")
        + render_signature_html(
            presence.get("signature") or (logbook or {}).get("cp_signature"),
            "Superintendent Signature", show_affirmation=legal_record)
    )


def render_signature_html(sig, label="CP Signature", show_affirmation=True):
    """Render a signature as email-safe HTML with its AFFIRMED / UNAFFIRMED
    banner. Handles both shapes: a base64 PNG string / {data: base64}, and the
    SignaturePad vector shape {paths: [...strokes...]} (reconstructed to SVG).

    ── show_affirmation ────────────────────────────────────────────────────
    A PARAMETER, NOT A SECOND RENDERER. The investor report prints the same
    fourteen signatures the filed documents do, and the affirmation banner
    beneath each one is machinery: "AFFIRMED for this document", a claimed
    time, a server-received time. That is the audit trail of a §3301 filing
    and it is exactly what a DOB inspector needs. It is not what a lender
    needs, and fourteen copies of it on a progress report read as a system
    talking to itself.

    THE SIGNATURE ITSELF NEVER GOES. Only the banner under it. Passing False
    also drops the UNAFFIRMED warning, which the operator has accepted for
    that document and ONLY that document: the per-logbook PDF
    (generate_single_logbook_html, 8 call sites) and the superintendent's log
    (_superintendent_log_html, 1) are the legal records and keep every banner
    they have.

    A COPY OF THIS FUNCTION WOULD HAVE DRIFTED. Two renderers of the same
    section have had to be pulled back twice on this file already; a third
    that differs only in one boolean would go the same way.
    """
    if not sig:
        return ""
    status = _signature_affirmation_html(sig) if show_affirmation else ""

    def _wrap(full_label, inner):
        return (
            # KEEP THE BLOCK TOGETHER. The label and the image are separate
            # <tr>s, and the print CSS carries `tr { page-break-inside: avoid }`
            # -- which protects each ROW and explicitly permits a break BETWEEN
            # them. So "CP Signature (Michael Cespedes):" ended one page and his
            # signature began the next, on a filed document whose whole point is
            # that a named person signed it.
            #
            # ON THE TABLE, so it covers every one of this function's ~20 call
            # sites at once. The .doc-section wrapper does not help: a section
            # holding a sixty-man roster is already taller than a page, so the
            # renderer drops its avoid request for the whole section.
            '<table cellpadding="0" cellspacing="0" border="0" '
            'style="margin-top:8px;page-break-inside:avoid;break-inside:avoid;">'
            '<tr><td style="font-weight:bold;color:#0A1929;font-size:14px;padding-bottom:4px;">'
            + full_label + ':</td></tr>'
            '<tr><td>' + inner + '</td></tr>'
            # An empty banner emits no row at all -- a bare <tr><td></td></tr>
            # is an invisible strip of padding under every signature on the
            # report, and fourteen of them is a visible one.
            + ('<tr><td>' + status + '</td></tr>' if status else '')
            + '</table>'
        )

    def _img(b64):
        # NO BORDER. A signature is ink on the page, not a framed exhibit; the
        # box read as a form field on a document whose whole point is that a
        # person signed it.
        return ('<img src="data:image/png;base64,' + b64
                + '" style="max-width:280px;height:auto;" />')

    if isinstance(sig, str):
        return _wrap(label, _img(sig))
    if isinstance(sig, dict):
        # THROUGH THE SAME NORMALISER AS EVERY OTHER NAME ON THIS DOCUMENT.
        # `signer_name` is stamped onto the signature object at signing time
        # from whatever the man typed; every other rendering of his name goes
        # through `_capitalize_first(logbook["cp_name"])`. So one filed report
        # carried "CP Signature (michael Cespedes):" beside "Michael Cespedes"
        # -- two spellings of one man on one page, from two sources.
        signer = _capitalize_first(
            sig.get("signer_name") or sig.get("signerName") or "")
        full_label = f"{label} ({signer})" if signer else label
        data_b64 = sig.get("data")
        # 1) base64 raster (legacy path / pre-rendered).
        if isinstance(data_b64, str) and data_b64:
            return _wrap(full_label, _img(data_b64))
        # 2) vector stroke paths — SignaturePad's real output → reconstruct SVG.
        svg = _signature_paths_to_svg(sig.get("paths"))
        if svg:
            return _wrap(full_label, svg)
        # 3) signer only (no drawable data).
        if signer:
            return (
                '<p style="color:#475569;margin:8px 0;">'
                '<strong style="color:#0A1929;">' + label + ':</strong> '
                + signer + ' (signed)</p>' + status
            )
        # A signature object with no drawable image and no signer — still record
        # its affirmation status so the record is never silently blank.
        return (
            '<p style="color:#475569;margin:8px 0;">'
            '<strong style="color:#0A1929;">' + label + ':</strong></p>' + status
        )
    return ""


def _filed_log(logbooks, log_type):
    """The log of this type the report should print: THE LATEST SIGNED RECORD.

    WHY THIS EXISTS. Ten call sites did `next((l for l in logbooks if ...))` on
    a query with NO sort, so each type resolved to whatever Mongo returned
    first — insertion order. `amend_logbook` creates the amendment as a SECOND
    document sharing (project_id, log_type, date), so once a log was amended the
    report kept printing the original and the correction was invisible. Ten
    hand-written picks is how the client and this renderer drifted apart twice;
    there is one now, and every call site goes through it.

    AN UNSIGNED AMENDMENT IS NOT A CORRECTION — it is an intention to correct.
    Replacing a signed record with it on a document that goes to investors and
    lenders would assert a change nobody has attested to. So supersession waits
    for the signature: the original prints until the amendment is FILED, and
    from that moment the amendment prints and the original never appears again.
    An in-progress amendment is not surfaced at all — "amendment in progress"
    tells a reader nothing actionable and invites being read as an admission.

    FILED means `is_locked` (the finalize flag) or `status == "submitted"` (the
    freeze for the immediate types). A cp_signature on an open draft is not a
    filed record. Ties break on created_at, newest first, then on _id so the
    choice is deterministic when timestamps collide.

    NOTHING FILED YET falls back to the first match, which is exactly the old
    behaviour: a day with only an unfiled draft still renders that draft rather
    than a blank section.

    A WITHDRAWN AMENDMENT IS NOT A CANDIDATE AT ALL, and the fallback is why
    that clause sits on `same_type` rather than inside the filed test. A withdrawn
    child can never be filed, so it could never win the `filed` branch — but on
    a day whose original was never signed it is a plain member of `same_type`
    and `same_type[0]` is insertion order, so the report could print a
    correction its own author took back, to a lender, as the day's record.
    """
    same_type = [l for l in logbooks
                 if l.get("log_type") == log_type and not logbook_is_withdrawn(l)]
    if not same_type:
        return None

    def _order(l):
        created = l.get("created_at")
        return (created if isinstance(created, datetime) else datetime.min.replace(tzinfo=timezone.utc),
                str(l.get("_id", "")))

    # `logbook_is_filed` IS the `_is_filed` that used to be defined here — the
    # same two clauses, lifted out so the withdraw endpoint asks this exact
    # question rather than writing a fourth copy of it.
    filed = [l for l in same_type if logbook_is_filed(l)]
    if filed:
        return max(filed, key=_order)
    return same_type[0]


async def generate_combined_report(
    project_id: str, date: str, diagnostics: bool = False,
) -> str:
    """Generate email-safe HTML report. Uses table-based layout, bgcolor attrs,
    and URL-based images for Gmail/Outlook/Apple Mail compatibility.

    Fixes:
      1) White background forced (Gmail dark mode defeated via bgcolor + color-scheme)
      2) Fits in email box (table layout, zero flexbox)
      3) Photos render (base64 -> absolute URLs to public image endpoints)
      4) Full report content (CP logbook activity photos + all sections)
    """

    BASE_URL = "https://api.levelog.com"

    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = project.get("name", "Unknown") if project else "Unknown"
    project_address = project.get("address", "") if project else ""

    # THE NAME AND THE ADDRESS ARE OFTEN THE SAME STRING. Projects are created
    # from an address, so `name` and `address` frequently hold identical text —
    # and the header printed both, in different fields, as though they were two
    # different facts. When they match, the band carries no subtitle and the
    # address is printed once, in the summary row beneath it.
    _header_project_line = (
        "" if (" ".join(str(project_name or "").split()).casefold()
               == " ".join(str(project_address or "").split()).casefold())
        else project_name
    )

    logbooks = await db.logbooks.find({
        "project_id": project_id,
        "date": date,
        "is_deleted": {"$ne": True},
    }).to_list(100)

    daily_log = await db.daily_logs.find_one({
        "project_id": project_id,
        "date": date,
        "is_deleted": {"$ne": True},
    })

    day_start, day_end = get_day_range_est(date)
    checkins = await db.checkins.find({
        "project_id": project_id,
        "check_in_time": {"$gte": day_start, "$lt": day_end},
        "is_deleted": {"$ne": True},
    }).to_list(500)

    checkin_count = len(checkins)

    # Reusable inline style constants
    TH = (
        'style="background-color:#1e293b;color:#ffffff;padding:10px 12px;'
        'text-align:left;font-weight:600;font-size:11px;text-transform:uppercase;'
        'letter-spacing:0.5px;" bgcolor="#1e293b"'
    )
    TD = 'style="padding:10px 12px;border-bottom:1px solid #e2e8f0;color:#334155;"'
    EMPTY_5 = f'<tr><td colspan="5" {TD}>&mdash;</td></tr>'
    # The pre-shift sheet is SIX columns since it gained a signature — a
    # placeholder narrower than its header renders a ragged table on the one
    # document nobody re-renders. EMPTY_5 still serves the three tables that
    # really are five wide.
    EMPTY_6 = f'<tr><td colspan="6" {TD}>&mdash;</td></tr>'
    EMPTY_3 = f'<tr><td colspan="3" {TD}>&mdash;</td></tr>'

    # =====================================================================
    #  TYPE AND SPACING SCALE
    # =====================================================================
    #
    # 17px against a 16px body is not a heading. This document had FOUR sizes
    # -- 16 body, 16 section header, 17 sub-head, 14 sub-title -- all within a
    # point of each other, so nothing on the page carried a rank. A reader
    # looking for the Pre-Shift Sign-In had to READ the words to find it, on a
    # sixteen-section record; and a section header the same size as the
    # sentence beneath it is not a header, it is a bolder sentence.
    #
    # THE TYPE SCALE. Each step is a jump, not a nudge:
    #
    #     30  document title      page 1 only, once
    #     24  section header      the name of a filed document
    #     19  sub-head            a named block inside a section
    #     16  body
    #     15  table label         uppercase and tracked; a caption, not a head
    #     13  table cell          density matters on a sixty-man roster
    #
    # THE SPACING SCALE, in the same spirit -- four steps, each roughly 1.7x
    # the one below it, so a gap ALWAYS says which boundary it is:
    #
    #     40  above a section header      between two filed documents
    #     24  between content blocks      within one document
    #     14  header to its description   they belong together
    #      8  label to its table          they are one unit
    #
    # A section header, its description and its content were separated by 12,
    # 12 and 12 -- three different relationships rendered identically, which is
    # why the page read as one undifferentiated column.
    _T_SECTION, _T_SUBHEAD, _T_LABEL = "24px", "19px", "15px"
    _S_SECTION, _S_BLOCK, _S_HEAD, _S_TIGHT = "40px", "24px", "14px", "8px"

    def section_title(text):
        """THE NAME OF A FILED DOCUMENT. Every one of these now starts its own
        sheet, so this is the first thing on a page and has to read like it."""
        return (
            '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
            f'class="doc-section-title" style="margin:{_S_SECTION} 0 0 0;">'
            f'<tr><td style="font-size:{_T_SECTION};font-weight:700;'
            'line-height:1.25;color:#0A1929;letter-spacing:-0.01em;'
            'padding-bottom:12px;border-bottom:2px solid #cbd5e1;">'
            f'{text}</td></tr></table>'
        )

    def sub_title(text):
        """THE CAPTION OVER A TABLE, and it is set as one: small, uppercase and
        tracked out, so it reads as a label rather than as a smaller heading
        competing with the section name above it."""
        return (
            '<table cellpadding="0" cellspacing="0" border="0" '
            f'style="margin:{_S_BLOCK} 0 {_S_TIGHT} 0;">'
            f'<tr><td style="font-size:{_T_LABEL};font-weight:700;'
            'color:#475569;text-transform:uppercase;letter-spacing:0.08em;">'
            f'{text}</td></tr></table>'
        )

    def sub_head(text):
        """A NAMED BLOCK INSIDE A SECTION -- "Headcount by subcontractor",
        "Work today". Four hand-written <h3>s at 17px; one builder at 19."""
        return (
            f'<h3 style="color:#0A1929;margin:{_S_BLOCK} 0 {_S_TIGHT};'
            f'font-size:{_T_SUBHEAD};font-weight:700;line-height:1.3;">'
            f'{text}</h3>'
        )

    def info_box(content):
        """THE SECTION'S DESCRIPTION. It sits under the header at the HEAD gap,
        the tightest of the block gaps -- a header and the line that qualifies
        it are one thing, and 12px put it exactly as far from its header as
        from the table below it."""
        return (
            '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
            f'style="margin:{_S_HEAD} 0 0 0;" bgcolor="#f1f5f9">'
            '<tr><td style="background-color:#f1f5f9;padding:16px 20px;'
            'border-left:4px solid #1565C0;font-size:16px;line-height:1.7;color:#475569;">'
            + content + '</td></tr></table>'
        )

    def para(text):
        return (f'<p style="color:#475569;font-size:16px;line-height:1.65;'
                f'margin:{_S_BLOCK} 0 0;">{text}</p>')

    def bold_para(label, value):
        return (
            f'<p style="color:#475569;font-size:16px;line-height:1.65;'
            f'margin:{_S_BLOCK} 0 0;">'
            f'<strong style="color:#0A1929;">{label}:</strong> {value}</p>'
        )

    # ==========================================================
    #  DAILY JOBSITE (CP Logbook)
    # ==========================================================
    daily_jobsite = _filed_log(logbooks, "daily_jobsite")
    # PAGE 1 - THE PROGRESS REPORT
    #
    # WHO THIS IS FOR. An investor or a bank, who asked "what was really done
    # today" and was handed a compliance filing. Page 2 onward IS that filing,
    # unchanged and unmoved - it is the legal record and an inspector reads it.
    # This page answers the question and stops.
    #
    # DELIBERATELY ABSENT: percent complete, which cannot be computed honestly
    # and is worse than nothing in front of a lender; and anything about cost
    # or draw status, which this app does not hold and must not imply.
    _pg1_date = _report_date_long(date)
    # AMENDED? A FACT ABOUT THE RECORD, not about one log section, so it sits
    # in the document header beside the date and the address.
    #
    # Read off the log this report PRINTS. _filed_log already supersedes a
    # signed parent with its signed amendment ("an unsigned amendment is not a
    # correction"), so by the time a child is printing, the reader is looking at
    # a corrected document with nothing on it saying so. That was the gap: the
    # report silently changed shape between two printings.
    # Escaped locally: the reason is operator-supplied text on its way into
    # an HTML document. `import html as _html` lower in this function is AFTER
    # this point, so it cannot be borrowed.
    import html as _amend_esc
    _amend = amendment_state(daily_jobsite)
    _amend_line = amendment_sentence(_amend)
    _amendment_html = (
        f'<div style="margin-top:16px;padding:12px 14px;background-color:#fffbeb;'
        f'border-left:3px solid #b45309;">'
        f'<span style="font-size:10px;text-transform:uppercase;letter-spacing:1.5px;'
        f'color:#b45309;font-weight:600;">AMENDED RECORD</span><br />'
        f'<span style="font-size:13px;color:#0A1929;">{_amend_esc.escape(_amend_line)}</span>'
        f'</div>'
    ) if _amend_line else ""

    _subs, _sub_total = _headcount_by_sub(checkins)

    _dj = ((daily_jobsite or {}).get("data") or {}) if daily_jobsite else {}
    _dj_id = str(daily_jobsite["_id"]) if daily_jobsite else ""
    # NO WEATHER ON THE COVER. It is a fact about the DAILY JOBSITE LOG and it
    # is printed there, in that log's own info box, where §3301-02 asks for it.
    # On the investor cover it was a second copy of the same string with no
    # document behind it -- the first line of a progress report answering a
    # question nobody with $2M in the ground was asking. `_display_weather` is
    # untouched and still has three call sites: both PDF renderers' daily
    # jobsite sections and the SSC section.

    # Headcount, by sub and total. From CHECK-INS, as ruled.
    _sub_rows = "".join(
        f'<tr><td {TD}>{_capitalize_first(_name)}</td>'
        f'<td {TD} align="right">{_n}</td></tr>'
        for _name, _n in _subs
    ) or f'<tr><td colspan="2" {TD}>{NOT_RECORDED}</td></tr>'

    # ONE LINE PER SUBCONTRACTOR. One Gemini call per row, every sentence
    # through the verifier before it can reach this page, and a refusal falls
    # back to the plain facts - which is exactly what this rendered before the
    # generator existed (#121), so the worst case here is the previous best case.
    #
    # AUTO-APPROVE. There is no human in this path: the report sends at the
    # admin's daily send time whether or not anyone read it. That is precisely
    # why generate_sentence is the ONLY thing called here - it runs
    # verify_sentence internally and returns None rather than an unchecked
    # string, so there is no way to render a sentence that did not pass.
    #
    # The closed input set is assembled below and is the whole of what the model
    # sees. Headcount comes from the GATE (_subs, via check-ins), not from the
    # row's hand-typed num_workers, matching the headcount table directly above.
    #
    # Imported here, not at module scope, matching how phase_inference is pulled
    # in (:11943) - the google-genai import stays off the boot path.
    from lib.ai.sub_summary import generate_sentence_traced as _gen_sub_sentence
    import html as _html

    _gate_counts = {_n.strip().lower(): _c for _n, _c in _subs}

    # Which of the four outcomes each row took. Rendered ONLY under
    # `diagnostics` — see the block after this loop.
    _ai_outcomes: List[tuple] = []

    # ── TWO CREWS, ONE SUBCONTRACTOR ────────────────────────────────────────
    #
    # Vanguard appeared twice in Work today with nothing to tell the two rows
    # apart. Both were correct — Concrete and Formwork — but a repeated name
    # with different activities under it reads as a duplicate on a document
    # somebody is checking for errors, and this page has already been through
    # one round of real duplicates.
    #
    # The trade is named ONLY where it disambiguates. Printing it on every row
    # would push a fact nobody asked for onto the rows that were never
    # ambiguous, and the page is a summary, not a schedule. Counted on the
    # normalised company so "AAZ" and "aaz " are one subcontractor, matching
    # how every other roster comparison on this project is keyed.
    _pg1_company_crews: Dict[str, int] = {}
    for _a in (_dj.get("activities") or []):
        _c = _roster_key(_a.get("company"))
        if _c:
            _pg1_company_crews[_c] = _pg1_company_crews.get(_c, 0) + 1

    _pg1_lines = ""
    for _a in (_dj.get("activities") or []):
        _co = str(_a.get("company") or "").strip()
        if not _co:
            continue
        # work_description / work_locations are the tapped chip labels, already
        # resolved and comma-joined by the stepper (composeSelection in
        # frontend/src/utils/dailyJobsiteModel.js). Splitting them back apart is
        # what gives the verifier one label per item to trace.
        _payload = {
            "company":      _display_sub_company(_co),
            "trade":        str(_a.get("trade") or "").strip(),
            "worker_count": _gate_counts.get(_co.lower()),
            "activities":   [_s.strip() for _s in
                             str(_a.get("work_description") or "").split(",")
                             if _s.strip()],
            "locations":    [_s.strip() for _s in
                             str(_a.get("work_locations") or "").split(",")
                             if _s.strip()],
            "photo_count":  sum(
                1 for _p in (_a.get("photos") or [])
                if _logbook_photo_is_renderable(_p)
            ),
        }
        # THE FALLBACK IS THE #121 LINE, unchanged. A refused sentence renders
        # exactly what this page rendered before the generator existed, so the
        # worst case of adding AI here is the status quo ante - never a gap.
        _facts = ", ".join(
            _x for _x in [
                _sentence_case(_a.get("work_description") or ""),
                _capitalize_first(_a.get("work_locations") or ""),
            ] if _x
        )
        # The generated sentence is ESCAPED and the fallback is not, and that
        # asymmetry is deliberate. verify_sentence is a vocabulary gate, not a
        # sanitizer - it tokenizes on [A-Za-z0-9]+ and ignores punctuation
        # completely, so angle brackets are invisible to it. CP free text is
        # already rendered raw here and on page 2 and that is this page's
        # established trust level; a model is a new writer and does not inherit
        # it. Escaping costs nothing on a sentence that traces.
        _gen, _outcome = _gen_sub_sentence(_payload)
        _ai_outcomes.append((_display_sub_company(_co), _outcome))
        _line = _sentence_case(_html.escape(_gen)) if _gen else _facts
        # The trade, only when this company has more than one crew today.
        _trade = str(_a.get("trade") or "").strip()
        _label = _capitalize_first(_display_sub_company(_co))
        if _pg1_company_crews.get(_roster_key(_co), 0) > 1 and _trade:
            _label += f' &mdash; {_capitalize_first(_trade)}'
        _pg1_lines += (
            '<p style="margin:0 0 10px;font-size:16px;line-height:1.6;color:#334155;">'
            f'<strong style="color:#0A1929;">{_label}</strong>'
            f'{" - " + _line if _line else ""}</p>'
        )

    # ── WHY THAT LINE SAYS WHAT IT SAYS — admin only ───────────────────────
    #
    # All four outcomes render the same fallback, so from the page alone a
    # refusal, a failure, a missing key and "no model was ever asked" are
    # indistinguishable. That is fine for a lender and useless for the person
    # who has to fix it — and a diagnosis has now been blocked twice on runtime
    # logs the operator cannot reach.
    #
    # NEVER ON THE SENT REPORT. `diagnostics` defaults False and only the two
    # authenticated preview endpoints pass it, gated on role. The scheduled
    # send — the copy that reaches investors and lenders — never sees this.
    #
    # It carries no key and no secret: an outcome is a branch name, an
    # exception CLASS, or a refusal reason plus the offending words, which are
    # the CP's own vocabulary or the model's.
    _pg1_ai_note = ""
    if diagnostics and _ai_outcomes:
        _rows = "".join(
            f'<div>{_html.escape(str(_c))} &mdash; {_html.escape(str(_o))}</div>'
            for _c, _o in _ai_outcomes
        )
        _pg1_ai_note = (
            '<div style="margin:12px 0;padding:8px 10px;border:1px solid #cbd5e1;'
            'border-radius:6px;background:#f8fafc;font-size:11px;color:#475569;">'
            '<strong style="color:#0A1929;">AI LINE &mdash; ADMIN VIEW ONLY, '
            'NOT ON THE SENT REPORT</strong>'
            f'{_rows}</div>'
        )

    # Photos, grouped by subcontractor, captioned from what the CP tapped.
    # ALL of them: four subs at five to seven each is the ordinary day and it
    # fits. Same URL scheme and the same renderable test the logbook section
    # uses, so a photo that vanishes there vanishes here - never a broken image
    # standing in for evidence.
    _pg1_photos = ""
    for _ai, _a in enumerate(_dj.get("activities") or []):
        _shots = ""
        for _pi, _photo in enumerate(_a.get("photos") or []):
            if not _logbook_photo_is_renderable(_photo):
                continue
            _orig = (
                f"{BASE_URL}/api/reports/logbook-photo/"
                f"{_dj_id}/{_ai}/{_pi}"
            )
            _done = _photo.get("enhance_status") == "done"
            _thumb = f"{_orig}?v=thumb" if _done else _orig
            _full = f"{_orig}?v=enhanced" if _done else _orig
            _tile = (
                f'<a href="{_full}" target="_blank" '
                'style="text-decoration:none;display:inline-block;">'
                f'<img src="{_thumb}" width="160" height="120" '
                'style="width:160px;height:120px;object-fit:cover;'
                'border-radius:4px;border:1px solid #e2e8f0;'
                'display:inline-block;margin:3px;" /></a>'
            )
            # A PHOTOGRAPH ADDED AFTER THE CP SIGNED IS LABELLED AS ONE.
            # Unlabelled photos are emitted exactly as before — the wrapper
            # exists only where there is something to say, so the ordinary
            # grid is untouched.
            _added_note = _photo_added_after_filing_caption(_photo)
            if _added_note:
                _tile = (
                    '<span style="display:inline-block;vertical-align:top;'
                    'width:166px;margin:0 0 6px;">'
                    f'{_tile}<span style="display:block;padding:0 3px;">'
                    f'{_added_note}</span></span>'
                )
            _shots += _tile
        if not _shots:
            continue
        _cap = " - ".join(
            _x for _x in [
                _capitalize_first(_display_sub_company(_a.get("company"))),
                _sentence_case(_a.get("work_description") or ""),
                _capitalize_first(_a.get("work_locations") or ""),
            ] if _x
        )
        _pg1_photos += (
            # SIZE, NOT CONTRAST, and the distinction is worth keeping:
            # #64748b on white is 4.76:1, which PASSES AA. It was simply the
            # smallest text near the photos. 13px is the report's own declared
            # table-cell step and #475569 is its body colour, which takes this
            # to 7.58:1 -- headroom instead of a 0.26 margin.
            f'<p style="margin:12px 0 4px;font-size:13px;color:#475569;">'
            f'{_cap}</p><div>{_shots}</div>'
        )

    # Anything flagged. Safety observations the CP recorded, and inspections he
    # marked FAILED - the two things a reader must not have to hunt for.
    _flags = ""
    for _o in (_dj.get("observations") or []):
        _desc = _sentence_case(_o.get("description") or "")
        if not _desc:
            continue
        _who = _capitalize_first(_o.get("responsible_party") or "")
        _fix = _sentence_case(_o.get("remedy") or "")
        _flags += (
            f'<li style="margin:0 0 6px;">{_desc}'
            f'{" - " + _who if _who else ""}'
            f'{". Action: " + _fix if _fix else ""}</li>'
        )
    for _k, _v in (_dj.get("checklist_items") or {}).items():
        if isinstance(_v, dict) and _v.get("result") == "fail":
            _note = str(_v.get("note") or "").strip()
            _flags += (
                '<li style="margin:0 0 6px;">Failed inspection: '
                f'{_inspection_label(_k)}{" - " + _note if _note else ""}</li>'
            )
    _flags_html = (
        sub_head("Flagged today")
        + '<ul style="margin:0 0 8px;padding-left:20px;font-size:15px;'
          'line-height:1.6;'
        + f'color:#334155;">{_flags}</ul>'
    ) if _flags else ""

    # ONE line of compliance status. The detail is page 2; this says only
    # whether a reader needs to go there.
    #
    # THE DENOMINATOR IS THE PROJECT'S REQUIRED SET. It used to be the number
    # of documents that happened to exist for the date, compared against
    # itself: `_total_logs = len(_real_logs)` and then "All 9 required logs
    # filed and signed". That sentence could not fail. Nine logs present became
    # nine logs required; a required log NOBODY FILED was invisible, because a
    # document that does not exist cannot be counted by counting documents. On
    # a compliance line that is the exact direction the error must not run.
    #
    # So the required set is read from the PROJECT (get_required_logbooks —
    # class, storeys, demolition, scaffold), and the logs actually filed are
    # compared against it. "4 of 4", which can also read "2 of 4".
    #
    # DAILY ONLY, and this is a restriction not an omission. A Tool Box Talk is
    # weekly and a Subcontractor Orientation is as-needed; counting either as
    # missing on a Tuesday would invent a deficiency out of a frequency. They
    # are still named when they ARE filed, so nothing the CP did goes unstated.
    #
    # SIGNED MEANS AFFIRMED, tested with _is_affirmed_signature — the same
    # predicate the signature banner beside each section prints from. The old
    # line tested `_l.get("cp_signature")` for truthiness, and production held
    # `cp_signature: {}`: an empty object, truthy, counted as signed here while
    # page 2 printed "UNAFFIRMED — inherited signature" for the very same log.
    # Two statements about one signature on one document.
    _FREQ = {t["key"]: (t.get("label") or t["key"], t.get("frequency"))
             for t in LOGBOOK_TYPE_REGISTRY}

    def _log_label(_t):
        return _FREQ.get(_t, (_t, None))[0]

    if project:
        _required = list(project.get("required_logbooks") or [])
        if not _required:
            _required = get_required_logbooks(project.get("project_class"), project)
    else:
        _required = []
    # THE SAME RESOLVER THE SECTIONS BELOW PRINT FROM, so this line can never
    # call a log missing that page 2 goes on to render, or vice versa. One pass,
    # so there is one lookup per required type and no second opinion.
    _by_type = {_t: _filed_log(logbooks, _t) for _t in _required}
    # An unknown key has no frequency to judge it by, so it is treated as due —
    # a new required type is surfaced rather than silently dropped from the
    # count until someone remembers to register it.
    _due = [_t for _t in _required if _FREQ.get(_t, (None, None))[1] in (None, "daily")]
    _done, _unaffirmed, _missing = [], [], []
    for _t in _due:
        _doc = _by_type.get(_t)
        if not _doc:
            _missing.append(_t)
        elif _is_affirmed_signature(_doc.get("cp_signature")):
            _done.append(_t)
        else:
            _unaffirmed.append(_t)
    # Required but not due today, and filed anyway. Stated because the ratio
    # above deliberately excludes them and silence would read as "not done".
    _extra = [_t for _t in _required if _t not in _due and _by_type.get(_t)]

    _unassessed_note = (
        " Building classification not set, so the two major-building logs are"
        " included until it is."
        if project and not classification_assessed(project) else ""
    )
    if not project:
        _compliance = "Project record not found — the required-log set could not be read."
    elif not _due:
        _compliance = "No daily logs are required on this project."
    else:
        _compliance = (
            f"{len(_done)} of {len(_due)} required daily logs filed and signed."
        )
        _short = []
        if _unaffirmed:
            _short.append(
                f"{len(_unaffirmed)} filed without an affirmed signature "
                f"({', '.join(_log_label(_t) for _t in _unaffirmed)})"
            )
        if _missing:
            _short.append(
                f"{len(_missing)} not filed "
                f"({', '.join(_log_label(_t) for _t in _missing)})"
            )
        if _short:
            _compliance = _compliance[:-1] + "; " + "; ".join(_short) + "."
    if _extra:
        _compliance += (
            " Also filed today: "
            + ", ".join(_log_label(_t) for _t in _extra) + "."
        )
    # WHY THE DENOMINATOR IS BIGGER THAN THE READER EXPECTS. get_required_logbooks
    # fails CLOSED on a project whose §3310 class was never decided, so the
    # Concrete Safety Manager log and the SSC/SSM log are counted as required.
    # Printing that count without the reason puts two unexplained deficiencies
    # on a document that goes to investors and lenders, and the honest sentence
    # is that nobody has classified the building — not that the site is failing.
    _compliance += _unassessed_note

    # ONE HEADER. The address and the date are printed by the document header
    # above this section and are NOT repeated here.
    #
    # They used to appear three times over: the dark band (which prints
    # project_name, and on this project the name IS the address), the summary
    # row (ADDRESS / DATE), and this subtitle — which printed project_name AND
    # project_address, i.e. the same string twice inside one line, formatted as
    # though they were two different facts. A reader counting fields on a
    # compliance document reads a repeat as a discrepancy.
    progress_html = (
        '<h2 style="color:#0A1929;margin:0 0 4px;font-size:30px;'
        'font-weight:700;line-height:1.2;letter-spacing:-0.02em;">'
        'Daily Progress Report</h2>'
        + info_box(
            '<strong style="color:#0A1929;">'
            f'Workers checked in at the gate:</strong> {_sub_total}'
        )
        + sub_head("Headcount by subcontractor")
        + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
          'style="border-collapse:collapse;margin:8px 0 0 0;font-size:15px;">'
        + f'<tr><th {TH}>Subcontractor</th>'
          f'<th {TH} align="right">Workers</th></tr>'
        + _sub_rows
        + f'<tr><td {TD}><strong>Total</strong></td>'
          f'<td {TD} align="right"><strong>{_sub_total}</strong></td></tr>'
        + '</table>'
        + ((sub_head("Work today") + _pg1_lines + _pg1_ai_note)
           if _pg1_lines else "")
        + ((sub_head("Photos") + _pg1_photos) if _pg1_photos else "")
        + _flags_html
        + '<p style="margin:22px 0 0;font-size:16px;line-height:1.6;color:#334155;">'
          f'<strong style="color:#0A1929;">Compliance:</strong> {_compliance}</p>'
        # THE BREAK USED TO BE EMITTED HERE and it was the only one in the
        # report. It is now emitted BETWEEN every pair of sections by the
        # joiner in the final assembly -- keeping a copy here as well would put
        # two breaks after the cover and a blank sheet between it and page 2.
    )

    jobsite_html = ""
    if daily_jobsite:
        logbook_id = str(daily_jobsite["_id"])
        d = daily_jobsite.get("data", {})
        activities = d.get("activities", [])

        # PHOTOS ARE PAGE 1 ONLY. Operator ruling, reversing the earlier one:
        # site photos are PROGRESS EVIDENCE and belong on the investor page.
        # The logbook is the legal record and NYC DOB 3301-02 does not require
        # a photograph, so page 2 stops carrying a second copy of the same
        # images.
        #
        # NOTHING ELSE LOSES THEM. The photo endpoint stays live because page 1
        # still uses it (server.py:15589), the per-logbook PDF an inspector
        # downloads renders its own (generate_single_logbook_html), and the
        # kiosk inspector renders from the device. This removes ONE of four
        # surfaces — see the PR.
        act_rows = ""
        for act in activities:
            # PR G + PR B (combined-report parity): company is short-entry AND the
            # UNASSIGNED sentinel renders as pending here too; description is prose;
            # location short-entry. crew_id/num_workers excluded.
            act_rows += (
                f'<tr>'
                f'<td {TD}>{act.get("crew_id", "")}</td>'
                f'<td {TD}>{_capitalize_first(_display_sub_company(act.get("company")))}</td>'
                f'<td {TD}>{_headcount_cell(act)}</td>'
                f'<td {TD}>{_sentence_case(act.get("work_description", ""))}</td>'
                f'<td {TD}>{_capitalize_first(act.get("work_locations", ""))}</td>'
                f'</tr>'
            )

        equip = d.get("equipment_on_site", {})
        equip_list = ", ".join(k.replace("_", " ").title() for k, v in equip.items() if v)
        chk = d.get("checklist_items", {})
        check_list = _display_inspections(chk)

        obs_html = ""
        obs_rows = ""
        for obs in d.get("observations", []):
            # PR G: description/remedy prose; responsible party short-entry.
            obs_rows += (
                f'<tr><td {TD}>{_sentence_case(obs.get("description", ""))}</td>'
                f'<td {TD}>{_capitalize_first(obs.get("responsible_party", ""))}</td>'
                f'<td {TD}>{_sentence_case(obs.get("remedy", ""))}</td></tr>'
            )
        if obs_rows:
            obs_html = (
                sub_title("Safety Observations")
                + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
                  'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
                + f'<tr><th {TH}>Description</th><th {TH}>Responsible</th><th {TH}>Remedy</th></tr>'
                + obs_rows + '</table>'
            )

        cp_sig = render_signature_html(daily_jobsite.get("cp_signature"), "CP Signature", show_affirmation=False)
        sup_sig = render_signature_html(d.get("superintendent_signature"), "Superintendent", show_affirmation=False)
        visitors = d.get("visitors_deliveries", "")
        wind = d.get("weather_wind", "")

        weather_str = _display_weather(d)

        # Only the ones that carry a value. All three empty renders nothing at
        # all rather than a row of "N/A" — see the note in the info box below.
        _t_in = str(d.get("time_in") or "").strip()
        _t_out = str(d.get("time_out") or "").strip()
        _areas = str(d.get("areas_visited") or "").strip()
        _pg2_bits = []
        if _t_in or _t_out:
            _pg2_bits.append(
                f'<strong style="color:#0A1929;">Time In:</strong> {_t_in or NOT_RECORDED}'
                f' &nbsp;&nbsp; <strong style="color:#0A1929;">Time Out:</strong> {_t_out or NOT_RECORDED}'
            )
        if _areas:
            _pg2_bits.append(
                f'<strong style="color:#0A1929;">Areas Visited:</strong> {_capitalize_first(_areas)}'
            )
        _pg2_times = ("<br />" + "<br />".join(_pg2_bits)) if _pg2_bits else ""

        jobsite_html = (
            section_title("Daily Jobsite Log (NYC DOB 3301-02)")
            + info_box(
                f'<strong style="color:#0A1929;">Weather:</strong> {weather_str}<br />'
                f'<strong style="color:#0A1929;">Description:</strong> {_sentence_case(d.get("general_description") or NOT_RECORDED)}'
                # PRINTED ONLY WHEN SET. Nothing in the app writes these three:
                # daily_jobsite.jsx holds timeIn/timeOut/areasVisited in state and
                # hydrates them from a stored log, but no control anywhere sets
                # them, so on every report since the U1 rebuild they printed a
                # permanent "N/A". A field that is always N/A on a compliance
                # record teaches a reader to skip the row. The state and the
                # payload keys are untouched, so the day a control is added these
                # reappear on their own — see the PR note.
                f'{_pg2_times}'
            )
            + sub_title("Activity Details")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            # "CP's count", not "Workers" — the same label the single-document
            # renderer now carries, for the same reason. See the note there.
            + f'<tr><th {TH}>Crew</th><th {TH}>Company</th><th {TH}>CP&#39;s count</th>'
              f'<th {TH}>Description</th><th {TH}>Location</th></tr>'
            + (act_rows or EMPTY_5)
            + '</table>'
            + bold_para("Equipment", equip_list or "None")
            + bold_para("Inspected", check_list or "None")
            + obs_html
            + (bold_para("Visitors / Deliveries", _sentence_case(visitors)) if visitors else "")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="margin-top:16px;border-top:1px solid #e2e8f0;"><tr><td style="padding-top:12px;">'
            + bold_para("CP", daily_jobsite.get("cp_name", "N/A"))
            + cp_sig + sup_sig
            + '</td></tr></table>'
        )

    # ==========================================================
    #  TOOLBOX TALK
    # ==========================================================
    toolbox = _filed_log(logbooks, "toolbox_talk")
    toolbox_html = ""
    if toolbox:
        td_data = toolbox.get("data", {})
        topics = td_data.get("checked_topics", {})
        topic_list = ", ".join(k.replace("_", " ").title() for k, v in topics.items() if v)
        att_rows = ""
        for a in td_data.get("attendees", []):
            # AN ATTENDEE WITH NO NAME IS NOT AN ATTENDEE. A seed row the CP
            # never filled rendered as a blank line on a signed attendance
            # record — a person who was at the talk and cannot be identified.
            #
            # THE COMMENT HERE USED TO SAY the pre-shift sheet and the OSHA
            # register "already use" this rule and that this table "was the one
            # that never got it". The first half was true and the second was
            # not: the per-logbook PDF for toolbox_talk (render_logbook_html)
            # had no name gate at all, so the SAME stored talk printed one way
            # in the emailed report and another way on the document an
            # inspector asks for by name. It has one now, and the two renderers
            # agree; there are two of these gates and both are load-bearing.
            if not str(a.get("name") or "").strip():
                continue
            # TWO COLUMNS ARE GONE FROM THIS TABLE, AND NEITHER FIELD IS.
            #
            # "Present" printed `signed` and "Confirmed" printed
            # `gate_confirmed`. Neither is a legal attestation -- the CP's
            # signature over the whole roster is (NYC DOB §3301.12.3 / OSHA
            # 1926.21) -- and two tick columns beside it invited exactly the
            # reading that signature already forecloses: that each man
            # individually attested to something. "Added by" stays, because
            # WHOSE CLAIM PUT HIM ON THE SHEET is the provenance question a
            # reader of an attendance record actually has.
            #
            # THE FIELDS STAY IN STORAGE, unchanged, and toolboxTalkModel.js is
            # untouched. Dropping a COLUMN is a rendering change; dropping a
            # FIELD is a data change, and the operator is not making that one.
            # Both are still written at the gate and both are still read --
            # `signed` by app/site/logbooks.jsx, `gate_confirmed` by anything
            # that queries the stored document.
            att_rows += (
                f'<tr><td {TD}>{_capitalize_first(a.get("name", ""))}</td>'
                f'<td {TD}>{_capitalize_first(a.get("title", ""))}</td>'
                f'<td {TD}>{_capitalize_first(a.get("company", ""))}</td>'
                f'<td {TD}>{_roster_clock(a.get("time"))}</td>'
                f'<td {TD}>{_attendee_source_label(a)}</td></tr>'
            )

        tb_sig = render_signature_html(toolbox.get("cp_signature"), "CP Signature", show_affirmation=False)

        # PR G: location/company/performed-by/cp short-entry; time excluded.
        toolbox_html = (
            section_title("Tool Box Talk")
            + info_box(
                f'<strong style="color:#0A1929;">Location:</strong> {_capitalize_first(td_data.get("location", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Company:</strong> {_capitalize_first(td_data.get("company_name", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Performed By:</strong> {_capitalize_first(td_data.get("performed_by", "N/A"))}<br />'
                f'<strong style="color:#0A1929;">Time:</strong> {td_data.get("meeting_time", "N/A")}'
            )
            + bold_para("Topics", topic_list or "None")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Name</th><th {TH}>Title</th><th {TH}>Company</th><th {TH}>In</th><th {TH}>Added by</th></tr>'
            + (att_rows or f'<tr><td colspan="5" {TD}>&mdash;</td></tr>')
            + '</table>'
            + bold_para("CP", _capitalize_first(toolbox.get("cp_name", "N/A")))
            + tb_sig
        )

    # ==========================================================
    #  PRE-SHIFT SIGN-IN
    # ==========================================================
    preshift = _filed_log(logbooks, "preshift_signin")
    preshift_html = ""
    if preshift:
        pd = preshift.get("data", {})
        # Affirmation only. Every other cell below reads `w`, the stored row.
        # A COUNT FOR THE FOOTER, not an overlay onto a man's row.
        _affirm_n = await preshift_affirmation_count(db, project_id, date)
        # Resolve R2-backed signatures ONCE for the whole roster, before the
        # loop: the cell renderer is sync and a per-row await would serialise
        # sixty object reads.
        _ps_sigs = await _resolve_signin_signatures(pd.get("workers", []))
        w_rows = ""
        for w in pd.get("workers", []):
            # `.get("name", "")` RETURNS THE DEFAULT ONLY ON AN ABSENT KEY.
            # A row storing `name: None` — which is exactly what correcting a
            # worker called "null" produces — returns None, and None.strip()
            # raises AttributeError. In a renderer, that does not skip a row:
            # it takes down the WHOLE PDF, so a data fix meant to clean one
            # name would have stopped every filed roster from printing.
            #
            # The safe form is already used twice in these same two functions
            # (`if not str(a.get("name") or "").strip()` on the attendee rows).
            # Shipped, not invented.
            if str(w.get("name") or "").strip():
                # PR G: name/company short-entry; osha_number excluded.
                # `or ""` ON EVERY CELL, for the same reason as the guard
                # above: a stored None interpolates into an f-string as the
                # four characters None, and a filed compliance record printing
                # "None" for a man's employer is the same defect as printing
                # "null" for his name, one field over.
                w_rows += (
                    f'<tr><td {TD}>{_capitalize_first(w.get("name") or "")}</td>'
                    f'<td {TD}>{_capitalize_first(w.get("company") or "")}</td>'
                    f'<td {TD}>{w.get("osha_number") or ""}</td>'
                    f'<td {TD}>{answer_label(w.get("had_injury"))}</td>'
                    f'<td {TD}>{answer_label(w.get("inspected_ppe"))}</td>'
                    f'<td {TD}>{_preshift_signature_cell(w, _ps_sigs)}</td></tr>'
                )

        ps_sig = render_signature_html(preshift.get("cp_signature"), "CP Signature", show_affirmation=False)

        preshift_html = (
            section_title("Pre-Shift Sign-In")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Name</th><th {TH}>Company</th><th {TH}>OSHA #</th>'
              f'<th {TH}>Injury</th><th {TH}>PPE</th><th {TH}>Signature</th></tr>'
            + (w_rows or EMPTY_6)
            + '</table>'
            + preshift_affirmation_footer(_affirm_n)
            # ABOVE the signature: the claim, then the name that makes it.
            + PRESHIFT_ATTESTATION_HTML
            + bold_para("CP", _capitalize_first(preshift.get("cp_name", "N/A")))
            + ps_sig
        )

    # ==========================================================
    #  SITE SUPERINTENDENT LOG  (daily_log)
    # ==========================================================
    site_html = ""
    if daily_log:
        # Subcontractor cards
        sub_rows = ""
        for card in (daily_log.get("subcontractor_cards") or []):
            # PR G: company/trade short-entry; description prose; hours/workers excluded.
            sub_rows += (
                f'<tr><td {TD}>{_capitalize_first(card.get("company_name", "N/A"))}</td>'
                f'<td {TD}>{_capitalize_first(card.get("trade", "N/A"))}</td>'
                f'<td {TD}>{card.get("num_workers", 0)}</td>'
                f'<td {TD}>{card.get("hours", "N/A")}</td>'
                f'<td {TD}>{_sentence_case(card.get("description", "N/A"))}</td></tr>'
            )

        # Safety checklist
        safety_rows = ""
        for item_key, item_val in (daily_log.get("safety_checklist") or {}).items():
            st = (answer_label(item_val.get("status"))
                  if isinstance(item_val, dict) else answer_label(item_val))
            cb = item_val.get("checked_by", "") if isinstance(item_val, dict) else ""
            safety_rows += (
                f'<tr><td {TD}>{item_key.replace("_", " ").title()}</td>'
                f'<td {TD}>{st}</td><td {TD}>{cb}</td></tr>'
            )

        # PR G: corrective actions / incident log / work performed are prose.
        corrective_na = daily_log.get("corrective_actions_na", False)
        corrective_text = "N/A" if corrective_na else (_sentence_case(daily_log.get("corrective_actions", "")) or "None recorded")

        incident_na = daily_log.get("incident_log_na", False)
        incident_text = "N/A" if incident_na else (_sentence_case(daily_log.get("incident_log", "")) or "None recorded")

        work_performed = _sentence_case(daily_log.get("work_performed", ""))
        work_html = (sub_title("Work Performed") + para(work_performed)) if work_performed else ""

        # Superintendent signature
        sup_sig_html = ""
        sup_sig_raw = daily_log.get("superintendent_signature")
        if sup_sig_raw and isinstance(sup_sig_raw, dict):
            # THROUGH THE NORMALISER, like every other name on this page.
            # These two blocks read signer_name raw, which is the same
            # "michael Cespedes" beside "Michael Cespedes" defect the
            # shared renderer just had, in the two places that do not use it.
            sn = _capitalize_first(
                sup_sig_raw.get("signer_name") or "Superintendent")
            sd = sup_sig_raw.get("data")
            inner = _signature_paths_to_svg(sup_sig_raw.get("paths"), max_width=150)
            if not inner and isinstance(sd, str) and sd:
                # NO BORDER, same as render_signature_html's _img. These two
                # blocks are hand-rolled copies of that renderer and carried
                # the frame it just lost.
                inner = (f'<img src="data:image/png;base64,{sd}" '
                         'style="max-width:300px;height:auto;" />')
            if inner:
                sup_sig_html = (
                    # Same break rule as render_signature_html's _wrap -- these
                    # two blocks are hand-rolled copies of it and split the same
                    # way.
                    '<table cellpadding="0" cellspacing="0" border="0" '
                    'style="margin-top:12px;page-break-inside:avoid;break-inside:avoid;">'
                    '<tr><td style="font-weight:bold;color:#0A1929;font-size:14px;padding-bottom:4px;">'
                    f'Superintendent ({sn}):</td></tr>'
                    f'<tr><td>{inner}</td></tr>'
                    '</table>'
                )
            elif sn:
                sup_sig_html = bold_para("Superintendent", sn + " (signed)")

        # CP signature
        cp_sig_html = ""
        cp_sig_raw = daily_log.get("competent_person_signature")
        if cp_sig_raw and isinstance(cp_sig_raw, dict):
            cn = _capitalize_first(
                cp_sig_raw.get("signer_name") or "Competent Person")
            cd = cp_sig_raw.get("data")
            inner = _signature_paths_to_svg(cp_sig_raw.get("paths"), max_width=150)
            if not inner and isinstance(cd, str) and cd:
                inner = (f'<img src="data:image/png;base64,{cd}" '
                         'style="max-width:300px;height:auto;" />')
            if inner:
                cp_sig_html = (
                    # Same break rule as render_signature_html's _wrap -- these
                    # two blocks are hand-rolled copies of it and split the same
                    # way.
                    '<table cellpadding="0" cellspacing="0" border="0" '
                    'style="margin-top:12px;page-break-inside:avoid;break-inside:avoid;">'
                    '<tr><td style="font-weight:bold;color:#0A1929;font-size:14px;padding-bottom:4px;">'
                    f'Competent Person ({cn}):</td></tr>'
                    f'<tr><td>{inner}</td></tr>'
                    '</table>'
                )
            elif cn:
                cp_sig_html = bold_para("Competent Person", cn + " (signed)")

        # The daily_log_photos collection and its four endpoints were removed:
        # nothing in the app ever wrote to it, so this section was always empty
        # and its <img> pointed at an auth-required endpoint that an email
        # client could never load. CP site photos come from the logbook
        # activity photos above, which DO have a public image endpoint.
        photos_section = ""

        not_signed_super = bold_para("Superintendent", "Not signed")
        not_signed_cp = bold_para("Competent Person", "Not signed")

        site_html = (
            section_title("Site Superintendent Log")
            + info_box(
                f'<strong style="color:#0A1929;">Weather:</strong> '
                f'{daily_log.get("weather", "N/A")} '
                f'{daily_log.get("weather_temp", "") or ""} '
                f'{daily_log.get("weather_wind", "") or ""}<br />'
                f'<strong style="color:#0A1929;">Workers on Site:</strong> {daily_log.get("worker_count", 0)}<br />'
                f'<strong style="color:#0A1929;">Notes:</strong> {daily_log.get("notes", "N/A")}'
            )
            + work_html
            + sub_title("Subcontractor Activity")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Company</th><th {TH}>Trade</th><th {TH}>Workers</th>'
              f'<th {TH}>Hours</th><th {TH}>Description</th></tr>'
            + (sub_rows or EMPTY_5) + '</table>'
            + sub_title("Safety Checklist")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Item</th><th {TH}>Status</th><th {TH}>Checked By</th></tr>'
            + (safety_rows or EMPTY_3) + '</table>'
            + sub_title("Corrective Actions") + para(corrective_text)
            + sub_title("Incident Log") + para(incident_text)
            + photos_section
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="margin-top:20px;border-top:2px solid #e2e8f0;"><tr><td style="padding-top:16px;">'
            + sub_title("Signatures")
            + (sup_sig_html or not_signed_super)
            + (cp_sig_html or not_signed_cp)
            + '</td></tr></table>'
        )

    # ==========================================================
    #  CONSTRUCTION SUPERINTENDENT LOG  (BC 3301.13.13)
    # ==========================================================
    cs_html = ""
    cs_lb = _filed_log(logbooks, "site_superintendent_log")
    if cs_lb:
        _cs_attr = await cs_attribution_for(
            db, project_id, cs_lb.get("date"),
            (cs_lb.get("data") or {}).get("presence") or {})
        cs_html = (
            section_title("Construction Superintendent Log (BC 3301.13.13)")
            # ONE BUILDER, BOTH RENDERERS. See _superintendent_log_html.
            + _superintendent_log_html(cs_lb, attribution=_cs_attr,
                                       legal_record=False)
        )

    # ==========================================================
    #  OSHA / SST CERTIFICATION LOG
    # ==========================================================
    # Rendered as a real table, and — critically — each row is joined back to the
    # worker's LIVE certifications so a cert the database has flagged for review
    # (needs_review / CLASS_UNVERIFIED, e.g. from audit_fabricated_certs) is never
    # shown as a clean row. The osha_log snapshot itself carries no review state,
    # so we look it up now; match is by (worker_id, card_number).
    osha_html = ""
    osha_lb = _filed_log(logbooks, "osha_log")
    if osha_lb:
        osha_entries = (osha_lb.get("data") or {}).get("entries") or []

        # ONE DEFINITION, in osha_review_index / osha_review_cell beside
        # _preshift_signature_cell. The rule is exercised directly by its tests
        # rather than through a copy, which is the only way a control run can
        # prove the renderer moved rather than a duplicate of it.
        review_by_key = {}
        known_cards, known_workers = set(), set()
        worker_ids = {str(e.get("worker_id")) for e in osha_entries if e.get("worker_id")}
        if worker_ids:
            qids = [q for q in (to_query_id(w) for w in worker_ids) if q is not None]
            worker_docs = await db.workers.find(
                {"_id": {"$in": qids}}, {"certifications": 1}
            ).to_list(500)
            review_by_key, known_cards, known_workers = osha_review_index(
                worker_docs)

        # THE SAME ROW RULE THE PER-LOGBOOK PDF APPLIES: a row that does not
        # name a worker is not printed.
        #
        # THE DIVERGENCE THIS CLOSES. generate_single_logbook_html dropped a
        # contentless row; this renderer did not. Same stored register, two
        # different documents — and THIS is the one the operator emails, so a
        # blank row that the per-logbook PDF refuses was printing on the
        # investor's copy as a certification row for nobody.
        #
        # The rule is now the NAME (device round 6): a row with a card number
        # and no worker was the shape that survived the old any-of-five test
        # and printed. Both renderers, the submit gate and the device all read
        # the one definition below, so all four moved together.
        #
        # THE DEFINITION IS NOT REWRITTEN HERE. It is read from
        # _SUBMIT_ROW_CONTENT_RULES, the rule #125 already enforces at submit,
        # through _row_has, the module-level mirror of this file's own `has()`.
        # One definition, three consumers: the submit gate, the per-logbook PDF
        # and this report. That is the whole point — this pair has drifted
        # twice before (weather, then drawings_on_site).
        _osha_content_fields = _SUBMIT_ROW_CONTENT_RULES["osha_log"][1]

        osha_rows = ""
        for e in osha_entries:
            if not isinstance(e, dict):
                continue
            if not any(_row_has(e, _k) for _k in _osha_content_fields):
                continue      # names nobody — including the untouched seed
            review_cell = osha_review_cell(
                e, review_by_key, known_cards, known_workers)
            # name/company are short-entry; card_number/expiration are identifiers
            # (rendered raw, no capitalization).
            osha_rows += (
                f'<tr><td {TD}>{_capitalize_first(e.get("worker_name", ""))}</td>'
                f'<td {TD}>{_capitalize_first(e.get("company", ""))}</td>'
                f'<td {TD}>{_osha_type_cell(e) or "&mdash;"}</td>'
                f'<td {TD}>{e.get("card_number", "") or "&mdash;"}</td>'
                f'<td {TD}>{e.get("expiration", "") or "&mdash;"}</td>'
                f'<td {TD}>{"&#10003;" if e.get("signed") else "&mdash;"}</td>'
                f'<td {TD}>{review_cell}</td></tr>'
            )

        osha_sig = render_signature_html(osha_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
        osha_html = (
            section_title("OSHA / SST Certification Log")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Worker</th><th {TH}>Company</th><th {TH}>Cert Type</th>'
              f'<th {TH}>Card #</th><th {TH}>Expiration</th><th {TH}>Signed</th>'
              f'<th {TH}>Review</th></tr>'
            + (osha_rows or f'<tr><td colspan="7" {TD}>No certifications recorded</td></tr>')
            + '</table>'
            # ABOVE the signature: the claim, then the name that makes it.
            + OSHA_LOG_ATTESTATION_HTML
            + osha_sig
        )

    # ==========================================================
    #  HOT WORK PERMIT
    # ==========================================================
    hot_work_html = ""
    hw_lb = _filed_log(logbooks, "hot_work")
    if hw_lb:
        d = hw_lb.get("data") or {}

        # Full precaution list so an UNconfirmed item reads "Not recorded", never
        # a silent "No" (sparse-map convention). Labels mirror the editor's
        # PRECAUTION_ITEMS.
        HW_PRECAUTIONS = [
            ("area_cleared", "Area Cleared of Combustibles (35 ft)"),
            ("fire_extinguisher_present", "Fire Extinguisher Present"),
            ("sprinklers_operational", "Sprinklers Operational"),
            ("combustibles_covered", "Combustibles Covered / Protected"),
            ("fire_watch_assigned", "Fire Watch Assigned"),
            ("ventilation_adequate", "Ventilation Adequate"),
            ("permit_posted", "Permit Posted at Location"),
        ]
        precautions = d.get("precautions") or {}
        prec_rows = ""
        for key, label in HW_PRECAUTIONS:
            if key in precautions:
                val = "Yes" if precautions.get(key) else "No"
            else:
                val = "&mdash; Not recorded"
            prec_rows += f'<tr><td {TD}>{label}</td><td {TD}>{val}</td></tr>'

        # The editor captures NO real fire-watch end time — fire_watch_end_time is
        # derived as work-end + 30 min. FDNY can require a 60-min watch, so this is
        # labeled as a computed DEFAULT, never asserted as a recorded watch-until.
        fw_end = d.get("fire_watch_end_time") or ""
        fw_end_display = (
            f'{fw_end} <span style="color:#94a3b8;">(default: work end + 30 min)</span>'
            if fw_end else "&mdash;"
        )

        # work_type is an enum label; location / worker / fire-watch names are
        # short-entry; worker_cert_number is an identifier (raw); times as-is.
        hot_work_html = (
            section_title("Hot Work Permit")
            + info_box(
                f'<strong style="color:#0A1929;">Work Type:</strong> {d.get("work_type") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Location:</strong> {_capitalize_first(d.get("location", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Worker:</strong> {_capitalize_first(d.get("worker_name", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Worker Cert #:</strong> {d.get("worker_cert_number") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Start &ndash; End:</strong> {d.get("start_time") or "N/A"} &ndash; {d.get("end_time") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Fire Watch:</strong> {_capitalize_first(d.get("fire_watch_name", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Fire Watch Until:</strong> {fw_end_display}'
            )
            + sub_title("Pre-Work Precautions")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Precaution</th><th {TH}>Confirmed</th></tr>'
            + prec_rows
            + '</table>'
            + render_signature_html(hw_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
        )

    # ==========================================================
    #  CRANE OPERATIONS
    # ==========================================================
    crane_html = ""
    crane_lb = _filed_log(logbooks, "crane_operations")
    if crane_lb:
        d = crane_lb.get("data") or {}

        # Full list so an unconfirmed item reads "Not recorded", never a silent
        # "No" (sparse-map convention). Labels mirror the editor's checklist.
        CRANE_PREOP = [
            ("wire_ropes", "Wire Ropes Inspected"),
            ("hooks_latches", "Hooks & Latches Secure"),
            ("brakes", "Brakes Functional"),
            ("outriggers", "Outriggers Deployed"),
            ("load_chart", "Load Chart Available"),
            ("boom_condition", "Boom Condition OK"),
            ("anti_two_block", "Anti Two-Block Device"),
            ("fire_extinguisher", "Fire Extinguisher Present"),
            ("signals_reviewed", "Signals Reviewed"),
            ("area_barricaded", "Area Barricaded"),
            ("wind_speed_checked", "Wind Speed Checked"),
            ("power_lines_clear", "Power Lines Clear"),
            ("load_weight_known", "Load Weight Known"),
            ("rigging_inspected", "Rigging Inspected"),
            ("swing_radius_clear", "Swing Radius Clear"),
        ]
        checklist = d.get("pre_operation_checklist") or {}
        preop_rows = ""
        for key, label in CRANE_PREOP:
            if key in checklist:
                val = "Yes" if checklist.get(key) else "No"
            else:
                val = "&mdash; Not recorded"
            preop_rows += f'<tr><td {TD}>{label}</td><td {TD}>{val}</td></tr>'

        load_entries = d.get("load_entries") or []
        load_rows = ""
        for le in load_entries:
            if not any(str(le.get(k, "")).strip() for k in ("time", "description", "load_weight", "radius")):
                continue
            load_rows += (
                f'<tr><td {TD}>{le.get("time", "") or "&mdash;"}</td>'
                f'<td {TD}>{_capitalize_first(le.get("description", "")) or "&mdash;"}</td>'
                f'<td {TD}>{le.get("load_weight", "") or "&mdash;"}</td>'
                f'<td {TD}>{le.get("radius", "") or "&mdash;"}</td></tr>'
            )

        # crane_type / operator_name are short-entry; crane_id / operator_license
        # are identifiers (raw). load_weight & radius are unit-less strings as
        # entered by the operator (units are a logged capture gap).
        crane_html = (
            section_title("Crane Operations")
            + info_box(
                f'<strong style="color:#0A1929;">Crane Type:</strong> {_capitalize_first(d.get("crane_type", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Crane ID:</strong> {d.get("crane_id") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Operator:</strong> {_capitalize_first(d.get("operator_name", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Operator License:</strong> {d.get("operator_license") or "N/A"}'
            )
            + sub_title("Pre-Operation Checklist")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Item</th><th {TH}>Confirmed</th></tr>'
            + preop_rows
            + '</table>'
            + sub_title("Lift Log")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Time</th><th {TH}>Description</th><th {TH}>Load Weight</th><th {TH}>Radius</th></tr>'
            + (load_rows or f'<tr><td colspan="4" {TD}>No lifts recorded</td></tr>')
            + '</table>'
            + render_signature_html(crane_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
        )

    # ==========================================================
    #  EXCAVATION MONITORING
    # ==========================================================
    exc_html = ""
    exc_lb = _filed_log(logbooks, "excavation_monitoring")
    if exc_lb:
        d = exc_lb.get("data") or {}

        # Vibration: the over-threshold flag is only meaningful with an actual
        # reading. Without both values it is "Not recorded", NOT a false "Within".
        v_thr = str(d.get("vibration_threshold") or "").strip()
        v_cur = str(d.get("vibration_current") or "").strip()
        if v_thr and v_cur:
            over_display = (
                '<span style="color:#b45309;font-weight:600;">&#9888; Over threshold</span>'
                if d.get("vibration_over_threshold") else "Within threshold"
            )
        else:
            over_display = "&mdash; Not recorded"

        # Adjacent-structure monitoring points. Units and per-reading timestamps
        # are NOT captured (tracked in followups), so headers imply no unit and
        # there is NO time column — readings render exactly as entered, and a
        # reading without a timestamp shows without one rather than inventing it.
        buildings = d.get("adjacent_buildings") or []
        bld_rows = ""
        for b in buildings:
            # The owner rule, same as the per-logbook PDF: a reading with no
            # address names no building.
            if not str(b.get("address", "")).strip():
                continue
            bld_rows += (
                f'<tr><td {TD}>{_capitalize_first(b.get("address", "")) or "&mdash;"}</td>'
                f'<td {TD}>{b.get("baseline_reading", "") or "&mdash;"}</td>'
                f'<td {TD}>{b.get("current_reading", "") or "&mdash;"}</td>'
                f'<td {TD}>{b.get("delta", "") or "&mdash;"}</td></tr>'
            )

        # soil_type / protection_system are enums (as-is); excavation_depth is a
        # raw number (unit not captured); groundwater / atmospheric are real
        # booleans (seeded false, always present) → Yes/No.
        exc_html = (
            section_title("Excavation Monitoring")
            + info_box(
                f'<strong style="color:#0A1929;">Excavation Depth:</strong> {d.get("excavation_depth") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Soil Type:</strong> {d.get("soil_type") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Protection System:</strong> {d.get("protection_system") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Groundwater Observed:</strong> {"Yes" if d.get("groundwater_observed") else "No"}<br />'
                f'<strong style="color:#0A1929;">Atmospheric Testing:</strong> {"Yes" if d.get("atmospheric_testing") else "No"}'
            )
            + sub_title("Vibration")
            + info_box(
                f'<strong style="color:#0A1929;">Threshold:</strong> {v_thr or "&mdash; Not recorded"}<br />'
                f'<strong style="color:#0A1929;">Current:</strong> {v_cur or "&mdash; Not recorded"}<br />'
                f'<strong style="color:#0A1929;">Status:</strong> {over_display}'
            )
            + sub_title("Adjacent-Structure Monitoring Points")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Location</th><th {TH}>Baseline</th><th {TH}>Current</th><th {TH}>Movement (&Delta;)</th></tr>'
            + (bld_rows or f'<tr><td colspan="4" {TD}>No monitoring points recorded</td></tr>')
            + '</table>'
            + render_signature_html(exc_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
        )

    # ==========================================================
    #  FALL PROTECTION EQUIPMENT
    # ==========================================================
    fp_html = ""
    fp_lb = _filed_log(logbooks, "fall_protection")
    if fp_lb:
        _fp_rows = ""
        for r in ((fp_lb.get("data") or {}).get("activities") or []):
            if not isinstance(r, dict):
                continue
            # The Group 1 rule. A nameless row here claims a man's fall-arrest
            # equipment was inspected without saying whose.
            if not str(r.get("worker_name") or "").strip():
                continue
            _res = str(r.get("result") or "").strip()
            if _res == "Pass":
                _res_cell = '<span style="color:#15803d;font-weight:600;">Pass</span>'
            elif _res:
                # Fail and "Removed from service" are different findings and
                # neither is collapsed into the other.
                _res_cell = ('<span style="color:#b91c1c;font-weight:700;">'
                             + _capitalize_first(_res) + '</span>')
            else:
                _res_cell = "&mdash; Not recorded"
            _imp = r.get("impact_loaded")
            _imp_cell = ("&mdash; Not recorded" if _imp is None
                         else ("Yes" if _imp else "No"))
            _fp_rows += (
                f'<tr><td {TD}>{_capitalize_first(r.get("worker_name", ""))}</td>'
                f'<td {TD}>{_capitalize_first(r.get("company", ""))}</td>'
                f'<td {TD}>{_capitalize_first(r.get("equipment_type", ""))}</td>'
                f'<td {TD}>{r.get("equipment_id", "") or "&mdash;"}</td>'
                f'<td {TD}>{r.get("manufacture_date", "") or "&mdash;"}</td>'
                f'<td {TD}>{_res_cell}</td>'
                f'<td {TD}>{_imp_cell}</td>'
                f'<td {TD}>{_sentence_case(r.get("defect_found") or "") or "&mdash;"}</td>'
                f'<td {TD}>{_sentence_case(r.get("action_taken") or "") or "&mdash;"}</td></tr>'
            )
        fp_html = (
            section_title("Fall Protection Equipment")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Worker</th><th {TH}>Company</th><th {TH}>Equipment</th>'
              f'<th {TH}>ID / Serial</th><th {TH}>Mfg Date</th><th {TH}>Result</th>'
              f'<th {TH}>Impact Loaded</th><th {TH}>Defect</th><th {TH}>Action Taken</th></tr>'
            + (_fp_rows or f'<tr><td colspan="9" {TD}>No inspections recorded</td></tr>')
            + '</table>'
            + render_signature_html(fp_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
            # THIS REPORT GOES TO INVESTORS AND LENDERS, and it is where a
            # reader is most likely to mistake this section for a required
            # filing. One sentence, on the section, saying what it is.
            + '<p style="color:#64748b;font-size:11px;line-height:1.6;margin:8px 0 0;">'
            + FALL_PROTECTION_NOTICE + '</p>'
        )

    # ==========================================================
    #  SCAFFOLD MAINTENANCE INSPECTION
    # ==========================================================
    scaffold_html = ""
    scaffold_lb = _filed_log(logbooks, "scaffold_maintenance")
    if scaffold_lb:
        d = scaffold_lb.get("data") or {}
        gi = d.get("general_info") or {}
        answers = d.get("answers") or {}

        # 19 inspection questions, exact DOB-form wording from the editor. Sparse:
        # an unanswered question reads "Not recorded", never a silent "No"; an
        # explicit N/A stays N/A. (general_info.drawings_on_site is a dead
        # duplicate of the answers question of the same key — only the answer is
        # rendered.)
        SCAFFOLD_QUESTIONS = [
            ("signs_on_parapets", "Are the signs on the parapets?"),
            ("base_plates_mudsills", "Are the base plates and mudsills secured?"),
            ("scaffold_pins_bolts", "Are the scaffold pins and bolts installed?"),
            ("legs_poles_plumb", "Are the legs and poles plumb, braced and not displaced?"),
            ("tie_ins_spaced", "Are tie-ins correctly spaced, properly secured and the correct amount?"),
            ("cross_braces", "Are cross braces fully attached, not bent, and not missing?"),
            ("pipe_clamps_tight", "Are pipe clamps tight?"),
            ("window_jacks_tight", "Are window jacks tight?"),
            ("planks_secured", "Are all the planks secured?"),
            ("decking_planks_condition", "Are decking and planks in good condition?"),
            ("deck_fully_planked", "Is deck fully planked?"),
            ("gaps_open_spaces", "Are there gaps or open spaces on decking?"),
            ("guardrails_toe_boards", "Are the guardrails and toe boards secured at all places where required?"),
            ("netting_extension", "Is the netting extension of full length and height?"),
            ("netting_secured", "Is the netting secured?"),
            ("parapet_height", "Is the parapet the proper height and secured?"),
            ("lights_working", "Are the lights working?"),
            ("deck_clean", "Is the deck clean and free of debris?"),
            ("drawings_on_site", "Drawings on site for inspection?"),
        ]
        q_rows = ""
        for key, label in SCAFFOLD_QUESTIONS:
            ans = answers.get(key)
            val = ans if (key in answers and ans) else "&mdash; Not recorded"
            q_rows += f'<tr><td {TD}>{label}</td><td {TD}>{val}</td></tr>'

        # scaffold_erector / renters_name are short-entry; permit_number / phone
        # are identifiers; dates & counts render raw; shed_type is an enum.
        scaffold_html = (
            section_title("Scaffold Maintenance Inspection")
            + info_box(
                f'<strong style="color:#0A1929;">Scaffold Erector:</strong> {_capitalize_first(gi.get("scaffold_erector", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Renter:</strong> {_capitalize_first(gi.get("renters_name", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Permit #:</strong> {gi.get("permit_number") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Phone #:</strong> {gi.get("phone") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Installation Date:</strong> {gi.get("installation_date") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Expiration:</strong> {gi.get("expiration_date") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Scaffold Height:</strong> {gi.get("scaffold_height") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Platforms Decked:</strong> {gi.get("num_platforms") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Shed Type:</strong> {gi.get("shed_type") or "N/A"}'
            )
            + sub_title("Inspection Checklist")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Question</th><th {TH}>Answer</th></tr>'
            + q_rows
            + '</table>'
            + render_signature_html(scaffold_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
        )

    # ==========================================================
    #  SUBCONTRACTOR SAFETY ORIENTATION  (aggregate — one doc per worker)
    # ==========================================================
    # LL196: subcontractor orientation is FIRST-TIME-on-project only (not daily).
    # The coverage question is therefore: has each worker currently ON SITE ever
    # been oriented on THIS project? Rendered whenever anyone checked in today,
    # even if no orientation was filed today — the point is catching an
    # un-oriented worker on a day nobody new was oriented.
    orientation_today = [l for l in logbooks if l.get("log_type") == "subcontractor_orientation"]
    orientation_html = ""
    if checkin_count > 0 or orientation_today:
        def _norm_name(v):
            return " ".join(str(v or "").split()).lower()

        # ON SITE = checked in today AND not checked out, THIS project (checkins is
        # already scoped to project_id + this date's EST window). Mirrors the app's
        # canonical on_site_query (status == "checked_in"); deduped to DISTINCT
        # workers so N counts people, not check-in rows.
        on_site = {}
        for c in checkins:
            if c.get("status") != "checked_in":
                continue
            rid = str(c.get("worker_id") or "")
            rname = _norm_name(c.get("worker_name"))
            key = rid or (f"name:{rname}" if rname else "")
            if key:
                on_site.setdefault(key, c)
        n_onsite = len(on_site)

        # Every orientation doc for THIS project across ALL dates — a worker
        # oriented weeks ago counts as covered. Manual entries mint a synthetic
        # worker_id, so match on worker_id OR normalized name (heuristic —
        # collisions/spelling can skew it; tracked in followups).
        all_orientations = await db.logbooks.find(
            {"project_id": project_id, "log_type": "subcontractor_orientation",
             "is_deleted": {"$ne": True}},
            {"data.worker_id": 1, "data.worker_name": 1},
        ).to_list(5000)
        oriented_ids, oriented_names = set(), set()
        for o in all_orientations:
            od = o.get("data") or {}
            if od.get("worker_id"):
                oriented_ids.add(str(od.get("worker_id")))
            if od.get("worker_name"):
                oriented_names.add(_norm_name(od.get("worker_name")))

        n_covered = 0
        for c in on_site.values():
            rid = str(c.get("worker_id") or "")
            rname = _norm_name(c.get("worker_name"))
            if (rid and rid in oriented_ids) or (rname and rname in oriented_names):
                n_covered += 1
        coverage_gap = max(0, n_onsite - n_covered)

        if n_onsite == 0:
            coverage_value = "No workers currently on site"
        else:
            coverage_value = f"{n_covered} of {n_onsite} on-site workers"
            if coverage_gap > 0:
                coverage_value += (
                    f' &nbsp;<span style="color:#b91c1c;font-weight:700;">'
                    f'&#9888; {coverage_gap} on-site worker(s) with no orientation on file</span>'
                )

        # Today's FILED orientation records — who was oriented today (often empty;
        # that is normal and correct, not a gap).
        n_today = len(orientation_today)
        n_signed = 0
        orient_rows = ""
        for doc in orientation_today:
            od = doc.get("data") or {}
            name = _capitalize_first(od.get("worker_name", "")) or "&mdash;"
            trade = _capitalize_first(od.get("worker_trade", ""))
            company = _capitalize_first(od.get("worker_company", ""))
            trade_company = " &bull; ".join([p for p in (trade, company) if p]) or "&mdash;"
            # Orientation date: completed_at (ISO) preferred, else the doc's date;
            # neither present renders "Not recorded", not a fabricated date.
            completed = od.get("completed_at") or ""
            orient_date = (str(completed)[:10] if completed else doc.get("date")) or "&mdash; Not recorded"
            # cp_name is the trainer's attestation (a competent person delivered
            # the orientation) — top-level on the doc, short-entry.
            cp = _capitalize_first(doc.get("cp_name", "")) or "&mdash; Not recorded"
            # LOAD-BEARING HONESTY: worker_signature is hardcoded null on manual
            # entries. Surface UNSIGNED so an unattested acknowledgment is never
            # presented as complete (same failure class as a replayed CP signature).
            if od.get("worker_signature"):
                sig_cell = '<span style="color:#15803d;font-weight:600;">Signed</span>'
                n_signed += 1
            else:
                sig_cell = '<span style="color:#b91c1c;font-weight:700;">UNSIGNED</span>'
            orient_rows += (
                f'<tr><td {TD}>{name}</td>'
                f'<td {TD}>{trade_company}</td>'
                f'<td {TD}>{orient_date}</td>'
                f'<td {TD}>{cp}</td>'
                f'<td {TD}>{sig_cell}</td></tr>'
            )

        signed_line = (
            bold_para("Worker acknowledgments signed", f"{n_signed} of {n_today} filed today")
            if n_today else ""
        )
        # ORIENTED TODAY IS OFTEN EMPTY, AND THAT IS NOT A FINDING.
        #
        # An orientation is due ONCE PER WORKER, before he starts. Most days
        # bring no new workers, so most days have nothing to put in this table
        # — and it printed anyway, five headers over one cell reading "No
        # orientations filed today". A section that reports nothing on a
        # compliance document teaches a reader to skip it, and the row beneath
        # it is the one that matters.
        #
        # THE COVERAGE LINE IS NOT SUPPRESSED WITH IT. "2 on-site workers with
        # no orientation on file" is the LL196 first-timer check, and it is a
        # real deficiency on exactly the days nobody was oriented — which is
        # why the section renders on any day somebody checked in, not only when
        # an orientation was filed. Dropping the whole section on a quiet day
        # would delete the warning along with the empty table.
        oriented_today_html = (
            sub_title("Oriented Today")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Worker</th><th {TH}>Trade / Company</th>'
              f'<th {TH}>Orientation Date</th><th {TH}>Conducted By (CP)</th>'
              f'<th {TH}>Worker Signature</th></tr>'
            + orient_rows
            + '</table>'
        ) if orient_rows else ""
        orientation_html = (
            section_title("Subcontractor Safety Orientation")
            + bold_para("First-time orientation on file", coverage_value)
            + signed_line
            + oriented_today_html
        )

    # ==========================================================
    #  SSC DAILY SAFETY LOG
    # ==========================================================
    ssc_html = ""
    ssc_lb = _filed_log(logbooks, "ssc_daily_safety_log")
    if ssc_lb:
        d = ssc_lb.get("data") or {}

        # Two-state ToggleRows (seeded false, always present) → Yes/No as captured.
        SSC_FLAGS = [
            ("incidents_reported", "Incidents Reported"),
            ("safety_meetings_held", "Safety Meetings Held"),
            ("fire_protection_in_place", "Fire Protection in Place"),
            ("housekeeping_satisfactory", "Housekeeping Satisfactory"),
            ("ppe_compliance", "PPE Compliance"),
        ]
        flag_rows = ""
        for key, label in SSC_FLAGS:
            flag_rows += f'<tr><td {TD}>{label}</td><td {TD}>{"Yes" if d.get(key) else "No"}</td></tr>'

        # Prose (sentence-case); empty renders "Not recorded", never an asserted
        # "none" that could read as a negative finding the CP did not make.
        def _ssc_prose(v):
            return (_sentence_case(v) if v else "") or "&mdash; Not recorded"

        incident_line = (
            bold_para("Incident Details", _ssc_prose(d.get("incident_details")))
            if d.get("incidents_reported") else ""
        )

        ssc_html = (
            section_title("SSC Daily Safety Log")
            + info_box(
                f'<strong style="color:#0A1929;">Project Address:</strong> {_capitalize_first(d.get("project_address", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Site Safety Plan #:</strong> {d.get("ssp_number") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Weather:</strong> {_display_weather(d)}<br />'
                f'<strong style="color:#0A1929;">Workers on Site:</strong> {d.get("workers_on_site_count") or "N/A"}'
            )
            + sub_title("Compliance")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Item</th><th {TH}>Status</th></tr>'
            + flag_rows
            + '</table>'
            # A rendered "No" here may be an untouched default, not a deliberate
            # negative finding — qualify it so a bare "No" is never read as an
            # affirmative safety-violation attestation on a DOB record.
            + '<p style="color:#94a3b8;font-size:11px;font-style:italic;margin:2px 0 0;">'
              'Compliance items default to "No" if not explicitly set by the reviewer.</p>'
            + sub_title("Narrative")
            + bold_para("Site Conditions", _ssc_prose(d.get("site_conditions")))
            + bold_para("Safety Violations Observed", _ssc_prose(d.get("safety_violations_observed")))
            + bold_para("Corrective Actions Taken", _ssc_prose(d.get("corrective_actions_taken")))
            + incident_line
            + render_signature_html(ssc_lb.get("cp_signature"), "SSC / SSM Signature", show_affirmation=False)
        )

    # ==========================================================
    #  CONCRETE OPERATIONS
    # ==========================================================
    concrete_html = ""
    concrete_lb = _filed_log(logbooks, "concrete_operations")
    if concrete_lb:
        d = concrete_lb.get("data") or {}

        FORMWORK_ITEMS = [
            ("shores_plumb", "Shores Plumb"),
            ("bracing_adequate", "Bracing Adequate"),
            ("formwork_clean", "Formwork Clean"),
            ("no_gaps", "No Gaps"),
        ]
        formwork = d.get("formwork_checklist") or {}
        formwork_rows = ""
        for key, label in FORMWORK_ITEMS:
            if key in formwork:
                val = "Yes" if formwork.get(key) else "No"
            else:
                val = "&mdash; Not recorded"
            formwork_rows += f'<tr><td {TD}>{label}</td><td {TD}>{val}</td></tr>'

        slump_rows = ""
        for st in (d.get("slump_tests") or []):
            t = str(st.get("time", "")).strip()
            v = str(st.get("value", "")).strip()
            p = st.get("pass")
            if not t and not v and p is None:
                continue
            # pass is TRI-STATE: null → Not recorded, never "Fail".
            if p is True:
                result = '<span style="color:#15803d;font-weight:600;">Pass</span>'
            elif p is False:
                result = '<span style="color:#b91c1c;font-weight:600;">Fail</span>'
            else:
                result = "&mdash; Not recorded"
            slump_rows += (
                f'<tr><td {TD}>{t or "&mdash;"}</td>'
                f'<td {TD}>{v or "&mdash;"}</td>'
                f'<td {TD}>{result}</td></tr>'
            )

        # pour_location / concrete_supplier short-entry; mix_design an identifier;
        # volume_ordered & temperature raw (unit-less as entered); weather an enum.
        concrete_html = (
            section_title("Concrete Operations")
            + info_box(
                f'<strong style="color:#0A1929;">Pour Location:</strong> {_capitalize_first(d.get("pour_location", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Supplier:</strong> {_capitalize_first(d.get("concrete_supplier", "")) or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Mix Design:</strong> {d.get("mix_design") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Volume Ordered:</strong> {d.get("volume_ordered") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Weather:</strong> {d.get("weather_conditions") or "N/A"}<br />'
                f'<strong style="color:#0A1929;">Temperature:</strong> {d.get("temperature") or "N/A"}'
            )
            + sub_title("Slump Tests")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Time</th><th {TH}>Slump</th><th {TH}>Result</th></tr>'
            + (slump_rows or f'<tr><td colspan="3" {TD}>No slump tests recorded</td></tr>')
            + '</table>'
            + sub_title("Formwork Inspection")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + f'<tr><th {TH}>Item</th><th {TH}>Confirmed</th></tr>'
            + formwork_rows
            + '</table>'
            + render_signature_html(concrete_lb.get("cp_signature"), "CP Signature", show_affirmation=False)
        )

    # ==========================================================
    #  ADDITIONAL LOGBOOKS (new types: SSC, concrete, crane, hot work, excavation)
    # ==========================================================
    # EVERY TYPE WITH A DEDICATED SECTION ABOVE MUST BE LISTED HERE, or it
    # prints twice: once under its own heading and again below as an
    # "Additional Logbook". fall_protection and site_superintendent_log had
    # both fallen through -- the second is the BC 3301.13.13 log, so the
    # duplicate landed on a statutory record a CP signs.
    #
    # Nothing about a duplicated section looks like an error: no crash, no
    # warning, just a report that mentions something twice. That is why
    # test_report_no_double_render.py compares this set against the
    # _filed_log(...) lookups by parsing BOTH, rather than pinning the two
    # types that happened to be wrong. Add a section, and that test tells you
    # to add it here.
    handled_types = {"daily_jobsite", "toolbox_talk", "preshift_signin", "scaffold_maintenance",
                     "subcontractor_orientation", "osha_log", "hot_work", "crane_operations",
                     "excavation_monitoring", "ssc_daily_safety_log", "concrete_operations",
                     "fall_protection", "site_superintendent_log"}
    additional_logbooks_html = ""
    for logbook in logbooks:
        lt = logbook.get("log_type", "")
        if lt in handled_types:
            continue
        d = logbook.get("data", {})
        label = lt.replace("_", " ").title()
        # Build key-value rows from the data dict
        data_rows = ""
        for k, v in d.items():
            if isinstance(v, (dict, list)):
                if isinstance(v, list):
                    v_str = ", ".join(str(item) if not isinstance(item, dict) else str(item) for item in v[:10])
                else:
                    # `if iv` dropped False and 0; and a True printed as
                    # `flag: True`. The bool branch below is the correct
                    # rendering and was one level out of reach.
                    v_str = ", ".join(
                        f"{ik}: {answer_label(iv)}" for ik, iv in v.items()
                        if isinstance(iv, bool) or iv)
            elif isinstance(v, bool):
                v_str = "Yes" if v else "No"
            else:
                v_str = str(v) if v else ""
            if v_str:
                field_label = k.replace("_", " ").title()
                data_rows += f'<tr><td {TD} style="font-weight:600;width:35%;padding:10px 12px;border-bottom:1px solid #e2e8f0;color:#334155;">{field_label}</td><td {TD}>{v_str}</td></tr>'

        sig_html = render_signature_html(logbook.get("cp_signature"), "Signature", show_affirmation=False)
        additional_logbooks_html += (
            section_title(f"{label}")
            + '<table cellpadding="0" cellspacing="0" border="0" width="100%" '
              'style="border-collapse:collapse;margin:8px 0 0 0;font-size:13px;">'
            + (data_rows or f'<tr><td {TD}>No data recorded</td></tr>')
            + '</table>'
            + sig_html
        )

    # ==========================================================
    #  EVERY DOCUMENT ON ITS OWN PAGE
    # ==========================================================
    #
    # There was exactly ONE page break in this report -- between the investor
    # cover and everything after it -- and page 2 onward ran together. A Tool
    # Box Talk ended four lines into a sheet and the Pre-Shift Sign-In began on
    # the fifth; an Activity Details table split across the fold with its
    # header on one page and half its crews on the next.
    #
    # THESE ARE SEPARATE FILED DOCUMENTS. An inspector asks for one of them by
    # name and a lender is handed another; a printed record that has to be cut
    # apart with a ruler to separate two statutory logs is not a record of
    # either. So each section starts a sheet.
    #
    # THE BREAK GOES *BETWEEN*, NEVER AFTER EACH. A break after the last
    # section ends the PDF on a blank sheet, and a blank final page on a
    # compliance document reads as a page somebody removed.
    #
    # AN UNFILED LOG IS NOT A PAGE. A section with no document behind it
    # renders "" and is dropped before the join, so a three-document day is
    # three sheets and not sixteen -- thirteen of them blank, each looking like
    # a filing that went missing.
    _SECTIONS = (
        progress_html, jobsite_html, cs_html, toolbox_html, preshift_html,
        site_html, osha_html, hot_work_html, crane_html, exc_html,
        scaffold_html, fp_html, orientation_html, ssc_html, concrete_html,
        additional_logbooks_html,
    )
    # page-break-inside ON THE WRAPPER, which is what stops a table splitting
    # across the fold.
    #
    # THE CLAIM THAT USED TO BE HERE WAS WRONG, AND IT NEVER HELD. It read:
    # "A section taller than a page cannot honour it, and WeasyPrint drops the
    # request rather than leaving the sheet blank -- which is what makes this
    # safe on a sixty-man pre-shift sheet." WeasyPrint does not drop it. It
    # RELOCATES the block to a fresh sheet first, and only then splits it
    # because it has nowhere else to go. The blank sheet is exactly what you
    # get.
    #
    # MEASURED, on this renderer, on production data, in a container where
    # WeasyPrint loads (2026-09-05):
    #
    #   2026-08-25   first section  461px   page 1 ends y=265   7 pages
    #   2026-09-04   first section  779px   page 1 ends y=265  12 pages
    #   2026-08-31   first section ~1715px  page 1 ends y=426   9 pages
    #
    # A4 at 12mm margins gives a content box of y 45..1078. The 08-31 section
    # is far taller than a whole page -- the exact case the old comment called
    # safe -- and it still began on page 2. Page 1 carried the header and the
    # summary row and nothing else, on all three.
    #
    # AND THIS WRAPPER IS ONLY HALF OF IT. Ablating one rule at a time on the
    # same rendered HTML: removing `.doc-section { break-inside: avoid }` alone
    # changed nothing on any of the three days. Removing the unqualified
    # `tr { page-break-inside: avoid }` from the print block alone moved the
    # light day's section back onto page 1 (page-1 bottom 265px -> 794px, 7
    # pages -> 6), because that rule matches the outer layout table's single
    # CONTENT row -- the one holding the entire body. Removing both moved all
    # three. So the wrapper is load-bearing on a photo-heavy day and irrelevant
    # on a light one, and the `tr` rule is the dominant cause.
    #
    # THE FIX IS THE `tr.shell` EXEMPTION in the print block BELOW, matching
    # the scoping the per-logbook PDF already carries. The wrapper below stays:
    # it is the rule that keeps a section together when a section CAN fit, and
    # on a photo-heavy day it is load-bearing.
    #
    # WHY IT SURVIVED: no check in this repo renders a page. Every
    # page-geometry test asserts the CSS a renderer emits, so a false claim
    # about what WeasyPrint does with that CSS sits next to a suite that
    # cannot contradict it. See docs/audits/check-harness.md section 8.
    sections_html = '<div style="page-break-after:always;"></div>'.join(
        f'<div class="doc-section" style="page-break-inside:avoid;">{_s}</div>'
        for _s in _SECTIONS if _s
    )

    # ==========================================================
    #  FINAL HTML ASSEMBLY  (email-safe, table-based)
    # ==========================================================
    # THE ZONE IS PART OF THE FACT. This printed a UTC clock with the word
    # UTC beside it -- not wrong, but the only Eastern-looking number on a
    # New York document, sitting four hours from every other time on it.
    # `eastern_datetime` carries its own zone, so the literal goes with it.
    gen_time = eastern_datetime(datetime.now(timezone.utc))
    font = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif"

    html = f"""<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<meta name="color-scheme" content="light only" />
<meta name="supported-color-schemes" content="light only" />
<title>Daily Construction Report - {project_name}</title>
<!--[if mso]><style>table, td {{font-family: Arial, sans-serif !important;}}</style><![endif]-->
<style>
  :root {{ color-scheme: light only; }}
  body, .body {{ background-color: #f0f4f8 !important; }}
  u + .body {{ background-color: #f0f4f8 !important; }}
  [data-ogsc] .wrapper {{ background-color: #ffffff !important; }}
  [data-ogsc] body {{ background-color: #f0f4f8 !important; }}
  @media (prefers-color-scheme: dark) {{
    body, .body {{ background-color: #f0f4f8 !important; }}
    .wrapper {{ background-color: #ffffff !important; }}
    .content-cell {{ background-color: #ffffff !important; color: #1a2332 !important; }}
  }}

  /* PRINT / PDF. ONE HTML SERVES TWO MEDIA and they want opposite things.
     The wrapper is width="680" with max-width:680px because that is the
     right column for an email client. The SAME string is handed to
     WeasyPrint (get_combined_report_pdf), where 680px sits on a ~794px A4
     page and leaves a dead strip down the right — which is what made the
     Activity Details table stop mid-page and read, on a phone, as though
     the document had been trimmed.

     Email clients ignore @media print, so releasing the width here costs
     the email nothing. */
  @page {{ size: A4; margin: 12mm; }}
  @media print {{
    .wrapper {{ width: 100% !important; max-width: 100% !important; }}
    body, .body {{ background-color: #ffffff !important; }}

    /* THE REST OF THE LEVER. The block released the width and stopped, and
       every typographic decision below is one an EMAIL CLIENT must not be
       asked to make -- these rules exist only for the sheet of paper.

       A HEADING MUST NOT BE THE LAST THING ON A PAGE. Every section now
       starts its own sheet, but the sub-heads inside one do not, and
       "Activity Details" alone at the foot of a page with its table
       overleaf is the shape a reader takes for a truncated document. */
    h2, h3, .doc-section-title {{
      page-break-after: avoid; break-after: avoid-page;
    }}

    /* THE SECTION HEADER IS THE FIRST THING ON ITS SHEET, so the 40px that
       separates it from the previous section on screen is a dead strip at
       the top of every printed page. Inline styles lose to !important. */
    .doc-section > .doc-section-title:first-child {{ margin-top: 0 !important; }}

    /* NEVER SPLIT A ROW. A man's name on one sheet and his check-in time on
       the next is not a roster entry -- and page-break-inside on the section
       wrapper cannot help a table that is genuinely taller than a page,
       which the pre-shift sheet on a busy day is. */
    tr {{ page-break-inside: avoid; break-inside: avoid; }}

    /* EXCEPT THE FIVE SHELL ROWS, WHICH ARE THE PAGE AND NOT ITS CONTENT.
       This document's outer markup is an email layout: a centring row, then
       the wrapper's header, summary, CONTENT and footer rows. The rule above
       matched the content row -- the one holding every section of the report
       -- so WeasyPrint refused to split it and relocated the whole body to a
       fresh sheet, leaving page 1 carrying the header and the summary and
       nothing else. That is the blank cover.

       Measured on production data, ablating this one rule and nothing else:
       the 2026-08-25 report's first section moved from page 2 back onto page
       1 (page-1 content bottom 265px -> 794px, 7 pages -> 6).

       By class rather than a `> tbody >` combinator, so it does not depend on
       where the parser puts an anonymous tbody. The nested roster and activity
       tables inside the content cell are untouched and still refuse to split,
       which is what the rule was written for. */
    tr.shell {{ page-break-inside: auto; break-inside: auto; }}
    .doc-section {{ break-inside: avoid; }}

    /* One line of a paragraph stranded by itself reads as a fragment. */
    p, li {{ orphans: 3; widows: 3; }}
  }}
</style>
</head>
<body class="body" style="margin:0;padding:0;background-color:#f0f4f8;font-family:{font};-webkit-font-smoothing:antialiased;" bgcolor="#f0f4f8">

<table cellpadding="0" cellspacing="0" border="0" width="100%" bgcolor="#f0f4f8" style="background-color:#f0f4f8;">
<tr class="shell"><td align="center" style="padding:20px 0;">

<table cellpadding="0" cellspacing="0" border="0" width="680" class="wrapper" bgcolor="#ffffff"
  style="background-color:#ffffff;max-width:680px;width:100%;">

  <!-- HEADER -->
  <tr class="shell">
    <td style="background-color:#0A1929;padding:32px 40px;" bgcolor="#0A1929">
      <table cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr><td style="color:rgba(255,255,255,0.5);font-size:10px;letter-spacing:3px;text-transform:uppercase;padding-bottom:16px;font-family:{font};">LEVELOG</td></tr>
        <tr><td style="color:#ffffff;font-size:22px;font-weight:600;letter-spacing:0.5px;padding-bottom:4px;font-family:{font};">Daily Construction Report</td></tr>
        <tr><td style="color:rgba(255,255,255,0.7);font-size:13px;font-weight:400;font-family:{font};">{_header_project_line}</td></tr>
      </table>
    </td>
  </tr>

  <!-- SUMMARY ROW -->
  <tr class="shell">
    <td style="background-color:#f8fafc;padding:20px 40px;border-bottom:1px solid #e2e8f0;" bgcolor="#f8fafc">
      <table cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr>
          <td width="50%" valign="top" style="vertical-align:top;">
            <span style="font-size:10px;text-transform:uppercase;letter-spacing:1.5px;color:#64748b;font-weight:600;">DATE</span><br />
            <span style="font-size:15px;color:#0A1929;font-weight:500;">{_pg1_date}</span>
          </td>
          <!-- WORKERS AT THE GATE WAS THE THIRD CELL HERE. It is printed
               again on page 2, where the roster it counts actually appears, so
               on the cover it was a number with nothing under it. The two
               remaining cells widen to fill the row rather than leaving the
               gap the removal would otherwise make. -->
          <td width="50%" valign="top" style="vertical-align:top;">
            <span style="font-size:10px;text-transform:uppercase;letter-spacing:1.5px;color:#64748b;font-weight:600;">ADDRESS</span><br />
            <span style="font-size:15px;color:#0A1929;font-weight:500;">{project_address or 'N/A'}</span>
          </td>
        </tr>
      </table>
      {_amendment_html}
    </td>
  </tr>

  <!-- CONTENT -->
  <tr class="shell">
    <td class="content-cell" style="padding:24px 40px 40px;background-color:#ffffff;color:#1a2332;" bgcolor="#ffffff">
      {sections_html}
    </td>
  </tr>

  <!-- FOOTER -->
  <tr class="shell">
    <td style="background-color:#f8fafc;padding:24px 40px;text-align:center;border-top:1px solid #e2e8f0;" bgcolor="#f8fafc">
      <span style="font-size:11px;color:#94a3b8;">This report was automatically generated on {gen_time}</span><br />
      <span style="font-size:10px;color:#cbd5e1;letter-spacing:3px;text-transform:uppercase;">LEVELOG CONSTRUCTION MANAGEMENT</span>
    </td>
  </tr>

</table>
</td></tr></table>

</body>
</html>"""
    return html

@api_router.get("/reports/project/{project_id}/date/{date}")
async def get_combined_report(project_id: str, date: str, token: Optional[str] = None, current_user = Depends(get_current_user), _proj = Depends(require_project_access)):
    """Generate combined daily report for a project+date."""
    from fastapi.responses import HTMLResponse
    # ADMIN PREVIEW ONLY. The scheduled send calls this with the default False.
    html = await generate_combined_report(
        project_id, date,
        diagnostics=current_user.get("role") in ("admin", "owner"),
    )
    return HTMLResponse(content=html)
@api_router.get("/reports/project/{project_id}/date/{date}/pdf")
async def get_combined_report_pdf(project_id: str, date: str, token: Optional[str] = None, current_user = Depends(get_current_user), _proj = Depends(require_project_access)):
    """Generate combined daily report as downloadable PDF."""
    from fastapi.responses import Response
    html = await generate_combined_report(
        project_id, date,
        diagnostics=current_user.get("role") in ("admin", "owner"),
    )
    try:
        from weasyprint import HTML
        # OFF THE EVENT LOOP -- see the note at the first of these three.
        def _render_pdf(h: str) -> bytes:
            return HTML(string=h).write_pdf()

        pdf_bytes = await asyncio.to_thread(_render_pdf, html)
    except Exception as e:
        logger.error(f"PDF generation failed: {e}")
        raise HTTPException(status_code=500, detail=f"PDF generation failed: {str(e)}")
    
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = (project.get("name", "report") if project else "report").replace(" ", "_")
    filename = f"Levelog_Report_{project_name}_{date}.pdf"
    
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
        },
    )


@api_router.get("/reports/project/{project_id}/preview/{date}")
async def get_report_preview(project_id: str, date: str, current_user = Depends(get_current_user)):
    """Get report preview metadata for a date — shows what has been filled so far (midday check).
    Returns summary of logbooks, checkins, daily log status without full HTML."""
    role = current_user.get("role")
    if role not in ["admin", "owner"]:
        raise HTTPException(status_code=403, detail="Only admins can preview reports")

    project_id_obj = to_query_id(project_id)
    project = await db.projects.find_one({"_id": project_id_obj})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    if role == "admin" and project.get("company_id") != current_user.get("company_id"):
        raise HTTPException(status_code=403, detail="Access denied")

    # Gather all data for the date
    logbooks = await db.logbooks.find({
        "project_id": project_id,
        "date": date,
        "is_deleted": {"$ne": True},
    }).to_list(100)

    # THE DAILY RECORD IS THE CP'S FILED daily_jobsite LOGBOOK, not db.daily_logs.
    #
    # This panel read `daily_logs` -- 92 rows, all written in April 2026 by the
    # operator's own kiosk testing, nothing since. `find_one` returned None every
    # time, so FIVE fields on this panel were constants: subcontractor_count 0,
    # daily_log_worker_count 0, has_daily_log false, and both daily_log_status
    # and daily_log_weather null. The panel reported "Subs 0" on a day with 16
    # men from 5 companies on site.
    #
    # Same collection, same mistake and the same fix as the 285 false compliance
    # flags (#295). daily_jobsite_filter is the ONE definition of the filed daily
    # record, so this panel and the detectors cannot drift apart again.
    _dj = await db.logbooks.find_one(
        daily_jobsite_filter(project_id, start=date, end=date))
    daily_log = as_daily_log_row(_dj) if _dj else None

    day_start, day_end = get_day_range_est(date)
    _day_checkins = {
        "project_id": project_id,
        "check_in_time": {"$gte": day_start, "$lt": day_end},
        "is_deleted": {"$ne": True},
    }
    checkin_count = await db.checkins.count_documents(_day_checkins)

    # COMPANIES ON SITE, FROM THE SAME ROWS THE HEADCOUNT COMES FROM, so the two
    # numbers on this panel cannot disagree about who was here.
    #
    # NOT "subcontractors". The gate records no GC flag -- nothing on a check-in
    # row distinguishes a general contractor's own crew from a sub's -- so the
    # number the data can honestly produce is distinct companies. Calling it
    # subcontractors would put the GC's own men in a subcontractor headcount,
    # which is a different kind of wrong from a miscount.
    #
    # Case and whitespace are not identity: `_norm_key`'s comment records that a
    # doubled space already printed the same man twice on a production pre-shift
    # sheet. A row naming no company is dropped rather than counted as one --
    # an unnamed company is a gap, and counting it makes the gap look like a fact.
    #
    # to_list(None) rather than a number: the scope is ONE project on ONE day
    # with a single field projected, so there is nothing here a cap would
    # protect against -- and a cap that silently truncated the roster would
    # under-report companies, which is the failure this whole change is about.
    _company_rows = await db.checkins.find(
        _day_checkins, {"worker_company": 1, "company": 1}).to_list(None)
    _companies = set()
    for _c in _company_rows:
        _name = _worker_company(_c.get("worker_company"), _c.get("company"))
        _key = " ".join(_name.lower().split())
        if _key:
            _companies.add(_key)
    companies_on_site = len(_companies)

    # Build summary of what sections are filled
    logbook_summary = []
    total_failed_photos = 0
    for lb in logbooks:
        # PHOTO ENHANCEMENT FAILURES.
        # _enhance_logbook_photos stamps enhance_status="failed" + enhance_error
        # on a photo whose enhance/upload pass raised (server.py:250-256).
        # Nothing read either field. A failed enhancement means the photo has no
        # R2 derivative, so it survives on its inline base64 alone — and it is
        # the photo most likely to be MISSING from the day's report. Counted
        # here so an admin can see it before the report goes out.
        #
        # ADMIN-ONLY BY CONSTRUCTION: this endpoint 403s anyone who is not
        # admin/owner (above), and the count is deliberately absent from the CP
        # editor and from the kiosk/inspector screen — it is our plumbing, not
        # an inspector's business.
        failed_photos = 0
        for activity in ((lb.get("data") or {}).get("activities") or []):
            if not isinstance(activity, dict):
                continue
            for photo in (activity.get("photos") or []):
                if isinstance(photo, dict) and photo.get("enhance_status") == "failed":
                    failed_photos += 1
        total_failed_photos += failed_photos
        logbook_summary.append({
            "log_type": lb.get("log_type"),
            "status": lb.get("status", "draft"),
            "has_signature": bool(lb.get("cp_signature")),
            "cp_name": lb.get("cp_name"),
            # WHOSE RECORD THIS IS, for the per-worker types.
            # subcontractor_orientation files ONE DOCUMENT PER WORKER (the
            # upsert is keyed on data.worker_id), so this list can hold four
            # rows that agree on log_type, cp_name and status and differ only
            # here. Without it the reports screen drew four identical rows for
            # four different workers.
            #
            # Only orientations write data.worker_name at the top level — the
            # other forms keep their names inside per-row arrays (osha_log
            # entries, fall_protection rows) — so every other type serves null
            # and the client renders nothing extra.
            "worker_name": (lb.get("data") or {}).get("worker_name"),
            "updated_at": lb.get("updated_at").isoformat() if isinstance(lb.get("updated_at"), datetime) else str(lb.get("updated_at", "")),
            "failed_photo_count": failed_photos,
        })

    # Check if report was already sent today
    already_sent = await db.report_emails.find_one({
        "project_id": project_id,
        "date": date,
    })

    return {
        "project_id": project_id,
        "project_name": project.get("name"),
        "date": date,
        "checkin_count": checkin_count,
        "logbooks": logbook_summary,
        # Sum of the per-logbook counts above, so the panel has one number to
        # show without walking the list.
        "failed_photo_count": total_failed_photos,
        "has_daily_log": bool(daily_log),
        # The filed logbook's own status, not the adapter's -- as_daily_log_row
        # projects content, and only a SUBMITTED log matches the filter above.
        "daily_log_status": _dj.get("status") if _dj else None,
        "daily_log_weather": daily_log.get("weather") if daily_log else None,
        # THE CP'S REPORTED CREW TOTAL, deliberately not the gate's count. This
        # number is rendered on the daily-log row, beside that log's status, so
        # it must be what that log CLAIMS. as_daily_log_row's own docstring makes
        # the same call for the same reason: the question is whether the CP
        # reported manpower, not whether the gate agreed with him. Showing the
        # gate's number under a daily-log heading would be a fresh contradiction
        # of exactly the kind this pass exists to remove.
        "daily_log_worker_count": daily_log.get("worker_count", 0) if daily_log else 0,
        "companies_on_site": companies_on_site,
        # COMPATIBILITY ALIAS, and it is scheduled rather than permanent. An
        # install older than this deploy reads `subcontractor_count` and would
        # render a blank card if the key vanished -- the stranded-device problem
        # #294 exists to measure. Drop this once CLIENT_MINIMUM_SUPPORTED passes
        # the version that reads `companies_on_site`.
        "subcontractor_count": companies_on_site,
        "report_already_sent": bool(already_sent),
        "report_sent_at": already_sent.get("sent_at").isoformat() if already_sent and isinstance(already_sent.get("sent_at"), datetime) else None,
        "report_send_time": project.get("report_send_time", "18:00"),
        "report_email_list": project.get("report_email_list", []),
    }


# ══ THE GATE TABLET'S ONLY LOGBOOK READ ══════════════════════════════════════
#
# frontend/app/site/logbooks.jsx is the SINGLE caller of the endpoint below
# (logbooksAPI.getSubmitted, src/utils/api.js:1011) and the only way an
# inspector standing on the site reaches a filed compliance record. It served
# whole documents, unprojected, capped at 500 logs. Three consequences, and
# they compound.
#
# ── WHY A PROJECTION AT ALL: THE TABLET COULD NOT CACHE ITS OWN RECORDS ──────
#
# That screen is cache-first by design — `writeListThrough` stores the list
# under ONE AsyncStorage key so a dead zone still shows records. Android
# AsyncStorage is SQLite with `PRAGMA max_page_count` derived from a 6MB
# default (ReactDatabaseSupplier), DATABASE-WIDE, and nothing here overrides it:
# the app is CNG/prebuild with no android/ directory. A write over that ceiling
# is REJECTED. A 60-date window of a photo-and-signature-heavy job measured
# 21,171,731 bytes unprojected — 3.4x the ceiling — so the write failed, and a
# failed write does not mean a missing photo, it means the offline screen has
# NOTHING on it for the one person who is there to read the record. (The
# screen's own rescue, `stripPhotoBlobs`, removes `base64` and nothing else, so
# on a finalized log — where the purge already took `base64` — the second
# attempt was byte-for-byte the first and failed identically.)
#
# ── DERIVED FROM THE CONSUMER, NOT GUESSED ──────────────────────────────────
#
# Everything logbooks.jsx reads off a returned log was enumerated before a
# field was named here. Two blobs, and only two, are provably UNRENDERABLE by
# that screen:
#
#   cp_signature.paths   SignatureBlock (logbooks.jsx:430) resolves
#                        `signature.data || signature.paths` and then draws it
#                        only `if typeof base64Data === 'string'`. `paths` is an
#                        ARRAY of stroke point arrays — SignaturePad.js:247
#                        appends one {x, y} per PanResponder move with no
#                        simplification — so the image branch is unreachable
#                        for it. The strokes crossed the wire and drew nothing.
#                        THE OBJECT STAYS: the screen asks whether a signature
#                        EXISTS (`log.cp_name && !log.cp_signature`), and the
#                        affirmation metadata on it is itself the record. Only
#                        the polyline goes. The PDF renderers keep reading it
#                        through their own reads (_signature_paths_to_svg).
#
#   data.activities[].photos[].base64
#                        the FULL-SIZE original, drawn into an 80x60 view
#                        (styles.activityPhoto). `logbookPhotoUri` is a ladder —
#                        base64, then thumb_base64, then the served-thumb URL —
#                        and the full-size copy is served on demand by
#                        get_logbook_activity_photo, an endpoint of its own.
#                        It is detail content, not list content.
#
# WHAT DELIBERATELY STAYS, because the renderers DRAW it:
#
#   thumb_base64         the retained ~400px copy, and the LAST inline one.
#                        logbookPhotoUri is inline-first on purpose: an
#                        inspector in a dead zone must still see the photo. The
#                        finalize purge is forbidden to remove this copy; this
#                        read may not remove it either.
#   worker_signature     drawn into an <Image> by renderPreshiftSignin and
#                        renderToolboxTalk. Removing it would not merely blank a
#                        picture: the same renderer keys "Not Signed:" off its
#                        ABSENCE, so a projection that dropped it would tell a
#                        DOB inspector that every worker who signed at the kiosk
#                        was unsigned. A record that lies is worse than one that
#                        is large.
#
# EXCLUSION, NOT INCLUSION, and the difference is which way the mistake falls.
# Naming one field to REMOVE cannot break a reader that starts reading a second
# field tomorrow — that field simply arrives. Naming twenty to KEEP breaks it
# silently, and on this screen "silently" means a compliance record renders
# blank to an inspector with nothing anywhere saying why. The same call, for the
# same reason, as WORKER_LIST_FIELDS above (server.py:14138) — that one is an
# inclusion list because its consumers were three known reads of a flat row;
# this payload is thirteen log types deep and every one of them is a `data`
# shape this file does not own.
SUBMITTED_LOGBOOK_EXCLUDED_FIELDS = {
    "cp_signature.paths": 0,
    "data.activities.photos.base64": 0,
}

# ── THE CAP, AND WHY IT COUNTS DATES ────────────────────────────────────────
#
# `.to_list(500)` returned the 500 most recent logs and said nothing about it.
# At thirteen registered log types that is roughly five WEEKS on a busy job,
# after which older filed records were simply unreachable through the tablet's
# only logbook screen. The operator has ruled the tablet must hold everything it
# is approved to see.
#
# A TRUNCATED RESPONSE CAN MAKE THIS CLIENT DELETE FILES. `datesToList` names
# each day's full-day-report PDF onto the cached entry, and `sweepDocCache`
# (src/utils/docCache.js:261) deletes every cached document that no stored list
# names. So a response that quietly dropped dates made the next sweep delete the
# offline PDFs for those dates. That is why the PARAMETER-FREE response is the
# complete set: an installed device cannot be upgraded to read a `complete`
# flag, so the request it already sends must never come back silently short.
# Only a caller that opts into paging — by sending `limit` — can receive a
# partial set, and it is told so in the body.
#
# THE CEILING COUNTS DATES BECAUSE THE CALENDAR BOUNDS IT. A project cannot
# file on more days than it has run; 4000 dates is eleven years of daily
# filing. A cap on LOGS has no such bound and was the defect. If this one is
# ever reached the response says `complete: false` and names its cursor, which
# is the honest failure the old cap could not express.
MAX_SUBMITTED_DATES = 4000


def _submitted_date_key(value) -> str:
    """The grouping key for one filed log.

    Matches the client's own bucketing: it groups on `date` and sorts the keys
    with `b.date.localeCompare(a.date)`, so an undated log lands under
    "unknown" and — 'u' sorting above any '2' — appears first, exactly where it
    did before. Kept as its own function so the page cursor and the grouping
    below cannot disagree about what one date key is.
    """
    return value if isinstance(value, str) and value.strip() else "unknown"


@api_router.get("/logbooks/project/{project_id}/submitted")
async def get_submitted_logbooks(
    project_id: str,
    before: Optional[str] = Query(
        None, max_length=32,
        description="Return only dates strictly older than this key (cursor).",
    ),
    limit: Optional[int] = Query(
        None, ge=1, le=MAX_SUBMITTED_DATES,
        description="Dates per page. Omit for the complete set.",
    ),
    current_user = Depends(get_current_user),
    _proj = Depends(require_project_access),
):
    """Submitted logbook entries grouped by date. The site device's only read.

    Returns {dates, complete, next_before, date_count, log_count}. `dates` is
    unchanged in shape and stays first for the installed clients that read
    nothing else.

    PAGES BY DATE, NEVER BY LOG. The client caches [{date, logs}] entries and
    renders a day as a unit; half a day in one page and half in the next would
    cache a date that is missing filed records with nothing saying so. So the
    page boundary is always a date boundary: the distinct dates are ordered
    first, the page is cut there, and only then are that page's logs read.
    """
    query = {
        "project_id": project_id,
        "status": "submitted",
        "is_deleted": {"$ne": True},
    }

    # Step 1 — the ordered date index. Cheap: one key per calendar day the
    # project filed on, never per log.
    raw_by_key: Dict[str, List] = {}
    for value in await db.logbooks.distinct("date", query):
        raw_by_key.setdefault(_submitted_date_key(value), []).append(value)
    keys = sorted(raw_by_key.keys(), reverse=True)

    # Step 2 — cut the page on a date boundary. The cursor is a date key and the
    # order is descending, so "older than the cursor" is "sorts below it".
    remaining = [k for k in keys if k < before] if before else keys
    page = remaining[:(limit or MAX_SUBMITTED_DATES)]
    # COMPLETE means: this body is the whole submitted history of this project.
    # A cursor was given, or a page was cut -> it is not, and it says so.
    complete = before is None and len(page) == len(keys)
    next_before = page[-1] if page and len(page) < len(remaining) else None

    # Step 3 — the logs for exactly those dates. The raw stored values are
    # replayed rather than the keys, so an undated log (null, missing, or "")
    # is fetched by what is actually on the document; `$in: [None]` matches a
    # missing field as well as a null one.
    wanted = [v for k in page for v in raw_by_key[k]]
    logbooks = []
    if wanted:
        logbooks = await db.logbooks.find(
            {**query, "date": {"$in": wanted}},
            SUBMITTED_LOGBOOK_EXCLUDED_FIELDS,
        ).sort("date", -1).to_list(None)

    by_date: Dict[str, List] = {k: [] for k in page}
    for log in logbooks:
        by_date[_submitted_date_key(log.get("date"))].append(serialize_id(dict(log)))
    return {
        "dates": by_date,
        "complete": complete,
        "next_before": next_before,
        "date_count": len(by_date),
        "log_count": len(logbooks),
    }

@api_router.put("/projects/{project_id}/report-settings", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def update_report_settings(project_id: str, data: dict, current_user = Depends(get_current_user)):
    """Update report email list + send time with validation."""
    # Verify user is admin
    user_role = current_user.get("role")
    if user_role not in ["admin", "owner"]:
        raise HTTPException(status_code=403, detail="Only admins can modify report settings")
    
    # Validate project exists
    project_id_obj = to_query_id(project_id)
    project = await db.projects.find_one({"_id": project_id_obj})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    
    # Check multi-tenancy: admin must be in same company as project
    if user_role == "admin":
        company_id = current_user.get("company_id")
        if project.get("company_id") != company_id:
            raise HTTPException(status_code=403, detail="Cannot modify projects outside your company")
    
    # Build update dict only with provided fields
    now = datetime.now(timezone.utc)
    update = {"updated_at": now}
    
    if "report_email_list" in data and data["report_email_list"] is not None:
        update["report_email_list"] = [email.lower() for email in data["report_email_list"]]
    
    if "report_send_time" in data and data["report_send_time"] is not None:
        update["report_send_time"] = data["report_send_time"]
    
    # Perform update
    result = await db.projects.update_one(
        {"_id": project_id_obj},
        {"$set": update}
    )
    
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Project not found")
    
    updated_project = await db.projects.find_one({"_id": project_id_obj})
    return {
        "message": "Report settings saved successfully",
        "report_email_list": updated_project.get("report_email_list", []),
        "report_send_time": updated_project.get("report_send_time", "18:00"),
    }

@api_router.get("/reports/project/{project_id}/history")
async def get_report_history(
    project_id: str,
    current_user = Depends(get_current_user),
    limit: int = Query(30, ge=1, le=100),
    skip: int = Query(0, ge=0),
):
    """Get report send history for a project (admin view)."""
    # Verify admin/owner
    role = current_user.get("role")
    if role not in ["admin", "owner"]:
        raise HTTPException(status_code=403, detail="Only admins can view report history")
    
    # Verify project exists and user has access
    project_id_obj = to_query_id(project_id)
    project = await db.projects.find_one({"_id": project_id_obj})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    
    if role == "admin" and project.get("company_id") != current_user.get("company_id"):
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Get report emails (automatic scheduler sends)
    history = await db.report_emails.find({
        "project_id": project_id
    }).sort("date", -1).skip(skip).limit(limit).to_list(limit)
    
    total = await db.report_emails.count_documents({"project_id": project_id})
    
    return {
        "project_id": project_id,
        "project_name": project.get("name"),
        "history": [serialize_id(h) for h in history],
        "total": total,
        "limit": limit,
        "skip": skip,
    }


@api_router.get("/reports/project/{project_id}/logs")
async def get_submitted_logs(
    project_id: str,
    current_user = Depends(get_current_user),
    date: Optional[str] = Query(None, description="YYYY-MM-DD"),
    log_type: Optional[str] = Query(None),
    limit: int = Query(30, ge=1, le=100),
):
    """Get submitted logbook entries for a project (admin view)."""
    # Verify admin
    role = current_user.get("role")
    if role not in ["admin", "owner"]:
        raise HTTPException(status_code=403, detail="Only admins can view logs")
    
    # Verify project
    project_id_obj = to_query_id(project_id)
    project = await db.projects.find_one({"_id": project_id_obj})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    
    if role == "admin" and project.get("company_id") != current_user.get("company_id"):
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Build query
    query = {
        "project_id": project_id,
        "status": "submitted",
        "is_deleted": {"$ne": True}
    }
    
    if date:
        query["date"] = date
    
    if log_type:
        query["log_type"] = log_type
    
    logs = await db.logbooks.find(query).sort("date", -1).limit(limit).to_list(limit)
    
    return {
        "project_id": project_id,
        "logs": [serialize_id(log) for log in logs],
        "filters": {
            "date": date,
            "log_type": log_type,
        }
    }

# ==================== DOB COMPLIANCE ENGINE ====================

def _parse_address_components(project_address: str) -> tuple:
    """Split "123 Main St, Brooklyn, NY" into (house_num, street_name).

    Sanitizes for Socrata $where — only uppercase alphanumerics + space
    survive, so attacker-supplied project names can't break out of the
    LIKE clause.
    """
    clean_address = ""
    if project_address:
        clean_address = project_address.split(",")[0].strip()[:40]
    house_num = ""
    street_name = ""
    if clean_address:
        parts = clean_address.split(" ", 1)
        if len(parts) == 2 and parts[0].isdigit():
            house_num = parts[0]
            street_name = parts[1].upper()
        else:
            street_name = clean_address.upper()
    street_name = re.sub(r"[^A-Z0-9 ]", "", street_name)
    house_num = re.sub(r"[^0-9]", "", house_num)
    return house_num, street_name


# Borough labels as they appear in the `borough` column of pkdm-hqz6
# (DOB NOW: CofO) — verified live 2026-09-02 against
#   $select=borough,count(1)&$group=borough
# which returns exactly these five values and no others.
_COFO_BOROUGH_BY_BIN_PREFIX = {
    "1": "MANHATTAN",
    "2": "BRONX",
    "3": "BROOKLYN",
    "4": "QUEENS",
    "5": "STATEN ISLAND",
}
_COFO_BOROUGH_ALIASES = {
    "MANHATTAN": "MANHATTAN", "NEW YORK": "MANHATTAN", "NY": "MANHATTAN",
    "BRONX": "BRONX", "THE BRONX": "BRONX",
    "BROOKLYN": "BROOKLYN", "KINGS": "BROOKLYN",
    "QUEENS": "QUEENS",
    "STATEN ISLAND": "STATEN ISLAND", "RICHMOND": "STATEN ISLAND",
}


def _cofo_borough_label(nyc_bin: str, project_address: str = "") -> Optional[str]:
    """Uppercase borough label for the CofO address-fallback query, or
    None when the borough genuinely cannot be derived.

    The fallback matches on house_no + street_name, which is NOT unique
    across NYC: "55 WATER STREET" resolves to 48 CofO rows split
    Manhattan 31 / Brooklyn 17 (verified live 2026-09-02), so without a
    borough constraint roughly a third of them belong to a different
    building. Two independent sources make the borough derivable in
    almost every case:

      1. The leading digit of the BIN. This works even for the
         placeholder BINs (``X000000``) that make ``bin_usable`` False —
         i.e. precisely the case where the address fallback is doing the
         real work rather than backstopping a BIN query.
      2. The borough named in the address itself. ``_parse_address_components``
         throws away everything after the first comma, but the raw
         address is still in hand here.

    Returns None only when the BIN is empty/short AND the address names
    no recognizable borough — a genuinely unlocatable project. Callers
    must then run the fallback unconstrained and treat its results as
    borough-ambiguous.
    """
    prefix = (nyc_bin or "").strip()[:1]
    if prefix in _COFO_BOROUGH_BY_BIN_PREFIX:
        return _COFO_BOROUGH_BY_BIN_PREFIX[prefix]
    # Fall back to the borough named in the address tail.
    for part in (project_address or "").upper().split(",")[1:]:
        cleaned = re.sub(r"[^A-Z ]", "", part).strip()
        if cleaned in _COFO_BOROUGH_ALIASES:
            return _COFO_BOROUGH_ALIASES[cleaned]
    return None


async def _query_dob_apis(nyc_bin: str, project_address: str = "") -> list:
    """Query NYC Open Data Socrata endpoints by BIN and/or address."""
    all_records = []
    seen_ids = set()
    
    # Extract clean street address for address-based queries
    clean_address = ""
    if project_address:
        clean_address = project_address.split(",")[0].strip()[:40]
    
    # Determine if BIN is usable (not a placeholder like X000000)
    bin_usable = nyc_bin and not nyc_bin.endswith("000000")
    
    # Parse house number and street name separately
    house_num, street_name = _parse_address_components(project_address)
    
    endpoints = []
    
    # ── JOB FILINGS (DOB NOW - w9ak-ipjd) ──
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/w9ak-ipjd.json",
            "params": {"bin": nyc_bin, "$limit": "50"},
            "record_type": "job_status",
            "id_field": "job_filing_number",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/w9ak-ipjd.json",
            "params": {"house_no": house_num, "$where": f"upper(street_name) like '%{street_name}%'", "$limit": "50"},
            "record_type": "job_status",
            "id_field": "job_filing_number",
        })
    
    # ── VIOLATIONS: DOB NOW Safety (855j-jady) - NEWEST, check first ──
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/855j-jady.json",
            "params": {"bin": nyc_bin, "$limit": "50"},
            "record_type": "violation",
            "id_field": "violation_number",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/855j-jady.json",
            "params": {"house_number": house_num, "$where": f"upper(street) like '%{street_name}%'", "$limit": "50"},
            "record_type": "violation",
            "id_field": "violation_number",
        })
    
    # ── VIOLATIONS: BIS legacy (3h2n-5cm9) - older violations ──
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/3h2n-5cm9.json",
            "params": {"bin": nyc_bin, "$limit": "50"},
            "record_type": "violation",
            "id_field": "isn_dob_bis_viol",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/3h2n-5cm9.json",
            "params": {"house_number": house_num, "$where": f"upper(street) like '%{street_name}%'", "$limit": "50"},
            "record_type": "violation",
            "id_field": "isn_dob_bis_viol",
        })
    
    # ── VIOLATIONS: ECB/OATH (6bgk-3dad) - adjudicated summonses ──
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/6bgk-3dad.json",
            "params": {"bin": nyc_bin, "$limit": "100", "$order": "issue_date DESC"},
            "record_type": "violation",
            "id_field": "ecb_violation_number",
        })
    # ECB/OATH (6bgk-3dad) has no `violation_address` — the only address
    # fields are `respondent_*` (mailing address of the respondent, not
    # the violation site). BIN is the only reliable key for this dataset,
    # so no address-shape fallback is added here.
    
    # ── PERMITS: DOB NOW Build (rbx6-tga4) - NEWEST, check first.
    #    This dataset has NO `filing_date` column — available date fields
    #    are `approved_date`, `issued_date`, `expired_date`. Ordering by
    #    a non-existent column made Socrata 400 every query, which is
    #    why DOB NOW Build permits were silently missing from projects.
    #    Order by `issued_date DESC` so renewal collapse keeps the
    #    most-recently-issued filing.
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/rbx6-tga4.json",
            "params": {"bin": nyc_bin, "$limit": "250", "$order": "issued_date DESC"},
            "record_type": "permit",
            "id_field": "job_filing_number",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/rbx6-tga4.json",
            "params": {"house_no": house_num, "$where": f"upper(street_name) like '%{street_name}%'", "$limit": "250", "$order": "issued_date DESC"},
            "record_type": "permit",
            "id_field": "job_filing_number",
        })

    # ── PERMITS: DOB NOW Electrical (dm9a-ab7w) - separate dataset for
    #    electrical permits (not returned by rbx6-tga4 or ipu4-2q9a).
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/dm9a-ab7w.json",
            "params": {"bin": nyc_bin, "$limit": "250", "$order": "filing_date DESC"},
            "record_type": "permit",
            "id_field": "job_filing_number",
        })
    if house_num and street_name:
        # DOB NOW Electrical address column is `house_number` (not `house_no`
        # like the Build dataset — different teams, different schemas).
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/dm9a-ab7w.json",
            "params": {"house_number": house_num, "$where": f"upper(street_name) like '%{street_name}%'", "$limit": "250", "$order": "filing_date DESC"},
            "record_type": "permit",
            "id_field": "job_filing_number",
        })

    # ── PERMITS: BIS legacy (ipu4-2q9a) - pre-2018 permits across
    #    all trades (PL, EL, EQ, etc.). Order by filing_date DESC.
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/ipu4-2q9a.json",
            "params": {"bin__": nyc_bin, "$limit": "250", "$order": "filing_date DESC"},
            "record_type": "permit",
            "id_field": "job__",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/ipu4-2q9a.json",
            "params": {"house__": house_num, "$where": f"upper(street_name) like '%{street_name}%'", "$limit": "250", "$order": "filing_date DESC"},
            "record_type": "permit",
            "id_field": "job__",
        })
    
    # ── DOB INSPECTIONS — INGEST REMOVED (COMMIT 1, 2026-07-25) ──
    # The p937-wjvj dataset ingested here as record_type="inspection"
    # is NYC DOHMH *Rodent* Inspection data (rat inspections), NOT DOB
    # building inspections — a dataset mislabel. Its "PC" (Pest Control)
    # job prefix was also fabricated into a "Plumbing" trade category by
    # the (now-removed) DOB_JOB_PREFIX_CATEGORY decoder. Ingest removed
    # so no new rodent rows enter dob_logs; existing rows are deleted
    # separately. NOTE: the statistical engine still queries p937-wjvj
    # LIVE via DATASET_DOB_INSPECTIONS (peer dimension, borough-sweep
    # trigger, inspection prediction, calibration) — deferred to the
    # score rebuild; see docs/audits/ follow-ups.

    # ── DOB COMPLAINTS RECEIVED (eabe-havv) - Primary DOB complaint source ──
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/eabe-havv.json",
            "params": {"bin": nyc_bin, "$limit": "50", "$order": "date_entered DESC"},
            "record_type": "complaint",
            "id_field": "complaint_number",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/eabe-havv.json",
            "params": {"house_number": house_num, "$where": f"upper(house_street) like '%{street_name}%'", "$limit": "50", "$order": "date_entered DESC"},
            "record_type": "complaint",
            "id_field": "complaint_number",
        })

    # ── MR.14 (commit 2b) — five new monitoring datasets ──────────
    # Verified Socrata IDs as of 2026-05-03 (operator F2/F3/F4 +
    # web verification). The four-letter dataset codes called out
    # by the operator (`if-bn-mnnh`, `bs9k-acwn`) did not match
    # the live datasets; correct IDs below. Surfaced in the commit
    # body for visibility.

    # ── STOP WORK ORDERS (3usq-5cid) - dedicated SWO dataset ──
    # Replaces the legacy text-match-on-violations path. Note: this
    # dataset is "Stop Work Orders since Article 202.6" — only
    # captures SWOs issued under Article 202.6 (a recent law).
    # Pre-Article-202.6 SWOs may not appear here. False-negative
    # risk surfaced in commit body.
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/3usq-5cid.json",
            "params": {"bin": nyc_bin, "$limit": "50", "$order": "issue_date DESC"},
            "record_type": "swo",
            "id_field": "stop_work_order_number",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/3usq-5cid.json",
            "params": {
                "house_number": house_num,
                "$where": f"upper(street_name) like '%{street_name}%'",
                "$limit": "50",
                "$order": "issue_date DESC",
            },
            "record_type": "swo",
            "id_field": "stop_work_order_number",
        })

    # ── CERTIFICATE OF OCCUPANCY (pkdm-hqz6) - DOB NOW: CofO ──
    # Per operator F3, replaces the unverified bs9k-acwn candidate
    # with the live DOB NOW: Certificate of Occupancy dataset.
    #
    # 2026-09-02: this block previously named SIX columns that
    # pkdm-hqz6 does not have. `$order: issuance_date` alone made
    # Socrata reject the whole request —
    #   HTTP 400 query.soql.no-such-column; No such column: issuance_date
    # — on every call since the feature shipped, 96×/day, so zero CofO
    # records were ever ingested. `id_field: co_number` and the
    # `house_number` filter param were wrong the same way. Real column
    # names verified live against the dataset schema; pinned offline in
    # tests/test_cofo_query_matches_dataset_schema.py.
    #
    # ORDERING: NOT c_of_o_issuance_date. That column is typed `text`
    # and holds "MM/DD/YY HH:MM:SS AM" strings, so DESC on it sorts
    # lexicographically — "12/02/24" ranks above "09/25/25". We sort on
    # c_of_o_sequence, a `number` column that is never null (0 of 81,264
    # rows) and tracks application_number ("CO-000100309" ⇔ 100309), so
    # it is monotonic in filing order. This matters: one BIN in the
    # dataset carries 64 CofO rows against a $limit of 50, so which 50
    # we take is a real choice, not a formality.
    #
    # NULL ISSUANCE: excluded server-side. A CofO row with no issuance
    # date is not evidence a building was completed, and Socrata sorts
    # nulls FIRST under DESC, so such a row silently consumes a slot in
    # the 50-row window ahead of every real certificate. This feeds the
    # seven-year records-retention clock, so an un-issued certificate
    # must not start it.
    _COFO_ISSUED_ONLY = "c_of_o_issuance_date IS NOT NULL"
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/pkdm-hqz6.json",
            "params": {
                "bin": nyc_bin,
                "$where": _COFO_ISSUED_ONLY,
                "$limit": "50",
                "$order": "c_of_o_sequence DESC",
            },
            "record_type": "cofo",
            "id_field": "c_of_o_number",
        })
    if house_num and street_name:
        # Left-anchored LIKE, not '%…%'. The leading wildcard matched
        # any street CONTAINING the name: '%BROADWAY%' also pulls WEST
        # BROADWAY (119 rows), EAST BROADWAY (49), E/W BROADWAY.
        # Anchoring keeps the suffix tolerance the wildcard was there
        # for (ST vs STREET) and drops the prefix bleed.
        #
        # street_name and house_num are sanitized by
        # _parse_address_components to [A-Z0-9 ] only, which removes the
        # quote, the LIKE metacharacters % and _, and comment syntax
        # before they reach this f-string.
        _cofo_where = [
            f"upper(street_name) like '{street_name}%'",
            _COFO_ISSUED_ONLY,
        ]
        _cofo_borough = _cofo_borough_label(nyc_bin, project_address)
        if _cofo_borough:
            _cofo_where.insert(1, f"upper(borough) = '{_cofo_borough}'")
        else:
            # Unlocatable project: no BIN digit and no borough in the
            # address. The fallback still runs, but house_no + street
            # repeats across boroughs, so these results are
            # borough-ambiguous and may attribute another building's
            # certificate to this project.
            logger.warning(
                "CofO address fallback for %r has no derivable borough; "
                "results are borough-ambiguous",
                project_address,
            )
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/pkdm-hqz6.json",
            "params": {
                "house_no": house_num,
                "$where": " AND ".join(_cofo_where),
                "$limit": "50",
                "$order": "c_of_o_sequence DESC",
            },
            "record_type": "cofo",
            "id_field": "c_of_o_number",
        })

    # ── FAÇADE FISP (xubg-57si) - DOB NOW: Safety Façades ──
    # Operator F4 — required for v1 monitoring scope.
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/xubg-57si.json",
            "params": {"bin": nyc_bin, "$limit": "50", "$order": "filing_date DESC"},
            "record_type": "facade_fisp",
            "id_field": "filing_number",
        })
    if house_num and street_name:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/xubg-57si.json",
            "params": {
                "house_number": house_num,
                "$where": f"upper(street_name) like '%{street_name}%'",
                "$limit": "50",
                "$order": "filing_date DESC",
            },
            "record_type": "facade_fisp",
            "id_field": "filing_number",
        })

    # ── BOILER COMPLIANCE (52dp-yji6) - DOB NOW: Safety Boiler ──
    # Operator F4 — required for v1 monitoring scope.
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/52dp-yji6.json",
            "params": {"bin_number": nyc_bin, "$limit": "50", "$order": "report_filing_date DESC"},
            "record_type": "boiler",
            "id_field": "tracking_number",
        })
    # Boiler dataset is BIN-keyed; address fallback skipped (the
    # dataset's only address fields describe the building, not the
    # filing — and BIN coverage is reliable for boilered buildings).

    # ── ELEVATOR COMPLIANCE (e5aq-a4j2) - DOB NOW Elevator ──
    # Operator F4 — required for v1 monitoring scope.
    if bin_usable:
        endpoints.append({
            "url": "https://data.cityofnewyork.us/resource/e5aq-a4j2.json",
            "params": {"bin": nyc_bin, "$limit": "100", "$order": "filing_date DESC"},
            "record_type": "elevator",
            "id_field": "device_number",
        })
    # Elevator dataset is BIN-keyed; same reasoning as boiler.


    # Per-endpoint counters so permit-count regressions ("previously 7,
    # now 2") can be diagnosed from a single sync log line without
    # live-tailing. Reported after the loop completes.
    per_endpoint_stats: List[Dict[str, Any]] = []

    async with ServerHttpClient(timeout=20.0) as http_client:
        for ep in endpoints:
            raw_returned = 0
            kept_after_dedup = 0
            try:
                resp = await http_client.get(ep["url"], params=ep["params"])
                if resp.status_code == 200:
                    records = resp.json()
                    if not isinstance(records, list):
                        records = []
                    raw_returned = len(records)
                    for rec in records:
                        # Build a dedup key from the record's unique ID
                        id_field = ep["id_field"]
                        raw_id = str(rec.get(id_field, "")).strip()

                        if not raw_id:
                            continue

                        # Permits: ONE row per permit filing. Key on the full
                        # job_filing_number (raw_id) — the same `record_type:raw_id`
                        # shape every other type uses (shared dedup, not a parallel
                        # permit copy). A permit re-issued annually is the SAME
                        # filing number on several rows with different issued_dates
                        # (e.g. B01074863-I1 × 3); endpoints order issued_/
                        # filing_date DESC, so the first seen is the newest — keep
                        # it, drop the older re-issuances → latest status wins.
                        # Distinct filings of one job (…-I1 vs …-S1) keep separate
                        # numbers → separate permits, correctly not merged.
                        #
                        # Replaces the old base_job:work_type collapse, which split
                        # ONE permit into duplicates whenever `work_type` was
                        # populated on one DOB dataset's row and null on another's.
                        # (Trade-off: a renewal DOB issues under a NEW number —
                        # …-I2/-I3 — now shows as its own filing rather than being
                        # folded into the base job. Current DOB NOW data re-issues
                        # under the same number, so this matches observed permits.)
                        if ep["record_type"] == "permit":
                            filing_no = (raw_id or "").strip()
                            dedup_key = f"permit:{filing_no.upper()}"
                            rec["_collapsed_permit_id"] = filing_no
                        else:
                            dedup_key = f"{ep['record_type']}:{raw_id}"

                        # Skip if we already have this record from another endpoint
                        if dedup_key in seen_ids:
                            continue
                        seen_ids.add(dedup_key)
                        kept_after_dedup += 1

                        rec["_record_type"] = ep["record_type"]
                        rec["_id_field"] = id_field
                        # V2.3.A2 Change 3 — stamp the source
                        # dataset slug on every record. Parsed
                        # from the endpoint URL's last path
                        # segment (e.g. ".../resource/855j-jady.json"
                        # → "855j-jady"). The url.split("?", 1)[0]
                        # strips any future query-string suffix
                        # before the slug parse so a maintainer
                        # adding ".../855j-jady.json?$where=..." to
                        # an endpoint URL string doesn't silently
                        # break the stamping. Forward-only: existing
                        # ~624 dob_logs records on prod remain
                        # unstamped; no backfill in this PR.
                        try:
                            url_path = ep["url"].split("?", 1)[0]
                            rec["_dataset"] = (
                                url_path.rsplit("/", 1)[-1].rsplit(".", 1)[0]
                            )
                        except Exception:
                            rec["_dataset"] = None
                        if ep["record_type"] == "violation":
                            # Check ALL text fields for stop work indicators across all 3 violation datasets
                            swo_fields = [
                                rec.get("violation_type", ""),
                                rec.get("violation_type_code", ""),
                                rec.get("description", ""),
                                rec.get("violation_description", ""),
                                rec.get("infraction_codes", ""),
                                rec.get("penalty_description", ""),
                                rec.get("section_of_law", ""),
                                rec.get("severity", ""),
                                rec.get("violation_category", ""),
                                rec.get("certification_status", ""),
                                rec.get("status", ""),
                            ]
                            combined = " ".join(str(f or "").lower() for f in swo_fields)
                            if "stop work" in combined or "swo" in combined or "partial stop" in combined:
                                rec["_record_type"] = "swo"
                        all_records.append(rec)
                else:
                    logger.warning(f"DOB API {ep['url']} returned {resp.status_code}")
            except Exception as e:
                logger.error(f"DOB API error {ep['url']}: {e}")
            per_endpoint_stats.append({
                "url": ep["url"].rsplit("/", 1)[-1].replace(".json", ""),
                "record_type": ep["record_type"],
                "query_shape": "bin" if "bin" in ep["params"] or "bin__" in ep["params"] else "addr",
                "raw_returned": raw_returned,
                "kept_after_dedup": kept_after_dedup,
            })

    # Per-record-type breakdown. Permits get special treatment: log
    # raw vs collapsed counts AND the unique base_jobs observed so we
    # can diagnose "shows N permits, should be M" without guessing.
    def _pt_summary(record_type: str) -> str:
        rows = [s for s in per_endpoint_stats if s["record_type"] == record_type]
        raw = sum(r["raw_returned"] for r in rows)
        kept = sum(r["kept_after_dedup"] for r in rows)
        shapes = ",".join(f"{r['url']}({r['query_shape']})={r['raw_returned']}→{r['kept_after_dedup']}" for r in rows)
        return f"{record_type}: raw={raw} kept={kept} [{shapes}]"

    permit_base_jobs = sorted({
        r.get("_collapsed_permit_id", "").split(":")[0]
        for r in all_records if r.get("_record_type") == "permit" and r.get("_collapsed_permit_id")
    })
    logger.info(
        f"DOB query complete: {len(all_records)} unique records from "
        f"{len(endpoints)} endpoints — "
        + "; ".join(_pt_summary(rt) for rt in ("permit", "inspection", "complaint", "violation"))
        + (f" — permit_base_jobs={permit_base_jobs}" if permit_base_jobs else "")
    )
    return all_records
 
def _humanize_record_type(rt: str) -> str:
    """User-facing label. No screaming caps — those hurt spam scores."""
    rt = (rt or "alert").lower().replace("_", " ")
    pretty = {
        "violation":  "violation",
        "complaint":  "complaint",
        "permit":     "permit update",
        "inspection": "inspection result",
        "swo":        "stop work order",
    }
    return pretty.get(rt, rt)


async def _send_critical_dob_alert(project: dict, dob_log: dict):
    """Send a notification email about a DOB record that needs attention.

    Deliberately plain and conversational. All-caps subjects, red
    banners, bracketed "[CRITICAL]" tags, and heavy emoji push spam
    filters toward Promotions / Junk even when SPF/DKIM/DMARC are
    clean on Resend. Ship a plain-text alternative alongside the HTML
    — html-only messages are themselves a spam signal.
    """
    if not RESEND_API_KEY:
        return

    company_id = project.get("company_id")
    if not company_id:
        return

    recipients = []
    admin_users = await db.users.find({
        "company_id": company_id,
        "role":       {"$in": ["admin", "owner"]},
        "is_deleted": {"$ne": True},
    }).to_list(50)
    for u in admin_users:
        email = u.get("email")
        if email:
            recipients.append(email)
    if not recipients:
        return

    project_name = project.get("name", "your project")
    summary      = dob_log.get("ai_summary")  or "A new DOB record was found."
    next_action  = dob_log.get("next_action") or "Open Levelog to review the details."
    rt_raw       = dob_log.get("record_type", "")
    rt           = _humanize_record_type(rt_raw)
    dob_link     = dob_log.get("dob_link") or ""
    detected_at  = dob_log.get("detected_at") or datetime.now(timezone.utc)
    if isinstance(detected_at, datetime):
        detected_str = detected_at.strftime("%b %d, %Y at %I:%M %p UTC")
    else:
        detected_str = str(detected_at)

    # Plaintext alternative: present-tense, human, no urgency language.
    link_line = f"\n\nDetails: {dob_link}" if dob_link else ""
    text_body = (
        f"Hi,\n\n"
        f"Levelog picked up a new {rt} on {project_name}.\n\n"
        f"Summary: {summary}\n\n"
        f"Recommended next step: {next_action}\n\n"
        f"Detected {detected_str}."
        f"{link_line}\n\n"
        f"You're receiving this because you're listed as an admin or owner "
        f"on this Levelog project. Reply to this email if you have questions.\n\n"
        f"— Levelog"
    )

    # HTML — neutral transactional layout. No red banner, no uppercase
    # pill labels, no emoji. Looks like any other account notification.
    link_html = (
        f'<p style="margin:16px 0 0;"><a href="{dob_link}" '
        f'style="color:#1d4ed8;text-decoration:none;">View on NYC DOB</a></p>'
        if dob_link else ""
    )
    html_body = f"""<!DOCTYPE html>
<html>
<body style="margin:0;padding:24px;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;color:#1f2937;line-height:1.55;">
  <table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" width="560" style="max-width:560px;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;">
    <tr><td style="padding:24px 28px;">
      <p style="margin:0 0 12px;font-size:14px;color:#6b7280;">Levelog</p>
      <h1 style="margin:0 0 18px;font-size:18px;font-weight:600;color:#111827;">
        New {rt} on {project_name}
      </h1>
      <p style="margin:0 0 14px;font-size:15px;">Hi,</p>
      <p style="margin:0 0 14px;font-size:15px;">
        Levelog picked up a new {rt} on <strong>{project_name}</strong>. Here are the details:
      </p>
      <p style="margin:0 0 14px;font-size:15px;"><strong>Summary:</strong> {summary}</p>
      <p style="margin:0 0 14px;font-size:15px;"><strong>Recommended next step:</strong> {next_action}</p>
      <p style="margin:0 0 14px;font-size:13px;color:#6b7280;">Detected {detected_str}.</p>
      {link_html}
      <hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0;">
      <p style="margin:0;font-size:12px;color:#6b7280;">
        You're receiving this because you're listed as an admin or owner on this Levelog project.
        Reply to this email if you have questions.
      </p>
    </td></tr>
  </table>
</body>
</html>"""

    subject = f"New {rt} on {project_name}"

    # MR.14 fix — route through lib/notifications.send_notification.
    # That helper provides:
    #   • Universal NOTIFICATIONS_KILL_SWITCH check
    #   • trigger_key idempotency (per recipient, 23h window)
    #   • notification_log audit trail
    #   • NOTIFICATIONS_ENABLED + RESEND_API_KEY gates
    # Pre-MR.14 this site called resend.Emails.send directly, which
    # bypassed all of those — that's how the 2026-05-03 flood
    # reached michael@blueviewbuilders.com without dedup.
    #
    # entity_id encodes the record being alerted on. Combined with
    # trigger_type='critical_dob_alert' and per-recipient dedup, the
    # idempotency check guarantees one alert per record per recipient
    # per 23 hours, regardless of how many polls fire in between.
    raw_dob_id = dob_log.get("raw_dob_id") or ""
    entity_id = f"dob_log:{raw_dob_id}" if raw_dob_id else f"project:{project.get('_id')}"
    from lib.notifications import send_notification
    for recipient in recipients:
        try:
            await send_notification(
                db,
                permit_renewal_id=entity_id,
                trigger_type="critical_dob_alert",
                recipient=recipient,
                subject=subject,
                html=html_body,
                text=text_body,
                metadata={
                    "project_id": str(project.get("_id") or ""),
                    "project_name": project_name,
                    "record_type": rt_raw,
                    "raw_dob_id": raw_dob_id,
                    "severity": dob_log.get("severity"),
                },
            )
        except Exception as e:
            logger.error(
                f"DOB notification send_notification error "
                f"recipient={recipient}: {e}"
            )
    logger.info(
        f"DOB notification dispatched for {project_name} "
        f"({rt}) to {len(recipients)} recipient(s) "
        f"via lib/notifications (idempotency-keyed by entity_id={entity_id})"
    )


# ==================== DOB ALERT GATING ====================
#
# Two layers, both keyed in system_config:
#
#  1. Initial-scan suppression. The first time a source (`dob`, `311`, `bis`)
#     scans a project, it pulls in the entire historical backlog. Emailing
#     every single one of those to the owner is worthless noise — the records
#     show in the app regardless. After the initial scan completes, we mark
#     the project/source pair done; from then on, newly-discovered records
#     can alert.
#
#  2. 24h per-record throttle. Mirrors the /dob-sync rate limiter shape.
#     Without this, every 30-min scheduler tick that rediscovers the same
#     Critical record resends the email.

_DOB_ALERT_THROTTLE_HOURS = 24


async def _initial_scan_done(project_id: str, source: str) -> bool:
    """True if `source` has already completed at least one full scan for
    this project. `source` is one of 'dob' (nightly DOB sync / NYC Open
    Data), '311' (311 Service Requests poll), 'bis' (BIS scraper)."""
    if not project_id or not source:
        return False
    try:
        doc = await db.system_config.find_one(
            {"key": f"initial_scan_done:{source}:{project_id}"}
        )
        return bool(doc)
    except Exception as e:
        logger.warning(f"initial_scan_done read failed: {e}")
        # On DB hiccups, err toward "done" so we don't silently suppress
        # real alerts forever.
        return True


async def _mark_initial_scan_done(project_id: str, source: str) -> None:
    if not project_id or not source:
        return
    try:
        await db.system_config.update_one(
            {"key": f"initial_scan_done:{source}:{project_id}"},
            {"$set": {
                "key":          f"initial_scan_done:{source}:{project_id}",
                "source":       source,
                "project_id":   project_id,
                "completed_at": datetime.now(timezone.utc),
            }},
            upsert=True,
        )
    except Exception as e:
        logger.warning(f"initial_scan mark failed: {e}")


async def _dob_alert_recently_sent(project_id: str, raw_dob_id: str,
                                     window_hours: int = _DOB_ALERT_THROTTLE_HOURS) -> bool:
    """Returns True if we've already emailed this (project, record) combo
    inside the window. Keyed on `dob_alert_sent:{project}:{raw_dob_id}`."""
    if not project_id or not raw_dob_id:
        return False
    try:
        doc = await db.system_config.find_one(
            {"key": f"dob_alert_sent:{project_id}:{raw_dob_id}"}
        )
        if not doc:
            return False
        last = doc.get("last_alert_at")
        if not isinstance(last, datetime):
            return False
        if last.tzinfo is None:
            last = last.replace(tzinfo=timezone.utc)
        elapsed_hours = (datetime.now(timezone.utc) - last).total_seconds() / 3600.0
        return elapsed_hours < window_hours
    except Exception as e:
        logger.warning(f"alert throttle read failed: {e}")
        return False  # on error, err toward sending rather than silent-drop


async def _mark_dob_alert_sent(project_id: str, raw_dob_id: str) -> None:
    if not project_id or not raw_dob_id:
        return
    try:
        await db.system_config.update_one(
            {"key": f"dob_alert_sent:{project_id}:{raw_dob_id}"},
            {"$set": {
                "key":           f"dob_alert_sent:{project_id}:{raw_dob_id}",
                "last_alert_at": datetime.now(timezone.utc),
            }},
            upsert=True,
        )
    except Exception as e:
        logger.warning(f"alert throttle write failed: {e}")


async def _send_critical_dob_alert_throttled(
    project: dict, dob_log: dict, source: str = "dob",
) -> bool:
    """Wrapper that enforces:

      1. Initial-scan suppression: first scan of the (project, source) pair
         never emails. Records still get inserted and shown in the app —
         this just mutes the notification firehose during backfill.
      2. 24h per-record throttle.

    `source` is one of 'dob', '311', 'bis'. Returns True if an alert was
    actually sent, False if suppressed. Existing callers that don't pass
    `source` get the default 'dob' which matches the nightly scan.
    """
    project_id = str(project.get("_id") or project.get("id") or "")
    raw_dob_id = str(dob_log.get("raw_dob_id") or "")

    # Gate 1 — initial-scan suppression
    if not await _initial_scan_done(project_id, source):
        logger.info(
            f"DOB alert suppressed (initial scan in progress) "
            f"source={source} project={project.get('name')} "
            f"raw_dob_id={raw_dob_id}"
        )
        return False

    # Gate 2 — 24h per-record throttle
    if await _dob_alert_recently_sent(project_id, raw_dob_id):
        logger.info(
            f"DOB alert throttled (within 24h) source={source} "
            f"project={project.get('name')} raw_dob_id={raw_dob_id}"
        )
        return False

    await _send_critical_dob_alert(project, dob_log)
    await _mark_dob_alert_sent(project_id, raw_dob_id)
    return True


# ==================== 311 FAST POLL (Feature 1) ====================
# NYC 311 Service Requests dataset (`erm2-nwe9`) — distinct from the
# DOB-specific complaints dataset `eabe-havv` already polled by the nightly
# scan. 311 catches the faster-moving stuff: neighbor calls about noise /
# construction / illegal conversions / elevator outages / boiler issues.
#
# Runs every 30 minutes via APScheduler. Dedup key is the 311 `unique_key`,
# stored in `dob_logs.raw_dob_id` with a `311:` prefix to avoid collision
# with DOB complaint numbers.

_NYC_311_ENDPOINT = "https://data.cityofnewyork.us/resource/erm2-nwe9.json"

# 311 complaint_type values that map to DOB-relevant inspector action.
# Curated per operator feedback: neighbor calls that actually produce
# inspector visits / violations against the building.
_311_ACTION_COMPLAINT_TYPES = {
    "Construction",
    "General Construction/Plumbing",
    "Construction Equipment",
    "Scaffold Safety",
    "Illegal Construction",
    "After Hours Work Illegal",
    "Non-Residential Building Condition",
    "Structural - Private",
    "Boiler",
    "Elevator",
    "Facade",
    "Unsafe Building",
    "Derrick/Suspension/Adjustable Scaffold",
    "Illegal Conversion",
}
_311_ACTION_SET_LOWER = {t.lower() for t in _311_ACTION_COMPLAINT_TYPES}


def _severity_for_311(complaint_type: str) -> str:
    """Return 'Action' for construction/structural categories, else 'Monitor'."""
    if not complaint_type:
        return "Monitor"
    return "Action" if complaint_type.strip().lower() in _311_ACTION_SET_LOWER else "Monitor"


def _fmt_311_summary(rec: dict) -> str:
    """One-line human summary for dob_logs.ai_summary."""
    ct = (rec.get("complaint_type") or "").strip() or "311 Complaint"
    desc = (rec.get("descriptor") or "").strip()
    agency = (rec.get("agency") or "").strip()
    parts = [ct]
    if desc and desc != ct:
        parts.append(desc)
    if agency:
        parts.append(f"({agency})")
    return " — ".join(parts)[:220]


def _next_action_for_311(rec: dict) -> str:
    status = (rec.get("status") or "").strip().lower()
    if status in ("closed", "resolved"):
        return "311 complaint is closed. Review disposition and file with the project record."
    return (
        "Inspector may visit within 48 hours. Pull the cited area, brief the super, "
        "and make sure relevant permits are posted + current."
    )


async def _fetch_311_for_project(
    client: "httpx.AsyncClient",
    bbl: str,
    house_num: str,
    street_name: str,
) -> List[dict]:
    """Fetch recent 311 service requests for a project.

    The 311 dataset (erm2-nwe9) has NO `bin` column — only `bbl`. Prior
    BIN queries were 400-ing every run. Prefer BBL when the project has
    one, otherwise fall back to an address match. Sorted newest-first,
    limit 100.

    Parameter renamed `nyc_bbl` → `bbl` 2026-04-27 (step 9.1) for
    consistency with the renamed Mongo field.
    """
    params: Optional[dict] = None
    if bbl:
        params = {
            "bbl":     bbl,
            "$limit":  "100",
            "$order":  "created_date DESC",
        }
    elif house_num and street_name:
        # incident_address is the raw street string ("123 Main St"); match
        # on house number + street name. Uppercased to tolerate casing.
        safe_house = house_num.replace("'", "").strip()
        safe_street = street_name.replace("'", "").strip().upper()
        params = {
            "$where": f"upper(incident_address) like '%{safe_house}%{safe_street}%'",
            "$limit":  "100",
            "$order":  "created_date DESC",
        }
    else:
        return []

    try:
        resp = await client.get(_NYC_311_ENDPOINT, params=params, timeout=20.0)
        if resp.status_code != 200:
            key = bbl or f"{house_num} {street_name}"
            logger.warning(f"311 fetch {key} returned {resp.status_code}")
            return []
        data = resp.json()
        return data if isinstance(data, list) else []
    except Exception as e:
        key = bbl or f"{house_num} {street_name}"
        logger.warning(f"311 fetch {key} failed: {e}")
        return []


def _build_311_doc(rec: dict, project: dict, now: datetime) -> dict:
    """V2.3.A3 PR #9 — extracted from ``_ingest_311_for_project``'s
    inline dict construction (formerly at server.py:14063-14093) per
    Stage 2 T6.B refactor. Pure function for testability.

    No behavior change beyond date normalization via
    ``_normalize_dob_date_to_iso`` on ``complaint_date`` +
    ``closed_date``. The mutation-and-diff logic
    (``current_status``, ``signal_kind``, ``previous_status``,
    ``is_seed_transition``) stays in the caller — this function
    only produces the base dob_log document shape.

    Args:
      rec     — raw Socrata record from erm2-nwe9.
      project — project document (provides ``_id``, ``company_id``,
                ``nyc_bin``).
      now     — write-time UTC timestamp.

    Returns the dob_log document with 311-shape fields populated
    + ISO-canonical date fields.
    """
    project_id = str(project.get("_id"))
    company_id = project.get("company_id", "")
    nyc_bin = (project.get("nyc_bin") or "").strip()
    unique_key = str(rec.get("unique_key") or "").strip()
    raw_dob_id = f"311:{unique_key}"

    ctype = (rec.get("complaint_type") or "").strip()
    severity = _severity_for_311(ctype)
    complaint_status = rec.get("status") or None

    address_parts = [
        (rec.get("incident_address") or "").strip(),
        (rec.get("city") or "").strip(),
    ]
    incident_address = ", ".join(p for p in address_parts if p)

    return {
        "project_id":        project_id,
        "company_id":        company_id,
        "nyc_bin":           nyc_bin,
        "record_type":       "complaint",
        "raw_dob_id":        raw_dob_id,
        "ai_summary":        _fmt_311_summary(rec),
        "severity":          severity,
        "next_action":       _next_action_for_311(rec),
        "dob_link":          (
            f"https://portal.311.nyc.gov/sr-details/?id={unique_key}"
        ),
        "detected_at":       now,
        "created_at":        now,
        "updated_at":        now,
        "is_deleted":        False,
        # 311-shaped extras — keep them on the same document so the
        # frontend timeline shows the same fields as DOB complaints.
        "complaint_number":  unique_key,
        "complaint_type":    ctype or None,
        "complaint_status":  complaint_status,
        # V2.3.A3 PR #9 — normalize via shared helper. Defensive:
        # current production 311 path emits ISO; if NYC ever
        # changes erm2-nwe9's source format, the helper handles it.
        "complaint_date":    _normalize_dob_date_to_iso(rec.get("created_date")),
        "closed_date":       _normalize_dob_date_to_iso(rec.get("closed_date")),
        "description":       (rec.get("descriptor") or "").strip() or None,
        "incident_address":  incident_address or None,
        "complaint_source":  "311",
        "source":            "311",   # extra tag so analytics can split 311 vs DOB
        "agency":            (rec.get("agency") or "").strip() or None,
        "agency_name":       (rec.get("agency_name") or "").strip() or None,
        "resolution_description": (rec.get("resolution_description") or "").strip() or None,
    }


async def _ingest_311_for_project(project: dict, client: "httpx.AsyncClient") -> dict:
    """Fetch + upsert new 311 records for one project. Returns a small stats dict."""
    project_id = str(project.get("_id"))
    company_id = project.get("company_id", "")
    nyc_bin = (project.get("nyc_bin") or "").strip()
    # bbl-first read with nyc_bbl fallback during the step-9.1 transition window.
    bbl = (project.get("bbl") or project.get("nyc_bbl") or "").strip()
    # 311 needs BBL (dataset has no `bin` column) OR an address match.
    # Use the same address parsing the main DOB fetcher uses.
    house_num, street_name = _parse_address_components(project.get("address") or "")
    if not bbl and not (house_num and street_name):
        return {"new": 0, "actions": 0, "skipped": True}

    records = await _fetch_311_for_project(client, bbl, house_num, street_name)
    new_count = 0
    action_count = 0
    now = datetime.now(timezone.utc)

    for rec in records:
        unique_key = str(rec.get("unique_key") or "").strip()
        if not unique_key:
            continue
        raw_dob_id = f"311:{unique_key}"

        # MR.14 (commit 2a) — apply v1-monitoring diffing semantics:
        # most-recent dob_log per raw_dob_id; insert new row only when
        # complaint_status differs. Pre-MR.14 the 311 path skipped any
        # existing row entirely (no update-in-place); now status
        # transitions (Open → In Progress → Closed) become activity-feed
        # events without losing the prior history.
        existing = await db.dob_logs.find_one(
            {"raw_dob_id": raw_dob_id},
            sort=[("detected_at", -1)],
        )

        # V2.3.A3 PR #9 — base dob_log shape built by the pure
        # ``_build_311_doc`` helper (T6.B refactor target). Helper
        # normalizes complaint_date + closed_date via the shared
        # ``_normalize_dob_date_to_iso``.
        doc = _build_311_doc(rec, project, now)
        # severity is needed below (action-count + alert gate); pull
        # it off the doc since the helper computes it.
        severity = doc["severity"]
        # MR.14 (commit 2a) v1-monitoring schema additions.
        # MR.14 (commit 2b) — classifier-driven signal_kind.
        current_status = _extract_dob_log_status(doc)
        doc["current_status"] = current_status
        doc["signal_kind"] = _signal_kind_for(doc)
        doc["read_by_user"] = []

        if existing and existing.get("current_status") == current_status:
            # Status unchanged. The 311 path historically skipped on
            # any existing row — preserve that behavior (don't refresh
            # mutable fields here; 311 records are append-once-then-
            # closed and rarely benefit from updates between polls).
            continue

        # Either first time OR status changed. Stamp transition markers.
        doc["previous_status"] = (
            existing.get("current_status") if existing else None
        )
        doc["status_changed_at"] = now

        # MR.14 commit 4a — stamp is_seed_transition on every 311
        # dob_log write. Same discriminator + reasoning as DOB-side
        # path: synthetic seeds where existing legacy doc lacks the
        # current_status field MUST NOT fire alerts AND must be
        # suppressed in the activity feed by default.
        is_seed_transition_311 = (
            existing is not None
            and "current_status" not in existing
        )
        doc["is_seed_transition"] = is_seed_transition_311

        try:
            await db.dob_logs.insert_one(doc)
            new_count += 1
            if severity == "Action" and not is_seed_transition_311:
                action_count += 1
                # Fire critical alert through the throttled wrapper.
                # Initial-scan suppression here means the very first 311
                # poll for a project quietly backfills the historical
                # complaints without spamming the owner.
                await _send_critical_dob_alert_throttled(project, doc, source="311")

            # V2.3 Commit 6 — predictive inspection surfacing.
            # Spawn a fire-and-forget similar-case correlation
            # only when ALL four suppression conditions are met:
            #
            #   1. existing is None       — truly NEW complaint.
            #      Status transitions (e.g., Open → Closed) also
            #      reach this path via the insert above, but the
            #      complaint itself was seen earlier; any
            #      inspection it triggered may have already
            #      happened, and a status-change prediction would
            #      have lower signal value.
            #   2. not is_seed_transition_311 — synthetic seed
            #      rows (from the V2.2 schema migration) must not
            #      fire predictions.
            #   3. _initial_scan_done — same gate the email
            #      throttler uses. First poll for a project is
            #      historical backfill; predictions on backfill
            #      would surface stale "inspection likely
            #      tomorrow" alerts for complaints from months
            #      ago.
            #   4. severity == "Action" — non-Action 311 categories
            #      (noise, parking) don't correlate with DOB
            #      inspections.
            #
            # Spawn wrapped in try/except so a prediction-side bug
            # never breaks the 311 poll's existing dedup + Mongo
            # write path. The wrapper itself (try_predict_inspection_
            # from_complaint) has its own outer catch-all.
            if (existing is None
                    and not is_seed_transition_311
                    and severity == "Action"
                    and await _initial_scan_done(project_id, "311")):
                try:
                    asyncio.create_task(
                        _stat_engine.try_predict_inspection_from_complaint(
                            db, project, rec,
                        ),
                        name=f"predict_inspection:{project_id}:{unique_key}",
                    )
                except Exception as _e:
                    logger.warning(
                        f"[predict_inspection] task spawn failed for "
                        f"{project_id}:{unique_key}: {_e!r}",
                    )
        except Exception as e:
            # MR.14 (commit 2a) — the legacy unique index on
            # raw_dob_id is being dropped in this commit, so duplicate-
            # key errors should no longer occur. Keeping the swallow
            # for one deploy cycle in case the index drop is delayed.
            msg = str(e).lower()
            if "duplicate key" in msg:
                continue
            logger.warning(
                f"311 insert failed project={project.get('name')} "
                f"unique_key={unique_key}: {e}"
            )

    # Mark the 311 initial scan done for this project so subsequent polls
    # can email when genuinely new complaints show up.
    await _mark_initial_scan_done(project_id, "311")
    return {"new": new_count, "actions": action_count, "skipped": False}


async def _poll_311_fast_complaints() -> None:
    """APScheduler job: poll 311 for every tracked BIN.

    Runs every 30 minutes. Safe to run alongside `dob_nightly_scan` — the two
    hit different datasets (erm2-nwe9 vs eabe-havv) and dedupe by a
    namespaced `raw_dob_id` (`311:<unique_key>` here, bare ID there).
    """
    started = datetime.now(timezone.utc)
    try:
        projects = await db.projects.find({
            "track_dob_status": True,
            "nyc_bin":          {"$exists": True, "$ne": ""},
            **ACTIVE_PROJECT_FILTER,
        }).to_list(500)
    except Exception as e:
        logger.error(f"311 poll: project lookup failed: {e}")
        return

    if not projects:
        logger.info("311 poll: no tracked projects — skip")
        return

    total_new = 0
    total_action = 0
    total_processed = 0
    async with ServerHttpClient(
        headers={"User-Agent": "Levelog/1.0 (311 poller)"},
    ) as client:
        # Cap concurrency so we don't hammer the NYC Open Data endpoint.
        sem = asyncio.Semaphore(5)

        async def _one(p):
            nonlocal total_new, total_action, total_processed
            async with sem:
                try:
                    stats = await _ingest_311_for_project(p, client)
                    if not stats.get("skipped"):
                        total_processed += 1
                        total_new += stats.get("new", 0)
                        total_action += stats.get("actions", 0)
                except Exception as e:
                    logger.warning(
                        f"311 poll project={p.get('name')} failed: {e}"
                    )

        await asyncio.gather(*[_one(p) for p in projects])

    elapsed = (datetime.now(timezone.utc) - started).total_seconds()
    logger.info(
        f"311 poll complete: projects={total_processed} new_records={total_new} "
        f"action_alerts={total_action} elapsed={elapsed:.1f}s"
    )

 
def _classify_filing_system(job_number: Optional[str]) -> str:
    """Classify a permit as DOB_NOW vs BIS based on job number shape.

    Per NYC DOB: DOB NOW Build job filings use a letter prefix
    (B/M/Q/X/R + digits, optional -I<n> suffix), while legacy BIS
    jobs are purely numeric. Drives different auto-extension rules
    in the renewal eligibility engine (BIS = 31-day look-ahead,
    DOB NOW = end-of-day after carrier files COI update).
    """
    if not job_number:
        return "DOB_NOW"  # safe default — most new filings are DOB NOW
    s = str(job_number).strip().upper()
    if s and s[0] in ("B", "M", "Q", "X", "R"):
        return "DOB_NOW"
    if s.replace("-", "").isdigit():
        return "BIS"
    return "DOB_NOW"


# Permit classification → drives renewal strategy (LL48 sheds get a
# parallel 90-day manual track per the Jan 26 2026 service notice).
_SHED_WORK_TYPES = {"SH"}
_FENCE_WORK_TYPES = {"FN"}
_BLDRS_PAVEMENT_WORK_TYPES = {"BL"}


def _classify_permit_class(work_type: Optional[str]) -> str:
    """Map a DOB work_type code to the renewal-strategy permit_class.

    'SH' → sidewalk_shed (90-day cap, PE/RA progress report required)
    'FN' → fence
    'BL' → bldrs_pavement (a BL without an SH on the same job is its
           own permit class — different rules from sheds)
    everything else → standard
    """
    if not work_type:
        return "standard"
    wt = str(work_type).strip().upper()
    if wt in _SHED_WORK_TYPES:
        return "sidewalk_shed"
    if wt in _FENCE_WORK_TYPES:
        return "fence"
    if wt in _BLDRS_PAVEMENT_WORK_TYPES:
        return "bldrs_pavement"
    return "standard"


# ── MR.14 commit 4a — seed-suppression via stored field ──────────
#
# The time-window heuristic from commits 2b/3 (MR14_SEED_WINDOW_START
# + MR14_SEED_WINDOW_DURATION_MIN env vars) is REMOVED. Replaced by
# is_seed_transition: bool stamped at insert time on every dob_log
# write. The discriminator is more durable (works retroactively;
# survives Railway env churn; cheap to index).
#
# Operator action: delete MR14_SEED_WINDOW_START + MR14_SEED_WINDOW_
# DURATION_MIN from Railway. They no longer affect anything.


# ── MR.14 (commit 2a) — dob_logs status diffing helpers ──────────────
#
# v1 monitoring-product invariant (operator F5): each poll diffs the
# incoming record's status against the most-recent dob_logs entry
# for the same raw_dob_id. New row created ONLY when status differs.
# previous_status + status_changed_at on the new row record the
# transition; the activity feed reads these as "this just changed"
# events.
#
# Status field name varies per record_type (each Socrata dataset
# uses different conventions — DOB NOW Build's `permit_status`,
# DOB Inspections' `inspection_result`, etc.). The map below
# normalizes which field to read; _extract_dob_log_status returns
# the universal current_status string for the diffing comparator.

DOB_RECORD_TYPE_STATUS_FIELDS: Dict[str, str] = {
    "permit":       "permit_status",       # rbx6-tga4 / dm9a-ab7w / ipu4-2q9a
    "violation":    "status",              # _extract_violation_fields composes
    "complaint":    "complaint_status",    # eabe-havv (DOB) and erm2-nwe9 (311) both
    "inspection":   "inspection_result",   # p937-wjvj — None for scheduled-not-yet-done
    "swo":          "status",              # SWO is a violation subtype; same field
    "job_status":   "filing_status",       # w9ak-ipjd
    # MR.14 (commit 2b) new record types — extras populate
    # `current_status` directly (the extractor already normalizes
    # the source-dataset's status field). Map points at
    # current_status for these so the diffing comparator stays
    # uniform across all record_types.
    "cofo":         "current_status",      # pkdm-hqz6
    "facade_fisp":  "current_status",      # xubg-57si
    "boiler":       "current_status",      # 52dp-yji6
    "elevator":     "current_status",      # e5aq-a4j2
}


def _signal_kind_for(dob_log: dict) -> str:
    """Module-level shim around lib.dob_signal_classifier.classify_signal_kind.
    Insertion sites call this without importing the helper directly,
    so test fixtures can monkey-patch the classifier on the server
    module surface."""
    from lib.dob_signal_classifier import classify_signal_kind
    return classify_signal_kind(dob_log)


def _extract_dob_log_status(dob_log: dict) -> Optional[str]:
    """Return the universal current_status for diffing. Reads the
    record-type-appropriate field per DOB_RECORD_TYPE_STATUS_FIELDS.

    Returns:
      - normalized string (uppercased + stripped) for non-empty values
      - None when the field is absent / empty / unknown record_type

    Caller persists the returned value on the dob_log doc as
    `current_status` so future polls can diff without re-parsing
    the dataset-specific field name.
    """
    rt = (dob_log.get("record_type") or "").lower().strip()
    field = DOB_RECORD_TYPE_STATUS_FIELDS.get(rt)
    if not field:
        return None
    val = dob_log.get(field)
    if val is None:
        return None
    s = str(val).strip()
    if not s:
        return None
    return s.upper()


# ─── V2.3.A3 PR #9 — Date format normalization ────────────────────

# Regex pre-detection for the three date format families dob_logs
# stores. Compiled once at module load.
_ISO_DATE_ONLY_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")
_ISO_WITH_TIME_RE = re.compile(
    r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?$"
)
_MDY_DATE_RE = re.compile(r"^([0-9]{1,2})/([0-9]{1,2})/([0-9]{4})$")


def _normalize_dob_date_to_iso(raw):
    """V2.3.A3 PR #9 — heterogeneous date format helper.

    Normalizes ``complaint_date`` / ``closed_date`` inputs to the
    canonical dob_logs storage format ``%Y-%m-%dT%H:%M:%S.000``
    (B1.a / B1.b locked format). Idempotent on already-canonical
    inputs.

    Accepts:
      • ISO with ms suffix    ``"2025-06-04T12:30:45.000"``  → passthrough
      • ISO without ms        ``"2025-06-04T12:30:45"``      → append ``.000``
      • ISO date-only         ``"2025-06-04"``               → expand to midnight + ``.000``
      • MDY zero-padded       ``"06/04/2025"``               → ``"2025-06-04T00:00:00.000"``
      • MDY single-digit      ``"6/4/2025"``                 → ``"2025-06-04T00:00:00.000"``
      • ``None`` / ``""`` / whitespace                       → ``None``
      • Malformed                                            → log WARNING + ``None``

    PR #9 Stage 1.5 Query B found 22% of production complaint_date
    values stored as MDY (50 records, all on the DOB-path eabe-havv
    via ``_extract_complaint_fields``). The aggregate pipeline in
    ``count_own_building_events`` uses lexicographic ``$gte``
    comparison which silently rejected MDY records since
    ``'0' (0x30) < '2' (0x32)``. This helper normalizes on write so
    the aggregate filter operates on uniform ISO strings.

    Stage 2 T2.C: malformed inputs emit a WARNING log line that
    references the raw value (strict-but-visible — bad source data
    stays out of dob_logs while operators still see new format
    surfaces in logs).
    """
    if raw is None:
        return None
    if not isinstance(raw, str):
        raw = str(raw)
    raw = raw.strip()
    if not raw:
        return None

    # ISO date-only — expand to midnight
    if _ISO_DATE_ONLY_RE.match(raw):
        return raw + "T00:00:00.000"

    # ISO with time — canonicalize ms suffix
    if _ISO_WITH_TIME_RE.match(raw):
        if "." in raw:
            return raw  # already canonical
        return raw + ".000"

    # MDY — parse + canonicalize to midnight ISO
    m = _MDY_DATE_RE.match(raw)
    if m:
        mo, dy, yr = m.groups()
        try:
            return datetime(int(yr), int(mo), int(dy)).strftime(
                "%Y-%m-%dT00:00:00.000"
            )
        except ValueError:
            # e.g., "13/45/2025" — month/day out of range; fall
            # through to the malformed branch below.
            pass

    # Malformed — warn + None
    logger.warning(
        f"[_normalize_dob_date_to_iso] Unrecognized date format: "
        f"{raw!r} — returning None"
    )
    return None


