def _extract_job_status_fields(rec: dict) -> dict:
    """Extract filing-status fields from DOB NOW Job Application
    Filings (w9ak-ipjd). The dataset's status column is
    `filing_status` (e.g. 'Approved', 'Disapproved', 'Withdrawn',
    'Pending'). Pre-MR.14 this dataset's records were inserted
    without an extras-extractor, so filing_status didn't survive
    onto dob_logs and couldn't be diffed."""
    fields = {}
    fields["filing_status"] = (
        rec.get("filing_status")
        or rec.get("current_filing_status")
        or rec.get("job_status")
        or None
    )
    fields["job_filing_number"] = rec.get("job_filing_number") or rec.get("job__") or None
    # current_status_date is DOB NOW's "Filing Status Date" — WHEN the filing
    # reached its current status (what DOB NOW shows). Read it FIRST so a filing
    # displays its real status date, not the original filing_date and never the
    # ingest date (today). The display uses filing_date for the job_status row.
    fields["filing_date"] = rec.get("current_status_date") or rec.get("filing_date") or rec.get("latest_action_date") or None
    fields["job_type"] = rec.get("job_type") or None
    fields["job_description"] = rec.get("job_description") or None
    return {k: str(v).strip() if v else None for k, v in fields.items()}


def _extract_permit_fields(rec: dict) -> dict:
    """Extract structured permit fields from raw DOB record.

    Also derives `filing_system` and `permit_class` so the renewal
    engine can branch without re-parsing the job number on every
    eligibility check. Both are deterministic functions of job# and
    work_type; storing them lets us index on them later.
    """
    fields = {}
    # DOB NOW permits (rbx6-tga4)
    fields["permit_type"] = rec.get("permit_type") or rec.get("permittee_s_license_type") or None
    fields["permit_subtype"] = rec.get("permit_subtype") or rec.get("work_type") or None
    # Read the real DOB status field per dataset — never leave it null to render
    # a fabricated "Unknown". rbx6-tga4 / ipu4-2q9a use `permit_status`; DOB NOW
    # Electrical (dm9a-ab7w) carries its state in `filing_status` / `job_status`,
    # which the old read missed → electrical permits showed with no real status.
    fields["permit_status"] = (
        rec.get("permit_status") or rec.get("filing_status") or rec.get("job_status")
        or rec.get("current_status") or rec.get("status") or None
    )
    fields["expiration_date"] = rec.get("expiration_date") or rec.get("permit_expiration_date") or rec.get("expired_date") or None
    # dm9a-ab7w (Electrical) names its issuance `permit_issued_date`.
    fields["issuance_date"] = rec.get("issuance_date") or rec.get("issued_date") or rec.get("permit_issued_date") or rec.get("permit_si_issuance_date") or None
    fields["filing_date"] = rec.get("filing_date") or rec.get("pre_filing_date") or rec.get("latest_action_date") or None
    fields["job_number"] = rec.get("job__") or rec.get("job_filing_number") or rec.get("job_number") or None
    fields["job_type"] = rec.get("job_type") or rec.get("filing_reason") or None
    fields["work_type"] = rec.get("work_type") or rec.get("permit_type") or None
    cleaned = {k: str(v).strip() if v else None for k, v in fields.items()}
    # Derived classification — must come AFTER cleanup so we read
    # the same trimmed values the rest of the pipeline persists.
    cleaned["filing_system"] = _classify_filing_system(cleaned.get("job_number"))
    cleaned["permit_class"] = _classify_permit_class(cleaned.get("work_type"))
    return cleaned
 
 
def _classify_violation_subtype(rec: dict) -> str:
    """Classify violation into sub-type: SWO_FULL, SWO_PARTIAL, VACATE_FULL, VACATE_PARTIAL, COMM_ORDER, ECB, NOV."""
    vtype = str(rec.get("violation_type") or rec.get("violation_type_code") or "").upper()
    desc = str(rec.get("description") or rec.get("violation_description") or "").upper()
    record_type = str(rec.get("_record_type") or "").lower()
    ecb_num = rec.get("ecb_violation_number") or ""

    combined = f"{vtype} {desc}"

    # Stop-work detection keyed on DOB's REAL phrasing, not just the literal
    # "FULL STOP WORK". A borough-commissioner order reads "…ORDERED ALL WORK
    # STOPPED…", which the old check missed → it fell through to COMM_ORDER and
    # ranked below open violations. record_type=='swo' still forces stop-work.
    stop_work = record_type == "swo" or any(p in combined for p in (
        "STOP WORK", "WORK STOPPED", "WORK SHALL NOT RESUME",
        "CEASE ALL WORK", "WORK SHALL STOP",
    ))
    if stop_work:
        return "SWO_PARTIAL" if "PARTIAL" in combined else "SWO_FULL"
    if "FULL VACATE" in combined:
        return "VACATE_FULL"
    if "PARTIAL VACATE" in combined or "VACATE" in combined:
        return "VACATE_PARTIAL"
    if "COMMISSIONER" in combined or "COMM ORDER" in combined:
        return "COMM_ORDER"
    if ecb_num or "ECB" in combined:
        return "ECB"
    return "NOV"


def _classify_resolution_state(rec: dict) -> str:
    """Derive resolution state from violation record fields."""
    cert_status = str(rec.get("certification_status") or "").upper()
    current_status = str(rec.get("current_status") or "").upper()
    category = str(rec.get("violation_category") or "").upper()
    # 855j-jady (DOB NOW Safety) carries its state in `violation_status`
    # ("Active" / "Disputed Successfully" / "Cured" / "Resolved") — a field
    # neither current_status nor violation_category exposes, so a won dispute
    # ("Disputed Successfully") read as OPEN until this was added.
    vstatus = str(rec.get("violation_status") or "").upper()
    hearing = rec.get("hearing_date_time") or rec.get("hearing_date") or ""
    disp_date = rec.get("disposition_date") or ""

    # Match DOB's actual status words, not a longer guess. BIS writes
    # `violation_category` as "V-DOB VIOLATION - ACTIVE" / "... RESOLVE" /
    # "... DISMISS" — note RESOLVE has no trailing D, so the old
    # `"RESOLVED" in current_status` check never fired. And on the raw Socrata
    # record `current_status` is empty; the real state lives in
    # `violation_category`. So the resolved/dismissed reads MUST consult
    # `category`, using substrings that DOB itself uses.
    if any(w in cert_status for w in ["CERTIFIED", "CERTIFICATE", "RESOLVE"]):
        return "certified"
    if "DISMISS" in current_status or "DISMISS" in category:
        return "dismissed"
    # A successful dispute (DOB NOW) resolves the violation in the owner's
    # favor. Match the FULL phrase — "Disputed Unsuccessfully" stays open.
    if "DISPUTED SUCCESSFULLY" in vstatus:
        return "resolved"
    if any(w in current_status for w in ["PAID", "SATISFIED"]):
        return "paid"
    if (any(w in current_status for w in ["RESOLVE", "CLOSED", "RESCIND"])
            or any(w in category for w in ["RESOLVE", "CLOSED", "RESCIND"])
            or any(w in vstatus for w in ["RESOLVE", "CLOSED", "CURED", "COMPLIED"])):
        return "resolved"
    if "CURE" in cert_status or "CURE" in current_status:
        return "cure_pending"
    if hearing:
        try:
            from dateutil import parser as dateparser
            h_date = dateparser.parse(str(hearing))
            if h_date.tzinfo is None:
                h_date = h_date.replace(tzinfo=timezone.utc)
            if h_date > datetime.now(timezone.utc):
                return "hearing_scheduled"
            return "hearing_past"
        except Exception:
            return "hearing_scheduled"
    return "open"


def _classify_notice_type(rec: dict) -> Optional[str]:
    """Classify violation notice type from description and violation_type fields."""
    desc = str(rec.get("description") or rec.get("violation_description") or "").upper()
    vtype = str(rec.get("violation_type") or rec.get("violation_type_code") or "").upper()
    combined = f"{vtype} {desc}"

    if "COMMISSIONER" in combined and "ORDER" in combined:
        return "commissioners_order"
    if "PADLOCK" in combined:
        return "padlock_order"
    if "EMERGENCY" in combined and ("DECLARATION" in combined or "ORDER" in combined):
        return "emergency_declaration"
    if "NOTICE OF DEFICIENCY" in combined or "NOD" in combined:
        return "notice_of_deficiency"
    if "LETTER OF DEFICIENCY" in combined or "LOD" in combined:
        return "letter_of_deficiency"
    return None


def _extract_compliance_deadline(rec: dict) -> Optional[str]:
    """Attempt to extract a compliance deadline from disposition comments or description."""
    from dateutil import parser as dateparser
    import re

    text = f"{rec.get('disposition_comments', '') or ''} {rec.get('description', '') or ''}"
    # Look for patterns like "comply by MM/DD/YYYY", "deadline: MM/DD/YYYY", "within 30 days"
    date_patterns = [
        r'comply by\s+(\d{1,2}/\d{1,2}/\d{2,4})',
        r'deadline[:\s]+(\d{1,2}/\d{1,2}/\d{2,4})',
        r'before\s+(\d{1,2}/\d{1,2}/\d{2,4})',
        r'by\s+(\d{1,2}/\d{1,2}/\d{2,4})',
        r'cure by\s+(\d{1,2}/\d{1,2}/\d{2,4})',
    ]
    for pattern in date_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            try:
                deadline = dateparser.parse(match.group(1))
                return deadline.strftime("%Y-%m-%d")
            except Exception:
                continue
    return None


def _cycle_date_from_violation_number(num) -> Optional[str]:
    """LAST-RESORT date proxy: DOB NOW violation numbers embed a 6-digit
    filing-cycle token (YYYYMM), e.g. VIO-FTF-PL-PER-202412-0186052 -> 2024-12.

    This is the filing CYCLE, not the issue date — the two can differ by many
    months (that very record's real violation_issue_date is 2026-01-08, 13
    months off its 202412 cycle). So it is used ONLY when DOB carries no real
    date field at all, purely so a dateless row reads/sorts with an approximate
    period instead of the ingest date (today). Returns 'YYYY-MM-01' or None.
    Plausibility-gated (year 2000-2099, month 01-12) so a stray 6-digit
    sequence/ISN is not mistaken for a date."""
    if not num:
        return None
    import re as _re
    for tok in _re.findall(r'(?<!\d)(\d{6})(?!\d)', str(num)):
        yr, mo = int(tok[:4]), int(tok[4:])
        if 2000 <= yr <= 2099 and 1 <= mo <= 12:
            return f"{yr:04d}-{mo:02d}-01"
    return None


def _extract_violation_fields(rec: dict) -> dict:
    """Extract structured violation fields from raw DOB record."""
    fields = {}
    fields["violation_type"] = rec.get("violation_type") or rec.get("violation_type_code") or rec.get("severity") or None
    # Build a display-friendly violation number from whichever source
    fields["violation_number"] = rec.get("ecb_violation_number") or rec.get("violation_number") or rec.get("number") or rec.get("isn_dob_bis_viol") or None
    fields["violation_category"] = rec.get("violation_category") or rec.get("category") or None
    # 855j-jady (DOB NOW Safety) names its date field `violation_issue_date`;
    # BIS/ECB use `issue_date`. Without the DOB NOW name here, those rows land
    # with violation_date=None and the UI falls back to the ingest date (today).
    # NOTE: do NOT parse the "202412" in the violation number as the date — that
    # is a filing-cycle code, not the issue date (this record proves it: id
    # cycle 202412 vs real violation_issue_date 2026-01-08).
    fields["violation_date"] = rec.get("issue_date") or rec.get("violation_issue_date") or rec.get("violation_date") or rec.get("issued_date") or rec.get("infraction_date") or None
    if not fields["violation_date"]:
        # Only when DOB has NO real date field: approximate from the filing-cycle
        # token in the violation number (YYYYMM). Approximate, never today.
        fields["violation_date"] = _cycle_date_from_violation_number(fields.get("violation_number"))
    # 855j-jady (DOB NOW Safety) has NO `description` field — its readable
    # content is device_type + violation_remarks, so FTF-PL-PER-class rows
    # otherwise ingest with a blank description. Compose from those when the
    # standard fields are absent so the code isn't shown bare.
    fields["description"] = (
        rec.get("description") or rec.get("violation_description")
        or rec.get("infraction_codes")
        or " — ".join(p for p in (rec.get("device_type"), rec.get("violation_remarks")) if p)
        or None
    )
    fields["penalty_amount"] = rec.get("penalty_applied") or rec.get("penalty_balance_due") or rec.get("amount_paid") or None
    fields["respondent"] = rec.get("respondent_name") or rec.get("respondent") or None
    fields["disposition_date"] = rec.get("disposition_date") or rec.get("hearing_date_time") or None
    fields["disposition_comments"] = rec.get("disposition_comments") or rec.get("hearing_status") or None
    fields["status"] = rec.get("violation_category") or rec.get("violation_status") or rec.get("certification_status") or rec.get("current_status") or None
    fields["violation_subtype"] = _classify_violation_subtype(rec)
    fields["resolution_state"] = _classify_resolution_state(rec)
    fields["notice_type"] = _classify_notice_type(rec)
    fields["compliance_deadline"] = _extract_compliance_deadline(rec)
    return {k: str(v).strip() if v else None for k, v in fields.items()}


def _extract_complaint_fields(rec: dict) -> dict:
    """Extract structured complaint fields from DOB Complaints Received (eabe-havv)."""
    fields = {}
    fields["complaint_number"] = rec.get("complaint_number") or None
    fields["complaint_type"] = rec.get("complaint_category") or None
    fields["complaint_status"] = rec.get("status") or None
    # eabe-havv `unit` = the DOB unit assigned to the complaint (e.g. "OBM").
    # This is a UNIT code, not a named inspector — surfaced as "ASSIGNED TO"
    # (labeled as the unit, never implying a person). 311 records don't reach
    # this extractor, so they carry no complaint_unit.
    fields["complaint_unit"] = rec.get("unit") or None
    # V2.3.A3 PR #9 — normalize MDY → ISO at ingestion time. Stage 1.5
    # Query B found 50 production complaints stored as MDY via this
    # path. T3.B: closed_date also normalized for symmetry with the
    # 311 path's hygiene + so a single record never carries one ISO
    # date and one MDY date.
    fields["complaint_date"] = _normalize_dob_date_to_iso(rec.get("date_entered"))
    fields["closed_date"] = _normalize_dob_date_to_iso(rec.get("disposition_date"))
    # Build rich description from code lookups
    category = rec.get("complaint_category") or ""
    disposition_code = rec.get("disposition_code") or ""
    fields["description"] = get_category_label(category) if category else None
    fields["disposition_code"] = disposition_code or None
    # Address
    house = rec.get("house_number") or ""
    street = rec.get("house_street") or ""
    fields["incident_address"] = f"{house} {street}".strip() if (house or street) else None

    # Sprint 1: Classify complaint and persist rich data
    result = classify_complaint(rec)
    fields["risk_level"] = result.get("risk_level")
    fields["disposition_label"] = result.get("disposition_label")
    fields["category_label"] = result.get("category_label")

    # Derived: complaint_source — from the ACTUAL source dataset, never inferred
    # from `community_board`. That was a location field present on virtually
    # every DOB complaint (e.g. "303"), so the old `if community_board` branch
    # stamped "Neighbor/Community Complaint" on almost everything, discarding the
    # record's real category. eabe-havv IS DOB Complaints Received; erm2-nwe9 is
    # 311. Unknown dataset → no fabricated source (the real complaint_category /
    # disposition carry the record's identity).
    _ds = str(rec.get("_dataset") or "")
    if _ds == "erm2-nwe9":
        fields["complaint_source"] = "311 Complaint"
    elif _ds == "eabe-havv":
        fields["complaint_source"] = "DOB Complaint"
    else:
        fields["complaint_source"] = None

    # Derived: inspector_unit
    disp_code = (disposition_code or "").strip()
    import re as _re
    if _re.match(r'^(D[1-9]|E[A-D])$', disp_code):
        fields["inspector_unit"] = result.get("disposition_label")
    else:
        fields["inspector_unit"] = None

    # Derived: what_to_expect
    if _re.match(r'^A[1-9]$', disp_code):
        fields["what_to_expect"] = "Inspector will visit within 1-5 business days"
    elif _re.match(r'^D[1-9]$', disp_code):
        unit_name = result.get("disposition_label", "specialized unit")
        fields["what_to_expect"] = f"Inspector from {unit_name} will visit within 1-5 business days"
    elif _re.match(r'^I[1-5]$', disp_code):
        fields["what_to_expect"] = "Respond before hearing date — cure or pay penalty"
    elif _re.match(r'^I[6-9]$', disp_code):
        fields["what_to_expect"] = "All covered work must cease immediately"
    elif _re.match(r'^C[1-9]$', disp_code):
        fields["what_to_expect"] = "Inspector will return — ensure site is accessible"
    elif _re.match(r'^[ZR][1-9]$', disp_code):
        fields["what_to_expect"] = "No further action needed"
    elif _re.match(r'^E[A-D]$', disp_code):
        fields["what_to_expect"] = "Inspector will visit within 1-5 business days"
    else:
        fields["what_to_expect"] = "Review complaint status on DOB BIS"

    return {k: str(v).strip() if v else None for k, v in fields.items()}


# DOB_JOB_PREFIX_CATEGORY / _decode_job_prefix REMOVED (COMMIT 1, 2026-07-25).
# The map decoded a job_id's 2-letter prefix into a trade category, but its
# only live caller was the p937-wjvj (rodent) inspection ingest, where the
# "PC" (Pest Control) prefix was fabricated into "Plumbing". Real DOB job
# numbers never hit the map (trade lives in a separate `work_type` field, not
# a number prefix), so with rodent ingest gone this had zero valid callers.


def _base_job_number(job_id: str) -> str:
    """Strip DOB filing sequence suffix so renewals collapse to one
    permit. 'B00834550-I1' → 'B00834550'. 'B00834550-I2' → 'B00834550'.
    Legacy numeric BIS jobs (e.g. '101220923') pass through unchanged.

    DOB NOW issues a fresh `job_filing_number` for every renewal of the
    same underlying permit. Without this collapse, the UI shows every
    historical filing — including long-expired ones that have already
    been renewed — as if they were separate live permits.
    """
    if not job_id:
        return ""
    import re as _re
    s = str(job_id).strip().upper()
    # DOB NOW: letter + digits, optional -I<digits> suffix
    m = _re.match(r'^([A-Z]\d+)(?:-[A-Z]\d+)?$', s)
    if m:
        return m.group(1)
    # BIS legacy: leading run of digits (strip any trailing letters)
    m = _re.match(r'^(\d+)', s)
    if m:
        return m.group(1)
    return s


def _extract_inspection_fields(rec: dict) -> dict:
    """Extract structured inspection fields. DEAD PATH — the inspection
    (p937-wjvj rodent) ingest was removed in COMMIT 1; this is retained only
    because the ingest dispatch still references it (harmless with no data,
    separate cleanup). The job-prefix → trade-category enrichment was removed
    with the rodent ingest: it fabricated "Plumbing" from the p937-wjvj "PC"
    (Pest Control) prefix via the deleted DOB_JOB_PREFIX_CATEGORY decoder.
    """
    fields = {}
    fields["inspection_date"] = rec.get("inspection_date") or rec.get("approved_date") or None

    raw_phase = rec.get("inspection_type") or rec.get("inspection_category") or rec.get("job_progress") or None
    job_id = rec.get("job_id") or rec.get("job_filing_number") or rec.get("job_number") or rec.get("job__") or None

    fields["inspection_type"] = str(raw_phase).strip() if raw_phase else None
    fields["inspection_category"] = None
    fields["inspection_phase"] = str(raw_phase).strip() if raw_phase else None

    fields["inspection_result"] = rec.get("result") or rec.get("inspection_result") or None
    fields["inspection_result_description"] = rec.get("result_description") or rec.get("comments") or None
    fields["linked_job_number"] = job_id
    return {k: str(v).strip() if v else None for k, v in fields.items()}


def _determine_severity(rec: dict, record_type: str) -> str:
    """Determine severity: 'Action' (needs attention) or 'Good' (no action needed)."""
    if record_type == "permit":
        exp = rec.get("expiration_date") or rec.get("permit_expiration_date") or rec.get("expired_date") or ""
        if exp:
            try:
                from dateutil import parser as dateparser
                exp_date = dateparser.parse(str(exp))
                if exp_date.tzinfo is None:
                    exp_date = exp_date.replace(tzinfo=timezone.utc)
                days_left = (exp_date - datetime.now(timezone.utc)).days
                if days_left <= 30:
                    return "Action"
            except Exception:
                pass
        status = str(rec.get("permit_status") or rec.get("current_status") or "").lower()
        if "expired" in status or "revoked" in status:
            return "Action"
        return "Good"

    if record_type in ("violation", "swo"):
        # Check if dismissed/resolved — should be filtered out, but just in case
        cat = str(rec.get("violation_category", "") or "").upper()
        status = str(rec.get("certification_status", "") or rec.get("current_status", "") or "").upper()
        if any(word in cat for word in ["DISMISSED", "RESOLVED"]):
            return "Good"
        if any(word in status for word in ["RESOLVED", "DISMISSED", "CLOSED", "CERTIFIED"]):
            return "Good"
        return "Action"

    if record_type == "inspection":
        result = str(rec.get("result") or rec.get("inspection_result") or "").upper()
        if "FAIL" in result:
            return "Action"
        return "Good"

    if record_type == "cofo":
        # A certificate of occupancy is never an alert.
        #
        # This branch changes no behavior — cofo already reached the
        # terminal `return "Good"` below. It reached it by ACCIDENT, the
        # same way an unknown record_type does, and the point of writing
        # it down is that the next person to touch this function should
        # have to argue with a decision instead of inheriting a
        # fallthrough.
        #
        # The argument. `severity` is a strict binary. "Action" is the
        # ONLY input to _send_critical_dob_alert_throttled (see the two
        # call sites in run_dob_sync_for_project) and renders as a red
        # "Action Needed" dot on the DOB logs card
        # (frontend/app/project/[id]/dob-logs.jsx getSevConfig). There is
        # no "notable but not urgent" value to reach for, so the choice
        # is: page the operator, or don't.
        #
        # Don't. Every one of pkdm-hqz6's 81,264 rows is a certificate
        # that WAS issued — c_of_o_status is the constant 'CO Issued',
        # there is no pending, expired or revoked state in this dataset.
        # Nothing in it asks the GC to do anything, and a final CO is
        # good news; labelling a completion "Action Needed" would be a
        # false statement on the card as well as an unwanted email.
        #
        # The one CofO event that WOULD be actionable — a temporary CO
        # about to lapse, after which the building may not be occupied —
        # cannot be detected from here at all: the dataset has no
        # expiration column, which is why 7c4f983 dropped
        # `expiration_date` rather than persisting a permanent None.
        # Inventing an "Action" we cannot substantiate would be worse
        # than declining to raise one.
        #
        # A completion is surfaced through `signal_kind`, which exists to
        # say what happened (now correctly cofo_final vs cofo_temporary —
        # see lib/dob_signal_classifier._classify_cofo). `severity` exists
        # to wake someone up. Reported, not fixed:
        # frontend/src/constants/signalKinds.js gives cofo_final
        # defaultSeverity 'critical', which disagrees with the backend
        # template's SEVERITY_INFO.
        return "Good"

    if record_type == "complaint":
        result = classify_complaint(rec)
        return result["severity"]
    return "Good"
 
 
def _generate_summary(rec: dict, record_type: str) -> str:
    """Generate a human-readable summary from raw fields without AI."""
    if record_type == "permit":
        job = rec.get("job__") or rec.get("job_filing_number") or "Unknown"
        ptype = rec.get("work_type") or rec.get("permit_type") or rec.get("filing_reason") or "General"
        status = rec.get("permit_status") or rec.get("current_status") or "Unknown"
        exp = rec.get("expiration_date") or rec.get("permit_expiration_date") or rec.get("expired_date") or ""
        summary = f"Permit {job} ({ptype}) — Status: {status}"
        if exp:
            summary += f" — Expires: {str(exp)[:10]}"
        return summary
 
    if record_type in ("violation", "swo"):
        vnum = rec.get("violation_number") or rec.get("number") or rec.get("ecb_violation_number") or "Unknown"
        # Violation-type codes have no verified official label yet → rendered
        # "DOB code: {code}" (never a bare code, never a guessed label); DOB's
        # own plain-English ECB values pass through as-is.
        vtype = violation_type_display(rec.get("violation_type") or rec.get("violation_type_code") or "")
        desc = rec.get("description") or rec.get("violation_description") or rec.get("infraction_codes") or ""
        if desc and len(str(desc)) > 120:
            desc = str(desc)[:117] + "..."
        vtype_part = f": {vtype}" if vtype else ""
        return f"Violation {vnum}{vtype_part}. {desc}".strip()
 
    if record_type == "complaint":
        comp_num = rec.get("complaint_number") or ""
        result = classify_complaint(rec)
        CATEGORY_DESCRIPTIONS = {
            "01": "illegal work or work without a permit",
            "03": "failure to maintain building facade",
            "05": "work contrary to approved plans",
            "06": "unsafe construction condition",
            "09": "illegal conversion or occupancy",
            "12": "failure to maintain elevator",
            "14": "demolition without permit",
            "23": "working without a safety net",
            "28": "illegal curb cut or sidewalk damage",
            "30": "debris falling from building",
            "45": "unsafe scaffolding or sidewalk shed",
            "49": "construction noise outside allowed hours",
            "59": "work without required DOB inspection",
            "63": "illegal fence or retaining wall",
            "71": "crane or derrick safety violation",
            "83": "failure to safeguard persons or property",
            "91": "building under construction in unsafe condition",
        }
        cat_code = rec.get("complaint_category", "")
        desc = CATEGORY_DESCRIPTIONS.get(cat_code, result['category_label'])
        summary = f"Complaint about {desc.lower()}. {result['disposition_label']}."
        if comp_num:
            summary = f"#{comp_num}: {summary}"
        return summary
 
    if record_type == "inspection":
        # DEAD PATH — inspection (p937-wjvj rodent) ingest removed in COMMIT 1.
        # The job-prefix → trade-category enrichment ("Plumbing …") was removed
        # with the decoder; phase-only label retained for the harmless dead path.
        phase = rec.get("inspection_type") or rec.get("job_progress") or ""
        job = rec.get("job_id") or rec.get("job_filing_number") or rec.get("job_number") or ""
        result = rec.get("result") or rec.get("inspection_result") or "Pending"
        label = f"{phase} Inspection" if phase else "Inspection"
        job_str = f" (Job {job})" if job else ""
        return f"{label}{job_str} — Result: {result}"

    if record_type == "job_status":
        job = rec.get("job__") or "Unknown"
        jtype = rec.get("job_type") or ""
        desc = rec.get("job_description") or rec.get("job_s1_special_place_name") or ""
        if desc and len(str(desc)) > 100:
            desc = str(desc)[:97] + "..."
        return f"Job {job} ({jtype}): {desc}".strip()
 
    return f"DOB record detected"
 
 
def _generate_next_action(rec: dict, record_type: str, severity: str) -> str:
    """Generate next action from raw fields."""
    if record_type == "permit":
        status = str(rec.get("permit_status") or rec.get("current_status") or "").lower()
        if "expired" in status:
            return "URGENT: Permit has expired. File renewal application on DOB NOW immediately."
        if severity == "Action":
            exp = rec.get("expiration_date") or rec.get("permit_expiration_date") or rec.get("expired_date") or ""
            return f"Permit expiring {str(exp)[:10]}. Contact expediter to file renewal on DOB NOW before expiration."
        return "Permit is active and current. No action needed."

    if record_type in ("violation", "swo"):
        vtype = str(rec.get("violation_type", "") or rec.get("violation_type_code", "")).lower()
        if "stop work" in vtype or "swo" in vtype:
            return "STOP ALL WORK. Contact DOB and your attorney immediately to resolve SWO."
        if severity == "Action":
            return "Active violation. Contact your expediter and schedule correction with DOB."
        return "Violation resolved. No action needed."

    if record_type == "inspection":
        result = str(rec.get("result") or rec.get("inspection_result") or "").upper()
        if "FAIL" in result:
            return "Failed inspection. Review deficiencies and schedule re-inspection on DOB NOW."
        if "PARTIAL" in result:
            return "Partial pass. Address noted deficiencies and request follow-up inspection."
        return "Inspection passed. No action needed."

    if record_type == "complaint":
        result = classify_complaint(rec)
        return result["action"]

    return "Review record details on DOB BIS/NOW portal."
 
 
def _is_dob_now_job(job_num: str) -> bool:
    """True iff the job number's leading non-digit is a letter — DOB NOW
    job numbers start with a borough letter (B, M, Q, X, R, etc.).
    Purely numeric ids are BIS legacy. Empty → False.
    """
    s = str(job_num or "").strip()
    if not s:
        return False
    return s[0].isalpha()


def _bis_bin_overview_url(bin_val: str) -> str:
    """BIS building overview by BIN — the safe BIN-scoped fallback.

    Uses PropertyProfileOverviewServlet with a plain `bin` param. This is the
    form the frontend's own "verify your BIN" link already uses successfully
    (frontend/app/project/[id]/dob-logs.jsx), and the form this file's final
    fallback used, so it is the proven-good shape.

    It replaces an earlier `OverviewByBinServlet?requestid=2&allbin=<bin>
    &allinquirytype=BXS3OCV4` form which returned BIS "Page not found". The
    `allinquirytype` value there was a hardcoded opaque token (no record field
    was ever mapped into it), and no other call site depended on that shape.

    NOTE: this is a deeplink builder — it returns a URL as data for the user's
    browser. The backend is firewalled from a810-bisweb (see
    lib/server_http.py AKAMAI_BLOCKED_HOSTS), so this is never fetched
    server-side and cannot be validated from here.
    """
    if not bin_val:
        return ""
    return (
        "https://a810-bisweb.nyc.gov/bisweb/PropertyProfileOverviewServlet"
        f"?bin={quote_plus(str(bin_val))}"
    )


def _open_data_filtered_url(dataset_id: str, column: str, value: str) -> str:
    """Build an Open Data filtered-view URL. This is the only public
    URL-param-respecting surface for DOB NOW specific records — the
    DOB NOW Public Portal is a client-side SPA whose deep-links the
    server doesn't honor, and the BIS `JobsQueryByNumberServlet`
    returns 'not found' for B-prefix jobs because DOB NOW jobs don't
    exist in BIS.
    """
    if not (dataset_id and column and value):
        return ""
    return (
        f"https://data.cityofnewyork.us/resource/{dataset_id}.html"
        f"?{quote_plus(column)}={quote_plus(str(value))}"
    )


def _build_dob_link(rec: dict, record_type: str) -> str:
    """Build a public URL that actually resolves to the record.

    Routing, by record type:
      - permit / job_status
          Always → PropertyProfileOverviewServlet by BIN. DOB NOW filings
          have no public per-record URL (login-walled SPA) and are not in
          BIS; legacy BIS-numeric permits share the same BIN profile. No BIN
          → no link.
      - violation
          ecb_violation_number → ECBQueryByNumberServlet
          isn + bin + number   → ActionViolationDisplayServlet
          else                 → PropertyProfileOverviewServlet by BIN
      - swo → ComplaintsByAddressServlet by BIN (else no link)
      - complaint
          complaint_number → OverviewForComplaintServlet; 311 unique_key →
          no link; else → ComplaintsByAddressServlet by BIN
      - inspection (ingest removed 2026-07-25; branch retained)
          DOB NOW job_id → Open Data p937-wjvj; legacy →
          JobsQueryByNumberServlet; else → PropertyProfileOverviewServlet
      - Fallback → PropertyProfileOverviewServlet by BIN

    Every BIN fallback routes through the single _bis_bin_overview_url helper
    (PropertyProfileOverviewServlet?bin=), the confirmed-live building page.
    The old OverviewByBinServlet form is decommissioned by DOB (BIS "Page not
    found") and must not be reintroduced — SourceInvariantTest guards it.
    """
    bin_val = str(rec.get("bin") or rec.get("bin__") or "").strip()
    isn_val = str(rec.get("isn_dob_bis_viol") or rec.get("isn") or "").strip()
    ecb_num = str(rec.get("ecb_violation_number") or "").strip()

    # ── SWO: straight to the complaints-by-BIN list view ──────────────
    if record_type == "swo":
        if bin_val:
            return (
                "https://a810-bisweb.nyc.gov/bisweb/ComplaintsByAddressServlet"
                f"?requestid=2&allbin={quote_plus(bin_val)}&fillerdata=A"
            )
        return ""

    # ── Violations ───────────────────────────────────────────────────
    if record_type == "violation":
        if ecb_num:
            # ECB/OATH — this one has always worked.
            return (
                "https://a810-bisweb.nyc.gov/bisweb/ECBQueryByNumberServlet"
                f"?requestid=2&ecbin={quote_plus(ecb_num)}"
            )
        # 3h2n-5cm9 rows carry both `isn_dob_bis_viol` and `number`.
        # Together with the BIN those are the keys BIS's
        # ActionViolationDisplayServlet actually wants. Old code fed
        # the ISN into `vlcompdetlkey` (a different identifier from a
        # different servlet) and got "ALL KEYS CANNOT BE BLANK".
        viol_num = str(rec.get("number") or rec.get("violation_number") or "").strip()
        if isn_val and bin_val and viol_num:
            return (
                "https://a810-bisweb.nyc.gov/bisweb/ActionViolationDisplayServlet"
                f"?requestid=2&allbin={quote_plus(bin_val)}"
                "&allinquirytype=BXS3OCV4"
                f"&allisn={quote_plus(isn_val)}"
                f"&ppremise60={quote_plus(viol_num)}"
            )
        # Fallback: BIN-scoped overview.
        return _bis_bin_overview_url(bin_val)

    # ── Complaints ────────────────────────────────────────────────────
    if record_type == "complaint":
        # DOB Complaints Received (eabe-havv) carry a real `complaint_number`
        # that deep-links to the BIS per-complaint page — verified live to work
        # for the modern alphanumeric "3A…" numbers, not just legacy numeric
        # ones. 311 Service Requests (erm2-nwe9) carry only a `unique_key`, for
        # which NYC 311 exposes no public per-SR URL — emit no link. (In
        # practice the 311 poller builds its own link inline and never reaches
        # this branch; the unique_key guard is defensive.)
        if rec.get("unique_key"):
            return ""
        comp_num = str(rec.get("complaint_number") or "").strip()
        if comp_num:
            return (
                "https://a810-bisweb.nyc.gov/bisweb/OverviewForComplaintServlet"
                f"?complaintno={quote_plus(comp_num)}"
            )
        # eabe-havv record missing its number → BIN-scoped list view fallback.
        if bin_val:
            return (
                "https://a810-bisweb.nyc.gov/bisweb/ComplaintsByAddressServlet"
                f"?requestid=1&allbin={quote_plus(bin_val)}"
            )
        return ""

    # ── Permits / job status ─────────────────────────────────────────
    # job_status is a status facet of a permit's job filing, not a separate
    # record — both route identically. DOB NOW exposes no public per-filing URL
    # (Angular SPA, login-walled — confirmed by fetch) and its filings are not
    # in BIS, so there is no per-record public page to deep-link. Point every
    # permit/job_status at the SAME confirmed-working BIS BIN property profile
    # used for the violation fallback (PropertyProfileOverviewServlet?bin=, via
    # _bis_bin_overview_url) — one clean building-overview form for the whole
    # type, showing that building's filings.
    #
    # This replaces the data.cityofnewyork.us/w9ak-ipjd.html?job_filing_number=
    # filtered view, which landed on a generic dataset page because Socrata's
    # .html surface ignores the column filter. Legacy BIS-numeric permits, which
    # previously went to JobsQueryByNumberServlet, share the BIN profile too, so
    # the whole type resolves to one verified destination. No BIN → no link (a
    # dead button is worse than none, same as the 311 pattern);
    # _bis_bin_overview_url returns "" for a blank BIN and the UI hides the
    # button. I1/inspection-suffix filings also fall here — the per-location
    # JobsQueryByLocationServlet was never fetch-confirmed, so it is NOT used
    # (logged as a candidate to verify when BIS is reliably up).
    if record_type in ("permit", "job_status"):
        return _bis_bin_overview_url(bin_val)

    # ── Inspections ──────────────────────────────────────────────────
    if record_type == "inspection":
        insp_job = str(
            rec.get("job_id")
            or rec.get("job_filing_number")
            or rec.get("job_number")
            or rec.get("job__")
            or ""
        ).strip()
        if _is_dob_now_job(insp_job):
            return _open_data_filtered_url(
                "p937-wjvj", "job_id", insp_job
            )
        if insp_job:
            base_job = _base_job_number(insp_job)
            return (
                "https://a810-bisweb.nyc.gov/bisweb/JobsQueryByNumberServlet"
                f"?passjobnumber={quote_plus(base_job)}"
                "&passdocnumber=01&requestid=1"
            )
        return _bis_bin_overview_url(bin_val)

    # ── Final fallback: property profile by BIN. ─────────────────────
    # Same builder as the per-type fallbacks above — one building-overview
    # form for the whole file, so the two can no longer drift apart (the
    # drift is exactly what produced the broken violation link).
    return _bis_bin_overview_url(bin_val)


async def run_dob_sync_for_project(project: dict) -> list:
    """Core sync logic: fetch, dedupe, extract fields, save, alert. Used by cron + manual.

    BIN auto-heal runs in two layers, cheapest/most-reliable first:

    1. BBL pre-heal — if the stored BIN is missing/placeholder but the
       project carries a real BBL, resolve the real BIN deterministically
       from the exact BBL BEFORE any address query. This auto-heals
       projects created while the placeholder-BIN bug was live, without a
       manual override.
    2. Record-harvest heal (fallback) — if the BIN is still missing/
       placeholder and the address-based pass returns ANY record with a
       real BIN, backfill the most-common real BIN and re-run the queries.
       Lets us find complete records across all four DOB datasets (some
       BIN-only, no address variant) when GeoSearch alone couldn't
       resolve the BIN.
    """
    project_id = str(project["_id"])
    company_id = project.get("company_id", "")
    nyc_bin = (project.get("nyc_bin") or "").strip()
    project_address = project.get("address", "")

    if not nyc_bin and not project_address:
        return []

    # --- Layer 1: BBL pre-heal (deterministic) ---
    # If the stored BIN is missing/placeholder but a real BBL was captured
    # at creation (by fetch_nyc_bin_from_address), resolve the real BIN
    # from the exact BBL before falling back to fragile address matching.
    # Backfill so future syncs hit BIN-only endpoints directly. If this
    # resolves, nyc_bin becomes real and the Layer-2 harvest below is
    # skipped automatically (should_heal turns False). No regression when
    # there's no BBL or the lookup misses — nyc_bin is left untouched.
    if (not nyc_bin) or _is_placeholder_bin(nyc_bin):
        stored_bbl = (project.get("bbl") or project.get("nyc_bbl") or "").strip()
        if stored_bbl:
            bbl_bin = await _resolve_bin_from_bbl(stored_bbl)
            if bbl_bin:
                logger.info(
                    f"DOB BBL->BIN pre-heal for project {project_id}: "
                    f"stored={nyc_bin!r} bbl={stored_bbl} -> {bbl_bin}"
                )
                try:
                    await db.projects.update_one(
                        {"_id": to_query_id(project_id)},
                        {"$set": {
                            "nyc_bin": bbl_bin,
                            "track_dob_status": True,
                            "updated_at": datetime.now(timezone.utc),
                        }},
                    )
                except Exception as e:
                    logger.warning(f"BBL->BIN pre-heal write failed: {e}")
                nyc_bin = bbl_bin

    raw_records = await _query_dob_apis(nyc_bin, project_address)

    # --- BIN auto-heal ---
    # Scan returned records for a real BIN. DOB's datasets expose the
    # BIN on every record. If the project has no real BIN stored, pull
    # the most-common real BIN from returned records and re-query with
    # that so BIN-only endpoints (inspections, BIS legacy permits) also
    # surface records.
    should_heal = (not nyc_bin) or _is_placeholder_bin(nyc_bin)
    if should_heal and raw_records:
        bin_votes: Dict[str, int] = {}
        for rec in raw_records:
            # DOB datasets use various field names for BIN: bin, bin__
            candidate = str(
                rec.get("bin") or rec.get("bin__") or ""
            ).strip()
            if candidate and not _is_placeholder_bin(candidate):
                bin_votes[candidate] = bin_votes.get(candidate, 0) + 1

        if bin_votes:
            healed_bin = max(bin_votes, key=bin_votes.get)
            logger.info(
                f"DOB BIN auto-heal for project {project_id}: "
                f"stored={nyc_bin!r} → healed={healed_bin} "
                f"(votes={bin_votes})"
            )
            # Backfill on the project document so future syncs skip
            # the address fallback entirely and hit BIN-only endpoints.
            try:
                await db.projects.update_one(
                    {"_id": to_query_id(project_id)},
                    {"$set": {
                        "nyc_bin": healed_bin,
                        "track_dob_status": True,
                        "updated_at": datetime.now(timezone.utc),
                    }},
                )
            except Exception as e:
                logger.warning(f"BIN backfill write failed: {e}")
            # Re-query with the real BIN and merge (dedup by record id).
            nyc_bin = healed_bin
            heal_records = await _query_dob_apis(healed_bin, project_address)
            if heal_records:
                seen_keys = set()
                merged = []
                for rec in raw_records + heal_records:
                    key = (
                        rec.get("_record_type", ""),
                        rec.get("_id_field", ""),
                        str(rec.get(rec.get("_id_field", "unique_key"), "")),
                    )
                    if key in seen_keys:
                        continue
                    seen_keys.add(key)
                    merged.append(rec)
                raw_records = merged
                logger.info(
                    f"DOB BIN auto-heal merged {len(heal_records)} "
                    f"BIN-query records (total after dedup: {len(raw_records)})"
                )

    if not raw_records:
        return []

    # DOB NOW Job → Filing de-duplication. A permit-bearing filing appears BOTH
    # in a permit dataset (rbx6-tga4 / dm9a-ab7w, record_type="permit") AND in the
    # job-filing dataset (w9ak-ipjd, record_type="job_status") — the SAME filing,
    # shown twice with two labels. Keep ONE row per permit-bearing filing: the
    # permit (it carries issuance + expiration), folding the real `job_type` from
    # the w9ak twin onto it (permit datasets have no job_type). Drop the redundant
    # job_status twin. Standalone job_status filings (Approved specs with no
    # permit) survive untouched as demoted "pending filings".
    def _norm_jfn(r):
        return str(r.get("job_filing_number") or r.get("job__") or "").strip().upper()

    _permit_by_jfn = {
        _norm_jfn(r): r
        for r in raw_records
        if r.get("_record_type") == "permit" and _norm_jfn(r)
    }
    if _permit_by_jfn:
        _deduped, _dropped = [], 0
        for r in raw_records:
            if r.get("_record_type") == "job_status":
                perm = _permit_by_jfn.get(_norm_jfn(r))
                if perm is not None:
                    # Fold the job's real type onto the permit for labelling,
                    # then drop this duplicate filing row.
                    if r.get("job_type") and not perm.get("job_type"):
                        perm["job_type"] = r.get("job_type")
                    _dropped += 1
                    continue
            _deduped.append(r)
        raw_records = _deduped
        if _dropped:
            logger.info(
                f"DOB sync for project {project_id}: collapsed {_dropped} "
                f"job_status filing(s) into their matching permit rows"
            )

    # One-time cleanup of legacy-format permit rows. Before the
    # renewal-collapse fix, permits were keyed by per-filing
    # job_filing_number (e.g. "B00834550-I1:FE"), so a renewed permit
    # left behind its expired predecessor as a phantom row. New code
    # keys permits as "permit:BASE_JOB:WORK_TYPE" — any permit row in
    # this project that doesn't match that prefix is a stale legacy
    # entry. Only run the purge when we successfully fetched fresh
    # permit data, so an upstream DOB API outage doesn't wipe good
    # cached state.
    if any(r.get("_record_type") == "permit" for r in raw_records):
        try:
            purged = await db.dob_logs.delete_many({
                "project_id": project_id,
                "record_type": "permit",
                "raw_dob_id": {"$not": {"$regex": "^permit:"}},
            })
            if purged.deleted_count:
                logger.info(
                    f"DOB sync for project {project_id}: purged "
                    f"{purged.deleted_count} legacy-format permit rows"
                )
        except Exception as e:
            logger.warning(f"Legacy permit purge failed for project {project_id}: {e}")

    existing_ids = set()
    existing_cursor = db.dob_logs.find({"project_id": project_id}, {"raw_dob_id": 1})
    async for doc in existing_cursor:
        existing_ids.add(doc.get("raw_dob_id"))
 
    new_records = []
    for rec in raw_records:
        id_field = rec.get("_id_field", "unique_key")
        raw_id = str(rec.get(id_field, ""))
        if not raw_id:
            continue
        # Permits: use the collapsed (base_job, work_type) key stamped
        # during the fetch phase so renewals update the existing row
        # rather than creating a new one. Without this, every renewal
        # gets a fresh job_filing_number and leaks an expired
        # "ghost" permit into the logs.
        if rec.get("_record_type") == "permit":
            collapsed = rec.get("_collapsed_permit_id")
            if collapsed:
                raw_id = f"permit:{collapsed}"
            else:
                work_suffix = rec.get("work_type") or rec.get("permit_type") or rec.get("permit_sequence__") or ""
                raw_id = f"{raw_id}:{work_suffix}" if work_suffix else raw_id
        # NOTE: we don't skip on existing_ids for permits here — the
        # update path below refreshes status/expiration from the newest
        # filing. Only skip for non-permit types where the record is
        # immutable.
        if rec.get("_record_type") != "permit" and raw_id in existing_ids:
            continue
        new_records.append((raw_id, rec))
 
    if not new_records:
        logger.info(f"DOB sync for project {project_id}: no new records")
        return []
 
    inserted_logs = []
    now = datetime.now(timezone.utc)
 
    for raw_id, rec in new_records:
        try:
            record_type = rec.get("_record_type", "unknown")
            # raw_id already has work-type suffix applied during dedup phase above
            severity = _determine_severity(rec, record_type)
            summary = _generate_summary(rec, record_type)
            next_action = _generate_next_action(rec, record_type, severity)
            dob_link = _build_dob_link(rec, record_type)

            # Extract structured fields based on record type
            extra_fields = {}
            if record_type == "permit":
                extra_fields = _extract_permit_fields(rec)
            elif record_type == "violation":
                extra_fields = _extract_violation_fields(rec)
            elif record_type == "swo":
                # MR.14 (commit 2b) — SWO records can come from two
                # paths: (1) text-match on violation records (legacy
                # path; uses _extract_violation_fields); (2) the new
                # 3usq-5cid Stop Work Orders dataset (uses
                # _extract_swo_fields). Discriminate on the presence
                # of `stop_work_order_number` in the raw record (only
                # the dedicated dataset has that field).
                if rec.get("stop_work_order_number"):
                    extra_fields = _extract_swo_fields(rec)
                else:
                    extra_fields = _extract_violation_fields(rec)
            elif record_type == "complaint":
                extra_fields = _extract_complaint_fields(rec)
            elif record_type == "inspection":
                extra_fields = _extract_inspection_fields(rec)
            elif record_type == "job_status":
                # MR.14 (commit 2a) — capture filing_status so diffing
                # has a value to compare against. Pre-MR.14 this
                # dataset was inserted without extras and couldn't
                # surface filing-status transitions.
                extra_fields = _extract_job_status_fields(rec)
            elif record_type == "cofo":
                extra_fields = _extract_cofo_fields(rec)
            elif record_type == "facade_fisp":
                extra_fields = _extract_facade_fisp_fields(rec)
            elif record_type == "boiler":
                extra_fields = _extract_boiler_fields(rec)
            elif record_type == "elevator":
                extra_fields = _extract_elevator_fields(rec)

            dob_log = {
                "project_id": project_id,
                "company_id": company_id,
                "nyc_bin": nyc_bin,
                "record_type": record_type,
                "raw_dob_id": raw_id,
                "ai_summary": summary,
                "severity": severity,
                "next_action": next_action,
                "dob_link": dob_link,
                "detected_at": now,
                "created_at": now,
                "updated_at": now,
                "is_deleted": False,
                # V2.3.A2 Change 3 — persist the source dataset
                # slug so future code that needs "did this come
                # from BIS legacy or DOB NOW Safety?" can answer
                # without re-parsing. Forward-only: existing
                # records remain unstamped. The in-flight tag
                # ``_dataset`` is stamped on the raw record in
                # _query_dob_apis; here we promote it to the
                # bare ``dataset`` field on the persisted doc.
                "dataset": rec.get("_dataset"),
                **extra_fields,
            }
            # MR.14 (commit 2a) — universal current_status field
            # (read by diffing logic below).
            # MR.14 (commit 2b) — signal_kind now derived from the
            # classifier (lib/dob_signal_classifier.py) instead of
            # mirroring record_type. Drives plain-English templates
            # + notification routing.
            current_status = _extract_dob_log_status(dob_log)
            dob_log["current_status"] = current_status
            dob_log["signal_kind"] = _signal_kind_for(dob_log)
            dob_log["read_by_user"] = []

            # MR.14 (commit 2a) — diffing logic. Find the most-recent
            # dob_log for this raw_dob_id; compare current_status.
            #   • No prior row OR status changed → INSERT new row with
            #     previous_status set to the prior current_status.
            #   • Status unchanged → update mutable fields on the
            #     existing row (severity / summary / next_action may
            #     have shifted even when status didn't).
            existing = await db.dob_logs.find_one(
                {"raw_dob_id": raw_id},
                sort=[("detected_at", -1)],
            )
            if existing and existing.get("current_status") == current_status:
                # No status change — refresh mutable fields. Don't
                # insert a duplicate.
                update_fields = {
                    "severity": dob_log["severity"],
                    "next_action": dob_log["next_action"],
                    "ai_summary": dob_log["ai_summary"],
                    "dob_link": dob_log["dob_link"],
                    "updated_at": now,
                    **extra_fields,
                }
                await db.dob_logs.update_one(
                    {"_id": existing["_id"]},
                    {"$set": update_fields},
                )
                dob_log["id"] = str(existing["_id"])
                # Only alert if severity escalated to Action — and
                # route through the throttled wrapper so initial-scan
                # suppression + 24h dedupe apply.
                old_severity = existing.get("severity", "")
                if severity == "Action" and old_severity != "Action":
                    await _send_critical_dob_alert_throttled(project, dob_log, source="dob")
            else:
                # Either first time OR status changed. Stamp
                # transition markers and insert a new row. The
                # activity feed surfaces these as "this changed"
                # events.
                dob_log["previous_status"] = (
                    existing.get("current_status") if existing else None
                )
                dob_log["status_changed_at"] = now
                # MR.14 commit 4a — stamp is_seed_transition on the
                # doc itself. Replaces the time-window-env-var
                # heuristic from commit 2b/3 with a durable, stored
                # discriminator. A row is a synthetic seed iff the
                # existing doc was a legacy pre-MR.14 entry (lacks
                # current_status field). Stored on every insert so
                # the activity feed can filter cheaply via index;
                # also gates the alert call below.
                is_seed_transition = (
                    existing is not None
                    and "current_status" not in existing
                )
                dob_log["is_seed_transition"] = is_seed_transition
                result = await db.dob_logs.insert_one(dob_log)
                dob_log["id"] = str(result.inserted_id)
                inserted_logs.append(dob_log)
                if severity == "Action" and not is_seed_transition:
                    await _send_critical_dob_alert_throttled(project, dob_log, source="dob")
        except Exception as e:
            logger.error(f"Failed to process dob_log for raw_id={raw_id} type={rec.get('_record_type')}: {e}", exc_info=True)
 
    # Sprint 1: Cross-reference complaints to violations
    try:
        from dateutil import parser as dateparser
        from datetime import timedelta
        complaints = await db.dob_logs.find({
            "project_id": project_id,
            "record_type": "complaint",
            "complaint_date": {"$ne": None},
        }).to_list(length=5000)
        violations = await db.dob_logs.find({
            "project_id": project_id,
            "record_type": "violation",
            "violation_date": {"$ne": None},
        }).to_list(length=5000)
        for comp in complaints:
            try:
                comp_date = dateparser.parse(comp["complaint_date"])
                comp_bin = comp.get("nyc_bin") or ""
                for viol in violations:
                    try:
                        viol_date = dateparser.parse(viol["violation_date"])
                        viol_bin = viol.get("nyc_bin") or ""
                        if comp_bin and comp_bin == viol_bin and timedelta(0) <= (viol_date - comp_date) <= timedelta(days=30):
                            await db.dob_logs.update_one(
                                {"_id": comp["_id"]},
                                {"$set": {"linked_violation_id": str(viol["_id"])}}
                            )
                            await db.dob_logs.update_one(
                                {"_id": viol["_id"]},
                                {"$addToSet": {"linked_complaint_ids": str(comp["_id"])}}
                            )
                    except Exception:
                        continue
            except Exception:
                continue
    except Exception as e:
        logger.error(f"Complaint-to-violation cross-referencing failed for project {project_id}: {e}")

    logger.info(
        f"DOB sync for project {project_id}: {len(inserted_logs)} new records "
        f"({sum(1 for l in inserted_logs if l.get('severity') == 'Critical')} critical)"
    )

    # Phase B3: first-poll summary for new-customer banner. Idempotent —
    # only writes once per project. Triggered ONCE on the first DOB
    # sync (when the project doc has no first_poll_completed_at).
    # The dashboard FE shows a 24h banner ("Initial scan complete for
    # {project_name} — found N permits, X violations, Y inspections")
    # by inspecting these fields. Wrapped in try/except so a count or
    # write hiccup never breaks the sync.
    try:
        proj_doc = await db.projects.find_one({"_id": to_query_id(project_id)})
        if proj_doc and not proj_doc.get("first_poll_completed_at"):
            permits_count = await db.dob_logs.count_documents(
                {"project_id": project_id, "record_type": "permit"}
            )
            violations_count = await db.dob_logs.count_documents(
                {"project_id": project_id, "record_type": "violation"}
            )
            inspections_count = await db.dob_logs.count_documents(
                {"project_id": project_id, "record_type": "inspection"}
            )
            await db.projects.update_one(
                {"_id": to_query_id(project_id)},
                {"$set": {
                    "first_poll_completed_at": datetime.now(timezone.utc),
                    "first_poll_summary": {
                        "permits": permits_count,
                        "violations": violations_count,
                        "inspections": inspections_count,
                    },
                }},
            )
            logger.info(
                f"first_poll_summary stamped for project {project_id}: "
                f"{permits_count}p / {violations_count}v / {inspections_count}i"
            )
    except Exception as _e:
        logger.warning(f"first_poll_summary write failed for {project_id}: {_e}")

    # Mark the initial DOB scan done for this project so subsequent scans
    # can send email alerts. The first scan of a newly-tracked project
    # pulls in the entire historical backlog — silent during that run.
    await _mark_initial_scan_done(project_id, "dob")

    # Rolling per-project sync freshness. Distinct from first_poll_completed_at,
    # which is written ONCE (guarded above) and therefore answers "has this
    # project ever synced?", not "how fresh is its DOB data?". This runs on
    # every successful sync, so the UI can show a real relative time.
    #
    # Placement is deliberate: after the three early returns (no BIN / lookup
    # failure / no records path), so a run that bailed never stamps a success.
    # Wrapped like the block above — a stamp failure must never fail the sync
    # that already inserted its records.
    try:
        await db.projects.update_one(
            {"_id": to_query_id(project_id)},
            {"$set": {"last_dob_sync_at": datetime.now(timezone.utc)}},
        )
    except Exception as _e:
        logger.warning(f"last_dob_sync_at write failed for {project_id}: {_e}")

    return inserted_logs
 
 
async def nightly_compliance_check():
    """Nightly check: missing logbooks, missing SSP for major projects, expiring safety staff licenses."""
    try:
        logger.info("🔍 Nightly compliance check starting...")
        now = datetime.now(timezone.utc)
        # Eastern, not UTC. This job runs off-hours by design, which is exactly
        # the window where the UTC day is already tomorrow in New York — it was
        # checking the wrong day for missing logbooks every night.
        today = eastern_date(now)

        projects = await db.projects.find({
            "status": "active", **ACTIVE_PROJECT_FILTER
        }).to_list(500)

        for project in projects:
            pid = str(project["_id"])
            pname = project.get("name", "Unknown")
            pclass = project.get("project_class")
            company_id = project.get("company_id")

            # 1. Check for missing required daily logbooks (only if workers were on site today)
            today_start, today_end = get_today_range_est()
            checkin_count = await db.checkins.count_documents({
                "project_id": pid,
                "check_in_time": {"$gte": today_start, "$lt": today_end},
                "is_deleted": {"$ne": True},
            })

            if checkin_count > 0:
                required = project.get("required_logbooks") or get_required_logbooks(pclass, project)
                daily_required = daily_required_logbooks(required)

                for log_type in daily_required:
                    existing = await db.logbooks.find_one({
                        "project_id": pid, "log_type": log_type, "date": today,
                        "status": "submitted", "is_deleted": {"$ne": True},
                    })
                    if not existing:
                        # Check if alert already exists for today
                        existing_alert = await db.compliance_alerts.find_one({
                            "alert_type": "missing_logbook", "project_id": pid,
                            "details.log_type": log_type, "details.date": today,
                        })
                        if not existing_alert:
                            severity = "high" if log_type == "ssc_daily_safety_log" else "medium"
                            await db.compliance_alerts.insert_one({
                                "alert_type": "missing_logbook",
                                "severity": severity,
                                "project_id": pid,
                                "project_name": pname,
                                "message": f"Required {log_type.replace('_', ' ').title()} not submitted for {pname} on {today}",
                                "resolved": False,
                                "created_at": now,
                                "company_id": company_id,
                                "details": {"log_type": log_type, "date": today},
                            })

            # 2. Missing SSP for major projects
            if pclass in ("major_a", "major_b") and not project.get("ssp_number"):
                existing_alert = await db.compliance_alerts.find_one({
                    "alert_type": "missing_ssp", "project_id": pid, "resolved": False,
                })
                if not existing_alert:
                    await db.compliance_alerts.insert_one({
                        "alert_type": "missing_ssp",
                        "severity": "critical",
                        "project_id": pid,
                        "project_name": pname,
                        "message": f"Major project {pname} has no Site Safety Plan (SSP) filed with DOB",
                        "resolved": False,
                        "created_at": now,
                        "company_id": company_id,
                    })

            # 3. SSP expiration warning (within 30 days)
            ssp_exp = project.get("ssp_expiration_date")
            if ssp_exp:
                try:
                    exp_date = datetime.strptime(ssp_exp, "%Y-%m-%d").replace(tzinfo=timezone.utc)
                    days_until = (exp_date - now).days
                    if 0 < days_until <= 30:
                        existing_alert = await db.compliance_alerts.find_one({
                            "alert_type": "ssp_expiring", "project_id": pid, "resolved": False,
                        })
                        if not existing_alert:
                            await db.compliance_alerts.insert_one({
                                "alert_type": "ssp_expiring",
                                "severity": "high",
                                "project_id": pid,
                                "project_name": pname,
                                "message": f"SSP for {pname} expires in {days_until} days ({ssp_exp})",
                                "resolved": False,
                                "created_at": now,
                                "company_id": company_id,
                            })
                except Exception:
                    pass

        # 4. Expiring safety staff licenses (within 30 days)
        all_staff = await db.safety_staff_registrations.find({
            "is_deleted": {"$ne": True}
        }).to_list(500)

        for staff in all_staff:
            exp = staff.get("license_expiration")
            if exp:
                try:
                    exp_date = datetime.strptime(exp, "%Y-%m-%d").replace(tzinfo=timezone.utc)
                    days_until = (exp_date - now).days
                    if 0 < days_until <= 30:
                        sid = str(staff["_id"])
                        existing_alert = await db.compliance_alerts.find_one({
                            "alert_type": "staff_license_expiring",
                            "details.staff_id": sid, "resolved": False,
                        })
                        if not existing_alert:
                            await db.compliance_alerts.insert_one({
                                "alert_type": "staff_license_expiring",
                                "severity": "high",
                                "project_id": staff.get("project_id"),
                                "message": f"{staff.get('role', '').upper()} {staff.get('name')}'s license ({staff.get('license_number')}) expires in {days_until} days",
                                "resolved": False,
                                "created_at": now,
                                "company_id": staff.get("company_id"),
                                "details": {"staff_id": sid, "license_expiration": exp},
                            })
                except Exception:
                    pass

        # 5. Expiring worker certifications (within 30 days)
        #
        # THE ONLY SCHEDULED READER of workers.certifications, and the first
        # query anywhere to use the worker_cert_expiry index. Until this
        # existed, CERT_EXPIRING_SOON was computed by
        # validate_worker_certifications and then dropped at every one of its
        # four call sites: the check-in paths freeze it into the row's
        # `cert_warnings` and emit nothing, and only EXPIRED_SST / SST_UNKNOWN
        # ever reached an alert. A man who stopped coming to site had his SST
        # lapse in silence -- and so did a man who came in every day.
        #
        # HERE AND NOT IN card_audit.check_card_expirations (02:15), because
        # that job's subject is worker_enrollments.card_expiration_date -- a
        # separate credential store with no join to workers.certifications --
        # and its output is card_fraud_flags under a FraudFlagType vocabulary.
        # A lapsed cert is not fraud. This is a compliance_alerts event read by
        # the same screen as sections 1-4, and section 4 (safety-staff licences)
        # is already this exact shape: a global non-project scan, 30-day window,
        # open-alert dedup.
        #
        # ALERT ONLY, NO NOTIFICATION, deliberately. dispatch_notification fans
        # out one inbox row per eligible user (capped at 100), so a nightly
        # per-worker dispatch is the shape that sent 80 renewal emails. It is
        # also the wrong substrate: compliance_alerts is in
        # SOFT_DELETE_NEVER_PURGE and has no TTL, while cleanup_inbox DELETES
        # read notifications after READ_RETENTION_DAYS -- and that row IS the
        # inbox's dedup key. A digest built off these alert rows is how this
        # gets pushed later, not a per-cert dispatch.
        thirty_days_out = now + timedelta(days=30)

        # `is_deleted: False` EXACTLY, not the `$ne: True` the rest of this file
        # uses. worker_cert_expiry carries
        # partialFilterExpression={"is_deleted": {"$eq": False}}, and Mongo uses
        # a partial index only when the query predicate implies that filter;
        # `$ne: True` does not. The mismatch is the index's to fix, not this
        # query's -- recorded in followups.md.
        cert_window_filter = {
            "is_deleted": False,
            "certifications.expiration_date": {"$gt": now, "$lte": thirty_days_out},
        }

        # TWO BLIND SPOTS, COUNTED RATHER THAN ASSUMED AWAY. The range query
        # matches BSON dates only, so a legacy string-typed expiry is invisible
        # to it, and `is_deleted: False` cannot see a worker document written
        # before that field existed. Both writers set is_deleted=False and store
        # a parsed datetime, so both numbers should be zero -- but "should be
        # zero" is exactly what permit_renewals.current_expiration looked like
        # before its mixed formats were found. If there is a gap the log says so
        # rather than the scan quietly covering less than it claims to.
        try:
            loose_count = await db.workers.count_documents({
                "is_deleted": {"$ne": True},
                "certifications.expiration_date": {"$gt": now, "$lte": thirty_days_out},
            })
            covered_count = await db.workers.count_documents(cert_window_filter)
            string_typed = await db.workers.count_documents({
                "is_deleted": {"$ne": True},
                "certifications.expiration_date": {"$type": "string"},
            })
            if loose_count != covered_count or string_typed:
                logger.warning(
                    "[cert_expiry] scan does not cover the whole collection: "
                    "%d workers in window, %d reachable by the indexed filter, "
                    "%d holding a string-typed expiration_date",
                    loose_count, covered_count, string_typed,
                )
        except Exception as probe_err:
            logger.warning(f"[cert_expiry] coverage probe failed: {probe_err!r}")

        cert_alerts = 0
        cert_no_company = 0
        async for w in db.workers.find(cert_window_filter):
            try:
                # THE GATE'S OWN VERDICT, not a second copy of the date maths.
                # validate_worker_certifications owns the 30-day window and the
                # datetime/string coercion; re-deriving either here is how the
                # cron and the gate drift into disagreeing about the same card.
                expiring = [
                    x for x in validate_worker_certifications(w).get("warnings", [])
                    if x.get("type") == "CERT_EXPIRING_SOON"
                ]
                if not expiring:
                    continue

                wid = str(w["_id"])
                w_company = w.get("company_id")
                if not w_company:
                    # get_compliance_alerts scopes on the admin's company_id, so
                    # an alert carrying none is invisible to every admin who has
                    # one. Skipped and counted, never written into a hole.
                    cert_no_company += 1
                    continue

                # EARLIEST expiry is the alert's date. It is what the operator is
                # racing, and it is stable under the array reordering a re-scan
                # can cause -- min() of a set does not depend on arrival order.
                dates = sorted(
                    x.get("expires_on") for x in expiring if x.get("expires_on")
                )
                earliest = dates[0] if dates else None

                # -- DEDUP: ONE OPEN ALERT PER WORKER ------------------------
                # Keyed on worker_id ALONE, never on the certification.
                #
                # There is no per-cert identity to key on: subdocuments in
                # workers.certifications[] carry no id, and the re-scan path
                # rewrites every field that could stand in for one -- `type`
                # when the class becomes legible, `expiration_date` when a
                # flagged row is corrected, `card_number` from whatever OCR
                # read. An array index is not an identity either. Key on any of
                # them and the alert re-fires the moment the review queue does
                # its job -- which is precisely how permit_renewal_id, a ROW id
                # for a permit that inserts a new row on every DOB status
                # change, sent one customer the same reminder six times.
                #
                # worker._id is the real stable thing here, the way raw_dob_id
                # names a permit: the document is created once and updated in
                # place, never re-inserted per state change. One open alert per
                # worker is also what an operator acts on -- you call the man,
                # not the card.
                #
                # THE SECOND CLAUSE IS THE RESOLVE RULE. Without it, an admin
                # who resolves an alert for a cert still twelve days from
                # expiring gets a fresh one that same night, and "resolved"
                # decays into "cleared for one night". Matching a RESOLVED alert
                # on the same earliest date makes resolve mean "I have handled
                # this expiry". The date is a SUPPRESSION TEST, not part of the
                # identity: when it changes -- a correction, or a renewal
                # setting a new one -- the fact has changed, and a fresh alert
                # is the correct outcome rather than a duplicate.
                dedup = {"alert_type": "worker_cert_expiring", "details.worker_id": wid}
                if earliest:
                    dedup["$or"] = [
                        {"resolved": False},
                        {"details.earliest_expiration": earliest},
                    ]
                else:
                    dedup["resolved"] = False
                if await db.compliance_alerts.find_one(dedup):
                    continue

                types = ", ".join(
                    sorted({str(x.get("cert_type") or "certification") for x in expiring})
                )
                await db.compliance_alerts.insert_one({
                    "alert_type": "worker_cert_expiring",
                    "severity": "high",
                    # A worker is not project-scoped. Section 4 reads project_id
                    # off its own record; there is no equivalent here, and
                    # inventing one from a recent check-in would tie a
                    # credential to whichever site he last happened to visit.
                    "project_id": None,
                    "message": (
                        f"{w.get('name') or 'A worker'}"
                        f"{' (' + w.get('company') + ')' if w.get('company') else ''}"
                        f" has {len(expiring)} certification(s) expiring within 30 days"
                        f"{' - earliest ' + earliest if earliest else ''}: {types}"
                    ),
                    "resolved": False,
                    "created_at": now,
                    "company_id": w_company,
                    "details": {
                        "worker_id": wid,
                        "earliest_expiration": earliest,
                        "certifications": [
                            {
                                "cert_type": x.get("cert_type"),
                                "expires_on": x.get("expires_on"),
                            }
                            for x in expiring
                        ],
                    },
                })
                cert_alerts += 1
            except Exception as cert_err:
                # Per-worker isolation: one malformed certifications array must
                # not end the sweep for everyone behind it in the cursor.
                logger.warning(
                    f"[cert_expiry] worker {w.get('_id')} skipped: {cert_err!r}"
                )

        if cert_alerts or cert_no_company:
            logger.info(
                "[cert_expiry] %d alert(s) raised; %d worker(s) skipped for "
                "having no company_id",
                cert_alerts, cert_no_company,
            )

        logger.info("🔍 Nightly compliance check completed")
    except Exception as e:
        logger.error(f"Nightly compliance check error: {e}")

async def nightly_dob_scan():
    """DOB compliance sync. Runs EVERY 15 MINUTES, not nightly.

    The name and this docstring are historical. MR.14 commit 2a moved
    this to IntervalTrigger(minutes=15) for the v1 monitoring product
    (operator F1: "DOB datasets at 15 min") and the docstring was left
    saying "runs daily at 04:00 AM EST" — which is how a job firing 96
    times a day went unnoticed for months while it drove a per-tick
    writer. The name is kept because the scheduler id, the logs, and
    the runbook all use it; the cadence is stated here so the next
    reader gets it from the docstring rather than from the add_job
    call ~9000 lines below.

    (Do not write the scheduler id as a literal in this docstring —
    TestSchedulerCadences anchors on its first occurrence in the file
    and asserts the 15-min trigger sits just above it.)

    Per tick: sync every tracked project's DOB records, then refresh
    permit severity/next_action from those records.
    """
    logger.info("🏗️ DOB nightly scan starting...")
 
    projects = await db.projects.find({
        "track_dob_status": True,
        "$or": [
            {"nyc_bin": {"$ne": None, "$exists": True}},
            {"address": {"$ne": None, "$ne": "", "$exists": True}},
        ],
        **ACTIVE_PROJECT_FILTER,
    }).to_list(500)
 
    if not projects:
        logger.info("DOB nightly scan: no tracked projects")
        return
 
    total_new = 0
    for project in projects:
        try:
            new_logs = await run_dob_sync_for_project(project)
            total_new += len(new_logs)
        except Exception as e:
            logger.error(f"DOB scan error for project {project.get('name')}: {e}")
 
    logger.info(f"🏗️ DOB nightly scan complete: {len(projects)} projects scanned, {total_new} new records")
    # Check for expiring permits across all projects. Reads and writes
    # dob_logs only — severity + next_action computed against each row's
    # own expiration_date. Stays.
    await check_permit_expirations()

    # `await nightly_renewal_scan(db)` is REMOVED from this tick.
    #
    # It was the writer for permit_renewals, and because this function
    # runs every 15 minutes (see docstring) it ran 96 times a day, not
    # once. Each pass re-walked every record_type="permit" row in
    # dob_logs and inserted a renewal for any whose permit_dob_log_id
    # wasn't already covered by a live row.
    #
    # permit_dob_log_id is a dob_logs _id, and dob_logs inserts a NEW
    # document with a NEW _id on every status change, so a single real
    # permit accrues a row per status transition — plus a whole fresh
    # set after a reset-resync, which mints new _ids for everything.
    # The rows it produced carry job_number=None and permit_type=None
    # (hardcoded in lib/eligibility_dispatcher.py:178-179) and a
    # days_until_expiry measured against a different date than the
    # current_expiration stored beside it. They are not recoverable by
    # deduping; they were never identifiable in the first place.
    #
    # Growth was 12/18/16/34 rows per month May-August 2026.
    #
    # This also retires Job 2 (AWAITING_GC -> COMPLETED completion
    # checks). Nothing else drives that transition, but nothing
    # produces AWAITING_GC either now except the manual /prepare
    # endpoint, and dob_approval_watcher still handles the
    # AWAITING_DOB_APPROVAL -> COMPLETED path on its own schedule.
    #
    # nightly_renewal_scan stays in permit_renewal.py, uncalled. It
    # comes back when the writer keys on a stable permit identity and
    # the adapter stops nulling the fields — i.e. when the module is
    # unparked, deliberately.
    #
    # See docs/audits/permit-expiry-claim-2026-08-27.md.

async def renewal_digest_daily_cron():
    """Daily 7am-ET digest run.

    For each non-deleted company:
      1. Pull permits + project denorm.
      2. compute_company_alerts() → list of alerts that crossed today.
      3. Idempotency check — alerts already sent today are skipped.
      4. If any new alerts: build HTML, resolve recipients, send via
         Resend, log success per-alert into renewal_alert_sent.

    Recipients per spec §4.1:
      - Company admins with notifications_enabled != False (default ON)
      - Non-admin PMs with renewal_digest_opt_in == True (default OFF)
      - Optional shared mailbox alias on companies.renewal_digest_alias_email
    """
    from lib.renewal_digest import (
        compute_company_alerts,
        digest_html,
        digest_subject,
        AlertKind,
    )

    started = datetime.now(timezone.utc)
    today = started

    companies = await db.companies.find({"is_deleted": {"$ne": True}}).to_list(500)
    sent_count = 0
    skipped_company_count = 0

    for company in companies:
        company_id = str(company["_id"])

        # Pull permits across all this company's tracked projects.
        # Denormalize project name so the email can render the right
        # project per permit.
        projects = await db.projects.find(
            {"company_id": company_id, "is_deleted": {"$ne": True}},
            {"_id": 1, "name": 1, "track_dob_status": 1},
        ).to_list(500)
        project_id_to_name = {str(p["_id"]): p.get("name", "") for p in projects}
        if not projects:
            permits = []
        else:
            permits = await db.dob_logs.find({
                "project_id": {"$in": list(project_id_to_name.keys())},
                "record_type": "permit",
                "is_deleted": {"$ne": True},
            }, {
                "_id": 1, "project_id": 1, "job_number": 1,
                "issuance_date": 1, "permit_class": 1, "filing_system": 1,
            }).to_list(2000)
            for p in permits:
                p["project_name"] = project_id_to_name.get(p.get("project_id"), "")

        alerts = compute_company_alerts(
            company=company, permits=permits, today=today,
        )
        if not alerts:
            skipped_company_count += 1
            continue

        # Idempotency: filter alerts already sent today.
        new_alerts = []
        for a in alerts:
            key = a.idempotency_key()
            key["sent_date"] = today.date().isoformat()
            existing = await db.renewal_alert_sent.find_one(key)
            if existing:
                continue
            new_alerts.append((a, key))

        if not new_alerts:
            skipped_company_count += 1
            continue

        # Resolve recipients.
        recipients = await _resolve_renewal_digest_recipients(company)
        if not recipients:
            logger.info(
                f"[renewal_digest] company={company_id} has "
                f"{len(new_alerts)} new alerts but zero opted-in recipients; "
                f"skipping send (alerts will retry tomorrow)."
            )
            continue

        subject = digest_subject([a for a, _ in new_alerts], company.get("name") or "")
        html = digest_html([a for a, _ in new_alerts], company.get("name") or "")

        # Send via Resend (or no-op if env unset).
        try:
            await _send_renewal_digest_email(
                recipients, subject, html, company_id=str(company_id),
            )
        except Exception as e:
            logger.error(
                f"[renewal_digest] send failed for company={company_id}: {e!r}"
            )
            continue  # don't mark idempotency on send failure

        # Mark idempotency: insert a row per alert.
        for _, key in new_alerts:
            try:
                await db.renewal_alert_sent.insert_one({
                    **key,
                    "sent_at": started,
                    "recipients": recipients,
                })
                sent_count += 1
            except Exception as e:
                # Unique-index collision (concurrent cron) is benign.
                logger.debug(f"[renewal_digest] idempotency insert: {e!r}")

    elapsed = (datetime.now(timezone.utc) - started).total_seconds()
    logger.info(
        f"📧 renewal digest cron complete: "
        f"alerts_sent={sent_count} companies_skipped={skipped_company_count} "
        f"elapsed={elapsed:.1f}s"
    )


async def _resolve_renewal_digest_recipients(company: dict) -> list:
    """Per spec §4.1:
      - admins of this company: opt-OUT (default ON, suppressed if
        user.renewal_digest_opt_out == True)
      - non-admin PMs: opt-IN (default OFF, included only if
        user.renewal_digest_opt_in == True)
      - optional shared alias on companies.renewal_digest_alias_email
    Returns deduplicated list of email addresses.
    """
    company_id = str(company["_id"])
    emails: list = []

    # Admins: default ON, opt-out via user flag.
    admin_cursor = db.users.find({
        "company_id": company_id,
        "role": "admin",
        "is_deleted": {"$ne": True},
        "renewal_digest_opt_out": {"$ne": True},
    }, {"email": 1})
    async for u in admin_cursor:
        e = (u.get("email") or "").strip().lower()
        if e:
            emails.append(e)

    # Non-admin PMs / CPs: default OFF, opt-in.
    pm_cursor = db.users.find({
        "company_id": company_id,
        "role": {"$in": ["pm", "cp"]},
        "is_deleted": {"$ne": True},
        "renewal_digest_opt_in": True,
    }, {"email": 1})
    async for u in pm_cursor:
        e = (u.get("email") or "").strip().lower()
        if e:
            emails.append(e)

    # Optional shared mailbox alias.
    alias = (company.get("renewal_digest_alias_email") or "").strip().lower()
    if alias:
        emails.append(alias)

    # Dedupe, preserve order.
    seen = set()
    out = []
    for e in emails:
        if e and e not in seen:
            seen.add(e)
            out.append(e)
    return out


async def _send_renewal_digest_email(
    recipients: list,
    subject: str,
    html: str,
    *,
    company_id: Optional[str] = None,
) -> None:
    """MR.14 fix — route through lib/notifications.send_notification.
    Per-recipient idempotency via entity_id keyed on
    (company_id, date) so a single company's daily digest won't
    re-send to the same recipient if the cron fires twice in a 23h
    window."""
    if not recipients:
        return
    date_key = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    # If company_id wasn't passed (legacy callers), use a date-only
    # entity_id. Slightly looser dedup but still bounded to one
    # email per recipient per day.
    entity_id = (
        f"renewal_digest:{company_id}:{date_key}"
        if company_id else f"renewal_digest:global:{date_key}"
    )
    text_fallback = f"{subject}\n\n(Open the email in HTML for the full digest.)"
    from lib.notifications import send_notification
    for recipient in recipients:
        try:
            await send_notification(
                db,
                permit_renewal_id=entity_id,
                trigger_type="renewal_digest",
                recipient=recipient,
                subject=subject,
                html=html,
                text=text_fallback,
                metadata={"company_id": company_id, "date": date_key},
            )
        except Exception as e:
            logger.error(
                f"renewal_digest send_notification error "
                f"recipient={recipient}: {e}"
            )


async def _eligibility_shadow_sweep():
    """30-min sweep that runs both legacy and v2 eligibility against
    every active permit, writes diff to `eligibility_shadow`. Only
    registered when ELIGIBILITY_REWRITE_MODE == 'shadow' (see startup).

    Cron lock: APScheduler `max_instances=1` ensures overlapping runs
    skip rather than double up. Mongo `processing_until` field on a
    sentinel doc would be more explicit but the in-process lock is
    sufficient for single-instance deploys.
    """
    from lib import eligibility_dispatcher, eligibility_shadow, eligibility_v2
    from permit_renewal import _check_renewal_eligibility_legacy_inner

    started = datetime.now(timezone.utc)
    permits_evaluated = 0
    permits_failed = 0

    # All permit rows on tracked projects with track_dob_status=True.
    # Fetch project + company once per permit; the dispatcher pattern
    # demands the snapshot-of-input determinism across legacy and v2.
    tracked_projects = await db.projects.find(
        {"track_dob_status": True, "is_deleted": {"$ne": True}},
        {"_id": 1, "name": 1, "company_id": 1},
    ).to_list(500)

    project_by_id = {str(p["_id"]): p for p in tracked_projects}
    company_cache: Dict[str, Optional[dict]] = {}

    for project in tracked_projects:
        project_id = str(project["_id"])
        company_id = project.get("company_id")
        if company_id and company_id not in company_cache:
            company_cache[company_id] = await db.companies.find_one(
                {"_id": to_query_id(company_id), "is_deleted": {"$ne": True}}
            )
        company = company_cache.get(company_id) or {}

        permits = await db.dob_logs.find({
            "project_id": project_id,
            "record_type": "permit",
            "is_deleted": {"$ne": True},
        }).to_list(500)

        for permit in permits:
            try:
                async def _legacy(p, pj, c, t, _name=None):
                    name = (
                        _name
                        or (c.get("gc_business_name") if c else None)
                        or (c.get("name") if c else "")
                        or ""
                    )
                    return await _check_renewal_eligibility_legacy_inner(
                        db, p, pj, name, c, today=t,
                    )

                async def _v2(d, p, pj, c, t):
                    return await eligibility_v2.evaluate(d, p, pj, c or {}, today=t)

                shadow_doc = await eligibility_shadow.run_one(
                    db,
                    legacy_callable=_legacy,
                    v2_callable=_v2,
                    permit=permit,
                    project=project,
                    company=company,
                )
                shadow_doc["sweep_started_at"] = started
                shadow_doc["project_id"] = project_id
                await db.eligibility_shadow.insert_one(shadow_doc)
                permits_evaluated += 1
            except Exception as e:
                permits_failed += 1
                logger.warning(
                    f"[eligibility_shadow_sweep] permit "
                    f"{permit.get('_id')} failed: {e!r}"
                )

    elapsed = (datetime.now(timezone.utc) - started).total_seconds()
    logger.info(
        f"🪞 eligibility shadow sweep complete: "
        f"evaluated={permits_evaluated} failed={permits_failed} "
        f"elapsed={elapsed:.1f}s"
    )


async def check_permit_expirations():
    """Check all tracked projects for permits expiring within 14 days. Called by nightly scan."""
    try:
        expiring_permits = []
        cutoff = datetime.now(timezone.utc) + timedelta(days=14)
 
        permits = await db.dob_logs.find({
            "record_type": "permit",
            "expiration_date": {"$ne": None},
            "is_deleted": {"$ne": True},
        }).to_list(1000)
 
        for permit in permits:
            exp_str = permit.get("expiration_date", "")
            if not exp_str:
                continue
            try:
                from dateutil import parser as dateparser
                exp_date = dateparser.parse(str(exp_str))
                if exp_date.tzinfo is None:
                    exp_date = exp_date.replace(tzinfo=timezone.utc)
                days_left = (exp_date - datetime.now(timezone.utc)).days
                if 0 < days_left <= 30:
                    await db.dob_logs.update_one(
                        {"_id": permit["_id"]},
                        {"$set": {"severity": "Action", "next_action": f"Permit expires in {days_left} days ({str(exp_str)[:10]}). File renewal on DOB NOW."}}
                    )
                    expiring_permits.append(permit)
                elif days_left <= 0:
                    await db.dob_logs.update_one(
                        {"_id": permit["_id"]},
                        {"$set": {"severity": "Action", "next_action": "EXPIRED: Permit has expired. Stop permitted work and file renewal immediately."}}
                    )
            except Exception:
                continue
 
        if expiring_permits:
            logger.info(f"Permit expiration check: {len(expiring_permits)} permits expiring within 14 days")
    except Exception as e:
        logger.error(f"Permit expiration check error: {e}")

 
# ==================== DOB COMPLIANCE ENDPOINTS ====================
 
@api_router.put("/projects/{project_id}/dob-config", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def update_dob_config(project_id: str, config: DOBConfigUpdate, admin=Depends(get_admin_user)):
    """Manual override: update BIN/BBL and toggle DOB tracking."""
    project = await db.projects.find_one({
        "_id": to_query_id(project_id),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
 
    company_id = get_user_company_id(admin)
    if company_id and project.get("company_id") != company_id:
        raise HTTPException(status_code=403, detail="Access denied to this project")
 
    update_fields = {"updated_at": datetime.now(timezone.utc)}
 
    if config.nyc_bin is not None:
        clean_bin = config.nyc_bin.strip()
        if clean_bin and (len(clean_bin) != 7 or not clean_bin.isdigit()):
            raise HTTPException(status_code=422, detail="BIN must be exactly 7 digits")
        update_fields["nyc_bin"] = clean_bin if clean_bin else None
 
    if config.bbl is not None:
        # Accept either `bbl` (canonical) or `nyc_bbl` (legacy alias)
        # via DOBConfigUpdate's populate_by_name. Always write to the
        # canonical `bbl` field. The step 9.1 migration $rename'd
        # legacy nyc_bbl values into bbl, so existing docs are clean.
        update_fields["bbl"] = config.bbl.strip() or None
        update_fields["bbl_source"] = "manual_entry"
        update_fields["bbl_last_synced"] = datetime.now(timezone.utc)
 
    if config.track_dob_status is not None:
        update_fields["track_dob_status"] = config.track_dob_status

    if config.gc_legal_name is not None:
        update_fields["gc_legal_name"] = config.gc_legal_name.strip() or None

    await db.projects.update_one({"_id": to_query_id(project_id)}, {"$set": update_fields})

    await audit_log("dob_config_update", str(admin.get("_id", admin.get("id", ""))), "project", project_id, {
        k: v for k, v in update_fields.items() if k != "updated_at"
    })

    updated = await db.projects.find_one({"_id": to_query_id(project_id)})

    # If BIN was just set or tracking just enabled, kick off an immediate background sync
    bin_changed = config.nyc_bin is not None and config.nyc_bin.strip() != (project.get("nyc_bin") or "")
    tracking_enabled = config.track_dob_status is True and not project.get("track_dob_status")
    if (bin_changed or tracking_enabled) and updated.get("nyc_bin"):
        import asyncio
        asyncio.create_task(run_dob_sync_for_project(updated))
        logger.info(f"Auto-triggered DOB sync for project {project_id} after config save")

    return {
        "message": "DOB config updated",
        "nyc_bin": updated.get("nyc_bin"),
        # bbl-first read with nyc_bbl fallback during step 9.1 transition.
        "bbl": updated.get("bbl") or updated.get("nyc_bbl"),
        "track_dob_status": updated.get("track_dob_status", False),
        "gc_legal_name": updated.get("gc_legal_name"),
    }


@api_router.get("/projects/{project_id}/dob-config")
async def get_dob_config(project_id: str, current_user=Depends(get_current_user)):
    """Get DOB config for a project (BIN, tracking, GC name)."""
    project = await db.projects.find_one({
        "_id": to_query_id(project_id),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")

    return {
        "nyc_bin": project.get("nyc_bin"),
        # bbl-first read with nyc_bbl fallback during step 9.1 transition.
        "bbl": project.get("bbl") or project.get("nyc_bbl"),
        "track_dob_status": project.get("track_dob_status", False),
        "gc_legal_name": project.get("gc_legal_name"),
    }


@api_router.get("/projects/{project_id}/dob-logs")
async def get_dob_logs(
    project_id: str,
    current_user=Depends(get_current_user),
    severity: Optional[str] = Query(None, description="Filter: Low, Medium, Critical"),
    record_type: Optional[str] = Query(None, description="Filter: complaint, violation, job_status, swo"),
    limit: int = Query(20, ge=1, le=200),
    skip: int = Query(0, ge=0),
    include_seed: bool = Query(
        False,
        description=(
            "MR.14 (commit 2b) — include the synthetic seed-transition "
            "rows that were inserted when MR.14 first deployed (one per "
            "pre-existing dob_logs entry, marking the moment LeveLog "
            "started tracking it). Default False so the activity feed "
            "doesn't drown in 'we started tracking this' noise on day "
            "one. Pass include_seed=true for admin/debug views."
        ),
    ),
    # MR.14 commit 3 — activity-feed filters.
    signal_kinds: Optional[str] = Query(
        None,
        description=(
            "Comma-separated list of signal_kind values to filter by "
            "(e.g. 'permit_expired,violation_dob,stop_work_full'). "
            "Match is OR across the list. Empty means no filter."
        ),
    ),
    severity_kind: Optional[str] = Query(
        None,
        description=(
            "Filter by template severity kind: 'critical', 'warning', "
            "or 'info'. Distinct from the legacy 'severity' field "
            "(Low/Medium/Critical) which uses different values."
        ),
    ),
    date_range: str = Query(
        "30d",
        description=(
            "today | 7d | 30d | all. Filters by detected_at relative "
            "to now. Default '30d' to keep the feed responsive on "
            "projects with long histories."
        ),
    ),
    unread_only: bool = Query(
        False,
        description=(
            "When True, return only logs where the current user has "
            "NOT marked the row read (i.e. their user_id is not in "
            "the read_by_user[].user_id list)."
        ),
    ),
    search: Optional[str] = Query(
        None,
        description=(
            "Free-text search over rendered title + body. "
            "Case-insensitive substring match. Empty means no filter."
        ),
    ),
):
    """Get translated DOB logs for a project, sorted by status_changed_at
    desc then detected_at desc.

    MR.14 commit 3 — server-side renders signal_kind into title /
    body / severity_kind / action_text via lib/dob_signal_templates.
    Frontend doesn't re-implement template logic; copy edits land in
    one place.
    """
    project = await db.projects.find_one({
        "_id": to_query_id(project_id),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")

    # Caller's user_id — used for read_by_user filtering + per-row is_read flag.
    caller_user_id = str(current_user.get("_id") or current_user.get("id") or "")

    query = {"project_id": project_id, "is_deleted": {"$ne": True}}
    if severity:
        query["severity"] = severity
    if record_type:
        query["record_type"] = record_type

    # MR.14 commit 3 — signal_kinds CSV filter.
    if signal_kinds:
        kinds = [k.strip() for k in signal_kinds.split(",") if k.strip()]
        if kinds:
            query["signal_kind"] = {"$in": kinds}

    # MR.14 commit 3 — date range filter.
    if date_range and date_range != "all":
        days_map = {"today": 1, "7d": 7, "30d": 30}
        days = days_map.get(date_range, 30)
        cutoff = datetime.now(timezone.utc) - timedelta(days=days)
        query["detected_at"] = {"$gte": cutoff}

    # MR.14 commit 3 — unread-only filter.
    if unread_only and caller_user_id:
        query["read_by_user.user_id"] = {"$ne": caller_user_id}

    if not include_seed:
        # MR.14 commit 4a — field-based seed suppression. Replaces
        # the commit-2b/3 time-window heuristic that depended on
        # the operator setting MR14_SEED_WINDOW_START on Railway.
        # is_seed_transition is now stamped at insert time (see
        # run_dob_sync_for_project + _poll_311_fast_complaints) and
        # carries the authoritative discriminator: True iff the
        # existing legacy doc lacked the current_status field.
        # Cheaper to filter (no time math) and works retroactively
        # AND for any future seed-style migration.
        query["is_seed_transition"] = {"$ne": True}

    total = await db.dob_logs.count_documents(query)
    # MR.14 commit 3 — sort by status_changed_at DESC, then
    # detected_at DESC. This surfaces TRUE status changes ahead of
    # mere re-detections of unchanged records.
    logs = await db.dob_logs.find(query).sort([
        ("status_changed_at", -1),
        ("detected_at", -1),
    ]).skip(skip).limit(limit).to_list(limit)

    # MR.14 commit 3 — search filter (post-render). Templates render
    # the user-facing title + body; search those rather than the raw
    # ai_summary so the UX matches what the user sees.
    search_term = (search or "").strip().lower() if search else ""

    serialized_logs = []
    # Lazy-import the templates module so test environments that
    # don't exercise the activity feed don't pay the import cost.
    from lib.dob_signal_templates import render_signal as _render_signal
    for log in logs:
        try:
            raw = log.get("raw_record") or {}
            rtype = log.get("record_type")

            # Broken DOB links written before the routing fix get
            # rebuilt on read from the raw record so existing rows pick
            # up working URLs without a migration. Previous regressions:
            # complaint URL used a bogus `vlession` param; permit URL
            # hardcoded passdocnumber=01; violation URL fed the ISN
            # into vlcompdetlkey; DOB NOW jobs (B-prefix) were routed
            # to BIS which doesn't have them. Now covers every type
            # whose builder was wrong.
            if raw and rtype in ("complaint", "permit", "job_status", "violation", "swo", "inspection"):
                try:
                    fresh_link = _build_dob_link(raw, rtype)
                    if fresh_link:
                        log["dob_link"] = fresh_link
                except Exception:
                    pass

            # Inspection read-time re-enrichment REMOVED (COMMIT 1, 2026-07-25).
            # It re-decoded the job_id prefix into a trade category ("Plumbing —
            # Initial") via the now-deleted DOB_JOB_PREFIX_CATEGORY decoder —
            # the "PC" (Pest Control) → "Plumbing" fabrication on rodent data.
            # Dead now that the p937-wjvj inspection ingest is gone.
            # MR.14 commit 3 — server-side render via templates.
            # signal_kind drives the per-template renderer; output
            # is added to the dict before Pydantic serialization so
            # the frontend gets title/body/severity_kind/action_text
            # without re-implementing template logic.
            try:
                rendered = _render_signal(log.get("signal_kind") or "", log)
            except Exception as _re:
                logger.warning(
                    "render_signal failed for log %s kind=%r: %s",
                    log.get("_id"), log.get("signal_kind"), _re,
                )
                rendered = {}

            log["title"] = rendered.get("title") or log.get("ai_summary") or ""
            log["body"] = rendered.get("body") or ""
            log["severity_kind"] = rendered.get("severity") or "info"
            log["action_text"] = rendered.get("action_text") or log.get("next_action") or ""

            # Apply post-render filters before serializing.
            if severity_kind and log["severity_kind"] != severity_kind:
                continue
            if search_term:
                hay = (log["title"] + " " + log["body"]).lower()
                if search_term not in hay:
                    continue

            # is_read computed per-caller. Each entry in read_by_user
            # is {user_id, read_at}; check user_id presence.
            log_reads = log.get("read_by_user") or []
            log["is_read"] = (
                bool(caller_user_id)
                and any(
                    isinstance(r, dict) and r.get("user_id") == caller_user_id
                    for r in log_reads
                )
            )

            serialized_logs.append(DOBLogResponse(**serialize_id(dict(log))))
        except Exception as e:
            logger.error(f"Failed to serialize dob_log {log.get('_id')}: {e}")

    return {
        "project_id": project_id,
        "project_name": project.get("name"),
        "nyc_bin": project.get("nyc_bin"),
        "track_dob_status": project.get("track_dob_status", False),
        "total": total,
        "logs": serialized_logs,
    }


# ── MR.14 commit 3 — mark-as-read endpoints ──────────────────────


async def _verify_dob_log_access(project_id: str, current_user: dict) -> dict:
    """Shared auth + tenant check for mark-as-read endpoints. Returns
    the project doc on success; raises HTTPException on failure."""
    project = await db.projects.find_one({
        "_id": to_query_id(project_id),
        "is_deleted": {"$ne": True},
    })
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    # THE BYPASS: `if company_id and ...` short-circuits, so a company-less
    # caller never reached the comparison and the 403 could not fire.
    # /auth/register sets company_id = None on every self-serve signup.
    # project_access_ok is the same rule require_project_access applies;
    # the lookup above is deliberately left exactly as it was.
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")
    return project


@api_router.post("/projects/{project_id}/dob-logs/{log_id}/mark-read", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def mark_dob_log_read(
    project_id: str,
    log_id: str,
    current_user=Depends(get_current_user),
):
    """Mark a single dob_log as read for the calling user.

    Idempotent: if the user has already marked this row read, the
    second call is a no-op (the existing read_by_user[].user_id
    entry is detected and we don't double-write).
    """
    await _verify_dob_log_access(project_id, current_user)
    user_id = str(current_user.get("_id") or current_user.get("id") or "")
    if not user_id:
        raise HTTPException(status_code=400, detail="No caller user_id")

    # Use $addToSet semantics manually: upsert only when this user_id
    # isn't already in the array. Mongo's $addToSet on an array of
    # subdocs is exact-match (would match {user_id, read_at} pairs as
    # whole units). We want match-by-user_id only, so we do a
    # find-then-update flow.
    existing = await db.dob_logs.find_one(
        {
            "_id": to_query_id(log_id),
            "project_id": project_id,
            "is_deleted": {"$ne": True},
        },
        {"read_by_user": 1},
    )
    if not existing:
        raise HTTPException(status_code=404, detail="DOB log not found")

    already_read = any(
        isinstance(r, dict) and r.get("user_id") == user_id
        for r in (existing.get("read_by_user") or [])
    )
    if already_read:
        return {"updated": False, "reason": "already_read", "log_id": log_id}

    now = datetime.now(timezone.utc)
    result = await db.dob_logs.update_one(
        {"_id": to_query_id(log_id), "project_id": project_id},
        {"$push": {"read_by_user": {"user_id": user_id, "read_at": now}}},
    )
    return {
        "updated": result.modified_count == 1,
        "log_id": log_id,
        "read_at": now.isoformat(),
    }


@api_router.post("/projects/{project_id}/dob-logs/mark-all-read", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def mark_all_dob_logs_read(
    project_id: str,
    current_user=Depends(get_current_user),
):
    """Mark all unread dob_logs for this project as read for the
    calling user. Bounded by the activity-feed defaults (last 30
    days, no seed-transitions) to avoid unbounded writes if a
    project's history is huge.
    """
    await _verify_dob_log_access(project_id, current_user)
    user_id = str(current_user.get("_id") or current_user.get("id") or "")
    if not user_id:
        raise HTTPException(status_code=400, detail="No caller user_id")

    cutoff = datetime.now(timezone.utc) - timedelta(days=30)
    now = datetime.now(timezone.utc)

    # Build the same query the activity feed uses by default so
    # mark-all-read affects exactly the rows the user CAN see (no
    # marking seed transitions or older-than-30d rows they're not
    # currently looking at).
    query = {
        "project_id": project_id,
        "is_deleted": {"$ne": True},
        "detected_at": {"$gte": cutoff},
        "read_by_user.user_id": {"$ne": user_id},
    }

    # MR.14 commit 4a — field-based seed suppression. Matches GET.
    query["is_seed_transition"] = {"$ne": True}

    result = await db.dob_logs.update_many(
        query,
        {"$push": {"read_by_user": {"user_id": user_id, "read_at": now}}},
    )
    return {
        "updated": result.modified_count,
        "user_id": user_id,
        "read_at": now.isoformat(),
    }


@api_router.post("/projects/{project_id}/dob-sync", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def manual_dob_sync(project_id: str, current_user=Depends(get_current_user)):
    """Manual trigger: bypass cron and force immediate DOB fetch. Rate limited 15 min."""
    import traceback as _tb
    try:
        # A marked project must stop syncing DOB entirely.
        project = await db.projects.find_one({
            "_id": to_query_id(project_id),
            **ACTIVE_PROJECT_FILTER,
        })
        if not project:
            raise HTTPException(status_code=404, detail="Project not found")

        company_id = get_user_company_id(current_user)
        if company_id and project.get("company_id") != company_id:
            raise HTTPException(status_code=403, detail="Access denied to this project")

        if not project.get("nyc_bin") and not project.get("address"):
            raise HTTPException(status_code=400, detail="No BIN or address configured. Update DOB config first.")

        rate_key = f"dob_sync_last:{project_id}"
        rate_doc = await db.system_config.find_one({"key": rate_key})
        if rate_doc:
            last_time = rate_doc.get("last_sync_at")
            if last_time and isinstance(last_time, datetime):
                # Ensure both datetimes are tz-aware for subtraction
                if last_time.tzinfo is None:
                    last_time = last_time.replace(tzinfo=timezone.utc)
                elapsed = (datetime.now(timezone.utc) - last_time).total_seconds()
                if elapsed < 900:
                    remaining = int(900 - elapsed)
                    raise HTTPException(
                        status_code=429,
                        detail=f"Rate limited. Try again in {remaining // 60}m {remaining % 60}s.",
                    )
        await db.system_config.update_one(
            {"key": rate_key},
            {"$set": {"key": rate_key, "last_sync_at": datetime.now(timezone.utc)}},
            upsert=True,
        )

        new_logs = await run_dob_sync_for_project(project)

        safe_logs = []
        for log in new_logs:
            try:
                safe_logs.append(DOBLogResponse(**serialize_id(dict(log))))
            except Exception as e:
                logger.warning(f"Failed to serialize dob_log {log.get('raw_dob_id')}: {e}")

        action_count = sum(1 for l in new_logs if l.get("severity") == "Action")
        return {
            "message": f"DOB sync complete. {len(new_logs)} new record(s) found.",
            "new_records": len(new_logs),
            "critical_count": action_count,
            "logs": safe_logs,
        }
    except HTTPException:
        raise
    except Exception as e:
        tb_str = _tb.format_exc()
        logger.exception(f"DOB sync UNHANDLED error for project {project_id}: {e}")
        return JSONResponse(
            status_code=500,
            content={"detail": f"DOB sync error: {str(e)}"},
        )


@api_router.post(
    "/projects/{project_id}/dob-logs/reset-resync",
    dependencies=[Depends(require_project_access)],
)
async def reset_and_resync_dob_logs(project_id: str, current_user=Depends(get_admin_user)):
    """Admin-only: row-level clear ONE project's dob_logs, then re-ingest from
    DOB through the current extractor.

    Why this exists: non-permit DOB records are insert-once — run_dob_sync_for_project
    skips any raw_id already in `existing_ids`, so a plain re-sync can never
    correct rows ingested with old logic or before DOB changed their disposition
    (that's why a rescinded SWO stays "open" and an old fabricated label sticks).
    This deletes the project's rows (delete_many on {project_id} — row-level,
    NEVER drop()) so the very next sync re-ingests every CURRENT DOB record fresh
    with correct source/category/resolution. Scoped to one project; fully
    reconstructed by the same sync it triggers.
    """
    try:
        project = await db.projects.find_one({
            "_id": to_query_id(project_id),
            **ACTIVE_PROJECT_FILTER,
        })
        if not project:
            raise HTTPException(status_code=404, detail="Project not found")

        company_id = get_user_company_id(current_user)
        if company_id and project.get("company_id") != company_id:
            raise HTTPException(status_code=403, detail="Access denied to this project")

        pid = str(project["_id"])
        deleted = await db.dob_logs.delete_many({"project_id": pid})
        logger.info(
            f"DOB reset-resync: purged {deleted.deleted_count} dob_logs rows "
            f"for project {pid} before re-ingest"
        )

        new_logs = await run_dob_sync_for_project(project)

        safe_logs = []
        for log in new_logs:
            try:
                safe_logs.append(DOBLogResponse(**serialize_id(dict(log))))
            except Exception as e:
                logger.warning(f"Failed to serialize dob_log {log.get('raw_dob_id')}: {e}")

        return {
            "message": (
                f"Cleared {deleted.deleted_count} row(s), re-ingested "
                f"{len(new_logs)} fresh record(s)."
            ),
            "deleted": deleted.deleted_count,
            "new_records": len(new_logs),
            "logs": safe_logs,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"DOB reset-resync error for project {project_id}: {e}")
        return JSONResponse(
            status_code=500,
            content={"detail": f"DOB reset-resync error: {str(e)}"},
        )


# ==================== REPORT EMAIL SCHEDULER ====================

# `_count_permits_expiring_soon` is REMOVED.
#
# It counted ROWS in permit_renewals, not permits, and fed the
# "N permits expiring within 30 days" line on the daily report email.
# Rows are keyed on permit_dob_log_id -- a dob_logs _id, not a permit
# identity -- so one real permit produced a row per DOB status change
# and a fresh set after each reset-resync, and the count multiplied
# with them. 588 Thomas was reported as "3 permits expiring" off rows
# that carried job_number=None and permit_type=None.
#
# It is not replaced with a zero. "0 permits expiring" is also an
# assertion, and we do not know how many permits are expiring -- only
# that the number we were printing was not it. The section comes out.
#
# The dob_logs-sourced tile on the project screen (GET
# /api/projects/dob-summary, permits_expiring facet) is unaffected and
# stays: it dedupes by raw_dob_id and renders an em dash rather than a
# zero when the read fails.
#
# See docs/audits/permit-expiry-claim-2026-08-27.md.


async def check_and_send_reports():
    """Called every minute. Sends report emails for projects whose send time matches now."""
    if not RESEND_API_KEY:
        return
    now = datetime.now(timezone.utc)
    from zoneinfo import ZoneInfo
    eastern = ZoneInfo("America/New_York")
    est_now = now.astimezone(eastern)
    current_time = est_now.strftime("%H:%M")
    today = est_now.strftime("%Y-%m-%d")

    projects_due = await db.projects.find({
        "report_send_time": current_time,
        "report_email_list": {"$exists": True, "$ne": []},
        **ACTIVE_PROJECT_FILTER,
    }).to_list(100)

    if not projects_due:
        return

    resend.api_key = RESEND_API_KEY
    for project in projects_due:
        project_id = str(project["_id"])
        project_name = project.get("name", "Project")
        email_list = project.get("report_email_list", [])
        if not email_list:
            continue
        already_sent = await db.report_emails.find_one({"project_id": project_id, "date": today})
        if already_sent:
            continue

        # Skip if no data exists for today (avoid blank reports).
        # These counts now also feed the email's summary line, so they are
        # bound BEFORE the try: a failed data check falls through to "sending
        # anyway" below, and unbound names would turn that into a NameError
        # that silently drops the report entirely.
        logbook_count = 0
        checkin_count = 0
        try:
            logbook_count = await db.logbooks.count_documents({
                "project_id": project_id,
                "date": today,
                "status": "submitted",
                "is_deleted": {"$ne": True},
            })
            has_daily_log = await db.daily_logs.find_one({
                "project_id": project_id,
                "date": today,
                "is_deleted": {"$ne": True},
            })
            day_start, day_end = get_day_range_est(today)
            checkin_count = await db.checkins.count_documents({
                "project_id": project_id,
                "check_in_time": {"$gte": day_start, "$lt": day_end},
                "is_deleted": {"$ne": True},
            })
            if not logbook_count and not has_daily_log and not checkin_count:
                logger.info(
                    f"Report skipped for {project_name} — no data for {today}"
                )
                continue
        except Exception as e:
            logger.warning(f"Data check failed for {project_name}, sending anyway: {e}")

        try:
            # DELIVERABILITY — the report DOCUMENT is no longer the email body.
            #
            # This used to inline generate_combined_report()'s 680px branded
            # card (nested tables, letter-spaced wordmark header, one remote
            # <img> + one outbound link per site photo) with a two-line
            # "open in HTML" text stub. Gmail read that as bulk and filed
            # compliance reports under Promotions. The permit-renewal triggers
            # reach the inbox from the SAME domain and sender, so the template
            # was the only variable — the body now uses their exact
            # render_for_trigger path and the document rides as a PDF.
            report_html = await generate_combined_report(project_id, today)

            # Render the PDF off the event loop: weasyprint is CPU-bound and
            # fetches every photo over HTTP, so doing it inline would stall the
            # once-a-minute scheduler for every other project due this tick.
            attachments = None
            try:
                def _render_pdf(h: str) -> bytes:
                    from weasyprint import HTML
                    return HTML(string=h).write_pdf()

                pdf_bytes = await asyncio.to_thread(_render_pdf, report_html)
                # Resend caps a message at 40MB; base64 inflates by ~4/3. Stay
                # well under and fall back to the link rather than having the
                # send rejected outright — a delivered summary beats a bounce.
                if pdf_bytes and len(pdf_bytes) <= 15 * 1024 * 1024:
                    safe_name = re.sub(r'[^A-Za-z0-9_.-]', '_', project_name) or "report"
                    attachments = [{
                        "filename": f"Levelog_Report_{safe_name}_{today}.pdf",
                        "content": base64.b64encode(pdf_bytes).decode("ascii"),
                    }]
                else:
                    logger.warning(
                        f"Daily report PDF for {project_name} {today} too large "
                        f"({len(pdf_bytes or b'')} bytes) — sending link only"
                    )
            except Exception as e:
                # Never let a render failure cost the notification itself.
                logger.warning(
                    f"Daily report PDF render failed for {project_name} {today} "
                    f"({e!r}) — sending link only"
                )

            # No permit-expiry key in this context. The renderer no
            # longer reads one, so a stale caller passing it cannot
            # resurrect the claim.
            from lib.email_templates import render_for_trigger
            subject, html, text = render_for_trigger("project_daily_report", {
                "recipient_name": "",          # per-recipient names aren't stored
                "project_name": project_name,
                "project_address": project.get("address", ""),
                "report_date": today,
                "logbook_count": logbook_count,
                "worker_count": checkin_count,
                "attached": bool(attachments),
                "action_link": f"{APP_BASE_URL.rstrip('/')}/reports",
            })
            # MR.14 fix — route through send_notification.
            # entity_id keys per (project, date) so a recurring cron
            # tick (every minute) at the same target time only sends
            # once per recipient per day.
            entity_id = f"daily_report:{project_id}:{today}"
            from lib.notifications import send_notification
            sent_to = []
            for recipient in email_list:
                try:
                    result = await send_notification(
                        db,
                        permit_renewal_id=entity_id,
                        trigger_type="project_daily_report",
                        recipient=recipient,
                        subject=subject,
                        html=html,
                        text=text,
                        attachments=attachments,
                        metadata={
                            "project_id": project_id,
                            "project_name": project_name,
                            "date": today,
                            "pdf_attached": bool(attachments),
                        },
                    )
                    if result.get("status") == "sent":
                        sent_to.append(recipient)
                except Exception as e:
                    logger.error(
                        f"daily_report send_notification error project={project_name} "
                        f"recipient={recipient}: {e}"
                    )
            await db.report_emails.insert_one({
                "project_id": project_id,
                "date": today,
                "sent_at": now,
                "recipients": email_list,
                "actually_sent_to": sent_to,
            })
            logger.info(
                f"Report dispatched for {project_name} to {len(email_list)} "
                f"recipient(s); {len(sent_to)} actually sent (rest deduped or suppressed)"
            )
        except Exception as e:
            logger.error(f"Failed to send report for {project_name}: {e}")

# ==================== DOCUMENT ANNOTATIONS (PLAN NOTES) ====================

async def _generate_annotation_screenshot(
    annotation_id: str,
    document_path: str,
    page_number: int,
    position: dict,
    project_id: str,
    company_id: str,
):
    """Render page thumbnail, draw red circle at pin, crop 400x400, store as base64 data URL."""
    if not SCREENSHOT_ENABLED:
        return
    try:
        from pdf2image import convert_from_bytes
        from PIL import Image, ImageDraw

        # Fetch PDF bytes from Dropbox
        project = await db.projects.find_one({"_id": to_query_id(project_id)})
        if not project:
            return
        try:
            access_token = await get_valid_dropbox_token(company_id)
        except Exception:
            return

        async with ServerHttpClient(timeout=30) as hc:
            resp = await hc.post(
                "https://content.dropboxapi.com/2/files/download",
                headers={
                    "Authorization": f"Bearer {access_token}",
                    "Dropbox-API-Arg": f'{{"path": "{document_path}"}}',
                },
            )
            if resp.status_code != 200:
                logger.error(f"Dropbox download failed for annotation screenshot: {resp.status_code}")
                return
            pdf_bytes = resp.content

        images = convert_from_bytes(pdf_bytes, first_page=page_number, last_page=page_number, dpi=150)
        if not images:
            return
        img = images[0]

        # Draw red circle at position
        draw = ImageDraw.Draw(img)
        px = int(position.get("x", 0.5) * img.width)
        py = int(position.get("y", 0.5) * img.height)
        r = 18
        draw.ellipse([px - r, py - r, px + r, py + r], outline="red", width=4)

        # Crop 400x400 centred on pin
        half = 200
        left = max(px - half, 0)
        top = max(py - half, 0)
        right = min(px + half, img.width)
        bottom = min(py + half, img.height)
        cropped = img.crop((left, top, right, bottom))

        buf = io.BytesIO()
        cropped.save(buf, format="JPEG", quality=80)
        b64 = base64.b64encode(buf.getvalue()).decode()
        data_url = f"data:image/jpeg;base64,{b64}"

        await db.document_annotations.update_one(
            {"_id": to_query_id(annotation_id)},
            {"$set": {"screenshot": data_url}},
        )
        logger.info(f"Annotation screenshot generated for {annotation_id}")
    except Exception as e:
        logger.error(f"Annotation screenshot failed: {e}")


async def _send_annotation_emails(annotation: dict, project_name: str, recipient_ids: list, creator_id: str):
    """Wait up to 30s for screenshot, then email all recipients."""
    try:
        # Wait for screenshot to be generated (up to 30s)
        ann_id = annotation.get("id") or str(annotation.get("_id"))
        screenshot_url = None
        for _ in range(15):
            await asyncio.sleep(2)
            doc = await db.document_annotations.find_one({"_id": to_query_id(ann_id)})
            if doc and doc.get("screenshot"):
                screenshot_url = doc["screenshot"]
                break

        # Gather recipient emails
        recipient_emails = []
        for uid in recipient_ids:
            if uid == creator_id:
                continue
            user = await db.users.find_one({"_id": to_query_id(uid)})
            if user and user.get("email"):
                recipient_emails.append(user["email"])

        if not recipient_emails:
            return

        creator = await db.users.find_one({"_id": to_query_id(creator_id)})
        creator_name = creator.get("name", "A team member") if creator else "A team member"

        short_link = f"https://levelog.com/a/{ann_id}"
        comment_text = annotation.get("comment", "")

        screenshot_block = ""
        if screenshot_url:
            screenshot_block = f'<img src="{screenshot_url}" alt="Plan screenshot" style="max-width:400px;border-radius:8px;border:1px solid #e2e8f0;margin:12px 0;" /><br/>'

        html = f"""
        <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:520px;margin:0 auto;padding:24px;background:#ffffff;">
            <div style="text-align:center;margin-bottom:16px;">
                <span style="font-size:20px;font-weight:700;color:#1e3a5f;">LEVELOG</span>
            </div>
            <div style="background:#f8fafc;border-radius:12px;padding:20px;border:1px solid #e2e8f0;">
                <p style="margin:0 0 8px;font-size:14px;color:#64748b;">New Plan Note on <strong>{project_name}</strong></p>
                <p style="margin:0 0 16px;font-size:16px;color:#1e293b;"><strong>{creator_name}</strong> left a note:</p>
                {screenshot_block}
                <div style="background:#ffffff;border-radius:8px;padding:16px;border-left:4px solid #3b82f6;margin:12px 0;">
                    <p style="margin:0;font-size:14px;color:#334155;">{comment_text}</p>
                </div>
                <a href="{short_link}" style="display:inline-block;margin-top:16px;padding:10px 24px;background:#3b82f6;color:#ffffff;text-decoration:none;border-radius:8px;font-size:14px;font-weight:600;">View Note</a>
            </div>
            <p style="text-align:center;font-size:10px;color:#cbd5e1;margin-top:16px;letter-spacing:2px;">LEVELOG</p>
        </div>
        """

        # MR.14 fix — route through send_notification. Annotations
        # are immutable once created (the note text doesn't change),
        # so per-recipient idempotency on (annotation_id, recipient)
        # matches the natural "tell each recipient once" contract.
        subject = f"Plan Note — {project_name}"
        text = f"{creator_name} left a plan note on {project_name}: {comment_text}\n\nView: {short_link}"
        from lib.notifications import send_notification
        for recipient in recipient_emails:
            try:
                await send_notification(
                    db,
                    permit_renewal_id=f"annotation:{ann_id}",
                    trigger_type="annotation_note",
                    recipient=recipient,
                    subject=subject,
                    html=html,
                    text=text,
                    metadata={
                        "annotation_id": ann_id,
                        "project_id": str(project_id),
                        "creator_name": creator_name,
                    },
                )
            except Exception as e:
                logger.error(
                    f"annotation send_notification error ann_id={ann_id} "
                    f"recipient={recipient}: {e}"
                )
        logger.info(f"Annotation email dispatched to {len(recipient_emails)} recipient(s) for {ann_id}")
    except Exception as e:
        logger.error(f"Failed to send annotation email: {e}")


async def _send_reply_notification(annotation: dict, thread_entry: dict):
    """Notify annotation creator when someone replies."""
    try:
        ann_id = annotation.get("id") or str(annotation.get("_id"))
        creator_id = annotation.get("created_by")
        replier_id = thread_entry.get("user_id")

        if creator_id == replier_id:
            return  # Don't notify self

        creator = await db.users.find_one({"_id": to_query_id(creator_id)})
        if not creator or not creator.get("email"):
            return

        replier = await db.users.find_one({"_id": to_query_id(replier_id)})
        replier_name = replier.get("name", "A team member") if replier else "A team member"

        project = await db.projects.find_one({"_id": to_query_id(annotation.get("project_id"))})
        project_name = project.get("name", "Unknown Project") if project else "Unknown Project"

        short_link = f"https://levelog.com/a/{ann_id}"
        reply_text = thread_entry.get("message", "")

        html = f"""
        <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:520px;margin:0 auto;padding:24px;background:#ffffff;">
            <div style="text-align:center;margin-bottom:16px;">
                <span style="font-size:20px;font-weight:700;color:#1e3a5f;">LEVELOG</span>
            </div>
            <div style="background:#f8fafc;border-radius:12px;padding:20px;border:1px solid #e2e8f0;">
                <p style="margin:0 0 8px;font-size:14px;color:#64748b;">Reply on <strong>{project_name}</strong></p>
                <p style="margin:0 0 16px;font-size:16px;color:#1e293b;"><strong>{replier_name}</strong> replied to your note:</p>
                <div style="background:#ffffff;border-radius:8px;padding:16px;border-left:4px solid #10b981;margin:12px 0;">
                    <p style="margin:0;font-size:14px;color:#334155;">{reply_text}</p>
                </div>
                <a href="{short_link}" style="display:inline-block;margin-top:16px;padding:10px 24px;background:#3b82f6;color:#ffffff;text-decoration:none;border-radius:8px;font-size:14px;font-weight:600;">View Thread</a>
            </div>
            <p style="text-align:center;font-size:10px;color:#cbd5e1;margin-top:16px;letter-spacing:2px;">LEVELOG</p>
        </div>
        """

        # MR.14 fix — route through send_notification. entity_id
        # combines annotation + thread_entry IDs so each individual
        # reply triggers at most one email per recipient (rather than
        # all replies bunching under a single annotation key).
        thread_entry_id = thread_entry.get("id") or thread_entry.get("_id") or ""
        subject = f"Reply on Plan Note — {project_name}"
        text = (
            f"{replier_name} replied on the plan note for {project_name}: "
            f"{reply_text}\n\nView thread: {short_link}"
        )
        from lib.notifications import send_notification
        try:
            await send_notification(
                db,
                permit_renewal_id=f"annotation_reply:{ann_id}:{thread_entry_id}",
                trigger_type="annotation_reply",
                recipient=creator["email"],
                subject=subject,
                html=html,
                text=text,
                metadata={
                    "annotation_id": ann_id,
                    "thread_entry_id": str(thread_entry_id),
                    "creator_id": str(creator_id),
                    "replier_id": str(replier_id),
                },
            )
        except Exception as e:
            logger.error(
                f"reply_notification send_notification error ann_id={ann_id}: {e}"
            )
        logger.info(f"Reply notification dispatched for annotation {ann_id}")
    except Exception as e:
        logger.error(f"Failed to send reply notification: {e}")


@api_router.get("/users/company-roster")
async def get_company_roster(current_user=Depends(get_current_user)):
    """Minimal user roster for the current user's company. Any authenticated
    user can call this — used by the annotation recipient picker. Returns
    only safe fields (id, name, email, role) and excludes deleted users.
    """
    company_id = get_user_company_id(current_user)
    query: Dict[str, Any] = {"is_deleted": {"$ne": True}}
    if company_id:
        query["company_id"] = company_id
    # ── `password: 0` REMOVED, AND THAT WAS THE WHOLE DEFECT ────────────────
    #
    # MongoDB REJECTS a projection that mixes an exclusion with inclusions —
    # `_id` is the only field allowed to be excluded inside an inclusion
    # projection. So this raised
    #
    #   OperationFailure: Cannot do inclusion on field name in exclusion
    #   projection
    #
    # on EVERY call. Not sometimes, not at scale: every call, since the line
    # was written. The annotation recipient picker has been returning a 500 to
    # any authenticated user who opened it — 40 events in Sentry over the week
    # before this fix, still arriving.
    #
    # HOW IT SURVIVED. `find_unserved_sorts.py` classifies a projection by
    # SHAPE and reported this row as "inclusion, base64 excluded" — protected.
    # docs/audits/followups.md then recorded that classification as fact, and a
    # later pass deferred the fix as "a riskier edit than adding an index"
    # WITHOUT CHECKING WHETHER IT WAS ALREADY FAILING. It was, and the evidence
    # was in Sentry the whole time. A tool that says "protected" must be able
    # to say protected BY WHAT, and be wrong loudly when the projection is
    # malformed.
    #
    # NOTHING ELSE CHANGES. `password` was already excluded by OMISSION — the
    # five inclusions below are the only fields the loop reads, so the response
    # is byte-identical to what this endpoint was written to return. The one
    # difference is that it now returns it.
    users = await db.users.find(
        query,
        {"_id": 1, "name": 1, "full_name": 1, "email": 1, "role": 1},
    ).sort("name", 1).to_list(500)
    out = []
    for u in users:
        out.append({
            "id":    str(u.get("_id")),
            "name":  u.get("name") or u.get("full_name") or u.get("email") or "Unknown",
            "email": u.get("email") or "",
            "role":  u.get("role") or "",
        })
    return out


async def _annotation_for_user(annotation_id: str, current_user: dict) -> dict:
    """Load an annotation and prove the caller may act on its PROJECT.

    THE HOLE THIS CLOSES. Three routes looked an annotation up by id alone:

        PUT    /annotations/{id}/reply     no check of any kind
        PUT    /annotations/{id}/resolve   creator / recipient / ROLE only
        DELETE /annotations/{id}           creator / ROLE only

    `is_admin = user_role in ["admin", "owner"]` is a ROLE test with no tenant
    in it, so an admin of ANY company could resolve or delete another company's
    plan note, and reply needed nothing at all beyond a token. The annotation
    id was the only thing standing between a caller and another tenant's
    document.

    THE PROJECT IS THE SCOPE, not company_id. Every annotation stores a
    project_id (create requires one), and _assert_project_access is the same
    rule require_project_access wraps -- it is used directly here because the
    project id comes off the DOCUMENT, not the path, so FastAPI has nothing to
    resolve a dependency from. Same rule, same 403, one address.

    It also subsumes the company check the reviewer asked for: project_access_ok
    compares company on the project, so a cross-tenant admin fails here without
    a second, hand-rolled `if company_id and ...` -- the conditional shape that
    passes for a company-less caller and is open on 24 other routes.

    FAILS CLOSED ON A PROJECTLESS ROW. A legacy annotation with no project_id
    cannot be scoped, so it cannot be acted on. Create has required project_id
    for as long as this endpoint has existed; if such a row is ever found, it
    needs a migration, not an exception here.
    """
    annotation = await db.document_annotations.find_one(
        {"_id": to_query_id(annotation_id), "is_deleted": {"$ne": True}}
    )
    if not annotation:
        raise HTTPException(status_code=404, detail="Annotation not found")
    project_id = str(annotation.get("project_id") or "")
    if not project_id:
        raise HTTPException(
            status_code=403, detail="Not authorized for this annotation",
        )
    await _assert_project_access(project_id, current_user)
    return annotation


@api_router.post("/annotations")
async def create_annotation(data: dict, background_tasks: BackgroundTasks, current_user=Depends(get_current_user)):
    """Create a document annotation (plan note).

    Accepts EITHER `document_path` (legacy, Dropbox-synced files) or `file_id`
    (direct-uploaded files which have no dropbox path). file_id is
    canonicalized as `file:{id}` and used as the document_path key.
    """
    project_id = data.get("project_id")
    document_path = (data.get("document_path") or "").strip()
    file_id = (data.get("file_id") or "").strip()
    page_number = data.get("page_number", 1)
    position = data.get("position", {"x": 0.5, "y": 0.5})
    comment = data.get("comment", "")
    recipients_input = data.get("recipients", "all")

    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    # THE CALLER MUST BE ABLE TO REACH THE PROJECT HE NAMES. This route took
    # project_id from the BODY and never checked it, so any authenticated user
    # could plant a note on any project in any tenant -- and the doc below then
    # stamps company_id from the CALLER, so the row would carry his tenancy
    # while pointing at someone else's project.
    #
    # _assert_project_access, not require_project_access: the id is in the body,
    # so there is no path parameter for a dependency to resolve. Same rule.
    await _assert_project_access(project_id, current_user)
    # Prefer file_id when present — it's stable across renames / R2 keys
    # (direct-upload files have empty dropbox_path).
    if file_id:
        document_path = f"file:{file_id}"
    if not document_path:
        raise HTTPException(
            status_code=400,
            detail="Either document_path or file_id is required",
        )

    user_id = current_user.get("id") or str(current_user.get("_id"))
    company_id = get_user_company_id(current_user)

    # Expand "all" to actual user IDs in the company
    if recipients_input == "all":
        all_users = await db.users.find(
            {"company_id": company_id, "is_deleted": {"$ne": True}},
            {"_id": 1},
        ).to_list(500)
        recipient_ids = [str(u["_id"]) for u in all_users]
    else:
        recipient_ids = recipients_input if isinstance(recipients_input, list) else [recipients_input]
        # Coerce any IDs to strings
        recipient_ids = [str(r) for r in recipient_ids if r]

    now = datetime.now(timezone.utc)
    doc = {
        "project_id": project_id,
        "document_path": document_path,
        "file_id": file_id or None,
        "page_number": page_number,
        "position": position,
        "comment": comment,
        "recipients": recipient_ids,
        "created_by": user_id,
        "company_id": company_id,
        "thread": [],
        "resolved": False,
        "is_deleted": False,
        "screenshot": None,
        "created_at": now,
        "updated_at": now,
    }
    result = await db.document_annotations.insert_one(doc)
    ann_id = str(result.inserted_id)
    doc["id"] = ann_id

    # Fetch project name for email
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = project.get("name", "Unknown Project") if project else "Unknown Project"

    # Background: generate screenshot + send emails
    background_tasks.add_task(
        _generate_annotation_screenshot, ann_id, document_path, page_number, position, project_id, company_id
    )
    background_tasks.add_task(
        _send_annotation_emails, doc, project_name, recipient_ids, user_id
    )

    return serialize_id(doc)


@api_router.get("/annotations/{project_id}/{document_path:path}")
async def get_annotations_for_document(project_id: str, document_path: str, current_user=Depends(get_current_user), _proj = Depends(require_project_access)):
    """Get annotations for a document with server-side visibility filtering.

    `document_path` may be either a real Dropbox path ("/Projects/…/A-101.pdf")
    or the sentinel form `file:{id}` used by direct-uploaded files.
    """
    user_id = current_user.get("id") or str(current_user.get("_id"))
    user_role = current_user.get("role")

    query = {
        "project_id": project_id,
        "document_path": document_path,
        "is_deleted": {"$ne": True},
    }

    # Non-admins only see their own annotations or where they are recipients
    if user_role not in ["admin", "owner"]:
        query["$or"] = [
            {"created_by": user_id},
            {"recipients": user_id},
        ]

    annotations = await db.document_annotations.find(query).sort("created_at", -1).to_list(500)
    return serialize_list([dict(a) for a in annotations])


@api_router.put("/annotations/{annotation_id}/reply")
async def add_annotation_reply(annotation_id: str, data: dict, background_tasks: BackgroundTasks, current_user=Depends(get_current_user)):
    """Add a reply to an annotation thread."""
    message = data.get("message", "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="message is required")

    # HAD NO CHECK OF ANY KIND. A valid token plus an annotation id was enough
    # to append to any thread in any tenant -- the only one of the five
    # annotation routes with no authorization at all.
    #
    # PROJECT ACCESS, NOT CREATOR-ONLY, and that is deliberate. A thread is the
    # collaborative half of a plan note: the creator asks a question and someone
    # else answers it, so restricting replies to the creator or the named
    # recipients would break the feature to close the hole. Everyone who can
    # open the drawing can answer a note on it; nobody else can see it at all.
    await _annotation_for_user(annotation_id, current_user)

    user_id = current_user.get("id") or str(current_user.get("_id"))
    now = datetime.now(timezone.utc)

    thread_entry = {
        "id": str(uuid.uuid4()),
        "user_id": user_id,
        "user_name": current_user.get("name", "Unknown"),
        "message": message,
        "created_at": now,
    }

    result = await db.document_annotations.update_one(
        {"_id": to_query_id(annotation_id), "is_deleted": {"$ne": True}},
        {"$push": {"thread": thread_entry}, "$set": {"updated_at": now}},
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Annotation not found")

    annotation = await db.document_annotations.find_one({"_id": to_query_id(annotation_id)})
    background_tasks.add_task(_send_reply_notification, serialize_id(dict(annotation)), thread_entry)

    return serialize_id(dict(annotation))


@api_router.put("/annotations/{annotation_id}/resolve")
async def resolve_annotation(annotation_id: str, current_user=Depends(get_current_user)):
    """Mark annotation as resolved. Only creator, recipient, or admin can resolve."""
    user_id = current_user.get("id") or str(current_user.get("_id"))
    user_role = current_user.get("role")

    # TENANCY FIRST. The lookup below was by annotation id alone, and the
    # `is_admin` branch is a ROLE test with no tenant in it -- so an admin of
    # any company could resolve any company's note. This scopes the row to a
    # project the caller can reach BEFORE the ownership rule is applied; the
    # ownership rule then decides which of those people may resolve it.
    annotation = await _annotation_for_user(annotation_id, current_user)

    is_creator = annotation.get("created_by") == user_id
    is_recipient = user_id in (annotation.get("recipients") or [])
    is_admin = user_role in ["admin", "owner"]

    if not (is_creator or is_recipient or is_admin):
        raise HTTPException(status_code=403, detail="Not authorized to resolve this annotation")

    await db.document_annotations.update_one(
        {"_id": to_query_id(annotation_id)},
        {"$set": {"resolved": True, "resolved_by": user_id, "resolved_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}},
    )
    updated = await db.document_annotations.find_one({"_id": to_query_id(annotation_id)})
    return serialize_id(dict(updated))


@api_router.delete("/annotations/{annotation_id}")
async def delete_annotation(annotation_id: str, current_user=Depends(get_current_user)):
    """Soft delete an annotation. Only creator or admin."""
    user_id = current_user.get("id") or str(current_user.get("_id"))
    user_role = current_user.get("role")

    # TENANCY FIRST, same as resolve above: `is_admin` is a role test with no
    # tenant in it, so a cross-tenant admin could soft-delete another company's
    # plan note. Project access is checked before ownership is considered.
    annotation = await _annotation_for_user(annotation_id, current_user)

    is_creator = annotation.get("created_by") == user_id
    is_admin = user_role in ["admin", "owner"]

    if not (is_creator or is_admin):
        raise HTTPException(status_code=403, detail="Not authorized to delete this annotation")

    await db.document_annotations.update_one(
        {"_id": to_query_id(annotation_id)},
        {"$set": {"is_deleted": True, "deleted_by": user_id, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}},
    )
    return {"status": "deleted"}


